--
-- Name: confirmed_account_notification_service(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirmed_account_notification_service(p_operation text, p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE n twuanis_canonical_private.confirmed_account_notifications%ROWTYPE;at_time timestamptz:=clock_timestamp();token uuid;BEGIN
 IF p_operation='claim' THEN
 SELECT * INTO n FROM twuanis_canonical_private.confirmed_account_notifications
 WHERE state IN('PENDING','RETRY') AND next_attempt<=at_time AND(lease_until IS NULL OR lease_until<=at_time)
 ORDER BY next_attempt,account_id LIMIT 1 FOR UPDATE SKIP LOCKED;
 IF NOT FOUND THEN RETURN NULL;END IF;
 -- Stop before Resend's 24-hour idempotency retention expires; never blindly resend afterward.
 IF n.attempts>=8 OR(n.first_attempt IS NOT NULL AND at_time>=n.first_attempt+interval '23 hours') THEN
 UPDATE twuanis_canonical_private.confirmed_account_notifications SET state='NEEDS_RESOLUTION',lease=NULL,lease_until=NULL WHERE account_id=n.account_id;RETURN NULL;END IF;
 token:=gen_random_uuid();UPDATE twuanis_canonical_private.confirmed_account_notifications SET attempts=attempts+1,first_attempt=coalesce(first_attempt,at_time),lease=token,lease_until=at_time+interval '2 minutes' WHERE account_id=n.account_id;
 RETURN jsonb_build_object('accountId',n.account_id,'token',token,'email',n.email,'createdAt',n.account_created_at,'confirmedAt',n.email_confirmed_at,'language',n.registration_language);
 ELSIF p_operation='finish' THEN
 SELECT * INTO STRICT n FROM twuanis_canonical_private.confirmed_account_notifications WHERE account_id=(p_command->>'accountId')::uuid FOR UPDATE;
 IF n.lease IS NULL OR n.lease IS DISTINCT FROM(p_command->>'token')::uuid OR n.lease_until<at_time THEN RAISE EXCEPTION 'notification lease conflict';END IF;
 IF p_command->>'outcome' NOT IN('ACCEPTED','RETRY') OR p_command->>'outcome' IS NULL THEN RAISE EXCEPTION 'bounded outcome required';END IF;
 IF p_command->>'outcome'='ACCEPTED' AND nullif(p_command->>'messageId','') IS NULL THEN RAISE EXCEPTION 'provider acknowledgement required';END IF;
 UPDATE twuanis_canonical_private.confirmed_account_notifications SET state=CASE WHEN p_command->>'outcome'='RETRY' AND attempts>=8 THEN 'NEEDS_RESOLUTION' ELSE p_command->>'outcome' END,
 provider_message=p_command->>'messageId',lease=NULL,lease_until=NULL,next_attempt=at_time+make_interval(secs=>least(3600,60*(2^n.attempts)::integer)) WHERE account_id=n.account_id;
 RETURN jsonb_build_object('ok',true);
 ELSE RAISE EXCEPTION 'unknown notification operation';END IF;END$$;


--
-- Name: create_csv_canonical_listing(uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_csv_canonical_listing(p_request uuid, p_input jsonb, p_source jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE existing_id uuid; result jsonb; actual_receipt uuid;
BEGIN
 IF p_source IS NULL THEN RAISE EXCEPTION 'genuine CSV source observation required' USING ERRCODE='22023'; END IF;
 -- Same capacity/source order as the closed creation boundary. Its locks reenter.
 PERFORM twuanis_canonical_private.lock_capacity_policy(false);
 PERFORM pg_advisory_xact_lock(3103,hashtext(jsonb_build_array(p_source->>'source_name',p_source->>'source_listing_id')::text));
 SELECT id INTO existing_id FROM public.listings WHERE source_name=p_source->>'source_name' AND source_listing_id=p_source->>'source_listing_id';
 IF existing_id IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM twuanis_canonical_private.csv_initial_publication WHERE listing_id=existing_id
 ) THEN RAISE EXCEPTION 'existing non-CSV creation cannot acquire CSV eligibility' USING ERRCODE='42501'; END IF;
 result:=public.create_trusted_canonical_listing(p_request,p_input,p_source);
 SELECT r.id INTO STRICT actual_receipt FROM public.canonical_operation_receipts r
 JOIN public.listing_lifecycle_events e ON e.operation_id=r.id AND e.listing_id=r.listing_id
 WHERE r.listing_id=(result->>'listing_id')::uuid AND r.operation_type='create_trusted'
 AND r.authority_kind='trusted' AND r.authority_identity='service_role' AND e.event_type='create';
 -- A replay of unrelated generic creation cannot enroll it through request ID.
 IF existing_id IS NULL AND (result->>'replayed')::boolean THEN
  IF NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.csv_initial_publication WHERE creation_receipt=actual_receipt)
  THEN RAISE EXCEPTION 'CSV creation eligibility absent on replay' USING ERRCODE='42501'; END IF;
 END IF;
 INSERT INTO twuanis_canonical_private.csv_initial_publication(creation_receipt,listing_id)
 VALUES(actual_receipt,(result->>'listing_id')::uuid) ON CONFLICT(creation_receipt) DO NOTHING;
 RETURN result||jsonb_build_object('csv_creation_receipt',actual_receipt::text);
END $$;


--
-- Name: create_customer_addon_order(uuid, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_customer_addon_order(p_request uuid, p_product text, p_currency text, p_listing uuid DEFAULT NULL::uuid, p_job uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE actor uuid:=auth.uid();p twuanis_canonical_private.addon_products%ROWTYPE;r jsonb;
BEGIN
 IF actor IS NULL OR auth.jwt()->>'role' IS DISTINCT FROM 'authenticated' OR NOT public.customer_commerce_ready() OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=actor AND email_confirmed_at IS NOT NULL) THEN RAISE EXCEPTION 'confirmed account and enabled commerce required';END IF;
 SELECT * INTO STRICT p FROM twuanis_canonical_private.addon_products WHERE id=p_product AND state='active';
 IF p_currency IS NULL OR p_currency NOT IN('USD','CRC') OR NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.sinpe_receiving_accounts WHERE enabled AND currency=p_currency) THEN RAISE EXCEPTION 'priced payment channel required';END IF;
 IF p.target='listing' AND (p_listing IS NULL OR p_job IS NOT NULL) THEN RAISE EXCEPTION 'listing target required';END IF;
 IF p.target='operation' AND (p_job IS NULL OR p_listing IS NOT NULL) THEN RAISE EXCEPTION 'import job required';END IF;
 IF p.target='account' THEN
 IF p_listing IS NOT NULL OR p_job IS NOT NULL THEN RAISE EXCEPTION 'account target required';END IF;
 PERFORM pg_advisory_xact_lock(3164,hashtext(actor::text||p_product));
 IF NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_order_snapshots WHERE account_id=actor AND request_id=p_request) AND (
 EXISTS(SELECT 1 FROM twuanis_canonical_private.entitlement_terms t WHERE t.account_id=actor AND t.product_class='FOUNDING_MEMBERSHIP' AND t.starts_at<=clock_timestamp() AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.entitlement_revocations r WHERE r.term_id=t.id)) OR
 EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_order_snapshots o WHERE o.account_id=actor AND o.product_id=p_product AND (o.payment_deadline>clock_timestamp() OR twuanis_canonical_private.sinpe_pending_review(o.id) OR EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_paid_acknowledgements WHERE order_id=o.id)))) THEN RAISE EXCEPTION 'membership active or acquisition pending';END IF;
 END IF;
 r:=twuanis_canonical_private.create_offer_order_snapshot(actor,p_request,'addon',p_product,p_currency,p_listing,p_job);
 RETURN jsonb_build_object('id',r->>'id','replayed',r->'replayed');
END$$;


