--
-- Name: current_account_has_capability(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_account_has_capability(p_capability text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a uuid:=auth.uid();
BEGIN
 IF a IS NULL OR auth.jwt()->>'role' IS DISTINCT FROM 'authenticated' THEN RETURN false;END IF;
 IF public.is_current_user_owner() AND EXISTS(SELECT 1 FROM twuanis_canonical_private.intelligence_capabilities WHERE id=p_capability) THEN RETURN true;END IF;
 RETURN EXISTS(SELECT 1 FROM twuanis_canonical_private.intelligence_package_rights r
 JOIN twuanis_canonical_private.intelligence_package_configurations v ON v.id=r.configuration_id AND v.package_id=r.package_id
 WHERE r.account_id=a AND r.revoked_at IS NULL AND r.starts_at<=statement_timestamp() AND r.ends_at>statement_timestamp() AND p_capability=ANY(v.capabilities))
 OR EXISTS(SELECT 1 FROM twuanis_canonical_private.legacy_package_access g JOIN public.user_subscriptions s ON s.id=g.subscription_id
 WHERE g.account_id=a AND s.user_id=a AND s.package_id=g.package_id AND s.status='active'
 AND s.cancelled_at IS NULL AND s.expired_at IS NULL
 AND s.current_period_start IS NOT DISTINCT FROM g.period_start AND s.current_period_end=g.expires_at
 AND (g.period_start IS NULL OR g.period_start<=statement_timestamp()) AND g.expires_at>statement_timestamp()
 AND p_capability=ANY(g.capabilities));
END$$;


--
-- Name: current_account_has_legacy_valuation_access(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_account_has_legacy_valuation_access() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT auth.uid() IS NOT NULL AND auth.jwt()->>'role'='authenticated' AND (public.is_current_user_owner() OR EXISTS(
 SELECT 1 FROM twuanis_canonical_private.legacy_package_access g
 JOIN public.user_subscriptions s ON s.id=g.subscription_id
 WHERE g.account_id=auth.uid() AND s.user_id=g.account_id AND s.package_id=g.package_id
 AND s.status='active' AND s.cancelled_at IS NULL AND s.expired_at IS NULL
 AND s.current_period_start IS NOT DISTINCT FROM g.period_start AND s.current_period_end=g.expires_at
 AND (g.period_start IS NULL OR g.period_start<=statement_timestamp()) AND g.expires_at>statement_timestamp()))
$$;


--
-- Name: current_account_has_population_capability(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_account_has_population_capability(p_capability text, p_population text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a uuid:=auth.uid();at_time timestamptz:=statement_timestamp();
BEGIN
 IF p_population IS NULL OR p_population NOT IN('PRIVATE','SALE','RENT','BANK') THEN RAISE EXCEPTION 'explicit PRIVATE, SALE, RENT or BANK population required' USING ERRCODE='22023';END IF;
 IF a IS NULL OR auth.jwt()->>'role' IS DISTINCT FROM 'authenticated' OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=a) THEN RETURN false;END IF;
 IF public.is_current_user_owner() AND EXISTS(SELECT 1 FROM twuanis_canonical_private.intelligence_capabilities WHERE id=p_capability) THEN RETURN true;END IF;
 IF p_population IN('PRIVATE','SALE','RENT') THEN RETURN public.current_account_has_capability(p_capability);END IF;
 IF twuanis_canonical_private.receipt_bank_terms(a,p_capability)IS NOT NULL THEN RETURN true;END IF;
 RETURN EXISTS(
 SELECT 1 FROM twuanis_canonical_private.entitlement_terms t
 JOIN twuanis_canonical_private.intelligence_package_rights r ON r.id=t.id AND r.account_id=t.account_id AND r.package_id=t.product_id AND r.configuration_id=t.configuration_id AND r.starts_at=t.starts_at AND r.ends_at=t.ends_at
 JOIN twuanis_canonical_private.intelligence_package_configurations c ON c.id=t.configuration_id AND c.package_id=t.product_id
 JOIN twuanis_canonical_private.offer_order_snapshots o ON o.id=t.order_id AND o.account_id=t.account_id AND o.product_id=t.product_id AND o.target_type='package'
 JOIN twuanis_canonical_private.offer_paid_acknowledgements ack ON ack.id=t.acknowledgement_id AND ack.order_id=o.id AND ack.currency=o.currency AND ack.amount=(o.resolved_terms->>'total')::numeric
 WHERE t.account_id=a AND t.product_class='PACKAGE' AND t.source='PURCHASED' AND t.bank_upgrade_selected
 AND t.starts_at<=at_time AND t.ends_at>at_time AND r.revoked_at IS NULL
 AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.entitlement_revocations v WHERE v.term_id=t.id)
 AND p_capability=ANY(c.capabilities)
 AND o.resolved_terms->>'orderContractVersion'='2'
 AND o.resolved_terms->'terms'->>'unit'='month' AND o.resolved_terms->'terms'->>'quantity'='1'
 AND o.resolved_terms->'terms'->'capabilities'=to_jsonb(c.capabilities)
 AND o.resolved_terms->>'configurationId'=t.configuration_id::text
 AND o.resolved_terms->'bankUpgrade'->'selected'='true'::jsonb
 AND ((ack.source='sinpe' AND EXISTS(SELECT 1 FROM twuanis_canonical_private.sinpe_review_decisions d WHERE d.acknowledgement_id=ack.id AND d.disposition='APPROVED'))
 OR (ack.source='onvo' AND EXISTS(SELECT 1 FROM twuanis_canonical_private.onvo_receipts v WHERE v.acknowledgement_id=ack.id AND v.disposition='APPROVED')) OR(ack.source='stripe'AND twuanis_canonical_private.stripe_paid(ack.id)))
 );
END$$;


--
-- Name: current_administrative_authority(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_administrative_authority() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v uuid:=twuanis_canonical_private.administrative_actor();
BEGIN
 RETURN jsonb_build_object('actorId',v,
 'owner',EXISTS(SELECT 1 FROM twuanis_canonical_private.owner_access_grants WHERE user_id=v AND revoked_at IS NULL),
 'topAdministrator',EXISTS(SELECT 1 FROM twuanis_canonical_private.top_administrator WHERE user_id=v),
 'permissions',(SELECT coalesce(jsonb_agg(permission ORDER BY permission),'[]') FROM twuanis_canonical_private.administrative_permissions WHERE twuanis_canonical_private.administrative_permission(v,permission)));
END $$;


