--
-- Name: customer_transactional_email_service(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_transactional_email_service(p_operation text, p_command jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET lock_timeout TO '5s'
    SET statement_timeout TO '15s'
    AS $$
DECLARE n twuanis_canonical_private.customer_email_obligations; ctl twuanis_canonical_private.customer_email_control; r record; at_time timestamptz:=clock_timestamp();token uuid;recipient text;lang text;count_new integer:=0;outcome text;env jsonb;v_id text;
BEGIN
 IF jsonb_typeof(p_command)<>'object'OR octet_length(p_command::text)>65536 THEN RAISE EXCEPTION 'bounded typed email command required';END IF;
 SELECT *INTO STRICT ctl FROM twuanis_canonical_private.customer_email_control WHERE singleton;
 IF p_operation='capture' THEN
 IF ctl.capture_from IS NULL THEN RETURN jsonb_build_object('state','DISABLED','queued',0);END IF;
 PERFORM pg_advisory_xact_lock(4216,1);
 FOR r IN SELECT s.*FROM twuanis_canonical_private.customer_email_sources s JOIN auth.users u ON u.id=s.account_id JOIN twuanis_canonical_private.account_principals principal ON principal.id=u.id AND principal.deleted_at IS NULL WHERE s.occurred_at>=ctl.capture_from AND s.occurred_at<=at_time AND s.account_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.customer_email_obligations o WHERE o.event_key=s.event_key AND o.account_id=s.account_id AND o.template=s.template AND o.event_revision=s.event_revision AND o.template_version=1)ORDER BY s.occurred_at,s.event_key LIMIT 100 LOOP
 -- Invalid/stale sources are recorded as suppressed once; they cannot starve subsequent events.
 INSERT INTO twuanis_canonical_private.customer_email_obligations(event_key,account_id,template,event_revision,entity_kind,entity_id,occurred_at,payload)VALUES(r.event_key,r.account_id,r.template,r.event_revision,r.entity_kind,r.entity_id,r.occurred_at,r.payload)ON CONFLICT DO NOTHING RETURNING *INTO n;
 IF FOUND THEN count_new:=count_new+1;IF NOT twuanis_canonical_private.customer_email_valid(n,at_time)THEN UPDATE twuanis_canonical_private.customer_email_obligations SET state='SUPPRESSED',last_error='STATE_CHANGED',updated_at=at_time WHERE id=n.id;END IF;END IF;
 END LOOP;

 RETURN jsonb_build_object('state','CAPTURED','queued',count_new);
 ELSIF p_operation='claim' THEN
 IF ctl.capture_from IS NULL THEN RETURN NULL;END IF;
 FOR n IN SELECT *FROM twuanis_canonical_private.customer_email_obligations WHERE state IN('QUEUED','RETRY')AND next_attempt<=at_time AND(lease_until IS NULL OR lease_until<=at_time)ORDER BY next_attempt,id LIMIT 20 FOR UPDATE SKIP LOCKED LOOP
 IF n.attempts>=8 OR(n.first_attempt IS NOT NULL AND at_time>=n.first_attempt+interval '23 hours')THEN UPDATE twuanis_canonical_private.customer_email_obligations SET state='NEEDS_RESOLUTION',lease=NULL,lease_until=NULL,last_error='RETRY_WINDOW_ENDED',updated_at=at_time WHERE id=n.id;CONTINUE;END IF;
 IF NOT twuanis_canonical_private.customer_email_valid(n,at_time)THEN UPDATE twuanis_canonical_private.customer_email_obligations SET state='SUPPRESSED',lease=NULL,lease_until=NULL,last_error='STATE_CHANGED',updated_at=at_time WHERE id=n.id;CONTINUE;END IF;
 SELECT u.email,coalesce(p.language,CASE WHEN n.payload->>'language'IN('en','es')THEN n.payload->>'language'END,'es')INTO recipient,lang FROM auth.users u LEFT JOIN twuanis_canonical_private.account_profiles p ON p.user_id=u.id WHERE u.id=n.account_id;
 IF n.envelope IS NOT NULL AND n.envelope->>'to' IS DISTINCT FROM recipient THEN UPDATE twuanis_canonical_private.customer_email_obligations SET state='SUPPRESSED',last_error='RECIPIENT_CHANGED',lease=NULL,lease_until=NULL,updated_at=at_time WHERE id=n.id;CONTINUE;END IF;
 token:=gen_random_uuid();UPDATE twuanis_canonical_private.customer_email_obligations SET attempts=attempts+1,first_attempt=coalesce(first_attempt,at_time),lease=token,lease_until=at_time+interval '2 minutes',updated_at=at_time WHERE id=n.id;
 RETURN jsonb_build_object('id',n.id,'token',token,'to',recipient,'language',lang,'template',n.template,'payload',n.payload,'envelope',n.envelope,'occurredAt',n.occurred_at);
 END LOOP;RETURN NULL;
 ELSIF p_operation IN('prepare','finish')THEN
 SELECT *INTO STRICT n FROM twuanis_canonical_private.customer_email_obligations WHERE id=(p_command->>'id')::uuid FOR UPDATE;
 IF n.lease IS NULL OR n.lease IS DISTINCT FROM(p_command->>'token')::uuid OR n.lease_until<at_time OR n.state NOT IN('QUEUED','RETRY')THEN RAISE EXCEPTION 'email lease conflict';END IF;
 IF p_operation='prepare'THEN
 env:=p_command->'envelope';SELECT email INTO recipient FROM auth.users WHERE id=n.account_id AND email_confirmed_at IS NOT NULL;
 IF NOT twuanis_canonical_private.customer_email_valid(n,at_time)OR env->>'to'IS DISTINCT FROM recipient THEN UPDATE twuanis_canonical_private.customer_email_obligations SET state='SUPPRESSED',lease=NULL,lease_until=NULL,last_error='STATE_CHANGED'WHERE id=n.id;RETURN NULL;END IF;
 IF jsonb_typeof(env)<>'object'OR EXISTS(SELECT 1 FROM jsonb_object_keys(env)k WHERE k NOT IN('from','to','replyTo','subject','text','html'))OR EXISTS(SELECT 1 FROM jsonb_each(env)e WHERE jsonb_typeof(e.value)<>'string')OR octet_length(env::text)>48000 OR nullif(env->>'subject','')IS NULL OR nullif(env->>'from','')IS NULL OR nullif(env->>'replyTo','')IS NULL OR nullif(env->>'text','')IS NULL OR nullif(env->>'html','')IS NULL OR(env->>'to')~'[\r\n]'THEN RAISE EXCEPTION 'bounded complete envelope required';END IF;
 IF n.envelope IS NOT NULL AND n.envelope IS DISTINCT FROM env THEN RAISE EXCEPTION 'frozen envelope conflict';END IF;
 UPDATE twuanis_canonical_private.customer_email_obligations SET envelope=env WHERE id=n.id;RETURN env;
 END IF;
 outcome:=p_command->>'outcome';IF outcome NOT IN('ACCEPTED','RETRY','FAILED')THEN RAISE EXCEPTION 'typed outcome required';END IF;
 IF outcome='ACCEPTED'AND(n.envelope IS NULL OR nullif(p_command->>'messageId','')IS NULL OR length(p_command->>'messageId')>200)THEN RAISE EXCEPTION 'frozen message and provider acknowledgement required';END IF;
 UPDATE twuanis_canonical_private.customer_email_obligations SET state=CASE WHEN outcome='ACCEPTED'THEN coalesce(twuanis_canonical_private.customer_email_provider_state(p_command->>'messageId'),'ACCEPTED')WHEN outcome='RETRY'AND attempts>=8 THEN 'NEEDS_RESOLUTION'ELSE outcome END,provider_message=CASE WHEN outcome='ACCEPTED'THEN p_command->>'messageId'ELSE provider_message END,lease=NULL,lease_until=NULL,next_attempt=at_time+make_interval(secs=>least(3600,60*(2^attempts)::integer)),last_error=CASE WHEN outcome='ACCEPTED'THEN NULL ELSE left(coalesce(p_command->>'error','TRANSPORT_UNAVAILABLE'),100)END,updated_at=at_time WHERE id=n.id;
 INSERT INTO twuanis_canonical_private.customer_email_attempts(obligation_id,attempt,outcome,provider_message,error_code)VALUES(n.id,n.attempts,outcome,CASE WHEN outcome='ACCEPTED'THEN p_command->>'messageId'END,CASE WHEN outcome<>'ACCEPTED'THEN left(coalesce(p_command->>'error','TRANSPORT_UNAVAILABLE'),100)END);
 RETURN jsonb_build_object('state',outcome);
 ELSIF p_operation='provider_event'THEN
 IF p_command->>'kind'NOT IN('email.delivered','email.bounced','email.failed','email.suppressed','email.complained','email.delivery_delayed')OR length(p_command->>'eventId')NOT BETWEEN 1 AND 200 OR length(p_command->>'messageId')NOT BETWEEN 1 AND 200 OR(p_command->>'occurredAt')::timestamptz>at_time+interval '5 minutes'THEN RAISE EXCEPTION 'typed provider evidence required';END IF;
 INSERT INTO twuanis_canonical_private.customer_email_provider_events(event_id,provider_message,kind,occurred_at)VALUES(p_command->>'eventId',p_command->>'messageId',p_command->>'kind',(p_command->>'occurredAt')::timestamptz)ON CONFLICT DO NOTHING;
 IF NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.customer_email_provider_events WHERE event_id=p_command->>'eventId'AND provider_message=p_command->>'messageId'AND kind=p_command->>'kind'AND occurred_at=(p_command->>'occurredAt')::timestamptz)THEN RAISE EXCEPTION 'provider event replay conflict';END IF;
 UPDATE twuanis_canonical_private.customer_email_obligations SET state=twuanis_canonical_private.customer_email_provider_state(provider_message),updated_at=at_time WHERE provider_message=p_command->>'messageId';RETURN jsonb_build_object('ok',true);
 ELSE RAISE EXCEPTION 'unknown customer email operation';END IF;
END$$;


--
-- Name: detach_listing_image(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.detach_listing_image(p_owner uuid, p_listing uuid, p_image text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE l public.listings%ROWTYPE;op twuanis_canonical_private.image_detach_operations%ROWTYPE;paths jsonb;raw text;is_managed boolean;
BEGIN
 SELECT * INTO l FROM public.listings WHERE id=p_listing FOR UPDATE;
 IF NOT FOUND OR p_owner IS NULL OR l.owner_id IS DISTINCT FROM p_owner OR l.listing_status IS NULL OR l.listing_status='deleted' OR (l.canonical_domain_version IS NOT NULL AND l.canonical_domain_version<>1) THEN RAISE EXCEPTION 'owned eligible listing required' USING ERRCODE='42501';END IF;
 IF p_image IS NULL OR length(p_image)>4096 THEN RAISE EXCEPTION 'invalid image' USING ERRCODE='22023';END IF;
 is_managed:=p_image ~ ('^'||p_owner::text||'/'||p_listing::text||'/[a-zA-Z0-9_-]+[.]jpg$');
 IF NOT is_managed AND p_image !~ '^https?://[^[:space:]]+$' THEN RAISE EXCEPTION 'foreign or invalid media path' USING ERRCODE='42501';END IF;
 raw:=btrim(coalesce(l.images::text,''));
 IF raw IN ('','null') THEN paths:='[]';ELSIF left(raw,1)='[' THEN paths:=raw::jsonb;ELSE paths:=to_jsonb(string_to_array(raw,'|'));END IF;
 IF jsonb_typeof(paths)<>'array' OR EXISTS(SELECT 1 FROM jsonb_array_elements(paths) v WHERE jsonb_typeof(v)<>'string') THEN RAISE EXCEPTION 'invalid image array' USING ERRCODE='22023';END IF;
 SELECT * INTO op FROM twuanis_canonical_private.image_detach_operations WHERE owner_id=p_owner AND listing_id=p_listing AND image_value=p_image;
 IF FOUND THEN
  IF paths @> jsonb_build_array(p_image) THEN RAISE EXCEPTION 'previously detached image is attached; do not clean up' USING ERRCODE='55000';END IF;
 ELSE
  IF NOT paths @> jsonb_build_array(p_image) THEN RAISE EXCEPTION 'attached image required' USING ERRCODE='22023';END IF;
  -- Detach all references to this one object; deleting bytes while another reference remains is unsafe.
  SELECT coalesce(jsonb_agg(value ORDER BY n),'[]') INTO paths FROM jsonb_array_elements(paths) WITH ORDINALITY a(value,n) WHERE value<>to_jsonb(p_image);
  UPDATE public.listings SET images=paths::text,updated_at=clock_timestamp() WHERE id=l.id;
  INSERT INTO twuanis_canonical_private.image_detach_operations(owner_id,listing_id,image_value,managed,cleanup_completed)
   VALUES(p_owner,p_listing,p_image,is_managed,NOT is_managed) RETURNING * INTO op;
 END IF;
 RETURN twuanis_canonical_private.duplicate_protect_media_result(to_jsonb(op)||jsonb_build_object('images',paths,'imageCount',jsonb_array_length(paths)));
END $_$;


--
-- Name: direct_sinpe_ready(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.direct_sinpe_ready() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT public.customer_commerce_ready()AND EXISTS(SELECT 1 FROM storage.buckets WHERE id='sinpe-receipts'AND NOT public AND file_size_limit=5242880 AND allowed_mime_types=ARRAY['application/pdf','image/jpeg','image/png','image/webp'])AND EXISTS(SELECT 1 FROM twuanis_canonical_private.sinpe_receiving_accounts WHERE enabled AND payment_method='direct_sinpe'AND currency='CRC'AND receiving_phone IS NOT NULL);$$;


--
-- Name: edit_customer_canonical_listing(uuid, bigint, uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.edit_customer_canonical_listing(p_listing uuid, p_expected bigint, p_request uuid, p_domains jsonb, p_content jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE actor uuid:=auth.uid(); previous twuanis_canonical_private.customer_content_edits%ROWTYPE; item record; result jsonb;
BEGIN
 IF actor IS NULL THEN RAISE EXCEPTION 'authenticated customer required' USING ERRCODE='42501'; END IF;
 PERFORM twuanis_canonical_private.s3_keys(p_content,ARRAY['title','description','whatsapp']);
 FOR item IN SELECT key,value FROM jsonb_each(p_content) LOOP
  IF jsonb_typeof(item.value)<>'string' OR length(item.value#>>'{}')>(CASE item.key WHEN 'title' THEN 512 WHEN 'description' THEN 16000 ELSE 256 END) THEN RAISE EXCEPTION 'bounded content required' USING ERRCODE='22023'; END IF;
 END LOOP;
 PERFORM twuanis_canonical_private.ensure_publisher_account(actor);
 PERFORM pg_advisory_xact_lock(3104,hashtext(jsonb_build_array('owner',actor::text,'domain_mutation',p_request)::text));
 SELECT * INTO previous FROM twuanis_canonical_private.customer_content_edits WHERE owner_id=actor AND request_id=p_request;
 IF FOUND THEN
  IF previous.listing_id IS DISTINCT FROM p_listing OR previous.expected_revision IS DISTINCT FROM p_expected OR previous.content IS DISTINCT FROM p_content THEN RAISE EXCEPTION 'content idempotency conflict' USING ERRCODE='22023'; END IF;
 ELSE
  IF EXISTS(SELECT 1 FROM public.canonical_operation_receipts WHERE authority_kind='owner' AND authority_identity=actor::text AND operation_type='domain_mutation' AND request_id=p_request) THEN RAISE EXCEPTION 'request already belongs to a different operation' USING ERRCODE='22023'; END IF;
  INSERT INTO twuanis_canonical_private.customer_content_edits(owner_id,request_id,listing_id,expected_revision,content) VALUES(actor,p_request,p_listing,p_expected,p_content);
 END IF;
 result:=twuanis_canonical_private.s3_admission_command(p_listing,p_expected,'owner',actor::text,p_request,p_domains,NULL,false,p_content);
 IF result->>'admission' IN ('REVIEW_REQUIRED','AUTOMATIC_REJECTION') THEN RETURN result||jsonb_build_object('listing_id',p_listing); END IF;
 IF coalesce(previous.completed,false) THEN RETURN result; END IF;
 UPDATE public.listings SET
 title=CASE WHEN p_content?'title' THEN p_content->>'title' ELSE title END,
 description=CASE WHEN p_content?'description' THEN p_content->>'description' ELSE description END,
 whatsapp=CASE WHEN p_content?'whatsapp' THEN p_content->>'whatsapp' ELSE whatsapp END
 WHERE id=p_listing AND owner_id=actor AND canonical_domain_version=1;
 IF NOT FOUND THEN RAISE EXCEPTION 'owned canonical listing required' USING ERRCODE='42501'; END IF;
 UPDATE twuanis_canonical_private.customer_content_edits SET completed=true WHERE owner_id=actor AND request_id=p_request;
 RETURN result;
END $$;


--
-- Name: execute_free_customer_addon_import(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.execute_free_customer_addon_import(p_job uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE actor uuid:=auth.uid(); j twuanis_canonical_private.addon_import_jobs%ROWTYPE; x jsonb; created jsonb; published jsonb;
BEGIN
 PERFORM public.guard_live_account_request();
 IF actor IS NULL OR auth.jwt()->>'role' IS DISTINCT FROM 'authenticated' THEN RAISE EXCEPTION 'authenticated customer required' USING ERRCODE='42501'; END IF;
 -- Match the paid path's policy → publisher → job lock order.
 PERFORM twuanis_canonical_private.lock_capacity_policy(false);
 PERFORM twuanis_canonical_private.ensure_publisher_account(actor);
 SELECT * INTO STRICT j FROM twuanis_canonical_private.addon_import_jobs WHERE id=p_job AND account_id=actor FOR UPDATE;
 IF j.validator_version<>'canonical-customer-free-v1' OR j.total IS NOT NULL OR j.unit_rate IS NOT NULL THEN RAISE EXCEPTION 'free customer job required' USING ERRCODE='42501'; END IF;
 LOCK TABLE public.ontology_terms,public.ontology_relationships,twuanis_canonical_private.accessibility_identity IN SHARE MODE;
 FOR x IN SELECT value FROM jsonb_array_elements(j.accepted_rows) LOOP PERFORM twuanis_canonical_private.addon_customer_input(x->'input'); END LOOP;
 PERFORM twuanis_canonical_private.addon_publication_capacity(actor,j.accepted_count);
 FOR x IN SELECT value FROM jsonb_array_elements(j.accepted_rows) LOOP
  created:=twuanis_canonical_private.s4_create_core(actor,(x->>'rowId')::uuid,x->'input',NULL);
  published:=twuanis_canonical_private.customer_publication_core(actor,(created->>'listing_id')::uuid,(created->>'revision')::bigint,(x->>'publicationRequest')::uuid,'publish');
  IF published->>'outcome' IS NOT NULL AND published->>'outcome' NOT IN('succeeded','noop') THEN RAISE EXCEPTION 'canonical publication failed'; END IF;
 END LOOP;
 RETURN public.read_customer_addon_job(j.id);
END $$;


--
-- Name: execution_credit_commerce_ready(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.execution_credit_commerce_ready() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$SELECT coalesce((SELECT enabled AND execution_credit_enabled FROM twuanis_canonical_private.customer_commerce_control WHERE singleton),false)$$;


--
-- Name: execution_credit_service(jsonb, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.execution_credit_service(p_claims jsonb, p_request uuid, p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a uuid;prior twuanis_canonical_private.execution_credit_receipts%ROWTYPE;x twuanis_canonical_private.execution_credit_executions%ROWTYPE;allocation twuanis_canonical_private.execution_credit_allocations%ROWTYPE;report twuanis_canonical_private.execution_credit_reports%ROWTYPE;authority jsonb;result jsonb;op text;execution_id_value uuid;reason text;n bigint;owner boolean;
BEGIN
 a:=twuanis_canonical_private.execution_credit_bridge(p_claims);op:=p_command->>'operation';
 IF p_request IS NULL OR jsonb_typeof(p_command)IS DISTINCT FROM'object' OR octet_length(p_command::text)>16000 OR op IS NULL OR op NOT IN('sync','reserve','release','settle','adjust','refund')THEN RAISE EXCEPTION 'Bounded execution-credit command required';END IF;
 SELECT * INTO prior FROM twuanis_canonical_private.execution_credit_receipts WHERE account_id=a AND request_id=p_request;
 IF FOUND THEN IF prior.command IS DISTINCT FROM p_command THEN RAISE EXCEPTION 'Command retry conflict';END IF;RETURN prior.result||jsonb_build_object('replayed',true);END IF;
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_command)k WHERE k NOT IN('operation','execution','orchestrator','population','request','reason','allocation','delta','confirmed'))THEN RAISE EXCEPTION 'Unknown execution-credit command field';END IF;

 IF(SELECT array_agg(k ORDER BY k)FROM jsonb_object_keys(p_command)k)IS DISTINCT FROM (CASE op
 WHEN'sync'THEN ARRAY['operation'] WHEN'reserve'THEN ARRAY['execution','operation','orchestrator','population','request'] WHEN'release'THEN ARRAY['execution','operation','reason'] WHEN'settle'THEN ARRAY['execution','operation'] WHEN'adjust'THEN ARRAY['allocation','confirmed','delta','operation','reason'] WHEN'refund'THEN ARRAY['confirmed','execution','operation','reason']END) THEN RAISE EXCEPTION 'Exact operation fields required';END IF;
 PERFORM twuanis_canonical_private.execution_credit_sync(a,p_request);owner:=public.is_current_user_owner();
 IF op='sync' THEN result:=jsonb_build_object('state','SYNCHRONIZED');
 ELSIF op='reserve' THEN
  execution_id_value:=(p_command->>'execution')::uuid;authority:=twuanis_canonical_private.execution_credit_authority(p_command->>'orchestrator',p_command->>'population');
  IF execution_id_value IS NULL OR jsonb_typeof(p_command->'request') IS DISTINCT FROM'object' THEN RAISE EXCEPTION 'Execution identity and question required';END IF;
  SELECT * INTO x FROM twuanis_canonical_private.execution_credit_executions WHERE execution_credit_executions.id=execution_id_value;
  IF FOUND THEN IF x.account_id<>a OR x.orchestrator_id IS DISTINCT FROM p_command->>'orchestrator' OR x.population IS DISTINCT FROM p_command->>'population' OR x.request_payload IS DISTINCT FROM p_command->'request' THEN RAISE EXCEPTION 'Execution retry conflict';END IF;
   result:=jsonb_build_object('execution',execution_id_value,'state',twuanis_canonical_private.execution_credit_execution_state(execution_id_value),'allocation',x.allocation_id,'unmetered',x.allocation_id IS NULL);
  ELSE
   IF NOT owner THEN
    SELECT * INTO allocation FROM twuanis_canonical_private.execution_credit_allocations c WHERE c.account_id=a AND twuanis_canonical_private.execution_credit_allocation_live(c.id) AND twuanis_canonical_private.execution_credit_remaining(c.id)>0
    ORDER BY CASE c.kind WHEN 'INCLUDED_PACKAGE'THEN 1 WHEN'ADMIN_ALLOWANCE'THEN 2 ELSE 3 END,c.expires_at NULLS LAST,c.effective_at,c.id LIMIT 1;
    IF NOT FOUND THEN RAISE EXCEPTION 'Execution credit balance required' USING ERRCODE='42501';END IF;
   END IF;
   INSERT INTO twuanis_canonical_private.execution_credit_executions(id,account_id,request_id,orchestrator_id,population,request_payload,allocation_id,authority,reserved_at,lease_until) VALUES(execution_id_value,a,p_request,p_command->>'orchestrator',p_command->>'population',p_command->'request',allocation.id,authority,clock_timestamp(),clock_timestamp()+interval'10 minutes');
   PERFORM twuanis_canonical_private.execution_credit_event(a,allocation.id,execution_id_value,NULL,'EXECUTION_RESERVED',CASE WHEN owner THEN 0 ELSE 1 END,a,p_request,jsonb_build_object('authority',authority));result:=jsonb_build_object('execution',execution_id_value,'state','RESERVED','allocation',allocation.id,'unmetered',owner);
  END IF;
 ELSIF op IN('release','settle','refund')THEN
  execution_id_value:=(p_command->>'execution')::uuid;SELECT * INTO STRICT x FROM twuanis_canonical_private.execution_credit_executions WHERE execution_credit_executions.id=execution_id_value AND(account_id=a OR(op='refund' AND owner));
  IF op='release' THEN
   reason:=p_command->>'reason';IF reason NOT IN('REQUEST_REJECTED','REQUIRED_ENGINE_FAILED','REPORT_COMPOSITION_FAILED','PERSISTENCE_FAILED','ENTIRELY_UNDEFINED','AUTHORIZATION_LOST','SYSTEM_FAILURE') OR reason IS NULL THEN RAISE EXCEPTION 'Explicit system release reason required';END IF;
   IF twuanis_canonical_private.execution_credit_execution_state(execution_id_value)='COMPLETED'THEN RAISE EXCEPTION 'Completed report cannot be released';END IF;
   IF twuanis_canonical_private.execution_credit_execution_state(execution_id_value)='RESERVED'THEN PERFORM twuanis_canonical_private.execution_credit_event(a,x.allocation_id,execution_id_value,NULL,'RESERVATION_RELEASED',CASE WHEN x.allocation_id IS NULL THEN 0 ELSE 1 END,a,p_request,jsonb_build_object('reason',reason));END IF;result:=jsonb_build_object('execution',execution_id_value,'state','RELEASED');
  ELSIF op='refund' THEN
   IF NOT owner OR p_command->>'confirmed'IS DISTINCT FROM'true' OR p_command->>'reason'NOT IN('SYSTEM_DELIVERY_FAILURE','ACCOUNTING_CORRECTION') OR p_command->>'reason'IS NULL OR x.allocation_id IS NULL OR twuanis_canonical_private.execution_credit_execution_state(execution_id_value)<>'COMPLETED'THEN RAISE EXCEPTION 'Explicit Owner accounting correction required' USING ERRCODE='42501';END IF;
   IF NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.execution_credit_events WHERE execution_id=execution_id_value AND kind='REFUND')THEN PERFORM pg_advisory_xact_lock(3512,hashtext(x.account_id::text));PERFORM twuanis_canonical_private.execution_credit_maintain(x.account_id,p_request);PERFORM twuanis_canonical_private.execution_credit_event(x.account_id,x.allocation_id,execution_id_value,NULL,'REFUND',1,a,p_request,jsonb_build_object('reason',p_command->>'reason'));IF NOT twuanis_canonical_private.execution_credit_allocation_live(x.allocation_id) THEN PERFORM twuanis_canonical_private.execution_credit_event(x.account_id,x.allocation_id,NULL,NULL,'ADJUSTMENT',-1,a,p_request,jsonb_build_object('reason','REFUND_RETAINS_ORIGINAL_EXPIRY','execution',execution_id_value));END IF;END IF;result:=jsonb_build_object('execution',execution_id_value,'state','REFUNDED');
  ELSE
   IF twuanis_canonical_private.execution_credit_execution_state(execution_id_value)<>'RESERVED'THEN result:=jsonb_build_object('execution',execution_id_value,'state',twuanis_canonical_private.execution_credit_execution_state(execution_id_value));
   ELSE
    reason:=NULL;
    BEGIN authority:=twuanis_canonical_private.execution_credit_authority(x.orchestrator_id,x.population);IF authority IS DISTINCT FROM x.authority THEN reason:='AUTHORIZATION_CHANGED';END IF;EXCEPTION WHEN insufficient_privilege THEN reason:='AUTHORIZATION_LOST';END;
    SELECT * INTO report FROM twuanis_canonical_private.execution_credit_reports WHERE execution_id=execution_id_value AND account_id=a;
    IF report.id IS NULL THEN reason:='DURABLE_REPORT_REQUIRED';ELSIF report.substantive_count=0 THEN reason:='ENTIRELY_UNDEFINED';END IF;
    IF reason IS NOT NULL THEN PERFORM twuanis_canonical_private.execution_credit_event(a,x.allocation_id,execution_id_value,NULL,'RESERVATION_RELEASED',CASE WHEN x.allocation_id IS NULL THEN 0 ELSE 1 END,a,p_request,jsonb_build_object('reason',reason));result:=jsonb_build_object('execution',execution_id_value,'state','RELEASED','reason',reason);
    ELSE PERFORM twuanis_canonical_private.execution_credit_event(a,x.allocation_id,execution_id_value,report.id,CASE WHEN x.allocation_id IS NULL THEN'OWNER_COMPLETED'ELSE'EXECUTION_CONSUMED'END,CASE WHEN x.allocation_id IS NULL THEN 0 ELSE 1 END,a,p_request,jsonb_build_object('substantiveCount',report.substantive_count,'contentMD5',report.content_md5));result:=jsonb_build_object('execution',execution_id_value,'state','COMPLETED','report',report.id,'charged',x.allocation_id IS NOT NULL);END IF;
   END IF;
  END IF;
 ELSIF op='adjust'THEN
  IF NOT owner OR p_command->>'confirmed'IS DISTINCT FROM'true' OR coalesce(length(btrim(p_command->>'reason')),0)<8 THEN RAISE EXCEPTION 'Confirmed Owner adjustment required' USING ERRCODE='42501';END IF;
  SELECT * INTO STRICT allocation FROM twuanis_canonical_private.execution_credit_allocations WHERE execution_credit_allocations.id=(p_command->>'allocation')::uuid;
  PERFORM pg_advisory_xact_lock(3512,hashtext(allocation.account_id::text));n:=(p_command->>'delta')::bigint;
  IF n IS NULL OR n=0 OR abs(n)>1000000 OR NOT twuanis_canonical_private.execution_credit_allocation_live(allocation.id) OR twuanis_canonical_private.execution_credit_remaining(allocation.id)+n<0 THEN RAISE EXCEPTION 'Bounded nonnegative adjustment required';END IF;
  PERFORM twuanis_canonical_private.execution_credit_event(allocation.account_id,allocation.id,NULL,NULL,'ADJUSTMENT',n,a,p_request,jsonb_build_object('reason',p_command->>'reason','authority','OWNER_ADJUSTMENT'));result:=jsonb_build_object('allocation',allocation.id,'state','ADJUSTED','delta',n::text);
 END IF;
 INSERT INTO twuanis_canonical_private.execution_credit_receipts(account_id,request_id,command,result) VALUES(a,p_request,p_command,result);RETURN result||jsonb_build_object('replayed',false);
END$$;


--
-- Name: fulfill_execution_credit_purchase(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fulfill_execution_credit_purchase(p_order uuid, p_ack uuid, p_request uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN IF auth.jwt()->>'role'IS DISTINCT FROM'service_role'THEN RAISE EXCEPTION 'Trusted payment fulfillment required' USING ERRCODE='42501';END IF;RETURN twuanis_canonical_private.commit_execution_credit_purchase(p_order,p_ack,p_request);END$$;


--
-- Name: get_image_detach_operation(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_image_detach_operation(p_owner uuid, p_operation uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE op twuanis_canonical_private.image_detach_operations%ROWTYPE;
BEGIN
 SELECT * INTO op FROM twuanis_canonical_private.image_detach_operations WHERE id=p_operation AND owner_id=p_owner;
 IF NOT FOUND THEN RAISE EXCEPTION 'owned detach operation required' USING ERRCODE='42501';END IF;
 RETURN twuanis_canonical_private.duplicate_protect_media_result(public.detach_listing_image(p_owner,op.listing_id,op.image_value));
END $$;


--
-- Name: get_my_listing_activity_counts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_listing_activity_counts() RETURNS TABLE(listing_id uuid, view_count bigint, favorite_count bigint, share_count bigint, whatsapp_click_count bigint)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    l.id as listing_id,

    count(*) filter (
      where ae.event_type = 'listing_viewed'
    ) as view_count,

    count(*) filter (
      where ae.event_type = 'listing_saved'
    ) as favorite_count,

    count(*) filter (
      where ae.event_type = 'listing_shared'
    ) as share_count,

    count(*) filter (
      where ae.event_type = 'listing_whatsapp_clicked'
    ) as whatsapp_click_count

  from public.listings l

  left join public.activity_events ae
    on ae.entity_type = 'listing'
    and ae.entity_id = l.id::text

  where l.owner_id = auth.uid()

  group by l.id;
$$;


--
-- Name: get_ordinary_upload(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ordinary_upload(p_owner uuid, p_operation uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE op twuanis_canonical_private.ordinary_upload_operations%ROWTYPE;
BEGIN
 SELECT o.* INTO op FROM twuanis_canonical_private.ordinary_upload_operations o JOIN public.listings l ON l.id=o.listing_id
 WHERE o.id=p_operation AND o.owner_id=p_owner AND l.owner_id=p_owner AND l.listing_status IS NOT NULL AND l.listing_status<>'deleted' AND (l.canonical_domain_version IS NULL OR l.canonical_domain_version=1);
 IF NOT FOUND THEN RAISE EXCEPTION 'owned eligible upload required' USING ERRCODE='42501';END IF;
 RETURN to_jsonb(op);
END $$;


--
-- Name: get_payment_review_queue(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_payment_review_queue() RETURNS TABLE(payment_id uuid, subscription_id uuid, user_id uuid, package_id uuid, package_slug text, package_name_en text, package_name_es text, amount numeric, currency text, sinpe_reference text, sender_name text, sender_phone text, payment_date timestamp with time zone, payment_status text, subscription_status text, submitted_at timestamp with time zone, user_email text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin

  perform public.require_payment_reviewer();

  return query

  select
    sp.id,
    us.id,
    us.user_id,

    p.id,
    p.slug::text,
    p.name_en::text,
    p.name_es::text,

    sp.amount,
    sp.currency::text,

    sp.sinpe_reference::text,
    sp.sender_name::text,
    sp.sender_phone::text,

    sp.payment_date,

    sp.status::text,
    us.status::text,

    sp.created_at,

    au.email::text

  from public.sinpe_payments sp

  join public.user_subscriptions us
    on us.id = sp.subscription_id

  join public.packages p
    on p.id = us.package_id

  join auth.users au
    on au.id = us.user_id

  where
    sp.status in (
      'submitted',
      'under_review'
    )

    and us.status =
      'pending_payment'

  order by
    sp.created_at asc;

end;
$$;


--
-- Name: get_token_canonical_operation(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_token_canonical_operation(p_token text, p_owner uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE c twuanis_canonical_private.token_creation_commands%ROWTYPE;
BEGIN
 SELECT x.* INTO c FROM twuanis_canonical_private.token_creation_commands x JOIN public.listing_publish_tokens t ON t.token=x.token WHERE t.token=p_token;
 IF NOT FOUND THEN RETURN NULL;END IF;
 IF c.owner_id IS DISTINCT FROM p_owner THEN RAISE EXCEPTION 'token owner conflict' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('listing_id',c.listing_id::text,'media',c.media,'completed',c.media_completed,'publication',c.publication_result,'transaction',(SELECT transaction_type FROM public.listings WHERE id=c.listing_id));
END $$;


--
-- Name: guard_live_account_request(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_live_account_request() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF auth.jwt()->>'role'='authenticated' AND NOT public.is_live_account() THEN RAISE EXCEPTION 'account no longer exists' USING ERRCODE='42501';END IF;
END$$;


--
-- Name: ingest_canonical_source_observation(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ingest_canonical_source_observation(p_evidence uuid, p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE e twuanis_canonical_private.csv_source_evidence%ROWTYPE; l public.listings%ROWTYPE;
 st twuanis_canonical_private.source_ingestion_state%ROWTYPE; cached jsonb; src jsonb; result jsonb; d jsonb;
 created jsonb; item record; sets uuid[]; refreshed boolean:=false; source_images text[]; url text; geo jsonb;
BEGIN
 SELECT * INTO e FROM twuanis_canonical_private.csv_source_evidence WHERE id=p_evidence;
 IF NOT FOUND THEN RAISE EXCEPTION 'retained source evidence required'; END IF;
 PERFORM twuanis_canonical_private.lock_capacity_policy(false);
 PERFORM pg_advisory_xact_lock(3123,hashtext(e.source_name));
 SELECT r.result INTO cached FROM twuanis_canonical_private.source_ingestion_results r WHERE evidence_id=p_evidence;
 IF FOUND THEN
  IF cached->>'admission' IN('REVIEW_REQUIRED','AUTOMATIC_REJECTION') AND cached?'sourceEvidence' AND EXISTS(SELECT 1 FROM twuanis_canonical_private.listing_duplicate_cases c WHERE c.id=(cached->>'caseId')::uuid AND c.status='DIFFERENT_PROPERTIES') THEN DELETE FROM twuanis_canonical_private.source_ingestion_results WHERE evidence_id=p_evidence;
  ELSE RETURN cached||'{""replayed"":true}'::jsonb; END IF;
 END IF;
 -- Indexed exact identity. No population acquisition or similarity comparison.
 SELECT * INTO l FROM public.listings WHERE source_name=e.source_name AND source_listing_id=e.source_listing_id FOR UPDATE;
 src:=jsonb_build_object('source_name',e.source_name,'source_listing_id',e.source_listing_id,'observation_id',e.source_observation_id,'observed_at',e.source_observed_at,'source_type','realtor');
 IF NOT FOUND THEN
  created:=public.create_csv_canonical_listing(p_evidence,p_input,src);
  PERFORM public.complete_csv_source_references((created->>'csv_creation_receipt')::uuid,p_evidence);
  result:=public.initially_publish_csv_listing((created->>'csv_creation_receipt')::uuid);
  INSERT INTO twuanis_canonical_private.source_ingestion_state(source_name,source_listing_id,listing_id)
  VALUES(e.source_name,e.source_listing_id,(created->>'listing_id')::uuid);
  result:=coalesce(result,'{}'::jsonb)||jsonb_build_object('listing_id',created->>'listing_id','created',true,'outcome',CASE WHEN result->>'admission' IN ('REVIEW_REQUIRED','AUTOMATIC_REJECTION') THEN 'held' ELSE 'accepted' END);
 ELSE
  IF l.canonical_domain_version IS DISTINCT FROM 1 OR l.owner_id IS NOT NULL OR l.publisher_account_id IS NOT NULL OR l.listing_origin IS DISTINCT FROM 'imported' THEN RAISE EXCEPTION 'ownerless canonical source appearance required'; END IF;
  SELECT jsonb_build_object('admission',CASE WHEN c.status IN('AUTOMATIC_REJECTION','CONFIRM_DUPLICATE') THEN 'AUTOMATIC_REJECTION' ELSE 'REVIEW_REQUIRED' END,'caseId',c.id,'listing_id',l.id,'outcome','held','sourceEvidence',p_evidence) INTO result FROM twuanis_canonical_private.listing_duplicate_cases c WHERE c.listing_id=l.id AND c.status IN('REVIEW_REQUIRED','AUTOMATIC_REJECTION','CONFIRM_DUPLICATE','UNRESOLVED');
  IF FOUND THEN INSERT INTO twuanis_canonical_private.source_ingestion_results VALUES(p_evidence,result);UPDATE twuanis_canonical_private.source_ingestion_state SET misses=0,positive_at=clock_timestamp() WHERE listing_id=l.id;RETURN result; END IF;
  SELECT * INTO st FROM twuanis_canonical_private.source_ingestion_state WHERE listing_id=l.id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'source ingestion state absent; no legacy adoption'; END IF;
  src:=(src-'source_type')||jsonb_build_object('transaction',p_input->'transaction','geography',p_input->'geography');
  d:=jsonb_build_object('geography',p_input->'geography');
  IF p_input ? 'money' THEN d:=d||jsonb_build_object('money',p_input->'money'); END IF;
  IF p_input ? 'measurements' THEN d:=d||jsonb_build_object('measurements',p_input->'measurements'); END IF;
  d:=twuanis_canonical_private.s4_domains(d,'source');
  -- Preserve recorded sealed derivation authority; never select a default rule.
  FOR item IN SELECT key FROM jsonb_each(coalesce(d->'measurements','{}')) LOOP
   SELECT array_agg(DISTINCT r.rule_set_id) INTO sets FROM public.listing_membership_origins o
   JOIN public.listing_classification_rules r ON r.id=o.classification_rule_id WHERE o.listing_id=l.id AND o.origin_domain=item.key;
   IF cardinality(sets)>1 THEN RAISE EXCEPTION 'ambiguous recorded measurement rule'; END IF;
   IF cardinality(sets)=1 THEN d:=jsonb_set(d,ARRAY['measurements',item.key,'rule_set'],to_jsonb(sets[1]::text)); END IF;
  END LOOP;
  SELECT jsonb_object_agg(t.term_type,t.official_code) INTO geo FROM public.listing_membership_origins o JOIN public.ontology_terms t ON t.id=o.ontology_term_id WHERE o.listing_id=l.id AND o.origin_domain='geography';
  -- Conflict/stale machinery must run before restoration. It returns before state edits.
  IF l.transaction_type IS DISTINCT FROM src->>'transaction' OR geo->>'province' IS DISTINCT FROM src->'geography'->>'province' OR geo->>'canton' IS DISTINCT FROM src->'geography'->>'canton' OR e.source_observed_at<l.last_seen THEN
   result:=twuanis_canonical_private.s3_command(l.id,l.canonical_revision,'trusted','service_role',p_evidence,d,src)||jsonb_build_object('listing_id',l.id::text);
  IF result->>'admission' IN ('REVIEW_REQUIRED','AUTOMATIC_REJECTION') THEN INSERT INTO twuanis_canonical_private.source_ingestion_results VALUES(p_evidence,result); RETURN result; END IF;
  ELSE
   IF st.archive_revision IS NOT NULL THEN
    IF l.listing_status<>'archived' OR l.canonical_revision<>st.archive_revision THEN RAISE EXCEPTION 'source archive state changed'; END IF;
    result:=twuanis_canonical_private.s3_command(l.id,l.canonical_revision,'trusted','service_role',gen_random_uuid(),'{""lifecycle"":{""event"":""restore"",""reason"":""observed again at source""}}',NULL);
  IF result->>'admission' IN ('REVIEW_REQUIRED','AUTOMATIC_REJECTION') THEN INSERT INTO twuanis_canonical_private.source_ingestion_results VALUES(p_evidence,result); RETURN result; END IF;
    SELECT * INTO l FROM public.listings WHERE id=l.id;
   END IF;
   result:=twuanis_canonical_private.s3_command(l.id,l.canonical_revision,'trusted','service_role',p_evidence,d,src)||jsonb_build_object('listing_id',l.id::text);
  IF result->>'admission' IN ('REVIEW_REQUIRED','AUTOMATIC_REJECTION') THEN INSERT INTO twuanis_canonical_private.source_ingestion_results VALUES(p_evidence,result); RETURN result; END IF;
   IF result->>'outcome'='accepted' OR result->>'outcome'='succeeded' THEN
    url:=e.raw_input->>'source_url';
    IF length(url) BETWEEN 1 AND 4096 AND url ~ '^https?://[^[:space:]]+$' THEN UPDATE public.listings SET source_url=url WHERE id=l.id; END IF;
    IF clock_timestamp()>=st.presentation_at+interval '6 months' THEN
     IF NULLIF(btrim(p_input->'content'->>'title'), '') IS NOT NULL THEN
        UPDATE public.listings
        SET title=btrim(p_input->'content'->>'title')
        WHERE id=l.id;
        refreshed:=true;
        END IF;

        IF NULLIF(btrim(e.raw_input->>'description'), '') IS NOT NULL THEN
        UPDATE public.listings
        SET description=e.raw_input->>'description'
        WHERE id=l.id;
        refreshed:=true;
        END IF;
     source_images:=array_remove(string_to_array(coalesce(e.raw_input->>'images',''),'|'),'');
     IF cardinality(source_images) BETWEEN 1 AND 100 AND NOT EXISTS(SELECT 1 FROM unnest(source_images)x WHERE length(x)>4096 OR x !~ '^https?://[^[:space:]]+$') THEN
      PERFORM twuanis_canonical_private.admin_source_media_refresh(l.id,source_images);refreshed:=true;
     END IF;
    END IF;
    IF st.archive_revision IS NOT NULL THEN
     SELECT * INTO l FROM public.listings WHERE id=l.id;
     result:=twuanis_canonical_private.s3_command(l.id,l.canonical_revision,'trusted','service_role',gen_random_uuid(),'{""lifecycle"":{""event"":""publish"",""duration_seconds"":""7776000"",""reason"":""observed again at source""}}',NULL);
  IF result->>'admission' IN ('REVIEW_REQUIRED','AUTOMATIC_REJECTION') THEN INSERT INTO twuanis_canonical_private.source_ingestion_results VALUES(p_evidence,result); RETURN result; END IF;
    END IF;
    UPDATE twuanis_canonical_private.source_ingestion_state SET misses=0,archive_revision=NULL,positive_at=clock_timestamp(),presentation_at=CASE WHEN refreshed THEN clock_timestamp() ELSE presentation_at END WHERE listing_id=l.id;
   END IF;
  END IF;
 END IF;
 INSERT INTO twuanis_canonical_private.source_ingestion_results VALUES(p_evidence,result);
 RETURN result;
END $_$;


--
-- Name: ingest_canonical_source_observation_in_run(uuid, jsonb, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ingest_canonical_source_observation_in_run(p_evidence uuid, p_input jsonb, p_run uuid, p_started_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE e twuanis_canonical_private.csv_source_evidence;old_link twuanis_canonical_private.listing_admission_run_links;completed twuanis_canonical_private.source_run_completions;r jsonb;lid uuid;did uuid;BEGIN
 SELECT * INTO STRICT e FROM twuanis_canonical_private.csv_source_evidence WHERE id=p_evidence;
 IF p_run IS NULL OR p_started_at IS NULL OR NOT isfinite(p_started_at)OR p_started_at>clock_timestamp()OR e.source_observed_at<p_started_at THEN RAISE EXCEPTION 'Actual run identity and applicable start required' USING ERRCODE='22023';END IF;
 PERFORM twuanis_canonical_private.lock_capacity_policy(false);
 PERFORM pg_advisory_xact_lock(3123,hashtext(e.source_name));
 SELECT * INTO old_link FROM twuanis_canonical_private.listing_admission_run_links WHERE evidence_id=p_evidence;
 IF FOUND AND(old_link.source_name,old_link.run_id,old_link.started_at)IS DISTINCT FROM(e.source_name,p_run,p_started_at)THEN RAISE EXCEPTION 'Source evidence already belongs to another run' USING ERRCODE='22023';END IF;
 IF EXISTS(SELECT 1 FROM twuanis_canonical_private.listing_admission_run_links WHERE source_name=e.source_name AND run_id=p_run AND started_at<>p_started_at)THEN RAISE EXCEPTION 'Run start conflict' USING ERRCODE='22023';END IF;
 SELECT * INTO completed FROM twuanis_canonical_private.source_run_completions WHERE source_name=e.source_name AND run_id=p_run;
 IF FOUND AND((completed.payload->>'started_at')::timestamptz<>p_started_at OR NOT(completed.payload->'observed_ids' ? e.source_listing_id))THEN RAISE EXCEPTION 'Completed canonical run evidence conflict' USING ERRCODE='22023';END IF;
 r:=public.ingest_canonical_source_observation(p_evidence,p_input);
 lid:=nullif(r->>'listing_id','')::uuid;
 IF lid IS NULL THEN
  SELECT s.listing_id INTO lid FROM twuanis_canonical_private.source_ingestion_state s WHERE s.source_name=e.source_name AND s.source_listing_id=e.source_listing_id;
  IF lid IS NULL THEN RAISE EXCEPTION 'Canonical source ingestion returned no listing identity' USING ERRCODE='55000'; END IF;
  r:=r||jsonb_build_object('listing_id',lid::text);
 END IF;
 SELECT d.id INTO did FROM twuanis_canonical_private.listing_admission_decisions d WHERE d.listing_id=lid AND d.request_id=p_evidence;
 IF did IS NULL AND r?'caseId' THEN SELECT current_admission_id INTO did FROM twuanis_canonical_private.listing_duplicate_cases WHERE id=(r->>'caseId')::uuid;END IF;
 INSERT INTO twuanis_canonical_private.listing_admission_run_links(evidence_id,source_name,run_id,started_at,listing_id,admission_id)VALUES(p_evidence,e.source_name,p_run,p_started_at,lid,did)ON CONFLICT(evidence_id)DO NOTHING;
 RETURN r||jsonb_build_object('run_id',p_run);
END$$;


--
-- Name: initially_publish_csv_listing(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.initially_publish_csv_listing(p_creation_receipt uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE eligibility twuanis_canonical_private.csv_initial_publication%ROWTYPE; l public.listings%ROWTYPE; r public.canonical_operation_receipts%ROWTYPE; result jsonb; completed boolean;
BEGIN
 PERFORM twuanis_canonical_private.lock_capacity_policy(false);
 SELECT * INTO eligibility FROM twuanis_canonical_private.csv_initial_publication WHERE creation_receipt=p_creation_receipt FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'CSV creation eligibility required' USING ERRCODE='42501'; END IF;
 SELECT * INTO r FROM public.canonical_operation_receipts WHERE id=eligibility.creation_receipt;
 IF NOT FOUND OR r.listing_id IS DISTINCT FROM eligibility.listing_id OR r.operation_type<>'create_trusted'
 OR r.authority_kind<>'trusted' OR r.authority_identity<>'service_role' OR r.result_revision<>1
 OR NOT EXISTS(SELECT 1 FROM public.listing_lifecycle_events WHERE operation_id=r.id AND listing_id=r.listing_id AND event_type='create' AND resulting_state='draft')
 THEN RAISE EXCEPTION 'invalid CSV creation receipt' USING ERRCODE='23514'; END IF;
 SELECT * INTO STRICT l FROM public.listings WHERE id=eligibility.listing_id;
 IF l.owner_id IS NOT NULL OR l.publisher_account_id IS NOT NULL OR l.canonical_domain_version IS DISTINCT FROM 1
 OR l.listing_origin IS DISTINCT FROM 'imported' OR l.source_name IS NULL OR l.source_listing_id IS NULL
 THEN RAISE EXCEPTION 'ownerless canonical CSV import required' USING ERRCODE='42501'; END IF;
 SELECT EXISTS(SELECT 1 FROM public.canonical_operation_receipts WHERE authority_kind='trusted' AND authority_identity='service_role'
 AND operation_type='domain_mutation' AND request_id=eligibility.publication_request AND listing_id=l.id AND outcome='succeeded') INTO completed;
 IF NOT completed AND (l.listing_status IS DISTINCT FROM 'draft' OR EXISTS(
  SELECT 1 FROM public.listing_lifecycle_events WHERE listing_id=l.id AND event_type='publish'))
 THEN RAISE EXCEPTION 'unpublished canonical draft required' USING ERRCODE='55000'; END IF;
 IF NOT completed THEN
  UPDATE twuanis_canonical_private.csv_initial_publication SET publication_expected=l.canonical_revision
  WHERE creation_receipt=p_creation_receipt;
  eligibility.publication_expected:=l.canonical_revision;
 END IF;
 -- Persisted expected revision and fixed operation identity survive successful replay.
 -- A failed command rolls the expectation back with its transaction.
 result:=twuanis_canonical_private.s3_command(l.id,eligibility.publication_expected,'trusted','service_role',eligibility.publication_request,
 '{"lifecycle":{"event":"publish","duration_seconds":"7776000"}}'::jsonb,NULL);
 RETURN result||jsonb_build_object('listing_id',l.id::text);
END $$;


