--
-- Name: ka09_bind_order_outcomes(uuid, bigint, uuid, timestamp with time zone, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ka09_bind_order_outcomes(p_grant uuid, p_revision bigint, p_order uuid, p_origin timestamp with time zone, p_page text, p_locale text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET statement_timeout TO '2s'
    AS $$DECLARE e text;r jsonb:='[]';BEGIN
 FOREACH e IN ARRAY ARRAY['purchase','tw_payment_state','tw_entitlement_state'] LOOP r:=r||jsonb_build_array(public.ka09_outcome_bind(p_grant,p_revision,e,'order',p_order,p_origin,p_page,p_locale));END LOOP;RETURN r;
END$$;


--
-- Name: ka09_consent_grant(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ka09_consent_grant(p_epoch text, p_client text, p_token_digest text, p_notice text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET statement_timeout TO '2s'
    AS $_$DECLARE a uuid;g twuanis_measurement_private.consent_grants%ROWTYPE;n timestamptz:=clock_timestamp();BEGIN
 a:=twuanis_canonical_private.execution_credit_actor();
 IF p_epoch IS NULL OR p_epoch!~'^[a-f0-9]{32}$' OR p_client IS NULL OR p_client!~'^[0-9]{1,20}\.[0-9]{1,20}$' OR p_token_digest IS NULL OR p_token_digest!~'^[a-f0-9]{64}$' OR p_notice IS DISTINCT FROM 'ka09-v1' THEN RAISE EXCEPTION 'explicit bounded consent required' USING ERRCODE='22023';END IF;
 IF NOT pg_try_advisory_xact_lock(9120,hashtext(a::text)) THEN RETURN jsonb_build_object('state','UNAVAILABLE');END IF;
 SELECT * INTO g FROM twuanis_measurement_private.consent_grants WHERE account_id=a AND purpose='analytics_outcomes' AND environment='production' AND epoch=p_epoch FOR UPDATE NOWAIT;
 IF g.id IS NULL THEN
 IF (SELECT count(*) FROM twuanis_measurement_private.consent_grants WHERE account_id=a)>=20 THEN RAISE EXCEPTION 'grant bound';END IF;
 INSERT INTO twuanis_measurement_private.consent_grants(account_id,session_id,notice_version,environment,epoch,client_id,revoke_digest,granted_at,expires_at,purge_at)VALUES(a,(auth.jwt()->>'session_id')::uuid,p_notice,'production',p_epoch,p_client,p_token_digest,n,least(n+interval '24 hours',coalesce((SELECT not_after FROM auth.sessions WHERE id=(auth.jwt()->>'session_id')::uuid),n+interval '24 hours')),n+interval '7 days'-interval '10 minutes') RETURNING * INTO g;
 ELSIF g.revoked_at IS NOT NULL OR g.expires_at<=n OR g.client_id IS DISTINCT FROM p_client OR g.revoke_digest<>p_token_digest THEN RETURN jsonb_build_object('state','SUPPRESSED');END IF;
 RETURN jsonb_build_object('state','GRANTED','id',g.id,'revision',g.revision,'expiresAt',g.expires_at);
END$_$;


--
-- Name: ka09_consent_revoke(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ka09_consent_revoke(p_id uuid, p_token text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET statement_timeout TO '2s'
    AS $_$DECLARE g twuanis_measurement_private.consent_grants%ROWTYPE;inflight boolean;BEGIN
 IF p_token IS NULL OR p_token!~'^[a-f0-9]{64}$' OR p_reason IS NULL OR p_reason NOT IN('withdrawal','logout','account_switch','erasure') THEN RAISE EXCEPTION 'bounded revoke required' USING ERRCODE='22023';END IF;
 SELECT * INTO g FROM twuanis_measurement_private.consent_grants WHERE id=p_id FOR UPDATE;
 IF g.id IS NULL THEN RETURN jsonb_build_object('state','REVOKED');END IF;
 IF g.revoke_digest<>encode(sha256(convert_to(p_token,'UTF8')),'hex') THEN RETURN jsonb_build_object('state','UNAVAILABLE');END IF;
 UPDATE twuanis_measurement_private.consent_grants SET revoked_at=coalesce(revoked_at,clock_timestamp()),revocation_reason=coalesce(revocation_reason,p_reason),revision=CASE WHEN revoked_at IS NULL THEN revision+1 ELSE revision END,client_id=NULL WHERE id=p_id;
 UPDATE twuanis_measurement_private.outcome_claims SET state='SUPPRESSED',reason='revoked',reservation=NULL,reserved_until=NULL WHERE grant_id=p_id AND attempt_count=0;
 SELECT EXISTS(SELECT 1 FROM twuanis_measurement_private.outcome_claims WHERE grant_id=p_id AND attempt_count=1)INTO inflight;
 IF p_reason='erasure' THEN DELETE FROM twuanis_measurement_private.consent_grants WHERE id=p_id;END IF;
 RETURN jsonb_build_object('state','REVOKED','inFlightCannotBeRecalled',inflight);
END$_$;


--
-- Name: ka09_measurement_backlog(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ka09_measurement_backlog() RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET statement_timeout TO '500ms'
    AS $$
 WITH due AS MATERIALIZED(SELECT purge_at FROM twuanis_measurement_private.consent_grants WHERE purge_at<=clock_timestamp() ORDER BY purge_at LIMIT 101), identifiers AS MATERIALIZED(SELECT expires_at FROM twuanis_measurement_private.consent_grants WHERE client_id IS NOT NULL AND expires_at<=clock_timestamp() ORDER BY expires_at LIMIT 101)
 SELECT jsonb_build_object('dueGrantsCapped',least((SELECT count(*)FROM due),100),'dueGrantsOver100',(SELECT count(*)FROM due)>100,'expiredIdentifiersCapped',least((SELECT count(*)FROM identifiers),100),'expiredIdentifiersOver100',(SELECT count(*)FROM identifiers)>100,'oldestOverdueSeconds',coalesce((SELECT greatest(0,extract(epoch FROM clock_timestamp()-min(purge_at)))FROM due),0))
$$;


--
-- Name: ka09_measurement_cleanup(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ka09_measurement_cleanup() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET statement_timeout TO '2s'
    AS $$DECLARE g twuanis_measurement_private.consent_grants%ROWTYPE;n integer:=0;m integer:=0;BEGIN
 SELECT * INTO g FROM twuanis_measurement_private.consent_grants WHERE purge_at<=clock_timestamp() OR(client_id IS NOT NULL AND(expires_at<=clock_timestamp() OR revoked_at IS NOT NULL))ORDER BY purge_at,id LIMIT 1 FOR UPDATE SKIP LOCKED;
 IF g.id IS NULL THEN RETURN jsonb_build_object('claims',0,'grants',0);END IF;
 UPDATE twuanis_measurement_private.consent_grants SET client_id=NULL WHERE id=g.id;
 IF g.purge_at<=clock_timestamp() THEN
 DELETE FROM twuanis_measurement_private.outcome_claims WHERE grant_id=g.id AND purge_at<=clock_timestamp();GET DIAGNOSTICS n=ROW_COUNT;
 IF NOT EXISTS(SELECT 1 FROM twuanis_measurement_private.outcome_claims WHERE grant_id=g.id)THEN DELETE FROM twuanis_measurement_private.consent_grants WHERE id=g.id;GET DIAGNOSTICS m=ROW_COUNT;END IF;END IF;
 RETURN jsonb_build_object('claims',n,'grants',m,'identifiers',CASE WHEN g.client_id IS NOT NULL THEN 1 ELSE 0 END);
END$$;


--
-- Name: ka09_outcome_acknowledge(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ka09_outcome_acknowledge(p_id uuid, p_event_id text, p_receipt text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$BEGIN
 IF p_receipt IS NULL OR p_receipt!~'^[a-zA-Z0-9_-]{1,80}$' THEN RAISE EXCEPTION 'verified opaque receipt required';END IF;
 UPDATE twuanis_measurement_private.outcome_claims SET state='ACKNOWLEDGED',reason='provider_receipt',provider_receipt=p_receipt WHERE id=p_id AND event_id=p_event_id AND attempt_count=1 AND state IN('UNKNOWN','ATTEMPTED');
END$_$;


--
-- Name: ka09_outcome_begin(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ka09_outcome_begin(p_id uuid, p_account uuid, p_reservation uuid, p_authority_digest text, p_payload_digest text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET statement_timeout TO '2s'
    AS $_$DECLARE g twuanis_measurement_private.consent_grants%ROWTYPE;c twuanis_measurement_private.outcome_claims%ROWTYPE;r jsonb;n timestamptz:=clock_timestamp();BEGIN
 SELECT g0.* INTO g FROM twuanis_measurement_private.consent_grants g0 JOIN twuanis_measurement_private.outcome_claims c0 ON c0.grant_id=g0.id WHERE c0.id=p_id FOR UPDATE OF g0;
 SELECT * INTO c FROM twuanis_measurement_private.outcome_claims WHERE id=p_id FOR UPDATE;n:=clock_timestamp();
 IF g.id IS NULL OR g.account_id IS DISTINCT FROM p_account OR c.state IS DISTINCT FROM 'CLAIMED' OR c.reservation IS DISTINCT FROM p_reservation OR c.attempt_count<>0 OR c.reserved_until<=n OR p_payload_digest IS NULL OR p_payload_digest!~'^[a-f0-9]{64}$' THEN RETURN jsonb_build_object('state','SUPPRESSED');END IF;
 IF NOT EXISTS(SELECT 1 FROM auth.users u JOIN twuanis_canonical_private.account_principals ap ON ap.id=u.id WHERE u.id=g.account_id AND ap.deleted_at IS NULL AND u.email_confirmed_at IS NOT NULL AND(u.banned_until IS NULL OR u.banned_until<=n)) OR NOT EXISTS(SELECT 1 FROM auth.sessions ss WHERE ss.id=g.session_id AND ss.user_id=g.account_id AND(ss.not_after IS NULL OR ss.not_after>n)) OR g.revoked_at IS NOT NULL OR g.revision<>c.grant_revision OR g.client_id IS NULL OR n>=g.expires_at OR n>=c.expires_at THEN UPDATE twuanis_measurement_private.consent_grants SET client_id=NULL WHERE id=g.id;UPDATE twuanis_measurement_private.outcome_claims SET state='SUPPRESSED',reason='revoked'WHERE id=c.id;RETURN jsonb_build_object('state','SUPPRESSED');END IF;
 r:=twuanis_measurement_private.authority(c.event_name,c.subject_id,p_account);
 IF r IS NULL OR encode(sha256(convert_to(r::text,'UTF8')),'hex') IS DISTINCT FROM p_authority_digest OR (r->>'outcome_at')::timestamptz<=c.bound_at OR n>=(r->>'outcome_at')::timestamptz+interval '72 hours' THEN UPDATE twuanis_measurement_private.outcome_claims SET state='SUPPRESSED',reason='authority'WHERE id=c.id;RETURN jsonb_build_object('state','SUPPRESSED');END IF;
 UPDATE twuanis_measurement_private.outcome_claims SET state='ATTEMPTED',attempt_count=1,attempt_at=n,payload_digest=p_payload_digest WHERE id=c.id;
 RETURN jsonb_build_object('state','ATTEMPTED','id',c.id,'eventId',c.event_id);
END$_$;


--
-- Name: ka09_outcome_bind(uuid, bigint, text, text, uuid, timestamp with time zone, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ka09_outcome_bind(p_grant uuid, p_revision bigint, p_event text, p_kind text, p_subject uuid, p_origin timestamp with time zone, p_page text, p_locale text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET statement_timeout TO '2s'
    AS $_$DECLARE a uuid;g twuanis_measurement_private.consent_grants%ROWTYPE;c twuanis_measurement_private.outcome_claims%ROWTYPE;t timestamptz;n timestamptz:=clock_timestamp();BEGIN
 a:=twuanis_canonical_private.execution_credit_actor();SELECT * INTO g FROM twuanis_measurement_private.consent_grants WHERE id=p_grant AND account_id=a AND session_id=(auth.jwt()->>'session_id')::uuid FOR UPDATE NOWAIT;n:=clock_timestamp();
 IF g.id IS NULL OR g.revoked_at IS NOT NULL OR g.revision IS DISTINCT FROM p_revision OR n>=g.expires_at OR g.client_id IS NULL THEN RETURN jsonb_build_object('state','SUPPRESSED');END IF;
 IF p_event IS NULL OR p_kind IS NULL OR (p_kind='order') IS DISTINCT FROM (p_event IN('purchase','tw_payment_state','tw_entitlement_state')) OR p_event NOT IN('purchase','tw_payment_state','tw_entitlement_state','tw_execution_result','tw_report_ready') OR p_kind NOT IN('order','execution') OR p_origin IS NULL OR p_origin>n OR p_origin<n-interval '10 minutes' OR p_origin<g.granted_at OR p_page IS NULL OR p_page!~'^[a-f0-9]{32}$' OR p_locale IS NULL OR p_locale NOT IN('en','es') THEN RETURN jsonb_build_object('state','SUPPRESSED');END IF;
 t:=twuanis_measurement_private.subject(p_kind,p_subject,a);
 IF t IS NULL THEN RETURN jsonb_build_object('state','SUPPRESSED');END IF;
 SELECT * INTO c FROM twuanis_measurement_private.outcome_claims WHERE environment='production' AND destination='G-XPKD8XE7FD' AND event_name=p_event AND subject_id=p_subject;
 IF c.id IS NOT NULL THEN IF c.grant_id<>g.id THEN RETURN jsonb_build_object('state','SUPPRESSED');END IF;RETURN jsonb_build_object('state','EXISTING','id',c.id);END IF;
 IF t IS NULL OR t<g.granted_at OR t<p_origin OR t>n OR twuanis_measurement_private.authority(p_event,p_subject,a) IS NOT NULL THEN RETURN jsonb_build_object('state','SUPPRESSED');END IF;
 IF (SELECT count(*) FROM twuanis_measurement_private.outcome_claims WHERE grant_id=g.id)>=40 THEN RAISE EXCEPTION 'claim bound';END IF;
 INSERT INTO twuanis_measurement_private.outcome_claims(grant_id,grant_revision,event_name,subject_kind,subject_id,environment,event_id,origin_at,page_instance,locale,bound_at,expires_at,purge_at)
 VALUES(g.id,g.revision,p_event,p_kind,p_subject,'production','e'||encode(sha256(convert_to('production:G-XPKD8XE7FD:'||p_event||':'||p_subject::text,'UTF8')),'hex'),p_origin,p_page,p_locale,n,least(g.expires_at,n+interval '72 hours'),least(g.purge_at,n+interval '7 days'-interval '10 minutes')) ON CONFLICT(environment,destination,event_name,subject_id) DO NOTHING RETURNING * INTO c;
 IF c.id IS NULL THEN SELECT * INTO c FROM twuanis_measurement_private.outcome_claims WHERE environment='production' AND destination='G-XPKD8XE7FD' AND event_name=p_event AND subject_id=p_subject;END IF;
 RETURN jsonb_build_object('state',c.state,'id',c.id);
END$_$;


--
-- Name: ka09_outcome_finish(uuid, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ka09_outcome_finish(p_id uuid, p_reservation uuid, p_result text, p_http integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET statement_timeout TO '2s'
    AS $$DECLARE c twuanis_measurement_private.outcome_claims%ROWTYPE;BEGIN
 SELECT * INTO c FROM twuanis_measurement_private.outcome_claims WHERE id=p_id FOR UPDATE;
 IF c.id IS NULL OR c.reservation IS DISTINCT FROM p_reservation OR c.state NOT IN('ATTEMPTED','UNKNOWN') OR c.attempt_count<>1 THEN RETURN jsonb_build_object('state','NO_CHANGE');END IF;
 IF p_result IS NULL OR p_result NOT IN('http_accepted','rejected','timeout','interrupted') OR(p_http IS NOT NULL AND p_http NOT BETWEEN 100 AND 599) OR(p_result='http_accepted' AND(p_http IS NULL OR p_http NOT BETWEEN 200 AND 299)) THEN RAISE EXCEPTION 'bounded transport evidence';END IF;
 -- GA4 HTTP 2xx is not processing acknowledgement: retain UNKNOWN.
 UPDATE twuanis_measurement_private.outcome_claims SET state=CASE WHEN p_result='rejected' THEN 'FAILED' ELSE 'UNKNOWN' END,reason=p_result,http_status=p_http,finished_at=clock_timestamp() WHERE id=p_id;
 RETURN jsonb_build_object('state',CASE WHEN p_result='rejected' THEN 'FAILED' ELSE 'UNKNOWN' END);
END$$;


--
-- Name: ka09_outcome_prepare(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ka09_outcome_prepare(p_id uuid, p_account uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET statement_timeout TO '2s'
    AS $$DECLARE g twuanis_measurement_private.consent_grants%ROWTYPE;c twuanis_measurement_private.outcome_claims%ROWTYPE;r jsonb;n timestamptz:=clock_timestamp();BEGIN
 SELECT g0.* INTO g FROM twuanis_measurement_private.consent_grants g0 JOIN twuanis_measurement_private.outcome_claims c0 ON c0.grant_id=g0.id WHERE c0.id=p_id FOR UPDATE OF g0;
 SELECT * INTO c FROM twuanis_measurement_private.outcome_claims WHERE id=p_id FOR UPDATE;n:=clock_timestamp();
 IF g.id IS NULL OR g.account_id IS DISTINCT FROM p_account THEN RETURN jsonb_build_object('state','SUPPRESSED');END IF;
 IF c.attempt_count=1 THEN
 IF c.state IN('ATTEMPTED','CLAIMED') THEN UPDATE twuanis_measurement_private.outcome_claims SET state='UNKNOWN',reason='interrupted' WHERE id=c.id;END IF;
 RETURN jsonb_build_object('state','NO_RETRY');END IF;
 IF NOT EXISTS(SELECT 1 FROM auth.users u JOIN twuanis_canonical_private.account_principals ap ON ap.id=u.id WHERE u.id=g.account_id AND ap.deleted_at IS NULL AND u.email_confirmed_at IS NOT NULL AND(u.banned_until IS NULL OR u.banned_until<=n)) OR NOT EXISTS(SELECT 1 FROM auth.sessions ss WHERE ss.id=g.session_id AND ss.user_id=g.account_id AND(ss.not_after IS NULL OR ss.not_after>n)) OR g.revoked_at IS NOT NULL OR g.revision<>c.grant_revision OR g.client_id IS NULL OR n>=g.expires_at OR n>=c.expires_at OR c.state='SUPPRESSED' THEN
 UPDATE twuanis_measurement_private.consent_grants SET client_id=NULL WHERE id=g.id;
 UPDATE twuanis_measurement_private.outcome_claims SET state='SUPPRESSED',reason=CASE WHEN g.revoked_at IS NOT NULL THEN 'revoked' ELSE 'expired' END WHERE id=c.id;RETURN jsonb_build_object('state','SUPPRESSED');END IF;
 IF c.state='CLAIMED' AND c.reserved_until>n THEN RETURN jsonb_build_object('state','BUSY');END IF;
 IF c.reservation_count>=2 THEN UPDATE twuanis_measurement_private.outcome_claims SET state='SUPPRESSED',reason='interrupted'WHERE id=c.id;RETURN jsonb_build_object('state','SUPPRESSED');END IF;
 r:=twuanis_measurement_private.authority(c.event_name,c.subject_id,p_account);
 IF r IS NULL THEN RETURN jsonb_build_object('state','PENDING');END IF;
 IF (r->>'outcome_at')::timestamptz<=c.bound_at OR (r->>'outcome_at')::timestamptz>n OR n>=(r->>'outcome_at')::timestamptz+interval '72 hours' THEN UPDATE twuanis_measurement_private.outcome_claims SET state='SUPPRESSED',reason='authority'WHERE id=c.id;RETURN jsonb_build_object('state','SUPPRESSED');END IF;
 UPDATE twuanis_measurement_private.outcome_claims SET state='ELIGIBLE',receipt_ref=r->>'receipt_ref',outcome_at=(r->>'outcome_at')::timestamptz WHERE id=c.id;
 RETURN jsonb_build_object('state','ELIGIBLE','id',c.id,'grantRevision',g.revision,'epoch',g.epoch,'page',c.page_instance,'locale',c.locale,'environment',c.environment,'event',c.event_name,'eventId',c.event_id,'subject',c.subject_id,'clientId',g.client_id,'authority',r,'authorityDigest',encode(sha256(convert_to(r::text,'UTF8')),'hex'));
END$$;


--
-- Name: ka09_outcome_reserve(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ka09_outcome_reserve(p_id uuid, p_account uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET statement_timeout TO '2s'
    AS $$DECLARE r jsonb;token uuid:=gen_random_uuid();BEGIN
 r:=public.ka09_outcome_prepare(p_id,p_account);IF r->>'state'<>'ELIGIBLE' THEN RETURN r;END IF;
 UPDATE twuanis_measurement_private.outcome_claims SET state='CLAIMED',reservation=token,reserved_until=clock_timestamp()+interval '30 seconds',reservation_count=reservation_count+1 WHERE id=p_id;
 RETURN r||jsonb_build_object('state','CLAIMED','reservation',token);
END$$;


--
-- Name: ka09_pending_outcomes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ka09_pending_outcomes() RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET statement_timeout TO '500ms'
    AS $$
 WITH candidates AS MATERIALIZED(SELECT c.id,c.event_name,c.subject_id,c.bound_at,g.account_id FROM twuanis_measurement_private.outcome_claims c JOIN twuanis_measurement_private.consent_grants g ON g.id=c.grant_id WHERE c.attempt_count=0 AND c.state IN('PENDING','ELIGIBLE','CLAIMED') AND(c.reserved_until IS NULL OR c.reserved_until<=clock_timestamp()) AND c.expires_at>clock_timestamp() AND g.expires_at>clock_timestamp() AND g.revoked_at IS NULL AND g.client_id IS NOT NULL ORDER BY c.bound_at DESC,c.id LIMIT 32)
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'account',account_id)),'[]'::jsonb)FROM(SELECT * FROM candidates WHERE twuanis_measurement_private.authority(event_name,subject_id,account_id) IS NOT NULL ORDER BY bound_at,id LIMIT 3)x
$$;


--
-- Name: ka10_ga4_session(uuid, bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ka10_ga4_session(p_grant uuid, p_revision bigint, p_session bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF p_session IS NULL OR p_session<=0 OR p_session>9007199254740991 THEN RETURN '{"state":"INVALID"}';END IF;
 UPDATE twuanis_measurement_private.consent_grants SET ga_session_id=p_session,ga_session_observed_at=coalesce(ga_session_observed_at,clock_timestamp()) WHERE id=p_grant AND account_id=auth.uid() AND account_id<>'d81064bc-1b4a-478f-8f6a-b263c4779bc1' AND session_id=nullif(auth.jwt()->>'session_id','')::uuid AND revision=p_revision AND revoked_at IS NULL AND expires_at>clock_timestamp() AND(ga_session_id IS NULL OR ga_session_id=p_session);
 RETURN jsonb_build_object('state',CASE WHEN FOUND THEN 'BOUND' ELSE 'SUPPRESSED' END);
END $$;


--
-- Name: ka10_ga4_stage_finish(text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ka10_ga4_stage_finish(p_journey text, p_event text, p_status integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 UPDATE twuanis_measurement_private.journey_ga4_stages_r4 SET state=CASE WHEN p_status BETWEEN 200 AND 299 THEN 'HTTP_ACCEPTED' WHEN p_status IS NULL THEN 'UNKNOWN' ELSE 'REJECTED' END,http_status=p_status,finished_at=clock_timestamp() WHERE journey=p_journey AND event_id=p_event AND state='ATTEMPTED';
 RETURN jsonb_build_object('state',CASE WHEN FOUND THEN 'RECORDED' ELSE 'UNCHANGED' END,'reportingAppearance','NOT_VERIFIED');
END $$;


--
-- Name: ka10_ga4_stage_reserve(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ka10_ga4_stage_reserve() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET statement_timeout TO '1s'
    AS $$
DECLARE r record;rows jsonb:='[]';
BEGIN
 PERFORM pg_advisory_xact_lock(7463103001);
 UPDATE twuanis_measurement_private.journey_ga4_stages_r4 SET state='UNKNOWN',finished_at=clock_timestamp() WHERE (journey,event_id) IN(SELECT journey,event_id FROM twuanis_measurement_private.journey_ga4_stages_r4 WHERE state='ATTEMPTED' AND attempted_at<clock_timestamp()-interval '1 minute' ORDER BY attempted_at LIMIT 20);
 FOR r IN SELECT e.*,g.id grant_id,g.client_id,CASE WHEN g.ga_session_observed_at BETWEEN o.created_at-interval '30 minutes' AND o.created_at+interval '1 minute' THEN g.ga_session_id END AS ga_session_id,g.epoch,g.environment,g.account_id,j.notice,o.product_id FROM twuanis_measurement_private.journey_events_r3 e JOIN twuanis_measurement_private.journeys_r3 j ON j.id=e.journey JOIN twuanis_canonical_private.offer_order_snapshots o ON o.id::text=e.envelope->>'order' AND o.account_id=j.account_id
 JOIN LATERAL(SELECT * FROM twuanis_measurement_private.consent_grants g WHERE g.account_id=j.account_id AND g.session_id=j.auth_session AND g.revoked_at IS NULL AND g.expires_at>clock_timestamp() AND g.granted_at<=e.observed_at AND g.client_id IS NOT NULL ORDER BY g.granted_at DESC LIMIT 1) g ON true
 WHERE e.authority='canonical' AND e.envelope->>'name' IN('tw_order_created','tw_payment_observed','tw_fulfillment','tw_access_active') AND j.ended_at IS NULL AND NOT j.suppressed AND j.expires_at>clock_timestamp() AND j.last_at+interval '30 minutes'>clock_timestamp() AND j.history_until>clock_timestamp() AND j.notice=public.ka10_journey_policy()->>'notice' AND j.account_id<>'d81064bc-1b4a-478f-8f6a-b263c4779bc1'
 AND EXISTS(SELECT 1 FROM auth.sessions s WHERE s.id=j.auth_session AND s.user_id=j.account_id AND(s.not_after IS NULL OR s.not_after>clock_timestamp()))
 AND NOT EXISTS(SELECT 1 FROM twuanis_measurement_private.journey_erasure_r3 er WHERE er.account_id=j.account_id)
 AND e.observed_at>clock_timestamp()-interval '72 hours' AND NOT EXISTS(SELECT 1 FROM twuanis_measurement_private.journey_ga4_stages_r4 c WHERE c.journey=e.journey AND c.event_id=e.id)
 ORDER BY e.observed_at,e.received_seq LIMIT 3 FOR UPDATE OF j SKIP LOCKED LOOP
 INSERT INTO twuanis_measurement_private.journey_ga4_stages_r4(journey,event_id,grant_id) VALUES(r.journey,r.id,r.grant_id) ON CONFLICT DO NOTHING;
 IF FOUND THEN rows:=rows||jsonb_build_array(jsonb_build_object('journey',r.journey,'eventId',r.id,'clientId',r.client_id,'epoch',r.epoch,'environment',r.environment,'gaSessionId',r.ga_session_id,'locale',coalesce(r.envelope->>'locale','en'),'observedAt',r.observed_at,'name',r.envelope->>'name','outcome',r.envelope->>'outcome','order',r.envelope->>'order','term',r.envelope->>'term','product',r.product_id));END IF;
 END LOOP;
 RETURN rows;
END $$;


--
-- Name: ka10_journey_business(date, date, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ka10_journey_business(p_from date, p_until date, p_after text, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET statement_timeout TO '2s'
    AS $$
DECLARE result jsonb;
BEGIN
 IF p_from IS NULL OR p_until IS NULL OR p_until<=p_from OR p_until-p_from>366 OR p_limit NOT BETWEEN 1 AND 200 OR p_limit IS NULL OR length(p_after)>2000 THEN RETURN '{"state":"INVALID"}';END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') INTO result FROM(SELECT bucket_day,cohort_day,projection,dimensions,event_count,scope_occurrences,scope_starts,revenue,status,bucket_day::text||'|'||cohort_day::text||'|'||projection||'|'||dimensions::text cursor FROM twuanis_measurement_private.journey_business_r4 WHERE bucket_day>=p_from AND bucket_day<p_until AND (p_after IS NULL OR bucket_day::text||'|'||cohort_day::text||'|'||projection||'|'||dimensions::text>p_after) ORDER BY bucket_day,cohort_day,projection,dimensions::text LIMIT p_limit)x;
 RETURN jsonb_build_object('state','READ','rows',result,'definitions','scope_occurrences are scope-days/cells, not unique people; do not add projections; revenue is gross verified collections in original currency; withheld is unavailable, not zero');
END $$;


--
-- Name: ka10_journey_end(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ka10_journey_end(p_journey text, p_token_digest text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN PERFORM pg_advisory_xact_lock(7463103001);UPDATE twuanis_measurement_private.journeys_r3 SET suppressed=suppressed OR p_reason IN('owner','withdrawal') OR coalesce(auth.uid()='d81064bc-1b4a-478f-8f6a-b263c4779bc1'::uuid,false),ended_at=coalesce(ended_at,clock_timestamp()),end_reason=coalesce(end_reason,p_reason) WHERE id=p_journey AND proof=p_token_digest AND p_reason IN('owner','withdrawal','logout','switch','expiry');IF p_reason='withdrawal' THEN DELETE FROM twuanis_measurement_private.journeys_r3 WHERE id=p_journey AND proof=p_token_digest;END IF;RETURN '{"state":"ENDED"}';END $$;


--
-- Name: ka10_journey_erase_account(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ka10_journey_erase_account(p_account uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET statement_timeout TO '2s'
    AS $$
DECLARE purged integer;
BEGIN
 IF p_account IS NULL THEN RETURN '{"state":"INVALID"}';END IF;
 PERFORM pg_advisory_xact_lock(7463103001);
 INSERT INTO twuanis_measurement_private.journey_erasure_r3(account_id,retain_until) VALUES(p_account,clock_timestamp()+make_interval(days=>coalesce((SELECT suppression_days FROM twuanis_measurement_private.journey_policy_r3 WHERE singleton),0))) ON CONFLICT DO NOTHING;
 UPDATE twuanis_measurement_private.consent_grants SET revoked_at=coalesce(revoked_at,clock_timestamp()),revocation_reason=coalesce(revocation_reason,'erasure'),client_id=NULL,ga_session_id=NULL,ga_session_observed_at=NULL WHERE id IN(SELECT id FROM twuanis_measurement_private.consent_grants WHERE account_id=p_account AND (revoked_at IS NULL OR client_id IS NOT NULL OR ga_session_id IS NOT NULL) LIMIT 100);
 DELETE FROM twuanis_measurement_private.journeys_r3 WHERE id IN(SELECT id FROM ((SELECT id FROM twuanis_measurement_private.journeys_r3 WHERE account_id=p_account LIMIT 100) UNION(SELECT journey FROM twuanis_measurement_private.journey_orders_r3 WHERE account_id=p_account LIMIT 100) UNION(SELECT e.journey FROM twuanis_measurement_private.journey_events_r3 e JOIN twuanis_canonical_private.offer_order_snapshots o ON o.id::text=e.envelope->>'order' WHERE o.account_id=p_account AND e.authority='canonical' LIMIT 100)) owned LIMIT 100);GET DIAGNOSTICS purged=ROW_COUNT;
 RETURN jsonb_build_object('state','SUPPRESSED','purged',purged,'remaining',EXISTS(SELECT 1 FROM twuanis_measurement_private.consent_grants WHERE account_id=p_account AND(revoked_at IS NULL OR client_id IS NOT NULL OR ga_session_id IS NOT NULL)) OR EXISTS(SELECT 1 FROM twuanis_measurement_private.journeys_r3 WHERE account_id=p_account) OR EXISTS(SELECT 1 FROM twuanis_measurement_private.journey_orders_r3 WHERE account_id=p_account) OR EXISTS(SELECT 1 FROM twuanis_measurement_private.journey_events_r3 e JOIN twuanis_canonical_private.offer_order_snapshots o ON o.id::text=e.envelope->>'order' WHERE o.account_id=p_account AND e.authority='canonical'));
END $$;


--
-- Name: ka10_journey_history(timestamp with time zone, timestamp with time zone, timestamp with time zone, bigint, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ka10_journey_history(p_from timestamp with time zone, p_until timestamp with time zone, p_after timestamp with time zone, p_after_seq bigint, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET statement_timeout TO '2000ms'
    AS $$
DECLARE result jsonb;
BEGIN
 IF p_from IS NULL OR p_until IS NULL OR p_until<=p_from OR p_until-p_from>interval '31 days' OR p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 200 OR (p_after IS NULL)<>(p_after_seq IS NULL) OR p_after IS NOT NULL AND (p_after<p_from OR p_after>=p_until OR p_after_seq<0) THEN RETURN '{"state":"INVALID"}';END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.observed_at,x.received_seq),'[]') INTO result FROM(SELECT journey,id,client_seq,received_seq,observed_at,received_at,envelope,authority,account_id,linked_at,ended_at,end_reason FROM twuanis_measurement_private.journey_reporting_r3 e WHERE e.retention_until>clock_timestamp() AND observed_at>=p_from AND observed_at<p_until AND (p_after IS NULL OR (observed_at,received_seq)>(p_after,p_after_seq)) ORDER BY observed_at,received_seq LIMIT p_limit) x;
 RETURN jsonb_build_object('state','READ','rows',result,'limit',p_limit);
END $$;


--
-- Name: ka10_journey_ingest(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ka10_journey_ingest(p_journey text, p_token_digest text, p_events jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET statement_timeout TO '1000ms'
    AS $_$
DECLARE admission text;j twuanis_measurement_private.journeys_r3%ROWTYPE;a uuid:=auth.uid();s uuid:=nullif(auth.jwt()->>'session_id','')::uuid;e jsonb;pair record;num integer:=0;n timestamptz:=clock_timestamp();inserted integer;fresh integer;
BEGIN
 IF p_journey !~ '^[a-f0-9]{32}$' OR p_token_digest !~ '^[a-f0-9]{64}$' OR p_journey IS NULL OR p_token_digest IS NULL OR jsonb_typeof(p_events)<>'array' OR jsonb_array_length(p_events)>20 OR octet_length(p_events::text)>20000 THEN RETURN '{"state":"INVALID"}';END IF;
 PERFORM pg_advisory_xact_lock(7463103001);
 IF a='d81064bc-1b4a-478f-8f6a-b263c4779bc1'::uuid THEN
 UPDATE twuanis_measurement_private.journeys_r3 SET suppressed=true,ended_at=n,end_reason='owner' WHERE id=p_journey AND proof=p_token_digest;RETURN '{"state":"SUPPRESSED"}';END IF;
 IF a IS NOT NULL AND (s IS NULL OR NOT EXISTS(SELECT 1 FROM auth.sessions WHERE id=s AND user_id=a AND (not_after IS NULL OR not_after>n))) THEN RETURN '{"state":"SUPPRESSED"}';END IF;
 -- Serialize short-window admission; history size is not a lifetime event quota.
 PERFORM pg_advisory_xact_lock(7463103001);
 SELECT * INTO j FROM twuanis_measurement_private.journeys_r3 WHERE id=p_journey FOR UPDATE;
 IF NOT FOUND THEN RETURN '{"state":"MISSING_CONSENT"}';END IF;
 IF j.notice IS DISTINCT FROM public.ka10_journey_policy()->>'notice' OR j.proof<>p_token_digest OR j.ended_at IS NOT NULL OR j.suppressed OR j.expires_at<=n OR j.last_at<n-interval '30 minutes' OR (j.account_id IS NOT NULL AND (j.account_id IS DISTINCT FROM a OR j.auth_session IS DISTINCT FROM s)) THEN RETURN '{"state":"SUPPRESSED"}';END IF;
 IF EXISTS(SELECT 1 FROM twuanis_measurement_private.journey_erasure_r3 WHERE account_id=a OR account_id=j.account_id) THEN RETURN '{"state":"SUPPRESSED"}';END IF;
 SELECT count(*) INTO fresh FROM jsonb_array_elements(p_events) item(value) WHERE NOT EXISTS(SELECT 1 FROM twuanis_measurement_private.journey_events_r3 old WHERE old.journey=j.id AND old.id=item.value->>'id');
 IF j.received+fresh>1500 THEN RETURN '{"state":"SESSION_LIMIT"}';END IF;
 admission:=twuanis_measurement_private.journey_admit_r3(0,fresh);IF admission<>'ADMITTED' THEN RETURN jsonb_build_object('state',admission);END IF;
 IF j.account_id IS NULL AND a IS NOT NULL THEN UPDATE twuanis_measurement_private.journeys_r3 SET account_id=a,auth_session=s,linked_at=n,identity_until=n+make_interval(days=>(public.ka10_journey_policy()->>'identityDays')::integer) WHERE id=j.id;END IF;
 FOR e IN SELECT value FROM jsonb_array_elements(p_events) LOOP
 IF jsonb_typeof(e)<>'object' OR (SELECT count(*) FROM jsonb_object_keys(e))<>17 OR NOT(e ?& ARRAY['id','seq','at','page','locale','name','control','operation','outcome','campaign','content','source','medium','landing','lost','subject','evidence']) OR e->>'id' !~ '^e[a-f0-9]{32}$' OR e->>'seq' !~ '^[0-9]{1,6}$' OR (e->>'seq')::bigint NOT BETWEEN 1 AND 100000 OR e->>'at' !~ '^[0-9]{13}$' OR e->>'locale' NOT IN('en','es') OR e->>'name' NOT IN('page_view','tw_navigation','tw_search_commit','tw_search_part','tw_search_result','tw_search_exit','tw_listing_exposure','tw_listing_view','tw_listing_image','tw_listing_section','tw_save_intent','tw_save_change','tw_share','tw_contact_start','tw_knowledge_view','tw_knowledge_search','tw_knowledge_select','tw_knowledge_engage','tw_package_view','tw_package_select','tw_analytics_select','tw_config_commit','tw_product_action','tw_report_view','tw_report_retrieve','tw_analysis_save','tw_authorization','tw_execution_result','begin_checkout','login') OR (e->>'control' NOT IN('server_response_tw_authorization','server_response_tw_execution_result','server_response_tw_report_retrieve','server_response_begin_checkout','bank_report_restore','analysis_delete','analysis_duplicate','analysis_rename','analysis_save','analysis_update','bank_import_prepare','bank_draft_save','bank_import_apply','bank_property_save','bank_property_remove','bank_search_create','bank_search_update','bank_search_remove','bank_alerts_configure','checkout_purchase','compare_delete','compare_save','compare_selection','compare_update','listing_import_prepare','listing_import_publish','listing_publish_or_renew','note_create','note_delete','note_update','payment_status_check','payment_status_response','saved_search_alert','saved_search_create','saved_search_delete','saved_search_rename','seller_whatsapp','homepage_background','spotlight_property','feature_listing','listing_photo_select','listing_permanent_delete','listing_duplicate','listing_media_update','account_profile_update','account_language_update','listing_prepare','listing_create','listing_update','listing_publish','listing_unpublish','listing_archive','listing_delete','listing_restore','listing_renew','profile_update','workspace_claims','workspace_overview','workspace_listings','workspace_knowledge','workspace_intelligence','workspace_commercial','workspace_notifications','workspace_settings','workspace_remates','population_sale','population_rent','population_bank','navigate_home','navigate_packages','navigate_intelligence','navigate_listing_detail','navigate_bank_discovery','navigate_sale_discovery','navigate_rent_discovery','navigate_favorites','navigate_workspace','navigate_knowledge','navigate_other_product') AND e->>'control'<>e->>'name' AND e->>'control' !~ '^(capability_navigation|example_open|view_package|locked_card_packages)_(sale|rent|bank|unknown)_(summary|composition|market_asking_price_distribution|matching|comparison|configuration|distribution|geography|size|construction_land|cohort_comparison|cross_dimensional|discovery|position|comparables|asking_area_ratio|weighted_price)$') OR e->>'page' !~ '^(/protected|/checkout|/(payments|commercial)/:id|/(en|es)(/(buy|comprar|rent-lease|alquilar-arrendar|bank-properties|remates|market-intelligence|inteligencia-de-mercado|knowledge|conocimiento|favorites|favoritos|sell|vender|publicar-alquiler-arrendamiento)(/(listing|anuncio)/:id|/packages|/paquetes)?)?)$' OR e->>'page' ~ '[a-f0-9]{8}-[a-f0-9-]{27}' OR e->>'operation' NOT IN('navigation','homepage','workspace','population','compare','saved_search','listing_manage','account','payment_status','checkout','order','execution','report','favorite','contact','share','package','example','discovery') OR e->>'outcome' NOT IN('intent','acknowledged','denied','failed','pending','verified','fulfilled','scheduled','active','reversed','unavailable') OR e->>'lost' !~ '^[0-9]{1,6}$' THEN RAISE EXCEPTION 'Invalid bounded journey envelope' USING ERRCODE='22023';END IF;
 IF jsonb_typeof(e->'evidence') IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(e->'evidence'))>24 THEN RAISE EXCEPTION 'Invalid bounded evidence' USING ERRCODE='22023';END IF;
 FOR pair IN SELECT key,value FROM jsonb_each(e->'evidence') LOOP
 IF pair.key NOT IN('event_id','page_instance','consent_epoch','logical_id','query_id','context_digest','state_digest','cfg','reason','transaction','count_kind','listing_market','surface','source_coverage','expected_state_scopes','count','displayed_count','result_count','package_id','duration_kind','market_variant','selection_kind','f00','f01','f02','f03','f04','f05','f06','f07','f08','f09','f10','f11','f12','f13','f14','f15','f16','f17') OR NOT(jsonb_typeof(pair.value)='string' AND pair.value#>>'{}' ~ '^[A-Za-z0-9._-]{1,100}$' OR jsonb_typeof(pair.value)='number' AND pair.value::text ~ '^[0-9]{1,8}$' AND (pair.value::text)::numeric<=10000000) THEN RAISE EXCEPTION 'Invalid evidence code' USING ERRCODE='22023';END IF;
 END LOOP;
 IF e->>'subject' IS NOT NULL AND e->>'subject' !~ '^([a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}|[mq]?[a-f0-9]{32,64}|summary|composition|market-asking-price-distribution|matching|comparison|configuration|distribution|geography|size|construction-land|cohort-comparison|cross-dimensional|discovery|position|comparables|asking-area-ratio|weighted-price|pkg-market-distribution|pkg-matching-market-comparison|pkg-pricing-position-relationships)$' THEN RAISE EXCEPTION 'Invalid subject reference' USING ERRCODE='22023';END IF;
 IF e->>'campaign' IS NOT NULL AND (e->>'campaign'<>'twuanis_launch_20261030' OR e->>'source' IS DISTINCT FROM 'twuanis' OR e->>'medium' IS DISTINCT FROM 'email' OR e->>'content' NOT IN('home','properties','intelligence','packages','footer')) THEN RAISE EXCEPTION 'Invalid bounded journey envelope' USING ERRCODE='22023';END IF;
 IF e->>'campaign' IS NULL AND (e->>'source' IS NOT NULL OR e->>'medium' IS NOT NULL OR e->>'content' IS NOT NULL) THEN RAISE EXCEPTION 'Invalid bounded journey envelope' USING ERRCODE='22023';END IF;
 IF e->>'landing' IS NOT NULL AND e->>'landing' !~ '^/(en|es)(/[a-z0-9/-]{0,120})?$' THEN RAISE EXCEPTION 'Invalid bounded journey envelope' USING ERRCODE='22023';END IF;
 IF to_timestamp((e->>'at')::double precision/1000)>n+interval '30 seconds' OR to_timestamp((e->>'at')::double precision/1000)<j.created_at-interval '24 hours' THEN RAISE EXCEPTION 'Invalid bounded journey envelope' USING ERRCODE='22023';END IF;
 IF EXISTS(SELECT 1 FROM twuanis_measurement_private.journey_events_r3 WHERE journey=j.id AND ((id=e->>'id' AND envelope<>e) OR (client_seq=(e->>'seq')::bigint AND id<>e->>'id'))) THEN RAISE EXCEPTION 'Conflicting event identity' USING ERRCODE='22023';END IF;
 INSERT INTO twuanis_measurement_private.journey_events_r3(journey,id,client_seq,observed_at,envelope,authority) VALUES(j.id,e->>'id',(e->>'seq')::bigint,to_timestamp((e->>'at')::double precision/1000),e,'client_observed') ON CONFLICT DO NOTHING;
 GET DIAGNOSTICS inserted=ROW_COUNT;num:=num+inserted;
 END LOOP;
 UPDATE twuanis_measurement_private.journeys_r3 SET last_at=n,received=received+num WHERE id=j.id;
 RETURN jsonb_build_object('state','STORED','inserted',num);
EXCEPTION WHEN disk_full OR out_of_memory OR configuration_limit_exceeded OR read_only_sql_transaction THEN RETURN '{"state":"CAPACITY","reason":"storage_or_compute"}';
END $_$;


--
-- Name: ka10_journey_maintenance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ka10_journey_maintenance() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET statement_timeout TO '2000ms'
    AS $$
DECLARE purged integer;unlinked integer;links integer;credentials integer;used bigint;archived jsonb;
BEGIN
 PERFORM pg_advisory_xact_lock(7463103001);
 UPDATE twuanis_measurement_private.journeys_r3 SET last_at=last_at WHERE id IN(SELECT id FROM twuanis_measurement_private.journeys_r3 WHERE collection_closed_at IS NULL AND(expires_at<=clock_timestamp() OR last_at<clock_timestamp()-interval '30 minutes' OR ended_at IS NOT NULL) ORDER BY expires_at,id LIMIT 100);
 archived:=twuanis_measurement_private.journey_archive_r4();
 DELETE FROM twuanis_measurement_private.journey_events_r3 WHERE (journey,id) IN(SELECT e.journey,e.id FROM twuanis_measurement_private.journey_events_r3 e JOIN twuanis_measurement_private.journeys_r3 j ON j.id=e.journey WHERE e.retention_until<=clock_timestamp() AND j.archive_state IS NOT NULL ORDER BY e.retention_until,e.received_seq LIMIT 2000);
 -- Scope/credential expiry is deliberately absent from historical deletion.
 UPDATE twuanis_measurement_private.journeys_r3 SET auth_session=NULL WHERE id IN(SELECT id FROM ((SELECT id FROM twuanis_measurement_private.journeys_r3 WHERE expires_at<=clock_timestamp() AND auth_session IS NOT NULL ORDER BY expires_at,id LIMIT 100) UNION (SELECT id FROM twuanis_measurement_private.journeys_r3 WHERE ended_at IS NOT NULL AND auth_session IS NOT NULL ORDER BY ended_at,id LIMIT 100)) ended LIMIT 100);GET DIAGNOSTICS credentials=ROW_COUNT;
 DELETE FROM twuanis_measurement_private.journey_orders_r3 o WHERE o.order_id IN(SELECT x.order_id FROM twuanis_measurement_private.journey_orders_r3 x JOIN twuanis_measurement_private.journeys_r3 j ON j.id=x.journey WHERE x.followup_until<=clock_timestamp() ORDER BY x.followup_until,x.order_id LIMIT 100);GET DIAGNOSTICS links=ROW_COUNT;

 DELETE FROM twuanis_measurement_private.journeys_r3 WHERE id IN(SELECT id FROM ((SELECT j.id FROM twuanis_measurement_private.journeys_r3 j WHERE j.history_until<=clock_timestamp() AND j.archive_state IS NOT NULL AND NOT EXISTS(SELECT 1 FROM twuanis_measurement_private.journey_events_r3 e WHERE e.journey=j.id) AND NOT EXISTS(SELECT 1 FROM twuanis_measurement_private.journey_orders_r3 o WHERE o.journey=j.id) ORDER BY j.history_until,j.id LIMIT 100) UNION (SELECT id FROM twuanis_measurement_private.journeys_r3 WHERE suppressed ORDER BY id LIMIT 100) UNION (SELECT j.id FROM twuanis_measurement_private.journey_erasure_r3 r JOIN twuanis_measurement_private.journeys_r3 j ON j.account_id=r.account_id LIMIT 100) UNION (SELECT o.journey AS id FROM twuanis_measurement_private.journey_erasure_r3 r JOIN twuanis_measurement_private.journey_orders_r3 o ON o.account_id=r.account_id LIMIT 100) UNION (SELECT ev.journey AS id FROM twuanis_measurement_private.journey_erasure_r3 r JOIN twuanis_canonical_private.offer_order_snapshots own ON own.account_id=r.account_id JOIN twuanis_measurement_private.journey_events_r3 ev ON ev.envelope->>'order'=own.id::text WHERE ev.authority='canonical' LIMIT 100)) due LIMIT 100);GET DIAGNOSTICS purged=ROW_COUNT;
 UPDATE twuanis_measurement_private.journeys_r3 SET account_id=NULL,auth_session=NULL,linked_at=NULL WHERE id IN(SELECT id FROM twuanis_measurement_private.journeys_r3 WHERE identity_until<=clock_timestamp() AND account_id IS NOT NULL ORDER BY identity_until,id LIMIT 100);GET DIAGNOSTICS unlinked=ROW_COUNT;
 -- Minimal suppression tombstones are finite too; never release suppression while related records remain.
 DELETE FROM twuanis_measurement_private.journey_erasure_r3 WHERE account_id IN(SELECT r.account_id FROM twuanis_measurement_private.journey_erasure_r3 r WHERE retain_until<=clock_timestamp() AND NOT EXISTS(SELECT 1 FROM twuanis_measurement_private.journeys_r3 j WHERE j.account_id=r.account_id) AND NOT EXISTS(SELECT 1 FROM twuanis_measurement_private.journey_orders_r3 o WHERE o.account_id=r.account_id) AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_order_snapshots own JOIN twuanis_measurement_private.journey_events_r3 ev ON ev.envelope->>'order'=own.id::text WHERE own.account_id=r.account_id AND ev.authority='canonical') ORDER BY retain_until,account_id LIMIT 100);
 SELECT coalesce(sum(pg_total_relation_size(x::regclass)),0) INTO used FROM unnest(ARRAY['twuanis_measurement_private.journeys_r3','twuanis_measurement_private.journey_events_r3','twuanis_measurement_private.journey_orders_r3','twuanis_measurement_private.journey_erasure_r3','twuanis_measurement_private.journey_business_r4']) x;

 RETURN jsonb_build_object('state','CHECKED','purged',purged,'collectionCredentialsCleared',credentials,'identitiesUnlinked',unlinked,'commercialLinksRemoved',links,'storageBytes',used,'databaseBytes',pg_database_size(current_database()),'connections',(SELECT count(*) FROM pg_stat_activity),'maxConnections',current_setting('max_connections')::integer,'admission',(SELECT jsonb_build_object('minute',minute_at,'scopes',starts,'events',events,'rateRejections',rate_rejections,'capacityRejections',capacity_rejections) FROM twuanis_measurement_private.journey_policy_r3 WHERE singleton),'archive',archived,'capacityState',CASE WHEN current_setting('default_transaction_read_only')='on' THEN 'READ_ONLY' ELSE 'AVAILABLE' END,'privacyBacklog',EXISTS(SELECT 1 FROM twuanis_measurement_private.journeys_r3 WHERE history_until<=clock_timestamp() OR(identity_until<=clock_timestamp() AND account_id IS NOT NULL) OR(collection_closed_at IS NULL AND(expires_at<=clock_timestamp() OR last_at+interval '30 minutes'<=clock_timestamp() OR ended_at IS NOT NULL))) OR EXISTS(SELECT 1 FROM twuanis_measurement_private.journey_orders_r3 WHERE followup_until<=clock_timestamp()) OR EXISTS(SELECT 1 FROM twuanis_measurement_private.journey_erasure_r3 WHERE retain_until<=clock_timestamp()) OR EXISTS(SELECT 1 FROM twuanis_measurement_private.journeys_r3 WHERE suppressed) OR EXISTS(SELECT 1 FROM twuanis_measurement_private.journey_erasure_r3 r JOIN twuanis_measurement_private.journeys_r3 j ON j.account_id=r.account_id) OR EXISTS(SELECT 1 FROM twuanis_measurement_private.journey_erasure_r3 r JOIN twuanis_measurement_private.journey_orders_r3 o ON o.account_id=r.account_id));
END $$;


--
-- Name: ka10_journey_order(text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ka10_journey_order(p_journey text, p_token_digest text, p_order uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET statement_timeout TO '1000ms'
    AS $$
DECLARE admission text;j twuanis_measurement_private.journeys_r3%ROWTYPE;a uuid:=auth.uid();n timestamptz:=clock_timestamp();c jsonb;
BEGIN
 PERFORM pg_advisory_xact_lock(7463103001);
 SELECT * INTO j FROM twuanis_measurement_private.journeys_r3 WHERE id=p_journey FOR UPDATE;
 IF a IS NULL OR a='d81064bc-1b4a-478f-8f6a-b263c4779bc1' OR j.id IS NULL OR j.notice IS DISTINCT FROM public.ka10_journey_policy()->>'notice' OR j.account_id IS DISTINCT FROM a OR j.proof<>p_token_digest OR j.ended_at IS NOT NULL OR j.suppressed OR j.expires_at<=n OR j.last_at+interval '30 minutes'<=n OR NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_order_snapshots WHERE id=p_order AND account_id=a AND created_at>=j.created_at AND created_at>=n-interval '10 minutes') THEN RETURN '{"state":"SUPPRESSED"}';END IF;
 SELECT envelope INTO c FROM twuanis_measurement_private.journey_events_r3 WHERE journey=j.id AND authority='client_observed' ORDER BY observed_at DESC,received_seq DESC LIMIT 1;
 IF EXISTS(SELECT 1 FROM twuanis_measurement_private.journey_erasure_r3 WHERE account_id=a) THEN RETURN '{"state":"SUPPRESSED"}';END IF;
 IF NOT EXISTS(SELECT 1 FROM twuanis_measurement_private.journey_orders_r3 WHERE order_id=p_order) THEN
 IF (SELECT count(*) FROM twuanis_measurement_private.journey_orders_r3 WHERE journey=j.id)>=100 THEN RETURN '{"state":"SESSION_LIMIT"}';END IF;
 admission:=twuanis_measurement_private.journey_admit_r3(0,2);IF admission<>'ADMITTED' THEN RETURN jsonb_build_object('state',admission);END IF;END IF;
 INSERT INTO twuanis_measurement_private.journey_orders_r3(order_id,journey,account_id,campaign,followup_until) VALUES(p_order,j.id,a,c,n+make_interval(days=>(public.ka10_journey_policy()->>'commercialDays')::integer)) ON CONFLICT DO NOTHING;
 IF NOT EXISTS(SELECT 1 FROM twuanis_measurement_private.journey_orders_r3 WHERE order_id=p_order AND journey=j.id) THEN RETURN '{"state":"ALREADY_BOUND"}';END IF;
 INSERT INTO twuanis_measurement_private.journey_events_r3(journey,id,observed_at,envelope,authority) SELECT j.id,'order:'||o.id::text,o.created_at,jsonb_build_object('name','tw_order_created','operation','order','outcome','pending','order',o.id,'product',o.product_id,'currency',o.currency,'locale',coalesce(c->>'locale','unknown'),'campaign',c->>'campaign','content',c->>'content'),'canonical' FROM twuanis_canonical_private.offer_order_snapshots o WHERE o.id=p_order ON CONFLICT DO NOTHING;
 RETURN '{"state":"BOUND"}';
EXCEPTION WHEN disk_full OR out_of_memory OR configuration_limit_exceeded OR read_only_sql_transaction THEN RETURN '{"state":"CAPACITY","reason":"storage_or_compute"}';
END $$;


--
-- Name: ka10_journey_policy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ka10_journey_policy() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT CASE WHEN approval_ref IS NULL OR history_days IS NULL OR identity_days IS NULL OR commercial_days IS NULL OR suppression_days IS NULL OR aggregate_approval_ref IS NULL THEN '{"state":"POLICY_REQUIRED"}'::jsonb ELSE jsonb_build_object('state','APPROVED','notice','journey-r4-'||md5(concat_ws('|',approval_ref,history_days,identity_days,commercial_days,suppression_days,aggregate_approval_ref,anonymous_aggregate_approval_ref,min_contributors)),'historyDays',history_days,'identityDays',identity_days,'commercialDays',commercial_days,'suppressionDays',suppression_days,'minimumContributors',min_contributors,'anonymousAggregationApproved',anonymous_aggregate_approval_ref IS NOT NULL) END FROM twuanis_measurement_private.journey_policy_r3 WHERE singleton
$$;


--
-- Name: ka10_journey_reconcile(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ka10_journey_reconcile() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET statement_timeout TO '2000ms'
    AS $$
DECLARE b record;r jsonb;paid jsonb;t record;payment_state text;provider_state text;deadline timestamptz;credit_delivery uuid;admission text;counted integer:=0;n timestamptz:=clock_timestamp();
BEGIN
 PERFORM pg_advisory_xact_lock(7463103001);
 FOR b IN SELECT o.* FROM twuanis_measurement_private.journey_orders_r3 o JOIN twuanis_measurement_private.journeys_r3 j ON j.id=o.journey
 WHERE NOT j.suppressed AND j.policy_ref IS NOT NULL AND o.followup_until>n AND o.account_id<>'d81064bc-1b4a-478f-8f6a-b263c4779bc1'
 AND NOT EXISTS(SELECT 1 FROM twuanis_measurement_private.journey_erasure_r3 r WHERE r.account_id=o.account_id)
 ORDER BY o.checked_at NULLS FIRST,o.bound_at LIMIT 20 FOR UPDATE OF o SKIP LOCKED LOOP
 admission:=twuanis_measurement_private.journey_admit_r3(0,5);IF admission<>'ADMITTED' THEN RETURN jsonb_build_object('state',admission,'checked',counted);END IF;
 paid:=twuanis_measurement_private.journey_paid_r3(b.order_id,b.account_id);
 IF paid IS NULL THEN
 SELECT o.payment_deadline INTO deadline FROM twuanis_canonical_private.offer_order_snapshots o WHERE o.id=b.order_id AND o.account_id=b.account_id;
 SELECT to_jsonb(i)->>'confirmation_status' INTO provider_state FROM twuanis_canonical_private.onvo_intents i WHERE i.order_id=b.order_id;
 payment_state:=CASE WHEN deadline<=n THEN 'expired' WHEN provider_state IN('failed','canceled') THEN 'failed' ELSE 'pending' END;
 INSERT INTO twuanis_measurement_private.journey_events_r3(journey,id,observed_at,envelope,authority) VALUES(b.journey,'payment_state:'||b.order_id::text||':'||payment_state,CASE WHEN payment_state='expired' THEN deadline ELSE n END,jsonb_build_object('name','tw_payment_observed','operation','payment_status','outcome',payment_state,'order',b.order_id,'provider_status',CASE WHEN provider_state IN('processing','failed','canceled') THEN provider_state ELSE 'unknown' END),'canonical') ON CONFLICT DO NOTHING;
 END IF;
 -- Existing canonical ONVO measurement authority requires the approved receipt and paid acknowledgement.
 paid:=twuanis_measurement_private.journey_paid_r3(b.order_id,b.account_id);r:=paid;
 IF paid IS NOT NULL THEN
 INSERT INTO twuanis_measurement_private.journey_events_r3(journey,id,observed_at,envelope,authority) VALUES(b.journey,'paid:'||b.order_id::text,(r->>'outcome_at')::timestamptz,jsonb_build_object('name','purchase','operation','order','outcome','verified','order',b.order_id,'amount',r->>'amount','currency',r->>'currency','paid_acknowledgement',r->>'receipt_ref','product',r->>'product_id','locale',coalesce(b.campaign->>'locale','unknown'),'campaign',b.campaign->>'campaign','content',b.campaign->>'content'),'canonical') ON CONFLICT DO NOTHING;
 END IF;
 FOR t IN SELECT et.* FROM twuanis_canonical_private.entitlement_terms et JOIN twuanis_canonical_private.offer_paid_acknowledgements pa ON pa.id=et.acknowledgement_id AND pa.order_id=et.order_id WHERE et.order_id=b.order_id AND et.account_id=b.account_id AND et.source='PURCHASED' AND paid IS NOT NULL AND pa.id::text=paid->>'receipt_ref' LOOP
 INSERT INTO twuanis_measurement_private.journey_events_r3(journey,id,observed_at,envelope,authority) VALUES(b.journey,'fulfilled:'||t.id::text,t.committed_at,jsonb_build_object('name','tw_fulfillment','operation','order','outcome',CASE WHEN t.starts_at>n THEN 'scheduled' ELSE 'fulfilled' END,'order',b.order_id,'term',t.id),'canonical') ON CONFLICT DO NOTHING;
 IF t.starts_at<=n AND (t.ends_at IS NULL OR t.ends_at>n) AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.entitlement_revocations WHERE term_id=t.id) THEN
 r:=twuanis_measurement_private.authority('tw_entitlement_state',b.order_id,b.account_id);
 IF t.product_class<>'PACKAGE' OR r IS NOT NULL AND EXISTS(SELECT 1 FROM twuanis_canonical_private.intelligence_package_rights rights WHERE rights.id=t.id AND rights.account_id=t.account_id AND rights.package_id=t.product_id AND rights.configuration_id=t.configuration_id AND rights.starts_at=t.starts_at AND rights.ends_at=t.ends_at AND rights.revoked_at IS NULL) THEN INSERT INTO twuanis_measurement_private.journey_events_r3(journey,id,observed_at,envelope,authority) VALUES(b.journey,'active:'||t.id::text,greatest(t.starts_at,t.committed_at),jsonb_build_object('name','tw_access_active','operation','order','outcome','active','product_class',t.product_class,'order',b.order_id,'term',t.id),'canonical') ON CONFLICT DO NOTHING;END IF;
 END IF;
 IF EXISTS(SELECT 1 FROM twuanis_canonical_private.entitlement_revocations WHERE term_id=t.id) THEN INSERT INTO twuanis_measurement_private.journey_events_r3(journey,id,observed_at,envelope,authority) VALUES(b.journey,'revoked:'||t.id::text,n,jsonb_build_object('name','tw_access_revoked','operation','order','outcome','reversed','order',b.order_id,'term',t.id),'canonical') ON CONFLICT DO NOTHING;END IF;
 END LOOP;
 IF paid IS NOT NULL AND EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_order_snapshots WHERE id=b.order_id AND account_id=b.account_id AND target_type='execution_credit') THEN
 BEGIN
 credit_delivery:=twuanis_canonical_private.assert_execution_credit_delivery(b.order_id);
 INSERT INTO twuanis_measurement_private.journey_events_r3(journey,id,observed_at,envelope,authority) VALUES(b.journey,'credit_delivery:'||credit_delivery::text,n,jsonb_build_object('name','tw_credit_delivery','operation','order','outcome','fulfilled','order',b.order_id,'allocation',credit_delivery,'timing','first_observed_verified'),'canonical') ON CONFLICT DO NOTHING;
 EXCEPTION WHEN OTHERS THEN NULL; -- Missing canonical delivery is pending, never fabricated.
 END;
 END IF;
 UPDATE twuanis_measurement_private.journey_orders_r3 SET checked_at=n WHERE order_id=b.order_id;counted:=counted+1;
 END LOOP;RETURN jsonb_build_object('state','CHECKED','checked',counted);
EXCEPTION WHEN disk_full OR out_of_memory OR configuration_limit_exceeded OR read_only_sql_transaction THEN RETURN '{"state":"CAPACITY","reason":"storage_or_compute"}';
END $$;


--
-- Name: ka10_journey_server_event(uuid, text, text, text, text, text, text, text, bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ka10_journey_server_event(p_account uuid, p_journey text, p_token_digest text, p_id text, p_name text, p_control text, p_outcome text, p_locale text, p_at bigint, p_request text, p_population text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET statement_timeout TO '1000ms'
    AS $_$
DECLARE admission text;inserted integer;j twuanis_measurement_private.journeys_r3%ROWTYPE;n timestamptz:=clock_timestamp();
BEGIN
 IF p_population NOT IN('PRIVATE','BANK','SALE','RENT','UNKNOWN') OR p_population IS NULL OR p_at IS NULL OR p_at<extract(epoch FROM n-interval '10 minutes')*1000 OR p_at>extract(epoch FROM n+interval '30 seconds')*1000 OR (p_request IS NOT NULL AND p_request !~ '^m[a-f0-9]{64}$') OR p_account IS NULL OR p_account='d81064bc-1b4a-478f-8f6a-b263c4779bc1' OR p_name NOT IN('tw_execution_request','tw_authorization','tw_execution_result','tw_report_retrieve','begin_checkout') OR p_id !~ '^e[a-f0-9]{32}$' OR p_control !~ '^[a-z][a-z0-9_-]{0,79}$' OR p_outcome NOT IN('intent','acknowledged','denied','failed','pending','unavailable') OR p_locale NOT IN('en','es') THEN RETURN '{"state":"INVALID"}';END IF;
 PERFORM pg_advisory_xact_lock(7463103001);
 SELECT * INTO j FROM twuanis_measurement_private.journeys_r3 WHERE id=p_journey FOR UPDATE;
 IF NOT FOUND OR j.notice IS DISTINCT FROM public.ka10_journey_policy()->>'notice' OR j.proof<>p_token_digest OR j.account_id IS DISTINCT FROM p_account OR j.ended_at IS NOT NULL OR j.suppressed OR j.expires_at<=n OR j.last_at+interval '30 minutes'<=n OR j.received>=2000 OR NOT EXISTS(SELECT 1 FROM auth.sessions WHERE id=j.auth_session AND user_id=p_account AND (not_after IS NULL OR not_after>n)) THEN RETURN '{"state":"SUPPRESSED"}';END IF;
 IF EXISTS(SELECT 1 FROM twuanis_measurement_private.journey_erasure_r3 WHERE account_id=p_account) THEN RETURN '{"state":"SUPPRESSED"}';END IF;
 IF EXISTS(SELECT 1 FROM twuanis_measurement_private.journey_events_r3 WHERE journey=j.id AND id=p_id) THEN RETURN '{"state":"STORED"}';END IF;
 admission:=twuanis_measurement_private.journey_admit_r3(0,1);IF admission<>'ADMITTED' THEN RETURN jsonb_build_object('state',admission);END IF;
 INSERT INTO twuanis_measurement_private.journey_events_r3(journey,id,observed_at,envelope,authority) VALUES(j.id,p_id,to_timestamp(p_at/1000.0),jsonb_build_object('population',p_population,'request',p_request,'name',p_name,'control',p_control,'operation',CASE WHEN p_name='begin_checkout' THEN 'checkout' WHEN p_name='tw_report_retrieve' THEN 'report' ELSE 'execution' END,'outcome',p_outcome,'locale',p_locale),'server_acknowledged') ON CONFLICT DO NOTHING;
 UPDATE twuanis_measurement_private.journeys_r3 SET received=received+1 WHERE id=j.id;RETURN '{"state":"STORED"}';
EXCEPTION WHEN disk_full OR out_of_memory OR configuration_limit_exceeded OR read_only_sql_transaction THEN RETURN '{"state":"CAPACITY","reason":"storage_or_compute"}';
END $_$;


--
-- Name: ka10_journey_start(text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ka10_journey_start(p_journey text, p_token_digest text, p_notice text, p_expires timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET statement_timeout TO '1000ms'
    AS $_$
DECLARE admission text;a uuid:=auth.uid();s uuid:=nullif(auth.jwt()->>'session_id','')::uuid;j twuanis_measurement_private.journeys_r3%ROWTYPE;n timestamptz:=clock_timestamp();
BEGIN
 IF public.ka10_journey_policy()->>'state'<>'APPROVED' THEN RETURN '{"state":"POLICY_REQUIRED"}';END IF;
 IF p_expires IS NULL OR p_expires<=n OR p_expires>n+interval '24 hours' OR p_notice IS DISTINCT FROM public.ka10_journey_policy()->>'notice' OR p_journey IS NULL OR p_journey !~ '^[a-f0-9]{32}$' OR p_token_digest IS NULL OR p_token_digest !~ '^[a-f0-9]{64}$' THEN RETURN '{"state":"INVALID"}';END IF;
 IF a='d81064bc-1b4a-478f-8f6a-b263c4779bc1' OR a IS NOT NULL AND (s IS NULL OR NOT EXISTS(SELECT 1 FROM auth.sessions WHERE id=s AND user_id=a AND (not_after IS NULL OR not_after>n))) THEN RETURN '{"state":"SUPPRESSED"}';END IF;
 PERFORM pg_advisory_xact_lock(7463103001);SELECT * INTO j FROM twuanis_measurement_private.journeys_r3 WHERE id=p_journey FOR UPDATE;
 IF FOUND THEN
 IF j.notice=p_notice AND j.proof=p_token_digest AND j.ended_at IS NULL AND NOT j.suppressed AND j.expires_at>n AND (j.account_id IS NULL OR j.account_id=a AND j.auth_session=s) THEN RETURN '{"state":"GRANTED"}';END IF;
 RETURN '{"state":"SUPPRESSED"}';END IF;
 IF EXISTS(SELECT 1 FROM twuanis_measurement_private.journey_erasure_r3 WHERE account_id=a) THEN RETURN '{"state":"SUPPRESSED"}';END IF;
 admission:=twuanis_measurement_private.journey_admit_r3(1,0);IF admission<>'ADMITTED' THEN RETURN jsonb_build_object('state',admission);END IF;
 INSERT INTO twuanis_measurement_private.journeys_r3(id,proof,account_id,auth_session,expires_at,linked_at,policy_ref,notice,history_until,identity_until,commercial_until,history_days,aggregate_ref,anonymous_aggregate_approved,minimum_contributors) VALUES(p_journey,p_token_digest,a,s,p_expires,CASE WHEN a IS NULL THEN NULL ELSE n END,(SELECT approval_ref FROM twuanis_measurement_private.journey_policy_r3 WHERE singleton),p_notice,p_expires+make_interval(days=>(public.ka10_journey_policy()->>'historyDays')::integer),n+make_interval(days=>(public.ka10_journey_policy()->>'identityDays')::integer),n+make_interval(days=>(public.ka10_journey_policy()->>'commercialDays')::integer),(public.ka10_journey_policy()->>'historyDays')::integer,(SELECT aggregate_approval_ref FROM twuanis_measurement_private.journey_policy_r3 WHERE singleton),(public.ka10_journey_policy()->>'anonymousAggregationApproved')::boolean,(public.ka10_journey_policy()->>'minimumContributors')::integer);RETURN '{"state":"GRANTED"}';
EXCEPTION WHEN disk_full OR out_of_memory OR configuration_limit_exceeded OR read_only_sql_transaction THEN RETURN '{"state":"CAPACITY","reason":"storage_or_compute"}';
END $_$;


--
-- Name: ka10_outcome_reserve_r4(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ka10_outcome_reserve_r4(p_id uuid, p_account uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE r jsonb;s bigint;
BEGIN
 IF EXISTS(SELECT 1 FROM twuanis_measurement_private.journey_erasure_r3 WHERE account_id=p_account) THEN RETURN '{"state":"SUPPRESSED"}';END IF;
 r:=public.ka09_outcome_reserve(p_id,p_account);
 IF r->>'state'='CLAIMED' THEN SELECT CASE WHEN g.ga_session_observed_at BETWEEN c.bound_at-interval '30 minutes' AND c.bound_at+interval '1 minute' THEN g.ga_session_id END INTO s FROM twuanis_measurement_private.outcome_claims c JOIN twuanis_measurement_private.consent_grants g ON g.id=c.grant_id WHERE c.id=p_id AND g.account_id=p_account;r:=r||jsonb_build_object('gaSessionId',s);END IF;
 RETURN r;
END $$;


--
-- Name: ka10_report_r4(text, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ka10_report_r4(p_panel text, p_from date, p_until date) RETURNS TABLE(bucket_day date, cohort_day date, projection text, locale text, population text, campaign text, source text, medium text, landing_page text, control_id text, algorithm_id text, product_id text, event_name text, outcome text, stage text, from_stage text, to_stage text, currency text, event_count bigint, scope_occurrences bigint, scope_starts bigint, gross_verified_revenue numeric, coverage text, source_from date, source_until date)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET statement_timeout TO '2s'
    AS $$
DECLARE n integer;ids text[];k integer;anonymous_ok boolean;
BEGIN
 IF p_panel NOT IN('B','C','D') OR p_panel IS NULL OR p_from IS NULL OR p_until IS NULL OR p_until<=p_from OR p_until-p_from>366 THEN RAISE EXCEPTION 'Bounded reporting window required' USING ERRCODE='22023';END IF;
 SELECT array_agg(x.journey) INTO ids FROM(SELECT DISTINCT e.journey FROM twuanis_measurement_private.journey_reporting_r3 e JOIN twuanis_measurement_private.journeys_r3 j ON j.id=e.journey WHERE j.archive_state IS NULL AND e.observed_at>=p_from::timestamp AT TIME ZONE 'UTC' AND e.observed_at<p_until::timestamp AT TIME ZONE 'UTC' LIMIT 1001)x;
 IF cardinality(ids)>1000 THEN RAISE EXCEPTION 'Narrow date range; current scope query bound exceeded' USING ERRCODE='54000';END IF;
 SELECT max(j.minimum_contributors),bool_and(j.anonymous_aggregate_approved) INTO k,anonymous_ok FROM twuanis_measurement_private.journeys_r3 j WHERE j.id=ANY(ids);
 RETURN QUERY
 WITH live AS MATERIALIZED(SELECT r.*,r.contributors>=k AND r.dominance<=0.2 AND (NOT r.anonymous OR anonymous_ok) AND(r.paid=0 OR r.payers>=k AND r.revenue_dominance<=0.2) released FROM twuanis_measurement_private.journey_cells_r4(ids,false) r),
 combined AS(
 SELECT a.bucket_day,a.cohort_day,a.projection,a.dimensions,a.event_count,a.scope_occurrences,a.scope_starts,a.revenue,a.status FROM twuanis_measurement_private.journey_business_r4 a WHERE a.bucket_day>=p_from AND a.bucket_day<p_until
 UNION ALL
 SELECT r.event_day,r.cohort,r.projection,r.dimensions,r.events,r.scopes,r.starts,CASE WHEN r.projection='commercial' THEN r.paid END,'APPROVED_AGGREGATE'::text FROM live r WHERE r.released AND r.event_day>=p_from AND r.event_day<p_until
 UNION ALL
 SELECT DISTINCT date_trunc('month',r.event_day)::date,date_trunc('month',r.cohort)::date,'coverage','{"reason":"privacy_withheld"}'::jsonb,NULL::bigint,NULL::bigint,NULL::bigint,NULL::numeric,'PRIVACY_WITHHELD'::text FROM live r WHERE NOT r.released
 ), totals AS(SELECT a.bucket_day,a.cohort_day,a.projection,a.dimensions,sum(a.event_count)::bigint event_count,sum(a.scope_occurrences)::bigint scope_occurrences,sum(a.scope_starts)::bigint scope_starts,sum(a.revenue) revenue,a.status FROM combined a GROUP BY a.bucket_day,a.cohort_day,a.projection,a.dimensions,a.status)
 SELECT a.bucket_day,a.cohort_day,a.projection,a.dimensions->>'locale',a.dimensions->>'population',a.dimensions->>'campaign',a.dimensions->>'source',a.dimensions->>'medium',a.dimensions->>'landing',a.dimensions->>'control',a.dimensions->>'algorithm',a.dimensions->>'product',a.dimensions->>'event',a.dimensions->>'outcome',a.dimensions->>'stage',a.dimensions->>'from',a.dimensions->>'to',a.dimensions->>'currency',a.event_count,a.scope_occurrences,a.scope_starts,a.revenue,a.status,p_from,p_until FROM totals a WHERE(a.projection='coverage' OR p_panel='B' AND a.projection IN('flow','transition','traffic','acquisition') OR p_panel='C' AND a.projection IN('feature','algorithm') OR p_panel='D' AND a.projection IN('commercial','flow')) ORDER BY a.bucket_day,a.cohort_day,a.projection,a.dimensions LIMIT 10001;
 GET DIAGNOSTICS n=ROW_COUNT;IF n>10000 THEN RAISE EXCEPTION 'Narrow date range; partial reports forbidden' USING ERRCODE='54000';END IF;
END $$;


--
-- Name: listing_duplicate_notification_service(text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listing_duplicate_notification_service(p_operation text, p_case uuid DEFAULT NULL::uuid, p_command jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE q twuanis_canonical_private.listing_duplicate_owner_notifications; lease_token uuid:=gen_random_uuid(); BEGIN
 IF p_operation='claim' THEN
  SELECT n.* INTO q FROM twuanis_canonical_private.listing_duplicate_owner_notifications n JOIN twuanis_canonical_private.listing_duplicate_cases c ON c.id=n.case_id WHERE c.status IN('REVIEW_REQUIRED','UNRESOLVED') AND n.state IN('PENDING','RETRY') AND n.next_at<=clock_timestamp() AND (n.lease_until IS NULL OR n.lease_until<clock_timestamp()) ORDER BY n.next_at,n.case_id FOR UPDATE OF n SKIP LOCKED LIMIT 1;
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF q.attempts>=8 OR q.first_attempt<clock_timestamp()-interval '23 hours' THEN UPDATE twuanis_canonical_private.listing_duplicate_owner_notifications SET state='NEEDS_RESOLUTION' WHERE case_id=q.case_id; RETURN NULL; END IF;
  UPDATE twuanis_canonical_private.listing_duplicate_owner_notifications SET attempts=attempts+1,first_attempt=coalesce(first_attempt,clock_timestamp()),lease=lease_token,lease_until=clock_timestamp()+interval '2 minutes' WHERE case_id=q.case_id;
  RETURN jsonb_build_object('caseId',q.case_id,'token',lease_token);
 ELSIF p_operation='finish' THEN
  UPDATE twuanis_canonical_private.listing_duplicate_owner_notifications SET state=CASE WHEN p_command->>'messageId' IS NOT NULL THEN 'ACCEPTED' ELSE 'RETRY' END,provider_id=p_command->>'messageId',lease=NULL,lease_until=NULL,next_at=clock_timestamp()+least(3600,30*power(2,attempts)) * interval '1 second' WHERE case_id=p_case AND lease=(p_command->>'token')::uuid;
  IF NOT FOUND THEN RAISE EXCEPTION 'Notification lease mismatch'; END IF; RETURN jsonb_build_object('ok',true);
 END IF; RAISE EXCEPTION 'Unsupported notification operation';
END $$;


--
-- Name: mutate_customer_canonical_listing(uuid, bigint, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mutate_customer_canonical_listing(p_listing uuid, p_expected bigint, p_request uuid, p_domains jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE actor uuid:=auth.uid(); d jsonb; original jsonb; snapshot twuanis_canonical_private.customer_domain_edits%ROWTYPE;
 item record; sets uuid[]; group_name text; dim text; l public.listings%ROWTYPE;
BEGIN
 IF actor IS NULL THEN RAISE EXCEPTION 'authenticated customer required' USING ERRCODE='42501'; END IF;
 IF p_request IS NULL OR p_expected IS NULL OR p_expected<1 THEN RAISE EXCEPTION 'explicit request/revision required' USING ERRCODE='22023'; END IF;
 d:=twuanis_canonical_private.s4_domains(p_domains,'owner'); original:=d;
 IF d ? 'lifecycle' THEN
  PERFORM twuanis_canonical_private.s3_keys(d->'lifecycle',ARRAY['event','reason'],ARRAY['event']);
  IF d->'lifecycle'->>'event' IN ('publish','renew') THEN RAISE EXCEPTION 'owner publication requires trusted duration policy' USING ERRCODE='0A000'; END IF;
 END IF;
 PERFORM twuanis_canonical_private.ensure_publisher_account(actor);
 PERFORM pg_advisory_xact_lock(3104,hashtext(jsonb_build_array('owner',actor::text,'domain_mutation',p_request)::text));
 SELECT * INTO snapshot FROM twuanis_canonical_private.customer_domain_edits WHERE owner_id=actor AND request_id=p_request;
 IF FOUND THEN
  IF snapshot.listing_id IS DISTINCT FROM p_listing OR snapshot.expected_revision IS DISTINCT FROM p_expected OR snapshot.input IS DISTINCT FROM original THEN RAISE EXCEPTION 'edit idempotency conflict' USING ERRCODE='22023'; END IF;
  d:=snapshot.derived;
 ELSE
  SELECT * INTO l FROM public.listings WHERE id=p_listing AND owner_id=actor FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'owner required' USING ERRCODE='42501'; END IF;
  IF l.canonical_domain_version IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'canonical listing required' USING ERRCODE='55000'; END IF;
  -- Receipts from before this migration retain their original payload semantics.
  IF NOT EXISTS(SELECT 1 FROM public.canonical_operation_receipts WHERE authority_kind='owner' AND authority_identity=actor::text AND operation_type='domain_mutation' AND request_id=p_request) THEN
  IF d->'facts'->'distance_to_paved_road'->>'kind'='range' AND EXISTS(SELECT 1 FROM public.listing_fact_evidence WHERE listing_id=p_listing AND dimension='distance_to_paved_road' AND kind='exact') THEN
   RAISE EXCEPTION 'Existing exact road-distance evidence cannot be replaced by a range' USING ERRCODE='22023';
  END IF;
   FOREACH group_name IN ARRAY ARRAY['facts','measurements'] LOOP
    FOR item IN SELECT key,value FROM jsonb_each(coalesce(d->group_name,'{}')) LOOP
     dim:=item.key;
     IF group_name='facts' AND item.value->>'kind' IS DISTINCT FROM 'exact' THEN CONTINUE; END IF;
     IF group_name='measurements' AND item.value='{"kind":"clear"}'::jsonb THEN CONTINUE; END IF;
     SELECT array_agg(DISTINCT r.rule_set_id) INTO sets FROM public.listing_membership_origins m JOIN public.listing_classification_rules r ON r.id=m.classification_rule_id WHERE m.listing_id=p_listing AND m.origin_domain=dim AND m.classification_rule_id IS NOT NULL;
     IF sets IS NOT NULL THEN
      IF cardinality(sets)<>1 OR NOT EXISTS(SELECT 1 FROM public.listing_classification_rule_sets r JOIN twuanis_canonical_private.classification_seals s ON s.rule_set_id=r.id WHERE r.id=sets[1] AND r.domain=dim) THEN RAISE EXCEPTION 'one recorded sealed typed rule required' USING ERRCODE='55000'; END IF;
      d:=jsonb_set(d,ARRAY[group_name,dim,'rule_set'],to_jsonb(sets[1]::text));
     END IF;
    END LOOP;
   END LOOP;
  END IF;
  INSERT INTO twuanis_canonical_private.customer_domain_edits VALUES(actor,p_request,p_listing,p_expected,original,d);
 END IF;
 RETURN twuanis_canonical_private.s3_command(p_listing,p_expected,'owner',actor::text,p_request,d,NULL)||jsonb_build_object('listing_id',p_listing::text);
END $$;


--
-- Name: mutate_trusted_canonical_listing(uuid, bigint, uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mutate_trusted_canonical_listing(p_listing uuid, p_expected bigint, p_request uuid, p_domains jsonb, p_source jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE d jsonb;source_name text;
BEGIN
 IF octet_length(p_source::text)>8192 THEN RAISE EXCEPTION 'source payload bound' USING ERRCODE='54000'; END IF;
 SELECT l.source_name INTO source_name FROM public.listings l WHERE l.id=p_listing;
 IF NOT FOUND THEN RAISE EXCEPTION 'listing missing' USING ERRCODE='P0002'; END IF;
 IF source_name IS NOT NULL AND p_source IS NULL THEN RAISE EXCEPTION 'source-backed mutation requires observation evidence' USING ERRCODE='22023'; END IF;
 d:=twuanis_canonical_private.s4_domains(p_domains,CASE WHEN p_source IS NULL THEN 'manual' ELSE 'source' END);
 RETURN twuanis_canonical_private.s3_command(p_listing,p_expected,'trusted','service_role',p_request,d,p_source)||jsonb_build_object('listing_id',p_listing::text);
END $$;


--
-- Name: onvo_reconciliation_service(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.onvo_reconciliation_service(p_operation text, p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE r twuanis_canonical_private.onvo_reconciliation%ROWTYPE;BEGIN
 IF p_operation='read' THEN
 INSERT INTO twuanis_canonical_private.onvo_reconciliation VALUES(p_command->>'providerAccount',p_command->>'mode',(p_command->>'from')::timestamptz,clock_timestamp(),NULL) ON CONFLICT DO NOTHING;
 SELECT * INTO STRICT r FROM twuanis_canonical_private.onvo_reconciliation WHERE provider_account=p_command->>'providerAccount' AND mode=p_command->>'mode';RETURN to_jsonb(r);
 ELSIF p_operation='advance' THEN
 SELECT * INTO STRICT r FROM twuanis_canonical_private.onvo_reconciliation WHERE provider_account=p_command->>'providerAccount' AND mode=p_command->>'mode' FOR UPDATE;
 IF r.cursor IS DISTINCT FROM p_command->>'expectedCursor' OR r.window_start IS DISTINCT FROM(p_command->>'start')::timestamptz OR r.window_end IS DISTINCT FROM(p_command->>'end')::timestamptz THEN RAISE EXCEPTION 'reconciliation cursor conflict';END IF;
 IF (p_command->>'hasMore')::boolean THEN IF p_command->>'cursor' IS NULL OR r.cursor IS NOT DISTINCT FROM p_command->>'cursor' THEN RAISE EXCEPTION 'nonadvancing cursor';END IF;UPDATE twuanis_canonical_private.onvo_reconciliation SET cursor=p_command->>'cursor' WHERE provider_account=r.provider_account AND mode=r.mode;
 ELSE UPDATE twuanis_canonical_private.onvo_reconciliation SET window_start=window_end,window_end=clock_timestamp(),cursor=NULL WHERE provider_account=r.provider_account AND mode=r.mode;END IF;RETURN jsonb_build_object('ok',true);
 ELSE RAISE EXCEPTION 'unknown reconciliation operation';END IF;
END$$;


--
-- Name: onvo_service_command(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.onvo_service_command(p_operation text, p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE o twuanis_canonical_private.offer_order_snapshots%ROWTYPE;i twuanis_canonical_private.onvo_intents%ROWTYPE;r twuanis_canonical_private.onvo_receipts%ROWTYPE;c twuanis_canonical_private.intelligence_package_configurations%ROWTYPE;j twuanis_canonical_private.onvo_fulfillment_jobs%ROWTYPE;tid uuid;aid uuid;rid uuid:=gen_random_uuid();start_at timestamptz;end_at timestamptz;received timestamptz;amount numeric;currency text;disposition text;reason text;result jsonb;inbox uuid;
BEGIN
 IF p_command IS NULL OR jsonb_typeof(p_command)<>'object' OR octet_length(p_command::text)>16384 THEN RAISE EXCEPTION 'bounded service command required';END IF;
 IF p_operation='health' THEN
 RETURN (WITH pending AS (
 SELECT received_at AS since FROM twuanis_canonical_private.onvo_inbox WHERE processed_at IS NULL
 UNION ALL SELECT ack.acknowledged_at FROM twuanis_canonical_private.onvo_fulfillment_jobs jobs JOIN twuanis_canonical_private.offer_paid_acknowledgements ack ON ack.order_id=jobs.order_id WHERE jobs.state='PENDING'
 UNION ALL SELECT n.created_at FROM twuanis_canonical_private.sinpe_purchase_notifications n WHERE n.state IN('PENDING','RETRY')
 ) SELECT jsonb_build_object('pending',count(*),'oldestPendingSeconds',coalesce(greatest(0,extract(epoch FROM clock_timestamp()-min(since)))::bigint,0),
 'attention',(SELECT count(*) FROM twuanis_canonical_private.onvo_intents WHERE state='UNCERTAIN' AND intent_id IS NULL)+
 (SELECT count(*) FROM twuanis_canonical_private.onvo_receipts receipts WHERE receipts.disposition IN('NEEDS_RESOLUTION','RECEIVED_UNMATCHED'))+
 (SELECT count(*) FROM twuanis_canonical_private.onvo_inbox inbox_rows WHERE inbox_rows.result->>'state'='NEEDS_RESOLUTION' OR(processed_at IS NULL AND attempts>=5 AND inbox_rows.result->>'reason' IS DISTINCT FROM 'verified_pending'))+
 (SELECT count(*) FROM twuanis_canonical_private.onvo_fulfillment_jobs WHERE state='NEEDS_RESOLUTION' OR(state='PENDING' AND attempts>=5))+
 (SELECT count(*) FROM twuanis_canonical_private.sinpe_purchase_notifications WHERE state='NEEDS_RESOLUTION')) FROM pending);
 ELSIF p_operation='provider_status' THEN
 SELECT * INTO STRICT i FROM twuanis_canonical_private.onvo_intents WHERE order_id=(p_command->>'orderId')::uuid FOR UPDATE;
 IF NOT i.confirmation_claimed OR i.intent_id IS DISTINCT FROM p_command->>'intentId' OR i.provider_account IS DISTINCT FROM p_command->>'providerAccount' OR i.mode IS DISTINCT FROM p_command->>'mode'
 OR p_command->>'status' IS NULL OR p_command->>'status' NOT IN('processing','failed') THEN RAISE EXCEPTION 'bound provider status required';END IF;
 IF i.confirmation_status IN('failed') AND i.confirmation_status IS DISTINCT FROM p_command->>'status' THEN RAISE EXCEPTION 'terminal status conflict';END IF;
 IF p_command->>'status'='failed' AND EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_paid_acknowledgements WHERE order_id=i.order_id) THEN RAISE EXCEPTION 'paid acknowledgement cannot be reversed by failure status';END IF;
 UPDATE twuanis_canonical_private.onvo_intents SET confirmation_status=p_command->>'status' WHERE order_id=i.order_id;
 RETURN jsonb_build_object('ok',true);
 ELSIF p_operation='unassociated' THEN
 SELECT id INTO inbox FROM twuanis_canonical_private.onvo_inbox WHERE digest=p_command->>'digest';IF FOUND THEN RETURN jsonb_build_object('state','NEEDS_RESOLUTION','id',inbox);END IF;
 IF NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.sinpe_receiving_accounts WHERE id=(p_command->>'receivingAccount')::uuid AND enabled) THEN RAISE EXCEPTION 'canonical receiving account required';END IF;
 INSERT INTO twuanis_canonical_private.sinpe_external_claims VALUES((p_command->>'receivingAccount')::uuid,p_command->>'reference','ONVO',rid);
 INSERT INTO twuanis_canonical_private.onvo_inbox(id,digest,event,processed_at,result)VALUES(rid,p_command->>'digest',jsonb_build_object('type','UNASSOCIATED','providerAccount',p_command->>'providerAccount','mode',p_command->>'mode','transactionId',p_command->>'transactionId','reference',p_command->>'reference','amount',p_command->>'amount','currency',p_command->>'currency','receivedAt',p_command->>'receivedAt'),clock_timestamp(),jsonb_build_object('state','NEEDS_RESOLUTION'));
 RETURN jsonb_build_object('state','NEEDS_RESOLUTION','id',rid);
 ELSIF p_operation='inbox' THEN
 INSERT INTO twuanis_canonical_private.onvo_inbox(digest,event)VALUES(p_command->>'digest',p_command->'event') ON CONFLICT(digest)DO NOTHING;
 SELECT id INTO inbox FROM twuanis_canonical_private.onvo_inbox WHERE digest=p_command->>'digest';RETURN jsonb_build_object('id',inbox);
 ELSIF p_operation='inbox_fail' THEN UPDATE twuanis_canonical_private.onvo_inbox SET attempts=attempts+1,next_attempt=clock_timestamp()+interval '1 minute',result=jsonb_build_object('state','RETRY','reason',CASE WHEN p_command->>'reason'='verified_pending' THEN 'verified_pending' ELSE 'provider_evidence_unavailable' END) WHERE id=(p_command->>'id')::uuid AND processed_at IS NULL;RETURN jsonb_build_object('ok',true);
 ELSIF p_operation='inbox_done' THEN UPDATE twuanis_canonical_private.onvo_inbox SET processed_at=clock_timestamp(),result=p_command->'result' WHERE id=(p_command->>'id')::uuid AND processed_at IS NULL;RETURN jsonb_build_object('ok',true);
 ELSIF p_operation='work' AND p_command->>'evidenceMode'='standard-intent' THEN
 IF nullif(p_command->>'providerAccount','') IS NULL OR p_command->>'mode' IS NULL OR p_command->>'mode' NOT IN('test','live') THEN RAISE EXCEPTION 'explicit standard provider scope required';END IF;
 RETURN jsonb_build_object(
 'events',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'event',event)),'[]')FROM(SELECT * FROM twuanis_canonical_private.onvo_inbox WHERE processed_at IS NULL AND next_attempt<=clock_timestamp() ORDER BY next_attempt,received_at,id LIMIT 20)x),
 'fulfillments',(SELECT coalesce(jsonb_agg(order_id),'[]')FROM(SELECT order_id FROM twuanis_canonical_private.onvo_fulfillment_jobs WHERE state='PENDING' AND next_attempt<=clock_timestamp() ORDER BY next_attempt LIMIT 20)x),
 'intents',(SELECT coalesce(jsonb_agg(jsonb_build_object('intentId',x.intent_id)),'[]')FROM(
 SELECT q.intent_id FROM twuanis_canonical_private.onvo_intents q
 WHERE q.provider_account=p_command->>'providerAccount' AND q.mode=p_command->>'mode' AND q.intent_id IS NOT NULL
 AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_paid_acknowledgements a WHERE a.order_id=q.order_id)
 AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.onvo_inbox n WHERE n.event->>'intentId'=q.intent_id)
 ORDER BY q.order_id LIMIT 20)x));
 ELSIF p_operation='work' THEN RETURN jsonb_build_object('events',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'event',event)),'[]')FROM(SELECT * FROM twuanis_canonical_private.onvo_inbox WHERE processed_at IS NULL AND next_attempt<=clock_timestamp() ORDER BY next_attempt,received_at,id LIMIT 20)x),'fulfillments',(SELECT coalesce(jsonb_agg(order_id),'[]')FROM(SELECT order_id FROM twuanis_canonical_private.onvo_fulfillment_jobs WHERE state='PENDING' AND next_attempt<=clock_timestamp() ORDER BY next_attempt LIMIT 20)x));
 END IF;
 IF p_operation IN('lookup','lookup_order') THEN
 SELECT * INTO i FROM twuanis_canonical_private.onvo_intents WHERE (p_operation='lookup' AND intent_id=p_command->>'intentId') OR(p_operation='lookup_order' AND order_id=(p_command->>'orderId')::uuid);IF NOT FOUND THEN RETURN NULL;END IF;
 ELSE SELECT * INTO STRICT o FROM twuanis_canonical_private.offer_order_snapshots WHERE id=(p_command->>'orderId')::uuid;
 END IF;
 IF p_operation='reserve' THEN
 IF o.resolved_terms->>'paymentExecution'='direct_sinpe'THEN RAISE EXCEPTION 'direct SINPE cannot initiate ONVO';END IF;
 IF o.account_id IS DISTINCT FROM (p_command->>'accountId')::uuid OR o.currency<>'CRC' OR o.target_type NOT IN('package','execution_credit','addon') OR NOT public.customer_commerce_ready() OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=o.account_id AND email_confirmed_at IS NOT NULL) OR clock_timestamp()>o.payment_deadline OR EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_paid_acknowledgements WHERE order_id=o.id) THEN RAISE EXCEPTION 'eligible confirmed owned CRC Order required';END IF;
 IF NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.sinpe_receiving_accounts bank WHERE bank.id=(p_command->>'receivingAccount')::uuid AND bank.enabled AND bank.currency='CRC') THEN RAISE EXCEPTION 'canonical receiving identity required';END IF;
 INSERT INTO twuanis_canonical_private.onvo_intents(order_id,provider_account,mode,receiving_account)VALUES(o.id,p_command->>'providerAccount',p_command->>'mode',(p_command->>'receivingAccount')::uuid)ON CONFLICT(order_id)DO NOTHING;
 SELECT * INTO STRICT i FROM twuanis_canonical_private.onvo_intents WHERE order_id=o.id FOR UPDATE;
 IF (i.provider_account,i.mode,i.receiving_account) IS DISTINCT FROM(p_command->>'providerAccount',p_command->>'mode',(p_command->>'receivingAccount')::uuid) THEN RAISE EXCEPTION 'provider reservation conflict';END IF;
 -- Claim the one POST opportunity before network I/O. Unknown outcomes never repeat it.
 IF i.state='RESERVED' THEN UPDATE twuanis_canonical_private.onvo_intents SET state='UNCERTAIN' WHERE order_id=o.id;result:=jsonb_build_object('create',true);ELSE result:=jsonb_build_object('create',false);END IF;
 RETURN result||jsonb_build_object('intentId',i.intent_id,'order',jsonb_build_object('id',o.id,'currency',o.currency,'amount',o.resolved_terms->>'total','createdAt',o.created_at,'deadline',o.payment_deadline));
 END IF;
 IF p_operation NOT IN('lookup','lookup_order') THEN SELECT * INTO STRICT i FROM twuanis_canonical_private.onvo_intents WHERE order_id=o.id FOR UPDATE;ELSE SELECT * INTO STRICT o FROM twuanis_canonical_private.offer_order_snapshots WHERE id=i.order_id;END IF;
 IF p_operation='bind' THEN
 IF i.intent_id IS NOT NULL AND i.intent_id IS DISTINCT FROM p_command->>'intentId' THEN RAISE EXCEPTION 'intent binding conflict';END IF;
 UPDATE twuanis_canonical_private.onvo_intents SET intent_id=p_command->>'intentId',state='BOUND' WHERE order_id=o.id;RETURN jsonb_build_object('ok',true);
 ELSIF p_operation='confirmation' THEN
 IF i.confirmation_claimed THEN RETURN jsonb_build_object('confirm',false);END IF;UPDATE twuanis_canonical_private.onvo_intents SET confirmation_claimed=true WHERE order_id=o.id;RETURN jsonb_build_object('confirm',true);
 ELSIF p_operation IN('lookup','lookup_order') THEN RETURN jsonb_build_object('order',jsonb_build_object('id',o.id,'currency',o.currency,'amount',o.resolved_terms->>'total','createdAt',o.created_at,'deadline',o.payment_deadline),'intentId',i.intent_id,'providerAccount',i.provider_account,'mode',i.mode);
 ELSIF p_operation='standard_receipt' THEN
 IF p_command->>'evidenceType' IS DISTINCT FROM 'ONVO_STANDARD_INTENT' OR p_command->>'status' IS DISTINCT FROM 'succeeded' OR p_command->>'chargeStatus' IS DISTINCT FROM 'succeeded' OR p_command->>'paymentMethodType' IS DISTINCT FROM 'mobile_number' OR p_command->>'evidenceDigest' !~ '^[a-f0-9]{64}$' OR p_command->>'evidenceDigest' IS NULL THEN RAISE EXCEPTION 'verified standard success evidence required';END IF;
 IF i.intent_id IS DISTINCT FROM p_command->>'intentId' OR i.provider_account IS DISTINCT FROM p_command->>'providerAccount' OR i.mode IS DISTINCT FROM p_command->>'mode' OR NOT i.confirmation_claimed THEN RAISE EXCEPTION 'confirmed provider binding mismatch';END IF;
 IF p_command->>'providerPaymentId' IS NULL OR p_command->>'providerPaymentId' !~ '^[A-Za-z0-9_-]{1,150}$' THEN RAISE EXCEPTION 'stable charge identity required';END IF;
 amount:=(p_command->>'amount')::numeric;currency:=p_command->>'currency';
 IF currency IS DISTINCT FROM 'CRC' OR currency IS DISTINCT FROM o.currency OR amount IS DISTINCT FROM (o.resolved_terms->>'total')::numeric OR (p_command->>'receivedAmount')::numeric IS DISTINCT FROM amount OR (p_command->>'chargeAmount')::numeric IS DISTINCT FROM amount THEN RAISE EXCEPTION 'exact standard paid amount required';END IF;
 PERFORM pg_advisory_xact_lock(3257,hashtext(i.provider_account||':'||i.mode||':'||(p_command->>'providerPaymentId')));
 SELECT * INTO r FROM twuanis_canonical_private.onvo_receipts WHERE provider_account=i.provider_account AND mode=i.mode AND transaction_id=p_command->>'providerPaymentId';
 IF FOUND THEN
 IF r.order_id<>o.id OR r.evidence_kind<>'STANDARD_INTENT' OR r.amount IS DISTINCT FROM amount OR r.currency IS DISTINCT FROM currency THEN RAISE EXCEPTION 'standard payment identity reuse conflict';END IF;
 RETURN jsonb_build_object('id',r.id,'disposition',r.disposition,'acknowledgementId',r.acknowledgement_id,'timingBasis',CASE WHEN r.disposition='APPROVED' THEN 'SUCCESS_VERIFIED_BY_DEADLINE' ELSE 'UNRESOLVED' END);END IF;
 PERFORM id FROM twuanis_canonical_private.offer_order_snapshots WHERE id=o.id FOR UPDATE;
 received:=clock_timestamp(); -- Canonical success verification-recorded time; NEVER bank funds-received time.
 IF received<=o.payment_deadline AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_paid_acknowledgements WHERE order_id=o.id) THEN disposition:='APPROVED';reason:=NULL;
 ELSE disposition:='NEEDS_RESOLUTION';reason:=CASE WHEN EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_paid_acknowledgements WHERE order_id=o.id) THEN 'order_already_paid' ELSE 'paid_timeliness_unresolved' END;END IF;
 IF disposition='APPROVED' THEN
 aid:=gen_random_uuid();INSERT INTO twuanis_canonical_private.offer_paid_acknowledgements(id,order_id,request_id,source,payment_event_id,external_reference,amount,currency,acknowledged_at,authority)VALUES(aid,o.id,rid,'onvo',rid,'ONVO_CHARGE:'||(p_command->>'providerPaymentId'),amount,currency,received,'ONVO:'||i.provider_account||':'||i.mode);
 INSERT INTO twuanis_canonical_private.onvo_fulfillment_jobs(order_id)VALUES(o.id)ON CONFLICT DO NOTHING;END IF;
 INSERT INTO twuanis_canonical_private.onvo_receipts(id,order_id,provider_account,mode,transaction_id,bank_reference,received_at,amount,currency,disposition,reason,acknowledgement_id,evidence_kind,success_verified_at,provider_evidence_digest)VALUES(rid,o.id,i.provider_account,i.mode,p_command->>'providerPaymentId',NULL,NULL,amount,currency,disposition,reason,aid,'STANDARD_INTENT',received,p_command->>'evidenceDigest');
 RETURN jsonb_build_object('id',rid,'disposition',disposition,'acknowledgementId',aid,'timingBasis',CASE WHEN disposition='APPROVED' THEN 'SUCCESS_VERIFIED_BY_DEADLINE' ELSE 'UNRESOLVED' END);
 ELSIF p_operation='receipt' THEN
 IF i.intent_id IS DISTINCT FROM p_command->>'intentId' OR i.provider_account IS DISTINCT FROM p_command->>'providerAccount' OR i.mode IS DISTINCT FROM p_command->>'mode' THEN RAISE EXCEPTION 'provider binding mismatch';END IF;
 PERFORM pg_advisory_xact_lock(3257,hashtext(i.provider_account||':'||i.mode||':'||(p_command->>'transactionId')));
 SELECT * INTO r FROM twuanis_canonical_private.onvo_receipts WHERE provider_account=i.provider_account AND mode=i.mode AND transaction_id=p_command->>'transactionId';
 IF FOUND THEN IF r.order_id<>o.id OR r.bank_reference IS DISTINCT FROM p_command->>'reference' OR r.amount IS DISTINCT FROM(p_command->>'amount')::numeric OR r.currency IS DISTINCT FROM p_command->>'currency' THEN RAISE EXCEPTION 'external event reuse conflict';END IF;RETURN jsonb_build_object('id',r.id,'disposition',r.disposition,'acknowledgementId',r.acknowledgement_id);END IF;
 PERFORM id FROM twuanis_canonical_private.offer_order_snapshots WHERE id=o.id FOR UPDATE;
 received:=(p_command->>'receivedAt')::timestamptz;amount:=(p_command->>'amount')::numeric;currency:=p_command->>'currency';reason:=NULL;
 IF received IS NULL THEN disposition:='NEEDS_RESOLUTION';reason:='missing_receipt_time';
 ELSIF NOT isfinite(received) OR received>clock_timestamp() THEN RAISE EXCEPTION 'invalid provider receipt time';
 ELSIF amount IS DISTINCT FROM(o.resolved_terms->>'total')::numeric OR currency IS DISTINCT FROM o.currency THEN disposition:='RECEIVED_UNMATCHED';reason:='amount_or_currency_mismatch';
 ELSIF received<o.created_at OR received>o.payment_deadline THEN disposition:='RECEIVED_UNMATCHED';reason:='outside_order_window';
 ELSIF EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_paid_acknowledgements WHERE order_id=o.id) THEN disposition:='RECEIVED_UNMATCHED';reason:='order_already_paid';
 ELSE disposition:='APPROVED';END IF;
 INSERT INTO twuanis_canonical_private.sinpe_external_claims VALUES(i.receiving_account,p_command->>'reference','ONVO',rid);
 IF disposition='APPROVED' THEN
 aid:=gen_random_uuid();INSERT INTO twuanis_canonical_private.offer_paid_acknowledgements(id,order_id,request_id,source,payment_event_id,external_reference,amount,currency,acknowledged_at,authority)VALUES(aid,o.id,rid,'onvo',rid,p_command->>'reference',amount,currency,clock_timestamp(),'ONVO:'||i.provider_account||':'||i.mode);
 INSERT INTO twuanis_canonical_private.onvo_fulfillment_jobs(order_id)VALUES(o.id)ON CONFLICT DO NOTHING;END IF;
 INSERT INTO twuanis_canonical_private.onvo_receipts(id,order_id,provider_account,mode,transaction_id,bank_reference,received_at,amount,currency,disposition,reason,acknowledgement_id)VALUES(rid,o.id,i.provider_account,i.mode,p_command->>'transactionId',p_command->>'reference',received,amount,currency,disposition,reason,aid);
 RETURN jsonb_build_object('id',rid,'disposition',disposition,'acknowledgementId',aid);
 ELSIF p_operation='fulfill' THEN
 SELECT * INTO STRICT j FROM twuanis_canonical_private.onvo_fulfillment_jobs WHERE order_id=o.id FOR UPDATE;
 IF p_command->>'customerRetry'='true' THEN
 IF o.account_id IS DISTINCT FROM (p_command->>'accountId')::uuid OR o.target_type<>'addon' THEN RAISE EXCEPTION 'owned Add-on retry required';END IF;
 IF j.state<>'COMPLETE' AND j.next_attempt>clock_timestamp() THEN RETURN jsonb_build_object('state','PENDING','reason','retry_deferred');END IF;
 END IF;

 BEGIN
 IF j.state='COMPLETE' THEN IF o.target_type='execution_credit'THEN PERFORM twuanis_canonical_private.assert_execution_credit_delivery(o.id);ELSIF o.target_type='addon' THEN
 SELECT id INTO STRICT aid FROM twuanis_canonical_private.offer_paid_acknowledgements WHERE order_id=o.id AND source='onvo';
 result:=twuanis_canonical_private.fulfill_addon(o.id,(SELECT payment_event_id FROM twuanis_canonical_private.offer_paid_acknowledgements WHERE id=aid),o.account_id,o.product_id,(o.resolved_terms->>'configurationId')::uuid,CASE WHEN o.job_id IS NOT NULL THEN 'operation' WHEN o.listing_id IS NOT NULL THEN 'listing' ELSE 'account' END,coalesce(o.listing_id,o.job_id,o.account_id),jsonb_build_object('currency',o.currency,'amount',o.resolved_terms->>'total'));
 ELSE PERFORM twuanis_canonical_private.assert_package_delivery(o.id,NULL);END IF;RETURN jsonb_build_object('state','COMPLETE','replayed',true);END IF;
 SELECT id INTO STRICT aid FROM twuanis_canonical_private.offer_paid_acknowledgements WHERE order_id=o.id AND source='onvo';
 IF o.target_type='addon' THEN
 -- Reuse the same private paid-source issuer as manual SINPE; pending publication is not delivery.
 result:=twuanis_canonical_private.fulfill_addon(o.id,(SELECT payment_event_id FROM twuanis_canonical_private.offer_paid_acknowledgements WHERE id=aid),o.account_id,o.product_id,(o.resolved_terms->>'configurationId')::uuid,CASE WHEN o.job_id IS NOT NULL THEN 'operation' WHEN o.listing_id IS NOT NULL THEN 'listing' ELSE 'account' END,coalesce(o.listing_id,o.job_id,o.account_id),jsonb_build_object('currency',o.currency,'amount',o.resolved_terms->>'total'));
 IF result->>'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'add-on fulfillment pending';END IF;
 result:=jsonb_build_object('state','COMPLETE','evidence',result);
 UPDATE twuanis_canonical_private.onvo_fulfillment_jobs SET state='COMPLETE' WHERE order_id=o.id;
 ELSIF o.target_type='execution_credit'THEN
 result:=twuanis_canonical_private.commit_execution_credit_purchase(o.id,aid,o.id);PERFORM twuanis_canonical_private.assert_execution_credit_delivery(o.id);result:=result||jsonb_build_object('state','COMPLETE');UPDATE twuanis_canonical_private.onvo_fulfillment_jobs SET state='COMPLETE'WHERE order_id=o.id;
 ELSE
 PERFORM pg_advisory_xact_lock(3200,hashtext(o.id::text));SELECT id INTO tid FROM twuanis_canonical_private.entitlement_terms WHERE order_id=o.id;
 IF tid IS NULL THEN
 SELECT * INTO STRICT c FROM twuanis_canonical_private.intelligence_package_configurations WHERE id=(o.resolved_terms->>'configurationId')::uuid AND package_id=o.product_id;
 IF o.target_type<>'package' OR o.resolved_terms->'terms'->'capabilities' IS DISTINCT FROM to_jsonb(c.capabilities) OR o.resolved_terms->'terms'->>'quantity'<>'1' OR o.resolved_terms->'terms'->>'unit' NOT IN('day','month') THEN RAISE EXCEPTION 'pinned Package contract mismatch';END IF;
 IF o.resolved_terms->'terms'->>'unit'='day' AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.package_daily_access_prices dp WHERE dp.package_id=o.product_id AND dp.currency=CASE WHEN o.currency='CRC'AND o.resolved_terms?'fx'THEN 'USD'ELSE o.currency END AND(CASE WHEN o.currency='CRC'AND o.resolved_terms?'fx'THEN round(dp.amount*(SELECT rate FROM public.fx_rates WHERE base_currency='USD'AND quote_currency='CRC'AND rate_type='reference_sale'AND source='BCCR'AND effective_date<=(o.created_at AT TIME ZONE 'America/Costa_Rica')::date ORDER BY effective_date DESC LIMIT 1),0)ELSE dp.amount END)=(o.resolved_terms->>'total')::numeric AND version=(o.resolved_terms->>'purchaseOptionVersion')::integer) THEN
 -- A discounted day remains valid only with the exact immutable membership-price proof.
 SELECT CASE WHEN o.currency='CRC'AND o.resolved_terms?'fx'THEN round(dp.amount*(SELECT rate FROM public.fx_rates WHERE base_currency='USD'AND quote_currency='CRC'AND rate_type='reference_sale'AND source='BCCR'AND effective_date<=(o.created_at AT TIME ZONE 'America/Costa_Rica')::date ORDER BY effective_date DESC LIMIT 1),0)ELSE dp.amount END
 INTO STRICT amount FROM twuanis_canonical_private.package_daily_access_prices dp
 WHERE dp.package_id=o.product_id AND dp.currency=CASE WHEN o.currency='CRC'AND o.resolved_terms?'fx'THEN 'USD'ELSE o.currency END AND dp.version=(o.resolved_terms->>'purchaseOptionVersion')::integer;
 result:=twuanis_canonical_private.membership_introductory_price(o.account_id,'package',o.product_id,o.currency,o.created_at,twuanis_canonical_private.membership_duration(o.resolved_terms->'terms'),1,'PRIVATE',o.resolved_terms->'terms');
 IF amount IS NULL OR result IS NULL OR o.resolved_terms->'founderProtection' IS DISTINCT FROM(result||jsonb_build_object('publicTotal',amount::text)) OR(o.resolved_terms->>'total')::numeric IS DISTINCT FROM least(amount,(result->>'total')::numeric) THEN
 RAISE EXCEPTION 'canonical daily protected-price proof required';END IF;
 END IF;
 SELECT starts_at,ends_at INTO start_at,end_at FROM twuanis_canonical_private.purchased_package_interval(o.account_id,o.product_id,o.resolved_terms->'terms'->>'unit',1,clock_timestamp());
 tid:=twuanis_canonical_private.commit_entitlement_term(o.account_id,'PACKAGE',o.product_id,c.id,NULL,'PURCHASED',o.id,aid,NULL,o.id,start_at,end_at,NULL,NULL);END IF;
 tid:=twuanis_canonical_private.assert_package_delivery(o.id,NULL);
 result:=jsonb_build_object('state','COMPLETE','termId',tid);UPDATE twuanis_canonical_private.onvo_fulfillment_jobs SET state='COMPLETE' WHERE order_id=o.id;
 END IF;
 EXCEPTION WHEN OTHERS THEN result:=jsonb_build_object('state','PENDING','reason','fulfillment_revalidation_failed');UPDATE twuanis_canonical_private.onvo_fulfillment_jobs SET state='PENDING' WHERE order_id=o.id;END;
 UPDATE twuanis_canonical_private.onvo_fulfillment_jobs SET attempts=attempts+1,next_attempt=clock_timestamp()+interval '1 minute' WHERE order_id=o.id;
 INSERT INTO twuanis_canonical_private.onvo_fulfillment_attempts(order_id,result)VALUES(o.id,result);RETURN result;
 ELSE RAISE EXCEPTION 'unknown ONVO operation';END IF;
END$_$;


--
-- Name: orchestrator_execution_claim(jsonb, uuid, uuid, text, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.orchestrator_execution_claim(p_claims jsonb, p_request uuid, p_execution uuid, p_orchestrator text, p_population text, p_question jsonb, p_worker uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE transport text:=current_setting('request.jwt.claims',true);a uuid;authority jsonb;x twuanis_canonical_private.execution_credit_executions%ROWTYPE;j twuanis_canonical_private.orchestrator_execution_claims%ROWTYPE;r jsonb;rid uuid;
BEGIN
 a:=twuanis_canonical_private.execution_credit_bridge(p_claims);
 authority:=twuanis_canonical_private.execution_credit_authority(p_orchestrator,p_population);
 IF p_worker IS NULL THEN RAISE EXCEPTION 'Trusted worker required';END IF;
 -- Account lock comes from the existing bridge. Bound active work independently
 -- of token quantity; retries of the same reserved execution remain admissible.
 IF NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.execution_credit_executions WHERE id=p_execution AND account_id=a)
 AND (SELECT count(*) FROM twuanis_canonical_private.orchestrator_execution_claims claim_row JOIN twuanis_canonical_private.execution_credit_executions ex ON ex.id=claim_row.execution_id WHERE ex.account_id=a AND claim_row.lease_until>clock_timestamp() AND twuanis_canonical_private.execution_credit_execution_state(ex.id)='RESERVED')>=2
 THEN RAISE EXCEPTION 'Two active orchestrator executions per account maximum' USING ERRCODE='54000';END IF;
 PERFORM set_config('request.jwt.claims',transport,true);
 r:=public.execution_credit_service(p_claims,p_request,jsonb_build_object('operation','reserve','execution',p_execution,'orchestrator',p_orchestrator,'population',p_population,'request',p_question));
 SELECT * INTO STRICT x FROM twuanis_canonical_private.execution_credit_executions WHERE id=p_execution AND account_id=a;
 IF x.authority IS DISTINCT FROM authority THEN RAISE EXCEPTION 'Execution authority changed' USING ERRCODE='42501';END IF;
 SELECT id INTO rid FROM twuanis_canonical_private.execution_credit_reports WHERE execution_id=x.id;
 IF rid IS NOT NULL THEN RETURN r||jsonb_build_object('state',twuanis_canonical_private.execution_credit_execution_state(x.id),'report',rid,'reason',(SELECT metadata->>'reason' FROM twuanis_canonical_private.execution_credit_events WHERE execution_id=x.id AND kind='RESERVATION_RELEASED'),'resumeCommit',true);END IF;
 IF twuanis_canonical_private.execution_credit_execution_state(x.id)<>'RESERVED' OR x.lease_until<=clock_timestamp() THEN
  -- A replayed reserve receipt must not leave an expired hold in the ledger.
  -- Reuse canonical maintenance under the existing account advisory lock.
  PERFORM twuanis_canonical_private.execution_credit_maintain(a,p_request);
  RETURN r||jsonb_build_object('state','RELEASED');
 END IF;
 SELECT * INTO j FROM twuanis_canonical_private.orchestrator_execution_claims WHERE execution_id=x.id FOR UPDATE;
 IF FOUND THEN
  IF j.lease_until>clock_timestamp() THEN RETURN jsonb_build_object('state','WORKING','execution',x.id);END IF;
  IF j.attempt>=3 THEN RAISE EXCEPTION 'Execution retry limit reached';END IF;
  UPDATE twuanis_canonical_private.orchestrator_execution_claims SET worker=p_worker,lease_until=least(clock_timestamp()+interval'3 minutes',x.lease_until),attempt=attempt+1 WHERE execution_id=x.id;
 ELSE INSERT INTO twuanis_canonical_private.orchestrator_execution_claims(execution_id,worker,lease_until)VALUES(x.id,p_worker,least(clock_timestamp()+interval'3 minutes',x.lease_until));END IF;
 RETURN jsonb_build_object('state','CLAIMED','execution',x.id,'authority',authority,'createdAt',x.reserved_at);
END$$;


--
-- Name: orchestrator_execution_claim_v2(jsonb, uuid, uuid, text, text, jsonb, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.orchestrator_execution_claim_v2(p_claims jsonb, p_request uuid, p_execution uuid, p_orchestrator text, p_population text, p_question jsonb, p_worker uuid, p_release text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE r jsonb;j twuanis_canonical_private.orchestrator_execution_claims%ROWTYPE;secret text;BEGIN
 IF NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.orchestrator_methodology_releases WHERE id=p_release) THEN RAISE EXCEPTION 'WITNESS_UNAPPROVED_RELEASE';END IF;
 r:=public.orchestrator_execution_claim(p_claims,p_request,p_execution,p_orchestrator,p_population,p_question,p_worker);
 IF r->>'state'<>'CLAIMED' THEN RETURN r;END IF;
 SELECT * INTO STRICT j FROM twuanis_canonical_private.orchestrator_execution_claims WHERE execution_id=p_execution AND worker=p_worker FOR UPDATE;
 secret:=encode(extensions.gen_random_bytes(32),'hex');
 INSERT INTO twuanis_canonical_private.orchestrator_witness_attempts VALUES(p_execution,j.attempt,p_worker,j.lease_until,p_release,encode(sha256(convert_to(secret,'UTF8')),'hex'));
 RETURN r||jsonb_build_object('captureCapability',secret,'attempt',j.attempt,'release',p_release);
END$$;


--
-- Name: orchestrator_execution_commit(jsonb, uuid, uuid, uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.orchestrator_execution_commit(p_claims jsonb, p_execution uuid, p_worker uuid, p_report uuid, p_body jsonb, p_settlement uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE transport text:=current_setting('request.jwt.claims',true);a uuid;x twuanis_canonical_private.execution_credit_executions%ROWTYPE;r jsonb;existing uuid;
BEGIN
 a:=twuanis_canonical_private.execution_credit_bridge(p_claims);
 SELECT * INTO STRICT x FROM twuanis_canonical_private.execution_credit_executions WHERE id=p_execution AND account_id=a;
 PERFORM pg_advisory_xact_lock(3512,hashtext(a::text));
 IF coalesce(p_body,(SELECT body FROM twuanis_canonical_private.execution_credit_reports WHERE execution_id=x.id))->>'format'='twuanis-orchestrator-evidence-v2' AND coalesce(p_body,(SELECT body FROM twuanis_canonical_private.execution_credit_reports WHERE execution_id=x.id))#>>'{accounting,settlementRequestId}' IS DISTINCT FROM p_settlement::text THEN RAISE EXCEPTION 'WITNESS_SETTLEMENT_IDENTITY';END IF;
 IF x.authority IS DISTINCT FROM twuanis_canonical_private.execution_credit_authority(x.orchestrator_id,x.population)THEN RAISE EXCEPTION 'Current execution authority required' USING ERRCODE='42501';END IF;
 SELECT id INTO existing FROM twuanis_canonical_private.execution_credit_reports WHERE execution_id=x.id;
 IF existing IS NULL AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.orchestrator_execution_claims WHERE execution_id=x.id AND worker=p_worker AND lease_until>clock_timestamp())THEN RAISE EXCEPTION 'Current worker claim required';END IF;
 IF existing IS NULL THEN PERFORM set_config('request.jwt.claims',transport,true);PERFORM public.record_execution_credit_report(p_claims,x.id,p_report,p_body);
 ELSIF existing IS DISTINCT FROM p_report THEN RAISE EXCEPTION 'Report identity conflict';
 ELSIF p_body IS NOT NULL THEN PERFORM set_config('request.jwt.claims',transport,true);PERFORM public.record_execution_credit_report(p_claims,x.id,p_report,p_body);END IF;
 PERFORM set_config('request.jwt.claims',transport,true);
 r:=public.execution_credit_service(p_claims,p_settlement,jsonb_build_object('operation','settle','execution',x.id));
 RETURN r;
END$$;


--
-- Name: orchestrator_witness_finalize(jsonb, uuid, uuid, integer, text, uuid, uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.orchestrator_witness_finalize(p_claims jsonb, p_execution uuid, p_worker uuid, p_attempt integer, p_capture text, p_report uuid, p_settlement uuid, p_transcript jsonb, p_envelope jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a uuid;x twuanis_canonical_private.execution_credit_executions%ROWTYPE;w twuanis_canonical_private.orchestrator_witness_attempts%ROWTYPE;old twuanis_canonical_private.orchestrator_execution_witnesses%ROWTYPE;rid uuid;BEGIN
 a:=twuanis_canonical_private.execution_credit_bridge(p_claims);
 SELECT * INTO STRICT x FROM twuanis_canonical_private.execution_credit_executions WHERE id=p_execution AND account_id=a;
 PERFORM pg_advisory_xact_lock(3512,hashtext(a::text));
 IF x.authority IS DISTINCT FROM twuanis_canonical_private.execution_credit_authority(x.orchestrator_id,x.population) THEN RAISE EXCEPTION 'WITNESS_AUTHORITY_CHANGED';END IF;
 SELECT * INTO STRICT w FROM twuanis_canonical_private.orchestrator_witness_attempts WHERE execution_id=x.id AND attempt=p_attempt;
 IF p_capture IS NULL OR w.capture_digest<>encode(sha256(convert_to(p_capture,'UTF8')),'hex') OR w.worker IS DISTINCT FROM p_worker THEN RAISE EXCEPTION 'WITNESS_CAPTURE_CAPABILITY_REQUIRED' USING ERRCODE='42501';END IF;
 SELECT * INTO old FROM twuanis_canonical_private.orchestrator_execution_witnesses WHERE execution_id=x.id AND attempt=p_attempt;
 IF FOUND THEN
 IF (old.report_id,old.settlement_id,old.transcript,old.envelope) IS DISTINCT FROM (p_report,p_settlement,p_transcript,p_envelope) THEN RAISE EXCEPTION 'WITNESS_IMMUTABLE_CONFLICT';END IF;
 RETURN jsonb_build_object('id',old.id,'replayed',true);END IF;
 IF twuanis_canonical_private.execution_credit_execution_state(x.id)<>'RESERVED' OR x.lease_until<=clock_timestamp() OR w.lease_until<=clock_timestamp() OR NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.orchestrator_execution_claims j WHERE j.execution_id=x.id AND j.worker=w.worker AND j.attempt=w.attempt AND j.lease_until>clock_timestamp()) THEN RAISE EXCEPTION 'WITNESS_CURRENT_ATTEMPT_REQUIRED';END IF;
 IF p_report IS NULL OR p_settlement IS NULL OR p_transcript->>'schema' IS DISTINCT FROM 'twuanis-analytical-evidence-v2' OR p_envelope#>'{evidence,methodology}' IS DISTINCT FROM (SELECT manifest->'methodology' FROM twuanis_canonical_private.orchestrator_methodology_releases WHERE id=w.release_id) THEN RAISE EXCEPTION 'WITNESS_RELEASE_OR_TRANSCRIPT_INVALID';END IF;
 IF octet_length(p_transcript::text)+octet_length(p_envelope::text)>33554432 THEN RAISE EXCEPTION 'WITNESS_RESOURCE_LIMIT';END IF;
 PERFORM twuanis_canonical_private.evidence_v2_validate(p_envelope||jsonb_build_object('immutableEvidence',p_transcript,'methodologyRelease',w.release_id),p_execution,p_report,a);
 -- Capture stores full inspectable JSONB; report hashes are not its authority.
 INSERT INTO twuanis_canonical_private.orchestrator_execution_witnesses(execution_id,attempt,report_id,settlement_id,transcript,envelope) VALUES(x.id,w.attempt,p_report,p_settlement,p_transcript,p_envelope) RETURNING id INTO rid;
 RETURN jsonb_build_object('id',rid,'attempt',w.attempt,'release',w.release_id);
END$$;


--
-- Name: owner_support_email_test(text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.owner_support_email_test(p_operation text, p_actor uuid, p_token uuid DEFAULT NULL::uuid, p_message text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET statement_timeout TO '5s'
    AS $_$
DECLARE v_token uuid; r twuanis_canonical_private.owner_support_email_test_once%ROWTYPE;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.owner_access_grants g JOIN auth.users u ON u.id=g.user_id WHERE g.user_id=p_actor AND g.revoked_at IS NULL AND u.deleted_at IS NULL AND u.email_confirmed_at IS NOT NULL AND (u.banned_until IS NULL OR u.banned_until<=clock_timestamp())) THEN RAISE insufficient_privilege; END IF;
 IF p_operation='claim' THEN
  IF p_token IS NOT NULL OR p_message IS NOT NULL THEN RAISE invalid_parameter_value; END IF;
  INSERT INTO twuanis_canonical_private.owner_support_email_test_once(singleton,actor,token,state) VALUES(true,p_actor,gen_random_uuid(),'CONSUMED') ON CONFLICT(singleton) DO NOTHING RETURNING token INTO v_token;
  RETURN jsonb_build_object('token',v_token);
 ELSIF p_operation='finish' THEN
  IF p_message IS NOT NULL AND p_message!~'^[0-9a-fA-F-]{36}$' THEN RAISE invalid_parameter_value; END IF;
  SELECT * INTO r FROM twuanis_canonical_private.owner_support_email_test_once WHERE singleton AND actor=p_actor AND token=p_token FOR UPDATE;
  IF NOT FOUND OR r.state<>'CONSUMED' THEN RAISE insufficient_privilege; END IF;
  UPDATE twuanis_canonical_private.owner_support_email_test_once SET finished_at=clock_timestamp(),provider_message_id=p_message,state=CASE WHEN p_message IS NULL THEN 'UNCONFIRMED_DISABLED' ELSE 'ACCEPTED_DISABLED' END WHERE singleton;
  RETURN jsonb_build_object('disabled',true);
 ELSE RAISE invalid_parameter_value; END IF;
END$_$;


