 IF p_operation='claim' THEN
  IF p_token IS NOT NULL OR p_message IS NOT NULL THEN RAISE invalid_parameter_value; END IF;
  INSERT INTO twuanis_canonical_private.owner_webhook_acceptance_test_once(singleton,actor,token,state) VALUES(true,p_actor,gen_random_uuid(),'CONSUMED') ON CONFLICT(singleton) DO NOTHING RETURNING token INTO v_token;
  RETURN jsonb_build_object('token',v_token);
 ELSIF p_operation='finish' THEN
  IF p_message IS NOT NULL AND p_message!~'^[0-9a-fA-F-]{36}$' THEN RAISE invalid_parameter_value; END IF;
  SELECT * INTO r FROM twuanis_canonical_private.owner_webhook_acceptance_test_once WHERE singleton AND actor=p_actor AND token=p_token FOR UPDATE;
  IF NOT FOUND OR r.state<>'CONSUMED' THEN RAISE insufficient_privilege; END IF;
  UPDATE twuanis_canonical_private.owner_webhook_acceptance_test_once SET finished_at=clock_timestamp(),provider_message_id=p_message,state=CASE WHEN p_message IS NULL THEN 'UNCONFIRMED_DISABLED' ELSE 'ACCEPTED_DISABLED' END WHERE singleton;
