--
-- Name: prepare_customer_addon_import(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_customer_addon_import(p_request uuid, p_rows jsonb) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$ SELECT public.prepare_customer_addon_import(p_request,p_rows,'USD'); $$;


--
-- Name: prepare_customer_addon_import(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_customer_addon_import(p_request uuid, p_rows jsonb, p_currency text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE actor uuid:=auth.uid();c uuid;fp text;j twuanis_canonical_private.addon_import_jobs%ROWTYPE;x record;accepted jsonb:='[]';rejected jsonb:='[]';evidence jsonb;rate numeric;quote jsonb;err text;
BEGIN
 IF actor IS NULL OR auth.jwt()->>'role' IS DISTINCT FROM 'authenticated' THEN RAISE EXCEPTION 'authenticated customer required'; END IF;
 IF p_currency IS NULL OR p_currency NOT IN('USD','CRC') THEN RAISE EXCEPTION 'explicit priced currency required';END IF;
 -- Transport bounds are operational limits, not pricing tiers.
 IF p_request IS NULL OR jsonb_typeof(p_rows) IS DISTINCT FROM 'array' OR jsonb_array_length(p_rows) NOT BETWEEN 1 AND 2048 OR octet_length(p_rows::text)>2097152 THEN RAISE EXCEPTION 'bounded batch required'; END IF;
 fp:=encode(sha256(convert_to(jsonb_build_array(p_currency,p_rows)::text,'UTF8')),'hex');
 PERFORM pg_advisory_xact_lock(3152,hashtext(jsonb_build_array(actor,p_request)::text));
 SELECT * INTO j FROM twuanis_canonical_private.addon_import_jobs WHERE account_id=actor AND request_id=p_request;
 IF FOUND THEN IF j.validator_version<>'canonical-customer-free-v1' THEN RAISE EXCEPTION 'historical paid job is immutable'; END IF; IF j.input_fingerprint<>fp THEN RAISE EXCEPTION 'immutable job request conflict'; END IF;
  RETURN jsonb_build_object('jobId',j.id,'submitted',j.submitted_count,'accepted',j.accepted_count,'rejected',j.rejected_rows,'currency',j.currency,'unitRate',j.unit_rate::text,'total',j.total::text,'free',true,'quotable',false,'acquisitionAvailable',false,'replayed',true); END IF;
 SELECT current_configuration_id INTO STRICT c FROM twuanis_canonical_private.addon_products WHERE id='addon-bulk-listing-import' FOR SHARE;
 FOR x IN SELECT value,ordinality FROM jsonb_array_elements(p_rows) WITH ORDINALITY LOOP
  BEGIN
   PERFORM twuanis_canonical_private.addon_customer_input(x.value);
   accepted:=accepted||jsonb_build_array(jsonb_build_object('rowId',md5('free-create:'||actor::text||x.value::text)::uuid,'publicationRequest',md5('free-publish:'||actor::text||x.value::text)::uuid,'input',x.value,'row',x.ordinality));
  EXCEPTION WHEN SQLSTATE 'P0001' OR SQLSTATE 'P0002' OR SQLSTATE 'P0003' OR SQLSTATE '22023' OR SQLSTATE '23514' OR SQLSTATE '22003' OR SQLSTATE '22000' THEN
   GET STACKED DIAGNOSTICS err=MESSAGE_TEXT;
   rejected:=rejected||jsonb_build_array(jsonb_build_object('row',x.ordinality,'code','canonical_input_rejected'));
  END;
 END LOOP;
 IF jsonb_array_length(accepted)=0 THEN RAISE EXCEPTION 'no accepted rows'; END IF;
 evidence:=twuanis_canonical_private.addon_publication_capacity(actor,jsonb_array_length(accepted));
 INSERT INTO twuanis_canonical_private.addon_import_jobs(account_id,request_id,configuration_id,submitted_count,accepted_count,input_fingerprint,validator_version,accepted_rows,rejected_rows,publication_evidence,currency,unit_rate,total)
 VALUES(actor,p_request,c,jsonb_array_length(p_rows),jsonb_array_length(accepted),fp,'canonical-customer-free-v1',accepted,rejected,evidence,p_currency,NULL,NULL) RETURNING * INTO j;
 RETURN jsonb_build_object('jobId',j.id,'submitted',j.submitted_count,'accepted',j.accepted_count,'rejected',j.rejected_rows,'currency',j.currency,'unitRate',j.unit_rate::text,'total',j.total::text,'free',true,'quotable',false,'acquisitionAvailable',false,'replayed',false);
END $$;


--
-- Name: prepare_customer_duplicate(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_customer_duplicate(p_source uuid, p_request uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE actor uuid:=auth.uid(); l public.listings%ROWTYPE; cmd twuanis_canonical_private.duplicate_commands%ROWTYPE;
 input jsonb; geo jsonb; sem jsonb; facts jsonb:='{}'; measurements jsonb:='{}'; f record; v jsonb;
 result jsonb; media jsonb:='[]'; paths jsonb; item text; i integer:=0; creation_request uuid:=gen_random_uuid(); classified jsonb:='{}'; rules uuid[]; dim text; domain_group text;
BEGIN
 IF actor IS NULL THEN RAISE EXCEPTION 'authenticated owner required' USING ERRCODE='42501'; END IF;
 IF p_source IS NULL OR p_request IS NULL THEN RAISE EXCEPTION 'source and request required' USING ERRCODE='22023'; END IF;
 -- Same order as canonical creation: policy/publisher before operation and listing locks.
 PERFORM twuanis_canonical_private.ensure_publisher_account(actor);
 PERFORM pg_advisory_xact_lock(3113,hashtext(jsonb_build_array(actor,p_request)::text));
 SELECT * INTO cmd FROM twuanis_canonical_private.duplicate_commands WHERE owner_id=actor AND request_id=p_request;
 IF FOUND THEN
  IF cmd.source_id<>p_source THEN RAISE EXCEPTION 'duplicate request conflict' USING ERRCODE='22023'; END IF;
  RETURN jsonb_build_object('listing_id',cmd.listing_id::text,'media',cmd.media,'completed',cmd.completed);
 END IF;
 SELECT * INTO l FROM public.listings WHERE id=p_source AND owner_id=actor FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'owned source required' USING ERRCODE='42501'; END IF;
 IF l.canonical_domain_version IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'source requires canonical evidence adapter' USING ERRCODE='55000'; END IF;
 SELECT jsonb_object_agg(t.term_type,t.official_code) INTO geo FROM public.listing_membership_origins m JOIN public.ontology_terms t ON t.id=m.ontology_term_id WHERE m.listing_id=l.id AND m.origin_domain='geography' AND t.term_type IN ('province','canton','district');
 SELECT jsonb_object_agg(dimension,ids) INTO sem FROM (SELECT dimension,jsonb_agg(ontology_term_id::text ORDER BY ontology_term_id) ids FROM public.listing_semantic_selections WHERE listing_id=l.id GROUP BY dimension)s;
 FOR f IN SELECT * FROM public.listing_fact_evidence WHERE listing_id=l.id LOOP
  v:=CASE f.kind WHEN 'exact' THEN jsonb_build_object('kind','exact','value',f.exact_value::text)
   WHEN 'category' THEN jsonb_build_object('kind','category','term',f.category_term_id::text)
   ELSE jsonb_build_object('kind','range','lower',f.range_lower::text,'upper',f.range_upper::text,'lower_inclusive',f.lower_inclusive,'upper_inclusive',f.upper_inclusive) END;
  facts:=facts||jsonb_build_object(f.dimension,v);
 END LOOP;
 IF l.property_area IS NOT NULL THEN measurements:=measurements||jsonb_build_object('property_area',jsonb_build_object('value',l.property_area::text)); END IF;
 IF l.construction_area IS NOT NULL THEN measurements:=measurements||jsonb_build_object('construction_area',jsonb_build_object('value',l.construction_area::text)); END IF;
 input:=jsonb_build_object('transaction',l.transaction_type,'geography',geo,'semantics',sem,'facts',facts,'measurements',measurements,
  'content',jsonb_strip_nulls(jsonb_build_object('title',left(coalesce(nullif(l.title,''),'Listing')||' — Copy',512),'description',l.description,'whatsapp',l.whatsapp)));
 IF (CASE l.transaction_type WHEN 'sale' THEN l.current_price ELSE l.monthly_price END) IS NOT NULL THEN
  input:=input||jsonb_build_object('money',jsonb_build_object('amount',(CASE l.transaction_type WHEN 'sale' THEN l.current_price ELSE l.monthly_price END)::text,'currency',l.currency));
 END IF;
 IF l.listing_origin IS DISTINCT FROM 'customer' OR l.listing_source_type IS DISTINCT FROM 'customer' OR l.source_name IS NOT NULL OR l.source_listing_id IS NOT NULL THEN RAISE EXCEPTION 'customer source provenance required' USING ERRCODE='42501'; END IF;
 -- Preserve only customer-owned source objects. Never accept URL/shared paths.
 IF l.images IS NULL OR btrim(l.images::text)='' THEN paths:='[]';
 ELSE BEGIN paths:=l.images::text::jsonb; EXCEPTION WHEN invalid_text_representation THEN paths:=to_jsonb(string_to_array(l.images::text,'|')); END; END IF;
 IF jsonb_typeof(paths)='string' THEN paths:=jsonb_build_array(paths); END IF;
 IF jsonb_typeof(paths)<>'array' OR jsonb_array_length(paths)>25 THEN RAISE EXCEPTION 'invalid source media' USING ERRCODE='22023'; END IF;
 FOR v IN SELECT value FROM jsonb_array_elements(paths) LOOP
  item:=v#>>'{}';
  IF jsonb_typeof(v)<>'string' OR item NOT LIKE (actor::text||'/'||l.id::text||'/%') OR item ~ '(^|/)[.][.]?(/|$)' OR item ~ '[\\]' OR item ~ '[?#]' OR item !~ ('^'||actor::text||'/'||l.id::text||'/[a-zA-Z0-9_-]+[.]jpg$') OR length(item)>1024 THEN RAISE EXCEPTION 'source media ownership invalid' USING ERRCODE='42501'; END IF;
 END LOOP;
 -- Rule policy is read from the source, never supplied by the caller.
 FOR f IN SELECT origin_domain,array_agg(DISTINCT r.rule_set_id) sets
 FROM public.listing_membership_origins m JOIN public.listing_classification_rules r ON r.id=m.classification_rule_id
 WHERE m.listing_id=l.id AND m.classification_rule_id IS NOT NULL GROUP BY origin_domain LOOP
  dim:=f.origin_domain;rules:=f.sets;
  IF cardinality(rules)<>1 THEN RAISE EXCEPTION 'ambiguous recorded classification' USING ERRCODE='55000'; END IF;
  IF NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.classification_seals z JOIN public.listing_classification_rule_sets r ON r.id=z.rule_set_id WHERE r.id=rules[1] AND r.domain=dim) THEN RAISE EXCEPTION 'recorded sealed typed rule required' USING ERRCODE='55000'; END IF;
  domain_group:=CASE WHEN dim IN ('property_area','construction_area') THEN 'measurements' ELSE 'facts' END;
  v:=input->domain_group->dim;
  IF v IS NULL OR (domain_group='facts' AND v->>'kind' IS DISTINCT FROM 'exact') THEN RAISE EXCEPTION 'recorded rule without exact evidence' USING ERRCODE='55000'; END IF;
  IF domain_group='facts' THEN v:=v||'{"source":"owner"}'::jsonb; END IF;
  classified:=classified||jsonb_build_object(domain_group,coalesce(classified->domain_group,'{}')||jsonb_build_object(dim,v||jsonb_build_object('rule_set',rules[1]::text)));
 END LOOP;
 -- Private request avoids colliding with ordinary customer creation requests.
 result:=twuanis_canonical_private.s4_create_core(actor,creation_request,input,NULL);
 IF classified<>'{}'::jsonb THEN
  PERFORM twuanis_canonical_private.s3_command((result->>'listing_id')::uuid,1,'owner',actor::text,gen_random_uuid(),classified,NULL);
 END IF;
 FOR item IN SELECT value FROM jsonb_array_elements_text(paths) LOOP
  i:=i+1;
  media:=media||jsonb_build_array(jsonb_build_object('source',item,'destination',actor::text||'/'||(result->>'listing_id')||'/duplicate-'||gen_random_uuid()::text||'.jpg'));
 END LOOP;
 INSERT INTO twuanis_canonical_private.duplicate_commands(owner_id,request_id,source_id,listing_id,creation_receipt,media)
 VALUES(actor,p_request,p_source,(result->>'listing_id')::uuid,(result->>'receipt_id')::uuid,media);
 RETURN jsonb_build_object('listing_id',result->>'listing_id','media',media,'completed',false);
END $_$;


--
-- Name: prepare_listing_submission_token(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_listing_submission_token(p_owner uuid, p_request uuid, p_phone text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE t twuanis_canonical_private.listing_submission_requests; value text:=gen_random_uuid()::text; BEGIN
 IF p_owner IS NULL OR p_request IS NULL OR p_payload->'publication_delivery'->>'account_id' IS DISTINCT FROM p_owner::text THEN RAISE EXCEPTION 'Authenticated submission identity required'; END IF;
 PERFORM pg_advisory_xact_lock(3148,hashtext(p_owner::text||p_request::text));
 SELECT * INTO t FROM twuanis_canonical_private.listing_submission_requests WHERE owner_id=p_owner AND request_id=p_request;
 IF FOUND THEN IF t.phone IS DISTINCT FROM p_phone OR t.payload IS DISTINCT FROM p_payload THEN RAISE EXCEPTION 'Submission request payload conflict'; END IF; RETURN jsonb_build_object('token',t.token,'replayed',true); END IF;
 INSERT INTO public.listing_publish_tokens(token,phone,listing_data,verified)VALUES(value,p_phone,p_payload,false);
 INSERT INTO twuanis_canonical_private.listing_submission_requests VALUES(p_owner,p_request,p_phone,p_payload,value);
 RETURN jsonb_build_object('token',value,'replayed',false);
END $$;


--
-- Name: prepare_ordinary_upload(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_ordinary_upload(p_owner uuid, p_listing uuid, p_bytes integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE l public.listings%ROWTYPE; op twuanis_canonical_private.ordinary_upload_operations%ROWTYPE; oid uuid:=gen_random_uuid();
BEGIN
 SELECT * INTO l FROM public.listings WHERE id=p_listing FOR UPDATE;
 IF NOT FOUND OR p_owner IS NULL OR l.owner_id IS DISTINCT FROM p_owner OR l.listing_status IS NULL OR l.listing_status='deleted' OR (l.canonical_domain_version IS NOT NULL AND l.canonical_domain_version<>1) THEN RAISE EXCEPTION 'owned eligible listing required' USING ERRCODE='42501';END IF;
 INSERT INTO twuanis_canonical_private.ordinary_upload_operations(id,owner_id,listing_id,storage_path,byte_size)
 VALUES(oid,p_owner,p_listing,p_owner::text||'/'||p_listing::text||'/upload-'||oid::text||'.jpg',p_bytes) RETURNING * INTO op;
 RETURN to_jsonb(op);
END $$;


--
-- Name: prepare_token_canonical_listing(text, uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_token_canonical_listing(p_token text, p_owner uuid, p_snapshot jsonb, p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE t public.listing_publish_tokens%ROWTYPE;c twuanis_canonical_private.token_creation_commands%ROWTYPE;
 result jsonb;media jsonb:='[]';paths jsonb;v jsonb;item text;
BEGIN
 IF p_owner IS NULL OR p_token IS NULL OR p_token !~ '^[0-9a-f-]{36}$' THEN RAISE EXCEPTION 'explicit token/customer required' USING ERRCODE='22023';END IF;
 PERFORM twuanis_canonical_private.ensure_publisher_account(p_owner);
 SELECT * INTO t FROM public.listing_publish_tokens WHERE token=p_token FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'token not found' USING ERRCODE='42501';END IF;
 SELECT * INTO c FROM twuanis_canonical_private.token_creation_commands WHERE token=p_token;
 IF FOUND THEN
  IF c.owner_id<>p_owner THEN RAISE EXCEPTION 'token owner conflict' USING ERRCODE='42501';END IF;
  RETURN jsonb_build_object('listing_id',c.listing_id::text,'media',c.media,'completed',c.media_completed,'publication',c.publication_result,'transaction',(SELECT transaction_type FROM public.listings WHERE id=c.listing_id));
 END IF;
 IF t.published_at IS NOT NULL OR t.published_listing_id IS NOT NULL OR t.verified IS TRUE THEN RAISE EXCEPTION 'previously completed token is not new creation' USING ERRCODE='55000';END IF;
 IF p_snapshot IS NULL OR t.listing_data::jsonb IS DISTINCT FROM p_snapshot THEN RAISE EXCEPTION 'token input changed' USING ERRCODE='40001';END IF;
 paths:=coalesce(t.listing_data->'temporary_images','[]');
 IF jsonb_typeof(paths)<>'array' OR jsonb_array_length(paths)>25 OR coalesce(t.listing_data->'images','[]') IS DISTINCT FROM paths THEN RAISE EXCEPTION 'explicit managed temporary media required' USING ERRCODE='22023';END IF;
 FOR v IN SELECT value FROM jsonb_array_elements(paths) LOOP
  item:=v#>>'{}';
  IF jsonb_typeof(v)<>'string' OR item !~ ('^temporary/'||p_token||'/[a-zA-Z0-9_-]+[.]jpg$') THEN RAISE EXCEPTION 'token media provenance invalid' USING ERRCODE='42501';END IF;
 END LOOP;
 IF (SELECT count(*)<>count(DISTINCT value) FROM jsonb_array_elements(paths)) THEN RAISE EXCEPTION 'duplicate media source' USING ERRCODE='22023';END IF;
 result:=twuanis_canonical_private.s4_create_core(p_owner,gen_random_uuid(),p_input,NULL);
 FOR item IN SELECT value FROM jsonb_array_elements_text(paths) LOOP
  media:=media||jsonb_build_array(jsonb_build_object('source',item,'destination',p_owner::text||'/'||(result->>'listing_id')||'/token-'||gen_random_uuid()::text||'.jpg'));
 END LOOP;
 INSERT INTO twuanis_canonical_private.token_creation_commands(token,owner_id,listing_id,media) VALUES(p_token,p_owner,(result->>'listing_id')::uuid,media);
 UPDATE public.listing_publish_tokens SET claimed_at=clock_timestamp() WHERE id=t.id;
 RETURN jsonb_build_object('listing_id',result->>'listing_id','media',media,'completed',false,'publication',NULL,'transaction',p_input->>'transaction');
END $_$;


--
-- Name: prevent_promotion_event_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_promotion_event_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  raise exception
    'promotion_events is immutable: % operations are not permitted',
    tg_op;
end;
$$;


--
-- Name: protect_saved_analysis_evidence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_saved_analysis_evidence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$ BEGIN
 IF (NEW.id,NEW.user_id,NEW.engine_type,NEW.language,NEW.filters,NEW.result,NEW.schema_version,NEW.created_at) IS DISTINCT FROM (OLD.id,OLD.user_id,OLD.engine_type,OLD.language,OLD.filters,OLD.result,OLD.schema_version,OLD.created_at) THEN RAISE EXCEPTION 'Saved analytical evidence and authorization identity are immutable' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: publish_customer_canonical_listing(uuid, bigint, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_customer_canonical_listing(p_listing uuid, p_expected bigint, p_request uuid, p_event text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 RETURN twuanis_canonical_private.customer_publication_core(auth.uid(),p_listing,p_expected,p_request,p_event);
END $$;


--
-- Name: publish_token_canonical_listing(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_token_canonical_listing(p_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE actor uuid:=auth.uid();c twuanis_canonical_private.token_creation_commands%ROWTYPE;rev bigint;result jsonb;
BEGIN
 IF actor IS NULL THEN RAISE EXCEPTION 'authenticated customer required' USING ERRCODE='42501';END IF;
 PERFORM twuanis_canonical_private.resolve_publisher(actor);
 PERFORM 1 FROM public.listing_publish_tokens WHERE token=p_token FOR UPDATE;
 SELECT x.* INTO c FROM twuanis_canonical_private.token_creation_commands x JOIN public.listing_publish_tokens t ON t.token=x.token WHERE t.token=p_token AND x.owner_id=actor FOR UPDATE OF x;
 IF NOT FOUND THEN RAISE EXCEPTION 'owned token operation required' USING ERRCODE='42501';END IF;
 IF c.publication_result IS NOT NULL THEN RETURN c.publication_result;END IF;
 IF NOT c.media_completed THEN RAISE EXCEPTION 'complete token media first' USING ERRCODE='55000';END IF;
 SELECT canonical_revision INTO rev FROM public.listings WHERE id=c.listing_id;
 result:=public.publish_customer_canonical_listing(c.listing_id,rev,c.publication_request,'publish');
 IF result->>'admission' IN ('REVIEW_REQUIRED','AUTOMATIC_REJECTION') THEN RETURN result; END IF;
 UPDATE twuanis_canonical_private.token_creation_commands SET publication_result=result WHERE token=c.token;
 UPDATE public.listing_publish_tokens SET published_listing_id=c.listing_id,published_at=clock_timestamp(),verified=true,claimed_at=NULL WHERE token=c.token;
 RETURN result;
END $$;


--
-- Name: read_account_deletion_eligibility(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_account_deletion_eligibility() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE phase text;BEGIN
 IF NOT public.is_live_account() THEN RETURN jsonb_build_object('allowed',false,'phase','UNAVAILABLE');END IF;
 PERFORM twuanis_canonical_private.assert_account_deletable(auth.uid());
 SELECT CASE WHEN storage_ready_at IS NULL THEN 'CLEANUP_PENDING' ELSE 'STORAGE_READY' END INTO phase FROM twuanis_canonical_private.account_deletion_requests WHERE account_id=auth.uid();
 RETURN jsonb_build_object('allowed',true,'phase',coalesce(phase,'NONE'));
 EXCEPTION WHEN insufficient_privilege THEN RETURN jsonb_build_object('allowed',false,'phase','PROTECTED');
END$$;


--
-- Name: read_account_profile(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_account_profile() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE u uuid:=twuanis_canonical_private.account_actor(); p twuanis_canonical_private.account_profiles; s twuanis_canonical_private.account_phone_state;
BEGIN
 INSERT INTO twuanis_canonical_private.account_profiles(user_id) VALUES(u) ON CONFLICT DO NOTHING;
 INSERT INTO twuanis_canonical_private.account_phone_state(user_id) VALUES(u) ON CONFLICT DO NOTHING;
 SELECT * INTO p FROM twuanis_canonical_private.account_profiles WHERE user_id=u;
 SELECT * INTO s FROM twuanis_canonical_private.account_phone_state WHERE user_id=u;
 RETURN jsonb_build_object('userId',u,'name',p.display_name,'biography',p.biography,'language',p.language,'revision',p.revision,'imageId',p.active_image_id,'phone',s.phone_e164,'phoneRevision',s.revision);
END $$;


--
-- Name: read_account_profile_image(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_account_profile_image() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE u uuid:=twuanis_canonical_private.account_actor(); result jsonb;
BEGIN
 PERFORM public.read_account_profile();
 SELECT jsonb_build_object('revision',p.revision,'assetId',i.id,'hasImage',i.id IS NOT NULL) INTO result
 FROM twuanis_canonical_private.account_profiles p LEFT JOIN twuanis_canonical_private.account_profile_images i ON i.id=p.active_image_id AND i.user_id=p.user_id AND i.state='READY' AND i.validated_at IS NOT NULL WHERE p.user_id=u;
 RETURN result;
END $$;


--
-- Name: read_addon_catalog(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_addon_catalog(p_after text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v jsonb;
BEGIN
 IF length(p_after)>150 THEN RAISE EXCEPTION 'invalid cursor'; END IF;
 SELECT coalesce(jsonb_agg(twuanis_canonical_private.addon_projection(id)-ARRAY['revision','configurationId','version'] ORDER BY id),'[]') INTO v FROM
 (SELECT id FROM twuanis_canonical_private.addon_products WHERE (state='active' OR (id='addon-homepage-background' AND state='inactive')) AND (p_after IS NULL OR id>p_after) ORDER BY id LIMIT 26)q;
 RETURN v;
END $$;


--
-- Name: read_addon_homepage_ids(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_addon_homepage_ids() RETURNS uuid[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT coalesce(array_agg(id ORDER BY activated_at DESC,id),'{}'::uuid[]) FROM (
 SELECT l.id,max(current_term.starts_at) activated_at FROM twuanis_canonical_private.addon_placement_rights r JOIN twuanis_canonical_private.addon_products p ON p.id=r.product_id JOIN public.listings l ON l.id=r.listing_id
 JOIN LATERAL (SELECT t.starts_at FROM twuanis_canonical_private.entitlement_terms t
 WHERE t.listing_id=r.listing_id AND t.product_id=r.product_id AND t.account_id=r.account_id
 AND t.starts_at<=statement_timestamp() AND t.ends_at>statement_timestamp()
 AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.entitlement_revocations v WHERE v.term_id=t.id) AND EXISTS(SELECT 1 FROM twuanis_canonical_private.addon_placement_markets m WHERE m.term_id=t.id AND m.market=l.transaction_type)
 ORDER BY t.starts_at DESC LIMIT 1) current_term ON true
 WHERE p.behavior='homepage_carousel' AND r.effective_intervals @> statement_timestamp()
 AND l.owner_id=r.account_id AND l.listing_status='active' AND l.canonical_domain_version=1
 GROUP BY l.id ORDER BY activated_at DESC,l.id LIMIT 10)x
$$;


--
-- Name: read_addon_placement(uuid[], text, bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_addon_placement(p_ids uuid[], p_surface text, p_province bigint DEFAULT NULL::bigint, p_property_type bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE result jsonb;
BEGIN
 IF cardinality(p_ids)>512 OR p_surface IS NULL OR p_surface NOT IN ('buy','rent','swipe-buy','swipe-rent','homepage') THEN RAISE EXCEPTION 'bounded marketplace context required'; END IF;
 IF p_province IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ontology_terms WHERE id=p_province AND term_type='province' AND level=1) THEN RAISE EXCEPTION 'canonical province required'; END IF;
 IF p_property_type IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ontology_terms WHERE id=p_property_type AND term_type='property_type' AND level=1) THEN RAISE EXCEPTION 'canonical property type required'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('listingId',x.listing_id,'behavior',x.behavior,'activatedAt',x.activated_at) ORDER BY x.listing_id,x.behavior),'[]') INTO result FROM (
 SELECT r.listing_id,p.behavior,max(current_term.starts_at) AS activated_at FROM twuanis_canonical_private.addon_placement_rights r
 JOIN twuanis_canonical_private.addon_products p ON p.id=r.product_id JOIN public.listings l ON l.id=r.listing_id
 JOIN LATERAL (SELECT t.starts_at FROM twuanis_canonical_private.entitlement_terms t
 WHERE t.listing_id=r.listing_id AND t.product_id=r.product_id AND t.account_id=r.account_id
 AND t.starts_at<=statement_timestamp() AND t.ends_at>statement_timestamp()
 AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.entitlement_revocations v WHERE v.term_id=t.id) AND EXISTS(SELECT 1 FROM twuanis_canonical_private.addon_placement_markets m WHERE m.term_id=t.id AND m.market=l.transaction_type)
 ORDER BY t.starts_at DESC LIMIT 1) current_term ON true
 WHERE r.listing_id=ANY(p_ids) AND r.effective_intervals @> statement_timestamp()
 AND l.owner_id=r.account_id AND l.listing_status='active' AND l.canonical_domain_version=1
 AND (p_surface='homepage' OR (p_surface IN ('buy','swipe-buy') AND l.transaction_type='sale') OR (p_surface IN ('rent','swipe-rent') AND l.transaction_type='rent'))
 AND ((p_surface='homepage' AND p.behavior='homepage_carousel') OR (p_surface<>'homepage' AND (
 p.behavior IN ('featured_collection','priority_over_organic') OR
 (p_surface IN ('buy','rent') AND p.behavior='province_contextual_priority' AND p_province IS NOT NULL AND EXISTS(SELECT 1 FROM public.listings_ontology_terms WHERE listing_id=l.id AND ontology_term_id=p_province)) OR
 (p_surface IN ('buy','rent') AND p.behavior='property_type_contextual_priority' AND p_property_type IS NOT NULL AND EXISTS(SELECT 1 FROM public.listing_semantic_selections WHERE listing_id=l.id AND dimension='property_type' AND ontology_term_id=p_property_type)))))
 GROUP BY r.listing_id,p.behavior)x;
 RETURN result;
END $$;


--
-- Name: read_admin_navigation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_admin_navigation() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT public.is_live_account() AND(
 EXISTS(SELECT 1 FROM twuanis_canonical_private.owner_access_grants WHERE user_id=auth.uid() AND revoked_at IS NULL)
 OR EXISTS(SELECT 1 FROM twuanis_canonical_private.top_administrator WHERE user_id=auth.uid())
 OR EXISTS(SELECT 1 FROM twuanis_canonical_private.administrators WHERE user_id=auth.uid() AND active))
$$;


--
-- Name: read_advertising_listing_ids(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_advertising_listing_ids(p_market text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE result jsonb;
BEGIN
 IF p_market IS NULL OR p_market NOT IN('sale','rent')THEN RAISE EXCEPTION 'bounded advertising market required';END IF;
 WITH eligible AS(SELECT DISTINCT l.id,p.behavior,max(t.starts_at)activated_at FROM twuanis_canonical_private.addon_placement_rights r JOIN twuanis_canonical_private.addon_products p ON p.id=r.product_id JOIN public.listings l ON l.id=r.listing_id JOIN twuanis_canonical_private.entitlement_terms t ON t.listing_id=r.listing_id AND t.account_id=r.account_id AND t.product_id=r.product_id JOIN twuanis_canonical_private.addon_placement_markets m ON m.term_id=t.id AND m.market=p_market WHERE l.transaction_type=p_market AND l.listing_status='active'AND l.canonical_domain_version=1 AND l.owner_id=r.account_id AND p.behavior IN('homepage_carousel','featured_collection')AND r.effective_intervals @> statement_timestamp()AND t.starts_at<=statement_timestamp()AND t.ends_at>statement_timestamp()AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.entitlement_revocations v WHERE v.term_id=t.id)GROUP BY l.id,p.behavior),ranked AS(SELECT *,row_number()OVER(PARTITION BY behavior ORDER BY activated_at DESC,id)n FROM eligible)
 SELECT jsonb_build_object('spotlight',coalesce(jsonb_agg(id ORDER BY activated_at DESC,id)FILTER(WHERE behavior='homepage_carousel'AND n<=5),'[]'),'featured',coalesce(jsonb_agg(id ORDER BY activated_at DESC,id)FILTER(WHERE behavior='featured_collection'AND n<=12),'[]'))INTO result FROM ranked;RETURN result;
END$$;


--
-- Name: read_analytical_population_authority(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_analytical_population_authority(p_capability text, p_population text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a uuid:=auth.uid();at_time timestamptz:=statement_timestamp();terms jsonb;
BEGIN
 IF p_population IS NULL OR p_population <>'BANK' THEN RAISE EXCEPTION 'BANK required' USING ERRCODE='22023'; END IF;
 IF NOT public.current_account_has_population_capability(p_capability,'BANK')
 THEN RAISE EXCEPTION 'Population capability denied' USING ERRCODE='42501'; END IF;
 RETURN twuanis_canonical_private.bank_population_authority(a,p_capability);
END$$;


--
-- Name: read_canonical_bank_analytical_evidence(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_canonical_bank_analytical_evidence(p_account uuid, p_capability text, p_population text, p_after uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE authority jsonb;rows jsonb;terms jsonb;
BEGIN
 IF auth.jwt()->>'role' IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Trusted server transport required' USING ERRCODE='42501';END IF;
 IF p_population IS NULL OR p_population <>'BANK' THEN RAISE EXCEPTION 'BANK required' USING ERRCODE='22023';END IF;
 authority:=twuanis_canonical_private.bank_population_authority(p_account,p_capability);
 WITH published AS MATERIALIZED (SELECT * FROM twuanis_remates_private.public_projection)
 SELECT jsonb_build_object('items',coalesce(jsonb_agg(item ORDER BY listing_id,property_id),'[]'),'dataRevision',
 (SELECT md5(jsonb_build_object('public',coalesce(jsonb_agg(v ORDER BY v.id),'[]'),
 'classes',(SELECT coalesce(jsonb_agg(cc.id ORDER BY cc.id),'[]') FROM twuanis_remates_private.classification_versions cc JOIN twuanis_remates_private.offering_properties op ON op.property_id=cc.property_id JOIN published vp ON vp.offering_id=op.offering_id),
 'financial',(SELECT coalesce(jsonb_agg(fe.id ORDER BY fe.id),'[]') FROM twuanis_remates_private.offering_events fe JOIN published vp ON vp.offering_id=fe.offering_id),
 'policies',(SELECT coalesce(jsonb_agg(pol.id ORDER BY pol.id),'[]') FROM twuanis_remates_private.source_lifecycle_policies pol JOIN twuanis_remates_private.offerings off ON off.source_id=pol.source_id JOIN published vp ON vp.offering_id=off.id))::text) FROM published v)) INTO rows FROM (
 SELECT v.id listing_id,p.id property_id,jsonb_build_object(
 'population','BANK','listingId',v.id,'propertyId',p.id,'offeringId',v.offering_id,'sourceId',s.id,'sourceNamespace',s.namespace,
 'sourceRevision',s.revision::text,'recordKey',b.record_key,'bindingId',b.id,'bindingRevision',b.revision::text,
 'publicationRevision',v.revision,'publicationStatus',v.state,'classificationId',c.id,'classificationRevision',c.revision::text,
 'observationId',ob.id,'observedAt',ob.retrieved_at,'contentHash',ob.content_sha256,'policyId',pol.id,'policyRevision',pol.revision::text,
 'freshSeconds',pol.fresh_seconds::text,'lifecycle',twuanis_remates_private.lifecycle_eligibility(v.offering_id),
 'mechanism',v.mechanism,'transactionEvidence',CASE WHEN ob.raw_text LIKE '{%' AND ob.parse_status='PARSED' THEN jsonb_build_array(jsonb_build_object('value',ob.raw_text::jsonb->>'transaction_type','path','raw.transaction_type','ordinal',0,'validation','RETAINED_RAW')) ELSE '[]'::jsonb END,
 'financial',jsonb_build_object('id',fv.id,'eventId',fe.id,'eventRevision',fe.revision::text,'kind',fv.kind,'status',fv.status,'amount',fv.amount::text,'currency',fv.currency,'observationId',fv.observation_id,'sourceId',fv.source_id,'offeringId',fv.offering_id,'fieldPath',fv.field_path,'ordinal',fv.ordinal,'selectionValid',twuanis_remates_private.financial_selection_valid(fe.id)),
 'terms',(SELECT jsonb_agg(jsonb_build_object('id',t.id::text,'parent_id',t.parent_id::text,'term_type',t.term_type,'level',t.level,'official_code',t.official_code,'slug',t.slug,'term_name',t.term_name,'term_name_en',to_jsonb(t)->>'term_name_en','term_name_es',to_jsonb(t)->>'term_name_es','slug_en',to_jsonb(t)->>'slug_en','slug_es',to_jsonb(t)->>'slug_es')) FROM twuanis_remates_private.property_terms pt JOIN public.ontology_terms t ON t.id=pt.term_id WHERE pt.classification_id=c.id AND pt.selected AND t.term_type IN('province','canton','district','property_type')),
 'measurements',(SELECT coalesce(jsonb_agg(jsonb_build_object('dimension',f.dimension,'kind',f.kind,'value',f.exact_value::text,'observationId',f.evidence_id,'fieldPath',f.field_path,'ordinal',f.ordinal,'unit',ef.unit,'validation',ef.validation,'fieldValue',ef.raw_value,'observedAt',eo.retrieved_at,'sourceId',eo.source_id,'recordKey',eo.record_key,'contentHash',eo.content_sha256,'page',ef.document_page,'selector',ef.selector)), '[]') FROM twuanis_remates_private.property_facts f JOIN twuanis_remates_private.observation_fields ef ON (ef.observation_id,ef.field_path,ef.ordinal)=(f.evidence_id,f.field_path,f.ordinal) JOIN twuanis_remates_private.observations eo ON eo.id=f.evidence_id WHERE f.classification_id=c.id AND f.dimension IN('property_area','construction_area')),
 'registryMeasurements',(SELECT coalesce(jsonb_agg(jsonb_build_object('value',f.raw_value,'observationId',f.observation_id,'fieldPath',f.field_path,'ordinal',f.ordinal,'unit',f.unit,'validation',f.validation,'page',f.document_page,'selector',f.selector)), '[]') FROM twuanis_remates_private.observation_fields f WHERE f.observation_id=c.observation_id AND f.field_path='pdf.normalized_registry_area'),
 'otherFacts',(SELECT coalesce(jsonb_agg(jsonb_build_object('dimension',f.dimension,'kind',f.kind,'exactValue',f.exact_value::text,'categoryTermId',f.category_term_id::text,'rangeLower',f.range_lower::text,'rangeUpper',f.range_upper::text,'lowerInclusive',f.lower_inclusive,'upperInclusive',f.upper_inclusive,'observationId',f.evidence_id,'fieldPath',f.field_path,'ordinal',f.ordinal)), '[]') FROM twuanis_remates_private.property_facts f WHERE f.classification_id=c.id AND f.dimension NOT IN('property_area','construction_area')),
 'semantics',(SELECT coalesce(jsonb_agg(jsonb_build_object('dimension',pt.dimension,'termId',pt.term_id::text,'observationId',pt.evidence_id)), '[]') FROM twuanis_remates_private.property_terms pt WHERE pt.classification_id=c.id AND pt.selected AND pt.dimension IN('property_type','utility','environment','terrain','accessibility','legal_status')),
 'areaSelection',(SELECT CASE WHEN eo.raw_text LIKE '{%' AND eo.raw_text::jsonb->>'format'='bp-reviewed-factual-areas-v1' THEN eo.raw_text::jsonb->'selection' ELSE NULL END FROM twuanis_remates_private.observations eo WHERE eo.id=c.observation_id)
 ) item
 FROM published v
 JOIN twuanis_remates_private.offerings off ON off.id=v.offering_id
 JOIN twuanis_remates_private.sources s ON s.id=off.source_id
 JOIN twuanis_remates_private.offering_properties op ON op.offering_id=off.id
 JOIN twuanis_remates_private.properties p ON p.id=op.property_id AND p.identity_status='CONFIRMED'
 JOIN LATERAL(SELECT cc.* FROM twuanis_remates_private.classification_versions cc WHERE cc.property_id=p.id ORDER BY cc.revision DESC LIMIT 1)c ON twuanis_remates_private.classification_minimum_valid(c.id) AND c.source_id=s.id
 JOIN twuanis_remates_private.source_bindings b ON b.id=c.binding_id AND b.source_id=s.id AND b.offering_id=off.id
 JOIN twuanis_remates_private.ingestion_results ir ON ir.id=twuanis_remates_private.current_ingestion(off.id)
 JOIN twuanis_remates_private.observations ob ON ob.id=ir.observation_id AND ob.source_id=s.id
 JOIN LATERAL(SELECT x.* FROM twuanis_remates_private.source_lifecycle_policies x WHERE x.source_id=s.id ORDER BY x.revision DESC LIMIT 1)pol ON pol.source_revision=s.revision
 JOIN LATERAL(SELECT x.* FROM twuanis_remates_private.offering_events x WHERE x.offering_id=off.id ORDER BY x.revision DESC LIMIT 1)fe ON true
 LEFT JOIN twuanis_remates_private.financial_values fv ON fv.id=fe.selected_value_id
 WHERE v.state='PUBLISHED' AND (p_after IS NULL OR v.id>p_after)
 AND (SELECT count(*) FROM twuanis_remates_private.offering_properties one WHERE one.offering_id=off.id)=1
 ORDER BY v.id,p.id LIMIT 26
 ) bounded;
 RETURN rows||jsonb_build_object('authority',authority);
END$$;


--
-- Name: read_canonical_listing_evidence(uuid[], text[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_canonical_listing_evidence(p_listing_ids uuid[], p_fact_dimensions text[], p_semantic_dimensions text[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE result jsonb;
BEGIN
 IF p_listing_ids IS NULL OR cardinality(p_listing_ids) NOT BETWEEN 1 AND 25
  OR array_ndims(p_listing_ids) <> 1 OR array_position(p_listing_ids,NULL) IS NOT NULL THEN
  RAISE EXCEPTION 'explicit batch of 1..25 listing identities required' USING ERRCODE='22023';
 END IF;
 IF p_fact_dimensions IS NULL OR cardinality(p_fact_dimensions)>5
  OR array_position(p_fact_dimensions,NULL) IS NOT NULL
  OR NOT p_fact_dimensions <@ ARRAY['bedrooms','bathrooms','parking','year_built','distance_to_paved_road']::text[]
  OR p_semantic_dimensions IS NULL OR cardinality(p_semantic_dimensions)>6
  OR array_position(p_semantic_dimensions,NULL) IS NOT NULL
  OR NOT p_semantic_dimensions <@ ARRAY['property_type','utility','environment','terrain','accessibility','legal_status']::text[] THEN
  RAISE EXCEPTION 'invalid evidence dimensions' USING ERRCODE='22023';
 END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object(
  'listing_id',l.id::text,'canonical_domain_version',l.canonical_domain_version,
  'geography',coalesce((SELECT jsonb_agg(jsonb_build_object(
   'id',t.id::text,'parent_id',t.parent_id::text,'official_code',t.official_code,
   'term_type',t.term_type,'level',t.level,'term_name',t.term_name,
   'term_name_en',(to_jsonb(t)->>'term_name_en'),'term_name_es',(to_jsonb(t)->>'term_name_es'),
   'slug',(to_jsonb(t)->>'slug'),'slug_en',(to_jsonb(t)->>'slug_en'),'slug_es',(to_jsonb(t)->>'slug_es')) ORDER BY t.level,t.id)
   FROM public.listings_ontology_terms m JOIN public.ontology_terms t ON t.id=m.ontology_term_id
   WHERE m.listing_id=l.id AND t.term_type IN ('province','canton','district')),'[]'::jsonb),
  'facts',coalesce((SELECT jsonb_agg(jsonb_build_object(
   'dimension',f.dimension,'kind',f.kind,'exact_value',f.exact_value::text,
   'category_term_id',f.category_term_id::text,'range_lower',f.range_lower::text,
   'range_upper',f.range_upper::text,'lower_inclusive',f.lower_inclusive,
   'upper_inclusive',f.upper_inclusive) ORDER BY f.dimension)
   FROM public.listing_fact_evidence f WHERE f.listing_id=l.id AND f.dimension=ANY(p_fact_dimensions)),'[]'::jsonb),
  'selections',coalesce((SELECT jsonb_agg(jsonb_build_object(
   'dimension',s.dimension,'ontology_term_id',s.ontology_term_id::text,
   'term_type',t.term_type,'level',t.level,'slug',(to_jsonb(t)->>'slug'),'term_name',t.term_name)
   ORDER BY s.dimension,s.ontology_term_id)
   FROM public.listing_semantic_selections s JOIN public.ontology_terms t ON t.id=s.ontology_term_id WHERE s.listing_id=l.id AND s.dimension=ANY(p_semantic_dimensions)),'[]'::jsonb)
 ) ORDER BY l.id),'[]'::jsonb) INTO result
 FROM public.listings l WHERE l.id=ANY(p_listing_ids) AND l.canonical_domain_version=1;
 RETURN result;
END
$$;


--
-- Name: read_completed_execution_report(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_completed_execution_report(p_report uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE a uuid;body jsonb;BEGIN
 a:=twuanis_canonical_private.execution_credit_actor();SELECT r.body INTO body FROM twuanis_canonical_private.execution_credit_reports r WHERE r.id=p_report AND r.account_id=a AND EXISTS(SELECT 1 FROM twuanis_canonical_private.execution_credit_events e WHERE e.report_id=r.id AND e.execution_id=r.execution_id AND e.account_id=a AND e.kind IN('EXECUTION_CONSUMED','OWNER_COMPLETED'));
 IF body IS NULL THEN RAISE EXCEPTION 'Completed account-owned report required' USING ERRCODE='42501';END IF;RETURN twuanis_canonical_private.evidence_v2_report_body(body);
END$$;


--
-- Name: read_customer_addon_job(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_customer_addon_job(p_job uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a uuid:=auth.uid();j twuanis_canonical_private.addon_import_jobs%ROWTYPE;price jsonb;
BEGIN
 IF a IS NULL OR auth.jwt()->>'role' IS DISTINCT FROM 'authenticated' THEN RAISE EXCEPTION 'authenticated account required';END IF;
 SELECT * INTO STRICT j FROM twuanis_canonical_private.addon_import_jobs WHERE id=p_job AND account_id=a;
 IF j.validator_version='canonical-customer-free-v1' THEN
 RETURN jsonb_build_object('id',j.id,'submitted',j.submitted_count,'accepted',j.accepted_count,'rejected',j.rejected_rows,'free',true,'orderable',false,
 'fulfilled',NOT EXISTS(SELECT 1 FROM jsonb_array_elements(j.accepted_rows)x WHERE NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.customer_publication_commands c WHERE c.owner_id=a AND c.request_id=(x->>'publicationRequest')::uuid)),
 'results',(SELECT coalesce(jsonb_agg(jsonb_build_object('row',x->>'row','listingId',r.listing_id)),'[]') FROM jsonb_array_elements(j.accepted_rows)x JOIN public.canonical_operation_receipts r ON r.authority_kind='owner' AND r.authority_identity=a::text AND r.operation_type='create_customer' AND r.request_id=(x->>'rowId')::uuid AND r.outcome='succeeded'));
 END IF;
 price:=twuanis_canonical_private.resolve_offer_price('addon','addon-bulk-listing-import',j.currency,j.accepted_count,clock_timestamp());
 RETURN jsonb_build_object('id',j.id,'submitted',j.submitted_count,'accepted',j.accepted_count,'rejected',j.rejected_rows,'currency',j.currency,'orderable',j.total IS NOT NULL AND j.configuration_id=(SELECT current_configuration_id FROM twuanis_canonical_private.addon_products WHERE id='addon-bulk-listing-import') AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.addon_import_results WHERE job_id=j.id),'order',(SELECT o.id FROM twuanis_canonical_private.offer_order_snapshots o WHERE o.job_id=j.id AND(o.payment_deadline>clock_timestamp()OR twuanis_canonical_private.sinpe_pending_review(o.id)OR EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_paid_acknowledgements WHERE order_id=o.id))ORDER BY o.created_at DESC LIMIT 1),'pricing',price,'currencyQuotes',jsonb_build_object('USD',twuanis_canonical_private.resolve_offer_price('addon','addon-bulk-listing-import','USD',j.accepted_count,clock_timestamp()),'CRC',twuanis_canonical_private.resolve_offer_price('addon','addon-bulk-listing-import','CRC',j.accepted_count,clock_timestamp())),'fulfilled',EXISTS(SELECT 1 FROM twuanis_canonical_private.addon_import_results WHERE job_id=j.id));
END$$;


--
-- Name: read_customer_addon_jobs(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_customer_addon_jobs(p_after uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a uuid:=auth.uid();result jsonb;BEGIN
 IF a IS NULL OR auth.jwt()->>'role' IS DISTINCT FROM 'authenticated' THEN RAISE EXCEPTION 'authenticated account required';END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(q)ORDER BY q.id),'[]')INTO result FROM(
 SELECT j.id,j.accepted_count AS accepted,j.submitted_count AS submitted,j.created_at AS "createdAt",EXISTS(SELECT 1 FROM twuanis_canonical_private.addon_import_results r WHERE r.job_id=j.id)AS fulfilled FROM twuanis_canonical_private.addon_import_jobs j WHERE j.account_id=a AND(p_after IS NULL OR j.id>p_after)ORDER BY j.id LIMIT 26)q;
 RETURN result;
END$$;


--
-- Name: read_customer_commercial(text, uuid, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_customer_commercial(p_area text, p_after uuid DEFAULT NULL::uuid, p_id uuid DEFAULT NULL::uuid, p_listing uuid DEFAULT NULL::uuid, p_history boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE actor uuid:=auth.uid();result jsonb;
BEGIN
 IF actor IS NULL OR auth.jwt()->>'role' IS DISTINCT FROM 'authenticated' THEN RAISE EXCEPTION 'authentication required';END IF;
 IF p_listing IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.listings WHERE id=p_listing AND owner_id=actor AND canonical_domain_version=1 AND listing_status<>'deleted') THEN RAISE EXCEPTION 'owned canonical listing required';END IF;
 IF p_area IN('orders','tokens') THEN
  SELECT coalesce(jsonb_agg(twuanis_canonical_private.customer_order_projection(q.id) ORDER BY q.id),'[]') INTO result FROM (
   SELECT o.id FROM twuanis_canonical_private.offer_order_snapshots o WHERE o.account_id=actor AND(p_area<>'tokens'OR o.target_type='execution_credit')AND (p_after IS NULL OR o.id>p_after) AND (p_id IS NULL OR o.id=p_id) AND (p_listing IS NULL OR o.listing_id=p_listing)
   ORDER BY o.id LIMIT 26)q;
 ELSIF p_area='rights' THEN
  SELECT coalesce(jsonb_agg(twuanis_canonical_private.customer_product_copy(q.product_class,q.product_id)||jsonb_build_object('id',q.id,'product',q.product_id,'class',q.product_class,'listing',q.listing_id,'source',q.source,'startsAt',q.starts_at,'endsAt',q.ends_at,'state',CASE WHEN q.revoked THEN 'REVOKED' WHEN q.starts_at>statement_timestamp() THEN 'SCHEDULED' WHEN q.ends_at<=statement_timestamp() THEN 'EXPIRED' ELSE 'ACTIVE' END) ORDER BY q.id),'[]') INTO result FROM (
   SELECT t.*,EXISTS(SELECT 1 FROM twuanis_canonical_private.entitlement_revocations WHERE term_id=t.id) revoked FROM twuanis_canonical_private.entitlement_terms t
   WHERE t.account_id=actor AND (p_after IS NULL OR t.id>p_after) AND (p_id IS NULL OR t.id=p_id) AND (p_listing IS NULL OR t.listing_id=p_listing)
   AND (p_history OR ((t.ends_at IS NULL OR t.ends_at>statement_timestamp()) AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.entitlement_revocations WHERE term_id=t.id))) ORDER BY t.id LIMIT 26)q;
 ELSIF p_area='payments' THEN
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',q.id,'order',q.canonical_order_id,'submittedAt',q.created_at,'currency',q.currency,'amount',q.amount::text,'state',coalesce(d.disposition,'REVIEW_PENDING'),'late',q.created_at>o.payment_deadline) ORDER BY q.id),'[]') INTO result FROM(
   SELECT p.* FROM public.sinpe_payments p WHERE p.user_id=actor AND p.canonical_order_id IS NOT NULL AND (p_after IS NULL OR p.id>p_after) AND (p_id IS NULL OR p.id=p_id) ORDER BY p.id LIMIT 26)q
   JOIN twuanis_canonical_private.offer_order_snapshots o ON o.id=q.canonical_order_id LEFT JOIN twuanis_canonical_private.sinpe_review_decisions d ON d.attempt_id=q.id;
 ELSIF p_area='listings' THEN
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',q.id,'title',q.title,'state',q.listing_status) ORDER BY q.id),'[]') INTO result FROM(
   SELECT id,title,listing_status FROM public.listings WHERE owner_id=actor AND canonical_domain_version=1 AND listing_status<>'deleted' AND (p_after IS NULL OR id>p_after) AND (p_id IS NULL OR id=p_id) ORDER BY id LIMIT 26)q;
 ELSIF p_area='legacy' THEN
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',g.subscription_id,'source','LEGACY','endsAt',g.expires_at,'capabilities',g.capabilities) ORDER BY g.subscription_id),'[]') INTO result FROM (SELECT g.* FROM twuanis_canonical_private.legacy_package_access g JOIN public.user_subscriptions s ON s.id=g.subscription_id
   WHERE g.account_id=actor AND s.user_id=actor AND s.package_id=g.package_id AND s.status='active' AND s.cancelled_at IS NULL AND s.expired_at IS NULL AND s.current_period_end=g.expires_at AND g.expires_at>statement_timestamp() AND (p_after IS NULL OR g.subscription_id>p_after) AND (p_id IS NULL OR g.subscription_id=p_id) ORDER BY g.subscription_id LIMIT 26)g;
 ELSE RAISE EXCEPTION 'unknown bounded commercial area';END IF;
 RETURN result;
END$$;


--
-- Name: read_customer_commercial_prices(text, text[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_customer_commercial_prices(p_kind text, p_products text[], p_currency text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a uuid:=auth.uid();result jsonb:='[]';row jsonb;price jsonb;BEGIN
 IF a IS NULL OR auth.jwt()->>'role' IS DISTINCT FROM 'authenticated' THEN RAISE EXCEPTION 'authenticated account required';END IF;
 FOR row IN SELECT value FROM jsonb_array_elements(public.read_offer_prices(p_kind,p_products,p_currency))LOOP
 IF row->'tiers' IS NOT NULL THEN result:=result||jsonb_build_array(row);CONTINUE;END IF;
 price:=twuanis_canonical_private.founder_price(a,p_kind,row->>'productId',p_currency,statement_timestamp(),twuanis_canonical_private.resolve_offer_price(p_kind,row->>'productId',p_currency,1,statement_timestamp()),'PRIVATE');
 result:=result||jsonb_build_array(row||jsonb_build_object('effectivePrice',price->>'effectiveRate','source',price->>'source','founderProtected',price?'founderProtection'));
 END LOOP;
 RETURN result;
END$$;


--
-- Name: read_customer_founder_acquisition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_customer_founder_acquisition() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a uuid:=auth.uid();reason text;oid uuid;active boolean;BEGIN
 IF a IS NULL OR auth.jwt()->>'role' IS DISTINCT FROM 'authenticated' THEN RAISE EXCEPTION 'authenticated account required';END IF;
 SELECT EXISTS(SELECT 1 FROM twuanis_canonical_private.entitlement_terms t WHERE t.account_id=a AND t.product_class='FOUNDING_MEMBERSHIP' AND t.starts_at<=statement_timestamp()AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.entitlement_revocations r WHERE r.term_id=t.id))INTO active;
 SELECT o.id INTO oid FROM twuanis_canonical_private.offer_order_snapshots o WHERE o.account_id=a AND o.product_id='addon-2026-founding-membership'AND(o.payment_deadline>statement_timestamp()OR twuanis_canonical_private.sinpe_pending_review(o.id)OR EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_paid_acknowledgements WHERE order_id=o.id))ORDER BY o.created_at DESC LIMIT 1;
 IF active THEN reason:='membership_active';
 ELSIF oid IS NOT NULL THEN reason:='existing_acquisition';
 ELSIF NOT EXISTS(SELECT 1 FROM auth.users WHERE id=a AND email_confirmed_at IS NOT NULL) THEN reason:='confirmation_required';
 ELSIF NOT public.customer_commerce_ready() THEN reason:='inactive';
 ELSIF NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.sinpe_receiving_accounts WHERE enabled AND currency='CRC')THEN reason:='channel_unavailable';
 ELSIF twuanis_canonical_private.resolve_offer_price('addon','addon-2026-founding-membership','CRC',1,statement_timestamp())->>'available'IS DISTINCT FROM'true'THEN reason:='acquisition_ended';
 END IF;
 RETURN jsonb_build_object('policyVersion',CASE WHEN active AND NOT twuanis_canonical_private.has_introductory_membership(a,statement_timestamp()) THEN 'historical-200-v1' ELSE 'cr-intro-life-2000-v1' END,'priceUSD','2000','capacity',5,'available',reason IS NULL,'reason',reason,'active',active,'order',oid);
END$$;


--
-- Name: read_customer_listing_review(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_customer_listing_review(p_listing uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE d record; BEGIN
 IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.listings WHERE id=p_listing AND owner_id=auth.uid()) THEN RAISE EXCEPTION 'Owned listing required' USING ERRCODE='42501'; END IF;
 SELECT c.id,c.status,c.version,c.updated_at INTO d FROM twuanis_canonical_private.listing_admission_decisions a JOIN twuanis_canonical_private.listing_duplicate_cases c ON c.current_admission_id=a.id WHERE a.listing_id=p_listing ORDER BY a.created_at DESC LIMIT 1; RETURN to_jsonb(d);
END $$;


--
-- Name: read_customer_package_catalog(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_customer_package_catalog(p_after text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT coalesce(jsonb_agg(x.value || jsonb_build_object('additionalCapabilityLabels',(SELECT jsonb_agg(jsonb_build_object('id',c.id,'en',c.name_en,'es',c.name_es) ORDER BY c.id) FROM twuanis_canonical_private.intelligence_capabilities c WHERE c.id IN(SELECT jsonb_array_elements_text(x.value->'capabilities')) AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.intelligence_packages p JOIN twuanis_canonical_private.intelligence_package_configurations v ON v.id=p.current_configuration_id WHERE p.id=CASE x.value->>'id' WHEN 'pkg-matching-market-comparison' THEN 'pkg-geographic-distribution-price-range' WHEN 'pkg-pricing-position-relationships' THEN 'pkg-matching-market-comparison' ELSE NULL END AND c.id=ANY(v.capabilities))),'capabilityLabels',(
 SELECT jsonb_agg(jsonb_build_object('id',c.id,'en',c.name_en,'es',c.name_es) ORDER BY c.id)
 FROM twuanis_canonical_private.intelligence_capabilities c WHERE c.id IN(SELECT jsonb_array_elements_text(x.value->'capabilities')))) ORDER BY x.value->>'id'),'[]')
 FROM jsonb_array_elements(public.read_intelligence_package_catalog(p_after)) x
$$;


--
-- Name: read_customer_payment_activity(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_customer_payment_activity(p_after uuid DEFAULT NULL::uuid, p_id uuid DEFAULT NULL::uuid, p_listing uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a uuid:=auth.uid();result jsonb;BEGIN
 IF a IS NULL OR auth.jwt()->>'role' IS DISTINCT FROM 'authenticated' THEN RAISE EXCEPTION 'authenticated account required';END IF;
 IF p_listing IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.listings WHERE id=p_listing AND owner_id=a AND canonical_domain_version=1 AND listing_status<>'deleted') THEN RAISE EXCEPTION 'owned listing required';END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(q)ORDER BY q.id),'[]')INTO result FROM(
 SELECT x.*,o.resolved_terms->'currencyQuotes'AS "currencyQuotes" FROM(
 SELECT p.id,p.canonical_order_id AS "order",p.created_at AS "submittedAt",p.currency,p.amount::text,coalesce(d.disposition,'REVIEW_PENDING') AS state,'SINPE'::text AS provider
 FROM public.sinpe_payments p LEFT JOIN twuanis_canonical_private.sinpe_review_decisions d ON d.attempt_id=p.id WHERE p.user_id=a AND p.canonical_order_id IS NOT NULL
 UNION ALL
 SELECT r.id,r.order_id,r.received_at,r.currency,r.amount::text,r.disposition,'ONVO'::text FROM twuanis_canonical_private.onvo_receipts r JOIN twuanis_canonical_private.offer_order_snapshots o ON o.id=r.order_id WHERE o.account_id=a
 UNION ALL SELECT r.id,r.order_id,r.paid_at,r.currency,r.amount::text,r.disposition,'STRIPE'::text FROM twuanis_canonical_private.stripe_receipts r JOIN twuanis_canonical_private.offer_order_snapshots s ON s.id=r.order_id WHERE s.account_id=a
 )x JOIN twuanis_canonical_private.offer_order_snapshots o ON o.id=x."order" AND o.account_id=a
 WHERE(p_after IS NULL OR x.id>p_after)AND(p_id IS NULL OR x.id=p_id)AND(p_listing IS NULL OR o.listing_id=p_listing)ORDER BY x.id LIMIT 26)q;
 RETURN result;
END$$;


--
-- Name: read_direct_sinpe_checkout(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_direct_sinpe_checkout(p_order uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a uuid:=auth.uid();o twuanis_canonical_private.offer_order_snapshots%ROWTYPE;r twuanis_canonical_private.direct_sinpe_receipts%ROWTYPE;receiver twuanis_canonical_private.sinpe_receiving_accounts%ROWTYPE;t twuanis_canonical_private.entitlement_terms%ROWTYPE;BEGIN
 IF a IS NULL OR auth.jwt()->>'role'IS DISTINCT FROM'authenticated'OR NOT EXISTS(SELECT 1 FROM auth.users u JOIN twuanis_canonical_private.account_principals p ON p.id=u.id WHERE u.id=a AND u.email_confirmed_at IS NOT NULL AND p.deleted_at IS NULL)THEN RAISE EXCEPTION 'confirmed live account required' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT o FROM twuanis_canonical_private.offer_order_snapshots WHERE id=p_order AND account_id=a AND target_type='package'AND currency='CRC';
 IF o.resolved_terms->>'paymentExecution'IS DISTINCT FROM'direct_sinpe' THEN RETURN jsonb_build_object('state','HISTORICAL_PROVIDER_ORDER','orderId',o.id);END IF;
 SELECT * INTO r FROM twuanis_canonical_private.direct_sinpe_receipts WHERE order_id=o.id;
 SELECT * INTO receiver FROM twuanis_canonical_private.sinpe_receiving_accounts WHERE id=(o.resolved_terms->>'directReceivingAccount')::uuid AND payment_method='direct_sinpe';
 IF receiver.id IS NULL THEN RAISE EXCEPTION 'pinned direct receiving identity missing';END IF;
 IF r.activation_term_id IS NOT NULL THEN SELECT * INTO STRICT t FROM twuanis_canonical_private.entitlement_terms WHERE id=r.activation_term_id;END IF;
 RETURN jsonb_build_object('state',CASE WHEN t.id IS NOT NULL THEN CASE WHEN EXISTS(SELECT 1 FROM twuanis_canonical_private.entitlement_revocations WHERE term_id=t.id)THEN'REVOKED'WHEN t.starts_at>clock_timestamp()THEN'SCHEDULED'WHEN t.ends_at<=clock_timestamp()THEN'ENDED'ELSE'ACTIVE'END WHEN clock_timestamp()>o.payment_deadline THEN'EXPIRED'WHEN NOT receiver.enabled OR NOT public.direct_sinpe_ready()THEN'UNAVAILABLE'ELSE'AWAITING_RECEIPT'END,'orderId',o.id,'accountId',a,'product',o.product_id,'configuration',o.resolved_terms->>'configurationId','amount',o.resolved_terms->>'total','currency','CRC','duration',o.resolved_terms->'terms'->>'unit','bankUpgrade',coalesce((o.resolved_terms->'bankUpgrade'->>'selected')::boolean,false),'receivingNumber',receiver.receiving_phone,'deadline',o.payment_deadline,'receiptId',r.id,'receiptSubmittedAt',r.submitted_at,'receiptActivated',t.id IS NOT NULL,'bankVerified',false,'reconciliation',r.reconciliation,'startsAt',t.starts_at,'endsAt',t.ends_at);
END $$;


--
-- Name: read_direct_sinpe_receipt(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_direct_sinpe_receipt(p_receipt uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a uuid:=auth.uid();r twuanis_canonical_private.direct_sinpe_receipts%ROWTYPE;BEGIN
 IF a IS NULL OR auth.jwt()->>'role'IS DISTINCT FROM'authenticated'THEN RAISE EXCEPTION 'authentication required' USING ERRCODE='42501';END IF;
 IF NOT EXISTS(SELECT 1 FROM storage.buckets WHERE id='sinpe-receipts'AND NOT public AND file_size_limit=5242880 AND allowed_mime_types=ARRAY['application/pdf','image/jpeg','image/png','image/webp'])THEN RAISE EXCEPTION 'Private receipt storage unavailable';END IF;
 SELECT * INTO STRICT r FROM twuanis_canonical_private.direct_sinpe_receipts WHERE id=p_receipt AND(account_id=a OR public.is_current_user_owner());
 RETURN jsonb_build_object('id',r.id,'path',r.object_path,'mime',r.mime_type,'size',r.file_size,'accountId',r.account_id,'orderId',r.order_id);
END $$;


