--
-- Name: set_listings_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_listings_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  new.updated_at = now();

  if new.listing_status = 'active'
     and new.published_at is null then
    new.published_at = now();
  end if;

  if new.listing_status = 'archived'
     and old.listing_status is distinct from 'archived'
     and new.archived_at is null then
    new.archived_at = now();
  end if;

  if new.listing_status = 'expired'
     and old.listing_status is distinct from 'expired'
     and new.expired_at is null then
    new.expired_at = now();
  end if;

  if new.listing_status = 'deleted'
     and old.listing_status is distinct from 'deleted'
     and new.deleted_at is null then
    new.deleted_at = now();
  end if;

  return new;
end;
$$;


