--
-- Name: sinpe_notification_service(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sinpe_notification_service(p_operation text, p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE n twuanis_canonical_private.sinpe_purchase_notifications%ROWTYPE;o twuanis_canonical_private.offer_order_snapshots%ROWTYPE;a twuanis_canonical_private.offer_paid_acknowledgements%ROWTYPE;t twuanis_canonical_private.entitlement_terms%ROWTYPE;token uuid;body jsonb;at_time timestamptz:=clock_timestamp();BEGIN
 IF p_operation='claim' THEN
 SELECT * INTO n FROM twuanis_canonical_private.sinpe_purchase_notifications WHERE state IN('PENDING','RETRY') AND next_attempt<=at_time AND(lease_until IS NULL OR lease_until<=at_time)ORDER BY next_attempt LIMIT 1 FOR UPDATE SKIP LOCKED;
 IF NOT FOUND THEN RETURN NULL;END IF;
 IF n.first_attempt IS NOT NULL AND at_time>=n.first_attempt+interval '23 hours 50 minutes' THEN
 UPDATE twuanis_canonical_private.sinpe_purchase_notifications SET state='NEEDS_RESOLUTION' WHERE order_id=n.order_id;INSERT INTO twuanis_canonical_private.sinpe_notification_attempts(order_id,outcome)VALUES(n.order_id,'NEEDS_RESOLUTION');RETURN NULL;END IF;
 token:=gen_random_uuid();SELECT * INTO STRICT o FROM twuanis_canonical_private.offer_order_snapshots WHERE id=n.order_id;SELECT * INTO STRICT a FROM twuanis_canonical_private.offer_paid_acknowledgements WHERE id=n.acknowledgement_id;SELECT * INTO t FROM twuanis_canonical_private.entitlement_terms WHERE order_id=n.order_id;
 body:=coalesce(n.payload,twuanis_canonical_private.customer_product_copy(o.target_type,o.product_id)||jsonb_build_object('orderId',o.id,'productClass',o.resolved_terms->>'productClass','productId',o.product_id,'unit',o.resolved_terms->'terms'->>'unit','quantity',o.resolved_terms->'terms'->>'quantity','durationDays',o.resolved_terms->'terms'->>'durationDays','termKind',o.resolved_terms->'terms'->>'termKind','amount',a.amount::text,'currency',a.currency,'payment','APPROVED','confirmedAt',a.acknowledged_at,'receivedAt',coalesce((SELECT received_at FROM twuanis_canonical_private.onvo_receipts WHERE acknowledgement_id=a.id),(SELECT received_at FROM twuanis_canonical_private.sinpe_review_decisions WHERE acknowledgement_id=a.id)),'fulfillment',CASE WHEN t.id IS NOT NULL OR EXISTS(SELECT 1 FROM twuanis_canonical_private.addon_fulfillments WHERE purchase_id=o.id AND result->>'ok'='true') THEN 'COMPLETE' ELSE 'PENDING' END,'startsAt',t.starts_at,'endsAt',t.ends_at,'asOf',at_time));
 UPDATE twuanis_canonical_private.sinpe_purchase_notifications SET payload=body,first_attempt=coalesce(first_attempt,at_time),lease=token,lease_until=at_time+interval '2 minutes' WHERE order_id=n.order_id;
 RETURN jsonb_build_object('orderId',n.order_id,'token',token,'recipient',n.recipient,'payload',body);
 ELSIF p_operation='finish' THEN
 SELECT * INTO STRICT n FROM twuanis_canonical_private.sinpe_purchase_notifications WHERE order_id=(p_command->>'orderId')::uuid FOR UPDATE;
 IF n.lease IS DISTINCT FROM(p_command->>'token')::uuid THEN RAISE EXCEPTION 'notification lease conflict';END IF;
 IF p_command->>'outcome' NOT IN('ACCEPTED','RETRY') THEN RAISE EXCEPTION 'bounded outcome required';END IF;
 UPDATE twuanis_canonical_private.sinpe_purchase_notifications SET state=p_command->>'outcome',provider_message=p_command->>'messageId',lease=NULL,lease_until=NULL,next_attempt=at_time+interval '1 minute' WHERE order_id=n.order_id;
 INSERT INTO twuanis_canonical_private.sinpe_notification_attempts(order_id,outcome,provider_message)VALUES(n.order_id,p_command->>'outcome',p_command->>'messageId');RETURN jsonb_build_object('ok',true);
 ELSE RAISE EXCEPTION 'unknown notification operation';END IF;
END$$;


--
-- Name: stripe_commerce_ready(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stripe_commerce_ready() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$SELECT coalesce((SELECT enabled FROM twuanis_canonical_private.stripe_control WHERE singleton),false)$$;


--
-- Name: stripe_service_command(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stripe_service_command(p_operation text, p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE o twuanis_canonical_private.offer_order_snapshots%ROWTYPE;c twuanis_canonical_private.stripe_checkouts%ROWTYPE;r twuanis_canonical_private.stripe_receipts%ROWTYPE;ctl twuanis_canonical_private.stripe_control%ROWTYPE;a twuanis_canonical_private.offer_paid_acknowledgements%ROWTYPE;rid uuid:=gen_random_uuid();aid uuid;cfg twuanis_canonical_private.intelligence_package_configurations%ROWTYPE;tid uuid;begins timestamptz;ends timestamptz;result jsonb;paid_at timestamptz;amount numeric;disposition text;
BEGIN
 IF auth.jwt()->>'role' IS DISTINCT FROM 'service_role'OR p_operation NOT IN('reserve','bind','receipt','fulfill','status')OR jsonb_typeof(p_command)IS DISTINCT FROM'object'OR octet_length(p_command::text)>16000 THEN RAISE EXCEPTION 'Stripe service authority required' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT ctl FROM twuanis_canonical_private.stripe_control WHERE singleton;
 IF ctl.account_id IS DISTINCT FROM p_command->>'providerAccount'OR ctl.mode IS DISTINCT FROM p_command->>'mode'THEN RAISE EXCEPTION 'Stripe account/environment mismatch';END IF;
 SELECT * INTO STRICT o FROM twuanis_canonical_private.offer_order_snapshots WHERE id=(p_command->>'orderId')::uuid;
 PERFORM pg_advisory_xact_lock(3200,hashtext(o.id::text));
 IF p_operation='reserve'THEN
  IF NOT ctl.enabled OR NOT public.stripe_commerce_ready()OR o.account_id IS DISTINCT FROM(p_command->>'accountId')::uuid OR o.currency<>'USD'OR (o.resolved_terms->>'total')::numeric<2 OR clock_timestamp()>=o.payment_deadline OR EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_paid_acknowledgements WHERE order_id=o.id)OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=o.account_id AND email_confirmed_at IS NOT NULL)THEN RAISE EXCEPTION 'eligible confirmed owned USD order required';END IF;
  INSERT INTO twuanis_canonical_private.stripe_checkouts(order_id,account_id,mode)VALUES(o.id,ctl.account_id,ctl.mode)ON CONFLICT DO NOTHING;
 END IF;
 SELECT * INTO STRICT c FROM twuanis_canonical_private.stripe_checkouts WHERE order_id=o.id FOR UPDATE;
 IF c.account_id<>ctl.account_id OR c.mode<>ctl.mode THEN RAISE EXCEPTION 'Stripe binding conflict';END IF;
 IF p_operation='reserve'OR p_operation='status'THEN RETURN jsonb_build_object('orderId',o.id,'accountId',o.account_id,'productId',o.product_id,'currency',o.currency,'amount',o.resolved_terms->>'total','deadline',o.payment_deadline,'sessionId',c.session_id,'fulfillment',c.fulfillment,'paid',EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_paid_acknowledgements WHERE order_id=o.id));END IF;
 IF p_operation='bind'THEN
  IF p_command->>'sessionId' !~ '^cs_(test_|live_)?[A-Za-z0-9]+$'OR p_command->>'sessionId'IS NULL OR(c.session_id IS NOT NULL AND c.session_id IS DISTINCT FROM p_command->>'sessionId')THEN RAISE EXCEPTION 'exact Stripe Session required';END IF;
  UPDATE twuanis_canonical_private.stripe_checkouts SET session_id=p_command->>'sessionId' WHERE order_id=o.id;RETURN jsonb_build_object('ok',true);
 END IF;
 IF p_operation='receipt'THEN
  IF p_command->>'sessionId'IS DISTINCT FROM c.session_id OR p_command->>'paymentStatus'IS DISTINCT FROM'paid'OR p_command->>'status'IS DISTINCT FROM'complete'OR p_command->>'currency'IS DISTINCT FROM'USD'OR p_command->>'paymentIntent'IS NULL OR p_command->>'paymentIntent' !~ '^pi_[A-Za-z0-9]+$'OR p_command->>'eventId'IS NULL OR p_command->>'eventId' !~ '^evt_[A-Za-z0-9]+$' THEN RAISE EXCEPTION 'verified complete Stripe payment required';END IF;
  amount:=(p_command->>'amount')::numeric;paid_at:=(p_command->>'paidAt')::timestamptz;
  IF amount IS NULL OR amount<=0 OR scale(amount)>2 OR NOT isfinite(paid_at)OR paid_at>clock_timestamp()+interval'5 minutes'THEN RAISE EXCEPTION 'bounded Stripe evidence required';END IF;
  PERFORM pg_advisory_xact_lock(3297,hashtext(ctl.account_id||':'||ctl.mode||':'||(p_command->>'paymentIntent')));
  SELECT * INTO r FROM twuanis_canonical_private.stripe_receipts WHERE account_id=ctl.account_id AND mode=ctl.mode AND payment_intent=p_command->>'paymentIntent';
  IF FOUND THEN IF r.order_id<>o.id OR r.amount<>amount OR r.currency<>o.currency OR r.session_id<>c.session_id THEN RAISE EXCEPTION 'Stripe transaction reuse conflict';END IF;RETURN jsonb_build_object('id',r.id,'disposition',r.disposition);END IF;
  disposition:=CASE WHEN amount=(o.resolved_terms->>'total')::numeric AND paid_at BETWEEN o.created_at AND o.payment_deadline AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_paid_acknowledgements WHERE order_id=o.id)THEN 'APPROVED'ELSE 'RECEIVED_UNMATCHED'END;
  IF c.payment_intent IS NOT NULL AND c.payment_intent IS DISTINCT FROM p_command->>'paymentIntent'THEN RAISE EXCEPTION 'Stripe intent binding conflict';END IF;
  UPDATE twuanis_canonical_private.stripe_checkouts SET payment_intent=p_command->>'paymentIntent' WHERE order_id=o.id;
  IF disposition='APPROVED'THEN
   aid:=gen_random_uuid();INSERT INTO twuanis_canonical_private.offer_paid_acknowledgements(id,order_id,request_id,source,payment_event_id,external_reference,amount,currency,acknowledged_at,authority)VALUES(aid,o.id,rid,'stripe',rid,p_command->>'paymentIntent',amount,'USD',clock_timestamp(),'STRIPE:'||ctl.account_id||':'||ctl.mode);
  END IF;
  INSERT INTO twuanis_canonical_private.stripe_receipts(id,order_id,account_id,mode,event_id,payment_intent,session_id,amount,currency,paid_at,disposition,acknowledgement_id)VALUES(rid,o.id,ctl.account_id,ctl.mode,p_command->>'eventId',p_command->>'paymentIntent',c.session_id,amount,'USD',paid_at,disposition,aid);
  RETURN jsonb_build_object('id',rid,'disposition',disposition);
 END IF;
 SELECT * INTO STRICT a FROM twuanis_canonical_private.offer_paid_acknowledgements WHERE order_id=o.id AND source='stripe';
 IF NOT twuanis_canonical_private.stripe_paid(a.id)THEN RAISE EXCEPTION 'verified Stripe correspondence required';END IF;
 IF o.target_type='package'THEN
  SELECT id INTO tid FROM twuanis_canonical_private.entitlement_terms WHERE order_id=o.id;
  IF tid IS NULL THEN
   SELECT * INTO STRICT cfg FROM twuanis_canonical_private.intelligence_package_configurations WHERE id=(o.resolved_terms->>'configurationId')::uuid AND package_id=o.product_id;
   IF o.resolved_terms->'terms'->>'unit'NOT IN('day','month')THEN RAISE EXCEPTION 'canonical duration required';END IF;
   SELECT starts_at,ends_at INTO begins,ends FROM twuanis_canonical_private.purchased_package_interval(o.account_id,o.product_id,o.resolved_terms->'terms'->>'unit',(o.resolved_terms->'terms'->>'quantity')::integer,clock_timestamp());
   tid:=twuanis_canonical_private.commit_entitlement_term(o.account_id,'PACKAGE',o.product_id,cfg.id,NULL,'PURCHASED',o.id,a.id,NULL,o.id,begins,ends,NULL,NULL);
  END IF;
  PERFORM twuanis_canonical_private.assert_package_delivery(o.id,NULL);result:=jsonb_build_object('state','COMPLETE','termId',tid);
 ELSIF o.target_type='execution_credit'THEN result:=twuanis_canonical_private.commit_execution_credit_purchase(o.id,a.id,o.id);PERFORM twuanis_canonical_private.assert_execution_credit_delivery(o.id);result:=result||jsonb_build_object('state','COMPLETE');
 ELSIF o.listing_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.listings WHERE id=o.listing_id AND owner_id=o.account_id AND canonical_domain_version=1 AND listing_status NOT IN('active','deleted'))THEN result:=jsonb_build_object('state','PENDING','reason','awaiting_publication');
 ELSE
  result:=twuanis_canonical_private.fulfill_addon(o.id,a.payment_event_id,o.account_id,o.product_id,(o.resolved_terms->>'configurationId')::uuid,CASE WHEN o.job_id IS NOT NULL THEN 'operation'WHEN o.listing_id IS NOT NULL THEN 'listing'ELSE 'account'END,coalesce(o.job_id,o.listing_id,o.account_id),jsonb_build_object('currency',o.currency,'amount',o.resolved_terms->>'total'));result:=result||jsonb_build_object('state','COMPLETE');
 END IF;
 UPDATE twuanis_canonical_private.stripe_checkouts SET fulfillment=result WHERE order_id=o.id;RETURN result;
END$_$;


--
-- Name: submit_direct_sinpe_receipt(uuid, text, text, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_direct_sinpe_receipt(p_order uuid, p_path text, p_sha256 text, p_mime text, p_size bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE a uuid:=auth.uid();o twuanis_canonical_private.offer_order_snapshots%ROWTYPE;r twuanis_canonical_private.direct_sinpe_receipts%ROWTYPE;start_at timestamptz;end_at timestamptz;tid uuid;expected_path text;BEGIN
 IF a IS NULL OR auth.jwt()->>'role'IS DISTINCT FROM'authenticated'OR NOT EXISTS(SELECT 1 FROM auth.users u JOIN twuanis_canonical_private.account_principals p ON p.id=u.id WHERE u.id=a AND u.email_confirmed_at IS NOT NULL AND p.deleted_at IS NULL)THEN RAISE EXCEPTION 'confirmed live account required' USING ERRCODE='42501';END IF;
 PERFORM pg_advisory_xact_lock(3200,hashtext(p_order::text));
 SELECT * INTO STRICT o FROM twuanis_canonical_private.offer_order_snapshots WHERE id=p_order AND account_id=a AND target_type='package'AND currency='CRC'FOR UPDATE;
 SELECT * INTO r FROM twuanis_canonical_private.direct_sinpe_receipts WHERE order_id=o.id;
 IF r.activation_term_id IS NOT NULL THEN RETURN public.read_direct_sinpe_checkout(o.id);END IF;
 IF NOT public.direct_sinpe_ready()OR o.resolved_terms->>'paymentExecution'IS DISTINCT FROM'direct_sinpe'OR o.resolved_terms->>'receiptActivationPolicy'IS DISTINCT FROM'direct-sinpe-receipt-access-2026-10-31-v1'OR clock_timestamp()>o.payment_deadline OR EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_paid_acknowledgements WHERE order_id=o.id)OR EXISTS(SELECT 1 FROM twuanis_canonical_private.onvo_intents WHERE order_id=o.id)THEN RAISE EXCEPTION 'eligible unexpired direct Order required';END IF;
 IF p_sha256 IS NULL OR p_sha256 !~ '^[0-9a-f]{64}$'OR p_size IS NULL OR p_size NOT BETWEEN 1 AND 5242880 OR p_mime IS NULL OR p_mime NOT IN('application/pdf','image/jpeg','image/png','image/webp')THEN RAISE EXCEPTION 'supported bounded receipt required';END IF;
 expected_path:=a::text||'/'||o.id::text||'/'||p_sha256||CASE p_mime WHEN'application/pdf'THEN'.pdf'WHEN'image/jpeg'THEN'.jpg'WHEN'image/png'THEN'.png'ELSE'.webp'END;
 IF p_path IS DISTINCT FROM expected_path OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='sinpe-receipts'AND name=p_path AND(metadata->>'size')::bigint=p_size AND metadata->>'mimetype'=p_mime)THEN RAISE EXCEPTION 'private server-uploaded owned receipt required';END IF;
 INSERT INTO twuanis_canonical_private.direct_sinpe_receipts(order_id,account_id,receiving_account_id,object_path,sha256,mime_type,file_size)VALUES(o.id,a,(o.resolved_terms->>'directReceivingAccount')::uuid,p_path,p_sha256,p_mime,p_size)RETURNING * INTO r;
 SELECT starts_at,ends_at INTO STRICT start_at,end_at FROM twuanis_canonical_private.purchased_package_interval(a,o.product_id,o.resolved_terms->'terms'->>'unit',1,clock_timestamp());
 tid:=twuanis_canonical_private.commit_entitlement_term(a,'PACKAGE',o.product_id,(o.resolved_terms->>'configurationId')::uuid,NULL,'RECEIPT_POLICY',o.id,NULL,NULL,r.id,start_at,end_at,NULL,'Owner-approved receipt-based activation; settlement not independently verified.');
 UPDATE twuanis_canonical_private.direct_sinpe_receipts SET activation_term_id=tid WHERE id=r.id;
 IF o.resolved_terms->'terms'->>'unit'='month'AND o.product_id IN('pkg-matching-market-comparison','pkg-pricing-position-relationships')AND start_at<=clock_timestamp()THEN
  PERFORM twuanis_canonical_private.execution_credit_issue(a,'INCLUDED_PACKAGE',CASE WHEN o.product_id='pkg-matching-market-comparison'THEN 5 ELSE 10 END,'TERM:'||tid,o.product_id,tid,o.id,NULL,start_at,end_at,jsonb_build_object('source','RECEIPT_POLICY_MONTHLY_TERM','configurationId',o.resolved_terms->>'configurationId','termId',tid),r.id);
 END IF;
 RETURN public.read_direct_sinpe_checkout(o.id);
END $_$;


--
-- Name: submit_order_sinpe(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_order_sinpe(p_order uuid, p_request uuid, p_account uuid, p_evidence jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE actor uuid:=auth.uid();o twuanis_canonical_private.offer_order_snapshots%ROWTYPE;prior public.sinpe_payments%ROWTYPE;at_time timestamptz;result uuid;BEGIN
 IF actor IS NULL OR p_request IS NULL OR p_order IS NULL OR p_account IS NULL OR jsonb_typeof(p_evidence) IS DISTINCT FROM 'object' OR octet_length(p_evidence::text)>8000 OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_evidence) k WHERE k NOT IN('reference','senderName','senderPhone','claimedPaymentDate')) OR length(btrim(coalesce(p_evidence->>'reference',''))) NOT BETWEEN 1 AND 300 OR length(btrim(coalesce(p_evidence->>'senderName',''))) NOT BETWEEN 1 AND 300 THEN RAISE EXCEPTION 'bounded customer evidence required';END IF;
 PERFORM pg_advisory_xact_lock(3190,hashtext(actor::text||p_request::text));
 SELECT * INTO prior FROM public.sinpe_payments WHERE user_id=actor AND submission_request_id=p_request AND canonical_order_id IS NOT NULL;
 IF FOUND THEN IF (prior.canonical_order_id,prior.receiving_account_id,prior.submission_evidence) IS DISTINCT FROM(p_order,p_account,p_evidence) THEN RAISE EXCEPTION 'submission replay conflict';END IF;RETURN prior.id;END IF;
 SELECT * INTO STRICT o FROM twuanis_canonical_private.offer_order_snapshots WHERE id=p_order AND account_id=actor;
 PERFORM twuanis_canonical_private.sinpe_lock_order(p_order);at_time:=clock_timestamp();
 IF EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_paid_acknowledgements WHERE order_id=p_order) THEN RAISE EXCEPTION 'Order not eligible for submission';END IF;
 PERFORM id FROM twuanis_canonical_private.sinpe_receiving_accounts WHERE id=p_account AND enabled AND currency=o.currency FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'receiving currency unavailable';END IF;
 INSERT INTO public.sinpe_payments(user_id,canonical_order_id,submission_request_id,receiving_account_id,submission_evidence,amount,currency,sinpe_reference,sender_name,sender_phone,status,created_at,updated_at)
 VALUES(actor,p_order,p_request,p_account,p_evidence,(o.resolved_terms->>'total')::numeric,o.currency,p_evidence->>'reference',p_evidence->>'senderName',p_evidence->>'senderPhone','submitted',at_time,at_time) RETURNING id INTO result;
 RETURN result;
END$$;


--
-- Name: update_account_profile(uuid, bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_account_profile(p_request uuid, p_expected_revision bigint, p_patch jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE u uuid:=twuanis_canonical_private.account_actor(); p twuanis_canonical_private.account_profiles; receipt twuanis_canonical_private.account_request_receipts; payload jsonb; result jsonb;
BEGIN
 IF p_request IS NULL OR p_expected_revision IS NULL OR p_expected_revision<0 OR p_patch IS NULL OR jsonb_typeof(p_patch)<>'object' OR p_patch='{}'::jsonb THEN RAISE EXCEPTION 'invalid profile command' USING ERRCODE='22023'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_each(p_patch) e WHERE e.key NOT IN ('name','biography','language') OR jsonb_typeof(e.value) NOT IN ('string','null')) THEN RAISE EXCEPTION 'unsupported profile fields' USING ERRCODE='22023'; END IF;
 PERFORM public.read_account_profile();
 SELECT * INTO p FROM twuanis_canonical_private.account_profiles WHERE user_id=u FOR UPDATE;
 payload:=jsonb_build_object('expectedRevision',p_expected_revision,'patch',p_patch);
 SELECT * INTO receipt FROM twuanis_canonical_private.account_request_receipts WHERE user_id=u AND request_id=p_request;
 IF FOUND THEN
  IF receipt.operation<>'PROFILE_UPDATE' OR receipt.input<>payload THEN RAISE EXCEPTION 'request identity conflict' USING ERRCODE='22023'; END IF;
  RETURN receipt.result;
 END IF;
 IF p.revision<>p_expected_revision THEN RAISE EXCEPTION 'profile revision conflict' USING ERRCODE='40001'; END IF;
 UPDATE twuanis_canonical_private.account_profiles SET display_name=CASE WHEN p_patch?'name' THEN p_patch->>'name' ELSE display_name END, biography=CASE WHEN p_patch?'biography' THEN p_patch->>'biography' ELSE biography END, language=CASE WHEN p_patch?'language' THEN p_patch->>'language' ELSE language END, revision=revision+1,updated_at=clock_timestamp() WHERE user_id=u RETURNING * INTO p;
 result:=jsonb_build_object('name',p.display_name,'biography',p.biography,'language',p.language,'revision',p.revision);
 INSERT INTO twuanis_canonical_private.account_request_receipts(user_id,request_id,operation,input,result) VALUES(u,p_request,'PROFILE_UPDATE',payload,result);
 INSERT INTO twuanis_canonical_private.account_security_events(user_id,kind,request_id,revision) VALUES(u,'PROFILE_UPDATED',p_request,p.revision);
 RETURN result;
END $$;


