--
-- Name: validate_listing_entitlement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_listing_entitlement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  listing_owner_id uuid;
  product_target_type text;
  product_duration_type text;
  product_duration_days integer;
  product_is_stackable boolean;
  existing_entitlement_count integer;
begin
  select
    owner_id
  into
    listing_owner_id
  from public.listings
  where id = new.listing_id;

  if not found then
    raise exception
      'The selected listing does not exist.';
  end if;

  if listing_owner_id is null then
    raise exception
      'The selected listing does not have a customer owner.';
  end if;

  if new.owner_id <> listing_owner_id then
    raise exception
      'The entitlement owner must match the listing owner.';
  end if;

  select
    target_type,
    duration_type,
    duration_days,
    is_stackable
  into
    product_target_type,
    product_duration_type,
    product_duration_days,
    product_is_stackable
  from public.add_on_products
  where
    id = new.product_id
    and is_active = true;

  if not found then
    raise exception
      'The selected add-on product does not exist or is inactive.';
  end if;

  if product_target_type <> 'listing' then
    raise exception
      'Only listing-targeted products can create listing entitlements.';
  end if;

  if (
    new.status in (
      'scheduled',
      'active'
    )
    and new.starts_at is null
  ) then
    new.starts_at = now();
  end if;

  if (
    product_duration_type = 'days'
    and new.starts_at is not null
    and new.expires_at is null
  ) then
    new.expires_at =
      new.starts_at +
      make_interval(
        days =>
          product_duration_days
      );
  end if;

  if (
    product_duration_type = 'listing_lifetime'
    and new.expires_at is not null
  ) then
    raise exception
      'Listing-lifetime products cannot have a fixed expiration date.';
  end if;

  if (
    new.status in (
      'scheduled',
      'active'
    )
    and product_is_stackable = false
  ) then
    select
      count(*)
    into
      existing_entitlement_count
    from public.listing_entitlements
    where
      listing_id =
        new.listing_id
      and product_id =
        new.product_id
      and status in (
        'scheduled',
        'active'
      )
      and id <>
        coalesce(
          new.id,
          gen_random_uuid()
        );

    if existing_entitlement_count > 0 then
      raise exception
        'This non-stackable entitlement is already scheduled or active for the listing.';
    end if;
  end if;

  new.updated_at = now();

  return new;
end;
$$;


--
-- Name: validate_purchase_request(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_purchase_request() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  listing_owner_id uuid;

  add_on_target_type text;

  package_exists boolean;
begin

  /*
   * Package purchases are account-targeted.
   */
  if new.product_type = 'package' then

    if new.target_type <> 'account' then
      raise exception
        'Package purchases must target an account.';
    end if;

    select exists (
      select 1
      from public.packages p
      where p.id = new.package_id
    )
    into package_exists;

    if not package_exists then
      raise exception
        'The selected package does not exist.';
    end if;

  end if;


  /*
   * Add-on target must agree with the canonical
   * target_type defined by add_on_products.
   */
  if new.product_type = 'add_on' then

    select
      product.target_type
    into
      add_on_target_type
    from public.add_on_products product
    where product.id =
      new.add_on_product_id;

    if add_on_target_type is null then
      raise exception
        'The selected add-on product does not exist.';
    end if;

    if add_on_target_type <>
      new.target_type
    then
      raise exception
        'Purchase target does not match the add-on product target.';
    end if;

  end if;


  /*
   * Listing-targeted purchases must belong to
   * the purchase owner.
   */
  if new.target_type = 'listing' then

    select
      listing.owner_id
    into
      listing_owner_id
    from public.listings listing
    where listing.id =
      new.listing_id;

    if listing_owner_id is null then
      raise exception
        'The selected listing does not have a customer owner.';
    end if;

    if listing_owner_id <>
      new.owner_id
    then
      raise exception
        'The purchase owner does not own the selected listing.';
    end if;

  end if;


  return new;
end;
$$;


--
-- Name: validate_purchase_request_transition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_purchase_request_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin

  if new.status =
    old.status
  then
    return new;
  end if;

  /*
   * V1 purchase lifecycle:
   *
   * pending
   *   → approved
   *   → rejected
   *   → expired
   *   → cancelled
   *
   * Terminal states do not transition elsewhere.
   */
  if old.status <> 'pending' then
    raise exception
      'Purchase request is already in a terminal state.';
  end if;

  if new.status not in (
    'approved',
    'rejected',
    'expired',
    'cancelled'
  ) then
    raise exception
      'Invalid purchase request state transition.';
  end if;

  return new;
end;
$$;


--
-- Name: validate_sinpe_payment_subscription(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_sinpe_payment_subscription() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF NEW.canonical_order_id IS NOT NULL THEN RETURN NEW; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.user_subscriptions us
                WHERE us.id=NEW.subscription_id AND us.user_id=NEW.user_id) THEN
  RAISE EXCEPTION 'The subscription does not belong to the specified user.';
 END IF;
 RETURN NEW;
END $$;


