--
-- Name: apply_rls(jsonb, integer); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.apply_rls(wal jsonb, max_record_bytes integer DEFAULT (1024 * 1024)) RETURNS SETOF realtime.wal_rls
    LANGUAGE plpgsql
    AS $$
declare
    -- Regclass of the table e.g. public.notes
    entity_ regclass = (quote_ident(wal ->> 'schema') || '.' || quote_ident(wal ->> 'table'))::regclass;

    -- I, U, D, T: insert, update ...
    action realtime.action = (
        case wal ->> 'action'
            when 'I' then 'INSERT'
            when 'U' then 'UPDATE'
            when 'D' then 'DELETE'
            else 'ERROR'
        end
    );

    -- Is row level security enabled for the table
    is_rls_enabled bool = relrowsecurity from pg_class where oid = entity_;

    subscriptions realtime.subscription[] = array_agg(subs)
        from
            realtime.subscription subs
        where
            subs.entity = entity_
            -- Filter by action early - only get subscriptions interested in this action
            -- action_filter column can be: '*' (all), 'INSERT', 'UPDATE', or 'DELETE'
            and (subs.action_filter = '*' or subs.action_filter = action::text);

    -- Subscription vars
    working_role regrole;
    working_selected_columns text[];
    claimed_role regrole;
    claims jsonb;

    subscription_id uuid;
    subscription_has_access bool;
    visible_to_subscription_ids uuid[] = '{}';

    -- structured info for wal's columns
    columns realtime.wal_column[];
    -- previous identity values for update/delete
    old_columns realtime.wal_column[];

    -- the same values as wal2json sent them, which is what filters compare against
    raw_columns realtime.wal_column[] =
        array_agg((x->>'name', x->>'type', x->>'typeoid', x->'value', null, null)::realtime.wal_column)
        from jsonb_array_elements(wal -> 'columns') x;
    raw_old_columns realtime.wal_column[] =
        array_agg((x->>'name', x->>'type', x->>'typeoid', x->'value', null, null)::realtime.wal_column)
        from jsonb_array_elements(wal -> 'identity') x;

    error_record_exceeds_max_size boolean = octet_length(wal::text) > max_record_bytes;

    -- Primary jsonb output for record
    output jsonb;

    -- Loop record for iterating unique roles (outer loop)
    role_record record;
    -- Loop record for iterating unique selected_columns within a role (inner loop)
    cols_record record;
    -- Subscription ids visible at the role level (before fanning out by selected_columns)
    visible_role_sub_ids uuid[] = '{}';

begin
    perform set_config('role', null, true);

    columns =
        array_agg(
            (
                x->>'name',
                x->>'type',
                x->>'typeoid',
                realtime.cast(
                    (x->'value') #>> '{}',
                    coalesce(
                        (x->>'typeoid')::regtype, -- null when wal2json version <= 2.4
                        (x->>'type')::regtype
                    )
                ),
                (pks ->> 'name') is not null,
                true
            )::realtime.wal_column
        )
        from
            jsonb_array_elements(wal -> 'columns') x
            left join jsonb_array_elements(wal -> 'pk') pks
                on (x ->> 'name') = (pks ->> 'name');

    old_columns =
        array_agg(
            (
                x->>'name',
                x->>'type',
                x->>'typeoid',
                realtime.cast(
                    (x->'value') #>> '{}',
                    coalesce(
                        (x->>'typeoid')::regtype, -- null when wal2json version <= 2.4
                        (x->>'type')::regtype
                    )
                ),
                (pks ->> 'name') is not null,
                true
            )::realtime.wal_column
        )
        from
            jsonb_array_elements(wal -> 'identity') x
            left join jsonb_array_elements(wal -> 'pk') pks
                on (x ->> 'name') = (pks ->> 'name');

    for role_record in
        select claims_role
        from (select distinct claims_role from unnest(subscriptions)) t
        order by claims_role::text
    loop
        working_role := role_record.claims_role;

        -- Update `is_selectable` for columns and old_columns (once per role)
        columns =
            array_agg(
                (
                    c.name,
                    c.type_name,
                    c.type_oid,
                    c.value,
                    c.is_pkey,
                    pg_catalog.has_column_privilege(working_role, entity_, c.name, 'SELECT')
                )::realtime.wal_column
            )
            from
                unnest(columns) c;

        old_columns =
                array_agg(
                    (
                        c.name,
                        c.type_name,
                        c.type_oid,
                        c.value,
                        c.is_pkey,
                        pg_catalog.has_column_privilege(working_role, entity_, c.name, 'SELECT')
                    )::realtime.wal_column
                )
                from
                    unnest(old_columns) c;

        if action <> 'DELETE' and count(1) = 0 from unnest(columns) c where c.is_pkey then
            -- Fan out 400 error per distinct selected_columns for this role
            for cols_record in
                select selected_columns
                from (select distinct selected_columns from unnest(subscriptions) s where s.claims_role = working_role) t
                order by coalesce(array_to_string(selected_columns, ','), '')
            loop
                working_selected_columns := cols_record.selected_columns;
                return next (
                    jsonb_build_object(
                        'schema', wal ->> 'schema',
                        'table', wal ->> 'table',
                        'type', action
                    ),
                    is_rls_enabled,
                    (select array_agg(s.subscription_id) from unnest(subscriptions) as s where s.claims_role = working_role and (s.selected_columns is not distinct from working_selected_columns)),
                    array['Error 400: Bad Request, no primary key']
                )::realtime.wal_rls;
            end loop;

        -- The claims role does not have SELECT permission to the primary key of entity
        elsif action <> 'DELETE' and sum(c.is_selectable::int) <> count(1) from unnest(columns) c where c.is_pkey then
            -- Fan out 401 error per distinct selected_columns for this role
            for cols_record in
                select selected_columns
                from (select distinct selected_columns from unnest(subscriptions) s where s.claims_role = working_role) t
                order by coalesce(array_to_string(selected_columns, ','), '')
            loop
                working_selected_columns := cols_record.selected_columns;
                return next (
                    jsonb_build_object(
                        'schema', wal ->> 'schema',
                        'table', wal ->> 'table',
                        'type', action
                    ),
                    is_rls_enabled,
                    (select array_agg(s.subscription_id) from unnest(subscriptions) as s where s.claims_role = working_role and (s.selected_columns is not distinct from working_selected_columns)),
                    array['Error 401: Unauthorized']
                )::realtime.wal_rls;
            end loop;

        else
            -- Create the prepared statement (once per role)
            if is_rls_enabled and action <> 'DELETE' then
                if (select 1 from pg_prepared_statements where name = 'walrus_rls_stmt' limit 1) > 0 then
                    deallocate walrus_rls_stmt;
                end if;
                execute realtime.build_prepared_statement_sql('walrus_rls_stmt', entity_, columns);
            end if;

            -- Collect all visible subscription IDs for this role (filter check + RLS check)
            visible_role_sub_ids = '{}';

            for subscription_id, claims in (
                    select
                        subs.subscription_id,
                        subs.claims
                    from
                        unnest(subscriptions) subs
                    where
                        subs.entity = entity_
                        and subs.claims_role = working_role
                        and (
                            realtime.is_visible_through_filters(raw_columns, subs.filters)
                            or (
                              action = 'DELETE'
                              and realtime.is_visible_through_filters(raw_old_columns, subs.filters)
                            )
                        )
            ) loop

                if not is_rls_enabled or action = 'DELETE' then
                    visible_role_sub_ids = visible_role_sub_ids || subscription_id;
                else
                    -- Check if RLS allows the role to see the record
                    perform
                        -- Trim leading and trailing quotes from working_role because set_config
                        -- doesn't recognize the role as valid if they are included
                        set_config('role', trim(both '"' from working_role::text), true),
                        set_config('request.jwt.claims', claims::text, true);

                    execute 'execute walrus_rls_stmt' into subscription_has_access;

                    -- Reset the role on every FOR..LOOP batch execution.
                    -- The first batch of 10 rows is pre-fetched using the current connection role (PG internal behaviour)
                    -- then we have to reset it again otherwise it would use the role defined in the `set_config` above
                    -- to fetch the remaining rows when rows>10, which could be a user-defined role that lacks execution grants.
                    -- The flow is:
                    --   1. run batch with conn role
                    --   2. set_config working_role
                    --   3. execute walrus
                    --   4. reset role (revert)
                    --   5. repeat
                    perform set_config('role', null, true);

                    if subscription_has_access then
                        visible_role_sub_ids = visible_role_sub_ids || subscription_id;
                    end if;
                end if;
            end loop;

            perform set_config('role', null, true);

            -- Inner loop: per distinct selected_columns for this role
            for cols_record in
                select selected_columns
                from (select distinct selected_columns from unnest(subscriptions) s where s.claims_role = working_role) t
                order by coalesce(array_to_string(selected_columns, ','), '')
            loop
                working_selected_columns := cols_record.selected_columns;

                output = jsonb_build_object(
                    'schema', wal ->> 'schema',
                    'table', wal ->> 'table',
                    'type', action,
                    'commit_timestamp', to_char(
                        ((wal ->> 'timestamp')::timestamptz at time zone 'utc'),
                        'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
                    ),
                    'columns', (
                        select
                            jsonb_agg(
                                jsonb_build_object(
                                    'name', pa.attname,
                                    'type', pt.typname
                                )
                                order by pa.attnum asc
                            )
                        from
                            pg_attribute pa
                            join pg_type pt
                                on pa.atttypid = pt.oid
                            left join (
                                select unnest(conkey) as pkey_attnum
                                from pg_constraint
                                where conrelid = entity_ and contype = 'p'
                            ) pk on pk.pkey_attnum = pa.attnum
                        where
                            attrelid = entity_
                            and attnum > 0
                            and pg_catalog.has_column_privilege(working_role, entity_, pa.attname, 'SELECT')
                            and (working_selected_columns is null or pa.attname = any(working_selected_columns) or pk.pkey_attnum is not null)
                    )
                )
                -- Add "record" key for insert and update
                || case
                    when action in ('INSERT', 'UPDATE') then
                        jsonb_build_object(
                            'record',
                            (
                                select
                                    jsonb_object_agg(
                                        -- if unchanged toast, get column name and value from old record
                                        coalesce((c).name, (oc).name),
                                        case
                                            when (c).name is null then (oc).value
                                            else (c).value
                                        end
                                    )
                                from
                                    unnest(columns) c
                                    full outer join unnest(old_columns) oc
                                        on (c).name = (oc).name
                                where
                                    coalesce((c).is_selectable, (oc).is_selectable)
                                    and (working_selected_columns is null or coalesce((c).name, (oc).name) = any(working_selected_columns) or coalesce((c).is_pkey, (oc).is_pkey))
                                    and ( not error_record_exceeds_max_size or (octet_length((c).value::text) <= 64))
                            )
                        )
                    else '{}'::jsonb
                end
                -- Add "old_record" key for update and delete
                || case
                    when action = 'UPDATE' then
                        jsonb_build_object(
                                'old_record',
                                (
                                    select jsonb_object_agg((c).name, (c).value)
                                    from unnest(old_columns) c
                                    where
                                        (c).is_selectable
                                        and (working_selected_columns is null or (c).name = any(working_selected_columns) or (c).is_pkey)
                                        and ( not error_record_exceeds_max_size or (octet_length((c).value::text) <= 64))
                                )
                            )
                    when action = 'DELETE' then
                        jsonb_build_object(
                            'old_record',
                            (
                                select jsonb_object_agg((c).name, (c).value)
                                from unnest(old_columns) c
                                where
                                    (c).is_selectable
                                    and (working_selected_columns is null or (c).name = any(working_selected_columns) or (c).is_pkey)
                                    and ( not error_record_exceeds_max_size or (octet_length((c).value::text) <= 64))
                                    and ( not is_rls_enabled or (c).is_pkey ) -- if RLS enabled, we can't secure deletes so filter to pkey
                            )
                        )
                    else '{}'::jsonb
                end;

                -- Filter visible_role_sub_ids to those matching the current selected_columns group
                visible_to_subscription_ids = coalesce(
                    (
                        select array_agg(s.subscription_id)
                        from unnest(subscriptions) s
                        where s.claims_role = working_role
                          and (s.selected_columns is not distinct from working_selected_columns)
                          and s.subscription_id = any(visible_role_sub_ids)
                    ),
                    '{}'::uuid[]
                );

                return next (
                    output,
                    is_rls_enabled,
                    visible_to_subscription_ids,
                    case
                        when error_record_exceeds_max_size then array['Error 413: Payload Too Large']
                        else '{}'
                    end
                )::realtime.wal_rls;
            end loop;

        end if;
    end loop;

    perform set_config('role', null, true);
end;
$$;


--
-- Name: authorize(text, text, text, text, text, text[], text[]); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.authorize(role_name text, topic_name text, claims text, sub text, headers text, read_extensions text[], write_extensions text[], OUT read_allowed boolean[], OUT write_allowed boolean[]) RETURNS record
    LANGUAGE plpgsql
    AS $$
declare
  probe_ids uuid[];
  probe_inserted_at timestamp := now() at time zone 'utc';
  visible_ids uuid[];
  ext text;
  allowed boolean;
begin
  -- The probe inserts are rolled back, but they still give the transaction an xid, so it ends
  -- in a commit. Nothing durable was written, so skip waiting on the WAL flush and sync standbys.
  -- Set outside the block below, whose rollback would undo it.
  perform set_config('synchronous_commit', 'off', true);

  -- The RAISE at the end of this block rolls back everything in it.
  begin
    probe_ids := array(select gen_random_uuid() from unnest(read_extensions));

    insert into realtime.messages (id, topic, extension, inserted_at, updated_at)
    select p.id, topic_name, p.extension, probe_inserted_at, probe_inserted_at
    from unnest(probe_ids, read_extensions) as p(id, extension);

    perform set_config('role', role_name, true),
            set_config('realtime.topic', topic_name, true),
            set_config('request.jwt.claims', claims, true),
            set_config('request.jwt.claim.sub', sub, true),
            set_config('request.jwt.claim.role', role_name, true),
            set_config('request.headers', headers, true);

    -- One lookup for every probe, by the full primary key. Skipped without probes, so the
    -- SELECT policies are not planned for a write.
    if cardinality(probe_ids) > 0 then
      visible_ids := array(
        select m.id
        from realtime.messages m
        where m.inserted_at = probe_inserted_at
          and m.id = any(probe_ids));
    end if;

    read_allowed := array(
      select p.id = any(visible_ids)
      from unnest(probe_ids) with ordinality as p(id, n)
      order by p.n);

    write_allowed := '{}';

    foreach ext in array write_extensions loop
      begin
        insert into realtime.messages (topic, extension, inserted_at, updated_at)
        values (topic_name, ext, now() at time zone 'utc', now() at time zone 'utc');

        allowed := true;
      exception when insufficient_privilege then
        allowed := false;
      end;

      write_allowed := write_allowed || allowed;
    end loop;

    raise sqlstate 'RTA01';
  exception when sqlstate 'RTA01' then
    null;
  end;
end;
$$;


--
-- Name: broadcast_changes(text, text, text, text, text, record, record, text); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.broadcast_changes(topic_name text, event_name text, operation text, table_name text, table_schema text, new record, old record, level text DEFAULT 'ROW'::text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    -- Declare a variable to hold the JSONB representation of the row
    row_data jsonb := '{}'::jsonb;
BEGIN
    IF level = 'STATEMENT' THEN
        RAISE EXCEPTION 'function can only be triggered for each row, not for each statement';
    END IF;
    -- Check the operation type and handle accordingly
    IF operation = 'INSERT' OR operation = 'UPDATE' OR operation = 'DELETE' THEN
        row_data := jsonb_build_object('old_record', OLD, 'record', NEW, 'operation', operation, 'table', table_name, 'schema', table_schema);
        PERFORM realtime.send (row_data, event_name, topic_name);
    ELSE
        RAISE EXCEPTION 'Unexpected operation type: %', operation;
    END IF;
EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Failed to process the row: %', SQLERRM;
END;

$$;


--
-- Name: build_prepared_statement_sql(text, regclass, realtime.wal_column[]); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.build_prepared_statement_sql(prepared_statement_name text, entity regclass, columns realtime.wal_column[]) RETURNS text
    LANGUAGE sql
    AS $$
      /*
      Builds a sql string that, if executed, creates a prepared statement to
      tests retrive a row from *entity* by its primary key columns.
      Example
          select realtime.build_prepared_statement_sql('public.notes', '{"id"}'::text[], '{"bigint"}'::text[])
      */
          select
      'prepare ' || prepared_statement_name || ' as
          select
              exists(
                  select
                      1
                  from
                      ' || entity || '
                  where
                      ' || string_agg(quote_ident(pkc.name) || '=' || quote_nullable(pkc.value #>> '{}') , ' and ') || '
              )'
          from
              unnest(columns) pkc
          where
              pkc.is_pkey
          group by
              entity
      $$;


--
-- Name: cast(text, regtype); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime."cast"(val text, type_ regtype) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    AS $$
declare
  res jsonb;
begin
  if type_::text = 'bytea' then
    return to_jsonb(val);
  end if;
  execute format('select to_jsonb(%L::'|| type_::text || ')', val) into res;
  return res;
end
$$;


--
-- Name: check_equality_op(realtime.equality_op, regtype, text, text); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.check_equality_op(op realtime.equality_op, type_ regtype, val_1 text, val_2 text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $$
/*
Casts *val_1* and *val_2* as type *type_* and check the *op* condition for truthiness
*/
declare
    op_symbol text = (
        case
            when op = 'eq' then '='
            when op = 'neq' then '!='
            when op = 'lt' then '<'
            when op = 'lte' then '<='
            when op = 'gt' then '>'
            when op = 'gte' then '>='
            when op = 'in' then '= any'
            else 'UNKNOWN OP'
        end
    );
    res boolean;
begin
    execute format(
        'select %L::'|| type_::text || ' ' || op_symbol
        || ' ( %L::'
        || (
            case
                when op = 'in' then type_::text || '[]'
                else type_::text end
        )
        || ')', val_1, val_2) into res;
    return res;
end;
$$;


--
-- Name: check_equality_op(realtime.equality_op, regtype, text, text, boolean); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.check_equality_op(op realtime.equality_op, type_ regtype, val_1 text, val_2 text, negate boolean) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $$
declare
    op_symbol text;
    res boolean;
begin
    -- IS DISTINCT FROM / IS NOT DISTINCT FROM: infix, both sides typed literals
    if op = 'isdistinct' then
        execute format(
            'select %L::%s %s %L::%s',
            val_1,
            type_::text,
            case when negate then 'IS NOT DISTINCT FROM' else 'IS DISTINCT FROM' end,
            val_2,
            type_::text
        ) into res;
        return res;
    end if;

    -- IS requires a keyword RHS (NULL, TRUE, FALSE, UNKNOWN), not a typed literal
    if op = 'is' then
        if val_2 not in ('null', 'true', 'false', 'unknown') then
            raise exception 'invalid value for is filter: must be null, true, false, or unknown';
        end if;
        execute format(
            'select %L::%s %s %s',
            val_1,
            type_::text,
            case when negate then 'IS NOT' else 'IS' end,
            upper(val_2)
        ) into res;
        return res;
    end if;

    op_symbol = case
        when op = 'eq'    then '='
        when op = 'neq'   then '!='
        when op = 'lt'    then '<'
        when op = 'lte'   then '<='
        when op = 'gt'    then '>'
        when op = 'gte'   then '>='
        when op = 'in'    then '= any'
        when op = 'like'   then 'LIKE'
        when op = 'ilike'  then 'ILIKE'
        when op = 'match'  then '~'
        when op = 'imatch' then '~*'
        else null
    end;

    if op_symbol is null then
        raise exception 'unsupported equality operator: %', op::text;
    end if;

    execute format(
        'select %L::%s %s (%L::%s)',
        val_1,
        type_::text,
        op_symbol,
        val_2,
        case when op = 'in' then type_::text || '[]' else type_::text end
    ) into res;

    return case when negate then not res else res end;
end;
$$;


--
-- Name: filters_hash(realtime.user_defined_filter[]); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.filters_hash(filters realtime.user_defined_filter[]) RETURNS bytea
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    AS $$
  select pg_catalog.int8send(pg_catalog.hash_array_extended(filters, 0))
      || pg_catalog.int8send(pg_catalog.hash_array_extended(filters, 1))
$$;


--
-- Name: is_visible_through_filters(realtime.wal_column[], realtime.user_defined_filter[]); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.is_visible_through_filters(columns realtime.wal_column[], filters realtime.user_defined_filter[]) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    select
        filters is null
        or array_length(filters, 1) is null
        or coalesce(
            count(col.name) = count(1)
            and sum(
                realtime.check_equality_op(
                    op:=f.op,
                    type_:=coalesce(col.type_oid::regtype, col.type_name::regtype),
                    val_1:=col.value #>> '{}',
                    val_2:=f.value,
                    negate:=coalesce(f.negate, false)
                )::int
            ) filter (where col.name is not null) = count(col.name),
            false
        )
    from
        unnest(filters) f
        left join unnest(columns) col
            on f.column_name = col.name;
$$;


--
-- Name: list_changes(name, name, integer, integer); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.list_changes(publication name, slot_name name, max_changes integer, max_record_bytes integer) RETURNS TABLE(wal jsonb, is_rls_enabled boolean, subscription_ids uuid[], errors text[], slot_changes_count bigint)
    LANGUAGE sql
    SET log_min_messages TO 'fatal'
    AS $$
  WITH pub AS (
    SELECT
      concat_ws(
        ',',
        CASE WHEN bool_or(pubinsert) THEN 'insert' ELSE NULL END,
        CASE WHEN bool_or(pubupdate) THEN 'update' ELSE NULL END,
        CASE WHEN bool_or(pubdelete) THEN 'delete' ELSE NULL END
      ) AS w2j_actions,
      coalesce(
        string_agg(
          realtime.quote_wal2json(format('%I.%I', schemaname, tablename)::regclass),
          ','
        ) filter (WHERE ppt.tablename IS NOT NULL),
        ''
      ) AS w2j_add_tables
    FROM pg_publication pp
    LEFT JOIN pg_publication_tables ppt ON pp.pubname = ppt.pubname
    WHERE pp.pubname = publication
    GROUP BY pp.pubname
    LIMIT 1
  ),
  -- MATERIALIZED ensures pg_logical_slot_get_changes is called exactly once
  w2j AS MATERIALIZED (
    SELECT x.*, pub.w2j_add_tables
    FROM pub,
         pg_logical_slot_get_changes(
           slot_name, null, max_changes,
           'include-pk', 'true',
           'include-transaction', 'false',
           'include-timestamp', 'true',
           'include-type-oids', 'true',
           'format-version', '2',
           'actions', pub.w2j_actions,
           'add-tables', pub.w2j_add_tables
         ) x
  ),
  slot_count AS (
    SELECT count(*)::bigint AS cnt
    FROM w2j
    WHERE w2j.w2j_add_tables <> ''
  ),
  rls_filtered AS (
    SELECT xyz.wal, xyz.is_rls_enabled, xyz.subscription_ids, xyz.errors
    FROM w2j,
         realtime.apply_rls(
           wal := w2j.data::jsonb,
           max_record_bytes := max_record_bytes
         ) xyz(wal, is_rls_enabled, subscription_ids, errors)
    WHERE w2j.w2j_add_tables <> ''
      AND xyz.subscription_ids[1] IS NOT NULL
  )
  SELECT rf.wal, rf.is_rls_enabled, rf.subscription_ids, rf.errors, sc.cnt
  FROM rls_filtered rf, slot_count sc

  UNION ALL

  SELECT null, null, null, null, sc.cnt
  FROM slot_count sc
  WHERE NOT EXISTS (SELECT 1 FROM rls_filtered)
$$;


--
-- Name: list_changes_sync(name, name, integer, integer); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.list_changes_sync(publication name, slot_name name, max_changes integer, max_record_bytes integer) RETURNS TABLE(wal jsonb, is_rls_enabled boolean, subscription_ids uuid[], errors text[], slot_changes_count bigint)
    LANGUAGE sql
    SET log_min_messages TO 'fatal'
    AS $$
  WITH pub AS (
    SELECT
      concat_ws(
        ',',
        CASE WHEN bool_or(pubinsert) THEN 'insert' ELSE NULL END,
        CASE WHEN bool_or(pubupdate) THEN 'update' ELSE NULL END,
        CASE WHEN bool_or(pubdelete) THEN 'delete' ELSE NULL END
      ) AS w2j_actions,
      coalesce(
        string_agg(
          realtime.quote_wal2json(format('%I.%I', schemaname, tablename)::regclass),
          ','
        ) filter (WHERE ppt.tablename IS NOT NULL),
        ''
      ) AS w2j_add_tables
    FROM pg_publication pp
    LEFT JOIN pg_publication_tables ppt ON pp.pubname = ppt.pubname
    WHERE pp.pubname = publication
    GROUP BY pp.pubname
    LIMIT 1
  ),
  -- MATERIALIZED ensures the slot is read exactly once.
  consumed AS MATERIALIZED (
    SELECT x.*, pub.w2j_add_tables
    FROM pub,
         realtime.settled_changes(
           slot_name, max_changes,
           'include-pk', 'true',
           'include-transaction', 'false',
           'include-timestamp', 'true',
           'include-type-oids', 'true',
           'format-version', '2',
           'actions', pub.w2j_actions,
           'add-tables', pub.w2j_add_tables
         ) x
  ),
  slot_count AS (
    SELECT count(*)::bigint AS cnt
    FROM consumed
    WHERE consumed.w2j_add_tables <> ''
  ),
  rls_filtered AS (
    SELECT xyz.wal, xyz.is_rls_enabled, xyz.subscription_ids, xyz.errors
    FROM consumed,
         realtime.apply_rls(
           wal := consumed.data::jsonb,
           max_record_bytes := max_record_bytes
         ) xyz(wal, is_rls_enabled, subscription_ids, errors)
    WHERE consumed.w2j_add_tables <> ''
      AND xyz.subscription_ids[1] IS NOT NULL
  )
  SELECT rf.wal, rf.is_rls_enabled, rf.subscription_ids, rf.errors, sc.cnt
  FROM rls_filtered rf, slot_count sc

  UNION ALL

  SELECT null, null, null, null, sc.cnt
  FROM slot_count sc
  WHERE NOT EXISTS (SELECT 1 FROM rls_filtered)
$$;


--
-- Name: quote_wal2json(regclass); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.quote_wal2json(entity regclass) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
  SELECT
    realtime.wal2json_escape_identifier(nsp.nspname::text)
    || '.'
    || realtime.wal2json_escape_identifier(pc.relname::text)
  FROM pg_class pc
  JOIN pg_namespace nsp ON pc.relnamespace = nsp.oid
  WHERE pc.oid = entity
$$;


--
-- Name: send(jsonb, text, text, boolean); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.send(payload jsonb, event text, topic text, private boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  generated_id uuid;
  final_payload jsonb;
BEGIN
  BEGIN
    generated_id := gen_random_uuid();

    -- Check if payload has an 'id' key, if not, add the generated UUID
    IF payload ? 'id' THEN
      final_payload := payload;
    ELSE
      final_payload := jsonb_set(payload, '{id}', to_jsonb(generated_id));
    END IF;

    -- Set the topic configuration
    EXECUTE format('SET LOCAL realtime.topic TO %L', topic);

    INSERT INTO realtime.messages (id, payload, event, topic, private, extension)
    VALUES (generated_id, final_payload, event, topic, private, 'broadcast');
  EXCEPTION
    WHEN OTHERS THEN
      RAISE WARNING 'WarnSendingBroadcastMessage: %', SQLERRM;
  END;
END;
$$;


--
-- Name: send_binary(bytea, text, text, boolean); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.send_binary(payload bytea, event text, topic text, private boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  generated_id uuid;
BEGIN
  BEGIN
    generated_id := gen_random_uuid();

    EXECUTE format('SET LOCAL realtime.topic TO %L', topic);

    INSERT INTO realtime.messages (id, binary_payload, event, topic, private, extension)
    VALUES (generated_id, payload, event, topic, private, 'broadcast');
  EXCEPTION
    WHEN OTHERS THEN
      RAISE WARNING 'WarnSendingBroadcastMessage: %', SQLERRM;
  END;
END;
$$;


--
-- Name: settled_changes(name, integer, text[]); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.settled_changes(slot_name name, max_changes integer, VARIADIC opts text[]) RETURNS TABLE(lsn pg_lsn, xid xid, data text)
    LANGUAGE plpgsql
    AS $$
declare
  upto pg_lsn;
  total bigint;
  xids xid[];
  starts bigint[];
  snapshot pg_snapshot;
  running_xids xid[];
  xmax_age int;
  cut bigint;
begin
  -- Each statement in a volatile function takes its own snapshot, which is what lets the
  -- check below see a writer that was still in flight when the peek ran. Under REPEATABLE
  -- READ the snapshot never advances, so a deferred change would never be released.
  if current_setting('transaction_isolation') <> 'read committed' then
    raise exception 'realtime.settled_changes requires READ COMMITTED';
  end if;

  -- The peek and the read below cover the same WAL, so the read cannot reach a commit the
  -- check never saw.
  upto := pg_current_wal_flush_lsn();

  -- One entry per transaction, in commit order: its xid and the position of its first
  -- change. The peek uses the caller's own options, so max_changes counts exactly what the
  -- read counts. A non-transactional logical message is emitted as soon as it is decoded,
  -- tagged with the xid of whatever transaction wrote it, so it does not mark where that
  -- transaction starts.
  select coalesce(sum(g.n), 0),
         array_agg(g.x order by g.first) filter (where g.first is not null),
         array_agg(g.first order by g.first) filter (where g.first is not null)
    into total, xids, starts
    from (
      select p.xid as x, count(*) as n,
             min(p.ord) filter (where not case
               when starts_with(p.data, '{"action":"M"') then (p.data::jsonb->>'transactional')::boolean is false
               else false
             end) as first
      from pg_logical_slot_peek_changes(slot_name, upto, max_changes, variadic opts)
           with ordinality as p(lsn, xid, data, ord)
      group by p.xid
    ) g;

  -- Nothing for the caller, but the slot still has to move past what the peek covered.
  if total = 0 then
    perform pg_replication_slot_advance(slot_name, upto);
    return;
  end if;

  if xids is not null then
    -- Taken after the peek is materialized, so a writer that was still in flight during
    -- decoding is guaranteed to show up here.
    snapshot := pg_current_snapshot();

    -- A commit record reaches the WAL before the writer leaves the proc array, so a change
    -- can be decoded while its row is invisible. apply_rls would resolve a policy against a
    -- row it cannot see and authorize it for nobody, while the read consumed it regardless.
    --
    -- xip lists transactions running when the snapshot was taken. It does not cover a writer
    -- whose xid sits at or beyond xmax, which never appears there, so the horizon is checked
    -- too. age() counts backwards from the current xid and so compares correctly across
    -- wraparound.
    select coalesce(array_agg(running.x::xid), array[]::xid[])
      into running_xids
      from pg_snapshot_xip(snapshot) running(x);
    xmax_age := age(pg_snapshot_xmax(snapshot)::xid);

    select min(u.s) into cut
      from unnest(xids, starts) as u(x, s)
      where u.x = any(running_xids) or age(u.x) <= xmax_age;
  end if;

  -- The read stops right after the commit that brings its count to upto_nchanges, so the
  -- count of changes in front of the first unsettled transaction stops it just before that
  -- transaction.
  if cut is null then
    return query
      select p.* from pg_logical_slot_get_changes(slot_name, upto, max_changes, variadic opts) p;
  elsif cut > 1 then
    return query
      select p.* from pg_logical_slot_get_changes(slot_name, upto, (cut - 1)::int, variadic opts) p;
  end if;
end;
$$;


--
-- Name: subscription_check_filters(); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.subscription_check_filters() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
    col_names text[] = coalesce(
            array_agg(a.attname order by a.attnum),
            '{}'::text[]
        )
        from
            pg_catalog.pg_attribute a
        where
            a.attrelid = new.entity
            and a.attnum > 0
            and not a.attisdropped
            and pg_catalog.has_column_privilege(
                (new.claims ->> 'role'),
                a.attrelid,
                a.attnum,
                'SELECT'
            );
    filter realtime.user_defined_filter;
    col_type regtype;
    in_val jsonb;
    selected_col text;
begin
    for filter in select * from unnest(new.filters) loop
        if not filter.column_name = any(col_names) then
            raise exception 'invalid column for filter %', filter.column_name;
        end if;

        col_type = (
            select atttypid::regtype
            from pg_catalog.pg_attribute
            where attrelid = new.entity
                  and attname = filter.column_name
        );
        if col_type is null then
            raise exception 'failed to lookup type for column %', filter.column_name;
        end if;

        if filter.op = 'in'::realtime.equality_op then
            in_val = realtime.cast(filter.value, (col_type::text || '[]')::regtype);
            if coalesce(jsonb_array_length(in_val), 0) > 100 then
                raise exception 'too many values for `in` filter. Maximum 100';
            end if;
        elsif filter.op = 'is'::realtime.equality_op then
            -- `is` requires a keyword RHS rather than a typed literal
            if filter.value not in ('null', 'true', 'false', 'unknown') then
                raise exception 'invalid value for is filter: must be null, true, false, or unknown';
            end if;
            -- IS NULL works for any type, but IS TRUE/FALSE/UNKNOWN require a boolean
            -- operand. Reject the non-null keywords on non-boolean columns here so they
            -- don't abort apply_rls at WAL time.
            if filter.value <> 'null' and col_type <> 'boolean'::regtype then
                raise exception 'is % filter requires a boolean column, got %', filter.value, col_type::text;
            end if;
        elsif filter.op in ('like'::realtime.equality_op, 'ilike'::realtime.equality_op) then
            -- like/ilike apply the text pattern operator (~~); reject column types that
            -- have no such operator instead of failing at WAL time
            if not exists (
                select 1 from pg_catalog.pg_operator
                where oprname = '~~' and oprleft = col_type
            ) then
                raise exception 'operator % requires a text-compatible column type, got %', filter.op::text, col_type::text;
            end if;
        elsif filter.op in ('match'::realtime.equality_op, 'imatch'::realtime.equality_op) then
            -- match/imatch apply the regex operators ~ / ~*; reject column types that have
            -- no such operator (e.g. integer) instead of failing at WAL time, mirroring the
            -- like/ilike guard above.
            if not exists (
                select 1 from pg_catalog.pg_operator
                where oprname = case when filter.op = 'imatch'::realtime.equality_op then '~*' else '~' end
                  and oprleft = col_type
                  and oprright = col_type
                  and oprresult = 'boolean'::regtype
            ) then
                raise exception 'operator % requires a text-compatible column type, got %', filter.op::text, col_type::text;
            end if;
            -- validate the regex eagerly so a bad pattern is rejected here, not inside
            -- apply_rls where it would abort the WAL stream for the entity
            begin
                perform '' ~ filter.value;
            exception when others then
                raise exception 'invalid regular expression for % filter: %', filter.op::text, sqlerrm;
            end;
        else
            -- eq/neq/lt/lte/gt/gte: value must be coercable to the type
            perform realtime.cast(filter.value, col_type);
        end if;
    end loop;

    if new.selected_columns is not null then
        for selected_col in select * from unnest(new.selected_columns) loop
            if not selected_col = any(col_names) then
                raise exception 'invalid column for select %', selected_col;
            end if;
        end loop;
    end if;

    -- Apply consistent order to filters so the unique constraint can't be tricked by a
    -- different filter order. negate is part of the sort key.
    new.filters = coalesce(
        array_agg(f order by f.column_name, f.op, f.value, f.negate),
        '{}'
    ) from unnest(new.filters) f;

    -- Normalize selected_columns order so ARRAY['a','b'] and ARRAY['b','a'] are treated
    -- as the same subscription group in apply_rls. Preserve an empty array as '{}'
    -- ("primary keys only") so it stays distinct from NULL ("all columns"); array_agg
    -- over an empty set would otherwise collapse '{}' back to NULL.
    if new.selected_columns is not null then
        new.selected_columns = coalesce(
            (
                select array_agg(c order by c)
                from unnest(new.selected_columns) c
            ),
            '{}'::text[]
        );
    end if;

    return new;
end;
$$;


--
-- Name: to_regrole(text); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.to_regrole(role_name text) RETURNS regrole
    LANGUAGE sql IMMUTABLE
    AS $$ select role_name::regrole $$;


--
-- Name: topic(); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.topic() RETURNS text
    LANGUAGE sql STABLE
    AS $$
select nullif(current_setting('realtime.topic', true), '')::text;
$$;


--
-- Name: wal2json_escape_identifier(text); Type: FUNCTION; Schema: realtime; Owner: -
--

CREATE FUNCTION realtime.wal2json_escape_identifier(name text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
  -- Prefix `\`, `,`, `.`, and any whitespace with `\`
  SELECT regexp_replace(name, '([\\,.[:space:]])', '\\\1', 'g')
$$;


--
-- Name: allow_any_operation(text[]); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.allow_any_operation(expected_operations text[]) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  WITH current_operation AS (
    SELECT storage.operation() AS raw_operation
  ),
  normalized AS (
    SELECT CASE
      WHEN raw_operation LIKE 'storage.%' THEN substr(raw_operation, 9)
      ELSE raw_operation
    END AS current_operation
    FROM current_operation
  )
  SELECT EXISTS (
    SELECT 1
    FROM normalized n
    CROSS JOIN LATERAL unnest(expected_operations) AS expected_operation
    WHERE expected_operation IS NOT NULL
      AND expected_operation <> ''
      AND n.current_operation = CASE
        WHEN expected_operation LIKE 'storage.%' THEN substr(expected_operation, 9)
        ELSE expected_operation
      END
  );
$$;


--
-- Name: allow_only_operation(text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.allow_only_operation(expected_operation text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  WITH current_operation AS (
    SELECT storage.operation() AS raw_operation
  ),
  normalized AS (
    SELECT
      CASE
        WHEN raw_operation LIKE 'storage.%' THEN substr(raw_operation, 9)
        ELSE raw_operation
      END AS current_operation,
      CASE
        WHEN expected_operation LIKE 'storage.%' THEN substr(expected_operation, 9)
        ELSE expected_operation
      END AS requested_operation
    FROM current_operation
  )
  SELECT CASE
    WHEN requested_operation IS NULL OR requested_operation = '' THEN FALSE
    ELSE COALESCE(current_operation = requested_operation, FALSE)
  END
  FROM normalized;
$$;


--
-- Name: can_insert_object(text, text, uuid, jsonb); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.can_insert_object(bucketid text, name text, owner uuid, metadata jsonb) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO "storage"."objects" ("bucket_id", "name", "owner", "metadata") VALUES (bucketid, name, owner, metadata);
  -- hack to rollback the successful insert
  RAISE sqlstate 'PT200' using
  message = 'ROLLBACK',
  detail = 'rollback successful insert';
END
$$;


--
-- Name: delete_lifecycle_objects(uuid[]); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.delete_lifecycle_objects(object_ids uuid[]) RETURNS TABLE(id uuid, is_delete_marker boolean, metadata jsonb)
    LANGUAGE plpgsql
    AS $$
DECLARE
    object_id uuid;
    deleted_row storage.objects%ROWTYPE;
    deleted_ids uuid[];
    deleted_markers boolean[];
    deleted_metadata jsonb[];
    bulk_deleted boolean := false;
BEGIN
    -- Surface pre-existing deferred violations instead of treating them as blocked rows.
    SET CONSTRAINTS ALL IMMEDIATE;
    PERFORM set_config('storage.allow_delete_query', 'true', true);

    -- One subxact keeps the subxid cache from overflowing; rows return only once it commits.
    BEGIN
        WITH deleted AS (
            DELETE FROM storage.objects AS object_row
              WHERE object_row.id = ANY(object_ids) AND object_row.archived_at IS NOT NULL
              RETURNING object_row.id, object_row.is_delete_marker, object_row.metadata
        )
        SELECT array_agg(deleted.id), array_agg(deleted.is_delete_marker), array_agg(deleted.metadata)
          INTO deleted_ids, deleted_markers, deleted_metadata
          FROM deleted;
        bulk_deleted := true;
    EXCEPTION
        WHEN OTHERS THEN
            -- User triggers may use insufficient_privilege to block a row.
            IF SQLSTATE <> '42501' AND left(SQLSTATE, 2) IN ('08', '40', '42', '53', '55', '57', '58', 'XX') THEN
                RAISE;
            END IF;
    END;
    IF bulk_deleted THEN
        RETURN QUERY SELECT * FROM unnest(deleted_ids, deleted_markers, deleted_metadata);
        RETURN;
    END IF;

    FOREACH object_id IN ARRAY object_ids LOOP
        BEGIN
            DELETE FROM storage.objects AS object_row
              WHERE object_row.id = object_id AND object_row.archived_at IS NOT NULL
              RETURNING object_row.* INTO deleted_row;
            IF FOUND THEN
                id := deleted_row.id;
                is_delete_marker := deleted_row.is_delete_marker;
                metadata := deleted_row.metadata;
                RETURN NEXT;
            END IF;
        EXCEPTION
            WHEN OTHERS THEN
                IF SQLSTATE <> '42501' AND left(SQLSTATE, 2) IN ('08', '40', '42', '53', '55', '57', '58', 'XX') THEN
                    RAISE;
                END IF;
        END;
    END LOOP;
END;
$$;


--
-- Name: enforce_bucket_lifecycle_service_role(); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.enforce_bucket_lifecycle_service_role() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF current_user::text IS DISTINCT FROM TG_ARGV[0] THEN
    -- Keep this check AFTER caller RLS accepts the proposed row. The API
    -- recognizes this exact signal after rolling back its permission probe.
    RAISE EXCEPTION 'bucket control columns may only be changed by the configured storage service role'
      USING ERRCODE = 'PST01',
            SCHEMA = TG_TABLE_SCHEMA,
            TABLE = TG_TABLE_NAME,
            CONSTRAINT = TG_NAME;
  END IF;

  RETURN NULL;
END;
$$;


--
-- Name: enforce_bucket_name_length(); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.enforce_bucket_name_length() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
    if length(new.name) > 100 then
        raise exception 'bucket name "%" is too long (% characters). Max is 100.', new.name, length(new.name);
    end if;
    return new;
end;
$$;


--
-- Name: enforce_versioning_status_transition(); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.enforce_versioning_status_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.versioning_status = OLD.versioning_status THEN
        RETURN NEW;
    END IF;

    IF NEW.versioning_status = 'DISABLED' OR
       (OLD.versioning_status = 'DISABLED' AND NEW.versioning_status = 'SUSPENDED') THEN
        RAISE EXCEPTION 'Cannot transition bucket versioning status from % to %',
            OLD.versioning_status, NEW.versioning_status;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: extension(text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.extension(name text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    _parts text[];
    _filename text;
BEGIN
    -- Split on "/" to get path segments
    SELECT string_to_array(name, '/') INTO _parts;
    -- Get the last path segment (the actual filename)
    SELECT _parts[array_length(_parts, 1)] INTO _filename;
    -- Extract extension: reverse, split on '.', then reverse again
    RETURN reverse(split_part(reverse(_filename), '.', 1));
END
$$;


--
-- Name: filename(text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.filename(name text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    _parts text[];
BEGIN
    SELECT string_to_array(name, '/') INTO _parts;
    RETURN _parts[array_length(_parts, 1)];
END
$$;


--
-- Name: foldername(text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.foldername(name text) RETURNS text[]
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    _parts text[];
BEGIN
    -- Split on "/" to get path segments
    SELECT string_to_array(name, '/') INTO _parts;
    -- Return everything except the last segment
    RETURN _parts[1 : array_length(_parts,1) - 1];
END
$$;


--
-- Name: get_common_prefix(text, text, text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.get_common_prefix(p_key text, p_prefix text, p_delimiter text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
SELECT CASE
    WHEN p_delimiter <> ''
         AND position(p_delimiter IN substring(p_key FROM length(p_prefix) + 1)) > 0
    THEN left(
        p_key,
        length(p_prefix)
            + position(p_delimiter IN substring(p_key FROM length(p_prefix) + 1))
            + length(p_delimiter) - 1
    )
    ELSE NULL
END;
$$;


--
-- Name: get_size_by_bucket(text, text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.get_size_by_bucket(noncurrent_versions text DEFAULT 'include'::text, delete_markers text DEFAULT 'include'::text) RETURNS TABLE(size bigint, bucket_id text)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    -- COALESCE first: NULL NOT IN (...) evaluates to NULL (not TRUE), so a
    -- bare NOT IN check silently leaves an explicit NULL argument unreset.
    noncurrent_versions := COALESCE(noncurrent_versions, 'include');
    delete_markers := COALESCE(delete_markers, 'include');
    IF noncurrent_versions NOT IN ('exclude', 'only', 'include') THEN
        noncurrent_versions := 'include';
    END IF;
    IF delete_markers NOT IN ('exclude', 'only', 'include') THEN
        delete_markers := 'include';
    END IF;

    return query
        select sum((metadata->>'size')::bigint)::bigint as size, obj.bucket_id
        from "storage".objects as obj
        where (noncurrent_versions != 'exclude' OR obj.archived_at IS NULL)
          and (noncurrent_versions != 'only' OR obj.archived_at IS NOT NULL)
          and (delete_markers != 'exclude' OR NOT obj.is_delete_marker)
          and (delete_markers != 'only' OR obj.is_delete_marker)
        group by obj.bucket_id;
END
$$;


--
-- Name: list_multipart_uploads_with_delimiter(text, text, text, integer, text, text, text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.list_multipart_uploads_with_delimiter(bucket_id text, prefix_param text, delimiter_param text, max_keys integer DEFAULT 100, next_key_token text DEFAULT ''::text, next_upload_token text DEFAULT ''::text, raw_prefix_param text DEFAULT NULL::text) RETURNS TABLE(key text, id text, created_at timestamp with time zone)
    LANGUAGE sql STABLE
    AS $_$
WITH candidates AS (
    SELECT
        upload.key AS object_key,
        CASE
            WHEN position($3 IN substring(upload.key FROM length(coalesce($7, $2)) + 1)) > 0
            THEN left(
                upload.key,
                length(coalesce($7, $2))
                    + position($3 IN substring(upload.key FROM length(coalesce($7, $2)) + 1))
                    + length($3) - 1
            )
            ELSE upload.key
        END AS result_key,
        upload.id,
        upload.created_at,
        position($3 IN substring(upload.key FROM length(coalesce($7, $2)) + 1)) > 0 AS is_common_prefix
    FROM storage.s3_multipart_uploads AS upload
    WHERE upload.bucket_id = $1
      AND upload.key COLLATE "C" LIKE $2 || '%'
), filtered AS (
    SELECT candidate.*
    FROM candidates AS candidate
    WHERE $5 = ''
       OR candidate.result_key COLLATE "C" > $5
       OR (
           candidate.result_key COLLATE "C" = $5
           AND NOT candidate.is_common_prefix
           AND $6 <> ''
           -- A completed or aborted marker repeats the remaining same-key uploads.
           AND COALESCE(
               (candidate.created_at, candidate.id COLLATE "C") > (
                   SELECT marker.created_at, marker.id COLLATE "C"
                   FROM storage.s3_multipart_uploads AS marker
                   WHERE marker.bucket_id = $1
                     AND marker.key COLLATE "C" = $5
                     AND marker.id = $6
               ),
               TRUE
           )
       )
), ranked AS (
    SELECT
        filtered.*,
        row_number() OVER (
            PARTITION BY filtered.result_key COLLATE "C"
            ORDER BY filtered.created_at, filtered.id COLLATE "C"
        ) AS prefix_rank
    FROM filtered
)
SELECT ranked.result_key, ranked.id, ranked.created_at
FROM ranked
WHERE NOT ranked.is_common_prefix OR ranked.prefix_rank = 1
ORDER BY ranked.result_key COLLATE "C", ranked.created_at, ranked.id COLLATE "C"
LIMIT $4;
$_$;


--
-- Name: list_objects_with_delimiter(text, text, text, integer, text, text, text, text, text, timestamp with time zone, text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.list_objects_with_delimiter(_bucket_id text, prefix_param text, delimiter_param text, max_keys integer DEFAULT 100, start_after text DEFAULT ''::text, next_token text DEFAULT ''::text, sort_order text DEFAULT 'asc'::text, noncurrent_versions text DEFAULT 'exclude'::text, delete_markers text DEFAULT 'exclude'::text, next_token_archived_at timestamp with time zone DEFAULT NULL::timestamp with time zone, next_token_version text DEFAULT ''::text) RETURNS TABLE(name text, id uuid, metadata jsonb, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone, version text, archived_at timestamp with time zone, is_delete_marker boolean, is_versioned boolean)
    LANGUAGE plpgsql STABLE
    AS $_$
DECLARE
    v_peek_name TEXT;
    v_current RECORD;
    v_common_prefix TEXT;

    -- Configuration
    v_is_asc BOOLEAN;
    v_prefix TEXT;
    v_start TEXT;
    v_start_relative TEXT;
    v_upper_bound TEXT;
    v_file_batch_size INT;
    v_version_filter TEXT;

    -- true when noncurrent_versions can return >1 row per name; keeps them
    -- ordered most-recent-first and lets pagination resume mid-key
    v_multi_row BOOLEAN;
    v_name_order TEXT;
    v_exact_range_predicate TEXT;
    v_strict_range_predicate TEXT;
    v_inclusive_range_predicate TEXT;

    -- Seek state for the current name. archived_at is normalized to JavaScript's
    -- millisecond precision and version breaks ties within the same millisecond.
    -- Current rows use 'infinity'; NULL means no tiebreak has been established.
    v_next_seek TEXT;
    v_next_seek_at TIMESTAMPTZ;
    v_next_seek_version TEXT;
    v_next_seek_strict BOOLEAN := false;
    v_cursor_is_folder BOOLEAN;
    v_count INT := 0;
    v_previous_seek TEXT;
    v_previous_seek_at TIMESTAMPTZ;
    v_previous_seek_version TEXT;
    v_previous_count INT;

    -- Dynamic SQL for batch query only
    v_batch_query TEXT;
    v_batch_query_strict TEXT;
    v_delete_marker_peek_query TEXT;
    v_delete_marker_peek_query_strict TEXT;

BEGIN
    -- ========================================================================
    -- INITIALIZATION
    -- ========================================================================
    v_is_asc := lower(coalesce(sort_order, 'asc')) = 'asc';
    v_prefix := coalesce(prefix_param, '');
    v_start := CASE WHEN coalesce(next_token, '') <> '' THEN next_token ELSE coalesce(start_after, '') END;
    v_file_batch_size := LEAST(GREATEST(max_keys * 2, 100), 1000);
    v_next_seek_at := NULL;
    v_next_seek_version := '';

    -- COALESCE first: NULL NOT IN (...) evaluates to NULL (not TRUE), so a
    -- bare NOT IN check silently leaves an explicit NULL argument unreset.
    noncurrent_versions := COALESCE(noncurrent_versions, 'exclude');
    delete_markers := COALESCE(delete_markers, 'exclude');
    IF noncurrent_versions NOT IN ('exclude', 'only', 'include') THEN
        noncurrent_versions := 'exclude';
    END IF;
    IF delete_markers NOT IN ('exclude', 'only', 'include') THEN
        delete_markers := 'exclude';
    END IF;

    v_multi_row := noncurrent_versions IN ('only', 'include');
    v_name_order := CASE WHEN v_is_asc THEN 'ASC' ELSE 'DESC' END;

    v_version_filter := '';
    IF noncurrent_versions = 'exclude' THEN
        v_version_filter := v_version_filter || ' AND o.archived_at IS NULL';
    ELSIF noncurrent_versions = 'only' THEN
        v_version_filter := v_version_filter || ' AND o.archived_at IS NOT NULL';
    END IF;
    IF delete_markers = 'exclude' THEN
        v_version_filter := v_version_filter || ' AND NOT o.is_delete_marker';
    ELSIF delete_markers = 'only' THEN
        v_version_filter := v_version_filter || ' AND o.is_delete_marker';
    END IF;

    -- Calculate upper bound for prefix filtering (bytewise, using COLLATE "C")
    IF v_prefix = '' THEN
        v_upper_bound := NULL;
    ELSE
        v_upper_bound := left(v_prefix, -1) || chr(ascii(right(v_prefix, 1)) + 1);
    END IF;

    -- Keep caller-provided cursors inside the requested prefix range.
    IF v_start <> '' AND v_upper_bound IS NOT NULL THEN
        IF v_is_asc THEN
            IF v_start COLLATE "C" < v_prefix COLLATE "C" THEN
                v_start := '';
            ELSIF v_start COLLATE "C" >= v_upper_bound COLLATE "C" THEN
                RETURN;
            END IF;
        ELSE
            IF v_start COLLATE "C" < v_prefix COLLATE "C" THEN
                RETURN;
            ELSIF v_start COLLATE "C" >= v_upper_bound COLLATE "C" THEN
                v_start := '';
            END IF;
        END IF;
    END IF;

    v_start_relative := substring(v_start FROM length(v_prefix) + 1);

    -- Direction affects only the indexed name range and its ordering. Cursor
    -- state transitions and within-key version ordering stay shared.
    IF v_is_asc THEN
        v_exact_range_predicate := 'TRUE';
        v_strict_range_predicate := 'o.name COLLATE "C" > $2';
        v_inclusive_range_predicate := 'o.name COLLATE "C" >= $2';
        IF v_upper_bound IS NOT NULL THEN
            v_exact_range_predicate := 'o.name COLLATE "C" < $3';
            v_strict_range_predicate := v_strict_range_predicate || ' AND o.name COLLATE "C" < $3';
            v_inclusive_range_predicate := v_inclusive_range_predicate || ' AND o.name COLLATE "C" < $3';
        END IF;
    ELSE
        v_exact_range_predicate := 'TRUE';
        v_strict_range_predicate := 'o.name COLLATE "C" < $2';
        v_inclusive_range_predicate := 'o.name COLLATE "C" < $2';
        IF v_prefix <> '' THEN
            v_exact_range_predicate := 'o.name COLLATE "C" >= $3';
            v_strict_range_predicate := v_strict_range_predicate || ' AND o.name COLLATE "C" >= $3';
            v_inclusive_range_predicate := v_inclusive_range_predicate || ' AND o.name COLLATE "C" >= $3';
        END IF;
    END IF;

    -- Build batch query (dynamic SQL - called infrequently, amortized over many rows)
    -- The multi-row order matches the externally serialized cursor exactly:
    -- archived_at at millisecond precision, then version as the final tiebreak.
    --
    -- When v_multi_row, the seek is a keyset tuple comparison ("name > $2 OR
    -- (name = $2 AND tiebreak)") - Postgres won't split that OR into indexable
    -- form (confirmed even with fully literal values), so as one WHERE clause
    -- it forces a full bucket scan filtered row-by-row. Splitting it into two
    -- independently-indexable branches (exact name match with the tiebreak
    -- filter, vs. strictly-past names) combined with UNION ALL lets each
    -- branch keep name as a real index condition; the outer ORDER BY/LIMIT
    -- re-merges them into the same page the single query used to produce.
    IF v_multi_row THEN
        v_batch_query := format(
            $sql$
            SELECT *
            FROM (
                (
                    SELECT o.name, o.id, o.updated_at, o.created_at,
                           o.last_accessed_at, o.metadata, o.version,
                           o.archived_at, o.is_delete_marker, o.is_versioned
                    FROM storage.objects o
                    WHERE o.bucket_id = $1
                      AND o.name COLLATE "C" = $2
                      AND %s
                      AND NOT $7::boolean
                      AND (
                          $5::timestamptz IS NULL
                          OR COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) < $5
                          OR (
                              COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) = $5
                              AND COALESCE(o.version, '') > $6
                          )
                      )
                      %s
                    ORDER BY
                        COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) DESC,
                        COALESCE(o.version, '') ASC
                    LIMIT $4
                )
                UNION ALL
                (
                    SELECT o.name, o.id, o.updated_at, o.created_at,
                           o.last_accessed_at, o.metadata, o.version,
                           o.archived_at, o.is_delete_marker, o.is_versioned
                    FROM storage.objects o
                    WHERE o.bucket_id = $1
                      AND %s
                      %s
                    ORDER BY
                        o.name COLLATE "C" %s,
                        COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) DESC,
                        COALESCE(o.version, '') ASC
                    LIMIT $4
                )
            ) sub
            ORDER BY
                sub.name COLLATE "C" %s,
                COALESCE(date_trunc('milliseconds', sub.archived_at), 'infinity'::timestamptz) DESC,
                COALESCE(sub.version, '') ASC
            LIMIT $4
            $sql$,
            v_exact_range_predicate,
            v_version_filter,
            v_strict_range_predicate,
            v_version_filter,
            v_name_order,
            v_name_order
        );
    ELSE
        v_batch_query := format(
            $sql$
            SELECT o.name, o.id, o.updated_at, o.created_at,
                   o.last_accessed_at, o.metadata, o.version,
                   o.archived_at, o.is_delete_marker, o.is_versioned
            FROM storage.objects o
            WHERE o.bucket_id = $1
              AND %s
              %s
            ORDER BY o.name COLLATE "C" %s, o.archived_at DESC
            LIMIT $4
            $sql$,
            v_inclusive_range_predicate,
            v_version_filter,
            v_name_order
        );

        -- Strict counterpart of the query above: used once the single-row
        -- ASC batch advance (below) has left v_next_seek pointing at the
        -- last row already emitted, so an inclusive predicate would
        -- re-match it forever. Only single-row mode ever sets strict mode,
        -- so this variant is never needed when v_multi_row.
        v_batch_query_strict := format(
            $sql$
            SELECT o.name, o.id, o.updated_at, o.created_at,
                   o.last_accessed_at, o.metadata, o.version,
                   o.archived_at, o.is_delete_marker, o.is_versioned
            FROM storage.objects o
            WHERE o.bucket_id = $1
              AND %s
              %s
            ORDER BY o.name COLLATE "C" %s, o.archived_at DESC
            LIMIT $4
            $sql$,
            v_strict_range_predicate,
            v_version_filter,
            v_name_order
        );
    END IF;

    -- The static peek predicates cannot use the partial delete-marker index
    -- once PL/pgSQL switches to a generic plan because whether
    -- is_delete_marker is required remains parameter-dependent. Reuse the
    -- already-specialized batch query with a one-row limit for this sparse
    -- filter so the plan sees a literal `o.is_delete_marker` predicate.
    IF delete_markers = 'only' THEN
        v_delete_marker_peek_query :=
            'SELECT marker_page.name FROM (' || v_batch_query || ') marker_page LIMIT 1';
        IF NOT v_multi_row THEN
            v_delete_marker_peek_query_strict :=
                'SELECT marker_page.name FROM (' || v_batch_query_strict || ') marker_page LIMIT 1';
        END IF;
    END IF;

    -- ========================================================================
    -- SEEK INITIALIZATION: Determine starting position
    -- ========================================================================
    IF v_start = '' THEN
        IF v_is_asc THEN
            v_next_seek := v_prefix;
        ELSE
            -- DESC without cursor performs one specialized initial seek so
            -- partial current-version and delete-marker indexes remain available.
            EXECUTE format(
                'SELECT o.name FROM storage.objects o WHERE o.bucket_id = $1%s%s ORDER BY o.name COLLATE "C" DESC LIMIT 1',
                CASE WHEN v_upper_bound IS NOT NULL
                    THEN ' AND o.name COLLATE "C" >= $2 AND o.name COLLATE "C" < $3'
                    ELSE ''
                END,
                v_version_filter
            )
            INTO v_next_seek
            USING _bucket_id, v_prefix, v_upper_bound;

            IF v_next_seek IS NOT NULL THEN
                v_next_seek := v_next_seek || delimiter_param;
            ELSE
                RETURN;
            END IF;
        END IF;
    ELSE
        -- Folder continuation tokens retain their trailing delimiter. A
        -- delimiter-less startAfter is always a literal key boundary.
        v_cursor_is_folder := delimiter_param <> ''
            AND v_start_relative <> ''
            AND right(v_start_relative, length(delimiter_param)) = delimiter_param;

        IF v_cursor_is_folder THEN
            v_next_seek := CASE
                WHEN right(v_start, length(delimiter_param)) = delimiter_param
                    THEN v_start
                ELSE v_start || delimiter_param
            END;
            IF v_is_asc THEN
                v_next_seek := left(v_next_seek, -1)
                    || chr(ascii(right(v_next_seek, 1)) + 1);
            END IF;
            v_next_seek_strict := NOT v_is_asc;
        ELSE
            -- leaf object: when v_multi_row, stay on v_start with the
            -- caller-supplied tiebreak so a page boundary mid-key resumes
            -- that key's remaining rows instead of skipping them. Truncate
            -- to milliseconds like every other v_next_seek_at assignment -
            -- harmless today since object.ts's cursor always round-trips
            -- through JS Date first, but this shouldn't rely on that.
            IF v_multi_row THEN
                v_next_seek := v_start;
                v_next_seek_at := date_trunc('milliseconds', next_token_archived_at);
                v_next_seek_version := coalesce(next_token_version, '');
                v_next_seek_strict := coalesce(next_token, '') = '';
            ELSIF v_is_asc THEN
                v_next_seek := v_start;
                v_next_seek_strict := true;
            ELSE
                v_next_seek := v_start;
            END IF;
        END IF;
    END IF;

    -- ========================================================================
    -- MAIN LOOP: Hybrid peek-then-batch algorithm
    -- Uses STATIC SQL for peek (hot path) and DYNAMIC SQL for batch
    -- ========================================================================
    LOOP
        EXIT WHEN v_count >= max_keys;

        v_previous_seek := v_next_seek;
        v_previous_seek_at := v_next_seek_at;
        v_previous_seek_version := v_next_seek_version;
        v_previous_count := v_count;

        -- STEP 1: PEEK using STATIC SQL (plan cached, very fast)
        -- v_multi_row is branched here (rather than folded into the WHERE
        -- clause as a bound parameter) so each concrete query keeps an
        -- unconditional seek predicate - once PL/pgSQL switches to its
        -- cached generic plan (after 5 calls), a parameter-gated
        -- "(NOT v_multi_row AND name >= $x) OR (v_multi_row AND ...)"
        -- predicate stops the planner from using name as an index
        -- condition at all, degrading every subsequent peek to a full
        -- index scan filtered row-by-row instead of a bounded range scan.
        -- v_multi_row's seek predicate is a keyset tuple comparison
        -- ("name > x OR (name = x AND tiebreak)") - Postgres does not
        -- split this OR into indexable form even with fully literal
        -- values, so it falls back to a full scan filtered row-by-row.
        -- Splitting it into two independently-indexable branches (exact
        -- name match with the tiebreak filter, vs. strictly-past name)
        -- combined with UNION ALL lets each branch keep name as a real
        -- index condition; the outer ORDER BY/LIMIT picks whichever of
        -- the (at most 2) rows sorts first.
        IF delete_markers = 'only' THEN
            EXECUTE CASE WHEN v_next_seek_strict AND NOT v_multi_row
                THEN v_delete_marker_peek_query_strict
                ELSE v_delete_marker_peek_query
            END
                INTO v_peek_name
                USING _bucket_id, v_next_seek,
                    CASE WHEN v_is_asc THEN COALESCE(v_upper_bound, v_prefix) ELSE v_prefix END,
                    1, v_next_seek_at, v_next_seek_version, v_next_seek_strict;
        ELSIF v_multi_row THEN
            IF v_is_asc THEN
                IF v_upper_bound IS NOT NULL THEN
                    SELECT sub.name INTO v_peek_name FROM (
                        (SELECT o.name FROM storage.objects o
                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" = v_next_seek
                           AND o.name COLLATE "C" < v_upper_bound
                           AND NOT v_next_seek_strict
                           AND (v_next_seek_at IS NULL
                                OR COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) < v_next_seek_at
                                OR (COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) = v_next_seek_at
                                    AND COALESCE(o.version, '') > v_next_seek_version))
                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)
                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)
                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                           AND (delete_markers != 'only' OR o.is_delete_marker)
                         ORDER BY COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) DESC, COALESCE(o.version, '') ASC LIMIT 1)
                        UNION ALL
                        (SELECT o.name FROM storage.objects o
                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" > v_next_seek AND o.name COLLATE "C" < v_upper_bound
                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)
                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)
                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                           AND (delete_markers != 'only' OR o.is_delete_marker)
                         ORDER BY o.name COLLATE "C" ASC LIMIT 1)
                    ) sub ORDER BY sub.name COLLATE "C" ASC LIMIT 1;
                ELSE
                    SELECT sub.name INTO v_peek_name FROM (
                        (SELECT o.name FROM storage.objects o
                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" = v_next_seek
                           AND NOT v_next_seek_strict
                           AND (v_next_seek_at IS NULL
                                OR COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) < v_next_seek_at
                                OR (COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) = v_next_seek_at
                                    AND COALESCE(o.version, '') > v_next_seek_version))
                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)
                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)
                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                           AND (delete_markers != 'only' OR o.is_delete_marker)
                         ORDER BY COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) DESC, COALESCE(o.version, '') ASC LIMIT 1)
                        UNION ALL
                        (SELECT o.name FROM storage.objects o
                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" > v_next_seek
                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)
                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)
                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                           AND (delete_markers != 'only' OR o.is_delete_marker)
                         ORDER BY o.name COLLATE "C" ASC LIMIT 1)
                    ) sub ORDER BY sub.name COLLATE "C" ASC LIMIT 1;
                END IF;
            ELSE
                IF v_upper_bound IS NOT NULL THEN
                    SELECT sub.name INTO v_peek_name FROM (
                        (SELECT o.name FROM storage.objects o
                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" = v_next_seek
                           AND o.name COLLATE "C" >= v_prefix
                           AND NOT v_next_seek_strict
                           AND (v_next_seek_at IS NULL
                                OR COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) < v_next_seek_at
                                OR (COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) = v_next_seek_at
                                    AND COALESCE(o.version, '') > v_next_seek_version))
                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)
                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)
                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                           AND (delete_markers != 'only' OR o.is_delete_marker)
                         ORDER BY COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) DESC, COALESCE(o.version, '') ASC LIMIT 1)
                        UNION ALL
                        (SELECT o.name FROM storage.objects o
                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" < v_next_seek AND o.name COLLATE "C" >= v_prefix
                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)
                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)
                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                           AND (delete_markers != 'only' OR o.is_delete_marker)
                         ORDER BY o.name COLLATE "C" DESC LIMIT 1)
                    ) sub ORDER BY sub.name COLLATE "C" DESC LIMIT 1;
                ELSE
                    SELECT sub.name INTO v_peek_name FROM (
                        (SELECT o.name FROM storage.objects o
                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" = v_next_seek
                           AND NOT v_next_seek_strict
                           AND (v_next_seek_at IS NULL
                                OR COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) < v_next_seek_at
                                OR (COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) = v_next_seek_at
                                    AND COALESCE(o.version, '') > v_next_seek_version))
                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)
                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)
                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                           AND (delete_markers != 'only' OR o.is_delete_marker)
                         ORDER BY COALESCE(date_trunc('milliseconds', o.archived_at), 'infinity'::timestamptz) DESC, COALESCE(o.version, '') ASC LIMIT 1)
                        UNION ALL
                        (SELECT o.name FROM storage.objects o
                         WHERE o.bucket_id = _bucket_id AND o.name COLLATE "C" < v_next_seek
                           AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)
                           AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)
                           AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                           AND (delete_markers != 'only' OR o.is_delete_marker)
                         ORDER BY o.name COLLATE "C" DESC LIMIT 1)
                    ) sub ORDER BY sub.name COLLATE "C" DESC LIMIT 1;
                END IF;
            END IF;
        ELSE
            -- Single-row mode is always noncurrent_versions='exclude'. Keep
            -- this predicate literal so generic plans use the current index.
            IF v_is_asc THEN
                IF v_next_seek_strict AND v_upper_bound IS NOT NULL THEN
                    SELECT o.name INTO v_peek_name FROM storage.objects o
                    WHERE o.bucket_id = _bucket_id
                      AND o.name COLLATE "C" > v_next_seek
                      AND o.name COLLATE "C" < v_upper_bound
                      AND o.archived_at IS NULL
                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                      AND (delete_markers != 'only' OR o.is_delete_marker)
                    ORDER BY o.name COLLATE "C" ASC LIMIT 1;
                ELSIF v_next_seek_strict THEN
                    SELECT o.name INTO v_peek_name FROM storage.objects o
                    WHERE o.bucket_id = _bucket_id
                      AND o.name COLLATE "C" > v_next_seek
                      AND o.archived_at IS NULL
                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                      AND (delete_markers != 'only' OR o.is_delete_marker)
                    ORDER BY o.name COLLATE "C" ASC LIMIT 1;
                ELSIF v_upper_bound IS NOT NULL THEN
                    SELECT o.name INTO v_peek_name FROM storage.objects o
                    WHERE o.bucket_id = _bucket_id
                      AND o.name COLLATE "C" >= v_next_seek
                      AND o.name COLLATE "C" < v_upper_bound
                      AND o.archived_at IS NULL
                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                      AND (delete_markers != 'only' OR o.is_delete_marker)
                    ORDER BY o.name COLLATE "C" ASC LIMIT 1;
                ELSE
                    SELECT o.name INTO v_peek_name FROM storage.objects o
                    WHERE o.bucket_id = _bucket_id
                      AND o.name COLLATE "C" >= v_next_seek
                      AND o.archived_at IS NULL
                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                      AND (delete_markers != 'only' OR o.is_delete_marker)
                    ORDER BY o.name COLLATE "C" ASC LIMIT 1;
                END IF;
            ELSE
                IF v_upper_bound IS NOT NULL THEN
                    SELECT o.name INTO v_peek_name FROM storage.objects o
                    WHERE o.bucket_id = _bucket_id
                      AND o.name COLLATE "C" < v_next_seek
                      AND o.name COLLATE "C" >= v_prefix
                      AND o.archived_at IS NULL
                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                      AND (delete_markers != 'only' OR o.is_delete_marker)
                    ORDER BY o.name COLLATE "C" DESC LIMIT 1;
                ELSE
                    SELECT o.name INTO v_peek_name FROM storage.objects o
                    WHERE o.bucket_id = _bucket_id
                      AND o.name COLLATE "C" < v_next_seek
                      AND o.archived_at IS NULL
                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                      AND (delete_markers != 'only' OR o.is_delete_marker)
                    ORDER BY o.name COLLATE "C" DESC LIMIT 1;
                END IF;
            END IF;
        END IF;

        EXIT WHEN v_peek_name IS NULL;

        -- STEP 2: Check if this is a FOLDER or FILE
        v_common_prefix := storage.get_common_prefix(v_peek_name, v_prefix, delimiter_param);

        IF v_common_prefix IS NOT NULL THEN
            -- FOLDER: Emit and skip to next folder (no heap access needed)
            name := v_common_prefix;
            id := NULL;
            updated_at := NULL;
            created_at := NULL;
            last_accessed_at := NULL;
            metadata := NULL;
            version := NULL;
            archived_at := NULL;
            is_delete_marker := NULL;
            is_versioned := NULL;
            RETURN NEXT;
            v_count := v_count + 1;

            -- Advance seek past the folder range
            IF v_is_asc THEN
                v_next_seek := left(v_common_prefix, -1)
                    || chr(ascii(right(v_common_prefix, 1)) + 1);
            ELSE
                v_next_seek := v_common_prefix;
            END IF;
            v_next_seek_at := NULL;
            v_next_seek_version := '';
            v_next_seek_strict := NOT v_is_asc;
        ELSE
            -- FILE: Batch fetch using DYNAMIC SQL (overhead amortized over many rows)
            -- For ASC: upper_bound is the exclusive upper limit (< condition)
            -- For DESC: prefix is the inclusive lower limit (>= condition)
            FOR v_current IN EXECUTE CASE WHEN v_next_seek_strict AND NOT v_multi_row THEN v_batch_query_strict ELSE v_batch_query END
                USING _bucket_id, v_next_seek,
                CASE WHEN v_is_asc THEN COALESCE(v_upper_bound, v_prefix) ELSE v_prefix END, v_file_batch_size, v_next_seek_at, v_next_seek_version,
                v_next_seek_strict
            LOOP
                v_common_prefix := storage.get_common_prefix(v_current.name, v_prefix, delimiter_param);

                IF v_common_prefix IS NOT NULL THEN
                    -- Hit a folder: exit batch, let peek handle it. Reset
                    -- strict mode too it may have been set by an earlier
                    -- row in this same batch (see the single-row ASC advance
                    -- below), and v_next_seek here is the folder-triggering
                    -- row's own name, which the next peek must find inclusively.
                    v_next_seek := CASE
                        WHEN v_is_asc THEN v_current.name
                        ELSE v_current.name || delimiter_param
                    END;
                    v_next_seek_at := NULL;
                    v_next_seek_version := '';
                    v_next_seek_strict := false;
                    EXIT;
                END IF;

                -- Emit file
                name := v_current.name;
                id := v_current.id;
                updated_at := v_current.updated_at;
                created_at := v_current.created_at;
                last_accessed_at := v_current.last_accessed_at;
                metadata := v_current.metadata;
                version := v_current.version;
                archived_at := v_current.archived_at;
                is_delete_marker := v_current.is_delete_marker;
                is_versioned := v_current.is_versioned;
                RETURN NEXT;
                v_count := v_count + 1;

                -- when v_multi_row, stay on this name and record its
                -- archived_at as the new tiebreak so remaining rows for the
                -- same key are picked up before moving to the next name
                IF v_multi_row THEN
                    v_next_seek := v_current.name;
                    v_next_seek_at := COALESCE(date_trunc('milliseconds', v_current.archived_at), 'infinity'::timestamptz);
                    v_next_seek_version := COALESCE(v_current.version, '');
                    v_next_seek_strict := false;
                ELSIF v_is_asc THEN
                    -- Appending the delimiter as a fake lexical successor
                    -- would skip a real key like `name || '!'` (or any
                    -- character sorting below the delimiter), which sorts
                    -- between `name` and `name || delimiter`. Track the real
                    -- name and mark the next comparison strict instead.
                    v_next_seek := v_current.name;
                    v_next_seek_strict := true;
                ELSE
                    v_next_seek := v_current.name;
                END IF;

                EXIT WHEN v_count >= max_keys;
            END LOOP;
        END IF;

        IF v_count = v_previous_count
           AND v_next_seek IS NOT DISTINCT FROM v_previous_seek
           AND v_next_seek_at IS NOT DISTINCT FROM v_previous_seek_at
           AND v_next_seek_version IS NOT DISTINCT FROM v_previous_seek_version THEN
            RAISE EXCEPTION 'storage.list_objects_with_delimiter made no progress at seek (%, %, %)',
                v_next_seek, v_next_seek_at, v_next_seek_version;
        END IF;
    END LOOP;
END;
$_$;


--
-- Name: operation(); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.operation() RETURNS text
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN current_setting('storage.operation', true);
END;
$$;


--
-- Name: protect_active_lifecycle_states(); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.protect_active_lifecycle_states() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM storage.bucket_lifecycle_states
        WHERE bucket_id = OLD.id
          AND NOT (
              continuation IS NULL
              OR (continuation @> '{"continuationVersion": 1}' AND continuation #> '{batch,inFlight}' IS NULL)
          )
    ) THEN
        RAISE EXCEPTION 'update or delete on table "buckets" violates foreign key constraint "bucket_lifecycle_states_bucket_id_fkey" on table "bucket_lifecycle_states"'
            USING ERRCODE = 'foreign_key_violation',
                  DETAIL = format('Key (id)=(%s) is still referenced from table "bucket_lifecycle_states".', OLD.id),
                  SCHEMA = 'storage',
                  TABLE = 'bucket_lifecycle_states',
                  CONSTRAINT = 'bucket_lifecycle_states_bucket_id_fkey';
    END IF;
    RETURN OLD;
END;
$$;


--
-- Name: protect_bucket_control_columns(); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.protect_bucket_control_columns() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  configuration_changed boolean;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.lifecycle_configuration IS NOT NULL
       OR NEW.lifecycle_configuration_generation IS NOT NULL THEN
      IF NOT pg_has_role(current_user, TG_ARGV[0], 'MEMBER') THEN
        RAISE EXCEPTION 'only members of the configured storage service role may insert lifecycle policy state'
          USING ERRCODE = '42501',
                HINT = format(
                  'Insert with both lifecycle columns NULL and configure lifecycle through the Storage API afterward, or insert as a member of %I.',
                  TG_ARGV[0]
                );
      END IF;
    END IF;

    RETURN NEW;
  END IF;

  configuration_changed =
    OLD.lifecycle_configuration IS DISTINCT FROM NEW.lifecycle_configuration
    OR OLD.lifecycle_configuration_generation IS DISTINCT FROM NEW.lifecycle_configuration_generation;

  IF NOT configuration_changed THEN
    RETURN NEW;
  END IF;

  IF NEW.type IS DISTINCT FROM 'STANDARD' THEN
    RAISE EXCEPTION 'bucket versioning and lifecycle controls require a Standard bucket'
      USING ERRCODE = '0A000';
  END IF;

  IF NEW.lifecycle_configuration IS NULL
     AND NEW.lifecycle_configuration_generation IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.lifecycle_configuration IS NULL
     OR NEW.lifecycle_configuration_generation IS NULL
     OR OLD.lifecycle_configuration IS NOT DISTINCT FROM NEW.lifecycle_configuration
     OR OLD.lifecycle_configuration_generation IS NOT DISTINCT FROM NEW.lifecycle_configuration_generation THEN
    RAISE EXCEPTION 'a changed lifecycle policy requires a new non-null generation'
      USING ERRCODE = '22023';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: protect_delete(); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.protect_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Check if storage.allow_delete_query is set to 'true'
    IF COALESCE(current_setting('storage.allow_delete_query', true), 'false') != 'true' THEN
        RAISE EXCEPTION 'Direct deletion from storage tables is not allowed. Use the Storage API instead.'
            USING HINT = 'This prevents accidental data loss from orphaned objects.',
                  ERRCODE = '42501';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: reconcile_lifecycle_state(text, boolean); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.reconcile_lifecycle_state(target_bucket_id text, policy_changed boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    bucket storage.buckets%ROWTYPE;
    active boolean;
    idle boolean;
    state_generation uuid;
BEGIN
    SELECT * INTO bucket FROM storage.buckets WHERE id = target_bucket_id FOR NO KEY UPDATE;
    IF NOT FOUND THEN
        RETURN;
    END IF;

    SELECT continuation IS NULL OR (
               continuation @> '{"continuationVersion": 1}'
               AND continuation #> '{batch,inFlight}' IS NULL
           ), generation
    INTO idle, state_generation
    FROM storage.bucket_lifecycle_states
    WHERE bucket_id = target_bucket_id
    FOR UPDATE;

    IF bucket.lifecycle_configuration IS NULL THEN
        DELETE FROM storage.bucket_lifecycle_states
        WHERE bucket_id = target_bucket_id
          AND idle IS TRUE;

        UPDATE storage.bucket_lifecycle_states
        SET next_run_at = clock_timestamp(), updated_at = clock_timestamp()
        WHERE bucket_id = target_bucket_id
          AND idle IS NOT TRUE;
        RETURN;
    END IF;

    active := bucket.versioning_status <> 'DISABLED'
        AND bucket.lifecycle_configuration @> '{"rules":[{"status":"Enabled"}]}'::jsonb;

    -- The state row records the generation it was reconciled with so callers need not detect
    -- policy changes. Rows without a recorded generation keep their work.
    policy_changed := policy_changed OR (
        state_generation IS NOT NULL AND state_generation <> bucket.lifecycle_configuration_generation
    );

    INSERT INTO storage.bucket_lifecycle_states AS state (bucket_id, generation, next_run_at)
    VALUES (bucket.id, bucket.lifecycle_configuration_generation, CASE WHEN active THEN clock_timestamp() END)
    ON CONFLICT (bucket_id) DO UPDATE
    SET next_run_at = CASE
            WHEN policy_changed THEN
                CASE WHEN active OR idle IS NOT TRUE THEN clock_timestamp() END
            ELSE EXCLUDED.next_run_at
        END,
        generation = EXCLUDED.generation,
        claim_id = CASE WHEN policy_changed AND idle IS TRUE
                        THEN NULL ELSE state.claim_id END,
        claim_until = CASE WHEN policy_changed AND idle IS TRUE
                           THEN NULL ELSE state.claim_until END,
        continuation = CASE WHEN policy_changed AND idle IS TRUE
                            THEN NULL ELSE state.continuation END,
        failure_count = CASE WHEN policy_changed AND idle IS TRUE
                             THEN 0 ELSE state.failure_count END,
        last_error = CASE WHEN policy_changed AND idle IS TRUE
                          THEN NULL ELSE state.last_error END,
        updated_at = clock_timestamp()
    WHERE policy_changed OR (state.next_run_at IS NULL AND EXCLUDED.next_run_at IS NOT NULL);
END;
$$;


--
-- Name: search(text, text, integer, integer, integer, text, text, text, text, text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.search(prefix text, bucketname text, limits integer DEFAULT 100, levels integer DEFAULT 1, offsets integer DEFAULT 0, search text DEFAULT ''::text, sortcolumn text DEFAULT 'name'::text, sortorder text DEFAULT 'asc'::text, noncurrent_versions text DEFAULT 'exclude'::text, delete_markers text DEFAULT 'exclude'::text) RETURNS TABLE(name text, id uuid, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone, metadata jsonb, version text, archived_at timestamp with time zone, is_delete_marker boolean, is_versioned boolean)
    LANGUAGE plpgsql STABLE
    AS $_$
DECLARE
    v_peek_name TEXT;
    v_current RECORD;
    v_common_prefix TEXT;
    v_delimiter CONSTANT TEXT := '/';

    -- Configuration
    v_limit INT;
    v_prefix TEXT;
    v_prefix_lower TEXT;
    v_prefix_len INT;
    v_prefix_start INT;
    v_combined_levels INT;
    v_is_asc BOOLEAN;
    v_order_by TEXT;
    v_sort_order TEXT;
    v_upper_bound TEXT;
    v_file_batch_size INT;
    v_version_filter TEXT;
    v_multi_row BOOLEAN;

    -- Dynamic SQL for batch query only
    v_batch_query TEXT;
    v_delete_marker_peek_query TEXT;
    v_delete_marker_peek_query_strict TEXT;

    -- Seek state
    v_next_seek TEXT;
    v_next_seek_at TIMESTAMPTZ;
    v_next_seek_version TEXT;
    v_next_seek_strict BOOLEAN := false;
    v_count INT := 0;
    v_skipped INT := 0;
    v_previous_seek TEXT;
    v_previous_seek_at TIMESTAMPTZ;
    v_previous_seek_version TEXT;
    v_previous_count INT;
    v_previous_skipped INT;
BEGIN
    -- ========================================================================
    -- INITIALIZATION
    -- ========================================================================
    v_limit := LEAST(coalesce(limits, 100), 1500);
    v_prefix := coalesce(prefix, '') || coalesce(search, '');
    v_prefix_lower := lower(v_prefix);
    v_prefix_len := length(coalesce(prefix, ''));
    v_prefix_start := coalesce(array_length(string_to_array(coalesce(prefix, ''), v_delimiter), 1), 1);
    v_combined_levels := coalesce(array_length(string_to_array(v_prefix, v_delimiter), 1), 1);
    v_is_asc := lower(coalesce(sortorder, 'asc')) = 'asc';
    v_file_batch_size := LEAST(GREATEST(v_limit * 2, 100), 1000);
    v_next_seek_at := NULL;
    v_next_seek_version := '';

    -- COALESCE first: NULL NOT IN (...) evaluates to NULL (not TRUE), so a
    -- bare NOT IN check silently leaves an explicit NULL argument unreset.
    noncurrent_versions := COALESCE(noncurrent_versions, 'exclude');
    delete_markers := COALESCE(delete_markers, 'exclude');
    IF noncurrent_versions NOT IN ('exclude', 'only', 'include') THEN
        noncurrent_versions := 'exclude';
    END IF;
    IF delete_markers NOT IN ('exclude', 'only', 'include') THEN
        delete_markers := 'exclude';
    END IF;

    v_multi_row := noncurrent_versions IN ('only', 'include');

    v_version_filter := '';
    IF noncurrent_versions = 'exclude' THEN
        v_version_filter := v_version_filter || ' AND o.archived_at IS NULL';
    ELSIF noncurrent_versions = 'only' THEN
        v_version_filter := v_version_filter || ' AND o.archived_at IS NOT NULL';
    END IF;
    IF delete_markers = 'exclude' THEN
        v_version_filter := v_version_filter || ' AND NOT o.is_delete_marker';
    ELSIF delete_markers = 'only' THEN
        v_version_filter := v_version_filter || ' AND o.is_delete_marker';
    END IF;

    -- Validate sort column
    CASE lower(coalesce(sortcolumn, 'name'))
        WHEN 'name' THEN v_order_by := 'name';
        WHEN 'updated_at' THEN v_order_by := 'updated_at';
        WHEN 'created_at' THEN v_order_by := 'created_at';
        WHEN 'last_accessed_at' THEN v_order_by := 'last_accessed_at';
        ELSE v_order_by := 'name';
    END CASE;

    v_sort_order := CASE WHEN v_is_asc THEN 'asc' ELSE 'desc' END;

    -- ========================================================================
    -- NON-NAME SORTING: Use path_tokens approach
    -- ========================================================================
    IF v_order_by != 'name' THEN
        RETURN QUERY EXECUTE format(
            $sql$
            WITH folders AS (
                SELECT array_to_string(path_tokens[$1:$2], '/') AS folder
                FROM storage.objects
                WHERE objects.name ILIKE $3 || '%%'
                  AND bucket_id = $4
                  AND array_length(objects.path_tokens, 1) <> $2
                  AND ($7 != 'exclude' OR objects.archived_at IS NULL)
                  AND ($7 != 'only' OR objects.archived_at IS NOT NULL)
                  AND ($8 != 'exclude' OR NOT objects.is_delete_marker)
                  AND ($8 != 'only' OR objects.is_delete_marker)
                GROUP BY folder
                ORDER BY folder %s
            )
            (SELECT folder AS "name",
                   NULL::uuid AS id,
                   NULL::timestamptz AS updated_at,
                   NULL::timestamptz AS created_at,
                   NULL::timestamptz AS last_accessed_at,
                   NULL::jsonb AS metadata,
                   NULL::text AS version,
                   NULL::timestamptz AS archived_at,
                   NULL::boolean AS is_delete_marker,
                   NULL::boolean AS is_versioned FROM folders)
            UNION ALL
            (SELECT array_to_string(path_tokens[$1:$2], '/') AS "name",
                   id, updated_at, created_at, last_accessed_at, metadata,
                   version, archived_at, is_delete_marker, is_versioned
             FROM storage.objects
             WHERE objects.name ILIKE $3 || '%%'
               AND bucket_id = $4
               AND array_length(objects.path_tokens, 1) = $2
               AND ($7 != 'exclude' OR objects.archived_at IS NULL)
               AND ($7 != 'only' OR objects.archived_at IS NOT NULL)
               AND ($8 != 'exclude' OR NOT objects.is_delete_marker)
               AND ($8 != 'only' OR objects.is_delete_marker)
             -- name, then version, as tiebreaks so two versions of the same
             -- key tying on the sort column still sort deterministically
             ORDER BY %I %s, name COLLATE "C" %s, COALESCE(version, '') %s)
            LIMIT $5 OFFSET $6
            $sql$, v_sort_order, v_order_by, v_sort_order, v_sort_order, v_sort_order
        ) USING v_prefix_start, v_combined_levels, v_prefix, bucketname, v_limit, offsets, noncurrent_versions, delete_markers;
        RETURN;
    END IF;

    -- ========================================================================
    -- NAME SORTING: Hybrid skip-scan with batch optimization
    -- ========================================================================

    -- Calculate upper bound for prefix filtering
    IF v_prefix_lower = '' THEN
        v_upper_bound := NULL;
    ELSIF right(v_prefix_lower, 1) = v_delimiter THEN
        v_upper_bound := left(v_prefix_lower, -1) || chr(ascii(v_delimiter) + 1);
    ELSE
        v_upper_bound := left(v_prefix_lower, -1) || chr(ascii(right(v_prefix_lower, 1)) + 1);
    END IF;

    -- Build a resume-safe batch query. The exact-name branch returns remaining
    -- versions after the current (archived_at, version) boundary; the strict
    -- name branch returns subsequent keys. UNION ALL keeps both predicates
    -- independently indexable.
    IF v_is_asc THEN
        IF v_upper_bound IS NOT NULL THEN
            v_batch_query := 'SELECT * FROM (' ||
                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||
                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" = $2 AND ($5::timestamptz IS NULL OR COALESCE(o.archived_at, ''infinity''::timestamptz) < $5 OR (COALESCE(o.archived_at, ''infinity''::timestamptz) = $5 AND COALESCE(o.version, '''') > $6))' ||
                v_version_filter || ' ORDER BY COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4) UNION ALL ' ||
                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||
                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" > $2 AND lower(o.name) COLLATE "C" < $3' || v_version_filter ||
                ' ORDER BY lower(o.name) COLLATE "C" ASC, COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4)' ||
                ') sub ORDER BY lower(sub.name) COLLATE "C" ASC, COALESCE(sub.archived_at, ''infinity''::timestamptz) DESC, COALESCE(sub.version, '''') ASC LIMIT $4';
        ELSE
            v_batch_query := 'SELECT * FROM (' ||
                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||
                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" = $2 AND ($5::timestamptz IS NULL OR COALESCE(o.archived_at, ''infinity''::timestamptz) < $5 OR (COALESCE(o.archived_at, ''infinity''::timestamptz) = $5 AND COALESCE(o.version, '''') > $6))' ||
                v_version_filter || ' ORDER BY COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4) UNION ALL ' ||
                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||
                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" > $2' || v_version_filter ||
                ' ORDER BY lower(o.name) COLLATE "C" ASC, COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4)' ||
                ') sub ORDER BY lower(sub.name) COLLATE "C" ASC, COALESCE(sub.archived_at, ''infinity''::timestamptz) DESC, COALESCE(sub.version, '''') ASC LIMIT $4';
        END IF;
    ELSE
        IF v_upper_bound IS NOT NULL THEN
            v_batch_query := 'SELECT * FROM (' ||
                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||
                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" = $2 AND ($5::timestamptz IS NULL OR COALESCE(o.archived_at, ''infinity''::timestamptz) < $5 OR (COALESCE(o.archived_at, ''infinity''::timestamptz) = $5 AND COALESCE(o.version, '''') > $6))' ||
                v_version_filter || ' ORDER BY COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4) UNION ALL ' ||
                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||
                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" < $2 AND lower(o.name) COLLATE "C" >= $3' || v_version_filter ||
                ' ORDER BY lower(o.name) COLLATE "C" DESC, COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4)' ||
                ') sub ORDER BY lower(sub.name) COLLATE "C" DESC, COALESCE(sub.archived_at, ''infinity''::timestamptz) DESC, COALESCE(sub.version, '''') ASC LIMIT $4';
        ELSE
            v_batch_query := 'SELECT * FROM (' ||
                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||
                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" = $2 AND ($5::timestamptz IS NULL OR COALESCE(o.archived_at, ''infinity''::timestamptz) < $5 OR (COALESCE(o.archived_at, ''infinity''::timestamptz) = $5 AND COALESCE(o.version, '''') > $6))' ||
                v_version_filter || ' ORDER BY COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4) UNION ALL ' ||
                '(SELECT o.name, o.id, o.updated_at, o.created_at, o.last_accessed_at, o.metadata, o.version, o.archived_at, o.is_delete_marker, o.is_versioned FROM storage.objects o ' ||
                'WHERE o.bucket_id = $1 AND lower(o.name) COLLATE "C" < $2' || v_version_filter ||
                ' ORDER BY lower(o.name) COLLATE "C" DESC, COALESCE(o.archived_at, ''infinity''::timestamptz) DESC, COALESCE(o.version, '''') ASC LIMIT $4)' ||
                ') sub ORDER BY lower(sub.name) COLLATE "C" DESC, COALESCE(sub.archived_at, ''infinity''::timestamptz) DESC, COALESCE(sub.version, '''') ASC LIMIT $4';
        END IF;
    END IF;

    -- Keep the delete-marker predicate literal so the cached generic
    -- plan can use idx_objects_delete_markers during the main-loop peek.
    IF delete_markers = 'only' THEN
        IF v_multi_row THEN
            v_delete_marker_peek_query :=
                'SELECT marker_page.name FROM (' || v_batch_query || ') marker_page LIMIT 1';
        ELSIF v_is_asc THEN
            -- Two separate literal query strings, not one gated by a bound
            -- boolean: folding "$n AND op1 OR NOT $n AND op2" into a single
            -- query defeats the generic plan's ability to push either
            -- comparison into the index. Branching in PL/pgSQL control flow
            -- instead keeps each query's index condition intact.
            v_delete_marker_peek_query :=
                'SELECT o.name FROM storage.objects o WHERE o.bucket_id = $1 ' ||
                'AND lower(o.name) COLLATE "C" >= $2' ||
                CASE WHEN v_upper_bound IS NOT NULL
                    THEN ' AND lower(o.name) COLLATE "C" < $3'
                    ELSE ''
                END ||
                v_version_filter ||
                ' ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1';
            -- Strict variant: used once the single-row ASC batch advance
            -- (below) has left v_next_seek pointing at the last row already
            -- emitted, so a plain >= would re-match it forever.
            v_delete_marker_peek_query_strict :=
                'SELECT o.name FROM storage.objects o WHERE o.bucket_id = $1 ' ||
                'AND lower(o.name) COLLATE "C" > $2' ||
                CASE WHEN v_upper_bound IS NOT NULL
                    THEN ' AND lower(o.name) COLLATE "C" < $3'
                    ELSE ''
                END ||
                v_version_filter ||
                ' ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1';
        ELSE
            v_delete_marker_peek_query :=
                'SELECT o.name FROM storage.objects o WHERE o.bucket_id = $1 ' ||
                'AND lower(o.name) COLLATE "C" < $2' ||
                CASE WHEN v_upper_bound IS NOT NULL
                    THEN ' AND lower(o.name) COLLATE "C" >= $3'
                    ELSE ''
                END ||
                v_version_filter ||
                ' ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1';
        END IF;
    END IF;

    -- Initialize seek position
    IF v_is_asc THEN
        v_next_seek := v_prefix_lower;
    ELSE
        -- DESC performs one specialized initial seek so partial current-version
        -- and delete-marker indexes remain available.
        EXECUTE format(
            'SELECT o.name FROM storage.objects o WHERE o.bucket_id = $1%s%s ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1',
            CASE WHEN v_upper_bound IS NOT NULL
                THEN ' AND lower(o.name) COLLATE "C" >= $2 AND lower(o.name) COLLATE "C" < $3'
                ELSE ''
            END,
            v_version_filter
        )
        INTO v_peek_name
        USING bucketname, v_prefix_lower, v_upper_bound;

        IF v_peek_name IS NOT NULL THEN
            v_next_seek := lower(v_peek_name) || v_delimiter;
        ELSE
            RETURN;
        END IF;
    END IF;

    -- ========================================================================
    -- MAIN LOOP: Hybrid peek-then-batch algorithm
    -- Uses STATIC SQL for peek (hot path) and DYNAMIC SQL for batch and
    -- the delete-marker-only path
    -- ========================================================================
    LOOP
        EXIT WHEN v_count >= v_limit;

        v_previous_seek := v_next_seek;
        v_previous_seek_at := v_next_seek_at;
        v_previous_seek_version := v_next_seek_version;
        v_previous_count := v_count;
        v_previous_skipped := v_skipped;

        -- STEP 1: PEEK
        v_peek_name := NULL;
        IF delete_markers = 'only' THEN
            EXECUTE CASE WHEN v_next_seek_strict
                THEN v_delete_marker_peek_query_strict
                ELSE v_delete_marker_peek_query
            END
                INTO v_peek_name
                USING bucketname, v_next_seek,
                    CASE WHEN v_is_asc THEN COALESCE(v_upper_bound, v_prefix_lower) ELSE v_prefix_lower END,
                    1, v_next_seek_at, v_next_seek_version;
        ELSIF v_multi_row AND v_next_seek_at IS NOT NULL THEN
            SELECT o.name INTO v_peek_name
            FROM storage.objects o
            WHERE o.bucket_id = bucketname
              AND lower(o.name) COLLATE "C" = v_next_seek
              AND (COALESCE(o.archived_at, 'infinity'::timestamptz) < v_next_seek_at
                   OR (COALESCE(o.archived_at, 'infinity'::timestamptz) = v_next_seek_at
                       AND COALESCE(o.version, '') > v_next_seek_version))
              AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)
              AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)
              AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
              AND (delete_markers != 'only' OR o.is_delete_marker)
            ORDER BY COALESCE(o.archived_at, 'infinity'::timestamptz) DESC,
                     COALESCE(o.version, '') ASC
            LIMIT 1;

            -- The current key is exhausted. Clear its version boundary and
            -- make the following ASC name peek strict. Appending '/' is not a
            -- valid lexical successor because keys ending in characters such
            -- as '!' sort between the exhausted name and name || '/'.
            IF v_peek_name IS NULL THEN
                IF v_is_asc THEN
                    v_next_seek_strict := true;
                END IF;
                v_next_seek_at := NULL;
                v_next_seek_version := '';
            END IF;
        END IF;

        -- Single-row mode is always noncurrent_versions='exclude'. Keep the
        -- current-row predicate literal so generic plans use the current index.
        IF delete_markers != 'only' AND v_peek_name IS NULL AND NOT v_multi_row THEN
            IF v_is_asc THEN
                IF v_next_seek_strict AND v_upper_bound IS NOT NULL THEN
                    SELECT o.name INTO v_peek_name FROM storage.objects o
                    WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" > v_next_seek AND lower(o.name) COLLATE "C" < v_upper_bound
                      AND o.archived_at IS NULL
                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                    ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1;
                ELSIF v_next_seek_strict THEN
                    SELECT o.name INTO v_peek_name FROM storage.objects o
                    WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" > v_next_seek
                      AND o.archived_at IS NULL
                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                    ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1;
                ELSIF v_upper_bound IS NOT NULL THEN
                    SELECT o.name INTO v_peek_name FROM storage.objects o
                    WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" >= v_next_seek AND lower(o.name) COLLATE "C" < v_upper_bound
                      AND o.archived_at IS NULL
                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                    ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1;
                ELSE
                    SELECT o.name INTO v_peek_name FROM storage.objects o
                    WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" >= v_next_seek
                      AND o.archived_at IS NULL
                      AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                    ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1;
                END IF;
            ELSIF v_upper_bound IS NOT NULL THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" < v_next_seek AND lower(o.name) COLLATE "C" >= v_prefix_lower
                  AND o.archived_at IS NULL
                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
            ELSE
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" < v_next_seek
                  AND o.archived_at IS NULL
                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
            END IF;
        ELSIF delete_markers != 'only' AND v_peek_name IS NULL AND v_is_asc THEN
            IF v_next_seek_strict AND v_upper_bound IS NOT NULL THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" > v_next_seek AND lower(o.name) COLLATE "C" < v_upper_bound
                  AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)
                  AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)
                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                  AND (delete_markers != 'only' OR o.is_delete_marker)
                ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1;
            ELSIF v_next_seek_strict THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" > v_next_seek
                  AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)
                  AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)
                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                  AND (delete_markers != 'only' OR o.is_delete_marker)
                ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1;
            ELSIF v_upper_bound IS NOT NULL THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" >= v_next_seek AND lower(o.name) COLLATE "C" < v_upper_bound
                  AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)
                  AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)
                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                  AND (delete_markers != 'only' OR o.is_delete_marker)
                ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1;
            ELSE
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" >= v_next_seek
                  AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)
                  AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)
                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                  AND (delete_markers != 'only' OR o.is_delete_marker)
                ORDER BY lower(o.name) COLLATE "C" ASC LIMIT 1;
            END IF;
        ELSIF delete_markers != 'only' AND v_peek_name IS NULL THEN
            IF v_upper_bound IS NOT NULL THEN
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" < v_next_seek AND lower(o.name) COLLATE "C" >= v_prefix_lower
                  AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)
                  AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)
                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                  AND (delete_markers != 'only' OR o.is_delete_marker)
                ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
            ELSE
                SELECT o.name INTO v_peek_name FROM storage.objects o
                WHERE o.bucket_id = bucketname AND lower(o.name) COLLATE "C" < v_next_seek
                  AND (noncurrent_versions != 'exclude' OR o.archived_at IS NULL)
                  AND (noncurrent_versions != 'only' OR o.archived_at IS NOT NULL)
                  AND (delete_markers != 'exclude' OR NOT o.is_delete_marker)
                  AND (delete_markers != 'only' OR o.is_delete_marker)
                ORDER BY lower(o.name) COLLATE "C" DESC LIMIT 1;
            END IF;
        END IF;

        EXIT WHEN v_peek_name IS NULL;

        -- If the peek landed on a different key than we were tracking, any
        -- version boundary belongs to the OLD key and must not leak into the
        -- new one - e.g. the deleteMarkers='only' peek doesn't know or care
        -- whether it's continuing the same key or jumping to a new one, so
        -- it never clears these itself.
        IF lower(v_peek_name) IS DISTINCT FROM v_next_seek THEN
            v_next_seek_at := NULL;
            v_next_seek_version := '';
        END IF;

        -- The peek is authoritative for the next key to process. This is
        -- especially important after exhausting a multi-version key: the
        -- version boundary has been cleared, so executing the batch against
        -- a stale v_next_seek would replay every version of that old key.
        v_next_seek := lower(v_peek_name);
        v_next_seek_strict := false;

        -- STEP 2: Check if this is a FOLDER or FILE
        v_common_prefix := storage.get_common_prefix(lower(v_peek_name), v_prefix_lower, v_delimiter);

        IF v_common_prefix IS NOT NULL THEN
            -- FOLDER: Handle offset, emit if needed, skip to next folder
            IF v_skipped < offsets THEN
                v_skipped := v_skipped + 1;
            ELSE
                name := substring(rtrim(storage.get_common_prefix(v_peek_name, v_prefix, v_delimiter), v_delimiter) from v_prefix_len + 1);
                id := NULL;
                updated_at := NULL;
                created_at := NULL;
                last_accessed_at := NULL;
                metadata := NULL;
                version := NULL;
                archived_at := NULL;
                is_delete_marker := NULL;
                is_versioned := NULL;
                RETURN NEXT;
                v_count := v_count + 1;
            END IF;

            -- Advance seek past the folder range
            IF v_is_asc THEN
                v_next_seek := lower(left(v_common_prefix, -1)) || chr(ascii(v_delimiter) + 1);
            ELSE
                v_next_seek := lower(v_common_prefix);
            END IF;
            v_next_seek_at := NULL;
            v_next_seek_version := '';
        ELSE
            -- FILE: Batch fetch using DYNAMIC SQL (overhead amortized over many rows)
            -- For ASC: upper_bound is the exclusive upper limit (< condition)
            -- For DESC: prefix_lower is the inclusive lower limit (>= condition)
            FOR v_current IN EXECUTE v_batch_query
                USING bucketname, v_next_seek,
                    CASE WHEN v_is_asc THEN COALESCE(v_upper_bound, v_prefix_lower) ELSE v_prefix_lower END, v_file_batch_size,
                    v_next_seek_at, v_next_seek_version
            LOOP
                v_common_prefix := storage.get_common_prefix(lower(v_current.name), v_prefix_lower, v_delimiter);

                IF v_common_prefix IS NOT NULL THEN
                    -- Hit a folder: exit batch, let peek handle it. Reset
                    -- strict mode too - it may have been set by an earlier
                    -- row in this same batch (see the single-row ASC advance
                    -- below), and v_next_seek here is the folder-triggering
                    -- row's own name, which the next peek must find inclusively.
                    v_next_seek := CASE
                        WHEN v_is_asc THEN lower(v_current.name)
                        ELSE lower(v_current.name) || v_delimiter
                    END;
                    v_next_seek_at := NULL;
                    v_next_seek_version := '';
                    v_next_seek_strict := false;
                    EXIT;
                END IF;

                -- Handle offset skipping
                IF v_skipped < offsets THEN
                    v_skipped := v_skipped + 1;
                ELSE
                    -- Emit file
                    name := substring(v_current.name from v_prefix_len + 1);
                    id := v_current.id;
                    updated_at := v_current.updated_at;
                    created_at := v_current.created_at;
                    last_accessed_at := v_current.last_accessed_at;
                    metadata := v_current.metadata;
                    version := v_current.version;
                    archived_at := v_current.archived_at;
                    is_delete_marker := v_current.is_delete_marker;
                    is_versioned := v_current.is_versioned;
                    RETURN NEXT;
                    v_count := v_count + 1;
                END IF;

                -- Multi-row mode must remain on this key until all of its
                -- versions have crossed the internal batch boundary.
                IF v_multi_row THEN
                    v_next_seek := lower(v_current.name);
                    v_next_seek_at := COALESCE(v_current.archived_at, 'infinity'::timestamptz);
                    v_next_seek_version := COALESCE(v_current.version, '');
                ELSIF v_is_asc THEN
                    -- Appending the delimiter as a fake lexical successor would
                    -- skip a real key like `name || '!'` (or any character
                    -- sorting below the delimiter), which sorts between `name`
                    -- and `name || delimiter`. Track the real name and mark the
                    -- next comparison strict instead - same fix as the
                    -- exhausted-key case above.
                    v_next_seek := lower(v_current.name);
                    v_next_seek_strict := true;
                ELSE
                    v_next_seek := lower(v_current.name);
                END IF;

                EXIT WHEN v_count >= v_limit;
            END LOOP;
        END IF;

        IF v_count = v_previous_count
           AND v_skipped = v_previous_skipped
           AND v_next_seek IS NOT DISTINCT FROM v_previous_seek
           AND v_next_seek_at IS NOT DISTINCT FROM v_previous_seek_at
           AND v_next_seek_version IS NOT DISTINCT FROM v_previous_seek_version THEN
            RAISE EXCEPTION 'storage.search made no progress at seek (%, %, %)',
                v_next_seek, v_next_seek_at, v_next_seek_version;
        END IF;
    END LOOP;
END;
$_$;


--
-- Name: search_by_timestamp(text, text, integer, integer, text, text, text, text, text, text, text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.search_by_timestamp(p_prefix text, p_bucket_id text, p_limit integer, p_level integer, p_start_after text, p_sort_order text, p_sort_column text, p_sort_column_after text, noncurrent_versions text DEFAULT 'exclude'::text, delete_markers text DEFAULT 'exclude'::text, p_start_after_version text DEFAULT ''::text) RETURNS TABLE(key text, name text, id uuid, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone, metadata jsonb, version text, archived_at timestamp with time zone, is_delete_marker boolean, is_versioned boolean)
    LANGUAGE plpgsql STABLE
    AS $_$
DECLARE
    v_cursor_op text;
    v_query text;
    v_prefix text;
    v_prefix_pattern text;
    v_sort_order text;
    v_sort_column text;
    v_version_tiebreak text;
BEGIN
    v_prefix := coalesce(p_prefix, '');
    -- Keep the raw prefix for common-prefix calculations and escape only LIKE metacharacters.
    v_prefix_pattern := replace(v_prefix, chr(92), chr(92) || chr(92));
    v_prefix_pattern := replace(v_prefix_pattern, '%', chr(92) || '%');
    v_prefix_pattern := replace(v_prefix_pattern, '_', chr(92) || '_');

    -- COALESCE first: NULL NOT IN (...) evaluates to NULL (not TRUE), so a
    -- bare NOT IN check silently leaves an explicit NULL argument unreset.
    noncurrent_versions := COALESCE(noncurrent_versions, 'exclude');
    delete_markers := COALESCE(delete_markers, 'exclude');
    IF noncurrent_versions NOT IN ('exclude', 'only', 'include') THEN
        noncurrent_versions := 'exclude';
    END IF;
    IF delete_markers NOT IN ('exclude', 'only', 'include') THEN
        delete_markers := 'exclude';
    END IF;

    -- $9 is only populated in multi-row mode; it's always '' otherwise, so
    -- only use each row's real version as a tiebreak in multi-row mode.
    v_version_tiebreak := CASE WHEN noncurrent_versions IN ('only', 'include') THEN 'COALESCE(version, '''')' ELSE '''''' END;

    -- Defense-in-depth: this function is independently reachable and must
    -- not trust p_sort_order/p_sort_column to already be validated by a
    -- caller. Normalize to the same strict allow-list storage.search_v2
    -- uses before interpolating anything into dynamic SQL below.
    v_sort_order := lower(coalesce(p_sort_order, 'asc'));
    IF v_sort_order NOT IN ('asc', 'desc') THEN
        v_sort_order := 'asc';
    END IF;

    v_sort_column := lower(coalesce(p_sort_column, 'updated_at'));
    IF v_sort_column NOT IN ('updated_at', 'created_at') THEN
        v_sort_column := 'updated_at';
    END IF;

    IF v_sort_order = 'asc' THEN
        v_cursor_op := '>';
    ELSE
        v_cursor_op := '<';
    END IF;

    v_query := format($sql$
        WITH raw_objects AS (
            SELECT
                o.name AS obj_name,
                o.id AS obj_id,
                o.updated_at AS obj_updated_at,
                o.created_at AS obj_created_at,
                o.last_accessed_at AS obj_last_accessed_at,
                o.metadata AS obj_metadata,
                o.version AS obj_version,
                o.archived_at AS obj_archived_at,
                o.is_delete_marker AS obj_is_delete_marker,
                o.is_versioned AS obj_is_versioned,
                storage.get_common_prefix(o.name, $1, '/') AS common_prefix
            FROM storage.objects o
            WHERE o.bucket_id = $2
              AND o.name COLLATE "C" LIKE $10 || '%%'
              AND ($7 != 'exclude' OR o.archived_at IS NULL)
              AND ($7 != 'only' OR o.archived_at IS NOT NULL)
              AND ($8 != 'exclude' OR NOT o.is_delete_marker)
              AND ($8 != 'only' OR o.is_delete_marker)
        ),
        -- Aggregate common prefixes (folders)
        -- Both created_at and updated_at use MIN(obj_created_at) to match the old prefixes table behavior
        aggregated_prefixes AS (
            SELECT
                common_prefix AS name,
                NULL::uuid AS id,
                MIN(obj_created_at) AS updated_at,
                MIN(obj_created_at) AS created_at,
                NULL::timestamptz AS last_accessed_at,
                NULL::jsonb AS metadata,
                NULL::text AS version,
                NULL::timestamptz AS archived_at,
                NULL::boolean AS is_delete_marker,
                NULL::boolean AS is_versioned,
                TRUE AS is_prefix
            FROM raw_objects
            WHERE common_prefix IS NOT NULL
            GROUP BY common_prefix
        ),
        leaf_objects AS (
            SELECT
                obj_name AS name,
                obj_id AS id,
                obj_updated_at AS updated_at,
                obj_created_at AS created_at,
                obj_last_accessed_at AS last_accessed_at,
                obj_metadata AS metadata,
                obj_version AS version,
                obj_archived_at AS archived_at,
                obj_is_delete_marker AS is_delete_marker,
                obj_is_versioned AS is_versioned,
                FALSE AS is_prefix
            FROM raw_objects
            WHERE common_prefix IS NULL
        ),
        combined AS (
            SELECT * FROM aggregated_prefixes
            UNION ALL
            SELECT * FROM leaf_objects
        ),
        filtered AS (
            SELECT *
            FROM combined
            WHERE (
                $5 = ''
                OR ROW(
                    COALESCE(date_trunc('milliseconds', %I), 'epoch'::timestamptz),
                    name COLLATE "C",
                    %s
                ) %s ROW(
                    -- truncated the same way as the stored value above
                    date_trunc('milliseconds', COALESCE(NULLIF($6, '')::timestamptz, 'epoch'::timestamptz)),
                    $5,
                    $9
                )
            )
        )
        SELECT
            split_part(name, '/', $3) AS key,
            name,
            id,
            updated_at,
            created_at,
            last_accessed_at,
            metadata,
            version,
            archived_at,
            is_delete_marker,
            is_versioned
        FROM filtered
        ORDER BY
            COALESCE(date_trunc('milliseconds', %I), 'epoch'::timestamptz) %s,
            name COLLATE "C" %s,
            COALESCE(version, '') %s
        LIMIT $4
    $sql$,
        v_sort_column,
        v_version_tiebreak,
        v_cursor_op,
        v_sort_column,
        v_sort_order,
        v_sort_order,
        v_sort_order
    );

    -- version is the third tiebreak component for two versions of the same
    -- key tying on both timestamp and name (see filtered CTE / ORDER BY above)
    RETURN QUERY EXECUTE v_query
    USING v_prefix, p_bucket_id, p_level, p_limit, p_start_after, p_sort_column_after, noncurrent_versions, delete_markers, coalesce(p_start_after_version, ''), v_prefix_pattern;
END;
$_$;


--
-- Name: search_v2(text, text, integer, integer, text, text, text, text, text, text, timestamp with time zone, text, boolean); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.search_v2(prefix text, bucket_name text, limits integer DEFAULT 100, levels integer DEFAULT 1, start_after text DEFAULT ''::text, sort_order text DEFAULT 'asc'::text, sort_column text DEFAULT 'name'::text, sort_column_after text DEFAULT ''::text, noncurrent_versions text DEFAULT 'exclude'::text, delete_markers text DEFAULT 'exclude'::text, start_after_archived_at timestamp with time zone DEFAULT NULL::timestamp with time zone, start_after_version text DEFAULT ''::text, start_after_is_continuation boolean DEFAULT false) RETURNS TABLE(key text, name text, id uuid, updated_at timestamp with time zone, created_at timestamp with time zone, last_accessed_at timestamp with time zone, metadata jsonb, version text, archived_at timestamp with time zone, is_delete_marker boolean, is_versioned boolean)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_sort_col text;
    v_sort_ord text;
    v_limit int;
BEGIN
    -- Cap limit to maximum of 1500 records
    v_limit := LEAST(coalesce(limits, 100), 1500);

    -- Validate and normalize sort_order
    v_sort_ord := lower(coalesce(sort_order, 'asc'));
    IF v_sort_ord NOT IN ('asc', 'desc') THEN
        v_sort_ord := 'asc';
    END IF;

    -- Validate and normalize sort_column
    v_sort_col := lower(coalesce(sort_column, 'name'));
    IF v_sort_col NOT IN ('name', 'updated_at', 'created_at') THEN
        v_sort_col := 'name';
    END IF;

    -- Route to appropriate implementation
    IF v_sort_col = 'name' THEN
        -- Use list_objects_with_delimiter for name sorting (most efficient: O(k * log n))
        RETURN QUERY
        SELECT
            split_part(l.name, '/', levels) AS key,
            l.name AS name,
            l.id,
            l.updated_at,
            l.created_at,
            l.last_accessed_at,
            l.metadata,
            l.version,
            l.archived_at,
            l.is_delete_marker,
            l.is_versioned
        FROM storage.list_objects_with_delimiter(
            bucket_name,
            coalesce(prefix, ''),
            '/',
            v_limit,
            CASE WHEN start_after_is_continuation THEN '' ELSE start_after END,
            CASE WHEN start_after_is_continuation THEN start_after ELSE '' END,
            v_sort_ord,
            noncurrent_versions,
            delete_markers,
            start_after_archived_at,
            start_after_version
        ) l;
    ELSE
        -- Use aggregation approach for timestamp sorting
        -- Not efficient for large datasets but supports correct pagination
        RETURN QUERY SELECT * FROM storage.search_by_timestamp(
            prefix, bucket_name, v_limit, levels, start_after,
            v_sort_ord, v_sort_col, sort_column_after,
            noncurrent_versions, delete_markers, start_after_version
        );
    END IF;
END;
$$;


--
-- Name: update_updated_at_column(); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.update_updated_at_column() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW; 
END;
$$;


--
-- Name: wake_lifecycle_state(); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.wake_lifecycle_state() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP = 'INSERT' AND NEW.lifecycle_configuration IS NULL THEN
        RETURN NEW;
    END IF;

    PERFORM storage.reconcile_lifecycle_state(NEW.id, false);
    RETURN NEW;
END;
$$;


--
-- Name: account_actor(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.account_actor() RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE u uuid:=auth.uid(); BEGIN
 IF u IS NULL OR auth.jwt()->>'role' IS DISTINCT FROM 'authenticated' THEN RAISE EXCEPTION 'authentication required' USING ERRCODE='42501'; END IF;
 RETURN u;
END $$;


--
-- Name: account_deletion_purge_allowed(uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.account_deletion_purge_allowed(p_user uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT pg_trigger_depth()>1 AND EXISTS(SELECT 1 FROM twuanis_canonical_private.account_principals WHERE id=p_user AND deleted_at IS NOT NULL)
$$;


--
-- Name: account_evidence_guard(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.account_evidence_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF TG_TABLE_NAME='account_profiles' AND NEW.active_image_id IS NOT NULL THEN
  PERFORM 1 FROM twuanis_canonical_private.account_profile_images i WHERE i.id=NEW.active_image_id AND i.user_id=NEW.user_id AND i.state='READY' FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'profile image must be owned and ready' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: account_image_guard(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.account_image_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='DELETE' AND twuanis_canonical_private.account_deletion_purge_allowed(OLD.user_id) THEN RETURN OLD;END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'retire image metadata; do not delete history' USING ERRCODE='23514'; END IF;
 IF (NEW.id,NEW.user_id,NEW.object_version,NEW.created_at) IS DISTINCT FROM (OLD.id,OLD.user_id,OLD.object_version,OLD.created_at) THEN RAISE EXCEPTION 'immutable image identity' USING ERRCODE='23514'; END IF;
 IF OLD.state<>'STAGED' AND (NEW.mime,NEW.width,NEW.height,NEW.byte_size,NEW.validated_at) IS DISTINCT FROM (OLD.mime,OLD.width,OLD.height,OLD.byte_size,OLD.validated_at) THEN RAISE EXCEPTION 'immutable validated image metadata' USING ERRCODE='23514'; END IF;
 IF NEW.state<>OLD.state AND NOT ((OLD.state='STAGED' AND NEW.state IN ('READY','DELETED')) OR (OLD.state='READY' AND NEW.state='RETIRED') OR (OLD.state='RETIRED' AND NEW.state='DELETED')) THEN RAISE EXCEPTION 'invalid image lifecycle' USING ERRCODE='23514'; END IF;
 IF NEW.state<>'READY' AND EXISTS(SELECT 1 FROM twuanis_canonical_private.account_profiles p WHERE p.active_image_id=OLD.id) THEN RAISE EXCEPTION 'clear active reference before retirement' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: account_immutable(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.account_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='DELETE' AND twuanis_canonical_private.account_deletion_purge_allowed(OLD.user_id) THEN RETURN OLD;END IF; RAISE EXCEPTION 'immutable account evidence' USING ERRCODE='23514'; END $$;


--
-- Name: account_phone_guard(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.account_phone_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF NEW.user_id<>OLD.user_id THEN RAISE EXCEPTION 'immutable phone owner'; END IF;
 IF NEW.phone_e164 IS DISTINCT FROM OLD.phone_e164 THEN
  NEW.revision:=OLD.revision+1; NEW.updated_at:=clock_timestamp();
 ELSIF NEW.revision<>OLD.revision THEN RAISE EXCEPTION 'phone revision changes only with phone' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: acknowledge_offer_order_paid(uuid, uuid, text, uuid, numeric, text, text, text); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.acknowledge_offer_order_paid(p_order uuid, p_request uuid, p_source text, p_event uuid, p_amount numeric, p_currency text, p_authority text, p_external_reference text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE o twuanis_canonical_private.offer_order_snapshots%ROWTYPE;a twuanis_canonical_private.offer_paid_acknowledgements%ROWTYPE;at_time timestamptz;aid uuid;
BEGIN
 IF p_order IS NULL OR p_request IS NULL OR p_event IS NULL OR nullif(btrim(p_source),'') IS NULL OR nullif(btrim(p_authority),'') IS NULL OR p_amount IS NULL OR p_currency IS NULL THEN RAISE EXCEPTION 'trusted payment evidence required'; END IF;
 PERFORM pg_advisory_xact_lock(3163,hashtext(p_request::text));
 SELECT * INTO a FROM twuanis_canonical_private.offer_paid_acknowledgements WHERE request_id=p_request;
 IF FOUND THEN
  IF (a.order_id,a.source,a.payment_event_id,a.amount,a.currency,a.authority,a.external_reference) IS DISTINCT FROM (p_order,p_source,p_event,p_amount,p_currency,p_authority,p_external_reference) THEN RAISE EXCEPTION 'payment acknowledgement replay conflict'; END IF;
  RETURN jsonb_build_object('id',a.id,'orderId',a.order_id,'state','paid','replayed',true);
 END IF;
 SELECT * INTO STRICT o FROM twuanis_canonical_private.offer_order_snapshots WHERE id=p_order;
 IF o.listing_id IS NOT NULL THEN PERFORM id FROM public.listings WHERE id=o.listing_id FOR UPDATE; END IF;
 SELECT * INTO STRICT o FROM twuanis_canonical_private.offer_order_snapshots WHERE id=p_order FOR UPDATE;
 at_time:=clock_timestamp();
 IF EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_paid_acknowledgements WHERE order_id=p_order) THEN RAISE EXCEPTION 'order already acknowledged'; END IF;
 IF at_time>=o.payment_deadline THEN RAISE EXCEPTION 'expired unpaid order; later payment resolution required'; END IF;
 IF p_currency IS DISTINCT FROM o.currency OR p_amount IS DISTINCT FROM (o.resolved_terms->>'total')::numeric THEN RAISE EXCEPTION 'payment does not match immutable order'; END IF;
 INSERT INTO twuanis_canonical_private.offer_paid_acknowledgements(order_id,request_id,source,payment_event_id,external_reference,amount,currency,acknowledged_at,authority)
 VALUES(p_order,p_request,p_source,p_event,p_external_reference,p_amount,p_currency,at_time,p_authority) RETURNING id INTO aid;
 RETURN jsonb_build_object('id',aid,'orderId',p_order,'state','paid','replayed',false);
END $$;


--
-- Name: addon_customer_input(jsonb); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.addon_customer_input(p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE d jsonb;content jsonb;geo bigint[];x record;t record;ids bigint[];tags text[];v jsonb;f jsonb;kind text;n numeric;c text;
BEGIN
 PERFORM twuanis_canonical_private.s3_keys(p_input,ARRAY['transaction','geography','semantics','facts','measurements','money','content'],ARRAY['transaction','geography','semantics']);
 IF jsonb_typeof(p_input->'transaction') IS DISTINCT FROM 'string' OR p_input->>'transaction' NOT IN ('sale','rent') THEN RAISE EXCEPTION 'explicit sale/rent required'; END IF;
 d:=twuanis_canonical_private.s4_domains(p_input-ARRAY['transaction','content'],'owner');
 IF NOT (d->'semantics') ? 'property_type' OR cardinality(twuanis_canonical_private.s3_term_ids(d->'semantics'->'property_type'))<>1 THEN RAISE EXCEPTION 'exactly one property type required'; END IF;
 content:=coalesce(p_input->'content','{}');PERFORM twuanis_canonical_private.s3_keys(content,ARRAY['title','description','whatsapp']);
 FOREACH c IN ARRAY ARRAY['title','description','whatsapp'] LOOP
  IF content ? c AND (jsonb_typeof(content->c) IS DISTINCT FROM 'string' OR length(content->>c)>(CASE c WHEN 'title' THEN 512 WHEN 'description' THEN 16000 ELSE 256 END)) THEN RAISE EXCEPTION 'bounded text content required'; END IF;
 END LOOP;
 geo:=twuanis_canonical_private.s3_geography(d->'geography');
 PERFORM twuanis_canonical_private.canonical_origin_ids('geography',geo);
 FOR x IN SELECT key,value FROM jsonb_each(d->'semantics') ORDER BY key LOOP
  ids:=twuanis_canonical_private.s3_term_ids(x.value);
  IF (x.key='property_type' AND cardinality(ids)<>1) OR (x.key='legal_status' AND cardinality(ids)>1) THEN RAISE EXCEPTION 'semantic cardinality'; END IF;
  FOR t IN SELECT id,term_type,level,term_name FROM public.ontology_terms WHERE id=ANY(ids) ORDER BY id FOR SHARE LOOP
   IF t.term_type IS DISTINCT FROM x.key OR t.level IS DISTINCT FROM 1 OR t.term_name IS NULL THEN RAISE EXCEPTION 'semantic type/level'; END IF;
  END LOOP;
  IF (SELECT count(*) FROM public.ontology_terms WHERE id=ANY(ids))<>cardinality(ids) THEN RAISE EXCEPTION 'unknown semantic identity'; END IF;
  IF x.key='accessibility' THEN
   PERFORM term_id FROM twuanis_canonical_private.accessibility_identity WHERE term_id=ANY(ids) ORDER BY term_id FOR SHARE;
   SELECT array_agg(code) INTO tags FROM twuanis_canonical_private.accessibility_identity WHERE term_id=ANY(ids);
   IF coalesce(cardinality(tags),0)<>cardinality(ids) OR ('boat'=ANY(tags) AND cardinality(tags)>1) OR ('4x4'=ANY(tags) AND tags && ARRAY['2wd','paved']) THEN RAISE EXCEPTION 'accessibility incompatible'; END IF;
  END IF;
  PERFORM twuanis_canonical_private.canonical_origin_ids(x.key,ids);
 END LOOP;
 FOR x IN SELECT key,value FROM jsonb_each(coalesce(d->'facts','{}')) LOOP
  v:=x.value;kind:=v->>'kind';ids:='{}';
  PERFORM twuanis_canonical_private.s3_keys(v,ARRAY['kind','value','term','lower','upper','lower_inclusive','upper_inclusive','source','reference'],ARRAY['kind']);
  IF kind='clear' THEN IF v<>'{"kind":"clear"}'::jsonb THEN RAISE EXCEPTION 'clear has no value'; END IF;CONTINUE; END IF;
  f:=jsonb_build_object('dimension',x.key,'kind',kind,'evidence_source','owner','evidence_reference',v->'reference');
  IF kind='exact' THEN
   IF v ?| ARRAY['term','lower','upper','lower_inclusive','upper_inclusive'] THEN RAISE EXCEPTION 'exact fact shape'; END IF;
   f:=f||jsonb_build_object('exact_value',twuanis_canonical_private.s3_decimal(v->'value'));
  ELSIF kind='category' THEN
   IF v ?| ARRAY['value','lower','upper','lower_inclusive','upper_inclusive'] THEN RAISE EXCEPTION 'category fact shape'; END IF;
   ids:=twuanis_canonical_private.s3_term_ids(jsonb_build_array(v->'term'));
   SELECT * INTO STRICT t FROM public.ontology_terms WHERE id=ids[1] FOR SHARE;
   IF t.term_type IS DISTINCT FROM x.key OR t.level IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'fact category type'; END IF;
   f:=f||jsonb_build_object('category_term_id',ids[1]);
  ELSIF kind='range' THEN
   IF v ?| ARRAY['value','term'] OR NOT v ?& ARRAY['lower','upper','lower_inclusive','upper_inclusive'] OR jsonb_typeof(v->'lower_inclusive') IS DISTINCT FROM 'boolean' OR jsonb_typeof(v->'upper_inclusive') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'explicit range required'; END IF;
   f:=f||jsonb_build_object('range_lower',CASE WHEN v->'lower'='null' THEN NULL ELSE twuanis_canonical_private.s3_decimal(v->'lower') END,'range_upper',CASE WHEN v->'upper'='null' THEN NULL ELSE twuanis_canonical_private.s3_decimal(v->'upper') END,'lower_inclusive',v->'lower_inclusive','upper_inclusive',v->'upper_inclusive');
  ELSE RAISE EXCEPTION 'invalid fact kind'; END IF;
  IF NOT twuanis_canonical_private.addon_validate_fact_record(f) THEN RAISE EXCEPTION 'canonical fact constraint'; END IF;
  PERFORM twuanis_canonical_private.canonical_origin_ids(x.key,ids);
 END LOOP;
 FOR x IN SELECT key,value FROM jsonb_each(coalesce(d->'measurements','{}')) LOOP
  PERFORM twuanis_canonical_private.s3_keys(x.value,ARRAY['value'],ARRAY['value']);
  n:=twuanis_canonical_private.s3_decimal(x.value->'value');IF n<=0 THEN RAISE EXCEPTION 'positive exact measurement required'; END IF;
 END LOOP;
 -- Successful bulk fulfillment includes publication, so original monetary evidence is required.
 IF NOT d ? 'money' THEN RAISE EXCEPTION 'publication requires monetary evidence'; END IF;
 n:=twuanis_canonical_private.s3_decimal(d->'money'->'amount');
 IF n<=0 OR d->'money'->>'currency' IS NULL OR d->'money'->>'currency' NOT IN ('USD','CRC') THEN RAISE EXCEPTION 'positive original monetary pair required'; END IF;
 RETURN p_input;
END $$;


--
-- Name: addon_projection(text); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.addon_projection(pid text) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT jsonb_build_object('id',p.id,'name_en',p.name_en,'name_es',p.name_es,'description_en',p.description_en,'description_es',p.description_es,
 'placementMarket',c.placement_market,'purchasesEnabled',p.state='active','target',p.target,'behavior',p.behavior,'termKind',p.term_kind,'state',p.state,'revision',p.revision::text,'configurationId',c.id,'version',c.version::text,
 'durationDays',CASE WHEN (c.calendar_months=1 OR c.id='05000000-0000-4000-8000-000000000103'::uuid) THEN NULL ELSE c.duration_days END,'termQuantity',CASE WHEN (c.calendar_months=1 OR c.id='05000000-0000-4000-8000-000000000103'::uuid) THEN 1 END,'termUnit',CASE WHEN (c.calendar_months=1 OR c.id='05000000-0000-4000-8000-000000000103'::uuid) THEN 'month' END,'capacity',CASE WHEN p.behavior='homepage_carousel' THEN (SELECT capacity FROM twuanis_canonical_private.addon_homepage_capacity WHERE id) END,
 'standardPrices',coalesce((SELECT jsonb_object_agg(currency,amount::text) FROM twuanis_canonical_private.addon_standard_prices WHERE configuration_id=c.id),'{}'),
 'quantityTiers',coalesce((SELECT jsonb_agg(jsonb_build_object('min',lower_quantity,'max',upper_quantity,'currency',currency,'unitRate',unit_rate::text) ORDER BY lower_quantity) FROM twuanis_canonical_private.addon_quantity_tiers WHERE configuration_id=c.id),'[]'),
 'acquisitionAvailable',false,'acquisitionState',CASE WHEN p.term_kind='unconfigured' THEN 'unconfigured' ELSE 'fulfillment_not_activated' END)
 FROM twuanis_canonical_private.addon_products p JOIN twuanis_canonical_private.addon_configurations c ON c.id=p.current_configuration_id AND c.product_id=p.id WHERE p.id=pid
$$;


--
-- Name: addon_publication_capacity(uuid, integer); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.addon_publication_capacity(p_owner uuid, p_quantity integer) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE pub uuid;a record;used bigint:=0;seconds bigint;
BEGIN
 IF p_quantity IS NULL OR p_quantity<1 THEN RAISE EXCEPTION 'positive batch count required'; END IF;
 PERFORM twuanis_canonical_private.lock_capacity_policy(false);
 SELECT id INTO pub FROM public.publisher_accounts WHERE owner_user_id=p_owner FOR UPDATE;
 IF pub IS NOT NULL THEN used:=twuanis_canonical_private.publisher_consumption(pub,p_owner); END IF;
 SELECT * INTO STRICT a FROM twuanis_canonical_private.customer_publication_allowance(p_owner);
 seconds:=2592000;
 IF seconds IS NULL OR seconds NOT BETWEEN 1 AND 315576000 THEN RAISE EXCEPTION 'publication duration authority unavailable'; END IF;
 IF NOT a.unlimited AND a.allowance-used<p_quantity THEN RAISE EXCEPTION 'whole-job publication allowance insufficient'; END IF;
 RETURN jsonb_build_object('subscriptionId',a.subscription_id,'packageId',a.package_id,'allowance',a.allowance,'consumption',used,'durationSeconds',seconds,'observedAt',a.observed_at);
END $$;


--
-- Name: addon_validate_fact_record(jsonb); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.addon_validate_fact_record(v jsonb) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$SELECT ((((kind = 'exact'::text) AND (exact_value IS NOT NULL) AND (category_term_id IS NULL) AND (range_lower IS NULL) AND (range_upper IS NULL) AND (lower_inclusive IS NULL) AND (upper_inclusive IS NULL)) OR ((kind = 'category'::text) AND (exact_value IS NULL) AND (category_term_id IS NOT NULL) AND (range_lower IS NULL) AND (range_upper IS NULL) AND (lower_inclusive IS NULL) AND (upper_inclusive IS NULL) AND (dimension <> 'distance_to_paved_road'::text)) OR ((kind = 'range'::text) AND (exact_value IS NULL) AND (category_term_id IS NULL) AND ((range_lower IS NOT NULL) OR (range_upper IS NOT NULL)) AND (lower_inclusive IS NOT NULL) AND (upper_inclusive IS NOT NULL) AND ((range_lower IS NOT NULL) OR (NOT lower_inclusive)) AND ((range_upper IS NOT NULL) OR (NOT upper_inclusive)) AND (NOT isempty(numrange(range_lower, range_upper, (
CASE
    WHEN lower_inclusive THEN '['::text
    ELSE '('::text
END ||
CASE
    WHEN upper_inclusive THEN ']'::text
    ELSE ')'::text
END))))))) IS NOT FALSE AND ((twuanis_canonical_private.finite_numeric(exact_value) AND twuanis_canonical_private.finite_numeric(range_lower) AND twuanis_canonical_private.finite_numeric(range_upper))) IS NOT FALSE AND ((((exact_value IS NULL) OR (exact_value >= (0)::numeric)) AND ((range_lower IS NULL) OR (range_lower >= (0)::numeric)) AND ((range_upper IS NULL) OR (range_upper >= (0)::numeric)))) IS NOT FALSE AND (((dimension <> 'bathrooms'::text) OR (kind <> 'exact'::text) OR (exact_value > (0)::numeric))) IS NOT FALSE AND (((dimension <> ALL (ARRAY['bedrooms'::text, 'parking'::text, 'year_built'::text])) OR (((exact_value IS NULL) OR (exact_value = trunc(exact_value))) AND ((range_lower IS NULL) OR (range_lower = trunc(range_lower))) AND ((range_upper IS NULL) OR (range_upper = trunc(range_upper)))))) IS NOT FALSE AND (((dimension <> 'year_built'::text) OR (((exact_value IS NULL) OR ((exact_value >= (1)::numeric) AND (exact_value <= (9999)::numeric))) AND ((range_lower IS NULL) OR ((range_lower >= (1)::numeric) AND (range_lower <= (9999)::numeric))) AND ((range_upper IS NULL) OR ((range_upper >= (1)::numeric) AND (range_upper <= (9999)::numeric)))))) IS NOT FALSE AND ((dimension = ANY (ARRAY['bedrooms'::text, 'bathrooms'::text, 'parking'::text, 'year_built'::text, 'distance_to_paved_road'::text]))) IS NOT FALSE AND (((evidence_reference IS NULL) OR ((length(evidence_reference) >= 1) AND (length(evidence_reference) <= 1024)))) IS NOT FALSE AND ((evidence_source = ANY (ARRAY['owner'::text, 'source'::text, 'manual'::text, 'migration'::text]))) IS NOT FALSE AND ((kind = ANY (ARRAY['exact'::text, 'category'::text, 'range'::text]))) IS NOT FALSE FROM jsonb_populate_record(NULL::public.listing_fact_evidence,v) f$$;


--
-- Name: admin_account_projection(uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.admin_account_projection(p_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT jsonb_build_object('id',u.id,'email',u.email,'confirmed',u.email_confirmed_at IS NOT NULL,
 'name',coalesce(nullif(btrim(p.display_name),''),nullif(btrim(u.raw_user_meta_data->>'full_name'),''),nullif(btrim(u.raw_user_meta_data->>'name'),'')),
 'phone',coalesce(s.phone_e164,nullif(u.phone,'')),
 'active',coalesce(a.active,false),
 'owner',EXISTS(SELECT 1 FROM twuanis_canonical_private.owner_access_grants o WHERE o.user_id=u.id AND o.revoked_at IS NULL),
 'topAdministrator',EXISTS(SELECT 1 FROM twuanis_canonical_private.top_administrator t WHERE t.user_id=u.id),
 'permissions',(SELECT coalesce(jsonb_agg(g.permission ORDER BY g.permission),'[]'::jsonb) FROM twuanis_canonical_private.administrative_permission_grants g WHERE g.user_id=u.id))
 FROM auth.users u LEFT JOIN twuanis_canonical_private.administrators a ON a.user_id=u.id
 LEFT JOIN twuanis_canonical_private.account_profiles p ON p.user_id=u.id
 LEFT JOIN twuanis_canonical_private.account_phone_state s ON s.user_id=u.id
 WHERE u.id=p_id
$$;


--
-- Name: admin_listing_snapshot(uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.admin_listing_snapshot(p_listing uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT jsonb_build_object('revision',l.canonical_revision,'status',l.listing_status,'property_area',l.property_area,'construction_area',l.construction_area,'owner',l.owner_id,'origin',l.listing_origin,'source_name',l.source_name,'source_listing_id',l.source_listing_id,'source_type',l.listing_source_type,
 'content',jsonb_build_object('title',l.title,'description',l.description,'whatsapp',l.whatsapp),
 'money',jsonb_build_object('transaction',l.transaction_type,'current_price',l.current_price,'monthly_price',l.monthly_price,'currency',l.currency),
 'geography',jsonb_build_object('province',l.province,'canton',l.canton,'district',l.district),
 'facts',(SELECT coalesce(jsonb_agg(to_jsonb(f)),'[]') FROM public.listing_fact_evidence f WHERE f.listing_id=l.id),
 'selections',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]') FROM public.listing_semantic_selections t WHERE t.listing_id=l.id))
 FROM public.listings l WHERE l.id=p_listing;
$$;


--
-- Name: admin_source_media_refresh(uuid, text[]); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.admin_source_media_refresh(p_listing uuid, p_images text[]) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE g twuanis_canonical_private.administrative_media_groups%ROWTYPE;
BEGIN
 SELECT * INTO g FROM twuanis_canonical_private.administrative_media_groups WHERE listing_id=p_listing FOR UPDATE;
 IF FOUND THEN
  UPDATE twuanis_canonical_private.administrative_media_groups SET source=p_images,revision=revision+1 WHERE listing_id=p_listing;
  UPDATE public.listings SET images=to_jsonb(g.managed||p_images)::text WHERE id=p_listing;
 ELSE UPDATE public.listings SET images=array_to_string(p_images,'|') WHERE id=p_listing; END IF;
END $$;


--
-- Name: administrative_actor(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.administrative_actor() RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v uuid:=auth.uid();
BEGIN
 IF v IS NULL OR auth.jwt()->>'role' IS DISTINCT FROM 'authenticated'
 OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=v) THEN
  RAISE EXCEPTION 'administrative access denied' USING ERRCODE='42501';
 END IF;
 RETURN v;
END $$;


--
-- Name: administrative_immutable(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.administrative_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$ BEGIN RAISE EXCEPTION 'administrative history is immutable' USING ERRCODE='42501'; END $$;


--
-- Name: administrative_permission(uuid, text); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.administrative_permission(p_actor uuid, p_permission text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT EXISTS(SELECT 1 FROM twuanis_canonical_private.administrative_permissions WHERE permission=p_permission)
 AND (EXISTS(SELECT 1 FROM twuanis_canonical_private.owner_access_grants WHERE user_id=p_actor AND revoked_at IS NULL)
 OR (p_permission IN ('administrators.read','administrators.manage') AND EXISTS(SELECT 1 FROM twuanis_canonical_private.top_administrator WHERE user_id=p_actor))
 OR (p_permission <> 'administrators.manage' AND EXISTS(
 SELECT 1 FROM twuanis_canonical_private.administrators a JOIN twuanis_canonical_private.administrative_permission_grants g USING(user_id)
 WHERE a.user_id=p_actor AND a.active AND g.permission=p_permission)))
$$;


--
-- Name: administrative_reason_required(text); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.administrative_reason_required(p_operation text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT p_operation IN ('owner.grant','owner.revoke','top.assign','owner.recover','delete','entitlement.revoke','payment.reject','override','exceptional_correction','listing.archive_other')
$$;


--
-- Name: append_administrative_event(uuid, text, text, text, text, uuid, jsonb, jsonb, text, uuid, text); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.append_administrative_event(p_actor uuid, p_authority text, p_permission text, p_operation text, p_target_type text, p_target uuid, p_before jsonb, p_after jsonb, p_reason text, p_request uuid, p_result text DEFAULT 'succeeded'::text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v bigint;
BEGIN
 IF p_actor IS DISTINCT FROM twuanis_canonical_private.administrative_actor() OR p_request IS NULL THEN
 RAISE EXCEPTION 'administrative access denied' USING ERRCODE='42501'; END IF;
 IF length(p_reason)>2000 OR (p_result='succeeded' AND twuanis_canonical_private.administrative_reason_required(p_operation) AND nullif(btrim(p_reason),'') IS NULL) THEN
 RAISE EXCEPTION 'administrative reason required' USING ERRCODE='22023'; END IF;
 INSERT INTO twuanis_canonical_private.administrative_events(actor_id,authority,permission,operation,target_type,target_id,result,before_state,after_state,reason,request_id)
 VALUES(p_actor,p_authority,p_permission,p_operation,p_target_type,p_target,p_result,p_before,p_after,nullif(btrim(p_reason),''),p_request) RETURNING id INTO v;
 RETURN v;
END $$;


--
-- Name: apply_package_payment_quote(uuid, text, text, boolean, timestamp with time zone, jsonb); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.apply_package_payment_quote(p_account uuid, p_product text, p_duration text, p_bank boolean, p_at timestamp with time zone, p_terms jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE q jsonb;provider text;selected jsonb;bank numeric:=coalesce((p_terms->'bankUpgrade'->>'amount')::numeric,0);gross numeric;standard_gross numeric;BEGIN
 q:=twuanis_canonical_private.package_payment_quote(p_account,p_product,p_duration,p_bank,p_at);
 provider:=CASE p_terms->>'currency'WHEN 'CRC'THEN 'sinpe'WHEN 'USD'THEN 'stripe'ELSE NULL END;
 IF provider IS NULL THEN RAISE EXCEPTION 'supported Package charge currency required';END IF;
 selected:=q->provider;
 IF selected->'available' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'approved method quote unavailable; price review required';END IF;
 IF provider='sinpe'AND(p_terms->>'total')::numeric<>(selected->>'chargeAmount')::numeric THEN RAISE EXCEPTION 'SINPE canonical price preservation mismatch';END IF;
 gross:=(selected->>'chargeAmount')::numeric;standard_gross:=(selected->'standardDisplayAmounts'->>(selected->>'chargeCurrency'))::numeric;
 RETURN p_terms||jsonb_build_object('total',gross::text,'standardTotal',standard_gross::text,'effectiveRate',(gross-bank)::text,'standardRate',(standard_gross-bank)::text,'baseTotal',(gross-bank)::text,'baseStandardTotal',(standard_gross-bank)::text,'unitPrice',CASE WHEN p_duration='day'THEN gross::text ELSE p_terms->>'unitPrice'END,'currencyQuotes',jsonb_build_object('USD',jsonb_build_object('total',selected->'displayAmounts'->>'USD'),'CRC',jsonb_build_object('total',selected->'displayAmounts'->>'CRC')),'paymentPricing',q,'paymentMethod',provider,'paymentBaseTerms',p_terms);

END $$;


--
-- Name: assert_account_deletable(uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.assert_account_deletable(p_user uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 PERFORM pg_advisory_xact_lock(3110,1);
 IF EXISTS(SELECT 1 FROM twuanis_canonical_private.owner_access_grants WHERE user_id=p_user AND revoked_at IS NULL)
 OR EXISTS(SELECT 1 FROM twuanis_canonical_private.top_administrator WHERE user_id=p_user) THEN RAISE EXCEPTION 'protected Owner or top administrator' USING ERRCODE='42501';END IF;
 IF EXISTS(SELECT 1 FROM twuanis_canonical_private.administrators WHERE user_id=p_user AND active)
 AND NOT EXISTS(SELECT 1 FROM auth.users u WHERE u.id<>p_user AND(
 EXISTS(SELECT 1 FROM twuanis_canonical_private.administrators a WHERE a.user_id=u.id AND a.active)
 OR EXISTS(SELECT 1 FROM twuanis_canonical_private.owner_access_grants o WHERE o.user_id=u.id AND o.revoked_at IS NULL)
 OR EXISTS(SELECT 1 FROM twuanis_canonical_private.top_administrator t WHERE t.user_id=u.id))) THEN RAISE EXCEPTION 'last administrator protected' USING ERRCODE='42501';END IF;
END$$;


--
-- Name: assert_administrative_permission(text); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.assert_administrative_permission(p_permission text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v uuid;
BEGIN
 PERFORM pg_advisory_xact_lock(3110,1);
 v:=twuanis_canonical_private.administrative_actor();
 IF NOT twuanis_canonical_private.administrative_permission(v,p_permission) THEN
 RAISE EXCEPTION 'administrative access denied' USING ERRCODE='42501'; END IF;
 RETURN v;
END $$;


--
-- Name: assert_advertising_market_interval(text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.assert_advertising_market_interval(p_market text, p_start timestamp with time zone, p_end timestamp with time zone) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$DECLARE peak bigint;BEGIN IF p_market IS NULL OR p_market NOT IN('sale','rent')OR p_start IS NULL OR p_end IS NULL OR NOT isfinite(p_start)OR NOT isfinite(p_end)OR p_end<=p_start THEN RAISE EXCEPTION 'bounded advertising interval required';END IF;PERFORM capacity FROM twuanis_canonical_private.addon_homepage_capacity WHERE id FOR UPDATE; WITH intervals AS(SELECT tstzrange(greatest(t.starts_at,p_start),least(t.ends_at,p_end,coalesce(r.revoked_at,t.ends_at)),'[)') span FROM twuanis_canonical_private.entitlement_terms t JOIN twuanis_canonical_private.addon_products p ON p.id=t.product_id JOIN twuanis_canonical_private.addon_placement_markets m ON m.term_id=t.id LEFT JOIN twuanis_canonical_private.entitlement_revocations r ON r.term_id=t.id WHERE p.behavior='homepage_carousel' AND m.market=p_market AND t.starts_at<p_end AND t.ends_at>p_start AND (r.term_id IS NULL OR (r.revoked_at>p_start AND r.revoked_at>t.starts_at))),events AS(SELECT lower(span) at_time,1 delta FROM intervals UNION ALL SELECT upper(span),-1 FROM intervals UNION ALL SELECT p_start,1 UNION ALL SELECT p_end,-1),sweep AS(SELECT sum(sum(delta))OVER(ORDER BY at_time) occupied FROM events GROUP BY at_time)SELECT max(occupied)INTO peak FROM sweep;
 IF peak>5 THEN RAISE EXCEPTION 'homepage_capacity_full';END IF;END$$;


--
-- Name: assert_execution_credit_delivery(uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.assert_execution_credit_delivery(p_order uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$DECLARE o twuanis_canonical_private.offer_order_snapshots%ROWTYPE;a twuanis_canonical_private.execution_credit_allocations%ROWTYPE;ack uuid;BEGIN
 SELECT * INTO STRICT o FROM twuanis_canonical_private.offer_order_snapshots WHERE id=p_order;SELECT id INTO STRICT ack FROM twuanis_canonical_private.offer_paid_acknowledgements WHERE order_id=o.id;PERFORM twuanis_canonical_private.assert_execution_credit_payment(o.id,ack);
 SELECT * INTO STRICT a FROM twuanis_canonical_private.execution_credit_allocations WHERE order_id=o.id AND kind='PURCHASED';
 IF a.account_id<>o.account_id OR a.quantity<>(o.resolved_terms->>'quantity')::bigint OR a.acknowledgement_id<>ack OR a.origin<>'ORDER:'||o.id OR a.expires_at IS NOT NULL OR a.package_id IS NOT NULL OR a.term_id IS NOT NULL OR NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.execution_credit_events WHERE allocation_id=a.id AND account_id=o.account_id AND kind='PURCHASE_CREDITED'AND quantity=a.quantity)THEN RAISE EXCEPTION 'Complete exact token delivery required';END IF;RETURN a.id;
END$$;


--
-- Name: assert_execution_credit_payment(uuid, uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.assert_execution_credit_payment(p_order uuid, p_ack uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$DECLARE o twuanis_canonical_private.offer_order_snapshots%ROWTYPE;v twuanis_canonical_private.execution_credit_price_versions%ROWTYPE;a twuanis_canonical_private.offer_paid_acknowledgements%ROWTYPE;q bigint;BEGIN
 SELECT * INTO STRICT o FROM twuanis_canonical_private.offer_order_snapshots WHERE id=p_order;IF o.target_type<>'execution_credit'OR o.product_id<>'execution-credit-v1'THEN RAISE EXCEPTION 'Exact approved execution-credit payment correspondence required' USING ERRCODE='23514';END IF;SELECT * INTO STRICT v FROM twuanis_canonical_private.execution_credit_price_versions WHERE id=(o.resolved_terms->>'priceVersionId')::uuid;
 q:=(o.resolved_terms->>'quantity')::bigint;
 IF o.target_type<>'execution_credit'OR o.product_id<>v.product_id OR v.version<>(o.resolved_terms->>'priceVersion')::integer OR v.effective_from>o.created_at OR(v.effective_until IS NOT NULL AND o.created_at>=v.effective_until)OR q IS NULL OR q NOT IN(2,5,10,20,50)OR(o.resolved_terms->>'unitPrice')::numeric IS DISTINCT FROM(CASE WHEN o.currency='USD'THEN v.usd_unit ELSE CASE WHEN o.resolved_terms?'fx'THEN round(v.usd_unit*(SELECT rate FROM public.fx_rates WHERE base_currency='USD'AND quote_currency='CRC'AND rate_type='reference_sale'AND source='BCCR'AND effective_date<=(o.created_at AT TIME ZONE 'America/Costa_Rica')::date ORDER BY effective_date DESC LIMIT 1),0)ELSE v.crc_unit END END)OR(o.resolved_terms->>'total')::numeric IS DISTINCT FROM q*(CASE WHEN o.currency='USD'THEN v.usd_unit ELSE CASE WHEN o.resolved_terms?'fx'THEN round(v.usd_unit*(SELECT rate FROM public.fx_rates WHERE base_currency='USD'AND quote_currency='CRC'AND rate_type='reference_sale'AND source='BCCR'AND effective_date<=(o.created_at AT TIME ZONE 'America/Costa_Rica')::date ORDER BY effective_date DESC LIMIT 1),0)ELSE v.crc_unit END END)THEN RAISE EXCEPTION 'Pinned token price correspondence required';END IF;
 SELECT * INTO STRICT a FROM twuanis_canonical_private.offer_paid_acknowledgements WHERE id=p_ack AND order_id=o.id AND currency=o.currency AND amount=(o.resolved_terms->>'total')::numeric;
 IF NOT((a.source='stripe'AND twuanis_canonical_private.stripe_paid(a.id))OR(a.source='onvo'AND EXISTS(SELECT 1 FROM twuanis_canonical_private.onvo_receipts r JOIN twuanis_canonical_private.onvo_intents i ON i.order_id=r.order_id AND i.provider_account=r.provider_account AND i.mode=r.mode WHERE r.acknowledgement_id=a.id AND r.order_id=o.id AND r.disposition='APPROVED'AND r.amount=a.amount AND r.currency=a.currency AND ((r.evidence_kind='SINPE_TRANSFER' AND r.received_at BETWEEN o.created_at AND o.payment_deadline)OR(r.evidence_kind='STANDARD_INTENT' AND r.received_at IS NULL AND r.success_verified_at BETWEEN o.created_at AND o.payment_deadline)) AND i.receiving_account IS NOT NULL))OR(a.source='sinpe'AND EXISTS(SELECT 1 FROM twuanis_canonical_private.sinpe_review_decisions d JOIN public.sinpe_payments s ON s.id=d.attempt_id WHERE d.acknowledgement_id=a.id AND d.disposition='APPROVED'AND s.canonical_order_id=o.id AND s.user_id=o.account_id AND d.amount=a.amount AND d.currency=a.currency AND d.received_at BETWEEN o.created_at AND o.payment_deadline AND d.receiving_account_id IS NOT NULL)))THEN RAISE EXCEPTION 'Existing exact approved payment evidence required' USING ERRCODE='23514';END IF;
END$$;


--
-- Name: assert_homepage_interval(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.assert_homepage_interval(p_start timestamp with time zone, p_end timestamp with time zone) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE cap integer; peak bigint;
BEGIN
 IF p_start IS NULL OR p_end IS NULL OR NOT isfinite(p_start) OR NOT isfinite(p_end) OR p_end<=p_start THEN RAISE EXCEPTION 'bounded homepage interval required';END IF;
 SELECT capacity INTO STRICT cap FROM twuanis_canonical_private.addon_homepage_capacity WHERE id FOR UPDATE;
 WITH intervals AS (
  SELECT twuanis_canonical_private.entitlement_interval(t.starts_at,t.ends_at,r.revoked_at) span
  FROM twuanis_canonical_private.entitlement_terms t
  JOIN twuanis_canonical_private.addon_products p ON p.id=t.product_id
  LEFT JOIN twuanis_canonical_private.entitlement_revocations r ON r.term_id=t.id
  WHERE p.behavior='homepage_carousel' AND t.starts_at<p_end AND t.ends_at>p_start
 ), clipped AS (
  SELECT span*tstzrange(p_start,p_end,'[)') span FROM intervals WHERE span&&tstzrange(p_start,p_end,'[)')
 ), events AS (
  SELECT lower(span) at_time,1 delta FROM clipped UNION ALL SELECT upper(span),-1 FROM clipped
  UNION ALL SELECT p_start,1 UNION ALL SELECT p_end,-1
 ), sweep AS (SELECT sum(sum(delta)) OVER(ORDER BY at_time) occupied FROM events GROUP BY at_time)
 SELECT max(occupied) INTO peak FROM sweep;
 IF peak>cap THEN RAISE EXCEPTION 'homepage_capacity_full' USING ERRCODE='P0001';END IF;
END $$;


--
-- Name: assert_package_delivery(uuid, uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.assert_package_delivery(p_order uuid, p_actor uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE o twuanis_canonical_private.offer_order_snapshots%ROWTYPE;t twuanis_canonical_private.entitlement_terms%ROWTYPE;c twuanis_canonical_private.intelligence_package_configurations%ROWTYPE;checked uuid;expected_end timestamptz;
BEGIN
 PERFORM pg_advisory_xact_lock(3200,hashtext(p_order::text));
 SELECT * INTO STRICT o FROM twuanis_canonical_private.offer_order_snapshots WHERE id=p_order;
 SELECT * INTO STRICT t FROM twuanis_canonical_private.entitlement_terms WHERE order_id=o.id;
 SELECT * INTO STRICT c FROM twuanis_canonical_private.intelligence_package_configurations WHERE id=t.configuration_id AND package_id=t.product_id;
 IF o.target_type<>'package' OR t.product_class<>'PACKAGE' OR t.source<>'PURCHASED' OR t.account_id<>o.account_id OR t.product_id<>o.product_id OR t.configuration_id::text IS DISTINCT FROM o.resolved_terms->>'configurationId'
 OR c.version::text IS DISTINCT FROM o.resolved_terms->>'configurationVersion'
 OR to_jsonb(c.capabilities) IS DISTINCT FROM o.resolved_terms->'terms'->'capabilities'
 OR o.resolved_terms->'terms'->>'quantity' IS DISTINCT FROM '1'
 OR NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.intelligence_package_rights r WHERE r.id=t.id AND r.account_id=t.account_id AND r.package_id=t.product_id AND r.configuration_id=t.configuration_id AND r.starts_at=t.starts_at AND r.ends_at=t.ends_at) THEN RAISE EXCEPTION 'complete purchased entitlement mismatch' USING ERRCODE='23514';END IF;
 IF o.resolved_terms->'terms'->>'unit'='month' THEN expected_end:=((t.starts_at AT TIME ZONE 'America/Costa_Rica')+interval '1 month') AT TIME ZONE 'America/Costa_Rica';
 ELSIF o.resolved_terms->'terms'->>'unit'='day' THEN expected_end:=t.starts_at+interval '24 hours';
 ELSE RAISE EXCEPTION 'purchased duration mismatch' USING ERRCODE='23514';END IF;
 IF NOT isfinite(t.starts_at) OR t.ends_at IS DISTINCT FROM expected_end THEN RAISE EXCEPTION 'purchased interval mismatch' USING ERRCODE='23514';END IF;
 -- Replay the restricted canonical issuer against an existing term only: its paid,
 -- price-version and Bank evidence checks are authoritative; no new term is issued.
 checked:=twuanis_canonical_private.commit_entitlement_term(t.account_id,'PACKAGE',t.product_id,t.configuration_id,NULL,'PURCHASED',o.id,t.acknowledgement_id,p_actor,gen_random_uuid(),t.starts_at,t.ends_at,NULL,NULL);
 IF checked IS DISTINCT FROM t.id THEN RAISE EXCEPTION 'complete term association mismatch' USING ERRCODE='23514';END IF;
 RETURN t.id;
END$$;


--
-- Name: audit_administrative_import(uuid, text, uuid, jsonb); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.audit_administrative_import(p_operation uuid, p_step text, p_target uuid, p_result jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE r twuanis_canonical_private.administrative_import_operations%ROWTYPE;
BEGIN
 r:=twuanis_canonical_private.lock_administrative_import(p_operation);
 IF p_step NOT IN ('import.retain','import.apply') THEN RAISE EXCEPTION 'invalid import step'; END IF;
 INSERT INTO twuanis_canonical_private.administrative_events(actor_id,authority,permission,operation,target_type,target_id,result,after_state,request_id)
 VALUES(r.actor_id,CASE WHEN EXISTS(SELECT 1 FROM twuanis_canonical_private.owner_access_grants WHERE user_id=r.actor_id AND revoked_at IS NULL) THEN 'Owner' ELSE 'Import Operator' END,'imports.manage',p_step,'source_evidence',p_target,'succeeded',p_result,p_operation);
END $$;


--
-- Name: bank_analytical_grant_terms(uuid, text); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.bank_analytical_grant_terms(p_account uuid, p_capability text) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT CASE WHEN paid IS NULL AND receipt IS NULL THEN NULL ELSE coalesce(paid,'[]'::jsonb)||coalesce(receipt,'[]'::jsonb)END FROM(SELECT twuanis_canonical_private.receipt_bank_terms(p_account,p_capability)receipt,(SELECT jsonb_agg(jsonb_build_object('id',term_id,'startsAt',starts_at,'endsAt',ends_at) ORDER BY term_id) FROM (
 SELECT t.id::text term_id,t.starts_at,t.ends_at FROM twuanis_canonical_private.entitlement_terms t
 JOIN twuanis_canonical_private.intelligence_package_rights r ON r.id=t.id AND r.account_id=t.account_id AND r.package_id=t.product_id AND r.configuration_id=t.configuration_id AND r.starts_at=t.starts_at AND r.ends_at=t.ends_at
 JOIN twuanis_canonical_private.intelligence_package_configurations c ON c.id=t.configuration_id AND c.package_id=t.product_id
 JOIN twuanis_canonical_private.offer_order_snapshots o ON o.id=t.order_id AND o.account_id=t.account_id AND o.product_id=t.product_id AND o.target_type='package'
 JOIN twuanis_canonical_private.offer_paid_acknowledgements ack ON ack.id=t.acknowledgement_id AND ack.order_id=o.id AND ack.currency=o.currency AND ack.amount=(o.resolved_terms->>'total')::numeric
 WHERE t.account_id=p_account AND t.product_class='PACKAGE' AND t.source='PURCHASED' AND t.bank_upgrade_selected
 AND t.starts_at<=statement_timestamp() AND t.ends_at>statement_timestamp() AND r.revoked_at IS NULL
 AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.entitlement_revocations v WHERE v.term_id=t.id)
 AND p_capability=ANY(c.capabilities)
 AND o.resolved_terms->>'orderContractVersion'='2'
 AND o.resolved_terms->'terms'->>'unit'='month' AND o.resolved_terms->'terms'->>'quantity'='1'
 AND o.resolved_terms->'terms'->'capabilities'=to_jsonb(c.capabilities)
 AND o.resolved_terms->>'configurationId'=t.configuration_id::text
 AND o.resolved_terms->'bankUpgrade'->'selected'='true'::jsonb
 AND ((ack.source='sinpe' AND EXISTS(SELECT 1 FROM twuanis_canonical_private.sinpe_review_decisions d WHERE d.acknowledgement_id=ack.id AND d.disposition='APPROVED'))
 OR (ack.source='onvo' AND EXISTS(SELECT 1 FROM twuanis_canonical_private.onvo_receipts v WHERE v.acknowledgement_id=ack.id AND v.disposition='APPROVED')) OR (ack.source='stripe' AND twuanis_canonical_private.stripe_paid(ack.id)))
 AND EXISTS(SELECT 1 FROM auth.users WHERE id=p_account)
 ) granting)paid)merged;
$$;


--
-- Name: bank_population_authority(uuid, text); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.bank_population_authority(p_account uuid, p_capability text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE owner_grant bigint;terms jsonb;
BEGIN
 IF p_account IS NULL OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=p_account) OR NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.intelligence_capabilities WHERE id=p_capability) THEN RAISE EXCEPTION 'Analytical identity or capability denied' USING ERRCODE='42501';END IF;
 SELECT id INTO owner_grant FROM twuanis_canonical_private.owner_access_grants WHERE user_id=p_account AND revoked_at IS NULL;
 IF owner_grant IS NOT NULL THEN RETURN jsonb_build_object('kind','OWNER_UNMETERED','ownerGrantId',owner_grant::text,'accountId',p_account,'capability',p_capability,'population','BANK','terms','[]'::jsonb);END IF;
 terms:=twuanis_canonical_private.bank_analytical_grant_terms(p_account,p_capability);
 IF terms IS NULL OR jsonb_array_length(terms)=0 THEN RAISE EXCEPTION 'Current same-term purchased capability required' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('accountId',p_account,'capability',p_capability,'population','BANK','terms',terms);
END$$;


--
-- Name: bind_addon_placement_market(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.bind_addon_placement_market() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_market text;required_market text;behavior text;peak bigint;
BEGIN
 SELECT p.behavior,c.placement_market INTO behavior,required_market FROM twuanis_canonical_private.addon_products p JOIN twuanis_canonical_private.addon_configurations c ON c.product_id=p.id WHERE p.id=NEW.product_id AND c.id=NEW.configuration_id;
 IF behavior NOT IN('homepage_carousel','featured_collection') THEN RETURN NEW;END IF;
 SELECT transaction_type INTO STRICT v_market FROM public.listings WHERE id=NEW.listing_id;
 IF v_market NOT IN('sale','rent') OR (required_market IS NOT NULL AND v_market<>required_market) THEN RAISE EXCEPTION 'advertising market mismatch';END IF;
 IF behavior='homepage_carousel' AND required_market IS NOT NULL THEN
 -- Existing capacity lock is also taken by commit_entitlement_term. Keep that protection and enforce five per market for new purchases.
 PERFORM capacity FROM twuanis_canonical_private.addon_homepage_capacity WHERE id FOR UPDATE;
 WITH intervals AS(SELECT tstzrange(greatest(t.starts_at,NEW.starts_at),least(t.ends_at,NEW.ends_at,coalesce(r.revoked_at,t.ends_at)),'[)') span FROM twuanis_canonical_private.entitlement_terms t JOIN twuanis_canonical_private.addon_products p ON p.id=t.product_id JOIN twuanis_canonical_private.addon_placement_markets m ON m.term_id=t.id LEFT JOIN twuanis_canonical_private.entitlement_revocations r ON r.term_id=t.id WHERE p.behavior='homepage_carousel' AND m.market=v_market AND t.starts_at<NEW.ends_at AND t.ends_at>NEW.starts_at AND (r.term_id IS NULL OR (r.revoked_at>NEW.starts_at AND r.revoked_at>t.starts_at))),events AS(SELECT lower(span) at_time,1 delta FROM intervals UNION ALL SELECT upper(span),-1 FROM intervals UNION ALL SELECT NEW.starts_at,1 UNION ALL SELECT NEW.ends_at,-1),sweep AS(SELECT sum(sum(delta))OVER(ORDER BY at_time) occupied FROM events GROUP BY at_time)SELECT max(occupied)INTO peak FROM sweep;
 IF peak>5 THEN RAISE EXCEPTION 'homepage_capacity_full';END IF;
 END IF;
 INSERT INTO twuanis_canonical_private.addon_placement_markets VALUES(NEW.id,v_market);
 RETURN NEW;
END$$;


--
-- Name: campaign_projection(uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.campaign_projection(cid uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT jsonb_build_object('id',c.id,'targetClass',c.target_class,'targetId',c.target_id,'revision',c.revision::text,
 'state',twuanis_canonical_private.campaign_status(c.state,v.starts_at,v.ends_at,statement_timestamp()),'creativeEvidence',(SELECT payload FROM twuanis_canonical_private.campaign_creative_versions WHERE id=v.creative_version),'configuration',jsonb_build_object('name',v.name,'creativeVersion',v.creative_version,'surfaces',v.surfaces,'audience',v.audience,'startsAt',v.starts_at,'endsAt',v.ends_at,'frequency',v.frequency,'priority',v.priority,'external',v.external))
 FROM twuanis_canonical_private.campaigns c JOIN twuanis_canonical_private.campaign_configurations v ON v.id=c.current_configuration_id WHERE c.id=cid
$$;


--
-- Name: campaign_status(text, timestamp with time zone, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.campaign_status(s text, b timestamp with time zone, e timestamp with time zone, t timestamp with time zone) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$SELECT CASE WHEN s IN ('draft','ended','archived') THEN s WHEN t>=e THEN 'ended' WHEN s='paused' THEN 'paused' WHEN t<b THEN 'scheduled' ELSE 'active' END$$;


--
-- Name: campaign_target_valid(text, text, timestamp with time zone, boolean); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.campaign_target_valid(kind text, tid text, at_time timestamp with time zone, rendering boolean DEFAULT false) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT CASE kind WHEN 'TWUANIS' THEN tid='twuanis'
 WHEN 'PACKAGE' THEN EXISTS(SELECT 1 FROM twuanis_canonical_private.intelligence_packages WHERE id=tid AND state='active')
 WHEN 'ADD_ON' THEN EXISTS(SELECT 1 FROM twuanis_canonical_private.addon_products WHERE id=tid AND state='active' AND term_kind<>'unconfigured')
 WHEN 'ENGINE' THEN EXISTS(SELECT 1 FROM twuanis_canonical_private.intelligence_capabilities WHERE id=tid)
 WHEN 'OFFER' THEN EXISTS(SELECT 1 FROM twuanis_canonical_private.offers o JOIN twuanis_canonical_private.offer_configurations c ON c.id=o.current_configuration_id WHERE o.id::text=tid AND o.state NOT IN ('ended','archived') AND (NOT rendering OR twuanis_canonical_private.offer_status(o.state,c.starts_at,c.ends_at,at_time)='active') AND twuanis_canonical_private.campaign_target_valid(CASE WHEN o.package_id IS NULL THEN 'ADD_ON' ELSE 'PACKAGE' END,coalesce(o.package_id,o.addon_id),at_time,rendering))
 ELSE false END
$$;


--
-- Name: canonical_origin_ids(text, bigint[]); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.canonical_origin_ids(dim text, ids bigint[]) RETURNS bigint[]
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE expanded bigint[]:=ids;x record;parent record;edge_count integer:=0;
BEGIN
 IF cardinality(ids)>32 THEN RAISE EXCEPTION 'membership set too large' USING ERRCODE='22023'; END IF;
 IF dim<>'geography' THEN
  FOR x IN SELECT id,parent_id FROM public.ontology_terms WHERE id=ANY(ids) ORDER BY id LOOP
   IF x.parent_id IS NOT NULL THEN
    SELECT * INTO STRICT parent FROM public.ontology_terms WHERE id=x.parent_id FOR SHARE;
    IF parent.level IS DISTINCT FROM 0 OR parent.parent_id IS NOT NULL THEN RAISE EXCEPTION 'unsupported non-flat canonical root' USING ERRCODE='23514'; END IF;
    expanded:=array_append(expanded,parent.id);
   END IF;
  END LOOP;
  FOR x IN SELECT target_term_id FROM public.ontology_relationships WHERE source_term_id=ANY(ids) AND relationship_type='is_part_of' LIMIT 65 LOOP
   edge_count:=edge_count+1;
   IF edge_count>64 OR cardinality(expanded)>=96 THEN RAISE EXCEPTION 'membership expansion bound' USING ERRCODE='54000'; END IF;
   SELECT * INTO STRICT parent FROM public.ontology_terms WHERE id=x.target_term_id FOR SHARE;
   IF parent.level IS DISTINCT FROM 0 OR parent.parent_id IS NOT NULL THEN RAISE EXCEPTION 'unsupported non-flat relationship root' USING ERRCODE='23514'; END IF;
   expanded:=array_append(expanded,parent.id);
  END LOOP;
 ELSE
  -- Fixed Costa Rica context, not a user-selectable semantic dimension.
  PERFORM id FROM public.ontology_terms WHERE id=9 AND term_type='country' AND level=0 FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Costa Rica context missing' USING ERRCODE='23514'; END IF;
  expanded:=array_append(expanded,9);
 END IF;
 RETURN expanded;
END $$;


--
-- Name: capacity_state(bigint, bigint); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.capacity_state(p_allowance bigint, p_consumption bigint) RETURNS TABLE(allowance bigint, consumption bigint, remaining bigint, over_capacity bigint, adding_one_exceeds boolean, is_over_capacity boolean, unlimited boolean)
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
 IF p_consumption IS NULL OR p_consumption<0 OR p_allowance<0 THEN
  RAISE EXCEPTION 'invalid capacity numbers' USING ERRCODE='22023';
 END IF;
 allowance:=p_allowance; consumption:=p_consumption; unlimited:=p_allowance IS NULL;
 remaining:=p_allowance-p_consumption;
 over_capacity:=CASE WHEN unlimited THEN 0 ELSE greatest(p_consumption-p_allowance,0) END;
 adding_one_exceeds:=NOT unlimited AND p_consumption>=p_allowance;
 is_over_capacity:=NOT unlimited AND p_consumption>p_allowance;
 RETURN NEXT;
END $$;


--
-- Name: capture_legacy_package_transition(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.capture_legacy_package_transition() RETURNS timestamp with time zone
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE at_time timestamptz;
BEGIN
 IF current_user<>'postgres' THEN RAISE EXCEPTION 'administrative transition required';END IF;
 LOCK TABLE public.user_subscriptions,public.packages,public.package_entitlements,public.entitlements IN SHARE ROW EXCLUSIVE MODE;
 SELECT transitioned_at INTO at_time FROM twuanis_canonical_private.package_access_transition WHERE singleton;
 IF FOUND THEN RETURN at_time;END IF;
 at_time:=clock_timestamp();
 INSERT INTO twuanis_canonical_private.package_access_transition VALUES(true,at_time);
 INSERT INTO twuanis_canonical_private.legacy_package_access
 SELECT s.id,s.user_id,s.package_id,s.current_period_start,s.current_period_end,at_time,
 ARRAY['cap-price-m2-distribution','cap-geographic-price-m2-comparison','cap-size-price-m2','cap-construction-land-price-m2','cap-user-defined-cohort-price-m2-comparison','cap-cross-dimensional-analysis','cap-comparative-price-m2-discovery','cap-property-price-m2-position','cap-user-defined-comparable-cohort','cap-asking-area-coefficient-ratio','cap-weighted-price-m2']::text[]
 FROM public.user_subscriptions s JOIN public.packages p ON p.id=s.package_id
 WHERE p.slug='market-pricing-intelligence' AND s.status='active'
 AND (s.current_period_start IS NULL OR s.current_period_start<=at_time)
 AND s.current_period_end>at_time AND isfinite(s.current_period_end)
 AND s.cancelled_at IS NULL AND s.expired_at IS NULL
 AND EXISTS(SELECT 1 FROM public.package_entitlements pe JOIN public.entitlements e ON e.id=pe.entitlement_id
 WHERE pe.package_id=p.id AND e.slug='price-m2-intelligence' AND e.is_active AND pe.boolean_value IS TRUE);
 RETURN at_time;
END$$;


--
-- Name: change_account_phone(uuid, bigint, text); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.change_account_phone(p_request uuid, p_expected_revision bigint, p_phone text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE u uuid:=twuanis_canonical_private.account_actor(); s twuanis_canonical_private.account_phone_state; receipt twuanis_canonical_private.account_request_receipts; payload jsonb; result jsonb;
BEGIN
 IF p_request IS NULL OR p_expected_revision IS NULL OR p_expected_revision<0 OR (p_phone IS NOT NULL AND p_phone !~ '^\+[1-9][0-9]{1,14}$') THEN RAISE EXCEPTION 'invalid canonical phone command' USING ERRCODE='22023'; END IF;
 PERFORM public.read_account_profile();
 -- Same lock order as profile updates, so the shared receipt namespace is atomic.
 PERFORM 1 FROM twuanis_canonical_private.account_profiles WHERE user_id=u FOR UPDATE;
 SELECT * INTO s FROM twuanis_canonical_private.account_phone_state WHERE user_id=u FOR UPDATE;
 payload:=jsonb_build_object('expectedRevision',p_expected_revision,'phone',p_phone);
 SELECT * INTO receipt FROM twuanis_canonical_private.account_request_receipts WHERE user_id=u AND request_id=p_request;
 IF FOUND THEN
  IF receipt.operation<>'PHONE_CHANGE' OR receipt.input<>payload THEN RAISE EXCEPTION 'request identity conflict' USING ERRCODE='22023'; END IF;
  RETURN receipt.result;
 END IF;
 IF s.revision<>p_expected_revision THEN RAISE EXCEPTION 'phone revision conflict' USING ERRCODE='40001'; END IF;
 IF s.phone_e164 IS DISTINCT FROM p_phone THEN
  UPDATE twuanis_canonical_private.account_phone_state SET phone_e164=p_phone WHERE user_id=u RETURNING * INTO s;
  INSERT INTO twuanis_canonical_private.account_security_events(user_id,kind,request_id,revision) VALUES(u,'PHONE_CHANGED',p_request,s.revision);
 END IF;
 result:=jsonb_build_object('phone',s.phone_e164,'revision',s.revision);
 INSERT INTO twuanis_canonical_private.account_request_receipts(user_id,request_id,operation,input,result) VALUES(u,p_request,'PHONE_CHANGE',payload,result);
 RETURN result;
END $_$;


--
-- Name: claim_contact(text); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.claim_contact(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
 SELECT CASE WHEN p ~ '^[+0-9 ().-]+$' THEN
 CASE WHEN length(regexp_replace(p,'[^0-9]','','g'))=8 THEN '+506'||regexp_replace(p,'[^0-9]','','g')
 WHEN regexp_replace(p,'[^0-9]','','g') ~ '^506[0-9]{8}$' THEN '+'||regexp_replace(p,'[^0-9]','','g') END END
$_$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: listings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.listings (
    created_at timestamp with time zone DEFAULT now(),
    province text,
    canton text,
    district text,
    property_type text,
    property_area numeric,
    utility text[],
    environment text,
    accessibility text,
    terrain text[],
    legal_status text,
    price_millions numeric,
    whatsapp text,
    images text,
    title text,
    description text,
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    bedrooms text,
    bathrooms text,
    parking text,
    year_built_range text,
    construction_area numeric,
    province_normalized text,
    canton_normalized text,
    district_normalized text,
    transaction_type text DEFAULT 'buy'::text NOT NULL,
    monthly_price numeric,
    listing_status text DEFAULT 'active'::text,
    currency text DEFAULT 'CRC'::text NOT NULL,
    source_url text,
    source_name text,
    source_listing_id text,
    current_price numeric,
    previous_price numeric,
    first_seen timestamp with time zone,
    last_seen timestamp with time zone,
    last_scraped timestamp with time zone,
    times_scraped integer DEFAULT 0,
    price_change_count integer DEFAULT 0,
    price_last_changed timestamp with time zone,
    owner_id uuid,
    published_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now(),
    archived_at timestamp with time zone,
    expired_at timestamp with time zone,
    deleted_at timestamp with time zone,
    renewed_at timestamp with time zone,
    listing_origin text NOT NULL,
    listing_source_type text NOT NULL,
    distance_to_paved_road_range text,
    canonical_revision bigint DEFAULT 0 NOT NULL,
    publisher_account_id uuid,
    publication_expires_at timestamp with time zone,
    canonical_domain_version smallint,
    agency_logo_url text,
    listing_agent_photo_url text,
    agency_name text,
    listing_agent_name text,
    CONSTRAINT listings_agency_logo_url_https CHECK (((agency_logo_url IS NULL) OR (agency_logo_url ~ '^https://[^[:space:]]+$'::text))),
    CONSTRAINT listings_canonical_domain_version_check CHECK ((canonical_domain_version = 1)),
    CONSTRAINT listings_canonical_revision_check CHECK ((canonical_revision >= 0)),
    CONSTRAINT listings_listing_agent_photo_url_https CHECK (((listing_agent_photo_url IS NULL) OR (listing_agent_photo_url ~ '^https://[^[:space:]]+$'::text))),
    CONSTRAINT listings_listing_origin_check CHECK ((listing_origin = ANY (ARRAY['customer'::text, 'scraped'::text, 'imported'::text, 'manual'::text, 'system'::text]))),
    CONSTRAINT listings_listing_source_type_check CHECK ((listing_source_type = ANY (ARRAY['customer'::text, 'realtor'::text, 'bank_remate'::text, 'developer'::text, 'brokerage'::text, 'government'::text, 'owner_direct'::text, 'unknown'::text]))),
    CONSTRAINT listings_listing_status_check CHECK ((listing_status = ANY (ARRAY['draft'::text, 'active'::text, 'expired'::text, 'archived'::text, 'deleted'::text])))
);


--
-- Name: claim_eligible(public.listings, text); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.claim_eligible(p public.listings, p_phone text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT p.owner_id IS NULL AND p.publisher_account_id IS NULL AND p.listing_origin='imported'
 AND p.canonical_domain_version=1 AND p.listing_status='active'
 AND p.source_name IS NOT NULL AND p.source_listing_id IS NOT NULL
 AND NOT EXISTS(SELECT 1 FROM public.source_identity_conflicts s WHERE s.listing_id=p.id)
 AND (p.publication_expires_at IS NULL OR p.publication_expires_at>statement_timestamp())
 AND twuanis_canonical_private.claim_contact(p.whatsapp)=p_phone
 AND EXISTS(SELECT 1 FROM twuanis_canonical_private.csv_initial_publication c
 JOIN public.canonical_operation_receipts r ON r.listing_id=c.listing_id AND r.request_id=c.publication_request
 WHERE c.listing_id=p.id AND r.operation_type='domain_mutation' AND r.outcome='succeeded')
$$;


--
-- Name: claim_manual_sinpe_event(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.claim_manual_sinpe_event() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF NEW.disposition IN('APPROVED','RECEIVED_UNMATCHED') THEN INSERT INTO twuanis_canonical_private.sinpe_external_claims VALUES(NEW.receiving_account_id,NEW.bank_reference,'SINPE_REVIEW',NEW.id);END IF;RETURN NEW;END$$;


--
-- Name: commit_entitlement_term(uuid, text, text, uuid, uuid, text, uuid, uuid, uuid, uuid, timestamp with time zone, timestamp with time zone, text, text); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.commit_entitlement_term(p_account uuid, p_class text, p_product text, p_configuration uuid, p_listing uuid, p_source text, p_order uuid, p_ack uuid, p_actor uuid, p_request uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_reason text, p_note text) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE tid uuid:=gen_random_uuid();p twuanis_canonical_private.addon_products%ROWTYPE;
 l public.listings%ROWTYPE;tail timestamptz;ord twuanis_canonical_private.offer_order_snapshots%ROWTYPE;prior twuanis_canonical_private.entitlement_terms%ROWTYPE;bank boolean:=false;v twuanis_canonical_private.package_bank_upgrade_price_versions%ROWTYPE;meta jsonb;at_time timestamptz:=clock_timestamp();
BEGIN
 IF p_account IS NULL OR p_request IS NULL OR p_start IS NULL OR NOT isfinite(p_start) THEN RAISE EXCEPTION 'exact entitlement identities and interval required';END IF;

 IF p_source='RECEIPT_POLICY' THEN
  IF p_class IS DISTINCT FROM 'PACKAGE'OR p_actor IS NOT NULL OR p_ack IS NOT NULL OR p_listing IS NOT NULL OR p_reason IS NOT NULL THEN RAISE EXCEPTION 'exact receipt-policy Package source required';END IF;
  PERFORM pg_advisory_xact_lock(3200,hashtext(p_order::text));
  SELECT * INTO STRICT ord FROM twuanis_canonical_private.offer_order_snapshots WHERE id=p_order AND account_id=p_account AND product_id=p_product AND target_type='package'AND currency='CRC';
  IF ord.resolved_terms->>'paymentExecution'IS DISTINCT FROM'direct_sinpe'OR ord.resolved_terms->>'configurationId'IS DISTINCT FROM p_configuration::text OR NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.direct_sinpe_receipts d JOIN storage.objects f ON f.bucket_id='sinpe-receipts'AND f.name=d.object_path WHERE d.id=p_request AND d.order_id=ord.id AND d.account_id=p_account AND d.receiving_account_id::text=ord.resolved_terms->>'directReceivingAccount'AND twuanis_canonical_private.direct_receipt_timing_valid(d.id,ord.id) AND(d.activation_term_id IS NULL OR d.activation_term_id IN(SELECT id FROM twuanis_canonical_private.entitlement_terms WHERE order_id=ord.id)))THEN RAISE EXCEPTION 'submitted private receipt and pinned direct Order required';END IF;
 IF ord.resolved_terms->'terms'->'capabilities' IS DISTINCT FROM (SELECT to_jsonb(capabilities) FROM twuanis_canonical_private.intelligence_package_configurations WHERE id=p_configuration AND package_id=p_product) OR ord.resolved_terms->'terms'->>'quantity'<>'1' OR ord.resolved_terms->'terms'->>'unit' NOT IN('day','month') THEN RAISE EXCEPTION 'pinned Package terms required';END IF;
  IF ord.resolved_terms->>'orderContractVersion'='2' THEN
   meta:=ord.resolved_terms->'bankUpgrade';
   IF jsonb_typeof(meta) IS DISTINCT FROM 'object' OR jsonb_typeof(meta->'selected') IS DISTINCT FROM 'boolean' OR jsonb_typeof(meta->'amount') IS DISTINCT FROM 'string' OR meta->>'amount' !~ '^[0-9]+(\.[0-9]{1,2})?$' THEN RAISE EXCEPTION 'explicit Bank purchased terms required';END IF;
   IF jsonb_typeof(ord.resolved_terms->'resolvedAt') IS DISTINCT FROM 'string' OR NOT isfinite((ord.resolved_terms->>'resolvedAt')::timestamptz) THEN RAISE EXCEPTION 'finite frozen pricing timestamp required';END IF;
   bank:=(meta->>'selected')::boolean;
   IF bank THEN
    IF ord.resolved_terms->'terms'->>'unit'<>'month' OR jsonb_typeof(meta->'priceVersionId') IS DISTINCT FROM 'string' OR jsonb_typeof(meta->'priceVersion') IS DISTINCT FROM 'number' THEN RAISE EXCEPTION 'monthly versioned Bank evidence required';END IF;
    SELECT * INTO v FROM twuanis_canonical_private.package_bank_upgrade_price_versions WHERE id=(meta->>'priceVersionId')::uuid AND package_id=p_product AND configuration_id=p_configuration AND version=(meta->>'priceVersion')::bigint;
    IF NOT FOUND OR v.effective_from>(ord.resolved_terms->>'resolvedAt')::timestamptz OR (EXISTS(SELECT 1 FROM twuanis_canonical_private.package_bank_upgrade_price_versions n WHERE n.configuration_id=p_configuration AND n.effective_from>v.effective_from AND n.effective_from<=(ord.resolved_terms->>'resolvedAt')::timestamptz) AND NOT twuanis_canonical_private.founder_bank_evidence_valid(p_account,p_product,ord.currency,ord.resolved_terms)) OR (meta->>'amount')::numeric IS DISTINCT FROM (CASE WHEN v.pricing_authority='CRC'THEN CASE ord.currency WHEN 'CRC'THEN v.crc_amount ELSE round(v.crc_amount/(SELECT rate FROM public.fx_rates WHERE base_currency='USD'AND quote_currency='CRC'AND rate_type='reference_sale'AND source='BCCR'AND effective_date<=((ord.resolved_terms->>'resolvedAt')::timestamptz AT TIME ZONE 'America/Costa_Rica')::date ORDER BY effective_date DESC LIMIT 1),2)END ELSE CASE ord.currency WHEN 'USD' THEN v.usd_amount WHEN 'CRC'THEN CASE WHEN ord.resolved_terms?'fx' OR ord.resolved_terms->'base'?'fx'THEN round(v.usd_amount*(SELECT rate FROM public.fx_rates WHERE base_currency='USD'AND quote_currency='CRC'AND rate_type='reference_sale'AND source='BCCR'AND effective_date<=((ord.resolved_terms->>'resolvedAt')::timestamptz AT TIME ZONE 'America/Costa_Rica')::date ORDER BY effective_date DESC LIMIT 1),0)ELSE v.crc_amount END END END) THEN RAISE EXCEPTION 'exact canonical Bank price evidence required';END IF;
   ELSE
    IF (meta->>'amount')::numeric<>0 OR meta->'priceVersionId' IS DISTINCT FROM 'null'::jsonb OR meta->'priceVersion' IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION 'base-only Bank evidence required';END IF;
   END IF;
   IF jsonb_typeof(ord.resolved_terms->'baseTotal') IS DISTINCT FROM 'string' OR jsonb_typeof(ord.resolved_terms->'baseStandardTotal') IS DISTINCT FROM 'string'
    OR (ord.resolved_terms->>'baseTotal')::numeric IS DISTINCT FROM (ord.resolved_terms->>'effectiveRate')::numeric
    OR (ord.resolved_terms->>'baseStandardTotal')::numeric IS DISTINCT FROM (ord.resolved_terms->>'standardRate')::numeric
    OR (ord.resolved_terms->>'total')::numeric IS DISTINCT FROM (ord.resolved_terms->>'baseTotal')::numeric+(meta->>'amount')::numeric
    OR (ord.resolved_terms->>'standardTotal')::numeric IS DISTINCT FROM (ord.resolved_terms->>'baseStandardTotal')::numeric+(meta->>'amount')::numeric THEN RAISE EXCEPTION 'exact complete purchased totals required';END IF;
  ELSIF ord.resolved_terms->>'orderContractVersion'='1' THEN
   IF ord.resolved_terms ? 'bankUpgrade' THEN RAISE EXCEPTION 'legacy Bank evidence forbidden';END IF;
  ELSE RAISE EXCEPTION 'supported purchase contract required';END IF;
 
 ELSE
 IF p_source='PURCHASED' AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_order_snapshots o JOIN twuanis_canonical_private.offer_paid_acknowledgements a ON a.order_id=o.id WHERE o.id=p_order AND a.id=p_ack AND o.account_id=p_account AND o.product_id=p_product AND (o.resolved_terms->>'configurationId')::uuid=p_configuration AND o.listing_id IS NOT DISTINCT FROM p_listing AND o.resolved_terms->>'productClass'=p_class) THEN RAISE EXCEPTION 'exact paid source required';END IF;
 IF p_actor IS NULL AND (p_source<>'PURCHASED' OR NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_paid_acknowledgements WHERE id=p_ack AND(source='onvo'OR(source='stripe'AND twuanis_canonical_private.stripe_paid(p_ack))))) THEN RAISE EXCEPTION 'system execution requires ONVO paid authority';END IF;
 IF p_class='PACKAGE' AND p_source='PURCHASED' THEN
  PERFORM pg_advisory_xact_lock(3200,hashtext(p_order::text));
  SELECT * INTO STRICT ord FROM twuanis_canonical_private.offer_order_snapshots WHERE id=p_order;
  IF ord.target_type<>'package' OR ord.account_id<>p_account OR ord.product_id<>p_product OR (ord.resolved_terms->>'configurationId')::uuid<>p_configuration
  OR NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_paid_acknowledgements a WHERE a.id=p_ack AND a.order_id=p_order AND a.amount=(ord.resolved_terms->>'total')::numeric AND a.currency=ord.currency AND
   ((a.source='sinpe' AND EXISTS(SELECT 1 FROM twuanis_canonical_private.sinpe_review_decisions d WHERE d.acknowledgement_id=a.id AND d.disposition='APPROVED')) OR
    (a.source='onvo' AND EXISTS(SELECT 1 FROM twuanis_canonical_private.onvo_receipts r WHERE r.acknowledgement_id=a.id AND r.disposition='APPROVED')) OR (a.source='stripe'AND twuanis_canonical_private.stripe_paid(a.id)))) THEN RAISE EXCEPTION 'verified complete paid Package required';END IF;
  IF p_actor IS NOT NULL AND (auth.uid() IS DISTINCT FROM p_actor OR auth.jwt()->>'role' IS DISTINCT FROM 'authenticated' OR NOT twuanis_canonical_private.administrative_permission(p_actor,'payments.review')) THEN RAISE EXCEPTION 'canonical issuance authority required' USING ERRCODE='42501';END IF;
  IF ord.resolved_terms->'terms'->'capabilities' IS DISTINCT FROM (SELECT to_jsonb(capabilities) FROM twuanis_canonical_private.intelligence_package_configurations WHERE id=p_configuration AND package_id=p_product) OR ord.resolved_terms->'terms'->>'quantity'<>'1' OR ord.resolved_terms->'terms'->>'unit' NOT IN('day','month') THEN RAISE EXCEPTION 'pinned Package terms required';END IF;
  IF ord.resolved_terms->>'orderContractVersion'='2' THEN
   meta:=ord.resolved_terms->'bankUpgrade';
   IF jsonb_typeof(meta) IS DISTINCT FROM 'object' OR jsonb_typeof(meta->'selected') IS DISTINCT FROM 'boolean' OR jsonb_typeof(meta->'amount') IS DISTINCT FROM 'string' OR meta->>'amount' !~ '^[0-9]+(\.[0-9]{1,2})?$' THEN RAISE EXCEPTION 'explicit Bank purchased terms required';END IF;
   IF jsonb_typeof(ord.resolved_terms->'resolvedAt') IS DISTINCT FROM 'string' OR NOT isfinite((ord.resolved_terms->>'resolvedAt')::timestamptz) THEN RAISE EXCEPTION 'finite frozen pricing timestamp required';END IF;
   bank:=(meta->>'selected')::boolean;
   IF bank THEN
    IF ord.resolved_terms->'terms'->>'unit'<>'month' OR jsonb_typeof(meta->'priceVersionId') IS DISTINCT FROM 'string' OR jsonb_typeof(meta->'priceVersion') IS DISTINCT FROM 'number' THEN RAISE EXCEPTION 'monthly versioned Bank evidence required';END IF;
    SELECT * INTO v FROM twuanis_canonical_private.package_bank_upgrade_price_versions WHERE id=(meta->>'priceVersionId')::uuid AND package_id=p_product AND configuration_id=p_configuration AND version=(meta->>'priceVersion')::bigint;
    IF NOT FOUND OR v.effective_from>(ord.resolved_terms->>'resolvedAt')::timestamptz OR (EXISTS(SELECT 1 FROM twuanis_canonical_private.package_bank_upgrade_price_versions n WHERE n.configuration_id=p_configuration AND n.effective_from>v.effective_from AND n.effective_from<=(ord.resolved_terms->>'resolvedAt')::timestamptz) AND NOT twuanis_canonical_private.founder_bank_evidence_valid(p_account,p_product,ord.currency,ord.resolved_terms)) OR (meta->>'amount')::numeric IS DISTINCT FROM (CASE WHEN v.pricing_authority='CRC'THEN CASE ord.currency WHEN 'CRC'THEN v.crc_amount ELSE round(v.crc_amount/(SELECT rate FROM public.fx_rates WHERE base_currency='USD'AND quote_currency='CRC'AND rate_type='reference_sale'AND source='BCCR'AND effective_date<=((ord.resolved_terms->>'resolvedAt')::timestamptz AT TIME ZONE 'America/Costa_Rica')::date ORDER BY effective_date DESC LIMIT 1),2)END ELSE CASE ord.currency WHEN 'USD' THEN v.usd_amount WHEN 'CRC'THEN CASE WHEN ord.resolved_terms?'fx' OR ord.resolved_terms->'base'?'fx'THEN round(v.usd_amount*(SELECT rate FROM public.fx_rates WHERE base_currency='USD'AND quote_currency='CRC'AND rate_type='reference_sale'AND source='BCCR'AND effective_date<=((ord.resolved_terms->>'resolvedAt')::timestamptz AT TIME ZONE 'America/Costa_Rica')::date ORDER BY effective_date DESC LIMIT 1),0)ELSE v.crc_amount END END END) THEN RAISE EXCEPTION 'exact canonical Bank price evidence required';END IF;
   ELSE
    IF (meta->>'amount')::numeric<>0 OR meta->'priceVersionId' IS DISTINCT FROM 'null'::jsonb OR meta->'priceVersion' IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION 'base-only Bank evidence required';END IF;
   END IF;
   IF jsonb_typeof(ord.resolved_terms->'baseTotal') IS DISTINCT FROM 'string' OR jsonb_typeof(ord.resolved_terms->'baseStandardTotal') IS DISTINCT FROM 'string'
    OR (ord.resolved_terms->>'baseTotal')::numeric IS DISTINCT FROM (ord.resolved_terms->>'effectiveRate')::numeric
    OR (ord.resolved_terms->>'baseStandardTotal')::numeric IS DISTINCT FROM (ord.resolved_terms->>'standardRate')::numeric
    OR (ord.resolved_terms->>'total')::numeric IS DISTINCT FROM (ord.resolved_terms->>'baseTotal')::numeric+(meta->>'amount')::numeric
    OR (ord.resolved_terms->>'standardTotal')::numeric IS DISTINCT FROM (ord.resolved_terms->>'baseStandardTotal')::numeric+(meta->>'amount')::numeric THEN RAISE EXCEPTION 'exact complete purchased totals required';END IF;
  ELSIF ord.resolved_terms->>'orderContractVersion'='1' THEN
   IF ord.resolved_terms ? 'bankUpgrade' THEN RAISE EXCEPTION 'legacy Bank evidence forbidden';END IF;
  ELSE RAISE EXCEPTION 'supported purchase contract required';END IF;
  SELECT * INTO prior FROM twuanis_canonical_private.entitlement_terms WHERE order_id=p_order;
  IF FOUND THEN
   IF prior.account_id<>p_account OR prior.product_id<>p_product OR prior.configuration_id<>p_configuration OR prior.bank_upgrade_selected<>bank OR prior.starts_at IS DISTINCT FROM p_start OR prior.ends_at IS DISTINCT FROM p_end OR prior.acknowledgement_id IS DISTINCT FROM p_ack OR NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.intelligence_package_rights r WHERE r.id=prior.id AND r.account_id=prior.account_id AND r.package_id=prior.product_id AND r.configuration_id=prior.configuration_id AND r.starts_at=prior.starts_at AND r.ends_at=prior.ends_at) THEN RAISE EXCEPTION 'existing complete entitlement conflict';END IF;
   RETURN prior.id;
  END IF;
 END IF;
 IF p_class='PACKAGE' THEN
  PERFORM id FROM twuanis_canonical_private.intelligence_package_configurations WHERE id=p_configuration AND package_id=p_product;
  IF NOT FOUND THEN RAISE EXCEPTION 'canonical package configuration required';END IF;
 ELSE
  SELECT * INTO STRICT p FROM twuanis_canonical_private.addon_products WHERE id=p_product;
  PERFORM id FROM twuanis_canonical_private.addon_configurations WHERE id=p_configuration AND product_id=p_product;
  IF NOT FOUND OR (p_class='LISTING_ADDON' AND p.term_kind<>'elapsed_days') OR (p_class='FOUNDING_MEMBERSHIP' AND p.term_kind<>'lifetime') THEN RAISE EXCEPTION 'canonical entitlement product required';END IF;
  IF p.behavior='homepage_carousel' THEN PERFORM capacity FROM twuanis_canonical_private.addon_homepage_capacity WHERE id FOR UPDATE;END IF;
  IF p_class='LISTING_ADDON' THEN
   SELECT * INTO STRICT l FROM public.listings WHERE id=p_listing FOR UPDATE;
   IF l.owner_id IS DISTINCT FROM p_account OR l.canonical_domain_version IS DISTINCT FROM 1 OR l.listing_status='deleted' THEN RAISE EXCEPTION 'owned canonical target required';END IF;
   IF l.listing_status<>'active' AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.addon_placement_rights WHERE listing_id=p_listing AND product_id=p_product AND effective_intervals @> at_time) THEN RAISE EXCEPTION 'publication required for new placement';END IF;
   -- Append only at commitment. No later operation compacts the committed calendar.
   SELECT max(t.ends_at) INTO tail FROM twuanis_canonical_private.entitlement_terms t WHERE t.listing_id=p_listing AND t.product_id=p_product AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.entitlement_revocations r WHERE r.term_id=t.id);
   IF tail>p_start THEN RAISE EXCEPTION 'interval must follow committed same-product time';END IF;
   IF EXISTS(SELECT 1 FROM twuanis_canonical_private.addon_placement_rights WHERE listing_id=p_listing AND product_id<>p_product AND effective_intervals && tstzmultirange(tstzrange(p_start,p_end,'[)'))) THEN RAISE EXCEPTION 'incompatible add-on interval';END IF;
   IF p.behavior='homepage_carousel' THEN PERFORM twuanis_canonical_private.assert_homepage_interval(p_start,p_end);END IF;
  ELSE
   PERFORM id FROM auth.users WHERE id=p_account FOR UPDATE;
   IF NOT FOUND THEN RAISE EXCEPTION 'recipient required';END IF;
  END IF;
 END IF;
 END IF; -- unchanged verified-payment/admin validation above
 INSERT INTO twuanis_canonical_private.entitlement_terms(id,account_id,product_class,product_id,configuration_id,listing_id,source,order_id,acknowledgement_id,actor_id,request_id,reason,note,starts_at,ends_at,execution_authority,bank_upgrade_selected)
 VALUES(tid,p_account,p_class,p_product,p_configuration,p_listing,p_source,p_order,p_ack,p_actor,p_request,p_reason,p_note,p_start,p_end,CASE WHEN p_source='RECEIPT_POLICY'THEN'RECEIPT_POLICY'WHEN p_actor IS NOT NULL THEN 'HUMAN' WHEN twuanis_canonical_private.stripe_paid(p_ack)THEN 'STRIPE'ELSE 'ONVO'END,bank);
 IF p_class='PACKAGE' THEN
  INSERT INTO twuanis_canonical_private.intelligence_package_rights(id,account_id,package_id,configuration_id,starts_at,ends_at,provenance) VALUES(tid,p_account,p_product,p_configuration,p_start,p_end,p_source||':'||tid::text);
 ELSIF p_class='LISTING_ADDON' THEN PERFORM twuanis_canonical_private.refresh_placement_terms(p_listing,p_product);
 ELSE
  INSERT INTO twuanis_canonical_private.addon_founder_rights(account_id,product_id,configuration_id,activated_at,purchase_id)
  VALUES(p_account,p_product,p_configuration,p_start,p_order)
  ON CONFLICT(account_id) DO UPDATE SET activated_at=(SELECT min(x.starts_at) FROM twuanis_canonical_private.entitlement_terms x WHERE x.account_id=p_account AND x.product_class='FOUNDING_MEMBERSHIP' AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.entitlement_revocations r WHERE r.term_id=x.id)),revoked_at=NULL,purchase_id=coalesce(EXCLUDED.purchase_id,twuanis_canonical_private.addon_founder_rights.purchase_id);
 END IF;
 RETURN tid;
END $_$;


--
-- Name: commit_execution_credit_purchase(uuid, uuid, uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.commit_execution_credit_purchase(p_order uuid, p_ack uuid, p_request uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE o twuanis_canonical_private.offer_order_snapshots%ROWTYPE;a twuanis_canonical_private.offer_paid_acknowledgements%ROWTYPE;old twuanis_canonical_private.execution_credit_receipts%ROWTYPE;q bigint;id uuid;command jsonb;result jsonb;
BEGIN
 IF p_request IS NULL THEN RAISE EXCEPTION 'Trusted payment fulfillment required' USING ERRCODE='42501';END IF;
 PERFORM pg_advisory_xact_lock(3110,1);PERFORM pg_advisory_xact_lock(3200,hashtext(p_order::text));SELECT * INTO STRICT o FROM twuanis_canonical_private.offer_order_snapshots WHERE offer_order_snapshots.id=p_order;
 PERFORM pg_advisory_xact_lock(3512,hashtext(o.account_id::text));PERFORM twuanis_canonical_private.assert_execution_credit_payment(o.id,p_ack);command:=jsonb_build_object('operation','purchase.credit','order',p_order,'ack',p_ack);
 SELECT * INTO old FROM twuanis_canonical_private.execution_credit_receipts WHERE account_id=o.account_id AND request_id=p_request;
 IF FOUND THEN IF old.command IS DISTINCT FROM command THEN RAISE EXCEPTION 'Purchase retry conflict';END IF;PERFORM twuanis_canonical_private.assert_execution_credit_delivery(o.id);RETURN old.result||jsonb_build_object('replayed',true);END IF;
 q:=(o.resolved_terms->>'quantity')::bigint;SELECT * INTO a FROM twuanis_canonical_private.offer_paid_acknowledgements WHERE offer_paid_acknowledgements.id=p_ack AND order_id=o.id AND currency=o.currency AND amount=(o.resolved_terms->>'total')::numeric;
 IF o.target_type<>'execution_credit' OR o.product_id<>'execution-credit-v1' OR o.resolved_terms->>'productClass'IS DISTINCT FROM'EXECUTION_CREDIT' OR o.resolved_terms->>'priceVersion'IS DISTINCT FROM'1' OR q IS NULL OR q NOT IN(2,5,10,20,50) OR o.currency NOT IN('USD','CRC') OR(o.resolved_terms->>'unitPrice')::numeric IS DISTINCT FROM (CASE WHEN o.currency='USD'THEN 1 ELSE CASE WHEN o.resolved_terms?'fx'THEN round((SELECT rate FROM public.fx_rates WHERE base_currency='USD'AND quote_currency='CRC'AND rate_type='reference_sale'AND source='BCCR'AND effective_date<=(o.created_at AT TIME ZONE 'America/Costa_Rica')::date ORDER BY effective_date DESC LIMIT 1),0)ELSE 500 END END) OR(o.resolved_terms->>'total')::numeric IS DISTINCT FROM q*(CASE WHEN o.currency='USD'THEN 1 ELSE CASE WHEN o.resolved_terms?'fx'THEN round((SELECT rate FROM public.fx_rates WHERE base_currency='USD'AND quote_currency='CRC'AND rate_type='reference_sale'AND source='BCCR'AND effective_date<=(o.created_at AT TIME ZONE 'America/Costa_Rica')::date ORDER BY effective_date DESC LIMIT 1),0)ELSE 500 END END) OR a.id IS NULL OR NOT((a.source='stripe'AND twuanis_canonical_private.stripe_paid(a.id))OR(a.source='sinpe'AND EXISTS(SELECT 1 FROM twuanis_canonical_private.sinpe_review_decisions WHERE acknowledgement_id=a.id AND disposition='APPROVED'))OR(a.source='onvo'AND EXISTS(SELECT 1 FROM twuanis_canonical_private.onvo_receipts WHERE acknowledgement_id=a.id AND disposition='APPROVED')))THEN RAISE EXCEPTION 'Exact approved execution-credit payment correspondence required' USING ERRCODE='23514';END IF;
 id:=twuanis_canonical_private.execution_credit_issue(o.account_id,'PURCHASED',q,'ORDER:'||o.id,NULL,NULL,o.id,a.id,o.created_at,NULL,jsonb_build_object('source','APPROVED_PAYMENT','currency',o.currency,'quantity',q,'total',a.amount::text,'provider',a.source,'orderId',o.id,'acknowledgementId',a.id,'priceVersion',1),p_request);PERFORM twuanis_canonical_private.assert_execution_credit_delivery(o.id);result:=jsonb_build_object('allocation',id,'quantity',q::text);
 INSERT INTO twuanis_canonical_private.execution_credit_receipts(account_id,request_id,command,result)VALUES(o.account_id,p_request,command,result);RETURN result||jsonb_build_object('replayed',false);
END$$;


--
-- Name: commit_package_payment_quote(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.commit_package_payment_quote() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE receiver uuid;BEGIN
 IF NEW.target_type='package'THEN
  NEW.resolved_terms:=twuanis_canonical_private.apply_package_payment_quote(NEW.account_id,NEW.product_id,NEW.resolved_terms->'terms'->>'unit',coalesce((NEW.resolved_terms->'bankUpgrade'->>'selected')::boolean,false),NEW.created_at,NEW.resolved_terms);
  IF NEW.currency='CRC'THEN
   IF NOT public.direct_sinpe_ready()THEN RAISE EXCEPTION 'direct SINPE not configured';END IF;
   SELECT id INTO STRICT receiver FROM twuanis_canonical_private.sinpe_receiving_accounts WHERE enabled AND payment_method='direct_sinpe'AND currency='CRC';
   NEW.resolved_terms:=NEW.resolved_terms||jsonb_build_object('paymentMethod','direct_sinpe','paymentExecution','direct_sinpe','directReceivingAccount',receiver::text,'receiptActivationPolicy','direct-sinpe-receipt-access-2026-10-31-v1');
  END IF;
 END IF;RETURN NEW;
END $$;


--
-- Name: create_offer_order_snapshot(uuid, uuid, text, text, text, uuid, uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.create_offer_order_snapshot(p_account uuid, p_request uuid, p_kind text, p_product text, p_currency text, p_listing uuid DEFAULT NULL::uuid, p_job uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE prior twuanis_canonical_private.offer_order_snapshots%ROWTYPE;l public.listings%ROWTYPE;quantity integer:=1;at_time timestamptz;terms jsonb;oid uuid;target_kind text;job_configuration uuid;j twuanis_canonical_private.addon_import_jobs%ROWTYPE;x jsonb;version bigint;standard_tier jsonb;effective_tier jsonb;
BEGIN
 IF p_account IS NULL OR p_request IS NULL OR p_kind IS NULL OR p_kind NOT IN ('package','addon') OR p_product IS NULL OR length(p_product)>150 THEN RAISE EXCEPTION 'trusted bounded identity required'; END IF;
 PERFORM pg_advisory_xact_lock(3162,hashtext(jsonb_build_array(p_account,p_request)::text));
 SELECT * INTO prior FROM twuanis_canonical_private.offer_order_snapshots WHERE account_id=p_account AND request_id=p_request;
 IF FOUND THEN
  IF (prior.target_type,prior.product_id,prior.currency,prior.listing_id,prior.job_id) IS DISTINCT FROM (p_kind,p_product,p_currency,p_listing,p_job) OR coalesce((prior.resolved_terms->'bankUpgrade'->>'selected')::boolean,false) THEN RAISE EXCEPTION 'order replay conflict'; END IF;
  RETURN jsonb_build_object('id',prior.id,'terms',prior.resolved_terms,'createdAt',prior.created_at,'paymentDeadline',prior.payment_deadline,'state',twuanis_canonical_private.offer_order_state(prior.id,clock_timestamp()),'expired',twuanis_canonical_private.offer_order_state(prior.id,clock_timestamp())='expired','replayed',true);
 END IF;
 PERFORM pg_advisory_xact_lock(3161,hashtext(p_kind||':'||p_product));
 IF p_kind='package' THEN
  IF p_listing IS NOT NULL OR p_job IS NOT NULL THEN RAISE EXCEPTION 'package targets account'; END IF;
  PERFORM id FROM twuanis_canonical_private.intelligence_packages WHERE id=p_product FOR SHARE;
  PERFORM package_id FROM twuanis_canonical_private.intelligence_package_prices WHERE package_id=p_product FOR SHARE;
 ELSE
  SELECT target INTO STRICT target_kind FROM twuanis_canonical_private.addon_products WHERE id=p_product FOR SHARE;
  IF target_kind='listing' THEN
   IF p_listing IS NULL OR p_job IS NOT NULL THEN RAISE EXCEPTION 'listing target required'; END IF;
   SELECT * INTO STRICT l FROM public.listings WHERE id=p_listing FOR UPDATE;
   IF l.owner_id IS DISTINCT FROM p_account OR l.canonical_domain_version IS DISTINCT FROM 1 OR l.listing_status IN ('archived','deleted') THEN RAISE EXCEPTION 'owned canonical listing required'; END IF;
   IF EXISTS(SELECT 1 FROM twuanis_canonical_private.addon_products p JOIN twuanis_canonical_private.addon_configurations c ON c.id=p.current_configuration_id WHERE p.id=p_product AND c.placement_market IS NOT NULL AND c.placement_market<>l.transaction_type) THEN RAISE EXCEPTION 'advertising market mismatch';END IF;
 at_time:=clock_timestamp();
   IF EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_order_snapshots s WHERE s.listing_id=p_listing AND (
    ((s.payment_deadline>at_time OR twuanis_canonical_private.sinpe_pending_review(s.id)) AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_paid_acknowledgements a WHERE a.order_id=s.id))
    OR (EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_paid_acknowledgements a WHERE a.order_id=s.id)
     AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.addon_fulfillments f WHERE f.purchase_id=s.id AND f.account_id=s.account_id AND f.product_id=s.product_id AND f.configuration_id=(s.resolved_terms->>'configurationId')::uuid AND f.target_kind='listing' AND f.target_id=s.listing_id AND f.result->>'ok'='true'))
   )) THEN RAISE EXCEPTION 'pending listing acquisition'; END IF;
   IF EXISTS(SELECT 1 FROM twuanis_canonical_private.addon_placement_rights WHERE listing_id=p_listing AND product_id<>p_product AND effective_intervals @> at_time) THEN RAISE EXCEPTION 'incompatible active add-on'; END IF;
   -- Step11: an owned durable canonical draft may acquire an optional Order.
   -- Publication remains a separate prerequisite at trusted fulfillment, not ordering.
  ELSIF target_kind='operation' THEN
   IF p_job IS NULL OR p_listing IS NOT NULL THEN RAISE EXCEPTION 'server-owned job required'; END IF;
   -- Match existing fulfillment lock order: capacity policy -> publisher -> job.
   PERFORM twuanis_canonical_private.lock_capacity_policy(false);
   PERFORM id FROM public.publisher_accounts WHERE owner_user_id=p_account FOR UPDATE;
   SELECT * INTO STRICT j FROM twuanis_canonical_private.addon_import_jobs WHERE id=p_job AND account_id=p_account FOR UPDATE;
   quantity:=j.accepted_count;job_configuration:=j.configuration_id;
   IF EXISTS(SELECT 1 FROM twuanis_canonical_private.addon_import_results WHERE job_id=p_job) THEN RAISE EXCEPTION 'bulk job already fulfilled'; END IF;
   at_time:=clock_timestamp();
   IF EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_order_snapshots o WHERE o.job_id=p_job AND (o.payment_deadline>at_time OR twuanis_canonical_private.sinpe_pending_review(o.id) OR EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_paid_acknowledgements a WHERE a.order_id=o.id))) THEN RAISE EXCEPTION 'bulk acquisition in flight'; END IF;
   IF j.validator_version<>'canonical-customer-v1' OR j.total IS NULL OR j.currency IS DISTINCT FROM p_currency THEN RAISE EXCEPTION 'accepted job unavailable'; END IF;
   -- Revalidate independently; this creates/reserves no listing or capacity.
   LOCK TABLE public.ontology_terms,public.ontology_relationships,twuanis_canonical_private.accessibility_identity IN SHARE MODE;
   FOR x IN SELECT value FROM jsonb_array_elements(j.accepted_rows) LOOP PERFORM twuanis_canonical_private.addon_customer_input(x->'input'); END LOOP;
   PERFORM twuanis_canonical_private.addon_publication_capacity(p_account,quantity);
  ELSE
   IF p_listing IS NOT NULL OR p_job IS NOT NULL THEN RAISE EXCEPTION 'account target required'; END IF;
  END IF;
 END IF;
 at_time:=clock_timestamp();
 terms:=twuanis_canonical_private.resolve_offer_price(p_kind,p_product,p_currency,quantity,at_time);
 IF p_kind IN('addon','package') THEN terms:=twuanis_canonical_private.founder_price(p_account,p_kind,p_product,p_currency,at_time,terms,'PRIVATE');END IF;
 IF terms->>'available' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'no authoritative purchasable price'; END IF;
 IF p_job IS NOT NULL AND job_configuration IS DISTINCT FROM (terms->>'configurationId')::uuid THEN RAISE EXCEPTION 'job configuration is no longer current; new authoritative preflight required'; END IF;
 -- Complete immutable evidence without a second resolver or Order identity.
 IF p_kind='package' THEN SELECT c.version INTO STRICT version FROM twuanis_canonical_private.intelligence_package_configurations c WHERE c.id=(terms->>'configurationId')::uuid;
 ELSE SELECT c.version INTO STRICT version FROM twuanis_canonical_private.addon_configurations c WHERE c.id=(terms->>'configurationId')::uuid; END IF;
 IF p_job IS NOT NULL THEN
  SELECT jsonb_build_object('lower',lower_quantity,'upper',upper_quantity,'unitRate',CASE WHEN p_currency='CRC' AND terms?'fx' THEN terms->>'standardRate' ELSE unit_rate::text END) INTO STRICT standard_tier FROM twuanis_canonical_private.addon_quantity_tiers WHERE configuration_id=job_configuration AND currency=CASE WHEN p_currency='CRC' AND terms?'fx' THEN 'USD' ELSE p_currency END AND quantity BETWEEN lower_quantity AND upper_quantity;
  IF terms->>'source'='OFFER' THEN
   SELECT jsonb_build_object('lower',lower_quantity,'upper',upper_quantity,'unitRate',CASE WHEN p_currency='CRC' AND terms?'fx' THEN terms->>'effectiveRate' ELSE unit_rate::text END) INTO STRICT effective_tier FROM twuanis_canonical_private.offer_quantity_tiers WHERE configuration_id=(terms->>'offerConfigurationId')::uuid AND currency=CASE WHEN p_currency='CRC' AND terms?'fx' THEN 'USD' ELSE p_currency END AND quantity BETWEEN lower_quantity AND upper_quantity;
  ELSE effective_tier:=standard_tier;END IF;
 END IF;
 terms:=terms||jsonb_build_object('orderContractVersion',1,'configurationVersion',version::text,
 'productClass',CASE WHEN p_kind='package' THEN 'PACKAGE' WHEN p_job IS NOT NULL THEN 'BULK_IMPORT' WHEN p_listing IS NOT NULL THEN 'LISTING_ADDON' ELSE 'FOUNDING_MEMBERSHIP' END,
 'targetKind',CASE WHEN p_listing IS NOT NULL THEN 'listing' WHEN p_job IS NOT NULL THEN 'job' ELSE 'account' END,'targetId',coalesce(p_listing,p_job,p_account),
 'standardTotal',((terms->>'standardRate')::numeric*quantity)::text,'standardTier',standard_tier,'purchasedTier',effective_tier,
 'offerVersion',(SELECT c.version::text FROM twuanis_canonical_private.offer_configurations c WHERE c.id=(terms->>'offerConfigurationId')::uuid),
 'acceptedJob',CASE WHEN p_job IS NOT NULL THEN jsonb_build_object('id',j.id,'acceptedQuantity',j.accepted_count,'fingerprint',j.input_fingerprint,'validator',j.validator_version,'publicationEvidence',j.publication_evidence) ELSE NULL END);
 -- Universal V1: every unpaid customer Order has the same 24-hour deadline.
 terms:=terms||jsonb_build_object('currencyQuotes',jsonb_build_object(p_currency,jsonb_build_object('total',terms->>'total','source',terms->>'source'),CASE p_currency WHEN 'USD'THEN 'CRC'ELSE 'USD'END,
 twuanis_canonical_private.founder_price(p_account,p_kind,p_product,CASE p_currency WHEN 'USD'THEN 'CRC'ELSE 'USD'END,at_time,twuanis_canonical_private.resolve_offer_price(p_kind,p_product,CASE p_currency WHEN 'USD'THEN 'CRC'ELSE 'USD'END,quantity,at_time),'PRIVATE')));
 INSERT INTO twuanis_canonical_private.offer_order_snapshots(account_id,request_id,target_type,product_id,listing_id,job_id,currency,resolved_terms,created_at,payment_deadline)
 VALUES(p_account,p_request,p_kind,p_product,p_listing,p_job,p_currency,terms,at_time,at_time+interval '24 hours') RETURNING id INTO oid;
 RETURN jsonb_build_object('id',oid,'terms',terms,'createdAt',at_time,'paymentDeadline',at_time+interval '24 hours','expired',false,'replayed',false);
END $$;


--
-- Name: create_offer_order_snapshot(uuid, uuid, text, text, text, uuid, uuid, boolean); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.create_offer_order_snapshot(p_account uuid, p_request uuid, p_kind text, p_product text, p_currency text, p_listing uuid, p_job uuid, p_bank_upgrade boolean) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE prior twuanis_canonical_private.offer_order_snapshots%ROWTYPE;l public.listings%ROWTYPE;quantity integer:=1;at_time timestamptz;terms jsonb;oid uuid;target_kind text;job_configuration uuid;j twuanis_canonical_private.addon_import_jobs%ROWTYPE;x jsonb;version bigint;standard_tier jsonb;effective_tier jsonb;composed jsonb;
BEGIN
 IF p_bank_upgrade IS NULL OR (p_kind<>'package' AND p_bank_upgrade) THEN RAISE EXCEPTION 'typed Package Bank selection required';END IF;
 IF p_account IS NULL OR p_request IS NULL OR p_kind IS NULL OR p_kind NOT IN ('package','addon') OR p_product IS NULL OR length(p_product)>150 THEN RAISE EXCEPTION 'trusted bounded identity required'; END IF;
 PERFORM pg_advisory_xact_lock(3162,hashtext(jsonb_build_array(p_account,p_request)::text));
 SELECT * INTO prior FROM twuanis_canonical_private.offer_order_snapshots WHERE account_id=p_account AND request_id=p_request;
 IF FOUND THEN
  IF (prior.target_type,prior.product_id,prior.currency,prior.listing_id,prior.job_id) IS DISTINCT FROM (p_kind,p_product,p_currency,p_listing,p_job) OR coalesce((prior.resolved_terms->'bankUpgrade'->>'selected')::boolean,false) IS DISTINCT FROM p_bank_upgrade OR (p_kind='package' AND prior.resolved_terms->'terms'->>'unit' IS DISTINCT FROM 'month') THEN RAISE EXCEPTION 'order replay conflict'; END IF;
  RETURN jsonb_build_object('id',prior.id,'terms',prior.resolved_terms,'createdAt',prior.created_at,'paymentDeadline',prior.payment_deadline,'state',twuanis_canonical_private.offer_order_state(prior.id,clock_timestamp()),'expired',twuanis_canonical_private.offer_order_state(prior.id,clock_timestamp())='expired','replayed',true);
 END IF;
 PERFORM pg_advisory_xact_lock(3161,hashtext(p_kind||':'||p_product));
 IF p_kind='package' THEN
  IF p_listing IS NOT NULL OR p_job IS NOT NULL THEN RAISE EXCEPTION 'package targets account'; END IF;
  PERFORM id FROM twuanis_canonical_private.intelligence_packages WHERE id=p_product FOR SHARE;
  PERFORM package_id FROM twuanis_canonical_private.intelligence_package_prices WHERE package_id=p_product FOR SHARE;
 ELSE
  SELECT target INTO STRICT target_kind FROM twuanis_canonical_private.addon_products WHERE id=p_product FOR SHARE;
  IF target_kind='listing' THEN
   IF p_listing IS NULL OR p_job IS NOT NULL THEN RAISE EXCEPTION 'listing target required'; END IF;
   SELECT * INTO STRICT l FROM public.listings WHERE id=p_listing FOR UPDATE;
   IF l.owner_id IS DISTINCT FROM p_account OR l.canonical_domain_version IS DISTINCT FROM 1 OR l.listing_status IN ('archived','deleted') THEN RAISE EXCEPTION 'owned canonical listing required'; END IF;
   at_time:=clock_timestamp();
   IF EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_order_snapshots s WHERE s.listing_id=p_listing AND (
    ((s.payment_deadline>at_time OR twuanis_canonical_private.sinpe_pending_review(s.id)) AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_paid_acknowledgements a WHERE a.order_id=s.id))
    OR (EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_paid_acknowledgements a WHERE a.order_id=s.id)
     AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.addon_fulfillments f WHERE f.purchase_id=s.id AND f.account_id=s.account_id AND f.product_id=s.product_id AND f.configuration_id=(s.resolved_terms->>'configurationId')::uuid AND f.target_kind='listing' AND f.target_id=s.listing_id AND f.result->>'ok'='true'))
   )) THEN RAISE EXCEPTION 'pending listing acquisition'; END IF;
   IF EXISTS(SELECT 1 FROM twuanis_canonical_private.addon_placement_rights WHERE listing_id=p_listing AND product_id<>p_product AND effective_intervals @> at_time) THEN RAISE EXCEPTION 'incompatible active add-on'; END IF;
   -- Step11: an owned durable canonical draft may acquire an optional Order.
   -- Publication remains a separate prerequisite at trusted fulfillment, not ordering.
  ELSIF target_kind='operation' THEN
   IF p_job IS NULL OR p_listing IS NOT NULL THEN RAISE EXCEPTION 'server-owned job required'; END IF;
   -- Match existing fulfillment lock order: capacity policy -> publisher -> job.
   PERFORM twuanis_canonical_private.lock_capacity_policy(false);
   PERFORM id FROM public.publisher_accounts WHERE owner_user_id=p_account FOR UPDATE;
   SELECT * INTO STRICT j FROM twuanis_canonical_private.addon_import_jobs WHERE id=p_job AND account_id=p_account FOR UPDATE;
   quantity:=j.accepted_count;job_configuration:=j.configuration_id;
   IF EXISTS(SELECT 1 FROM twuanis_canonical_private.addon_import_results WHERE job_id=p_job) THEN RAISE EXCEPTION 'bulk job already fulfilled'; END IF;
   at_time:=clock_timestamp();
   IF EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_order_snapshots o WHERE o.job_id=p_job AND (o.payment_deadline>at_time OR twuanis_canonical_private.sinpe_pending_review(o.id) OR EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_paid_acknowledgements a WHERE a.order_id=o.id))) THEN RAISE EXCEPTION 'bulk acquisition in flight'; END IF;
   IF j.validator_version<>'canonical-customer-v1' OR j.total IS NULL OR j.currency IS DISTINCT FROM p_currency THEN RAISE EXCEPTION 'accepted job unavailable'; END IF;
   -- Revalidate independently; this creates/reserves no listing or capacity.
   LOCK TABLE public.ontology_terms,public.ontology_relationships,twuanis_canonical_private.accessibility_identity IN SHARE MODE;
   FOR x IN SELECT value FROM jsonb_array_elements(j.accepted_rows) LOOP PERFORM twuanis_canonical_private.addon_customer_input(x->'input'); END LOOP;
   PERFORM twuanis_canonical_private.addon_publication_capacity(p_account,quantity);
  ELSE
   IF p_listing IS NOT NULL OR p_job IS NOT NULL THEN RAISE EXCEPTION 'account target required'; END IF;
  END IF;
 END IF;
 at_time:=clock_timestamp();
 IF p_kind='package' THEN
 composed:=twuanis_canonical_private.resolve_package_bank_upgrade_price(p_product,p_currency,'month',p_bank_upgrade,at_time);composed:=twuanis_canonical_private.founder_composed_price(p_account,p_product,p_currency,at_time,composed,p_bank_upgrade);terms:=composed->'base';
 ELSE terms:=twuanis_canonical_private.founder_price(p_account,p_kind,p_product,p_currency,at_time,twuanis_canonical_private.resolve_offer_price(p_kind,p_product,p_currency,quantity,at_time),'PRIVATE');END IF;
 IF terms->>'available' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'no authoritative purchasable price'; END IF;
 IF p_job IS NOT NULL AND job_configuration IS DISTINCT FROM (terms->>'configurationId')::uuid THEN RAISE EXCEPTION 'job configuration is no longer current; new authoritative preflight required'; END IF;
 -- Complete immutable evidence without a second resolver or Order identity.
 IF p_kind='package' THEN SELECT c.version INTO STRICT version FROM twuanis_canonical_private.intelligence_package_configurations c WHERE c.id=(terms->>'configurationId')::uuid;
 ELSE SELECT c.version INTO STRICT version FROM twuanis_canonical_private.addon_configurations c WHERE c.id=(terms->>'configurationId')::uuid; END IF;
 IF p_job IS NOT NULL THEN
  SELECT jsonb_build_object('lower',lower_quantity,'upper',upper_quantity,'unitRate',unit_rate::text) INTO STRICT standard_tier FROM twuanis_canonical_private.addon_quantity_tiers WHERE configuration_id=job_configuration AND currency=p_currency AND quantity BETWEEN lower_quantity AND upper_quantity;
  IF terms->>'source'='OFFER' THEN
   SELECT jsonb_build_object('lower',lower_quantity,'upper',upper_quantity,'unitRate',unit_rate::text) INTO STRICT effective_tier FROM twuanis_canonical_private.offer_quantity_tiers WHERE configuration_id=(terms->>'offerConfigurationId')::uuid AND currency=p_currency AND quantity BETWEEN lower_quantity AND upper_quantity;
  ELSE effective_tier:=standard_tier;END IF;
 END IF;
 terms:=terms||jsonb_build_object('orderContractVersion',1,'configurationVersion',version::text,
 'productClass',CASE WHEN p_kind='package' THEN 'PACKAGE' WHEN p_job IS NOT NULL THEN 'BULK_IMPORT' WHEN p_listing IS NOT NULL THEN 'LISTING_ADDON' ELSE 'FOUNDING_MEMBERSHIP' END,
 'targetKind',CASE WHEN p_listing IS NOT NULL THEN 'listing' WHEN p_job IS NOT NULL THEN 'job' ELSE 'account' END,'targetId',coalesce(p_listing,p_job,p_account),
 'standardTotal',((terms->>'standardRate')::numeric*quantity)::text,'standardTier',standard_tier,'purchasedTier',effective_tier,
 'offerVersion',(SELECT c.version::text FROM twuanis_canonical_private.offer_configurations c WHERE c.id=(terms->>'offerConfigurationId')::uuid),
 'acceptedJob',CASE WHEN p_job IS NOT NULL THEN jsonb_build_object('id',j.id,'acceptedQuantity',j.accepted_count,'fingerprint',j.input_fingerprint,'validator',j.validator_version,'publicationEvidence',j.publication_evidence) ELSE NULL END);
 IF p_kind='package' THEN terms:=terms||jsonb_build_object('orderContractVersion',2,'bankUpgrade',composed->'bankUpgrade','baseTotal',composed->>'baseTotal','baseStandardTotal',(terms->>'standardRate'),'total',composed->>'total','standardTotal',composed->>'standardTotal');END IF;
 -- Universal V1: every unpaid customer Order has the same 24-hour deadline.
 terms:=terms||jsonb_build_object('currencyQuotes',jsonb_build_object(p_currency,jsonb_build_object('total',terms->>'total'),CASE p_currency WHEN 'USD'THEN 'CRC'ELSE 'USD'END,
 CASE WHEN p_kind='package' THEN jsonb_build_object('total',(twuanis_canonical_private.founder_composed_price(p_account,p_product,CASE p_currency WHEN 'USD'THEN 'CRC'ELSE 'USD'END,at_time,twuanis_canonical_private.resolve_package_bank_upgrade_price(p_product,CASE p_currency WHEN 'USD'THEN 'CRC'ELSE 'USD'END,'month',p_bank_upgrade,at_time),p_bank_upgrade))->>'total')
 ELSE twuanis_canonical_private.founder_price(p_account,p_kind,p_product,CASE p_currency WHEN 'USD'THEN 'CRC'ELSE 'USD'END,at_time,twuanis_canonical_private.resolve_offer_price(p_kind,p_product,CASE p_currency WHEN 'USD'THEN 'CRC'ELSE 'USD'END,quantity,at_time),'PRIVATE')END));
 INSERT INTO twuanis_canonical_private.offer_order_snapshots(account_id,request_id,target_type,product_id,listing_id,job_id,currency,resolved_terms,created_at,payment_deadline)
 VALUES(p_account,p_request,p_kind,p_product,p_listing,p_job,p_currency,terms,at_time,at_time+interval '24 hours') RETURNING id INTO oid;
 RETURN jsonb_build_object('id',oid,'terms',terms,'createdAt',at_time,'paymentDeadline',at_time+interval '24 hours','expired',false,'replayed',false);
END $$;


--
-- Name: create_offer_order_snapshot(uuid, uuid, text, text, text, uuid, uuid, integer); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.create_offer_order_snapshot(p_account uuid, p_request uuid, p_kind text, p_product text, p_currency text, p_listing uuid, p_job uuid, p_quantity integer) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$DECLARE old twuanis_canonical_private.offer_order_snapshots%ROWTYPE;terms jsonb;at_time timestamptz;oid uuid;BEGIN
 IF p_kind IS DISTINCT FROM'execution_credit'THEN IF p_quantity IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'Original scalar quantity required';END IF;RETURN twuanis_canonical_private.create_offer_order_snapshot(p_account,p_request,p_kind,p_product,p_currency,p_listing,p_job);END IF;
 IF p_account IS NULL OR p_request IS NULL OR p_listing IS NOT NULL OR p_job IS NOT NULL OR p_product IS DISTINCT FROM'execution-credit-v1'OR p_quantity IS NULL OR p_quantity NOT IN(2,5,10,20,50)OR p_currency IS NULL OR p_currency NOT IN('USD','CRC')THEN RAISE EXCEPTION 'Exact token order intent required';END IF;
 PERFORM pg_advisory_xact_lock(3162,hashtext(jsonb_build_array(p_account,p_request)::text));SELECT * INTO old FROM twuanis_canonical_private.offer_order_snapshots WHERE account_id=p_account AND request_id=p_request;
 IF FOUND THEN IF old.target_type<>p_kind OR old.product_id<>p_product OR old.currency<>p_currency OR(old.resolved_terms->>'quantity')::integer<>p_quantity OR old.listing_id IS NOT NULL OR old.job_id IS NOT NULL THEN RAISE EXCEPTION 'Order replay conflict';END IF;RETURN jsonb_build_object('id',old.id,'replayed',true);END IF;
 at_time:=clock_timestamp();terms:=twuanis_canonical_private.resolve_offer_price(p_kind,p_product,p_currency,p_quantity,at_time);IF terms IS NULL OR terms->>'available'IS DISTINCT FROM'true'THEN RAISE EXCEPTION 'Token price unavailable';END IF;terms:=terms||jsonb_build_object('currencyQuotes',jsonb_build_object(p_currency,jsonb_build_object('total',terms->>'total'),CASE p_currency WHEN 'USD'THEN 'CRC'ELSE 'USD'END,jsonb_build_object('total',twuanis_canonical_private.resolve_offer_price(p_kind,p_product,CASE p_currency WHEN 'USD'THEN 'CRC'ELSE 'USD'END,p_quantity,at_time)->>'total')));
 INSERT INTO twuanis_canonical_private.offer_order_snapshots(account_id,request_id,target_type,product_id,currency,resolved_terms,created_at,payment_deadline)VALUES(p_account,p_request,p_kind,p_product,p_currency,terms,at_time,at_time+interval'24 hours')RETURNING id INTO oid;RETURN jsonb_build_object('id',oid,'replayed',false);
END$$;


--
-- Name: create_package_access_order(uuid, uuid, text, text, text); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.create_package_access_order(p_account uuid, p_request uuid, p_product text, p_currency text, p_duration text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE usd_amount numeric;prior twuanis_canonical_private.offer_order_snapshots%ROWTYPE;cfg twuanis_canonical_private.intelligence_package_configurations%ROWTYPE;d twuanis_canonical_private.package_daily_access_prices%ROWTYPE;terms jsonb;oid uuid;at_time timestamptz;
BEGIN
 IF p_account IS NULL OR p_request IS NULL OR p_duration IS NULL OR p_duration NOT IN('day','month') THEN RAISE EXCEPTION 'explicit purchase identity required';END IF;
 PERFORM pg_advisory_xact_lock(3162,hashtext(p_account::text||p_request::text));
 SELECT * INTO prior FROM twuanis_canonical_private.offer_order_snapshots WHERE account_id=p_account AND request_id=p_request;
 IF FOUND THEN
 IF prior.target_type<>'package' OR prior.product_id IS DISTINCT FROM p_product OR prior.currency IS DISTINCT FROM p_currency OR prior.resolved_terms->'terms'->>'unit' IS DISTINCT FROM p_duration OR coalesce((prior.resolved_terms->'bankUpgrade'->>'selected')::boolean,false) THEN RAISE EXCEPTION 'purchase request conflict';END IF;
 RETURN jsonb_build_object('id',prior.id,'terms',prior.resolved_terms,'replayed',true);END IF;
 IF p_duration='month' THEN RETURN twuanis_canonical_private.create_offer_order_snapshot(p_account,p_request,'package',p_product,p_currency,NULL,NULL);END IF;
 SELECT * INTO STRICT d FROM twuanis_canonical_private.package_daily_access_prices WHERE package_id=p_product AND currency=CASE WHEN p_product='pkg-matching-market-comparison' AND p_currency='CRC' THEN 'CRC' ELSE 'USD' END ORDER BY version DESC LIMIT 1;usd_amount:=CASE WHEN p_product='pkg-matching-market-comparison' AND p_currency='CRC' THEN (SELECT amount FROM twuanis_canonical_private.package_daily_access_prices WHERE package_id=p_product AND currency='USD' ORDER BY version DESC LIMIT 1) ELSE d.amount END;
 SELECT c.* INTO STRICT cfg FROM twuanis_canonical_private.intelligence_packages p JOIN twuanis_canonical_private.intelligence_package_configurations c ON c.id=p.current_configuration_id AND c.package_id=p.id WHERE p.id=p_product AND p.state='active' FOR SHARE OF p;
 at_time:=clock_timestamp();IF p_currency='CRC' AND NOT(p_product='pkg-matching-market-comparison' AND d.currency='CRC' AND d.version=2)THEN d.amount:=round(d.amount*(SELECT rate FROM public.fx_rates WHERE base_currency='USD'AND quote_currency='CRC'AND rate_type='reference_sale'AND source='BCCR'AND effective_date<=(at_time AT TIME ZONE 'America/Costa_Rica')::date ORDER BY effective_date DESC LIMIT 1),0);IF d.amount IS NULL OR d.amount<=0 THEN RAISE EXCEPTION 'BCCR daily price unavailable';END IF;END IF;
 terms:=jsonb_build_object('available',true,'kind','package','productId',p_product,'currency',p_currency,'quantity',1,'source','STANDARD','standardRate',d.amount::text,'unitPrice',d.amount::text,'total',d.amount::text,'standardTotal',d.amount::text,'configurationId',cfg.id,'configurationVersion',cfg.version::text,'orderContractVersion',1,'productClass','PACKAGE','targetKind','account','targetId',p_account,'purchaseOption','day','purchaseOptionVersion',d.version,'terms',jsonb_build_object('quantity',1,'unit','day','capabilities',cfg.capabilities));
 terms:=terms||jsonb_build_object('currencyQuotes',jsonb_build_object('USD',jsonb_build_object('total',usd_amount::text),'CRC',jsonb_build_object('total',round(usd_amount*(SELECT rate FROM public.fx_rates WHERE base_currency='USD'AND quote_currency='CRC'AND rate_type='reference_sale'AND source='BCCR'AND effective_date<=(at_time AT TIME ZONE 'America/Costa_Rica')::date ORDER BY effective_date DESC LIMIT 1),0)::text)));IF p_currency='CRC'THEN terms:=terms||jsonb_build_object('fx',jsonb_build_object('rate',(SELECT rate FROM public.fx_rates WHERE base_currency='USD'AND quote_currency='CRC'AND rate_type='reference_sale'AND source='BCCR'AND effective_date<=(at_time AT TIME ZONE 'America/Costa_Rica')::date ORDER BY effective_date DESC LIMIT 1),'source','BCCR','rateType','reference_sale'));END IF;
 IF p_product='pkg-matching-market-comparison' AND p_currency='CRC' AND d.currency='CRC' AND d.version=2 THEN terms:=(terms-'fx')||jsonb_build_object('pricingAuthority','CRC','currencyQuotes',jsonb_build_object('USD',jsonb_build_object('total',usd_amount::text),'CRC',jsonb_build_object('total',d.amount::text))); END IF;
 INSERT INTO twuanis_canonical_private.offer_order_snapshots(account_id,request_id,target_type,product_id,currency,resolved_terms,created_at,payment_deadline) VALUES(p_account,p_request,'package',p_product,p_currency,terms,at_time,at_time+interval '24 hours') RETURNING id INTO oid;
 RETURN jsonb_build_object('id',oid,'terms',terms,'createdAt',at_time,'paymentDeadline',at_time+interval '24 hours','replayed',false);
END$$;


--
-- Name: create_package_access_order(uuid, uuid, text, text, text, boolean); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.create_package_access_order(p_account uuid, p_request uuid, p_product text, p_currency text, p_duration text, p_bank_upgrade boolean) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE usd_amount numeric;prior twuanis_canonical_private.offer_order_snapshots%ROWTYPE;cfg twuanis_canonical_private.intelligence_package_configurations%ROWTYPE;d twuanis_canonical_private.package_daily_access_prices%ROWTYPE;terms jsonb;oid uuid;at_time timestamptz;
BEGIN
 IF p_bank_upgrade IS NULL OR p_currency IS NULL OR p_currency NOT IN('USD','CRC') OR (p_duration='day' AND p_bank_upgrade) THEN RAISE EXCEPTION 'typed monthly Bank selection required';END IF;
 IF p_account IS NULL OR p_request IS NULL OR p_duration IS NULL OR p_duration NOT IN('day','month') THEN RAISE EXCEPTION 'explicit purchase identity required';END IF;
 PERFORM pg_advisory_xact_lock(3162,hashtext(p_account::text||p_request::text));
 SELECT * INTO prior FROM twuanis_canonical_private.offer_order_snapshots WHERE account_id=p_account AND request_id=p_request;
 IF FOUND THEN
 IF prior.target_type<>'package' OR prior.product_id IS DISTINCT FROM p_product OR prior.currency IS DISTINCT FROM p_currency OR prior.resolved_terms->'terms'->>'unit' IS DISTINCT FROM p_duration OR coalesce((prior.resolved_terms->'bankUpgrade'->>'selected')::boolean,false) IS DISTINCT FROM p_bank_upgrade THEN RAISE EXCEPTION 'purchase request conflict';END IF;
 RETURN jsonb_build_object('id',prior.id,'terms',prior.resolved_terms,'replayed',true);END IF;
 IF p_duration='month' THEN RETURN twuanis_canonical_private.create_offer_order_snapshot(p_account,p_request,'package',p_product,p_currency,NULL,NULL,p_bank_upgrade);END IF;
 SELECT * INTO STRICT d FROM twuanis_canonical_private.package_daily_access_prices WHERE package_id=p_product AND currency=CASE WHEN p_product='pkg-matching-market-comparison' AND p_currency='CRC' THEN 'CRC' ELSE 'USD' END ORDER BY version DESC LIMIT 1;usd_amount:=CASE WHEN p_product='pkg-matching-market-comparison' AND p_currency='CRC' THEN (SELECT amount FROM twuanis_canonical_private.package_daily_access_prices WHERE package_id=p_product AND currency='USD' ORDER BY version DESC LIMIT 1) ELSE d.amount END;
 SELECT c.* INTO STRICT cfg FROM twuanis_canonical_private.intelligence_packages p JOIN twuanis_canonical_private.intelligence_package_configurations c ON c.id=p.current_configuration_id AND c.package_id=p.id WHERE p.id=p_product AND p.state='active' FOR SHARE OF p;
 at_time:=clock_timestamp();IF p_currency='CRC' AND NOT(p_product='pkg-matching-market-comparison' AND d.currency='CRC' AND d.version=2)THEN d.amount:=round(d.amount*(SELECT rate FROM public.fx_rates WHERE base_currency='USD'AND quote_currency='CRC'AND rate_type='reference_sale'AND source='BCCR'AND effective_date<=(at_time AT TIME ZONE 'America/Costa_Rica')::date ORDER BY effective_date DESC LIMIT 1),0);IF d.amount IS NULL OR d.amount<=0 THEN RAISE EXCEPTION 'BCCR daily price unavailable';END IF;END IF;
 terms:=jsonb_build_object('available',true,'kind','package','productId',p_product,'currency',p_currency,'quantity',1,'source','STANDARD','standardRate',d.amount::text,'unitPrice',d.amount::text,'total',d.amount::text,'standardTotal',d.amount::text,'configurationId',cfg.id,'configurationVersion',cfg.version::text,'orderContractVersion',1,'productClass','PACKAGE','targetKind','account','targetId',p_account,'purchaseOption','day','purchaseOptionVersion',d.version,'terms',jsonb_build_object('quantity',1,'unit','day','capabilities',cfg.capabilities));
 terms:=terms||jsonb_build_object('currencyQuotes',jsonb_build_object('USD',jsonb_build_object('total',usd_amount::text),'CRC',jsonb_build_object('total',round(usd_amount*(SELECT rate FROM public.fx_rates WHERE base_currency='USD'AND quote_currency='CRC'AND rate_type='reference_sale'AND source='BCCR'AND effective_date<=(at_time AT TIME ZONE 'America/Costa_Rica')::date ORDER BY effective_date DESC LIMIT 1),0)::text)));IF p_currency='CRC'THEN terms:=terms||jsonb_build_object('fx',jsonb_build_object('rate',(SELECT rate FROM public.fx_rates WHERE base_currency='USD'AND quote_currency='CRC'AND rate_type='reference_sale'AND source='BCCR'AND effective_date<=(at_time AT TIME ZONE 'America/Costa_Rica')::date ORDER BY effective_date DESC LIMIT 1),'source','BCCR','rateType','reference_sale'));END IF;
 IF p_product='pkg-matching-market-comparison' AND p_currency='CRC' AND d.currency='CRC' AND d.version=2 THEN terms:=(terms-'fx')||jsonb_build_object('pricingAuthority','CRC','currencyQuotes',jsonb_build_object('USD',jsonb_build_object('total',usd_amount::text),'CRC',jsonb_build_object('total',d.amount::text))); END IF;
 INSERT INTO twuanis_canonical_private.offer_order_snapshots(account_id,request_id,target_type,product_id,currency,resolved_terms,created_at,payment_deadline) VALUES(p_account,p_request,'package',p_product,p_currency,terms,at_time,at_time+interval '24 hours') RETURNING id INTO oid;
 RETURN jsonb_build_object('id',oid,'terms',terms,'createdAt',at_time,'paymentDeadline',at_time+interval '24 hours','replayed',false);
END$$;


--
-- Name: customer_email_guard(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.customer_email_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF(NEW.id,NEW.event_key,NEW.account_id,NEW.template,NEW.template_version,NEW.event_revision,NEW.entity_kind,NEW.entity_id,NEW.occurred_at,NEW.payload,NEW.created_at) IS DISTINCT FROM(OLD.id,OLD.event_key,OLD.account_id,OLD.template,OLD.template_version,OLD.event_revision,OLD.entity_kind,OLD.entity_id,OLD.occurred_at,OLD.payload,OLD.created_at) OR(OLD.envelope IS NOT NULL AND NEW.envelope IS DISTINCT FROM OLD.envelope) OR(OLD.provider_message IS NOT NULL AND NEW.provider_message IS DISTINCT FROM OLD.provider_message) OR(OLD.first_attempt IS NOT NULL AND NEW.first_attempt IS DISTINCT FROM OLD.first_attempt) THEN RAISE EXCEPTION 'immutable customer email evidence';END IF;RETURN NEW;END$$;


--
-- Name: customer_email_product(text, text, uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.customer_email_product(p_class text, p_id text, p_config uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT CASE WHEN p_class='PACKAGE' THEN(SELECT jsonb_build_object('productId',p.id,'nameEn',p.name_en,'nameEs',p.name_es,'capabilities',c.capabilities,'capabilityNamesEn',(SELECT jsonb_agg(k.name_en ORDER BY k.id)FROM twuanis_canonical_private.intelligence_capabilities k WHERE k.id=ANY(c.capabilities)),'capabilityNamesEs',(SELECT jsonb_agg(coalesce(k.name_es,k.name_en)ORDER BY k.id)FROM twuanis_canonical_private.intelligence_capabilities k WHERE k.id=ANY(c.capabilities)))FROM twuanis_canonical_private.intelligence_packages p JOIN twuanis_canonical_private.intelligence_package_configurations c ON c.package_id=p.id WHERE p.id=p_id AND c.id=p_config)
 ELSE(SELECT jsonb_build_object('productId',p.id,'nameEn',p.name_en,'nameEs',p.name_es,'placement',p.behavior)FROM twuanis_canonical_private.addon_products p WHERE p.id=p_id)END;
$$;


--
-- Name: customer_email_provider_state(text); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.customer_email_provider_state(p_message text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT CASE kind WHEN 'email.complained' THEN 'COMPLAINED'WHEN 'email.bounced' THEN 'BOUNCED'WHEN 'email.failed' THEN 'FAILED'WHEN 'email.suppressed' THEN 'FAILED'WHEN 'email.delivered' THEN 'DELIVERED'ELSE 'ACCEPTED'END FROM twuanis_canonical_private.customer_email_provider_events WHERE provider_message=p_message ORDER BY CASE kind WHEN 'email.complained' THEN 5 WHEN 'email.bounced' THEN 4 WHEN 'email.failed' THEN 3 WHEN 'email.suppressed' THEN 3 WHEN 'email.delivered' THEN 2 ELSE 1 END DESC,occurred_at DESC LIMIT 1;
$$;


--
-- Name: entitlement_terms; Type: TABLE; Schema: twuanis_canonical_private; Owner: -
--

CREATE TABLE twuanis_canonical_private.entitlement_terms (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    product_class text NOT NULL,
    product_id text NOT NULL,
    configuration_id uuid NOT NULL,
    listing_id uuid,
    source text NOT NULL,
    order_id uuid,
    acknowledgement_id uuid,
    actor_id uuid,
    request_id uuid NOT NULL,
    reason text,
    note text,
    starts_at timestamp with time zone NOT NULL,
    ends_at timestamp with time zone,
    committed_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    execution_authority text DEFAULT 'HUMAN'::text NOT NULL,
    bank_upgrade_selected boolean DEFAULT false NOT NULL,
    CONSTRAINT bank_upgrade_purchased_package CHECK (((NOT bank_upgrade_selected) OR ((product_class = 'PACKAGE'::text) AND (source = ANY (ARRAY['PURCHASED'::text, 'RECEIPT_POLICY'::text])) AND (order_id IS NOT NULL)))),
    CONSTRAINT entitlement_execution_actor CHECK ((((execution_authority = 'HUMAN'::text) AND (actor_id IS NOT NULL)) OR ((execution_authority = ANY (ARRAY['ONVO'::text, 'STRIPE'::text])) AND (actor_id IS NULL) AND (source = 'PURCHASED'::text)) OR ((execution_authority = 'RECEIPT_POLICY'::text) AND (actor_id IS NULL) AND (source = 'RECEIPT_POLICY'::text)))),
    CONSTRAINT entitlement_terms_check CHECK ((isfinite(starts_at) AND ((ends_at IS NULL) OR (isfinite(ends_at) AND (ends_at > starts_at))))),
    CONSTRAINT entitlement_terms_check1 CHECK (((product_class = 'FOUNDING_MEMBERSHIP'::text) = (ends_at IS NULL))),
    CONSTRAINT entitlement_terms_check2 CHECK (((product_class = 'LISTING_ADDON'::text) = (listing_id IS NOT NULL))),
    CONSTRAINT entitlement_terms_check3 CHECK ((((source = 'PURCHASED'::text) AND (order_id IS NOT NULL) AND (acknowledgement_id IS NOT NULL) AND (reason IS NULL)) OR ((source = 'ADMIN_GRANT'::text) AND (order_id IS NULL) AND (acknowledgement_id IS NULL) AND (reason = ANY (ARRAY['SALES'::text, 'CUSTOMER_SERVICE'::text, 'PROMOTION'::text, 'PARTNER'::text, 'OPERATIONAL_CORRECTION'::text, 'OTHER'::text])) AND ((reason <> 'OTHER'::text) OR (COALESCE(length(btrim(note)), 0) > 0))) OR ((source = 'RECEIPT_POLICY'::text) AND (product_class = 'PACKAGE'::text) AND (order_id IS NOT NULL) AND (acknowledgement_id IS NULL) AND (actor_id IS NULL) AND (reason IS NULL)))),
    CONSTRAINT entitlement_terms_execution_authority_check CHECK ((execution_authority = ANY (ARRAY['HUMAN'::text, 'ONVO'::text, 'STRIPE'::text, 'RECEIPT_POLICY'::text]))),
    CONSTRAINT entitlement_terms_note_check CHECK ((length(note) <= 2000)),
    CONSTRAINT entitlement_terms_product_class_check CHECK ((product_class = ANY (ARRAY['PACKAGE'::text, 'LISTING_ADDON'::text, 'FOUNDING_MEMBERSHIP'::text]))),
    CONSTRAINT entitlement_terms_source_check CHECK ((source = ANY (ARRAY['PURCHASED'::text, 'ADMIN_GRANT'::text, 'RECEIPT_POLICY'::text])))
);


--
-- Name: customer_email_term_current(twuanis_canonical_private.entitlement_terms); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.customer_email_term_current(p twuanis_canonical_private.entitlement_terms) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.entitlement_revocations r WHERE r.term_id=p.id)
 AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.entitlement_terms n WHERE n.id<>p.id AND n.account_id=p.account_id AND n.product_class=p.product_class AND n.product_id=p.product_id AND n.listing_id IS NOT DISTINCT FROM p.listing_id AND n.starts_at<=p.ends_at AND(n.ends_at IS NULL OR n.ends_at>p.ends_at)AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.entitlement_revocations r WHERE r.term_id=n.id));
$$;


--
-- Name: customer_email_obligations; Type: TABLE; Schema: twuanis_canonical_private; Owner: -
--

CREATE TABLE twuanis_canonical_private.customer_email_obligations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    event_key text NOT NULL,
    account_id uuid NOT NULL,
    template text NOT NULL,
    template_version integer DEFAULT 1 NOT NULL,
    event_revision text NOT NULL,
    entity_kind text NOT NULL,
    entity_id uuid NOT NULL,
    occurred_at timestamp with time zone NOT NULL,
    payload jsonb NOT NULL,
    state text DEFAULT 'QUEUED'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    first_attempt timestamp with time zone,
    next_attempt timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    lease uuid,
    lease_until timestamp with time zone,
    envelope jsonb,
    provider_message text,
    last_error text,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT customer_email_obligations_attempts_check CHECK (((attempts >= 0) AND (attempts <= 8))),
    CONSTRAINT customer_email_obligations_entity_kind_check CHECK ((entity_kind = ANY (ARRAY['listing'::text, 'claim'::text, 'order'::text, 'term'::text, 'addon'::text]))),
    CONSTRAINT customer_email_obligations_payload_check CHECK (((jsonb_typeof(payload) = 'object'::text) AND (octet_length((payload)::text) <= 32000))),
    CONSTRAINT customer_email_obligations_state_check CHECK ((state = ANY (ARRAY['QUEUED'::text, 'RETRY'::text, 'ACCEPTED'::text, 'DELIVERED'::text, 'BOUNCED'::text, 'FAILED'::text, 'COMPLAINED'::text, 'SUPPRESSED'::text, 'NEEDS_RESOLUTION'::text]))),
    CONSTRAINT customer_email_obligations_template_version_check CHECK ((template_version = 1))
);


--
-- Name: customer_email_valid(twuanis_canonical_private.customer_email_obligations, timestamp with time zone); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.customer_email_valid(p twuanis_canonical_private.customer_email_obligations, p_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE l public.listings;t twuanis_canonical_private.entitlement_terms;c twuanis_canonical_private.listing_claim_challenges;days integer;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM auth.users u JOIN twuanis_canonical_private.account_principals a ON a.id=u.id WHERE u.id=p.account_id AND u.email_confirmed_at IS NOT NULL AND u.email IS NOT NULL AND a.deleted_at IS NULL AND(u.banned_until IS NULL OR u.banned_until<=p_at))THEN RETURN false;END IF;
 IF p.entity_kind='listing' OR p.template='listing_claimed' THEN
 SELECT *INTO l FROM public.listings WHERE id=(p.payload->>'listingId')::uuid;
 IF l.id IS NULL OR l.owner_id IS DISTINCT FROM p.account_id OR l.listing_status='deleted' THEN RETURN false;END IF;
 IF p.template IN('listing_published','listing_renewed')AND(l.listing_status<>'active'OR(l.publication_expires_at IS NOT NULL AND l.publication_expires_at<=p_at)OR l.publication_expires_at IS DISTINCT FROM(p.payload->>'endsAt')::timestamptz)THEN RETURN false;END IF;
 IF p.template='listing_expired' OR p.template LIKE 'listing_reminder_%' THEN
 IF l.publication_expires_at IS DISTINCT FROM(CASE WHEN p.payload?'deadline'THEN p.payload->>'deadline'ELSE p.payload->>'endsAt'END)::timestamptz OR l.listing_status NOT IN('active','expired')THEN RETURN false;END IF;
 days:=(p.payload->>'reminderDays')::integer;
 IF days=0 THEN RETURN l.listing_status='expired'OR l.publication_expires_at<=p_at;END IF;
 IF greatest(coalesce(l.published_at,l.created_at),coalesce(l.renewed_at,l.published_at,l.created_at))>l.publication_expires_at-make_interval(secs=>86400*days)THEN RETURN false;END IF;
 RETURN l.listing_status='active'AND p_at>=l.publication_expires_at-make_interval(secs=>86400*days)AND p_at<l.publication_expires_at-make_interval(secs=>CASE WHEN days=7 THEN 86400 ELSE 0 END);
 END IF;
 ELSIF p.entity_kind='order' THEN
 RETURN EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_order_snapshots o JOIN twuanis_canonical_private.offer_paid_acknowledgements ack ON ack.order_id=o.id WHERE o.id=p.entity_id AND o.account_id=p.account_id AND ack.id=(p.payload->>'acknowledgementId')::uuid AND ack.amount::text=p.payload->>'amount'AND ack.currency=p.payload->>'currency');
 ELSIF p.entity_kind='addon' THEN
 RETURN EXISTS(SELECT 1 FROM twuanis_canonical_private.addon_fulfillments f WHERE f.purchase_id=p.entity_id AND f.account_id=p.account_id AND f.result->>'ok'='true');
 ELSIF p.entity_kind='term'AND p.template='entitlement_revoked'THEN
 RETURN EXISTS(SELECT 1 FROM twuanis_canonical_private.entitlement_terms et JOIN twuanis_canonical_private.entitlement_revocations rev ON rev.term_id=et.id WHERE et.id=p.entity_id AND et.account_id=p.account_id AND rev.request_id::text=p.event_revision);
 ELSIF p.entity_kind='term'AND p.template<>'entitlement_revoked' THEN
 SELECT *INTO t FROM twuanis_canonical_private.entitlement_terms WHERE id=p.entity_id;
 IF t.id IS NULL OR t.account_id<>p.account_id OR NOT twuanis_canonical_private.customer_email_term_current(t)THEN RETURN false;END IF;
 IF p.template LIKE '%_reminder_%' OR p.template IN('package_expired','addon_expired')THEN
 IF t.ends_at IS DISTINCT FROM(p.payload->>'endsAt')::timestamptz THEN RETURN false;END IF;days:=(p.payload->>'reminderDays')::integer;
 IF days=0 THEN RETURN t.ends_at<=p_at;END IF;
 IF t.starts_at>p_at OR t.committed_at>t.ends_at-make_interval(secs=>86400*days)THEN RETURN false;END IF;
 RETURN p_at>=t.ends_at-make_interval(secs=>86400*days)AND p_at<t.ends_at-make_interval(secs=>CASE WHEN days=7 THEN 86400 ELSE 0 END);
 END IF;
 RETURN t.starts_at<=p_at AND(t.ends_at IS NULL OR t.ends_at>p_at);
 ELSIF p.template IN('claim_approved','claim_rejected','claim_revoked') THEN
 SELECT *INTO c FROM twuanis_canonical_private.listing_claim_challenges WHERE id=(p.payload->>'challengeId')::uuid;
 IF c.id IS NULL OR c.user_id<>p.account_id OR c.status<>(CASE p.template WHEN 'claim_approved' THEN 'approved'WHEN 'claim_rejected' THEN 'rejected'ELSE 'revoked'END)THEN RETURN false;END IF;
 IF p.template='claim_approved'AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.account_phone_state ph WHERE ph.user_id=p.account_id AND ph.phone_e164=c.phone AND ph.revision=c.phone_revision)THEN RETURN false;END IF;
 END IF;RETURN true;
END$$;


--
-- Name: customer_order_before_direct_v1(uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.customer_order_before_direct_v1(p_id uuid) RETURNS jsonb
    LANGUAGE sql
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT CASE WHEN o.target_type='execution_credit'THEN jsonb_build_object('id',o.id,'kind',o.target_type,'product',o.product_id,'nameEN','Execution tokens','nameES','Tokens de ejecución','quantity',o.resolved_terms->>'quantity','unitPrice',o.resolved_terms->>'unitPrice','priceVersionId',o.resolved_terms->>'priceVersionId','currencyQuotes',o.resolved_terms->'currencyQuotes','founderProtection',o.resolved_terms->'founderProtection','importSummary',(SELECT jsonb_build_object('submitted',j.submitted_count,'accepted',j.accepted_count,'rejected',jsonb_array_length(j.rejected_rows),'published',coalesce(jsonb_array_length(r.result),0))FROM twuanis_canonical_private.addon_import_jobs j LEFT JOIN twuanis_canonical_private.addon_import_results r ON r.job_id=j.id WHERE j.id=o.job_id AND j.account_id=o.account_id),'createdAt',o.created_at,'currency',o.currency,'amount',o.resolved_terms->>'total','deadline',o.payment_deadline,'state',twuanis_canonical_private.offer_order_state(o.id,statement_timestamp()),'paid',EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_paid_acknowledgements WHERE order_id=o.id),'receiptReference',(SELECT external_reference FROM twuanis_canonical_private.offer_paid_acknowledgements WHERE order_id=o.id),'provider',(SELECT source FROM twuanis_canonical_private.offer_paid_acknowledgements WHERE order_id=o.id),'allocationId',(SELECT id FROM twuanis_canonical_private.execution_credit_allocations WHERE order_id=o.id AND kind='PURCHASED'),'tokensIssued',(SELECT quantity::text FROM twuanis_canonical_private.execution_credit_allocations WHERE order_id=o.id AND kind='PURCHASED'),'tokensRemaining',(SELECT twuanis_canonical_private.execution_credit_remaining(id)::text FROM twuanis_canonical_private.execution_credit_allocations WHERE order_id=o.id AND kind='PURCHASED'),'fulfilled',CASE WHEN EXISTS(SELECT 1 FROM twuanis_canonical_private.execution_credit_allocations WHERE order_id=o.id AND kind='PURCHASED')THEN twuanis_canonical_private.assert_execution_credit_delivery(o.id)IS NOT NULL ELSE false END)ELSE twuanis_canonical_private.customer_product_copy(o.target_type,o.product_id)||jsonb_build_object('id',o.id,'kind',o.target_type,'product',o.product_id,'listing',o.listing_id,'currency',o.currency,'amount',o.resolved_terms->>'total','standardAmount',o.resolved_terms->>'standardTotal','priceSource',o.resolved_terms->>'source','bankUpgradeSelected',CASE WHEN o.target_type='package' THEN coalesce((o.resolved_terms->'bankUpgrade'->>'selected')::boolean,false) ELSE NULL END,'termQuantity',o.resolved_terms->'terms'->'quantity','termUnit',o.resolved_terms->'terms'->>'unit','durationDays',o.resolved_terms->'terms'->'durationDays','currencyQuotes',o.resolved_terms->'currencyQuotes','founderProtection',o.resolved_terms->'founderProtection','importSummary',(SELECT jsonb_build_object('submitted',j.submitted_count,'accepted',j.accepted_count,'rejected',jsonb_array_length(j.rejected_rows),'published',coalesce(jsonb_array_length(r.result),0))FROM twuanis_canonical_private.addon_import_jobs j LEFT JOIN twuanis_canonical_private.addon_import_results r ON r.job_id=j.id WHERE j.id=o.job_id AND j.account_id=o.account_id),'createdAt',o.created_at,'deadline',o.payment_deadline,'state',twuanis_canonical_private.offer_order_state(o.id,statement_timestamp()),
 'paid',EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_paid_acknowledgements WHERE order_id=o.id),
 'fulfilled',EXISTS(SELECT 1 FROM twuanis_canonical_private.entitlement_terms WHERE order_id=o.id) OR EXISTS(SELECT 1 FROM twuanis_canonical_private.addon_fulfillments af WHERE af.purchase_id=o.id AND af.result->>'ok'='true'),
 'awaitingPublication',EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_paid_acknowledgements WHERE order_id=o.id) AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.addon_fulfillments WHERE purchase_id=o.id) AND EXISTS(SELECT 1 FROM public.listings WHERE id=o.listing_id AND owner_id=o.account_id AND listing_status NOT IN('active','deleted')))
 END FROM twuanis_canonical_private.offer_order_snapshots o WHERE o.id=p_id
$$;


--
-- Name: customer_order_projection(uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.customer_order_projection(p_id uuid) RETURNS jsonb
    LANGUAGE sql
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT twuanis_canonical_private.customer_order_before_direct_v1(p_id)||CASE WHEN o.resolved_terms->>'paymentExecution'='direct_sinpe'THEN jsonb_build_object('paymentMethod','direct_sinpe','receiptActivated',d.activation_term_id IS NOT NULL,'reconciliation',d.reconciliation,'bankVerified',false)ELSE'{}'::jsonb END FROM twuanis_canonical_private.offer_order_snapshots o LEFT JOIN twuanis_canonical_private.direct_sinpe_receipts d ON d.order_id=o.id WHERE o.id=p_id;$$;


--
-- Name: customer_product_copy(text, text); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.customer_product_copy(p_kind text, p_product text) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT CASE WHEN p_kind='execution_credit'THEN jsonb_build_object('nameEN','Execution tokens','nameES','Tokens de ejecución') WHEN p_kind IN('package','PACKAGE') THEN (SELECT jsonb_build_object('nameEN',name_en,'nameES',name_es) FROM twuanis_canonical_private.intelligence_packages WHERE id=p_product)
 ELSE (SELECT jsonb_build_object('nameEN',name_en,'nameES',name_es) FROM twuanis_canonical_private.addon_products WHERE id=p_product) END
$$;


--
-- Name: customer_publication_allowance(uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.customer_publication_allowance(p_owner uuid) RETURNS TABLE(subscription_id uuid, package_id uuid, allowance bigint, unlimited boolean, effective_start timestamp with time zone, effective_end timestamp with time zone, observed_at timestamp with time zone)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
 IF p_owner IS NULL THEN RAISE EXCEPTION 'customer identity required' USING ERRCODE='42501'; END IF;
 PERFORM twuanis_canonical_private.lock_capacity_policy(false);
 RETURN QUERY SELECT NULL::uuid,NULL::uuid,NULL::bigint,true,NULL::timestamptz,NULL::timestamptz,clock_timestamp();
END $$;


--
-- Name: customer_publication_core(uuid, uuid, bigint, uuid, text); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.customer_publication_core(p_actor uuid, p_listing uuid, p_expected bigint, p_request uuid, p_event text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE actor uuid:=p_actor;publisher uuid;governing record;c twuanis_canonical_private.customer_publication_commands%ROWTYPE;seconds bigint;result jsonb;
BEGIN
 IF actor IS NULL THEN RAISE EXCEPTION 'authenticated customer required' USING ERRCODE='42501'; END IF;
 IF p_request IS NULL OR p_listing IS NULL OR p_expected IS NULL OR p_expected<0 OR p_event IS NULL OR p_event NOT IN ('publish','renew')
 THEN RAISE EXCEPTION 'explicit bounded publication command required' USING ERRCODE='22023'; END IF;
 publisher:=twuanis_canonical_private.resolve_publisher(actor);
 IF NOT EXISTS(SELECT 1 FROM public.listings WHERE id=p_listing AND owner_id=actor AND publisher_account_id=publisher AND canonical_domain_version=1)
 THEN RAISE EXCEPTION 'owned canonical listing required' USING ERRCODE='42501'; END IF;
 -- Same operation lock as S3, after the established policy/publisher lock order.
 PERFORM pg_advisory_xact_lock(3104,hashtext(jsonb_build_array('owner',actor::text,'domain_mutation',p_request)::text));
 SELECT * INTO c FROM twuanis_canonical_private.customer_publication_commands WHERE owner_id=actor AND request_id=p_request;
 IF FOUND THEN
  IF (c.listing_id,c.expected_revision,c.event) IS DISTINCT FROM (p_listing,p_expected,p_event)
  THEN RAISE EXCEPTION 'publication retry payload conflict' USING ERRCODE='22023'; END IF;
  seconds:=c.duration_seconds;
 ELSE
  SELECT * INTO STRICT governing FROM twuanis_canonical_private.publisher_allowance(publisher,actor);
  seconds:=2592000; -- Existing 30 elapsed-day term, independent of paid Packages.
  IF seconds IS NULL OR seconds<=0 OR seconds>315576000 THEN RAISE EXCEPTION 'valid package publication entitlement required' USING ERRCODE='55000'; END IF;
  INSERT INTO twuanis_canonical_private.customer_publication_commands(owner_id,request_id,listing_id,expected_revision,event,duration_seconds,package_id)
  VALUES(actor,p_request,p_listing,p_expected,p_event,seconds,governing.package_id);
 END IF;
 result:=twuanis_canonical_private.s3_command(p_listing,p_expected,'owner',actor::text,p_request,
 jsonb_build_object('lifecycle',jsonb_build_object('event',p_event,'duration_seconds',seconds::text)),NULL);
 RETURN result||jsonb_build_object('listing_id',p_listing::text);
END $$;


--
-- Name: decide_listing_admission(jsonb, uuid, text, boolean); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.decide_listing_admission(p jsonb, r uuid, a text, retain boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE s jsonb; sig jsonb; candidate record; ref jsonb; matches jsonb:='[]'; reasons jsonb; price_equal boolean; phone_equal boolean; fx jsonb; v numeric; left_price numeric; right_price numeric; decision text:='ALLOW'; saved twuanis_canonical_private.listing_admission_decisions; latest record; review_id uuid; latest_found boolean;
BEGIN
 s:=twuanis_canonical_private.duplicate_snapshot(p-'__refresh'); sig:=twuanis_canonical_private.duplicate_signature(s);
 -- A retry cannot clear a retained rejection just because a reference becomes hidden.
 SELECT d.*,c.status,c.id AS case_id INTO latest FROM twuanis_canonical_private.listing_admission_decisions d JOIN twuanis_canonical_private.listing_duplicate_cases c ON c.current_admission_id=d.id WHERE d.listing_id=(s->>'id')::uuid AND c.status<>'DIFFERENT_PROPERTIES' ORDER BY d.created_at DESC LIMIT 1;
 latest_found:=FOUND;
 IF latest_found AND NOT(p?'__refresh') AND latest.status IN('AUTOMATIC_REJECTION','CONFIRM_DUPLICATE') AND EXISTS(SELECT 1 FROM public.listings WHERE id=(s->>'id')::uuid AND listing_status='draft') THEN RETURN jsonb_build_object('admission','AUTOMATIC_REJECTION','caseId',latest.case_id,'listing_id',s->>'id'); END IF;
 -- Generated publication times remain evidence, not caller intent. The private normalized command
 -- supplies __intent before the first check and retains it unchanged with the held decision.
 IF latest_found AND NOT(p?'__refresh') THEN
  SELECT * INTO saved FROM twuanis_canonical_private.listing_admission_decisions WHERE listing_id=(s->>'id')::uuid AND request_id=r;
  IF FOUND AND NOT (CASE WHEN jsonb_typeof(saved.proposed->'__intent')='object' AND jsonb_typeof(s->'__intent')='object' THEN saved.proposed->'__intent' IS NOT DISTINCT FROM s->'__intent' ELSE (saved.proposed-'__command'-'__intent') IS NOT DISTINCT FROM (s-'__command'-'__intent') END) THEN RAISE EXCEPTION 'Admission request payload conflict' USING ERRCODE='22023'; END IF;
 END IF;
 IF latest_found AND NOT(p?'__refresh') AND (latest.request_id=r OR (CASE WHEN jsonb_typeof(latest.proposed->'__intent')='object' AND jsonb_typeof(s->'__intent')='object' THEN latest.proposed->'__intent' IS NOT DISTINCT FROM s->'__intent' ELSE (latest.proposed-'__command'-'__intent') IS NOT DISTINCT FROM (s-'__command'-'__intent') END)) THEN RETURN jsonb_build_object('admission',CASE WHEN latest.status IN('AUTOMATIC_REJECTION','CONFIRM_DUPLICATE') THEN 'AUTOMATIC_REJECTION' ELSE 'REVIEW_REQUIRED' END,'caseId',latest.case_id,'listing_id',s->>'id'); END IF;
 IF sig IS NULL THEN UPDATE twuanis_canonical_private.listing_duplicate_cases c SET status='NO_MATCH_AFTER_REVISION',version=version+1,updated_at=clock_timestamp() FROM twuanis_canonical_private.listing_admission_decisions d WHERE d.id=c.current_admission_id AND c.listing_id=(s->>'id')::uuid AND c.status IN('REVIEW_REQUIRED','UNRESOLVED') AND twuanis_canonical_private.duplicate_signature(d.proposed) IS DISTINCT FROM sig; RETURN jsonb_build_object('admission','ALLOW','comparison','NOT_ESTABLISHED'); END IF;
 -- Nonblocking lock avoids inversions with the established publisher/source/listing locks. Retry original request on contention.
 IF NOT pg_try_advisory_xact_lock(3147,hashtext(sig::text)) THEN RAISE EXCEPTION 'Concurrent canonical admission; retry same request' USING ERRCODE='40001'; END IF;
 SELECT to_jsonb(f)||jsonb_build_object('exact_rate',f.rate::text) INTO fx FROM public.fx_rates f WHERE base_currency='USD' AND quote_currency='CRC' AND source='BCCR' AND rate_type='reference_sale' AND effective_date <= (clock_timestamp() AT TIME ZONE 'America/Costa_Rica')::date ORDER BY effective_date DESC LIMIT 1;
 FOR candidate IN SELECT l.* FROM public.listings l WHERE l.id<>(s->>'id')::uuid AND l.canonical_domain_version=1 AND l.listing_status<>'deleted' AND (l.listing_status='active' OR l.published_at IS NOT NULL) AND l.transaction_type=s->>'transaction_type' AND l.property_area=(s->>'property_area')::numeric AND l.construction_area=(s->>'construction_area')::numeric LOOP
  ref:=twuanis_canonical_private.duplicate_snapshot(to_jsonb(candidate));
  IF twuanis_canonical_private.duplicate_signature(ref) IS DISTINCT FROM sig THEN CONTINUE; END IF;
  IF EXISTS(SELECT 1 FROM twuanis_canonical_private.listing_duplicate_exceptions x WHERE
  (x.listing_id=(s->>'id')::uuid AND x.reference_id=candidate.id AND twuanis_canonical_private.duplicate_same_reviewed_evidence(x.proposed,s) AND twuanis_canonical_private.duplicate_same_reviewed_evidence(x.reference,ref)) OR
  (x.reference_id=(s->>'id')::uuid AND x.listing_id=candidate.id AND twuanis_canonical_private.duplicate_same_reviewed_evidence(x.reference,s) AND twuanis_canonical_private.duplicate_same_reviewed_evidence(x.proposed,ref))) THEN CONTINUE; END IF;
  left_price:=(CASE s->>'transaction_type' WHEN 'sale' THEN s->>'current_price' ELSE s->>'monthly_price' END)::numeric;
  right_price:=CASE candidate.transaction_type WHEN 'sale' THEN candidate.current_price ELSE candidate.monthly_price END;
  price_equal:=NULL;
  IF left_price>0 AND right_price>0 THEN
   IF s->>'currency'=candidate.currency THEN price_equal:=left_price=right_price;
   ELSIF s->>'currency' IN('USD','CRC') AND candidate.currency IN('USD','CRC') AND (fx->>'rate')::numeric>0 THEN
    price_equal:=(left_price*CASE s->>'currency' WHEN 'USD' THEN (fx->>'rate')::numeric ELSE 1 END)=(right_price*CASE candidate.currency WHEN 'USD' THEN (fx->>'rate')::numeric ELSE 1 END);
   END IF;
  END IF;
  phone_equal:=NULL;
  IF s->'verified_contact'->>'destination' IS NOT NULL AND ref->'verified_contact'->>'destination' IS NOT NULL THEN phone_equal:=(s->'verified_contact'->>'destination')=(ref->'verified_contact'->>'destination'); END IF;
  reasons:=jsonb_build_object('priceEqual',price_equal,'verifiedWhatsappEqual',phone_equal,'fx',fx,'reference',ref);
  matches:=matches||jsonb_build_array(reasons);
  IF price_equal OR phone_equal THEN decision:='AUTOMATIC_REJECTION'; ELSIF decision='ALLOW' THEN decision:='REVIEW_REQUIRED'; END IF;
 END LOOP;
 IF decision='ALLOW' AND p?'__refresh' THEN decision:='REVIEW_REQUIRED'; END IF;
 IF decision='ALLOW' THEN UPDATE twuanis_canonical_private.listing_duplicate_cases c SET status='NO_MATCH_AFTER_REVISION',version=version+1,updated_at=clock_timestamp() FROM twuanis_canonical_private.listing_admission_decisions d WHERE d.id=c.current_admission_id AND c.listing_id=(s->>'id')::uuid AND c.status IN('REVIEW_REQUIRED','UNRESOLVED') AND twuanis_canonical_private.duplicate_signature(d.proposed) IS DISTINCT FROM sig; RETURN jsonb_build_object('admission','ALLOW'); END IF;
 IF retain THEN
  SELECT * INTO saved FROM twuanis_canonical_private.listing_admission_decisions WHERE listing_id=(s->>'id')::uuid AND request_id=r;
  IF FOUND THEN IF NOT (CASE WHEN jsonb_typeof(saved.proposed->'__intent')='object' AND jsonb_typeof(s->'__intent')='object' THEN saved.proposed->'__intent' IS NOT DISTINCT FROM s->'__intent' ELSE (saved.proposed-'__command'-'__intent') IS NOT DISTINCT FROM (s-'__command'-'__intent') END) THEN RAISE EXCEPTION 'Admission request payload conflict' USING ERRCODE='22023'; END IF;
  ELSE
   INSERT INTO twuanis_canonical_private.listing_admission_decisions(listing_id,request_id,actor,revision,proposed,candidates,outcome) VALUES((s->>'id')::uuid,r,a,(s->>'canonical_revision')::bigint,s,matches,decision) RETURNING * INTO saved;
   INSERT INTO twuanis_canonical_private.listing_duplicate_cases(id,listing_id,current_admission_id,status) VALUES(saved.id,saved.listing_id,saved.id,decision)
   ON CONFLICT(listing_id) DO UPDATE SET current_admission_id=EXCLUDED.current_admission_id,status=EXCLUDED.status,version=listing_duplicate_cases.version+1,updated_at=clock_timestamp() RETURNING id INTO review_id;
   IF decision='REVIEW_REQUIRED' THEN INSERT INTO twuanis_canonical_private.listing_duplicate_owner_notifications(case_id) VALUES(review_id) ON CONFLICT DO NOTHING; END IF;
  END IF;
 END IF;
 RETURN jsonb_build_object('admission',decision,'caseId',coalesce(review_id,(SELECT id FROM twuanis_canonical_private.listing_duplicate_cases WHERE listing_id=saved.listing_id)),'listing_id',s->>'id');
END $$;


--
-- Name: decide_listing_price(public.listings); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.decide_listing_price(l public.listings) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
 amount numeric:=CASE l.transaction_type WHEN 'sale'THEN l.current_price ELSE l.monthly_price END;
 reasons text[]:='{}';m public.listing_monetary_events; observation public.listing_source_observations; retained twuanis_canonical_private.csv_source_evidence;
 raw jsonb; eligibility jsonb; products jsonb; product jsonb; offer jsonb; pair_count integer:=0; price jsonb; n numeric; c text; texts text[]:=ARRAY[l.title,l.description]; owner_assertion boolean:=false;
 structured_offer_valid boolean:=true; structured_authority boolean:=false; scraper_price_valid boolean:=false; price_evidence jsonb; text_reasons text[];
BEGIN
 IF amount IS NULL OR amount<=0 OR NOT twuanis_canonical_private.finite_numeric(amount)THEN reasons:=array_append(reasons,'PRICE_MISSING_OR_INVALID');END IF;
 IF l.currency IS NULL OR l.currency NOT IN('USD','CRC')THEN reasons:=array_append(reasons,'PRICE_CURRENCY_UNSUPPORTED');END IF;
 IF l.transaction_type NOT IN('sale','rent')OR l.transaction_type IS NULL THEN reasons:=array_append(reasons,'PRICE_TRANSACTION_UNSUPPORTED');END IF;
 IF (l.transaction_type='sale'AND l.monthly_price IS NOT NULL)OR(l.transaction_type='rent'AND l.current_price IS NOT NULL)THEN reasons:=array_append(reasons,'PRICE_TRANSACTION_MIXING');END IF;
 SELECT * INTO m FROM public.listing_monetary_events e WHERE e.listing_id=l.id ORDER BY e.listing_revision DESC,e.recorded_at DESC,e.id DESC LIMIT 1;
 IF m.id IS NULL OR (m.new_amount,m.new_currency,m.transaction_type)IS DISTINCT FROM(amount,l.currency,l.transaction_type)THEN reasons:=array_append(reasons,'PRICE_CANONICAL_ASSERTION_MISSING');END IF;
 owner_assertion:=m.actor_kind='owner'AND l.owner_id IS NOT NULL AND m.actor_identity=l.owner_id::text;
 IF NOT coalesce(owner_assertion,false)THEN
  SELECT * INTO observation FROM public.listing_source_observations s WHERE s.listing_id=l.id AND s.outcome='accepted' ORDER BY s.result_revision DESC,s.processed_at DESC,s.id DESC LIMIT 1;
  SELECT * INTO retained FROM twuanis_canonical_private.csv_source_evidence e WHERE e.source_name=l.source_name AND e.source_listing_id=l.source_listing_id AND e.source_observation_id=observation.source_observation_id;
  IF retained.id IS NULL THEN reasons:=array_append(reasons,'PRICE_RETAINED_SOURCE_EVIDENCE_REQUIRED');
  ELSE
   raw:=retained.raw_input;
   IF (raw->>'source_name',raw->>'source_listing_id',raw->>'observation_id')IS DISTINCT FROM(l.source_name,l.source_listing_id,observation.source_observation_id)THEN reasons:=array_append(reasons,'PRICE_SOURCE_IDENTITY_MISMATCH');END IF;
   IF raw->>'transaction_type'IS DISTINCT FROM l.transaction_type THEN reasons:=array_append(reasons,'PRICE_TRANSACTION_MIXING');END IF;
   n:=twuanis_canonical_private.price_integrity_number(CASE l.transaction_type WHEN 'sale'THEN raw->>'current_price'ELSE raw->>'monthly_price'END);
   IF n IS DISTINCT FROM amount OR raw->>'currency'IS DISTINCT FROM l.currency THEN reasons:=array_append(reasons,'PRICE_RETAINED_PAIR_MISMATCH');END IF;
   IF l.transaction_type='sale'AND coalesce(raw->>'monthly_price','')<>''THEN reasons:=array_append(reasons,'PRICE_TRANSACTION_MIXING');END IF;
   BEGIN eligibility:=(raw->>'collection_eligibility')::jsonb;EXCEPTION WHEN invalid_text_representation THEN eligibility:=NULL;END;
   IF eligibility->>'status'IS DISTINCT FROM 'ELIGIBLE'OR jsonb_typeof(eligibility->'reasons')IS DISTINCT FROM 'array'OR jsonb_array_length(eligibility->'reasons')<>0 THEN reasons:=array_append(reasons,'PRICE_REJECTED_OR_QUARANTINED_SOURCE');END IF;
   IF l.transaction_type='rent'AND coalesce(raw->>'current_price','')<>''THEN reasons:=array_append(reasons,'PRICE_TRANSACTION_MIXING');END IF;
   texts:=texts||ARRAY[raw->>'title',raw->>'description'];
   BEGIN products:=(raw->>'raw_jsonld')::jsonb;EXCEPTION WHEN invalid_text_representation THEN products:=NULL;reasons:=array_append(reasons,'PRICE_STRUCTURED_EVIDENCE_REQUIRED');END;
   IF jsonb_typeof(products)IS DISTINCT FROM 'array'THEN reasons:=array_append(reasons,'PRICE_STRUCTURED_EVIDENCE_REQUIRED');
   ELSE
    FOR product IN SELECT value FROM jsonb_array_elements(products)LOOP
     IF product->>'@type'<>'Product'THEN CONTINUE;END IF;texts:=array_append(texts,product->>'description');
     FOR offer IN SELECT value FROM jsonb_array_elements(CASE WHEN jsonb_typeof(product->'offers')='array'THEN product->'offers'ELSE jsonb_build_array(product->'offers')END)LOOP
      pair_count:=pair_count+1;n:=twuanis_canonical_private.price_integrity_number(offer->>'price');c:=twuanis_canonical_private.price_integrity_currency(offer->'priceCurrency');
      IF n IS NULL OR c IS NULL OR n IS DISTINCT FROM amount OR c IS DISTINCT FROM l.currency THEN reasons:=array_append(reasons,'PRICE_STRUCTURED_PAIR_CONTRADICTION');structured_offer_valid:=false;END IF;
     END LOOP;
    END LOOP;
   END IF;
   IF pair_count=0 THEN reasons:=array_append(reasons,'PRICE_STRUCTURED_EVIDENCE_REQUIRED');structured_offer_valid:=false;END IF;
   structured_authority:=pair_count>0 AND structured_offer_valid;
   BEGIN price:=((raw->>'raw_price_evidence')::jsonb)->'flight_price';EXCEPTION WHEN invalid_text_representation THEN price:=NULL;reasons:=array_append(reasons,'PRICE_SOURCE_PAIR_INVALID');END;
   IF price IS NOT NULL AND price<>'null'::jsonb THEN
    n:=twuanis_canonical_private.price_integrity_number(price#>>'{amount,value}');c:=twuanis_canonical_private.price_integrity_currency(price->'currency');
    IF n IS NULL OR c IS NULL OR n IS DISTINCT FROM amount OR c IS DISTINCT FROM l.currency THEN reasons:=array_append(reasons,'PRICE_SOURCE_PAIR_CONTRADICTION');END IF;
   END IF;
  END IF;
 END IF;
 
-- A trusted scraper observation remains subject to the retained identity,
-- eligibility, transaction, amount, currency, and textual-consistency gates.
-- It can establish structured price authority when the original source URL and
-- observation timestamp are bound to the retained exact price pair.
BEGIN
 price_evidence:=(raw->>'raw_price_evidence')::jsonb;
EXCEPTION WHEN invalid_text_representation THEN
 price_evidence:=NULL;
END;
IF jsonb_typeof(price_evidence)='object'
   AND price_evidence->>'source_url'=raw->>'source_url'
   AND price_evidence->>'observed_at'=raw->>'observed_at'
   AND jsonb_typeof(price_evidence->'flight_price')='object'
   AND coalesce(price_evidence->'flight_price'->>'source_label','')<>''
   AND coalesce(price_evidence->'flight_price'->>'source_value','')<>'' THEN
 n:=twuanis_canonical_private.price_integrity_number(price_evidence#>>'{flight_price,amount,value}');
 c:=twuanis_canonical_private.price_integrity_currency(price_evidence->'flight_price'->'currency');
 IF n IS NOT NULL AND c IS NOT NULL AND n=amount AND c=l.currency THEN
  scraper_price_valid:=true;
  reasons:=array_remove(reasons,'PRICE_STRUCTURED_EVIDENCE_REQUIRED');
  structured_authority:=true;
 ELSE
  reasons:=array_append(reasons,'PRICE_SOURCE_PAIR_CONTRADICTION');
 END IF;
ELSE
 reasons:=array_append(reasons,'PRICE_SOURCE_PAIR_INVALID');
END IF;
text_reasons:=twuanis_canonical_private.price_integrity_texts(texts,l.transaction_type,amount,l.currency);

 IF structured_authority THEN text_reasons:=array_remove(text_reasons,'PRICE_TEXT_MALFORMED_OR_AMBIGUOUS');END IF;
 reasons:=reasons||text_reasons;
 reasons:=ARRAY(SELECT DISTINCT x FROM unnest(reasons)x ORDER BY x);
 RETURN jsonb_build_object('status',CASE WHEN cardinality(reasons)=0 THEN 'APPROVED'ELSE 'REJECTED'END,'reasons',to_jsonb(reasons),'monetary_event',m.id,'source_observation',observation.id,'retained_evidence',retained.id,'source_disposition',eligibility->>'status','source_reasons',eligibility->'reasons','assertion_kind',CASE WHEN owner_assertion THEN 'authenticated_owner_asking_price'ELSE 'retained_source_asking_price'END,'transaction',l.transaction_type,'amount',amount,'currency',l.currency);
END $$;


--
-- Name: direct_receipt_immutable(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.direct_receipt_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF TG_OP<>'UPDATE' THEN RAISE EXCEPTION 'receipt records cannot be deleted';END IF;
 IF(to_jsonb(NEW)-ARRAY['activation_term_id','reconciliation','reconciled_by','reconciled_at'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['activation_term_id','reconciliation','reconciled_by','reconciled_at'])OR(OLD.activation_term_id IS NOT NULL AND NEW.activation_term_id IS DISTINCT FROM OLD.activation_term_id)THEN RAISE EXCEPTION 'receipt evidence is immutable';END IF;RETURN NEW;END $$;


--
-- Name: direct_receipt_object_allowed(text); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.direct_receipt_object_allowed(p_path text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT EXISTS(SELECT 1 FROM storage.buckets WHERE id='sinpe-receipts'AND NOT public AND file_size_limit=5242880 AND allowed_mime_types=ARRAY['application/pdf','image/jpeg','image/png','image/webp'])AND auth.uid()IS NOT NULL AND auth.jwt()->>'role'='authenticated'AND EXISTS(SELECT 1 FROM auth.users u JOIN twuanis_canonical_private.account_principals p ON p.id=u.id WHERE u.id=auth.uid()AND p.deleted_at IS NULL)AND EXISTS(SELECT 1 FROM twuanis_canonical_private.direct_sinpe_receipts r WHERE r.object_path=p_path AND(r.account_id=auth.uid()OR public.is_current_user_owner()));$$;


--
-- Name: direct_receipt_term_guard(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.direct_receipt_term_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF NOT twuanis_canonical_private.receipt_term_valid(NEW.id)THEN RAISE EXCEPTION 'complete receipt-policy entitlement correspondence required';END IF;RETURN NULL;END $$;


--
-- Name: direct_receipt_timing_valid(uuid, uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.direct_receipt_timing_valid(p_receipt uuid, p_order uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT EXISTS(SELECT 1 FROM twuanis_canonical_private.direct_sinpe_receipts d JOIN twuanis_canonical_private.offer_order_snapshots o ON o.id=d.order_id AND o.account_id=d.account_id WHERE d.id=p_receipt AND o.id=p_order AND CASE WHEN d.recovery_evidence IS NULL THEN d.submitted_at<=o.payment_deadline ELSE coalesce(d.recovery_evidence->>'version'='owner-direct-recovery-v1'AND d.recovery_evidence->>'paymentTimeSource'='OWNER_CONFIRMED'AND d.recovery_evidence->>'providerVerified'='false'AND (d.recovery_evidence->>'recoveredAt')::timestamptz=d.submitted_at AND isfinite((d.recovery_evidence->>'paymentAt')::timestamptz)AND (d.recovery_evidence->>'paymentAt')::timestamptz>=o.created_at AND (d.recovery_evidence->>'paymentAt')::timestamptz<=o.payment_deadline AND (d.recovery_evidence->>'paymentAt')::timestamptz<=d.submitted_at,false)END);
$$;


--
-- Name: direct_recovery_result(uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.direct_recovery_result(p_receipt uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT jsonb_build_object('ok',true,'receiptId',d.id,'orderId',d.order_id,'accountId',d.account_id,'termId',t.id,'startsAt',t.starts_at,'endsAt',t.ends_at,'source',t.source,'reconciliation',d.reconciliation,'paymentAt',d.recovery_evidence->>'paymentAt','paymentTimeSource','OWNER_CONFIRMED','providerVerified',false,'recoveredAt',d.submitted_at,'bankReference',d.recovery_evidence->>'bankReference')FROM twuanis_canonical_private.direct_sinpe_receipts d JOIN twuanis_canonical_private.entitlement_terms t ON t.id=d.activation_term_id AND t.order_id=d.order_id WHERE d.id=p_receipt;
$$;


--
-- Name: direct_sinpe_legacy_fence(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.direct_sinpe_legacy_fence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$BEGIN IF EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_order_snapshots WHERE id=NEW.canonical_order_id AND resolved_terms->>'paymentExecution'='direct_sinpe')THEN RAISE EXCEPTION 'use direct receipt submission for this Order';END IF;RETURN NEW;END $$;


--
-- Name: duplicate_owner(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.duplicate_owner() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE u uuid:=twuanis_canonical_private.administrative_actor(); BEGIN
 IF u IS NULL OR NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.owner_access_grants WHERE user_id=u AND revoked_at IS NULL) THEN RAISE EXCEPTION 'Current Owner authority required' USING ERRCODE='42501'; END IF; RETURN u;
END $$;


--
-- Name: duplicate_protect_media_result(jsonb); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.duplicate_protect_media_result(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE evidence jsonb; raw text; paths jsonb; BEGIN
 IF p->>'managed' IS DISTINCT FROM 'true' THEN RETURN p; END IF;
 FOR evidence IN
 SELECT d.proposed FROM twuanis_canonical_private.listing_admission_decisions d WHERE d.listing_id=(p->>'listing_id')::uuid
 UNION ALL SELECT pair.value->'reference' FROM twuanis_canonical_private.listing_admission_decisions d CROSS JOIN LATERAL jsonb_array_elements(d.candidates)pair WHERE pair.value->'reference'->>'id'=p->>'listing_id'
 LOOP
  raw:=btrim(coalesce(evidence->>'images',''));
  IF raw IN('','null') THEN paths:='[]';ELSIF left(raw,1)='[' THEN paths:=raw::jsonb;ELSE paths:=to_jsonb(string_to_array(raw,'|'));END IF;
  IF paths @> jsonb_build_array(p->>'image_value') THEN RETURN p||jsonb_build_object('managed',false,'retainedForDuplicateReview',true); END IF;
 END LOOP;
 RETURN p;
END $$;


--
-- Name: duplicate_same_reviewed_evidence(jsonb, jsonb); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.duplicate_same_reviewed_evidence(old_e jsonb, new_e jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT twuanis_canonical_private.duplicate_signature(old_e)=twuanis_canonical_private.duplicate_signature(new_e) AND (new_e->>'canonical_revision')::bigint BETWEEN (old_e->>'canonical_revision')::bigint AND (old_e->>'canonical_revision')::bigint+1 AND (old_e->'current_price',old_e->'monthly_price',old_e->'currency',old_e->'whatsapp') IS NOT DISTINCT FROM (new_e->'current_price',new_e->'monthly_price',new_e->'currency',new_e->'whatsapp');
$$;


--
-- Name: duplicate_signature(jsonb); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.duplicate_signature(p jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT CASE WHEN p->'canonical_geography'->>'province' IS NOT NULL AND p->'canonical_geography'->>'canton' IS NOT NULL AND p->'canonical_geography'->>'district' IS NOT NULL AND p->>'canonical_type' IS NOT NULL AND p->>'transaction_type' IN('sale','rent') AND (p->>'property_area')::numeric>0 AND (p->>'construction_area')::numeric>0 THEN jsonb_build_array(p->'canonical_geography'->>'province',p->'canonical_geography'->>'canton',p->'canonical_geography'->>'district',trim_scale((p->>'property_area')::numeric),trim_scale((p->>'construction_area')::numeric),p->>'canonical_type',p->>'transaction_type') END;
$$;


--
-- Name: duplicate_snapshot(jsonb); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.duplicate_snapshot(p jsonb) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT p||jsonb_build_object('_exact',jsonb_build_object('property_area',p->>'property_area','construction_area',p->>'construction_area','current_price',p->>'current_price','monthly_price',p->>'monthly_price','canonical_revision',p->>'canonical_revision'),'canonical_geography',coalesce(p->'canonical_geography',(SELECT jsonb_object_agg(t.term_type,t.id::text) FROM public.listing_membership_origins o JOIN public.ontology_terms t ON t.id=o.ontology_term_id WHERE o.listing_id=(p->>'id')::uuid AND o.origin_domain='geography' AND t.term_type IN('province','canton','district'))),
 'canonical_type',coalesce(p->>'canonical_type',(SELECT ontology_term_id::text FROM public.listing_semantic_selections WHERE listing_id=(p->>'id')::uuid AND dimension='property_type')),
 'verified_contact',twuanis_canonical_private.duplicate_verified_phone(p));
$$;


--
-- Name: duplicate_verified_phone(jsonb); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.duplicate_verified_phone(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE verified_number text; e jsonb; proof jsonb; BEGIN
 verified_number:=twuanis_canonical_private.claim_contact(p->>'whatsapp');
 SELECT jsonb_build_object('destination',verified_number,'authority','account_phone_challenge','owner',p->>'owner_id','challengeId',c.id,'phoneRevision',a.revision) INTO proof FROM twuanis_canonical_private.account_phone_state a JOIN twuanis_canonical_private.listing_claim_challenges c ON c.user_id=a.user_id AND c.phone=a.phone_e164 AND c.phone_revision=a.revision WHERE a.user_id=(p->>'owner_id')::uuid AND a.phone_e164=verified_number AND c.status='approved' ORDER BY c.created_at DESC,c.id DESC LIMIT 1; IF FOUND THEN RETURN proof; END IF;
 SELECT x.proof INTO proof FROM twuanis_canonical_private.source_profile_whatsapp_evidence x JOIN twuanis_canonical_private.csv_source_evidence e ON e.id=x.evidence_id WHERE e.source_name=p->>'source_name' AND e.source_listing_id=p->>'source_listing_id' ORDER BY e.source_observed_at DESC LIMIT 1;
 IF proof->>'destination'=verified_number THEN RETURN proof||jsonb_build_object('authority','source_profile_whatsapp'); END IF;
 SELECT evidence INTO e FROM twuanis_canonical_private.listing_duplicate_source_contacts WHERE listing_id=(p->>'id')::uuid; IF e->>'source_name'=p->>'source_name' AND e->>'source_listing_id'=p->>'source_listing_id' THEN RETURN e; END IF; RETURN NULL;
END $$;


--
-- Name: elevated_owner(uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.elevated_owner(p_actor uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT EXISTS(SELECT 1 FROM twuanis_canonical_private.owner_access_grants WHERE user_id=p_actor AND revoked_at IS NULL)
 AND auth.jwt()->>'aal'='aal2'
 AND EXISTS(SELECT 1 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(auth.jwt()->'amr')='array' THEN auth.jwt()->'amr' ELSE '[]'::jsonb END) e
 WHERE e->>'method' IN ('mfa/totp','mfa/phone','mfa/webauthn')
 AND CASE WHEN jsonb_typeof(e->'timestamp')='number' THEN (e->>'timestamp')::numeric BETWEEN extract(epoch FROM statement_timestamp())-300 AND extract(epoch FROM statement_timestamp()) ELSE false END)
$$;


--
-- Name: ensure_publisher_account(uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.ensure_publisher_account(p_owner uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE v_id uuid;
BEGIN
 IF p_owner IS NULL THEN RAISE EXCEPTION 'customer identity required' USING ERRCODE='22023'; END IF;
 PERFORM twuanis_canonical_private.lock_capacity_policy(false);
 INSERT INTO public.publisher_accounts(owner_user_id) VALUES(p_owner)
  ON CONFLICT(owner_user_id) DO NOTHING;
 -- Separate post-conflict statement obtains a fresh READ COMMITTED snapshot.
 SELECT id INTO STRICT v_id FROM public.publisher_accounts WHERE owner_user_id=p_owner FOR UPDATE;
 RETURN v_id;
END $$;


--
-- Name: entitlement_interval(timestamp with time zone, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.entitlement_interval(p_start timestamp with time zone, p_end timestamp with time zone, p_revoked timestamp with time zone) RETURNS tstzrange
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT CASE WHEN p_revoked IS NOT NULL AND p_revoked<=p_start THEN 'empty'::tstzrange
 ELSE tstzrange(p_start,CASE WHEN p_revoked IS NULL THEN p_end WHEN p_end IS NULL THEN p_revoked ELSE least(p_end,p_revoked) END,'[)') END
$$;


--
-- Name: entitlement_projection(uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.entitlement_projection(p_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT jsonb_build_object('id',t.id,'accountId',t.account_id,'productClass',t.product_class,'productId',t.product_id,'configurationId',t.configuration_id,'listingId',t.listing_id,'source',t.source,'orderId',t.order_id,'acknowledgementId',t.acknowledgement_id,'actorId',t.actor_id,'requestId',t.request_id,'reason',t.reason,'note',t.note,'startsAt',t.starts_at,'endsAt',t.ends_at,'committedAt',t.committed_at,
 'state',CASE WHEN r.term_id IS NOT NULL THEN 'REVOKED' WHEN t.starts_at>statement_timestamp() THEN 'SCHEDULED' WHEN t.ends_at<=statement_timestamp() THEN 'EXPIRED' ELSE 'ACTIVE' END,
 'revocation',CASE WHEN r.term_id IS NOT NULL THEN jsonb_build_object('actorId',r.actor_id,'requestId',r.request_id,'reason',r.reason,'revokedAt',r.revoked_at) END)
 FROM twuanis_canonical_private.entitlement_terms t LEFT JOIN twuanis_canonical_private.entitlement_revocations r ON r.term_id=t.id WHERE t.id=p_id
$$;


--
-- Name: evidence_v2_bank_scope(jsonb); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.evidence_v2_bank_scope(body jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE scope jsonb;page jsonb;manifest jsonb;revision text;after_id uuid;raws jsonb:='{}';v jsonb;r record;root text;raw jsonb;profiles text[];expected_ids text[];actual_ids text[];phase text;profile text;BEGIN
 IF body->>'population' IN('SALE','RENT') OR NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.orchestrator_methodology_releases mr WHERE mr.id=body->>'methodologyRelease' AND mr.manifest->>'acquisitionContract'='canonical-scoped-acquisition-v1') THEN RETURN;END IF;
 scope:=jsonb_build_object('transaction',body#>>'{request,scope,transaction}','geography',body#>'{request,scope,geography}','propertyType',body#>>'{request,scope,propertyType}');
 LOOP
 page:=twuanis_canonical_private.orchestrator_bank_scope_page(scope,after_id);
 IF manifest IS NULL THEN manifest:=page->'scopeEvidence';revision:=page->>'dataRevision';ELSIF manifest IS DISTINCT FROM page->'scopeEvidence' OR revision IS DISTINCT FROM page->>'dataRevision' THEN RAISE EXCEPTION 'BANK_SCOPE_REVISION_CHANGED';END IF;
 FOR raw IN SELECT value FROM jsonb_array_elements(page->'items') WITH ORDINALITY e(value,n) WHERE n<=100 LOOP
 IF raws?(raw->>'listingId') THEN RAISE EXCEPTION 'BANK_SCOPE_DUPLICATE';END IF;
 raws:=raws||jsonb_build_object(raw->>'listingId',raw);after_id:=(raw->>'listingId')::uuid;
 END LOOP;
 EXIT WHEN jsonb_array_length(page->'items')<=100;
 END LOOP;
 SELECT coalesce(array_agg(value ORDER BY value),ARRAY[]::text[]) INTO expected_ids FROM jsonb_object_keys(raws)value;
 DROP TABLE IF EXISTS pg_temp.twuanis_bank_scope_records;
 CREATE TEMP TABLE pg_temp.twuanis_bank_scope_records(kind text,payload jsonb)ON COMMIT DROP;
 REVOKE ALL ON pg_temp.twuanis_bank_scope_records FROM PUBLIC,anon,authenticated,service_role;
 INSERT INTO pg_temp.twuanis_bank_scope_records SELECT DISTINCT value->>'kind',twuanis_canonical_private.evidence_v2_decode_indexed(value->>'contentId') FROM jsonb_array_elements(body#>'{immutableEvidence,records}')value WHERE value->>'kind' IN('bank-scope-evidence','bank-acquisition-decision') OR value->>'kind' LIKE '%/bank-scope-evidence' OR value->>'kind' LIKE '%/bank-acquisition-decision';
 FOR v IN SELECT payload FROM pg_temp.twuanis_bank_scope_records WHERE kind LIKE '%bank-scope-evidence' LOOP
 IF v->'manifest' IS DISTINCT FROM manifest OR v->>'dataRevision' IS DISTINCT FROM revision OR v#>>'{authority,accountId}' IS DISTINCT FROM body->>'accountId' OR v#>>'{authority,population}' IS DISTINCT FROM body->>'population' OR jsonb_build_object('transaction',v#>>'{request,transaction}','geography',v#>'{request,geography}','propertyType',v#>>'{request,propertyType}') IS DISTINCT FROM scope THEN RAISE EXCEPTION 'BANK_SCOPE_ATTESTATION_MISMATCH';END IF;
 END LOOP;
 FOR v IN SELECT payload FROM pg_temp.twuanis_bank_scope_records WHERE kind LIKE '%bank-acquisition-decision' LOOP
 IF v->'raw' IS DISTINCT FROM raws->(v#>>'{raw,listingId}') THEN RAISE EXCEPTION 'BANK_SCOPE_RAW_MISMATCH';END IF;
 END LOOP;
 SELECT array_agg(DISTINCT value#>>'{result,eligibilityProfile}') INTO profiles FROM jsonb_array_elements(body->'engines')value;
 FOREACH phase IN ARRAY ARRAY['execution','freshness'] LOOP
 FOREACH profile IN ARRAY profiles LOOP
 IF NOT EXISTS(SELECT 1 FROM pg_temp.twuanis_bank_scope_records WHERE kind LIKE '%bank-scope-evidence' AND payload->>'phase'=phase AND payload#>>'{request,profile}'=profile) THEN RAISE EXCEPTION 'BANK_SCOPE_PHASE_REQUIRED';END IF;
 SELECT coalesce(array_agg(DISTINCT payload#>>'{raw,listingId}' ORDER BY payload#>>'{raw,listingId}'),ARRAY[]::text[]) INTO actual_ids FROM pg_temp.twuanis_bank_scope_records WHERE kind LIKE '%bank-acquisition-decision' AND payload->>'phase'=phase AND payload#>>'{request,profile}'=profile;
 IF actual_ids IS DISTINCT FROM expected_ids THEN RAISE EXCEPTION 'BANK_SCOPE_COMPLETE_MEMBERSHIP_REQUIRED';END IF;
 END LOOP;END LOOP;
END$$;


--
-- Name: evidence_v2_call_relationships(jsonb); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.evidence_v2_call_relationships(body jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE invalid boolean;records jsonb:=body#>'{immutableEvidence,records}';BEGIN
 body:=body-'immutableEvidence';
 WITH specifications(name,argument_types,output_type,engine_ids) AS (VALUES
 ('evaluateMarketPreferences',ARRAY['object','object','object'],'array',NULL::text[]),
 ('buildPriceMeterObservations',ARRAY['array','scalar'],'array',NULL::text[]),
 ('buildPriceMeterTransactionCohorts',ARRAY['array'],'object',NULL::text[]),
 ('buildPriceMeterAnalyticalCohort',ARRAY['object'],'object',NULL::text[]),
 ('calculateMarketSummary',ARRAY['object','binary64','binary64'],'object',ARRAY['summary']),
 ('canonicalMarketPrevalence',ARRAY['array'],'object',ARRAY['composition','comparison']),
 ('projectCanonicalPrevalence',ARRAY['array','array','map','map','map'],'object',ARRAY['composition','comparison']),
 ('buildNumericalDistribution',ARRAY['array'],'object',ARRAY['market-asking-price-distribution']),
 ('rankMarketPreferences',ARRAY['array'],'array',ARRAY['matching']),
 ('calculateConfigurationFrequency',ARRAY['object','scalar','binary64','binary64','scalar','array'],'object',ARRAY['configuration']),
 ('calculateMarketComparisonSide',ARRAY['array','object','binary64','scalar','object','archive-callback'],'object',ARRAY['comparison']),
 ('buildPriceMeterDistribution',ARRAY['object'],'object',ARRAY['distribution','geography','position']),
 ('buildPriceMeterGeographicLevel',ARRAY['object'],'array',ARRAY['geography']),
 ('buildPriceMeterGeographicStatistics',ARRAY['object'],'array',ARRAY['geography']),
 ('buildPriceMeterSizeRelationshipPopulation',ARRAY['object'],'object',ARRAY['size']),
 ('buildPriceMeterDescriptiveSizeRelationshipResult',ARRAY['object','scalar'],'object',ARRAY['size']),
 ('buildSelectedConstructionLand',ARRAY['array','scalar','scalar'],'object',ARRAY['construction-land']),
 ('buildPriceMeterComparisonCohortPopulation',ARRAY['object'],'object',ARRAY['cohort-comparison']),
 ('buildPriceMeterComparisonAnalysis',ARRAY['object'],'object',ARRAY['cohort-comparison']),
 ('analyzePriceMeterCrossDimensionalRelationship',ARRAY['object'],'object',ARRAY['cross-dimensional']),
 ('calculateDiscoveryPopulation',ARRAY['array'],'object',ARRAY['discovery']),
 ('buildPriceMeterPropertyPositionEvidence',ARRAY['object'],'object',ARRAY['position']),
 ('runPriceMeterComparableEngine',ARRAY['object'],'object',ARRAY['comparables']),
 ('analyzeAreaRatio',ARRAY['array'],'object',ARRAY['asking-area-ratio']),
 ('analyzeWeightedPrice',ARRAY['array','object'],'object',ARRAY['weighted-price']),
 ('establishWeightedSubject',ARRAY['object','scalar'],'object',ARRAY['weighted-price'])
 ), nodes AS NOT MATERIALIZED (SELECT node_id id,node FROM pg_temp.twuanis_evidence_validation_nodes),
 calls AS (SELECT r->>'kind' kind,r->>'contentId' id,split_part(r->>'kind','/',1) engine,split_part(r->>'kind','/',3) name FROM jsonb_array_elements(records)r WHERE r->>'kind' LIKE '%/call/%'),
 links AS (SELECT c.*,n.node,
 (SELECT jsonb_object_agg(p->>0,p->>1) FROM jsonb_array_elements(CASE WHEN n.node->>0='object' THEN n.node->1 ELSE '[]' END)p) fields
 FROM calls c LEFT JOIN nodes n ON n.id=c.id),
 contexts AS MATERIALIZED (SELECT cx.id,jsonb_object_agg(pair->>0,n.node->1) payload FROM nodes cx CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN cx.node->>0='object' THEN cx.node->1 ELSE '[]' END)pair JOIN nodes n ON n.id=pair->>1 WHERE cx.id IN(SELECT fields->>'context' FROM links) GROUP BY cx.id),
 checked AS MATERIALIZED (SELECT l.*,s.argument_types,s.output_type,s.engine_ids,i.node inode,o.node onode,a.node args,z.node result,ctx.payload context_value,ord.node order_node
 FROM links l LEFT JOIN specifications s ON s.name=l.name
 LEFT JOIN nodes i ON i.id=l.fields->>'inputId'
 LEFT JOIN nodes o ON o.id=l.fields->>'outputId'
 LEFT JOIN nodes a ON a.id=i.node->>1
 LEFT JOIN nodes z ON z.id=o.node->>1 LEFT JOIN contexts ctx ON ctx.id=l.fields->>'context' LEFT JOIN nodes ord ON ord.id=l.fields->>'invocationOrder')
 SELECT EXISTS(SELECT 1 FROM checked c WHERE
 c.argument_types IS NULL OR c.node->>0 IS DISTINCT FROM 'object'
 OR c.context_value->>'executionId' IS DISTINCT FROM body->>'executionId'
 OR c.context_value->>'accountId' IS DISTINCT FROM body->>'accountId'
 OR c.context_value->>'requestId' IS DISTINCT FROM body#>>'{request,requestId}'
 OR c.context_value->>'methodologyRelease' IS DISTINCT FROM body->>'methodologyRelease'
 OR c.context_value->>'engine' IS DISTINCT FROM c.engine
 OR c.context_value->>'population' IS NULL OR c.context_value->>'population' NOT IN('SALE','RENT','BANK')
 OR c.context_value->>'population' IS DISTINCT FROM body->>'population'
 OR c.order_node->>0 IS DISTINCT FROM 'binary64' OR c.order_node->>2 IS NULL OR c.order_node->>2!~'^[1-9][0-9]*$'
 OR jsonb_array_length(c.node->1)<>4 OR NOT(c.fields ?& ARRAY['inputId','outputId','invocationOrder','context'])
 OR c.inode->>0 IS DISTINCT FROM 'scalar' OR c.onode->>0 IS DISTINCT FROM 'scalar'
 OR c.args->>0 IS DISTINCT FROM 'array' OR c.result->>0 IS DISTINCT FROM c.output_type
 OR jsonb_array_length(c.args->1) IS DISTINCT FROM cardinality(c.argument_types)
 OR (c.engine_ids IS NOT NULL AND NOT(c.engine=ANY(c.engine_ids)))
 OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(body->'engines') e WHERE e->>'id'=c.engine)
 OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(c.args->1) WITH ORDINALITY arg(id,ord)
 LEFT JOIN nodes n ON n.id=arg.id WHERE n.node->>0 IS DISTINCT FROM c.argument_types[arg.ord])
 ) OR EXISTS(SELECT 1 FROM checked HAVING count(*)<>count(DISTINCT order_node->>2) OR min(CASE WHEN order_node->>2~'^[1-9][0-9]*$' THEN (order_node->>2)::numeric END)<>1 OR max(CASE WHEN order_node->>2~'^[1-9][0-9]*$' THEN (order_node->>2)::numeric END)<>count(*)) INTO invalid;
 IF invalid THEN RAISE EXCEPTION 'ER_CALL_ROLE_OR_ENGINE_CONTRACT' USING ERRCODE='23514';END IF;
END$_$;


--
-- Name: evidence_v2_decode(jsonb, text, integer); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.evidence_v2_decode(nodes jsonb, id text, depth integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE n jsonb;v jsonb;pair jsonb;result jsonb;kind text;k text;BEGIN
 IF depth>32 THEN RAISE EXCEPTION 'Evidence nesting limit';END IF;n:=nodes->id;IF n IS NULL THEN RAISE EXCEPTION 'Missing evidence reference';END IF;kind:=n->>0;
 IF kind='scalar' THEN RETURN n->1;
 ELSIF kind='binary64' THEN RETURN (n->>2)::jsonb;
 ELSIF kind='bigint' THEN RETURN n->1;
 ELSIF kind='undefined' THEN RETURN 'null';
 ELSIF kind IN('array','set') THEN result:='[]';FOR v IN SELECT value FROM jsonb_array_elements(n->1) LOOP result:=result||jsonb_build_array(twuanis_canonical_private.evidence_v2_decode(nodes,v#>>'{}',depth+1));END LOOP;RETURN result;
 ELSIF kind='object' THEN result:='{}';FOR pair IN SELECT value FROM jsonb_array_elements(n->1) LOOP k:=pair->>0;IF result?k THEN RAISE EXCEPTION 'Duplicate evidence field';END IF;IF nodes->(pair->>1)->>0<>'undefined' THEN result:=result||jsonb_build_object(k,twuanis_canonical_private.evidence_v2_decode(nodes,pair->>1,depth+1));END IF;END LOOP;RETURN result;
 ELSIF kind='map' THEN RETURN jsonb_build_object('entries',n->1,'properties',n->2);
 ELSIF kind='archive-callback' THEN RETURN jsonb_build_object('protectedArchiveCallback',n->1);
 END IF;RAISE EXCEPTION 'Unsupported evidence node';
END$$;


--
-- Name: evidence_v2_decode_indexed(text, integer); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.evidence_v2_decode_indexed(id text, depth integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STRICT
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE n jsonb;answer jsonb;ready boolean;kind text;height integer;BEGIN
 IF depth>32 THEN RAISE EXCEPTION 'Evidence nesting limit';END IF;
 SELECT node,decoded,decoded_ready,decoded_height INTO n,answer,ready,height FROM pg_temp.twuanis_evidence_validation_nodes WHERE node_id=id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Missing evidence reference';END IF;
 IF ready THEN IF depth+height>32 THEN RAISE EXCEPTION 'Evidence nesting limit';END IF;RETURN answer;END IF;kind:=n->>0;
 IF kind='scalar' THEN answer:=n->1;
 ELSIF kind='binary64' THEN answer:=(n->>2)::jsonb;
 ELSIF kind='bigint' THEN answer:=n->1;
 ELSIF kind='undefined' THEN answer:='null';
 ELSIF kind IN('array','set') THEN
  SELECT coalesce(jsonb_agg(CASE WHEN child.decoded_ready AND depth+1+child.decoded_height<=32 THEN child.decoded ELSE twuanis_canonical_private.evidence_v2_decode_indexed(value#>>'{}',depth+1) END ORDER BY ord),'[]') INTO answer FROM jsonb_array_elements(n->1)WITH ORDINALITY e(value,ord) LEFT JOIN pg_temp.twuanis_evidence_validation_nodes child ON child.node_id=value#>>'{}';
 ELSIF kind='object' THEN
  IF (SELECT count(*)<>count(DISTINCT value->>0)FROM jsonb_array_elements(n->1)) THEN RAISE EXCEPTION 'Duplicate evidence field';END IF;
  SELECT coalesce(jsonb_object_agg(p->>0,CASE WHEN child.decoded_ready AND depth+1+child.decoded_height<=32 THEN child.decoded ELSE twuanis_canonical_private.evidence_v2_decode_indexed(p->>1,depth+1) END),'{}') INTO answer FROM jsonb_array_elements(n->1)p JOIN pg_temp.twuanis_evidence_validation_nodes child ON child.node_id=p->>1 WHERE child.node->>0<>'undefined';
 ELSIF kind='map' THEN answer:=jsonb_build_object('entries',n->1,'properties',n->2);
 ELSIF kind='archive-callback' THEN answer:=jsonb_build_object('protectedArchiveCallback',n->1);
 ELSE RAISE EXCEPTION 'Unsupported evidence node';END IF;
 height:=0;
 IF kind IN('array','set') THEN SELECT coalesce(max(child.decoded_height+1),0) INTO height FROM jsonb_array_elements_text(n->1)r JOIN pg_temp.twuanis_evidence_validation_nodes child ON child.node_id=r;
 ELSIF kind='object' THEN SELECT coalesce(max(child.decoded_height+1),0) INTO height FROM jsonb_array_elements(n->1)r JOIN pg_temp.twuanis_evidence_validation_nodes child ON child.node_id=r->>1 WHERE child.node->>0<>'undefined';END IF;
 IF depth+height>32 THEN RAISE EXCEPTION 'Evidence nesting limit';END IF;
 UPDATE pg_temp.twuanis_evidence_validation_nodes SET decoded=answer,decoded_ready=true,decoded_height=height WHERE node_id=id;
 RETURN answer;
END$$;


--
-- Name: evidence_v2_field(jsonb, text, text); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.evidence_v2_field(nodes jsonb, id text, k text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $$ SELECT value->>1 FROM jsonb_array_elements(nodes->id->1) WHERE value->>0=k $$;


--
-- Name: evidence_v2_json(jsonb); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.evidence_v2_json(p jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE s text;BEGIN
 IF NOT jsonb_path_exists(p,'$.** ? (@.type() == "object")') THEN
  RETURN regexp_replace(p::text,'("(?:[^"\\]|\\.)*")|[[:space:]]+','\1','g');
 END IF;
 CASE jsonb_typeof(p)
 WHEN 'array' THEN SELECT '['||coalesce(string_agg(twuanis_canonical_private.evidence_v2_json(value),',' ORDER BY ord),'')||']' INTO s FROM jsonb_array_elements(p) WITH ORDINALITY e(value,ord);
 WHEN 'object' THEN SELECT '{'||coalesce(string_agg(to_jsonb(key)::text||':'||twuanis_canonical_private.evidence_v2_json(value),',' ORDER BY key COLLATE "C"),'')||'}' INTO s FROM jsonb_each(p);
 ELSE s:=p::text; END CASE; RETURN s;
END$_$;


--
-- Name: evidence_v2_private_sources(jsonb); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.evidence_v2_private_sources(body jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE nodes jsonb:=body#>'{immutableEvidence,nodes}';root text;v jsonb;source jsonb;current_value jsonb;BEGIN
 -- This function follows immutable-witness equality in report commitment.
 -- Rebuild the private lookup; never reuse a caller-created cache.
 DROP TABLE IF EXISTS pg_temp.twuanis_evidence_validation_nodes;
 CREATE TEMP TABLE pg_temp.twuanis_evidence_validation_nodes(node_id text PRIMARY KEY,node jsonb NOT NULL,decoded jsonb,decoded_ready boolean NOT NULL DEFAULT false,decoded_height integer)ON COMMIT DROP;
 REVOKE ALL ON pg_temp.twuanis_evidence_validation_nodes FROM PUBLIC,anon,authenticated,service_role;
 INSERT INTO pg_temp.twuanis_evidence_validation_nodes(node_id,node) SELECT key,value FROM jsonb_each(nodes);
 ANALYZE pg_temp.twuanis_evidence_validation_nodes;
 FOR root IN SELECT DISTINCT value->>'contentId' FROM jsonb_array_elements(body#>'{immutableEvidence,records}') WHERE value->>'kind'='private-scalar-source' OR value->>'kind' LIKE '%/private-scalar-source' LOOP
  v:=twuanis_canonical_private.evidence_v2_decode_indexed(root);source:=v->'source';
  SELECT jsonb_build_object('id',l.id,'canonical_domain_version',l.canonical_domain_version,'listing_status',l.listing_status,'transaction_type',l.transaction_type,'currency',l.currency,'created_at',l.created_at,'evidence_current_price',l.current_price::text,'evidence_monthly_price',l.monthly_price::text,'evidence_property_area',l.property_area::text,'evidence_construction_area',l.construction_area::text) INTO current_value FROM public.listings l WHERE l.id=(source->>'id')::uuid;
  IF current_value IS NULL OR source->>'evidence_current_price' IS DISTINCT FROM current_value->>'evidence_current_price' OR source->>'evidence_monthly_price' IS DISTINCT FROM current_value->>'evidence_monthly_price' OR source->>'evidence_property_area' IS DISTINCT FROM current_value->>'evidence_property_area' OR source->>'evidence_construction_area' IS DISTINCT FROM current_value->>'evidence_construction_area' OR source->>'currency' IS DISTINCT FROM current_value->>'currency' OR source->>'listing_status' IS DISTINCT FROM current_value->>'listing_status' OR source->>'transaction_type' IS DISTINCT FROM current_value->>'transaction_type' THEN RAISE EXCEPTION 'Original Private evidence changed or tampered';END IF;
 END LOOP;
 PERFORM twuanis_canonical_private.evidence_v2_bank_scope(body);
END$$;


--
-- Name: evidence_v2_report_body(jsonb); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.evidence_v2_report_body(stored jsonb) RETURNS jsonb
    LANGUAGE plpgsql STRICT
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE w twuanis_canonical_private.orchestrator_execution_witnesses%ROWTYPE;BEGIN
 IF stored->>'format' IS DISTINCT FROM 'twuanis-orchestrator-evidence-v2' OR stored?'immutableEvidence' THEN RETURN stored;END IF;
 SELECT * INTO STRICT w FROM twuanis_canonical_private.orchestrator_execution_witnesses WHERE id=(stored->>'witnessId')::uuid AND report_id=(stored->>'reportId')::uuid AND execution_id=(stored->>'executionId')::uuid;
 IF stored-ARRAY['witnessId','methodologyRelease'] IS DISTINCT FROM w.envelope OR NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.orchestrator_witness_attempts a JOIN twuanis_canonical_private.execution_credit_executions x ON x.id=a.execution_id WHERE a.execution_id=w.execution_id AND a.attempt=w.attempt AND a.release_id=stored->>'methodologyRelease' AND x.account_id=(stored->>'accountId')::uuid) THEN RAISE EXCEPTION 'Stored report witness binding invalid';END IF;
 RETURN stored||jsonb_build_object('immutableEvidence',w.transcript);
END$$;


--
-- Name: evidence_v2_validate(jsonb, uuid, uuid, uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.evidence_v2_validate(body jsonb, execution uuid, report uuid, account uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE ev jsonb;nodes jsonb;n jsonb;rec jsonb;entry record;kind text;item jsonb;refs text[];ref text;engine jsonb;decoded jsonb;ids text[];cnt integer;request_ref text;rows_ref text;checked_rows text[]:=ARRAY[]::text[];BEGIN
 IF body->>'population' IS NULL OR body->>'population' NOT IN('SALE','RENT','BANK') OR body#>>'{request,scope,transaction}' IS DISTINCT FROM (CASE body->>'population' WHEN 'SALE' THEN 'sale' WHEN 'RENT' THEN 'rent' WHEN 'BANK' THEN 'bank' END) THEN RAISE EXCEPTION 'Independent analytical universe required';END IF;
 ev:=body->'immutableEvidence';nodes:=ev->'nodes';
 IF body->>'format' IS DISTINCT FROM 'twuanis-orchestrator-evidence-v2' OR body->>'executionId' IS DISTINCT FROM execution::text OR body->>'reportId' IS DISTINCT FROM report::text OR body->>'accountId' IS DISTINCT FROM account::text OR ev->>'schema' IS DISTINCT FROM 'twuanis-analytical-evidence-v2' OR ev->>'encoding' IS DISTINCT FROM 'ordered-content-graph-binary64-v1' OR jsonb_typeof(nodes) IS DISTINCT FROM 'object' OR jsonb_typeof(ev->'records') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Complete V2 identity and schema required';END IF;
 -- Experimental ceiling: not a production-qualified budget. Scope remains fail closed.
 IF octet_length(body::text)>33554432 OR jsonb_array_length(ev->'records')>40000 OR (SELECT count(*) FROM jsonb_object_keys(nodes))>100000 THEN RAISE EXCEPTION 'V2 qualification resource ceiling exceeded';END IF;
 -- Rebuild a private, transaction-local lookup; never trust a caller-created cache.
 DROP TABLE IF EXISTS pg_temp.twuanis_evidence_validation_nodes;
 CREATE TEMP TABLE pg_temp.twuanis_evidence_validation_nodes(node_id text PRIMARY KEY,node jsonb NOT NULL,decoded jsonb,decoded_ready boolean NOT NULL DEFAULT false,decoded_height integer)ON COMMIT DROP;
 REVOKE ALL ON pg_temp.twuanis_evidence_validation_nodes FROM PUBLIC,anon,authenticated,service_role;
 INSERT INTO pg_temp.twuanis_evidence_validation_nodes(node_id,node) SELECT key,value FROM jsonb_each(nodes);
 ANALYZE pg_temp.twuanis_evidence_validation_nodes;
 DROP TABLE IF EXISTS pg_temp.twuanis_evidence_validation_records;
 CREATE TEMP TABLE pg_temp.twuanis_evidence_validation_records ON COMMIT DROP AS SELECT value->>'kind' kind,value->>'contentId' content_id FROM jsonb_array_elements(ev->'records');
 REVOKE ALL ON pg_temp.twuanis_evidence_validation_records FROM PUBLIC,anon,authenticated,service_role;
 CREATE INDEX ON pg_temp.twuanis_evidence_validation_records(kind);
 ANALYZE pg_temp.twuanis_evidence_validation_records;
 PERFORM twuanis_canonical_private.evidence_v2_call_relationships(body);
 -- Release duplicate graph variables before traversal; authoritative nodes remain indexed.
 nodes:=NULL;ev:=NULL;
 FOR entry IN SELECT node_id AS key,node AS value FROM pg_temp.twuanis_evidence_validation_nodes LOOP
 n:=entry.value;kind:=n->>0;refs:=ARRAY[]::text[];
 IF entry.key!~'^[0-9a-f]{64}$' OR encode(sha256(convert_to(twuanis_canonical_private.evidence_v2_json(n),'UTF8')),'hex')<>entry.key OR jsonb_typeof(n)<>'array' THEN RAISE EXCEPTION 'Evidence content hash mismatch';END IF;
 IF kind='scalar' THEN IF jsonb_array_length(n)<>2 OR jsonb_typeof(n->1) NOT IN('string','null','boolean') THEN RAISE EXCEPTION 'Invalid scalar evidence';END IF;
 ELSIF kind='binary64' THEN IF jsonb_array_length(n)<>3 OR n->>1!~'^[0-9a-f]{16}$' OR n->>2!~'^-?([0-9]+(\.[0-9]+)?)(e[+-]?[0-9]+)?$' OR encode(float8send((n->>2)::double precision),'hex')<>n->>1 THEN RAISE EXCEPTION 'Invalid numerical evidence';END IF;
 ELSIF kind='bigint' THEN IF jsonb_array_length(n)<>2 OR n->>1!~'^-?[0-9]+$' THEN RAISE EXCEPTION 'Invalid integer evidence';END IF;
 ELSIF kind='undefined' THEN IF jsonb_array_length(n)<>1 THEN RAISE EXCEPTION 'Invalid undefined value';END IF;
 ELSIF kind IN('array','set') THEN IF jsonb_array_length(n)<>2 OR jsonb_typeof(n->1)<>'array' THEN RAISE EXCEPTION 'Invalid sequence';END IF;SELECT coalesce(array_agg(value),ARRAY[]::text[]) INTO refs FROM jsonb_array_elements_text(n->1);
 ELSIF kind IN('object','map') THEN
 IF jsonb_array_length(n)<>(CASE WHEN kind='map' THEN 3 ELSE 2 END) OR jsonb_typeof(n->1)<>'array' THEN RAISE EXCEPTION 'Invalid keyed evidence';END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(n->1) LOOP IF jsonb_typeof(item)<>'array' OR jsonb_array_length(item)<>2 OR jsonb_typeof(item->0)<>'string' OR jsonb_typeof(item->1)<>'string' THEN RAISE EXCEPTION 'Invalid keyed pair';END IF;refs:=array_append(refs,item->>1);IF kind='map' THEN refs:=array_append(refs,item->>0);END IF;END LOOP;
 IF kind='object' AND (SELECT count(*)<>count(DISTINCT value->>0) FROM jsonb_array_elements(n->1)) THEN RAISE EXCEPTION 'Duplicate evidence key';END IF;
 IF kind='map' THEN IF jsonb_typeof(n->2)<>'array' THEN RAISE EXCEPTION 'Invalid map properties';END IF;FOR item IN SELECT value FROM jsonb_array_elements(n->2) LOOP refs:=array_append(refs,item->>1);END LOOP;END IF;
 ELSIF kind='archive-callback' THEN IF jsonb_array_length(n)<>2 OR jsonb_typeof(n->1)<>'string' THEN RAISE EXCEPTION 'Invalid callback identity';END IF;
 ELSE RAISE EXCEPTION 'Unsupported evidence tag';END IF;
 FOREACH ref IN ARRAY refs LOOP IF ref IS NULL OR ref!~'^[0-9a-f]{64}$' OR NOT EXISTS(SELECT 1 FROM pg_temp.twuanis_evidence_validation_nodes lookup WHERE lookup.node_id=ref) THEN RAISE EXCEPTION 'Incomplete evidence reference';END IF;END LOOP;
 END LOOP;
 FOR rec IN SELECT value FROM jsonb_array_elements(body#>'{immutableEvidence,records}') LOOP IF jsonb_typeof(rec)<>'object' OR jsonb_typeof(rec->'kind') IS DISTINCT FROM 'string' OR NOT EXISTS(SELECT 1 FROM pg_temp.twuanis_evidence_validation_nodes lookup WHERE lookup.node_id=rec->>'contentId') THEN RAISE EXCEPTION 'Incomplete evidence root';END IF;END LOOP;
 UPDATE pg_temp.twuanis_evidence_validation_nodes SET decoded=CASE node->>0 WHEN 'binary64' THEN(node->>2)::jsonb WHEN 'undefined' THEN 'null'::jsonb ELSE node->1 END,decoded_ready=true,decoded_height=0 WHERE node->>0 IN('scalar','binary64','undefined','bigint');
 FOR engine IN SELECT value FROM jsonb_array_elements(body->'engines') LOOP
 SELECT count(*),min(content_id) INTO cnt,ref FROM pg_temp.twuanis_evidence_validation_records r WHERE r.kind=engine->>'id'||'/engine-output';IF cnt<>1 THEN RAISE EXCEPTION 'Unique engine evidence required';END IF;
 decoded:=twuanis_canonical_private.evidence_v2_decode_indexed(ref);IF decoded IS DISTINCT FROM engine->'result' THEN RAISE EXCEPTION 'Engine output binding mismatch';END IF;
 SELECT count(*),min(content_id) INTO cnt,ref FROM pg_temp.twuanis_evidence_validation_records r WHERE r.kind=engine->>'id'||'/resolved-input';IF cnt<>1 THEN RAISE EXCEPTION 'Complete engine inputs required';END IF;
 SELECT pair->>1 INTO request_ref FROM pg_temp.twuanis_evidence_validation_nodes n CROSS JOIN LATERAL jsonb_array_elements(n.node->1)pair WHERE n.node_id=ref AND pair->>0='request';
 decoded:=twuanis_canonical_private.evidence_v2_decode_indexed(request_ref);
 IF decoded->>'engine' IS DISTINCT FROM engine->>'id' OR decoded#>>'{scope,population}' IS DISTINCT FROM body->>'population' OR decoded->'scope' IS DISTINCT FROM ((body#>'{request,scope}')||jsonb_build_object('population',body->>'population')) OR decoded->'filters' IS DISTINCT FROM body#>'{request,filters}' THEN RAISE EXCEPTION 'Engine input request binding mismatch';END IF;
 SELECT pair->>1 INTO rows_ref FROM pg_temp.twuanis_evidence_validation_nodes n CROSS JOIN LATERAL jsonb_array_elements(n.node->1)pair WHERE n.node_id=ref AND pair->>0='rows';
 IF NOT(rows_ref=ANY(checked_rows)) THEN
 SELECT array_agg(identity_node.node->>1) INTO ids FROM jsonb_array_elements_text((SELECT node->1 FROM pg_temp.twuanis_evidence_validation_nodes WHERE node_id=rows_ref))v LEFT JOIN pg_temp.twuanis_evidence_validation_nodes row_node ON row_node.node_id=v LEFT JOIN LATERAL(SELECT pair->>1 id FROM jsonb_array_elements(row_node.node->1)pair WHERE pair->>0='id')identity_ref ON true LEFT JOIN pg_temp.twuanis_evidence_validation_nodes identity_node ON identity_node.node_id=identity_ref.id;
 IF cardinality(ids)<>(SELECT count(DISTINCT v)FROM unnest(ids)v) OR EXISTS(SELECT 1 FROM unnest(ids)v WHERE v!~'^(SALE|RENT|BANK):[0-9a-f-]{36}$' OR split_part(v,':',1)<>body->>'population') THEN RAISE EXCEPTION 'Population identity or qualification limit mismatch';END IF;
 checked_rows:=array_append(checked_rows,rows_ref);END IF;
 END LOOP;
 IF body#>>'{evidence,methodology,sourceDigest}' IS NULL THEN RAISE EXCEPTION 'Methodology reference required';END IF;
 PERFORM twuanis_canonical_private.evidence_v2_bank_scope(body);
END$_$;


--
-- Name: evidence_v2_witness_binding(jsonb, uuid, uuid, uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.evidence_v2_witness_binding(body jsonb, execution uuid, report uuid, account uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE w twuanis_canonical_private.orchestrator_execution_witnesses%ROWTYPE;a twuanis_canonical_private.orchestrator_witness_attempts%ROWTYPE;x twuanis_canonical_private.execution_credit_executions%ROWTYPE;BEGIN
 SELECT * INTO STRICT x FROM twuanis_canonical_private.execution_credit_executions WHERE id=execution AND account_id=account;
 SELECT * INTO w FROM twuanis_canonical_private.orchestrator_execution_witnesses WHERE id=(body->>'witnessId')::uuid AND execution_id=execution AND report_id=report;
 IF NOT FOUND THEN RAISE EXCEPTION 'WITNESS_REQUIRED';END IF;
 SELECT * INTO STRICT a FROM twuanis_canonical_private.orchestrator_witness_attempts WHERE execution_id=w.execution_id AND attempt=w.attempt;
 IF body->>'methodologyRelease' IS DISTINCT FROM a.release_id OR body->'request' IS DISTINCT FROM x.request_payload OR body->>'orchestrator' IS DISTINCT FROM x.orchestrator_id OR body->>'population' IS DISTINCT FROM x.population OR body#>>'{accounting,settlementRequestId}' IS DISTINCT FROM w.settlement_id::text THEN RAISE EXCEPTION 'WITNESS_EXECUTION_BINDING';END IF;
 IF body->'immutableEvidence' IS DISTINCT FROM w.transcript OR (body-ARRAY['immutableEvidence','witnessId','methodologyRelease']) IS DISTINCT FROM w.envelope THEN RAISE EXCEPTION 'WITNESS_REPORT_MISMATCH';END IF;
 IF NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.orchestrator_methodology_releases r WHERE r.id=a.release_id AND r.manifest->'methodology'=body#>'{evidence,methodology}') THEN RAISE EXCEPTION 'WITNESS_METHODOLOGY_BINDING';END IF;
 -- New commitment must belong to current attempt; immutable completed retries keep existing semantics.
 IF NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.execution_credit_reports r WHERE r.execution_id=execution) AND (a.lease_until<=clock_timestamp() OR x.lease_until<=clock_timestamp() OR NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.orchestrator_execution_claims c WHERE c.execution_id=execution AND c.attempt=a.attempt AND c.worker=a.worker AND c.lease_until>clock_timestamp())) THEN RAISE EXCEPTION 'WITNESS_EXPIRED_ATTEMPT';END IF;
END$$;


--
-- Name: execution_credit_actor(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.execution_credit_actor() RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$DECLARE a uuid;BEGIN
 IF auth.jwt()->>'role' IS DISTINCT FROM 'authenticated' OR jsonb_typeof(auth.jwt()->'exp') IS DISTINCT FROM 'number' OR(auth.jwt()->>'exp')::numeric<=extract(epoch FROM clock_timestamp()) THEN RAISE EXCEPTION 'Current authenticated session required' USING ERRCODE='42501';END IF;
 a:=twuanis_remates_private.live_session_actor();
 IF EXISTS(SELECT 1 FROM auth.sessions WHERE id=(auth.jwt()->>'session_id')::uuid AND user_id=a AND not_after IS NOT NULL AND not_after<=clock_timestamp())THEN RAISE EXCEPTION 'Session expired' USING ERRCODE='42501';END IF;RETURN a;
END$$;


--
-- Name: execution_credit_allocation_live(uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.execution_credit_allocation_live(p_allocation uuid) RETURNS boolean
    LANGUAGE sql
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT EXISTS(SELECT 1 FROM twuanis_canonical_private.execution_credit_allocations a WHERE a.id=p_allocation AND a.effective_at<=statement_timestamp() AND(a.expires_at IS NULL OR a.expires_at>statement_timestamp()) AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.execution_credit_events e WHERE e.allocation_id=a.id AND e.kind='ALLOCATION_EXPIRED') AND
 (a.kind='PURCHASED' OR(a.kind='INCLUDED_PACKAGE' AND twuanis_canonical_private.execution_credit_qualifying_term(a.term_id)) OR(a.kind='ADMIN_ALLOWANCE' AND twuanis_canonical_private.execution_credit_is_admin(a.account_id))))
$$;


--
-- Name: execution_credit_authority(text, text); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.execution_credit_authority(p_orchestrator text, p_population text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a uuid;o twuanis_canonical_private.execution_credit_orchestrators%ROWTYPE;t record;cap text;ok boolean;
BEGIN
 a:=twuanis_canonical_private.execution_credit_actor();
 IF p_population IS NULL OR p_population NOT IN('SALE','RENT','BANK') THEN RAISE EXCEPTION 'Explicit population required' USING ERRCODE='22023';END IF;
 SELECT * INTO STRICT o FROM twuanis_canonical_private.execution_credit_orchestrators WHERE id=p_orchestrator;
 IF public.is_current_user_owner() THEN RETURN jsonb_build_object('kind','OWNER_UNMETERED','accountId',a,'orchestrator',o.id,'version',o.version,'capabilities',o.capabilities,'population',p_population);END IF;
 FOR t IN SELECT e.id,e.configuration_id,c.capabilities,e.product_id,e.starts_at,e.ends_at FROM twuanis_canonical_private.entitlement_terms e
 JOIN twuanis_canonical_private.intelligence_package_rights r ON r.id=e.id AND r.account_id=e.account_id AND r.package_id=e.product_id AND r.configuration_id=e.configuration_id AND r.starts_at=e.starts_at AND r.ends_at=e.ends_at
 JOIN twuanis_canonical_private.intelligence_package_configurations c ON c.id=e.configuration_id AND c.package_id=e.product_id
 WHERE e.account_id=a AND e.product_class='PACKAGE' AND e.product_id IN(o.package_id,'pkg-pricing-position-relationships') AND c.capabilities@>o.capabilities AND e.starts_at<=statement_timestamp() AND e.ends_at>statement_timestamp() AND r.revoked_at IS NULL AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.entitlement_revocations v WHERE v.term_id=e.id)
 ORDER BY e.ends_at,e.id LOOP
 ok:=true;
 FOREACH cap IN ARRAY o.capabilities LOOP
 IF NOT public.current_account_has_capability(cap) THEN ok:=false;EXIT;END IF;
 IF p_population='BANK' AND (NOT public.current_account_has_population_capability(cap,'BANK') OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(twuanis_canonical_private.bank_analytical_grant_terms(a,cap)) x WHERE x->>'id'=t.id::text)) THEN ok:=false;EXIT;END IF;
 END LOOP;
 IF ok THEN RETURN jsonb_build_object('kind','PACKAGE','accountId',a,'orchestrator',o.id,'version',o.version,'termId',t.id,'configurationId',t.configuration_id,'packageId',t.product_id,'capabilities',o.capabilities,'population',p_population,'startsAt',t.starts_at,'endsAt',t.ends_at);END IF;
 END LOOP;
 RAISE EXCEPTION 'Current Package and same-term population authority required' USING ERRCODE='42501';
END$$;


--
-- Name: execution_credit_bridge(jsonb); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.execution_credit_bridge(p_claims jsonb) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$DECLARE a uuid;BEGIN
 IF auth.jwt()->>'role' IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Trusted server required' USING ERRCODE='42501';END IF;
 IF jsonb_typeof(p_claims)<>'object' OR (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(p_claims)k)<>ARRAY['aal','exp','role','session_id','sub'] OR p_claims->>'role'<>'authenticated' OR p_claims->>'aal' IS NULL OR p_claims->>'aal' NOT IN('aal1','aal2') OR jsonb_typeof(p_claims->'exp')<>'number' OR(p_claims->>'exp')::numeric<=extract(epoch FROM clock_timestamp()) THEN RAISE EXCEPTION 'Verified current customer claims required' USING ERRCODE='42501';END IF;
 PERFORM set_config('request.jwt.claims',p_claims::text,true);
 a:=twuanis_canonical_private.execution_credit_actor();
 PERFORM pg_advisory_xact_lock(3512,hashtext(a::text));RETURN a;
END$$;


--
-- Name: execution_credit_event(uuid, uuid, uuid, uuid, text, bigint, uuid, uuid, jsonb); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.execution_credit_event(p_account uuid, p_allocation uuid, p_execution uuid, p_report uuid, p_kind text, p_quantity bigint, p_actor uuid, p_request uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$DECLARE id bigint;BEGIN
 IF p_allocation IS NOT NULL AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.execution_credit_allocations WHERE execution_credit_allocations.id=p_allocation AND account_id=p_account) OR p_execution IS NOT NULL AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.execution_credit_executions WHERE execution_credit_executions.id=p_execution AND account_id=p_account AND allocation_id IS NOT DISTINCT FROM p_allocation) OR p_report IS NOT NULL AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.execution_credit_reports WHERE execution_credit_reports.id=p_report AND execution_id=p_execution AND account_id=p_account) THEN RAISE EXCEPTION 'Exact accounting identity required' USING ERRCODE='23514';END IF;
 INSERT INTO twuanis_canonical_private.execution_credit_events(account_id,allocation_id,execution_id,report_id,kind,quantity,actor_id,request_id,metadata) VALUES(p_account,p_allocation,p_execution,p_report,p_kind,p_quantity,p_actor,p_request,p_metadata) RETURNING execution_credit_events.id INTO id;RETURN id;
END$$;


--
-- Name: execution_credit_execution_state(uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.execution_credit_execution_state(p_execution uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT CASE WHEN EXISTS(SELECT 1 FROM twuanis_canonical_private.execution_credit_events WHERE execution_id=p_execution AND kind IN('EXECUTION_CONSUMED','OWNER_COMPLETED')) THEN 'COMPLETED'
 WHEN EXISTS(SELECT 1 FROM twuanis_canonical_private.execution_credit_events WHERE execution_id=p_execution AND kind='RESERVATION_RELEASED') THEN 'RELEASED' ELSE 'RESERVED' END
$$;


--
-- Name: execution_credit_is_admin(uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.execution_credit_is_admin(p_account uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT EXISTS(SELECT 1 FROM twuanis_canonical_private.administrators WHERE user_id=p_account AND active) OR EXISTS(SELECT 1 FROM twuanis_canonical_private.top_administrator WHERE user_id=p_account)
$$;


--
-- Name: execution_credit_issue(uuid, text, bigint, text, text, uuid, uuid, uuid, timestamp with time zone, timestamp with time zone, jsonb, uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.execution_credit_issue(p_account uuid, p_kind text, p_quantity bigint, p_origin text, p_package text, p_term uuid, p_order uuid, p_ack uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_provenance jsonb, p_request uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$DECLARE id uuid;old twuanis_canonical_private.execution_credit_allocations%ROWTYPE;BEGIN

 IF p_kind='INCLUDED_PACKAGE' AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.entitlement_terms t WHERE t.id=p_term AND t.account_id=p_account AND t.product_id=p_package AND t.order_id=p_order AND t.acknowledgement_id IS NOT DISTINCT FROM p_ack AND t.starts_at=p_start AND t.ends_at=p_end AND p_origin='TERM:'||t.id AND p_quantity=CASE WHEN t.product_id='pkg-matching-market-comparison'THEN 5 WHEN t.product_id='pkg-pricing-position-relationships'THEN 10 ELSE 0 END AND p_provenance->>'configurationId'=t.configuration_id::text AND twuanis_canonical_private.execution_credit_monthly_term_source(t.id) AND t.starts_at<=clock_timestamp() AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.entitlement_revocations v WHERE v.term_id=t.id AND v.revoked_at<=t.starts_at))THEN RAISE EXCEPTION 'Exact included term provenance required';END IF;
 SELECT * INTO old FROM twuanis_canonical_private.execution_credit_allocations WHERE account_id=p_account AND origin=p_origin;
 IF FOUND THEN IF(old.kind,old.quantity,old.package_id,old.term_id,old.order_id,old.acknowledgement_id,old.effective_at,old.expires_at,old.provenance) IS DISTINCT FROM(p_kind,p_quantity,p_package,p_term,p_order,p_ack,p_start,p_end,p_provenance) THEN RAISE EXCEPTION 'Allocation retry conflict';END IF;RETURN old.id;END IF;
 INSERT INTO twuanis_canonical_private.execution_credit_allocations(account_id,kind,quantity,origin,package_id,term_id,order_id,acknowledgement_id,effective_at,expires_at,provenance) VALUES(p_account,p_kind,p_quantity,p_origin,p_package,p_term,p_order,p_ack,p_start,p_end,p_provenance) RETURNING execution_credit_allocations.id INTO id;
 PERFORM twuanis_canonical_private.execution_credit_event(p_account,id,NULL,NULL,CASE WHEN p_kind='PURCHASED'THEN 'PURCHASE_CREDITED'ELSE'ALLOCATION_ISSUED'END,p_quantity,p_account,p_request,p_provenance);RETURN id;
END$$;


--
-- Name: execution_credit_maintain(uuid, uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.execution_credit_maintain(p_account uuid, p_request uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$DECLARE x record;n bigint;BEGIN

 -- Materialize only this policy's included benefits when a scheduled term becomes current.
 FOR x IN SELECT t.* FROM twuanis_canonical_private.entitlement_terms t JOIN twuanis_canonical_private.offer_order_snapshots o ON o.id=t.order_id WHERE t.account_id=p_account AND t.source='RECEIPT_POLICY'AND t.product_id IN('pkg-matching-market-comparison','pkg-pricing-position-relationships')AND o.resolved_terms->'terms'->>'unit'='month'AND t.starts_at<=clock_timestamp()AND t.ends_at>clock_timestamp()AND twuanis_canonical_private.receipt_term_valid(t.id)AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.entitlement_revocations WHERE term_id=t.id)AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.execution_credit_allocations WHERE term_id=t.id AND kind='INCLUDED_PACKAGE')LOOP
  PERFORM twuanis_canonical_private.execution_credit_issue(p_account,'INCLUDED_PACKAGE',CASE WHEN x.product_id='pkg-matching-market-comparison'THEN 5 ELSE 10 END,'TERM:'||x.id,x.product_id,x.id,x.order_id,NULL,x.starts_at,x.ends_at,jsonb_build_object('source','RECEIPT_POLICY_MONTHLY_TERM','configurationId',x.configuration_id::text,'termId',x.id),x.request_id);
 END LOOP;
 FOR x IN SELECT e.* FROM twuanis_canonical_private.execution_credit_executions e WHERE e.account_id=p_account AND twuanis_canonical_private.execution_credit_execution_state(e.id)='RESERVED' AND(e.lease_until<=clock_timestamp() OR(e.allocation_id IS NOT NULL AND NOT twuanis_canonical_private.execution_credit_allocation_live(e.allocation_id))) ORDER BY e.id LOOP
  PERFORM twuanis_canonical_private.execution_credit_event(p_account,x.allocation_id,x.id,NULL,'RESERVATION_RELEASED',CASE WHEN x.allocation_id IS NULL THEN 0 ELSE 1 END,p_account,p_request,jsonb_build_object('reason','LEASE_OR_ALLOCATION_EXPIRED'));
 END LOOP;
 FOR x IN SELECT a.* FROM twuanis_canonical_private.execution_credit_allocations a WHERE a.account_id=p_account AND a.kind<>'PURCHASED' AND(a.expires_at<=clock_timestamp() OR(a.kind='INCLUDED_PACKAGE' AND NOT twuanis_canonical_private.execution_credit_qualifying_term(a.term_id))) AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.execution_credit_events e WHERE e.allocation_id=a.id AND e.kind='ALLOCATION_EXPIRED') ORDER BY a.id LOOP
  n:=twuanis_canonical_private.execution_credit_remaining(x.id);PERFORM twuanis_canonical_private.execution_credit_event(p_account,x.id,NULL,NULL,'ALLOCATION_EXPIRED',n,p_account,p_request,jsonb_build_object('originalQuantity',x.quantity,'expiresAt',x.expires_at,'termId',x.term_id,'reason','TIME_OR_ORIGIN_AUTHORITY_ENDED'));
 END LOOP;
END$$;


--
-- Name: execution_credit_monthly_term_source(uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.execution_credit_monthly_term_source(p_term uuid) RETURNS boolean
    LANGUAGE sql
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT EXISTS(SELECT 1 FROM twuanis_canonical_private.entitlement_terms t JOIN twuanis_canonical_private.offer_order_snapshots o ON o.id=t.order_id WHERE t.id=p_term AND t.product_id IN('pkg-matching-market-comparison','pkg-pricing-position-relationships')AND o.resolved_terms->'terms'->>'unit'='month'AND twuanis_canonical_private.receipt_term_valid(t.id)) OR EXISTS(SELECT 1 FROM twuanis_canonical_private.entitlement_terms t
 JOIN twuanis_canonical_private.intelligence_package_rights r ON r.id=t.id AND r.account_id=t.account_id AND r.package_id=t.product_id AND r.configuration_id=t.configuration_id AND r.starts_at=t.starts_at AND r.ends_at=t.ends_at
 JOIN twuanis_canonical_private.intelligence_package_configurations c ON c.id=t.configuration_id AND c.package_id=t.product_id
 JOIN twuanis_canonical_private.offer_order_snapshots o ON o.id=t.order_id AND o.account_id=t.account_id AND o.product_id=t.product_id AND o.target_type='package'
 JOIN twuanis_canonical_private.offer_paid_acknowledgements ack ON ack.id=t.acknowledgement_id AND ack.order_id=o.id AND ack.currency=o.currency AND ack.amount=(o.resolved_terms->>'total')::numeric
 WHERE t.id=p_term AND t.product_class='PACKAGE' AND t.source='PURCHASED' AND t.product_id IN('pkg-matching-market-comparison','pkg-pricing-position-relationships')
 AND c.term_unit='month' AND c.term_quantity=1 AND o.resolved_terms->'terms'->>'unit'='month' AND o.resolved_terms->'terms'->>'quantity'='1' AND o.resolved_terms->>'configurationId'=t.configuration_id::text

 AND((ack.source='sinpe' AND EXISTS(SELECT 1 FROM twuanis_canonical_private.sinpe_review_decisions d WHERE d.acknowledgement_id=ack.id AND d.disposition='APPROVED')) OR(ack.source='onvo' AND EXISTS(SELECT 1 FROM twuanis_canonical_private.onvo_receipts v WHERE v.acknowledgement_id=ack.id AND v.disposition='APPROVED')) OR(ack.source='stripe'AND twuanis_canonical_private.stripe_paid(ack.id))))
$$;


--
-- Name: execution_credit_qualifying_term(uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.execution_credit_qualifying_term(p_term uuid) RETURNS boolean
    LANGUAGE sql
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT twuanis_canonical_private.execution_credit_monthly_term_source(p_term) AND EXISTS(SELECT 1 FROM twuanis_canonical_private.entitlement_terms t JOIN twuanis_canonical_private.intelligence_package_rights r ON r.id=t.id WHERE t.id=p_term AND t.starts_at<=statement_timestamp() AND t.ends_at>statement_timestamp() AND r.revoked_at IS NULL AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.entitlement_revocations v WHERE v.term_id=t.id))
$$;


--
-- Name: execution_credit_remaining(uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.execution_credit_remaining(p_allocation uuid) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$DECLARE n bigint;BEGIN
 SELECT a.quantity+coalesce(sum(CASE WHEN e.kind IN('ADJUSTMENT','REFUND')THEN e.quantity WHEN e.kind IN('EXECUTION_CONSUMED','ALLOCATION_EXPIRED','EXECUTION_RESERVED')THEN -e.quantity WHEN e.kind='RESERVATION_RELEASED'THEN e.quantity ELSE 0 END),0)::bigint INTO n
 FROM twuanis_canonical_private.execution_credit_allocations a LEFT JOIN twuanis_canonical_private.execution_credit_events e ON e.allocation_id=a.id WHERE a.id=p_allocation GROUP BY a.quantity;
 -- CONSUMED retires an already-reserved unit; it must not debit available units twice.
 n:=n+coalesce((SELECT sum(quantity) FROM twuanis_canonical_private.execution_credit_events WHERE allocation_id=p_allocation AND kind='EXECUTION_CONSUMED'),0)::bigint;
 IF n IS NULL OR n<0 THEN RAISE EXCEPTION 'Invalid negative execution-credit balance' USING ERRCODE='23514';END IF;RETURN n;
END$$;


--
-- Name: execution_credit_sync(uuid, uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.execution_credit_sync(p_account uuid, p_request uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$DECLARE t record;start_at timestamptz;end_at timestamptz;BEGIN
 FOR t IN SELECT * FROM twuanis_canonical_private.entitlement_terms WHERE account_id=p_account AND starts_at<=clock_timestamp() AND twuanis_canonical_private.execution_credit_monthly_term_source(id) AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.entitlement_revocations v WHERE v.term_id=entitlement_terms.id AND v.revoked_at<=entitlement_terms.starts_at) ORDER BY id LOOP
  PERFORM twuanis_canonical_private.execution_credit_issue(p_account,'INCLUDED_PACKAGE',CASE WHEN t.product_id='pkg-matching-market-comparison'THEN 5 ELSE 10 END,'TERM:'||t.id,t.product_id,t.id,t.order_id,t.acknowledgement_id,t.starts_at,t.ends_at,jsonb_build_object('source','PURCHASED_MONTHLY_TERM','configurationId',t.configuration_id,'termId',t.id),p_request);
 END LOOP;
 IF twuanis_canonical_private.execution_credit_is_admin(p_account) AND NOT public.is_current_user_owner() THEN
  start_at:=date_trunc('month',clock_timestamp() AT TIME ZONE 'America/Costa_Rica') AT TIME ZONE 'America/Costa_Rica';end_at:=((start_at AT TIME ZONE 'America/Costa_Rica')+interval'1 month')AT TIME ZONE 'America/Costa_Rica';
  IF NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.execution_credit_allocations WHERE account_id=p_account AND origin='ADMIN:'||to_char(start_at AT TIME ZONE 'America/Costa_Rica','YYYY-MM')) THEN
  PERFORM twuanis_canonical_private.execution_credit_issue(p_account,'ADMIN_ALLOWANCE',3,'ADMIN:'||to_char(start_at AT TIME ZONE 'America/Costa_Rica','YYYY-MM'),NULL,NULL,NULL,NULL,start_at,end_at,jsonb_build_object('source','CANONICAL_ADMIN','period',to_char(start_at AT TIME ZONE 'America/Costa_Rica','YYYY-MM'),'timezone','America/Costa_Rica','authoritySnapshot',coalesce((SELECT to_jsonb(ad) FROM twuanis_canonical_private.administrators ad WHERE ad.user_id=p_account),(SELECT to_jsonb(ad)FROM twuanis_canonical_private.top_administrator ad WHERE ad.user_id=p_account))),p_request);END IF;
 END IF;
 PERFORM twuanis_canonical_private.execution_credit_maintain(p_account,p_request);
END$$;


--
-- Name: execution_credit_term_allocation(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.execution_credit_term_allocation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 -- Deferred: the existing issuer inserts the matching rights after the term.
 -- Add only accounting effects; do not replace payment or entitlement issuers.
 IF NEW.product_class='PACKAGE' AND NEW.source IN('PURCHASED','RECEIPT_POLICY') AND NEW.starts_at<=clock_timestamp() AND twuanis_canonical_private.execution_credit_qualifying_term(NEW.id) THEN
  PERFORM pg_advisory_xact_lock(3512,hashtext(NEW.account_id::text));
  PERFORM twuanis_canonical_private.execution_credit_issue(NEW.account_id,'INCLUDED_PACKAGE',CASE WHEN NEW.product_id='pkg-matching-market-comparison'THEN 5 ELSE 10 END,'TERM:'||NEW.id,NEW.product_id,NEW.id,NEW.order_id,NEW.acknowledgement_id,NEW.starts_at,NEW.ends_at,jsonb_build_object('source',CASE WHEN NEW.source='RECEIPT_POLICY'THEN'RECEIPT_POLICY_MONTHLY_TERM'ELSE'PURCHASED_MONTHLY_TERM'END,'configurationId',NEW.configuration_id,'termId',NEW.id),NEW.request_id);
 END IF;RETURN NULL;
END$$;


--
-- Name: finite_numeric(numeric); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.finite_numeric(v numeric) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  SELECT v IS NULL OR v NOT IN ('NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric)
$$;


--
-- Name: founder_bank_evidence_valid(uuid, text, text, jsonb); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.founder_bank_evidence_valid(p_account uuid, p_product text, p_currency text, p_terms jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE q jsonb:=p_terms->'paymentPricing';b jsonb:=p_terms->'paymentBaseTerms';gross numeric;BEGIN
 IF q IS NOT NULL AND p_terms->>'paymentMethod'='stripe' THEN
  IF p_currency IS DISTINCT FROM 'USD'OR q->>'version'IS DISTINCT FROM 'payment-method-v1'OR q->>'product'IS DISTINCT FROM p_product OR b->>'currency'IS DISTINCT FROM 'USD'OR b->>'productId'IS DISTINCT FROM p_product OR b->>'targetId'IS DISTINCT FROM p_account::text OR q->'fx'->>'source'IS DISTINCT FROM 'BCCR' THEN RETURN false;END IF;
  IF q->>'pricebookStatus'='PROPOSED_ONLY'THEN
   IF(p_terms->>'total')::numeric IS DISTINCT FROM(b->>'total')::numeric OR(q->'stripe'->>'chargeAmount')::numeric IS DISTINCT FROM(b->>'total')::numeric OR p_terms->'bankUpgrade'IS DISTINCT FROM b->'bankUpgrade'THEN RETURN false;END IF;
   RETURN twuanis_canonical_private.founder_bank_payment_base_v1(p_account,p_product,p_currency,b);
  END IF;
  IF q->>'pricebook'IS DISTINCT FROM 'package-card-usd-2026-10-31-v1' OR q->>'duration'IS DISTINCT FROM(b->'terms'->>'unit') OR (q->>'bankUpgrade')::boolean IS DISTINCT FROM coalesce((b->'bankUpgrade'->>'selected')::boolean,false) OR q->>'phase'IS DISTINCT FROM (CASE WHEN b->>'source'='OFFER' OR b->'founderProtection'IS NOT NULL THEN 'introductory'ELSE 'standard'END) THEN RETURN false;END IF;
  gross:=twuanis_canonical_private.package_card_price_v1(p_product,q->>'duration',(q->>'bankUpgrade')::boolean,q->>'phase');
  IF gross IS NULL OR gross-round(gross*0.044,2)-0.35<round((q->'sinpe'->>'chargeAmount')::numeric/(q->'fx'->>'rate')::numeric,2) THEN RETURN false;END IF;
  IF (p_terms->>'total')::numeric IS DISTINCT FROM gross OR (q->'stripe'->>'chargeAmount')::numeric IS DISTINCT FROM gross OR (p_terms->'bankUpgrade')IS DISTINCT FROM(b->'bankUpgrade')THEN RETURN false;END IF;
  RETURN twuanis_canonical_private.founder_bank_payment_base_v1(p_account,p_product,p_currency,b);
 END IF;
 RETURN twuanis_canonical_private.founder_bank_payment_base_v1(p_account,p_product,p_currency,p_terms);
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;


--
-- Name: founder_bank_evidence_valid_historical_v1(uuid, text, text, jsonb); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.founder_bank_evidence_valid_historical_v1(p_account uuid, p_product text, p_currency text, p_terms jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE e jsonb:=p_terms->'founderProtection';f twuanis_canonical_private.founder_protected_prices%ROWTYPE;b twuanis_canonical_private.founder_protected_prices%ROWTYPE;combined numeric;at_time timestamptz:=(p_terms->>'resolvedAt')::timestamptz;
BEGIN
 IF e IS NULL OR e->>'kind'<>'package' OR e->>'productId' IS DISTINCT FROM p_product OR e->>'currency' IS DISTINCT FROM p_currency OR e->>'population'<>'COMBINED'OR e->>'scheduleDate'<>'2027-01-01'OR at_time<'2027-01-01 00:00:00 America/Costa_Rica'::timestamptz THEN RETURN false;END IF;
 IF NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.entitlement_terms t WHERE t.id=(e->>'termId')::uuid AND t.account_id=p_account AND t.product_class='FOUNDING_MEMBERSHIP' AND t.starts_at<=at_time AND(t.ends_at IS NULL OR t.ends_at>at_time)AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.entitlement_revocations r WHERE r.term_id=t.id AND r.revoked_at<=at_time))THEN RETURN false;END IF;
 SELECT * INTO STRICT f FROM twuanis_canonical_private.founder_protected_prices WHERE kind='package'AND product_id=p_product AND currency=CASE WHEN p_currency='CRC'AND p_terms?'fx'THEN 'USD'ELSE p_currency END AND population='PRIVATE';
 SELECT * INTO STRICT b FROM twuanis_canonical_private.founder_protected_prices WHERE kind='package'AND product_id=p_product AND currency=CASE WHEN p_currency='CRC'AND p_terms?'fx'THEN 'USD'ELSE p_currency END AND population='BANK';
 SELECT amount INTO STRICT combined FROM twuanis_canonical_private.founder_protected_prices WHERE kind='package'AND product_id=p_product AND currency=CASE WHEN p_currency='CRC'AND p_terms?'fx'THEN 'USD'ELSE p_currency END AND population='COMBINED';
 IF p_currency='CRC'AND p_terms?'fx'THEN f.amount:=round(f.amount*(SELECT rate FROM public.fx_rates WHERE base_currency='USD'AND quote_currency='CRC'AND rate_type='reference_sale'AND source='BCCR'AND effective_date<=(at_time AT TIME ZONE 'America/Costa_Rica')::date ORDER BY effective_date DESC LIMIT 1),0);b.amount:=round(b.amount*(SELECT rate FROM public.fx_rates WHERE base_currency='USD'AND quote_currency='CRC'AND rate_type='reference_sale'AND source='BCCR'AND effective_date<=(at_time AT TIME ZONE 'America/Costa_Rica')::date ORDER BY effective_date DESC LIMIT 1),0);combined:=f.amount+b.amount;END IF;
 RETURN (p_terms->>'total')::numeric=combined AND(p_terms->>'baseTotal')::numeric=f.amount AND(p_terms->'bankUpgrade'->>'amount')::numeric=b.amount AND p_terms->'bankUpgrade'->>'priceVersionId'=b.evidence->>'bankPriceVersionId' AND p_terms->'bankUpgrade'->'priceVersion'=b.evidence->'bankPriceVersion';
END$$;


--
-- Name: founder_bank_payment_base_v1(uuid, text, text, jsonb); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.founder_bank_payment_base_v1(p_account uuid, p_product text, p_currency text, p_terms jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE e jsonb:=p_terms->'founderProtection';b jsonb;k jsonb;at_time timestamptz:=(p_terms->>'resolvedAt')::timestamptz;BEGIN
 IF e->>'policyVersion' IS DISTINCT FROM 'cr-intro-life-2000-v1' THEN RETURN twuanis_canonical_private.founder_bank_evidence_valid_historical_v1(p_account,p_product,p_currency,p_terms);END IF;
 b:=twuanis_canonical_private.membership_introductory_price(p_account,'package',p_product,p_currency,at_time,twuanis_canonical_private.membership_duration(p_terms->'terms'),1,'PRIVATE',p_terms->'terms');
 k:=twuanis_canonical_private.membership_introductory_price(p_account,'package',p_product,p_currency,at_time,twuanis_canonical_private.membership_duration(p_terms->'terms'),1,'BANK',p_terms->'terms');
 RETURN coalesce(b IS NOT NULL AND k IS NOT NULL AND e->>'membershipId'=b->>'membershipId' AND e->>'priceIdentity'=b->>'priceIdentity' AND e->'bankProtection'=k AND (p_terms->>'baseTotal')::numeric=(b->>'total')::numeric AND (p_terms->'bankUpgrade'->>'amount')::numeric=(k->>'total')::numeric AND (p_terms->>'total')::numeric=(b->>'total')::numeric+(k->>'total')::numeric AND p_terms->'bankUpgrade'->>'priceVersionId'=k->'sourceEvidence'->>'bankPriceVersionId' AND p_terms->'bankUpgrade'->'priceVersion'=k->'sourceEvidence'->'bankPriceVersion',false);
END$$;


--
-- Name: founder_composed_price(uuid, text, text, timestamp with time zone, jsonb, boolean); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.founder_composed_price(p_account uuid, p_product text, p_currency text, p_at timestamp with time zone, p_composed jsonb, p_bank boolean) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE b jsonb;k jsonb;base jsonb;protection jsonb;total numeric;BEGIN
 IF NOT twuanis_canonical_private.has_introductory_membership(p_account,p_at) THEN RETURN twuanis_canonical_private.founder_composed_price_historical_v1(p_account,p_product,p_currency,p_at,p_composed,p_bank);END IF;
 IF NOT p_bank THEN
 base:=twuanis_canonical_private.founder_price(p_account,'package',p_product,p_currency,p_at,p_composed->'base','PRIVATE');RETURN p_composed||jsonb_build_object('base',base,'baseTotal',base->>'total','total',base->>'total');END IF;
 base:=p_composed->'base';
 b:=twuanis_canonical_private.membership_introductory_price(p_account,'package',p_product,p_currency,p_at,twuanis_canonical_private.membership_duration(base->'terms'),1,'PRIVATE',base->'terms');
 k:=twuanis_canonical_private.membership_introductory_price(p_account,'package',p_product,p_currency,p_at,twuanis_canonical_private.membership_duration(base->'terms'),1,'BANK',base->'terms');
 IF b IS NULL OR k IS NULL THEN RAISE EXCEPTION 'eligible Bank introductory binding requires qualification';END IF;
 total:=(b->>'total')::numeric+(k->>'total')::numeric;
 IF total>=(p_composed->>'total')::numeric THEN RETURN p_composed;END IF;
 protection:=b||jsonb_build_object('population','COMBINED','bankProtection',k,'publicTotal',p_composed->>'total');
 base:=base||jsonb_build_object('effectiveRate',b->>'total','total',b->>'total','source','STANDARD','offerId',NULL,'offerConfigurationId',NULL,'offerEnd',NULL,'founderProtection',protection);
 RETURN p_composed||jsonb_build_object('base',base,'baseTotal',b->>'total','total',total::text,'standardTotal',((base->>'standardRate')::numeric+(k->>'total')::numeric)::text,'bankUpgrade',jsonb_build_object('selected',true,'priceVersionId',k->'sourceEvidence'->>'bankPriceVersionId','priceVersion',k->'sourceEvidence'->'bankPriceVersion','amount',k->>'total'));
END$$;


--
-- Name: founder_composed_price_historical_v1(uuid, text, text, timestamp with time zone, jsonb, boolean); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.founder_composed_price_historical_v1(p_account uuid, p_product text, p_currency text, p_at timestamp with time zone, p_composed jsonb, p_bank boolean) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE chosen jsonb;b jsonb;k twuanis_canonical_private.founder_protected_prices%ROWTYPE;f twuanis_canonical_private.founder_protected_prices%ROWTYPE;
BEGIN
 IF NOT p_bank THEN
 b:=twuanis_canonical_private.founder_price(p_account,'package',p_product,p_currency,p_at,p_composed->'base','PRIVATE');
 RETURN p_composed||jsonb_build_object('base',b,'baseTotal',b->>'total','total',b->>'total');
 END IF;
 chosen:=twuanis_canonical_private.founder_price(p_account,'package',p_product,p_currency,p_at,jsonb_build_object('available',true,'total',p_composed->>'total'),'COMBINED');
 IF chosen->'founderProtection' IS NULL THEN RETURN p_composed;END IF;
 SELECT * INTO STRICT f FROM twuanis_canonical_private.founder_protected_prices WHERE kind='package'AND product_id=p_product AND currency='USD' AND population='PRIVATE';
 SELECT * INTO STRICT k FROM twuanis_canonical_private.founder_protected_prices WHERE kind='package'AND product_id=p_product AND currency='USD' AND population='BANK';
 IF p_currency='CRC'THEN f.amount:=round(f.amount*(SELECT rate FROM public.fx_rates WHERE base_currency='USD'AND quote_currency='CRC'AND rate_type='reference_sale'AND source='BCCR'AND effective_date<=(p_at AT TIME ZONE 'America/Costa_Rica')::date ORDER BY effective_date DESC LIMIT 1),0);k.amount:=round(k.amount*(SELECT rate FROM public.fx_rates WHERE base_currency='USD'AND quote_currency='CRC'AND rate_type='reference_sale'AND source='BCCR'AND effective_date<=(p_at AT TIME ZONE 'America/Costa_Rica')::date ORDER BY effective_date DESC LIMIT 1),0);END IF;
 b:=(p_composed->'base')||jsonb_build_object('effectiveRate',f.amount::text,'total',f.amount::text,'source','STANDARD','offerId',NULL,'offerConfigurationId',NULL,'offerEnd',NULL,'founderProtection',chosen->'founderProtection');
 RETURN p_composed||jsonb_build_object('base',b,'baseTotal',f.amount::text,'total',chosen->>'total','standardTotal',(((b->>'standardRate')::numeric)+k.amount)::text,'bankUpgrade',jsonb_build_object('selected',true,'priceVersionId',k.evidence->>'bankPriceVersionId','priceVersion',k.evidence->'bankPriceVersion','amount',k.amount::text));
END$$;


--
-- Name: founder_price(uuid, text, text, text, timestamp with time zone, jsonb, text); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.founder_price(p_account uuid, p_kind text, p_product text, p_currency text, p_at timestamp with time zone, p_public jsonb, p_population text DEFAULT 'PRIVATE'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE q jsonb;amount numeric;quantity integer;BEGIN
 IF NOT twuanis_canonical_private.has_introductory_membership(p_account,p_at) THEN RETURN twuanis_canonical_private.founder_price_historical_v1(p_account,p_kind,p_product,p_currency,p_at,p_public,p_population);END IF;
 IF p_public->>'available' IS DISTINCT FROM 'true' THEN RETURN p_public;END IF;
 IF p_kind NOT IN('package','addon') OR (p_kind='addon' AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.addon_products WHERE id=p_product AND term_kind='elapsed_days')) THEN RETURN p_public;END IF;
 quantity:=coalesce((p_public->>'quantity')::integer,1);
 q:=twuanis_canonical_private.membership_introductory_price(p_account,p_kind,p_product,p_currency,p_at,twuanis_canonical_private.membership_duration(p_public->'terms'),quantity,p_population,p_public->'terms');
 IF q IS NULL THEN RAISE EXCEPTION 'eligible introductory price binding requires qualification';END IF;
 amount:=least((p_public->>'total')::numeric,(q->>'total')::numeric);
 RETURN p_public||jsonb_build_object('effectiveRate',(amount/quantity)::text,'total',amount::text,'source','STANDARD','offerId',NULL,'offerConfigurationId',NULL,'offerEnd',NULL,'founderProtection',q||jsonb_build_object('publicTotal',p_public->>'total'));
END$$;


--
-- Name: founder_price_historical_v1(uuid, text, text, text, timestamp with time zone, jsonb, text); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.founder_price_historical_v1(p_account uuid, p_kind text, p_product text, p_currency text, p_at timestamp with time zone, p_public jsonb, p_population text DEFAULT 'PRIVATE'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE t uuid;f twuanis_canonical_private.founder_protected_prices%ROWTYPE;amount numeric;BEGIN
 SELECT id INTO t FROM twuanis_canonical_private.entitlement_terms e WHERE e.account_id=p_account AND e.product_class='FOUNDING_MEMBERSHIP' AND e.starts_at<=p_at AND(e.ends_at IS NULL OR e.ends_at>p_at) AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.entitlement_revocations r WHERE r.term_id=e.id AND r.revoked_at<=p_at) ORDER BY starts_at LIMIT 1;
 IF t IS NULL OR p_at<'2027-01-01 00:00:00 America/Costa_Rica'::timestamptz OR p_public->>'available' IS DISTINCT FROM 'true' THEN RETURN p_public;END IF;
 SELECT * INTO f FROM twuanis_canonical_private.founder_protected_prices WHERE kind=p_kind AND product_id=p_product AND currency='USD' AND population=p_population;
 IF FOUND AND p_currency='CRC'THEN f.amount:=round(f.amount*(SELECT rate FROM public.fx_rates WHERE base_currency='USD'AND quote_currency='CRC'AND rate_type='reference_sale'AND source='BCCR'AND effective_date<=(p_at AT TIME ZONE 'America/Costa_Rica')::date ORDER BY effective_date DESC LIMIT 1),0);f.currency:='CRC';IF p_population='COMBINED'THEN SELECT sum(round(fp.amount*(SELECT rate FROM public.fx_rates WHERE base_currency='USD'AND quote_currency='CRC'AND rate_type='reference_sale'AND source='BCCR'AND effective_date<=(p_at AT TIME ZONE 'America/Costa_Rica')::date ORDER BY effective_date DESC LIMIT 1),0))INTO f.amount FROM twuanis_canonical_private.founder_protected_prices fp WHERE kind=p_kind AND product_id=p_product AND currency='USD'AND population IN('PRIVATE','BANK');END IF;END IF;
 IF NOT FOUND OR(p_public->>'total')::numeric<=f.amount THEN RETURN p_public;END IF;
 amount:=f.amount;
 RETURN p_public||jsonb_build_object('effectiveRate',amount::text,'total',amount::text,'source','STANDARD','offerId',NULL,'offerConfigurationId',NULL,'offerEnd',NULL,
 'founderProtection',jsonb_build_object('termId',t,'scheduleDate',f.schedule_date,'kind',f.kind,'productId',f.product_id,'population',f.population,'currency',f.currency,'amount',amount::text,'publicTotal',p_public->>'total','evidence',f.evidence));
END$$;


--
-- Name: founding_membership_capacity_guard(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.founding_membership_capacity_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE policy text;slot_id integer;held uuid;
BEGIN
 IF TG_TABLE_NAME='offer_order_snapshots' THEN
 SELECT version INTO policy FROM twuanis_canonical_private.founding_membership_policies WHERE configuration_id=(NEW.resolved_terms->>'configurationId')::uuid AND product_id=NEW.product_id;
 IF NOT FOUND THEN RETURN NEW;END IF;
 IF NEW.target_type<>'addon' OR (NEW.resolved_terms->>'quantity')::integer IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'one membership per canonical Order';END IF;
 PERFORM pg_advisory_xact_lock(3260,1);
 -- Release ONLY expired, unpaid reservations with no provider-start evidence.
 -- Existing/uncertain provider attempts keep their slot until separately reconciled.
 UPDATE twuanis_canonical_private.founding_membership_capacity s SET order_id=NULL
 FROM twuanis_canonical_private.offer_order_snapshots o
 WHERE s.order_id=o.id AND s.term_id IS NULL AND o.payment_deadline<clock_timestamp()
 AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_paid_acknowledgements a WHERE a.order_id=o.id)
 AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.onvo_intents i WHERE i.order_id=o.id)
 AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.stripe_checkouts c WHERE c.order_id=o.id);
 SELECT slot INTO slot_id FROM twuanis_canonical_private.founding_membership_capacity WHERE order_id IS NULL AND policy_version=policy ORDER BY slot LIMIT 1 FOR UPDATE;
 IF slot_id IS NULL THEN RAISE EXCEPTION 'five-membership inventory exhausted';END IF;
 UPDATE twuanis_canonical_private.founding_membership_capacity SET order_id=NEW.id WHERE slot=slot_id;RETURN NEW;
 ELSIF TG_TABLE_NAME='entitlement_terms' THEN
 SELECT version INTO policy FROM twuanis_canonical_private.founding_membership_policies WHERE configuration_id=NEW.configuration_id;
 IF NOT FOUND THEN RETURN NEW;END IF;
 IF NEW.product_class<>'FOUNDING_MEMBERSHIP' OR NEW.source<>'PURCHASED' OR NEW.ends_at IS NOT NULL OR NEW.order_id IS NULL OR NEW.acknowledgement_id IS NULL THEN RAISE EXCEPTION 'paid lifetime membership required';END IF;
 PERFORM pg_advisory_xact_lock(3260,1);
 SELECT term_id INTO held FROM twuanis_canonical_private.founding_membership_capacity WHERE order_id=NEW.order_id FOR UPDATE;
 IF NOT FOUND OR held IS NOT NULL THEN RAISE EXCEPTION 'exact unissued capacity reservation required';END IF;
 UPDATE twuanis_canonical_private.founding_membership_capacity SET term_id=NEW.id WHERE order_id=NEW.order_id;RETURN NEW;
 ELSE
 IF NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_order_snapshots o JOIN twuanis_canonical_private.founding_membership_policies p ON p.configuration_id=(o.resolved_terms->>'configurationId')::uuid WHERE o.id=NEW.order_id)THEN RETURN NEW;END IF;
 PERFORM pg_advisory_xact_lock(3260,1);
 IF NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.founding_membership_capacity s JOIN twuanis_canonical_private.offer_order_snapshots o ON o.id=s.order_id WHERE s.order_id=NEW.order_id AND o.payment_deadline>=clock_timestamp()) THEN RAISE EXCEPTION 'live membership reservation required';END IF;
 RETURN NEW;
 END IF;
END$$;


--
-- Name: fulfill_addon(uuid, uuid, uuid, text, uuid, text, uuid, jsonb); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.fulfill_addon(p_purchase uuid, p_verified_payment uuid, p_account uuid, p_product text, p_configuration uuid, p_target_kind text, p_target uuid, p_evidence jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE p twuanis_canonical_private.addon_products%ROWTYPE;c twuanis_canonical_private.addon_configurations%ROWTYPE;
 old twuanis_canonical_private.addon_fulfillments%ROWTYPE;
 at_time timestamptz;expires timestamptz;result jsonb;term_id uuid;ack uuid;term_start timestamptz;
BEGIN
 IF p_purchase IS NULL OR p_verified_payment IS NULL OR p_account IS NULL OR p_target IS NULL OR jsonb_typeof(p_evidence) IS DISTINCT FROM 'object' OR octet_length(p_evidence::text)>16000 THEN RAISE EXCEPTION 'bounded trusted purchased evidence required'; END IF;
 -- This is a private INVOKER primitive for a future verified-payment transaction.
 -- UUIDs supplied by a browser are never accepted as proof; API roles have no EXECUTE.
 PERFORM pg_advisory_xact_lock(3153,hashtext(p_purchase::text));
 SELECT * INTO old FROM twuanis_canonical_private.addon_fulfillments WHERE purchase_id=p_purchase;
 IF FOUND THEN
  IF (old.verified_payment_id,old.account_id,old.product_id,old.configuration_id,old.target_kind,old.target_id,old.purchased_evidence) IS DISTINCT FROM (p_verified_payment,p_account,p_product,p_configuration,p_target_kind,p_target,p_evidence) THEN RAISE EXCEPTION 'purchase replay conflict'; END IF;
  RETURN old.result;
 END IF;
 SELECT * INTO STRICT p FROM twuanis_canonical_private.addon_products WHERE id=p_product;
 SELECT * INTO STRICT c FROM twuanis_canonical_private.addon_configurations WHERE product_id=p_product AND id=p_configuration;
 IF p.target IS DISTINCT FROM p_target_kind OR p.term_kind='unconfigured' THEN RAISE EXCEPTION 'target/fulfillment unavailable'; END IF;
 IF p_evidence->>'currency' IS NULL OR p_evidence->>'currency' NOT IN ('USD','CRC') OR jsonb_typeof(p_evidence->'amount') IS DISTINCT FROM 'string' OR (p_evidence->>'amount') !~ '^[0-9]+(\.[0-9]{1,2})?$' OR (p_evidence->>'amount')::numeric<=0 THEN RAISE EXCEPTION 'immutable resolved purchase price required'; END IF;
 IF p.term_kind IN ('whole_job','lifetime') AND p_evidence->>'currency'<>'USD' AND NOT (
 p_evidence->>'currency'='CRC' AND EXISTS(
 SELECT 1 FROM twuanis_canonical_private.offer_order_snapshots o JOIN twuanis_canonical_private.offer_paid_acknowledgements a ON a.order_id=o.id
 WHERE o.id=p_purchase AND o.account_id=p_account AND o.product_id=p_product AND (o.resolved_terms->>'configurationId')::uuid=p_configuration
 AND a.payment_event_id=p_verified_payment AND o.currency='CRC' AND o.resolved_terms->>'total'=p_evidence->>'amount'
 AND o.resolved_terms->'currencyQuotes'->'CRC'->>'total'=o.resolved_terms->>'total'
 AND o.resolved_terms->'fx'->>'source'='BCCR' AND o.resolved_terms->'fx'->>'rateType'='reference_sale' AND(o.resolved_terms->'fx'->>'rate')::numeric>0
 AND(EXISTS(SELECT 1 FROM twuanis_canonical_private.addon_standard_prices s WHERE s.configuration_id=p_configuration AND s.currency='USD')OR EXISTS(SELECT 1 FROM twuanis_canonical_private.addon_quantity_tiers t WHERE t.configuration_id=p_configuration AND t.currency='USD'))))THEN RAISE EXCEPTION 'unpriced currency';END IF;
 SELECT a.id INTO STRICT ack FROM twuanis_canonical_private.offer_paid_acknowledgements a
 JOIN twuanis_canonical_private.offer_order_snapshots o ON o.id=a.order_id
 WHERE o.id=p_purchase AND a.payment_event_id=p_verified_payment AND o.account_id=p_account AND o.product_id=p_product
 AND (o.resolved_terms->>'configurationId')::uuid=p_configuration AND o.currency=p_evidence->>'currency'
 AND o.resolved_terms->>'total'=p_evidence->>'amount'
 AND coalesce(o.job_id,o.listing_id,o.account_id)=p_target;
 IF p.term_kind='elapsed_days' THEN
  IF c.duration_days IS NULL THEN RAISE EXCEPTION 'purchased duration missing';END IF;
  IF p.behavior='homepage_carousel' THEN PERFORM h.capacity FROM twuanis_canonical_private.addon_homepage_capacity h WHERE h.id FOR UPDATE;END IF;
  PERFORM id FROM public.listings WHERE id=p_target FOR UPDATE;
  IF NOT EXISTS(SELECT 1 FROM public.listings WHERE id=p_target AND listing_status='active' AND canonical_domain_version=1 AND owner_id=p_account) THEN RAISE EXCEPTION 'publication required for purchased fulfillment';END IF;
  at_time:=clock_timestamp();
  SELECT greatest(at_time,max(t.ends_at)) INTO term_start FROM twuanis_canonical_private.entitlement_terms t
  WHERE t.listing_id=p_target AND t.product_id=p_product AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.entitlement_revocations r WHERE r.term_id=t.id);
  expires:=CASE WHEN c.calendar_months=1 OR c.id='05000000-0000-4000-8000-000000000103'::uuid THEN ((term_start AT TIME ZONE 'America/Costa_Rica')+interval '1 month') AT TIME ZONE 'America/Costa_Rica' ELSE term_start+c.duration_days*interval '24 hours' END;
  term_id:=twuanis_canonical_private.commit_entitlement_term(p_account,'LISTING_ADDON',p_product,p_configuration,p_target,'PURCHASED',p_purchase,ack,auth.uid(),p_purchase,term_start,expires,NULL,NULL);
  result:=jsonb_build_object('ok',true,'termId',term_id,'listingId',p_target,'activatedAt',term_start,'expiresAt',expires,'behavior',p.behavior);
 ELSIF p.term_kind='lifetime' THEN
  IF p_target<>p_account THEN RAISE EXCEPTION 'account target mismatch';END IF;
  at_time:=clock_timestamp();
  term_id:=twuanis_canonical_private.commit_entitlement_term(p_account,'FOUNDING_MEMBERSHIP',p_product,p_configuration,NULL,'PURCHASED',p_purchase,ack,auth.uid(),p_purchase,at_time,NULL,NULL,NULL);
  result:=jsonb_build_object('ok',true,'termId',term_id,'accountId',p_account,'kind','founding_pricing_entitlement');
 ELSE
  IF NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.addon_import_jobs WHERE id=p_target AND account_id=p_account AND configuration_id=p_configuration) THEN RAISE EXCEPTION 'immutable customer job mismatch'; END IF;
  result:=jsonb_build_object('ok',true,'jobId',p_target,'listings',twuanis_canonical_private.fulfill_customer_addon_import(p_target,p_purchase,p_verified_payment));at_time:=clock_timestamp();
 END IF;
 INSERT INTO twuanis_canonical_private.addon_fulfillments VALUES(p_purchase,p_verified_payment,p_account,p_product,p_configuration,p_target_kind,p_target,p_evidence,result,at_time);
 RETURN result;
END $_$;


--
-- Name: fulfill_customer_addon_import(uuid, uuid, uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.fulfill_customer_addon_import(p_job uuid, p_purchase uuid, p_verified_payment uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE j twuanis_canonical_private.addon_import_jobs%ROWTYPE;r twuanis_canonical_private.addon_import_results%ROWTYPE;x jsonb;created jsonb;published jsonb;result jsonb:='[]';
BEGIN
 IF p_purchase IS NULL OR p_verified_payment IS NULL THEN RAISE EXCEPTION 'trusted purchased terms and verified payment identities required'; END IF;
 -- Only a future trusted payment orchestrator may call this private primitive.
 SELECT * INTO STRICT j FROM twuanis_canonical_private.addon_import_jobs WHERE id=p_job;
 PERFORM twuanis_canonical_private.lock_capacity_policy(false);
 PERFORM id FROM public.publisher_accounts WHERE owner_user_id=j.account_id FOR UPDATE;
 PERFORM id FROM twuanis_canonical_private.addon_import_jobs WHERE id=p_job FOR UPDATE;
 SELECT * INTO r FROM twuanis_canonical_private.addon_import_results WHERE job_id=p_job;
 IF FOUND THEN IF (r.purchase_id,r.verified_payment_id) IS DISTINCT FROM (p_purchase,p_verified_payment) THEN RAISE EXCEPTION 'fulfillment identity conflict'; END IF;RETURN r.result; END IF;
 IF j.total IS NULL OR j.validator_version<>'canonical-customer-v1' THEN RAISE EXCEPTION 'job unpriced or validator unavailable'; END IF;
 -- Lock reference relations through validation and mutation; prevent root-edge phantom changes.
 LOCK TABLE public.ontology_terms,public.ontology_relationships,twuanis_canonical_private.accessibility_identity IN SHARE MODE;
 FOR x IN SELECT value FROM jsonb_array_elements(j.accepted_rows) LOOP PERFORM twuanis_canonical_private.addon_customer_input(x->'input'); END LOOP;
 PERFORM twuanis_canonical_private.addon_publication_capacity(j.account_id,j.accepted_count);
 -- First publisher creation, if needed, happens only after complete job validation.
 PERFORM twuanis_canonical_private.ensure_publisher_account(j.account_id);
 -- Recheck after unique publisher creation contention before the first listing mutation.
 PERFORM twuanis_canonical_private.addon_publication_capacity(j.account_id,j.accepted_count);
 FOR x IN SELECT value FROM jsonb_array_elements(j.accepted_rows) LOOP
  created:=twuanis_canonical_private.s4_create_core(j.account_id,(x->>'rowId')::uuid,x->'input',NULL);
  published:=twuanis_canonical_private.customer_publication_core(j.account_id,(created->>'listing_id')::uuid,(created->>'revision')::bigint,(x->>'publicationRequest')::uuid,'publish');
  IF published->>'outcome' IS NOT NULL AND published->>'outcome' NOT IN ('succeeded','noop') THEN RAISE EXCEPTION 'publication did not succeed'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.listings WHERE id=(created->>'listing_id')::uuid AND owner_id=j.account_id AND listing_status='active' AND canonical_domain_version=1) THEN RAISE EXCEPTION 'batch publication invariant'; END IF;
  result:=result||jsonb_build_array(jsonb_build_object('rowId',x->>'rowId','listingId',created->>'listing_id'));
 END LOOP;
 INSERT INTO twuanis_canonical_private.addon_import_results(job_id,purchase_id,verified_payment_id,result) VALUES(p_job,p_purchase,p_verified_payment,result);
 RETURN result;
END $$;


--
-- Name: guard_account_disposable_write(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.guard_account_disposable_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 PERFORM 1 FROM twuanis_canonical_private.account_principals WHERE id=NEW.user_id AND deleted_at IS NULL FOR SHARE;
 IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=NEW.user_id) THEN RAISE EXCEPTION 'account no longer exists' USING ERRCODE='42501';END IF;
 IF TG_TABLE_NAME='account_profile_images' AND EXISTS(SELECT 1 FROM twuanis_canonical_private.account_deletion_requests WHERE account_id=NEW.user_id) THEN
 IF TG_OP='INSERT' OR NEW.state NOT IN('RETIRED','DELETED') THEN RAISE EXCEPTION 'account disposal in progress' USING ERRCODE='42501';END IF;END IF;
 RETURN NEW;END$$;


