--
-- Name: guard_auth_account_deletion(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.guard_auth_account_deletion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 PERFORM twuanis_canonical_private.assert_account_deletable(OLD.id);
 PERFORM 1 FROM twuanis_canonical_private.account_principals WHERE id=OLD.id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='profile-images' AND split_part(name,'/',1)=OLD.id::text) THEN RAISE EXCEPTION 'remove profile images through supported Storage API first';END IF;
 INSERT INTO twuanis_canonical_private.account_deletion_requests(account_id,request_id,storage_ready_at)
 VALUES(OLD.id,gen_random_uuid(),clock_timestamp()) ON CONFLICT(account_id) DO UPDATE SET storage_ready_at=coalesce(account_deletion_requests.storage_ready_at,clock_timestamp());
 UPDATE twuanis_canonical_private.account_principals SET deleted_at=clock_timestamp() WHERE id=OLD.id AND deleted_at IS NULL;
 -- Revoke access; historical grant identities remain independently attributable.
 UPDATE twuanis_canonical_private.administrators SET active=false WHERE user_id=OLD.id;
 DELETE FROM twuanis_canonical_private.administrative_permission_grants WHERE user_id=OLD.id;
 UPDATE twuanis_canonical_private.administrative_access_grants SET revoked_at=clock_timestamp(),revoked_by=session_user WHERE user_id=OLD.id AND revoked_at IS NULL;
 DELETE FROM public.payment_reviewers WHERE user_id=OLD.id;
 -- Dedicated disposal exception only during this Auth-delete transaction.
 DELETE FROM twuanis_canonical_private.account_profiles WHERE user_id=OLD.id;
 DELETE FROM twuanis_canonical_private.account_image_operations WHERE user_id=OLD.id;
 DELETE FROM twuanis_canonical_private.account_profile_images WHERE user_id=OLD.id;
 DELETE FROM twuanis_canonical_private.account_request_receipts WHERE user_id=OLD.id;
 DELETE FROM twuanis_canonical_private.account_security_events WHERE user_id=OLD.id;
 DELETE FROM twuanis_canonical_private.account_phone_state WHERE user_id=OLD.id;
 DELETE FROM twuanis_canonical_private.confirmed_account_notifications WHERE account_id=OLD.id;
 UPDATE twuanis_canonical_private.account_deletion_requests SET completed_at=clock_timestamp() WHERE account_id=OLD.id;
 RETURN OLD;END$$;


