--
-- Name: guard_complete_publication_geography(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.guard_complete_publication_geography() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE l public.listings; codes jsonb; ids bigint[]; actual bigint[]; n integer; p text;c text;d text;
 external_source boolean; customer_publication boolean;
BEGIN
 SELECT * INTO l FROM public.listings WHERE id=NEW.id;
 IF NOT FOUND OR l.listing_status IS DISTINCT FROM 'active' THEN RETURN NULL;END IF;
 external_source:=l.listing_origin='imported'
   AND l.listing_source_type IS NOT NULL AND l.listing_source_type<>'customer'
   AND l.source_name IS NOT NULL AND l.source_listing_id IS NOT NULL;
 SELECT EXISTS(
  SELECT 1 FROM public.listing_lifecycle_events e
  WHERE e.listing_id=l.id AND e.listing_revision=l.canonical_revision
   AND e.actor_kind='owner' AND e.event_type IN ('publish','renew')
 ) INTO customer_publication;
 IF external_source AND NOT customer_publication THEN RETURN NULL; END IF;
 IF l.canonical_domain_version IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'CANONICAL_PUBLICATION_GEOGRAPHY_REQUIRED' USING ERRCODE='23514';END IF;
 SELECT count(*),array_agg(t.id ORDER BY t.level),jsonb_object_agg(t.term_type,t.official_code)
 INTO n,actual,codes FROM public.listing_membership_origins o JOIN public.ontology_terms t ON t.id=o.ontology_term_id WHERE o.listing_id=l.id AND o.origin_domain='geography'AND t.term_type IN('province','canton','district');
 IF n<>3 OR codes->>'province'IS NULL OR codes->>'canton'IS NULL OR codes->>'district'IS NULL THEN RAISE EXCEPTION 'CANONICAL_PUBLICATION_GEOGRAPHY_REQUIRED' USING ERRCODE='23514';END IF;
 BEGIN ids:=twuanis_canonical_private.s3_geography(codes);
 EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'CANONICAL_PUBLICATION_GEOGRAPHY_REQUIRED' USING ERRCODE='23514';END;
 IF cardinality(ids)<>3 OR actual IS DISTINCT FROM ids THEN RAISE EXCEPTION 'CANONICAL_PUBLICATION_GEOGRAPHY_REQUIRED' USING ERRCODE='23514';END IF;
 SELECT term_name INTO p FROM public.ontology_terms WHERE id=ids[1];SELECT term_name INTO c FROM public.ontology_terms WHERE id=ids[2];SELECT term_name INTO d FROM public.ontology_terms WHERE id=ids[3];
 IF (l.province,l.canton,l.district,l.province_normalized,l.canton_normalized,l.district_normalized)IS DISTINCT FROM(p,c,d,twuanis_private.normalize_geographic_projection(p),twuanis_private.normalize_geographic_projection(c),twuanis_private.normalize_geographic_projection(d))
 OR (SELECT count(*)FROM public.listings_ontology_terms WHERE listing_id=l.id AND ontology_term_id=ANY(ids))<>3 THEN RAISE EXCEPTION 'CANONICAL_PUBLICATION_GEOGRAPHY_REQUIRED' USING ERRCODE='23514';END IF;
 RETURN NULL;
END $$;


