--
-- Name: guard_duplicate_admission(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.guard_duplicate_admission() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE d jsonb; final_row public.listings; BEGIN
 SELECT * INTO final_row FROM public.listings WHERE id=NEW.id; IF NOT FOUND THEN RETURN NULL; END IF;
 NEW:=final_row;
 IF NEW.canonical_domain_version=1 AND NEW.listing_status='active' THEN
  d:=twuanis_canonical_private.decide_listing_admission(to_jsonb(NEW),gen_random_uuid(),'admission-guard',false);
  IF d->>'admission'<>'ALLOW' THEN RAISE EXCEPTION 'Canonical duplicate admission requires retained decision' USING ERRCODE='23514'; END IF;
 END IF; RETURN NEW;
END $$;


