 IF NEW.listing_status='active' AND OLD.listing_status IS DISTINCT FROM 'active' AND EXISTS(SELECT 1 FROM twuanis_canonical_private.duplicate_commands WHERE listing_id=NEW.id AND NOT completed) THEN
