--
-- Name: guard_legacy_package_transition(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.guard_legacy_package_transition() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.package_access_transition WHERE singleton) THEN RETURN NEW;END IF;
 IF EXISTS(SELECT 1 FROM public.packages WHERE id=NEW.package_id AND slug='market-pricing-intelligence') THEN
  IF TG_OP='INSERT' THEN RAISE EXCEPTION 'legacy acquisition closed';END IF;
  IF (NEW.id,NEW.user_id,NEW.package_id,NEW.current_period_start,NEW.current_period_end,NEW.started_at) IS DISTINCT FROM (OLD.id,OLD.user_id,OLD.package_id,OLD.current_period_start,OLD.current_period_end,OLD.started_at)
   OR (NEW.status='active' AND OLD.status<>'active')
   OR (OLD.cancelled_at IS NOT NULL AND NEW.cancelled_at IS NULL)
   OR (OLD.expired_at IS NOT NULL AND NEW.expired_at IS NULL)
  THEN RAISE EXCEPTION 'legacy renewal or reactivation closed';END IF;
 END IF;
 RETURN NEW;
END$$;


--
-- Name: guard_listing_price_integrity(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.guard_listing_price_integrity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE decision jsonb; final_row public.listings;
BEGIN
 -- Validate final transaction state: the existing atomic edit writes money then text.
 SELECT * INTO final_row FROM public.listings WHERE id=NEW.id;
 IF NOT FOUND THEN RETURN NULL;END IF;
 IF final_row.canonical_domain_version IS DISTINCT FROM 1 THEN
  IF final_row.listing_status='active'AND(TG_OP='INSERT'OR OLD.listing_status IS DISTINCT FROM 'active'OR(final_row.current_price,final_row.monthly_price,final_row.currency,final_row.title,final_row.description)IS DISTINCT FROM(OLD.current_price,OLD.monthly_price,OLD.currency,OLD.title,OLD.description))THEN RAISE EXCEPTION 'PRICE_INTEGRITY_REJECTED: PRICE_CANONICAL_IDENTITY_REQUIRED' USING ERRCODE='23514';END IF;
  RETURN NULL;
 END IF;
 IF TG_OP='UPDATE'AND OLD.canonical_domain_version=1 AND
 (final_row.transaction_type,final_row.current_price,final_row.monthly_price,final_row.currency,final_row.title,final_row.description,final_row.last_scraped)IS NOT DISTINCT FROM(OLD.transaction_type,OLD.current_price,OLD.monthly_price,OLD.currency,OLD.title,OLD.description,OLD.last_scraped)
 AND NOT(final_row.listing_status='active'AND(OLD.listing_status IS DISTINCT FROM 'active'OR final_row.publication_expires_at IS DISTINCT FROM OLD.publication_expires_at))THEN RETURN NULL;END IF;
 decision:=twuanis_canonical_private.decide_listing_price(final_row);
 IF decision->>'status'<>'APPROVED'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='PRICE_INTEGRITY_REJECTED: '||(decision->'reasons')::text,DETAIL=decision::text;END IF;
 RETURN NULL;
END $$;


--
-- Name: guard_live_administrative_identity(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.guard_live_administrative_identity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v uuid:=CASE WHEN TG_OP='DELETE' THEN OLD.user_id ELSE NEW.user_id END;BEGIN
 PERFORM pg_advisory_xact_lock(3110,1);
 IF TG_OP<>'DELETE' AND NOT EXISTS(SELECT 1 FROM auth.users WHERE id=v) THEN RAISE EXCEPTION 'historical identity cannot receive administrative authority';END IF;
 IF TG_OP<>'DELETE' AND EXISTS(SELECT 1 FROM twuanis_canonical_private.account_deletion_requests WHERE account_id=v) AND NOT twuanis_canonical_private.account_deletion_purge_allowed(v) THEN RAISE EXCEPTION 'pending deletion cannot receive administrative authority';END IF;
 IF TG_TABLE_NAME='administrators' THEN
 IF TG_OP<>'INSERT' AND OLD.active AND(TG_OP='DELETE' OR NOT NEW.active) THEN
 IF NOT EXISTS(SELECT 1 FROM auth.users u WHERE u.id<>v AND(
 EXISTS(SELECT 1 FROM twuanis_canonical_private.administrators a WHERE a.user_id=u.id AND a.active)
 OR EXISTS(SELECT 1 FROM twuanis_canonical_private.owner_access_grants o WHERE o.user_id=u.id AND o.revoked_at IS NULL)
 OR EXISTS(SELECT 1 FROM twuanis_canonical_private.top_administrator t WHERE t.user_id=u.id))) THEN RAISE EXCEPTION 'last administrator protected';END IF;END IF;END IF;
 IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;END$$;


--
-- Name: guard_new_historical_reference(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.guard_new_historical_reference() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE col text;v uuid;BEGIN
 FOREACH col IN ARRAY TG_ARGV LOOP
 IF TG_OP='UPDATE' AND (to_jsonb(NEW)->col) IS NOT DISTINCT FROM(to_jsonb(OLD)->col) THEN CONTINUE;END IF;
 v:=nullif(to_jsonb(NEW)->>col,'')::uuid;
 IF v IS NOT NULL THEN
 PERFORM 1 FROM twuanis_canonical_private.account_principals p JOIN auth.users u ON u.id=p.id WHERE p.id=v AND p.deleted_at IS NULL FOR KEY SHARE OF p;
 IF NOT FOUND THEN RAISE EXCEPTION 'historical identity cannot acquire new authority' USING ERRCODE='42501';END IF;END IF;
 END LOOP;RETURN NEW;END$$;


