--
-- Name: initialize_capacity_guard(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.initialize_capacity_guard() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
 IF current_setting('transaction_isolation') <> 'read committed' THEN
  RAISE EXCEPTION 'coordination requires READ COMMITTED' USING ERRCODE='0A000';
 END IF;
 INSERT INTO public.capacity_policy_guard(id) VALUES(1) ON CONFLICT(id) DO NOTHING;
END $$;


--
-- Name: listing_admission_report_rows(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.listing_admission_report_rows() RETURNS TABLE(id uuid, listing_id uuid, case_id uuid, created_at timestamp with time zone, outcome text, status text, source_name text, source_evidence_id uuid, proposed jsonb, candidates jsonb)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT s.listing_id,s.listing_id,NULL::uuid,s.created_at,'ACCEPTED'::text,'ACCEPTED'::text,s.source_name,s.source_evidence_id,s.proposed,'[]'::jsonb FROM twuanis_canonical_private.listing_admission_successes s

 UNION ALL
 SELECT d.id,d.listing_id,c.id,d.created_at,d.outcome,c.status,CASE WHEN d.proposed->>'owner_id'IS NOT NULL THEN 'customer'ELSE coalesce(d.proposed->>'source_name',d.proposed->>'listing_origin')END,NULL::uuid,d.proposed,d.candidates
 FROM twuanis_canonical_private.listing_duplicate_cases c JOIN twuanis_canonical_private.listing_admission_decisions d ON d.id=c.current_admission_id
 WHERE NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.listing_admission_successes s WHERE s.listing_id=d.listing_id AND(s.created_at>=d.created_at OR c.status IN('DIFFERENT_PROPERTIES','NO_MATCH_AFTER_REVISION')));
$$;


--
-- Name: administrative_import_operations; Type: TABLE; Schema: twuanis_canonical_private; Owner: -
--

CREATE TABLE twuanis_canonical_private.administrative_import_operations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    actor_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    evidence_id uuid,
    input_snapshot jsonb,
    result jsonb
);


--
-- Name: lock_administrative_import(uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.lock_administrative_import(p_operation uuid) RETURNS twuanis_canonical_private.administrative_import_operations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE r twuanis_canonical_private.administrative_import_operations%ROWTYPE;
BEGIN
 IF auth.jwt()->>'role' IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'administrative access denied' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(3110,1);
 SELECT * INTO r FROM twuanis_canonical_private.administrative_import_operations WHERE id=p_operation FOR UPDATE;
 IF NOT FOUND OR r.created_at < clock_timestamp()-interval '5 minutes' OR NOT twuanis_canonical_private.administrative_permission(r.actor_id,'imports.manage') THEN RAISE EXCEPTION 'administrative access denied' USING ERRCODE='42501'; END IF;
 RETURN r;
END $$;


--
-- Name: lock_capacity_policy(boolean); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.lock_capacity_policy(p_exclusive boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
 IF current_setting('transaction_isolation') <> 'read committed' THEN
  RAISE EXCEPTION 'coordination requires READ COMMITTED' USING ERRCODE='0A000';
 END IF;
 IF p_exclusive IS NULL THEN RAISE EXCEPTION 'policy lock mode required' USING ERRCODE='22023'; END IF;
 IF p_exclusive THEN
  PERFORM id FROM public.capacity_policy_guard WHERE id=1 FOR UPDATE;
 ELSE
  PERFORM id FROM public.capacity_policy_guard WHERE id=1 FOR SHARE;
 END IF;
 IF NOT FOUND THEN RAISE EXCEPTION 'capacity guard missing' USING ERRCODE='55000'; END IF;
END $$;


--
-- Name: lock_package_coverage_change(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.lock_package_coverage_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a uuid;p text;r record;
BEGIN
 IF TG_TABLE_NAME='entitlement_terms' THEN
 IF NEW.product_class<>'PACKAGE' THEN RETURN NEW;END IF;a:=NEW.account_id;p:=NEW.product_id;
 ELSIF TG_TABLE_NAME='entitlement_revocations' THEN
 SELECT account_id,product_id INTO a,p FROM twuanis_canonical_private.entitlement_terms WHERE id=NEW.term_id AND product_class='PACKAGE';
 ELSE
 -- Subscription mutations serialize with Package purchases before legacy eligibility changes.
 FOR r IN SELECT DISTINCT g.account_id,c.id FROM twuanis_canonical_private.legacy_package_access g CROSS JOIN twuanis_canonical_private.intelligence_packages c
 WHERE g.subscription_id=OLD.id ORDER BY g.account_id,c.id LOOP
 PERFORM pg_advisory_xact_lock(3254,hashtext(r.account_id::text||':'||r.id));END LOOP;
 IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;
 END IF;
 IF a IS NOT NULL THEN PERFORM pg_advisory_xact_lock(3254,hashtext(a::text||':'||p));END IF;RETURN NEW;
END$$;


--
-- Name: lock_publisher(uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.lock_publisher(p_publisher uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE v_owner uuid;
BEGIN
 PERFORM twuanis_canonical_private.lock_capacity_policy(false);
 SELECT owner_user_id INTO v_owner FROM public.publisher_accounts WHERE id=p_publisher FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'publisher not found' USING ERRCODE='P0002'; END IF;
 RETURN v_owner;
END $$;


--
-- Name: marketplace_label(text); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.marketplace_label(v text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$ SELECT lower(btrim(regexp_replace(replace(translate(regexp_replace(coalesce(v,''),'[''’`]', '', 'g'),'áéíóúüñÁÉÍÓÚÜÑ','aeiouunAEIOUUN'),'-',' '),'\s+',' ','g'))) $$;


--
-- Name: marketplace_matches(jsonb, jsonb, text, numeric); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.marketplace_matches(p jsonb, f jsonb, tx text, fx numeric) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE k text;v jsonb;wanted text;actual text;n numeric;required numeric;lo numeric;hi numeric;amount numeric;currency text;yr integer;
BEGIN
 FOR k,v IN SELECT * FROM jsonb_each(f) LOOP
  IF v='null'::jsonb OR v='""'::jsonb OR v='[]'::jsonb THEN CONTINUE;END IF;
  IF(k='monthly_price' AND tx<>'rent') OR(k='price_range' AND tx='rent') THEN CONTINUE;END IF;
  IF k='distance_to_paved_road_range' AND f->>'accessibility' IS DISTINCT FROM 'Unpaved Road to Property' THEN CONTINUE;END IF;
  wanted:=twuanis_canonical_private.marketplace_label(v#>>'{}');actual:=twuanis_canonical_private.marketplace_label(p->>k);
  IF k IN('province','canton','district','property_type','use_type','legal_status','distance_to_paved_road_range') THEN
   IF k='province' THEN actual:=replace(actual,' provincia','');END IF;
   IF actual<>wanted AND NOT(k='canton' AND wanted='san jose' AND actual LIKE '%san jo%') THEN RETURN false;END IF;
  ELSIF k='bathrooms' AND p->>'canonical_domain_version'='1' THEN
   required:=substring(wanted FROM '[0-9]+(?:\.[0-9]+)?')::numeric;
   IF required IS NULL THEN RETURN false;END IF;
   actual:=p->'bathroom_evidence'->>'kind';
   IF actual='exact' THEN n:=(p->'bathroom_evidence'->>'exact_value')::numeric;
   ELSIF actual='category' THEN n:=CASE p->'bathroom_evidence'->>'category_term_id' WHEN '1127' THEN 1 WHEN '1128' THEN 2 WHEN '1129' THEN 3 WHEN '1130' THEN 4 WHEN '1131' THEN 5 ELSE NULL END;
   ELSIF actual='range' THEN n:=(p->'bathroom_evidence'->>'range_lower')::numeric;
   ELSE RETURN false;END IF;
   -- Full evidence containment in the inclusive minimum interval; never an endpoint displayed as exact.
   IF n IS NULL OR n<required THEN RETURN false;END IF;
  ELSIF k IN('bedrooms','bathrooms','parking') THEN
   required:=substring(replace(wanted,',','') FROM '[0-9]+(?:\.[0-9]+)?')::numeric;n:=substring(replace(actual,',','') FROM '[0-9]+(?:\.[0-9]+)?')::numeric;
   IF n IS NULL OR required IS NULL OR n<required THEN RETURN false;END IF;
  ELSIF k='year_built' THEN
   yr:=substring(coalesce(p->>'year_built',p->>'year_built_range','') FROM '(?:19|20)[0-9]{2}')::integer;
   IF yr IS NULL OR NOT (CASE wanted WHEN 'pre 1980' THEN yr<1980 WHEN '1980s' THEN yr BETWEEN 1980 AND 1989 WHEN '1990s' THEN yr BETWEEN 1990 AND 1999 WHEN '2000s' THEN yr BETWEEN 2000 AND 2009 WHEN '2010s' THEN yr BETWEEN 2010 AND 2019 WHEN '2020+' THEN yr>=2020 ELSE false END) THEN RETURN false;END IF;
  ELSIF k IN('utility','environment','terrain','accessibility') THEN
   IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v)='array' THEN v ELSE jsonb_build_array(v) END)w WHERE EXISTS(SELECT 1 FROM regexp_split_to_table(CASE WHEN jsonb_typeof(p->k)='array' THEN (SELECT string_agg(x,'|') FROM jsonb_array_elements_text(p->k)x) ELSE p->>k END,'[|,;]')a WHERE twuanis_canonical_private.marketplace_label(a)=twuanis_canonical_private.marketplace_label(w))) THEN RETURN false;END IF;
  ELSIF k IN('property_area','construction_area') THEN
   actual:=regexp_replace(replace(coalesce(p->>k,''),',',''),'\s*m²\s*$','','i');IF actual !~ '^[0-9]+(\.[0-9]+)?$' THEN RETURN false;END IF;n:=actual::numeric;
   IF NOT (CASE wanted WHEN '<1,000m²' THEN n<1000 WHEN '1,000–10,000m²' THEN n>=1000 AND n<10000 WHEN '10,000–50,000m²' THEN n>=10000 AND n<50000 WHEN '50,000m²+' THEN n>=50000 WHEN 'mas de 50,000m²' THEN n>=50000 WHEN '<50m²' THEN n<50 WHEN '50 100m²' THEN n>=50 AND n<100 WHEN '100 200m²' THEN n>=100 AND n<200 WHEN '200 400m²' THEN n>=200 AND n<400 WHEN '400m²+' THEN n>=400 ELSE false END) THEN RETURN false;END IF;
  ELSIF k IN('price_range','monthly_price') THEN
   currency:=CASE WHEN p->>'canonical_domain_version'='1' OR tx='bank' THEN p->>'currency' ELSE upper(btrim(p->>'currency')) END;
   IF tx='bank' THEN amount:=(p->>'amount')::numeric;
   ELSIF tx='rent' THEN amount:=(p->>'monthly_price')::numeric;
   ELSIF (p->>'canonical_domain_version')='1' THEN amount:=(p->>'current_price')::numeric;
   ELSE amount:=CASE WHEN (p->>'current_price')::numeric>1 THEN (p->>'current_price')::numeric ELSE (p->>'price_millions')::numeric*1000000 END;END IF;
   IF amount IS NULL OR amount<=0 OR currency IS NULL OR currency NOT IN('CRC','USD') THEN RETURN false;END IF;
   IF (tx IN('sale','bank') AND currency='USD') OR(tx='rent' AND currency='CRC') THEN IF fx IS NULL OR fx<=0 THEN RETURN false;END IF;amount:=CASE WHEN tx='rent' THEN amount/fx ELSE amount*fx END;END IF;
   SELECT x.l,x.h INTO lo,hi FROM (VALUES ('₡0 - ₡25M',0::numeric,25000000::numeric),('₡25M - ₡75M',25000000,75000000),('₡75M - ₡150M',75000000,150000000),('₡150M - ₡250M',150000000,250000000),('₡250M+',250000000,NULL),('₡250M - ₡500M',250000000,500000000),('₡500M - ₡1B',500000000,1000000000),('₡1B+',1000000000,NULL),('$0 - $500/mo',0,500),('$500 - $1K/mo',500,1000),('$1K - $2K/mo',1000,2000),('$2K - $5K/mo',2000,5000),('$5K+/mo',5000,NULL))x(key,l,h) WHERE x.key=v#>>'{}';
   IF lo IS NULL OR amount<lo OR(hi IS NOT NULL AND CASE WHEN tx='rent' THEN amount>hi ELSE amount>=hi END) THEN RETURN false;END IF;
  ELSE RETURN false;END IF;
 END LOOP;RETURN true;
END$_$;


--
-- Name: membership_duration(jsonb); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.membership_duration(p_terms jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
SELECT coalesce(jsonb_object_agg(key,value),'{}'::jsonb) FROM jsonb_each(p_terms) WHERE key IN('unit','quantity','durationDays','kind')$$;


--
-- Name: membership_introductory_price(uuid, text, text, text, timestamp with time zone, jsonb, integer, text, jsonb); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.membership_introductory_price(p_account uuid, p_kind text, p_product text, p_currency text, p_at timestamp with time zone, p_duration jsonb, p_quantity integer, p_population text, p_terms jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m record;p record;converted numeric;rate numeric;BEGIN
 IF p_currency IS NULL OR p_currency NOT IN('USD','CRC') OR p_at IS NULL OR NOT isfinite(p_at) OR p_quantity IS NULL OR p_quantity<1 THEN RAISE EXCEPTION 'typed protected quote required';END IF;
 SELECT e.id,e.account_id,e.starts_at,s.policy_version INTO m FROM twuanis_canonical_private.entitlement_terms e JOIN twuanis_canonical_private.founding_membership_capacity s ON s.term_id=e.id
 WHERE e.account_id=p_account AND e.product_class='FOUNDING_MEMBERSHIP' AND e.starts_at<=p_at AND e.ends_at IS NULL AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.entitlement_revocations r WHERE r.term_id=e.id AND r.revoked_at<=p_at) ORDER BY e.starts_at,e.id LIMIT 1;
 IF NOT FOUND THEN RETURN NULL;END IF;
 BEGIN
 SELECT * INTO STRICT p FROM twuanis_canonical_private.membership_introductory_prices x WHERE x.policy_version=m.policy_version AND x.kind=p_kind AND x.product_id=p_product AND x.duration=p_duration AND p_quantity BETWEEN x.quantity_lower AND x.quantity_upper AND x.population=p_population AND x.commercial_terms=p_terms;
 EXCEPTION WHEN NO_DATA_FOUND THEN RETURN NULL;END;
 converted:=p.amount;
 IF p.currency<>p_currency THEN
 SELECT r.rate INTO rate FROM public.fx_rates r WHERE r.base_currency='USD' AND r.quote_currency='CRC' AND r.source='BCCR' AND r.rate_type='reference_sale' AND r.effective_date<=(p_at AT TIME ZONE 'America/Costa_Rica')::date ORDER BY r.effective_date DESC LIMIT 1;
 IF rate IS NULL OR rate<=0 THEN RAISE EXCEPTION 'canonical BCCR rate required';END IF;
 converted:=CASE WHEN p.currency='USD' THEN round(p.amount*rate,0) ELSE round(p.amount/rate,2) END;
 END IF;
 RETURN jsonb_build_object('priceIdentity',p.id,'policyVersion',m.policy_version,'membershipId',m.id,'purchaser',m.account_id,'activatedAt',m.starts_at,'productId',p.product_id,'currency',p_currency,'originalCurrency',p.currency,'originalAmount',p.amount::text,'unitAmount',converted::text,'quantity',p_quantity,'total',(converted*p_quantity)::text,'duration',p.duration,'quantityLower',p.quantity_lower,'quantityUpper',p.quantity_upper,'commercialTerms',p.commercial_terms,'population',p.population,'originalPriceVersion',p.original_price_version,'sourceEvidence',p.source_evidence);
END$$;


--
-- Name: new_membership_quote(text, timestamp with time zone); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.new_membership_quote(p_currency text, p_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE p twuanis_canonical_private.founding_membership_policies%ROWTYPE;rate numeric;total numeric;BEGIN
 SELECT * INTO STRICT p FROM twuanis_canonical_private.founding_membership_policies WHERE version='cr-intro-life-2000-v1';
 IF p_currency NOT IN('USD','CRC') OR p_currency IS NULL OR p_at IS NULL OR NOT isfinite(p_at) THEN RAISE EXCEPTION 'typed membership quote required';END IF;
 total:=p.usd_price;
 IF p_currency='CRC' THEN SELECT r.rate INTO rate FROM public.fx_rates r WHERE r.base_currency='USD' AND r.quote_currency='CRC' AND r.rate_type='reference_sale' AND r.source='BCCR' AND r.effective_date<=(p_at AT TIME ZONE 'America/Costa_Rica')::date ORDER BY r.effective_date DESC LIMIT 1;
 IF rate IS NULL OR rate<=0 THEN RAISE EXCEPTION 'canonical BCCR rate required';END IF;total:=round(total*rate,0);END IF;
 RETURN jsonb_build_object('available',true,'targetType','addon','productId',p.product_id,'configurationId',p.configuration_id,'currency',p_currency,'priceShape','scalar','quantity',1,'standardRate',total::text,'effectiveRate',total::text,'total',total::text,'source','STANDARD','offerEnd',NULL,'membershipPolicyVersion',p.version,'capacity',p.capacity,'terms',jsonb_build_object('kind','lifetime','durationDays',NULL,'behavior','founding_pricing_entitlement','membershipPolicyVersion',p.version),'resolvedAt',p_at,'currencyQuotes',jsonb_build_object('USD',jsonb_build_object('total',p.usd_price::text),'CRC',jsonb_build_object('total',CASE WHEN p_currency='CRC'THEN total::text ELSE NULL END)))||CASE WHEN p_currency='CRC' THEN jsonb_build_object('fx',jsonb_build_object('rate',rate,'source','BCCR','rateType','reference_sale'))ELSE '{}'::jsonb END;
END$$;


--
-- Name: offer_order_state(uuid, timestamp with time zone); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.offer_order_state(p_order uuid, p_at timestamp with time zone) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT CASE WHEN EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_paid_acknowledgements WHERE order_id=o.id) THEN 'paid' WHEN p_at>=o.payment_deadline THEN 'expired' ELSE 'pending' END
 FROM twuanis_canonical_private.offer_order_snapshots o WHERE o.id=p_order
$$;


--
-- Name: offer_projection(uuid, timestamp with time zone); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.offer_projection(oid uuid, at_time timestamp with time zone) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT jsonb_build_object('id',o.id,'targetType',CASE WHEN o.package_id IS NOT NULL THEN 'package' ELSE 'addon' END,
 'targetId',coalesce(o.package_id,o.addon_id),'state',twuanis_canonical_private.offer_status(o.state,c.starts_at,c.ends_at,at_time),
 'administrativeState',o.state,'revision',o.revision::text,'configurationId',c.id,'version',c.version::text,
 'name_en',c.name_en,'name_es',c.name_es,'description_en',c.description_en,'description_es',c.description_es,
 'startsAt',c.starts_at,'endsAt',c.ends_at,'priceShape',c.price_shape,
 'prices',coalesce((SELECT jsonb_object_agg(currency,amount::text) FROM twuanis_canonical_private.offer_scalar_prices WHERE configuration_id=c.id),'{}'),
 'tiers',coalesce((SELECT jsonb_agg(jsonb_build_object('min',lower_quantity,'max',upper_quantity,'currency',currency,'unitRate',unit_rate::text) ORDER BY lower_quantity) FROM twuanis_canonical_private.offer_quantity_tiers WHERE configuration_id=c.id),'[]'))
 FROM twuanis_canonical_private.offers o JOIN twuanis_canonical_private.offer_configurations c ON c.id=o.current_configuration_id WHERE o.id=oid
$$;


--
-- Name: offer_status(text, timestamp with time zone, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.offer_status(s text, b timestamp with time zone, e timestamp with time zone, at_time timestamp with time zone) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT CASE WHEN s='archived' THEN 'archived' WHEN s='draft' THEN 'draft' WHEN s='ended' OR at_time>e THEN 'ended' WHEN at_time<b THEN 'scheduled' ELSE 'active' END
$$;


--
-- Name: orchestrator_bank_scope_page(jsonb, uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.orchestrator_bank_scope_page(p_scope jsonb, p_after uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE rows jsonb;geo_input record;geo_row public.ontology_terms%ROWTYPE;BEGIN

 IF jsonb_typeof(p_scope) IS DISTINCT FROM 'object' OR (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(p_scope)k) IS DISTINCT FROM ARRAY['geography','propertyType','transaction'] OR p_scope->>'transaction'<>'bank' OR p_scope->>'transaction' IS NULL OR jsonb_typeof(p_scope->'geography') IS DISTINCT FROM 'object' OR (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(p_scope->'geography')k) IS DISTINCT FROM ARRAY['canton','district','province'] THEN RAISE EXCEPTION 'Canonical scope required';END IF;
 IF p_scope#>>'{geography,district}' IS NOT NULL AND p_scope#>>'{geography,canton}' IS NULL OR p_scope#>>'{geography,canton}' IS NOT NULL AND p_scope#>>'{geography,province}' IS NULL THEN RAISE EXCEPTION 'Canonical geographic ancestry required';END IF;
 IF jsonb_typeof(p_scope->'propertyType') IS DISTINCT FROM 'string' OR NOT EXISTS(SELECT 1 FROM public.ontology_terms t WHERE t.id::text=p_scope->>'propertyType' AND t.term_type='property_type' AND t.level=1) THEN RAISE EXCEPTION 'Canonical property type required';END IF;
 FOR geo_input IN SELECT key,value FROM jsonb_each_text(p_scope->'geography') LOOP
 IF geo_input.value IS NULL THEN CONTINUE;END IF;
 SELECT * INTO geo_row FROM public.ontology_terms WHERE id::text=geo_input.value;
 IF NOT FOUND OR geo_row.term_type<>geo_input.key OR geo_row.level<>(CASE geo_input.key WHEN 'province' THEN 1 WHEN 'canton' THEN 2 ELSE 3 END) OR geo_row.official_code IS NULL OR geo_row.official_code!~(CASE geo_input.key WHEN 'province' THEN '^[0-9]$' WHEN 'canton' THEN '^[0-9]{3}$' ELSE '^[0-9]{5}$' END) THEN RAISE EXCEPTION 'Canonical geographic identity required';END IF;
 IF geo_input.key='canton' AND (geo_row.parent_id::text IS DISTINCT FROM p_scope#>>'{geography,province}' OR left(geo_row.official_code,1) IS DISTINCT FROM(SELECT official_code FROM public.ontology_terms WHERE id=geo_row.parent_id)) OR geo_input.key='district' AND(geo_row.parent_id::text IS DISTINCT FROM p_scope#>>'{geography,canton}' OR left(geo_row.official_code,3) IS DISTINCT FROM(SELECT official_code FROM public.ontology_terms WHERE id=geo_row.parent_id)) THEN RAISE EXCEPTION 'Canonical geography mismatch';END IF;
 END LOOP;
 WITH canonical_visibility AS MATERIALIZED (SELECT id,twuanis_remates_private.publication_visibility(id) value FROM twuanis_remates_private.listings), canonical_public AS MATERIALIZED (SELECT l.id,
 l.revision::text AS revision,
 l.offering_id,
 i.id AS institution_id,
 i.legal_name AS institution,
 COALESCE(fe.mechanism, 'UNKNOWN'::text) AS mechanism,
 l.state,
 vis.value ->> 'label'::text AS visibility_label,
 CASE
 WHEN COALESCE(( SELECT d.publication_model
 FROM twuanis_remates_private.independent_source_decisions d
 WHERE d.source_id = s.id
 ORDER BY d.revision DESC
 LIMIT 1), 'REVIEWED_SOURCE_CONTENT'::text) = 'FACTUAL_ONLY'::text THEN ''::text
 ELSE COALESCE(( SELECT "left"(f.raw_value, 256) AS "left"
 FROM twuanis_remates_private.observation_fields f
 WHERE f.observation_id = ob.id AND f.field_path = 'title'::text AND f.validation = 'VALID'::text
 ORDER BY f.ordinal
 LIMIT 1), ''::text)
 END AS title,
 s.namespace AS source_name,
 CASE
 WHEN ob.source_url ~~ 'https://%'::text AND twuanis_remates_private.valid_evidence_locator(s.id, ob.source_url) THEN ob.source_url
 ELSE NULL::text
 END AS source_url,
 fv.amount::text AS amount,
 fv.currency,
 fv.kind AS financial_kind,
 fv.original_label AS financial_label,
 fv.round_key AS auction_round,
 pub.recorded_at AS published_at,
 ( SELECT jsonb_agg(jsonb_build_object('id', p.id, 'terms', ( SELECT COALESCE(jsonb_agg(jsonb_build_object('id', t.id::text, 'type', t.term_type, 'parent', t.parent_id::text, 'en', COALESCE(to_jsonb(t.*) ->> 'term_name_en'::text, t.term_name), 'es', COALESCE(to_jsonb(t.*) ->> 'term_name_es'::text, t.term_name)) ORDER BY t.id), '[]'::jsonb) AS "coalesce"
 FROM twuanis_remates_private.property_terms pt
 JOIN public.ontology_terms t ON t.id = pt.term_id
 WHERE pt.classification_id = c.id AND pt.selected AND (t.term_type = ANY (ARRAY['province'::text, 'canton'::text, 'district'::text, 'property_type'::text]))), 'area', ( SELECT property_facts.exact_value::text AS exact_value
 FROM twuanis_remates_private.property_facts
 WHERE property_facts.classification_id = c.id AND property_facts.dimension = 'property_area'::text AND property_facts.kind = 'exact'::text), 'construction_area', ( SELECT pf.exact_value::text AS exact_value
 FROM twuanis_remates_private.property_facts pf
 WHERE pf.classification_id = c.id AND pf.dimension = 'construction_area'::text AND pf.kind = 'exact'::text AND pf.exact_value > 0::numeric), 'images',
 CASE
 WHEN s.namespace = 'bp-inventory'::text AND s.origin_host = 'srv.bancopopular.fi.cr'::text AND twuanis_remates_private.independent_source_allowed(s.id) AND COALESCE(( SELECT d.public_image_display
 FROM twuanis_remates_private.independent_source_decisions d
 WHERE d.source_id = s.id
 ORDER BY d.revision DESC
 LIMIT 1), false) AND (( SELECT count(*) AS count
 FROM twuanis_remates_private.offering_properties single_property
 WHERE single_property.offering_id = o.id)) = 1 THEN COALESCE(( SELECT jsonb_agg(ref.source_url ORDER BY ref.ordinal, ref.id) AS jsonb_agg
 FROM ( SELECT a.id,
 a.ordinal,
 a.source_url
 FROM twuanis_remates_private.media_assets a
 JOIN LATERAL ( SELECT ml.state
 FROM twuanis_remates_private.media_links ml
 WHERE ml.asset_id = a.id
 ORDER BY ml.revision DESC
 LIMIT 1) link ON true
 JOIN twuanis_remates_private.observation_fields field ON field.observation_id = a.observation_id AND field.field_path = a.field_path AND field.ordinal = a.ordinal
 WHERE a.offering_id = o.id AND a.source_id = s.id AND a.observation_id = ob.id AND a.kind = 'SOURCE_REFERENCE'::text AND link.state = 'STAGED'::text AND a.field_path = 'csv.image_url'::text AND field.validation = 'VALID'::text AND field.raw_value = a.source_url AND a.source_url ~* '^https://srv[.]bancopopular[.]fi[.]cr/(?!.*([?#[:space:]]|[.][.]))[^?#[:space:]]+[.](jpg|jpeg|png|webp)$'::text
 ORDER BY a.ordinal, a.id
 LIMIT 32) ref), '[]'::jsonb)
 ELSE '[]'::jsonb
 END)) AS jsonb_agg
 FROM twuanis_remates_private.offering_properties op
 JOIN twuanis_remates_private.properties p ON p.id = op.property_id
 JOIN LATERAL ( SELECT cc.id,
 cc.institution_id,
 cc.property_id,
 cc.property_revision,
 cc.source_id,
 cc.observation_id,
 cc.binding_id,
 cc.revision,
 cc.prior_id,
 cc.actor_id,
 cc.receipt_id,
 cc.reason,
 cc.snapshot,
 cc.minimum_ready,
 cc.recorded_at
 FROM twuanis_remates_private.classification_versions cc
 WHERE cc.property_id = p.id
 ORDER BY cc.revision DESC
 LIMIT 1) c ON true
 WHERE op.offering_id = o.id) AS properties
 FROM twuanis_remates_private.listings l JOIN canonical_visibility vis ON vis.id=l.id
 JOIN twuanis_remates_private.offerings o ON o.id = l.offering_id
 JOIN twuanis_remates_private.institutions i ON i.id = o.institution_id
 JOIN twuanis_remates_private.sources s ON s.id = o.source_id
 JOIN LATERAL ( SELECT e.id,
 e.institution_id,
 e.source_id,
 e.listing_id,
 e.offering_id,
 e.revision,
 e.prior_id,
 e.state,
 e.operation,
 e.policy_id,
 e.ingestion_id,
 e.financial_event_id,
 e.verification_id,
 e.actor_id,
 e.receipt_id,
 e.reason,
 e.evidence,
 e.transaction_id,
 e.recorded_at
 FROM twuanis_remates_private.publication_events e
 WHERE e.listing_id = l.id
 ORDER BY e.revision DESC
 LIMIT 1) pub ON true
 LEFT JOIN twuanis_remates_private.ingestion_results ir ON ir.id = pub.ingestion_id
 LEFT JOIN twuanis_remates_private.observations ob ON ob.id = ir.observation_id
 LEFT JOIN twuanis_remates_private.offering_events fe ON fe.id = pub.financial_event_id
 LEFT JOIN twuanis_remates_private.financial_values fv ON fv.id = fe.selected_value_id AND (fv.kind = ANY (ARRAY['SELLING_PRICE'::text, 'AUCTION_BASE'::text]))
 WHERE COALESCE(( SELECT delivery_versions.enabled
 FROM twuanis_remates_private.delivery_versions
 ORDER BY delivery_versions.revision DESC
 LIMIT 1), false) AND (vis.value -> 'visible'::text) = 'true'::jsonb), canonical_scope AS MATERIALIZED (SELECT v.id listing_id,p.id property_id,c.id classification_id,s.id source_id,ob.id observation_id,array_remove(ARRAY[
 CASE WHEN EXISTS(SELECT 1 FROM jsonb_each_text((p_scope->'geography')||jsonb_build_object('property_type',p_scope->>'propertyType')) g WHERE g.value IS NOT NULL AND NOT EXISTS(SELECT 1 FROM twuanis_remates_private.property_terms pt JOIN public.ontology_terms t ON t.id=pt.term_id WHERE pt.classification_id=c.id AND pt.selected AND t.term_type=g.key AND t.id::text=g.value)) THEN 'SCOPE_MISMATCH' END
 ],NULL) reasons FROM canonical_public v
 JOIN twuanis_remates_private.offerings off ON off.id=v.offering_id
 JOIN twuanis_remates_private.sources s ON s.id=off.source_id
 JOIN twuanis_remates_private.offering_properties op ON op.offering_id=off.id
 JOIN twuanis_remates_private.properties p ON p.id=op.property_id AND p.identity_status='CONFIRMED'
 JOIN LATERAL(SELECT cc.* FROM twuanis_remates_private.classification_versions cc WHERE cc.property_id=p.id ORDER BY cc.revision DESC LIMIT 1)c ON twuanis_remates_private.classification_minimum_valid(c.id) AND c.source_id=s.id
 JOIN twuanis_remates_private.source_bindings b ON b.id=c.binding_id AND b.source_id=s.id AND b.offering_id=off.id
 JOIN twuanis_remates_private.ingestion_results ir ON ir.id=twuanis_remates_private.current_ingestion(off.id)
 JOIN twuanis_remates_private.observations ob ON ob.id=ir.observation_id AND ob.source_id=s.id
 JOIN LATERAL(SELECT x.* FROM twuanis_remates_private.source_lifecycle_policies x WHERE x.source_id=s.id ORDER BY x.revision DESC LIMIT 1)pol ON pol.source_revision=s.revision
 JOIN LATERAL(SELECT x.* FROM twuanis_remates_private.offering_events x WHERE x.offering_id=off.id ORDER BY x.revision DESC LIMIT 1)fe ON true
 LEFT JOIN twuanis_remates_private.financial_values fv ON fv.id=fe.selected_value_id
 WHERE v.state='PUBLISHED'
 AND (SELECT count(*) FROM twuanis_remates_private.offering_properties one WHERE one.offering_id=off.id)=1
), scope_manifest AS (SELECT jsonb_build_object('schema','bank-scoped-population-v1','scope',p_scope,'members',coalesce(jsonb_agg(jsonb_build_object('listingId',listing_id,'propertyId',property_id,'classificationId',classification_id,'sourceId',source_id,'observationId',observation_id) ORDER BY listing_id,property_id) FILTER(WHERE cardinality(reasons)=0),'[]'),'excluded',coalesce(jsonb_agg(jsonb_build_object('listingId',listing_id,'propertyId',property_id,'classificationId',classification_id,'sourceId',source_id,'observationId',observation_id,'reasons',reasons) ORDER BY listing_id,property_id) FILTER(WHERE cardinality(reasons)>0),'[]')) manifest FROM canonical_scope) SELECT jsonb_build_object('scopeEvidence',(SELECT manifest FROM scope_manifest),'items',coalesce(jsonb_agg(item ORDER BY listing_id,property_id),'[]'),'dataRevision',
 (SELECT md5(jsonb_build_object('public',coalesce(jsonb_agg(v ORDER BY v.id),'[]'),
 'classes',(SELECT coalesce(jsonb_agg(cc.id ORDER BY cc.id),'[]') FROM twuanis_remates_private.classification_versions cc JOIN twuanis_remates_private.offering_properties op ON op.property_id=cc.property_id JOIN canonical_public vp ON vp.offering_id=op.offering_id),
 'financial',(SELECT coalesce(jsonb_agg(fe.id ORDER BY fe.id),'[]') FROM twuanis_remates_private.offering_events fe JOIN canonical_public vp ON vp.offering_id=fe.offering_id),
 'policies',(SELECT coalesce(jsonb_agg(pol.id ORDER BY pol.id),'[]') FROM twuanis_remates_private.source_lifecycle_policies pol JOIN twuanis_remates_private.offerings off ON off.source_id=pol.source_id JOIN canonical_public vp ON vp.offering_id=off.id))::text) FROM canonical_public v)) INTO rows FROM (
 SELECT v.id listing_id,p.id property_id,jsonb_build_object(
 'population','BANK','listingId',v.id,'propertyId',p.id,'offeringId',v.offering_id,'sourceId',s.id,'sourceNamespace',s.namespace,
 'sourceRevision',s.revision::text,'recordKey',b.record_key,'bindingId',b.id,'bindingRevision',b.revision::text,
 'publicationRevision',v.revision,'publicationStatus',v.state,'classificationId',c.id,'classificationRevision',c.revision::text,
 'observationId',ob.id,'observedAt',ob.retrieved_at,'contentHash',ob.content_sha256,'policyId',pol.id,'policyRevision',pol.revision::text,
 'freshSeconds',pol.fresh_seconds::text,'lifecycle',twuanis_remates_private.lifecycle_eligibility(v.offering_id),
 'mechanism',v.mechanism,'transactionEvidence',CASE WHEN ob.raw_text LIKE '{%' AND ob.parse_status='PARSED' THEN jsonb_build_array(jsonb_build_object('value',ob.raw_text::jsonb->>'transaction_type','path','raw.transaction_type','ordinal',0,'validation','RETAINED_RAW')) ELSE '[]'::jsonb END,
 'financial',jsonb_build_object('id',fv.id,'eventId',fe.id,'eventRevision',fe.revision::text,'kind',fv.kind,'status',fv.status,'amount',fv.amount::text,'currency',fv.currency,'observationId',fv.observation_id,'sourceId',fv.source_id,'offeringId',fv.offering_id,'fieldPath',fv.field_path,'ordinal',fv.ordinal,'selectionValid',twuanis_remates_private.financial_selection_valid(fe.id)),
 'terms',(SELECT jsonb_agg(jsonb_build_object('id',t.id::text,'parent_id',t.parent_id::text,'term_type',t.term_type,'level',t.level,'official_code',t.official_code,'slug',t.slug,'term_name',t.term_name,'term_name_en',to_jsonb(t)->>'term_name_en','term_name_es',to_jsonb(t)->>'term_name_es','slug_en',to_jsonb(t)->>'slug_en','slug_es',to_jsonb(t)->>'slug_es')) FROM twuanis_remates_private.property_terms pt JOIN public.ontology_terms t ON t.id=pt.term_id WHERE pt.classification_id=c.id AND pt.selected AND t.term_type IN('province','canton','district','property_type')),
 'measurements',(SELECT coalesce(jsonb_agg(jsonb_build_object('dimension',f.dimension,'kind',f.kind,'value',f.exact_value::text,'observationId',f.evidence_id,'fieldPath',f.field_path,'ordinal',f.ordinal,'unit',ef.unit,'validation',ef.validation,'fieldValue',ef.raw_value,'observedAt',eo.retrieved_at,'sourceId',eo.source_id,'recordKey',eo.record_key,'contentHash',eo.content_sha256,'page',ef.document_page,'selector',ef.selector)), '[]') FROM twuanis_remates_private.property_facts f JOIN twuanis_remates_private.observation_fields ef ON (ef.observation_id,ef.field_path,ef.ordinal)=(f.evidence_id,f.field_path,f.ordinal) JOIN twuanis_remates_private.observations eo ON eo.id=f.evidence_id WHERE f.classification_id=c.id AND f.dimension IN('property_area','construction_area')),
 'registryMeasurements',(SELECT coalesce(jsonb_agg(jsonb_build_object('value',f.raw_value,'observationId',f.observation_id,'fieldPath',f.field_path,'ordinal',f.ordinal,'unit',f.unit,'validation',f.validation,'page',f.document_page,'selector',f.selector)), '[]') FROM twuanis_remates_private.observation_fields f WHERE f.observation_id=c.observation_id AND f.field_path='pdf.normalized_registry_area'),
 'otherFacts',(SELECT coalesce(jsonb_agg(jsonb_build_object('dimension',f.dimension,'kind',f.kind,'exactValue',f.exact_value::text,'categoryTermId',f.category_term_id::text,'rangeLower',f.range_lower::text,'rangeUpper',f.range_upper::text,'lowerInclusive',f.lower_inclusive,'upperInclusive',f.upper_inclusive,'observationId',f.evidence_id,'fieldPath',f.field_path,'ordinal',f.ordinal)), '[]') FROM twuanis_remates_private.property_facts f WHERE f.classification_id=c.id AND f.dimension NOT IN('property_area','construction_area')),
 'semantics',(SELECT coalesce(jsonb_agg(jsonb_build_object('dimension',pt.dimension,'termId',pt.term_id::text,'observationId',pt.evidence_id)), '[]') FROM twuanis_remates_private.property_terms pt WHERE pt.classification_id=c.id AND pt.selected AND pt.dimension IN('property_type','utility','environment','terrain','accessibility','legal_status')),
 'areaSelection',(SELECT CASE WHEN eo.raw_text LIKE '{%' AND eo.raw_text::jsonb->>'format'='bp-reviewed-factual-areas-v1' THEN eo.raw_text::jsonb->'selection' ELSE NULL END FROM twuanis_remates_private.observations eo WHERE eo.id=c.observation_id)
 ) item
 FROM canonical_public v
 JOIN twuanis_remates_private.offerings off ON off.id=v.offering_id
 JOIN twuanis_remates_private.sources s ON s.id=off.source_id
 JOIN twuanis_remates_private.offering_properties op ON op.offering_id=off.id
 JOIN twuanis_remates_private.properties p ON p.id=op.property_id AND p.identity_status='CONFIRMED'
 JOIN LATERAL(SELECT cc.* FROM twuanis_remates_private.classification_versions cc WHERE cc.property_id=p.id ORDER BY cc.revision DESC LIMIT 1)c ON twuanis_remates_private.classification_minimum_valid(c.id) AND c.source_id=s.id
 JOIN twuanis_remates_private.source_bindings b ON b.id=c.binding_id AND b.source_id=s.id AND b.offering_id=off.id
 JOIN twuanis_remates_private.ingestion_results ir ON ir.id=twuanis_remates_private.current_ingestion(off.id)
 JOIN twuanis_remates_private.observations ob ON ob.id=ir.observation_id AND ob.source_id=s.id
 JOIN LATERAL(SELECT x.* FROM twuanis_remates_private.source_lifecycle_policies x WHERE x.source_id=s.id ORDER BY x.revision DESC LIMIT 1)pol ON pol.source_revision=s.revision
 JOIN LATERAL(SELECT x.* FROM twuanis_remates_private.offering_events x WHERE x.offering_id=off.id ORDER BY x.revision DESC LIMIT 1)fe ON true
 LEFT JOIN twuanis_remates_private.financial_values fv ON fv.id=fe.selected_value_id
 WHERE v.state='PUBLISHED' AND (p_after IS NULL OR v.id>p_after)
 AND (SELECT count(*) FROM twuanis_remates_private.offering_properties one WHERE one.offering_id=off.id)=1
 AND EXISTS(SELECT 1 FROM canonical_scope cs WHERE cs.listing_id=v.id AND cs.property_id=p.id AND cardinality(cs.reasons)=0)
 ORDER BY v.id,p.id LIMIT 101
 ) bounded;

 RETURN rows;
END$_$;


--
-- Name: order_evidence(uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.order_evidence(p_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT jsonb_build_object('id',o.id,'accountId',o.account_id,'requestId',o.request_id,'productId',o.product_id,'targetType',o.target_type,'listingId',o.listing_id,'jobId',o.job_id,'currency',o.currency,'createdAt',o.created_at,'paymentDeadline',o.payment_deadline,'terms',o.resolved_terms,
 'state',twuanis_canonical_private.offer_order_state(o.id,statement_timestamp()),
 'payment', (SELECT jsonb_build_object('id',a.id,'eventId',a.payment_event_id,'source',a.source,'amount',a.amount::text,'currency',a.currency,'acknowledgedAt',a.acknowledged_at) FROM twuanis_canonical_private.offer_paid_acknowledgements a WHERE a.order_id=o.id),
 'entitlement',(SELECT jsonb_build_object('id',t.id,'source',t.source,'startsAt',t.starts_at,'endsAt',t.ends_at,'committedAt',t.committed_at) FROM twuanis_canonical_private.entitlement_terms t WHERE t.order_id=o.id),'fulfillment',coalesce((SELECT jsonb_build_object('purchaseId',f.purchase_id,'paymentId',f.verified_payment_id,'activatedAt',f.activated_at,'result',f.result) FROM twuanis_canonical_private.addon_fulfillments f WHERE f.purchase_id=o.id AND f.account_id=o.account_id AND f.product_id=o.product_id AND f.configuration_id=(o.resolved_terms->>'configurationId')::uuid AND f.target_id=coalesce(o.listing_id,o.job_id,o.account_id)),(SELECT jsonb_build_object('termId',t.id,'acknowledgementId',t.acknowledgement_id,'startsAt',t.starts_at,'endsAt',t.ends_at,'committedAt',t.committed_at,'state','COMPLETE') FROM twuanis_canonical_private.entitlement_terms t WHERE t.order_id=o.id AND t.product_class='PACKAGE')),
 'evidenceComplete',o.resolved_terms->>'orderContractVersion'='1')
 FROM twuanis_canonical_private.offer_order_snapshots o WHERE o.id=p_id
$$;


--
-- Name: package_card_price_v1(text, text, boolean, text); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.package_card_price_v1(p_product text, p_duration text, p_bank boolean, p_phase text) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT CASE WHEN p_duration='day' AND NOT p_bank THEN CASE p_product WHEN 'pkg-matching-market-comparison' THEN 5.00 WHEN 'pkg-pricing-position-relationships' THEN 4.75 END
 WHEN p_duration='month' AND p_phase IN('introductory','standard') THEN CASE p_product
 WHEN 'pkg-geographic-distribution-price-range' THEN CASE WHEN p_phase='introductory' THEN CASE WHEN p_bank THEN 9.75 ELSE 5.00 END ELSE CASE WHEN p_bank THEN 16.50 ELSE 12.00 END END
 WHEN 'pkg-matching-market-comparison' THEN CASE WHEN p_phase='introductory' THEN CASE WHEN p_bank THEN 28.75 ELSE 23.50 END ELSE CASE WHEN p_bank THEN 63.00 ELSE 57.75 END END
 WHEN 'pkg-pricing-position-relationships' THEN CASE WHEN p_phase='introductory' THEN CASE WHEN p_bank THEN 114.25 ELSE 103.75 END ELSE CASE WHEN p_bank THEN 240.25 ELSE 229.75 END END END END;
$$;


--
-- Name: package_card_schedule_approved(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.package_card_schedule_approved() RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$SELECT true;$$;


--
-- Name: package_payment_quote(uuid, text, text, boolean, timestamp with time zone); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.package_payment_quote(p_account uuid, p_product text, p_duration text, p_bank boolean, p_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE rate numeric;fx_date date;comp jsonb;base jsonb;crc numeric;standard_crc numeric;usd numeric;standard_usd numeric;minimum numeric;card numeric;standard_card numeric;daily numeric;result jsonb;phase text;card_available boolean;approved boolean:=twuanis_canonical_private.package_card_schedule_approved();proposed_card numeric;legacy jsonb;legacy_base jsonb;
BEGIN
 IF p_duration IS NULL OR p_duration NOT IN('day','month') OR p_bank IS NULL OR(p_duration='day'AND p_bank)OR p_at IS NULL OR NOT isfinite(p_at)OR p_product NOT IN('pkg-geographic-distribution-price-range','pkg-matching-market-comparison','pkg-pricing-position-relationships') THEN RAISE EXCEPTION 'supported explicit Package configuration required';END IF;
 IF NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.intelligence_packages WHERE id=p_product AND state='active')THEN RAISE EXCEPTION 'active Package required';END IF;
 SELECT f.rate,f.effective_date INTO STRICT rate,fx_date FROM public.fx_rates f WHERE f.base_currency='USD'AND f.quote_currency='CRC'AND f.rate_type='reference_sale'AND f.source='BCCR'AND f.effective_date<=(p_at AT TIME ZONE 'America/Costa_Rica')::date ORDER BY f.effective_date DESC LIMIT 1;
 IF rate IS NULL OR rate<=0 THEN RAISE EXCEPTION 'canonical BCCR quote unavailable';END IF;
 IF p_duration='month' THEN
  comp:=twuanis_canonical_private.resolve_package_bank_upgrade_price(p_product,'CRC','month',p_bank,p_at);
  IF p_account IS NOT NULL THEN comp:=twuanis_canonical_private.founder_composed_price(p_account,p_product,'CRC',p_at,comp,p_bank);END IF;
  base:=comp->'base';crc:=(comp->>'total')::numeric;standard_crc:=(comp->>'standardTotal')::numeric;
 ELSE
  SELECT amount INTO STRICT daily FROM twuanis_canonical_private.package_daily_access_prices WHERE package_id=p_product AND currency=CASE WHEN p_product='pkg-matching-market-comparison'THEN 'CRC'ELSE 'USD'END ORDER BY version DESC LIMIT 1;
  crc:=CASE WHEN p_product='pkg-matching-market-comparison'THEN daily ELSE round(daily*rate,0)END;standard_crc:=crc;base:=jsonb_build_object('available',true,'quantity',1,'source','STANDARD','currency','CRC','productId',p_product,'configurationId',(SELECT current_configuration_id FROM twuanis_canonical_private.intelligence_packages WHERE id=p_product),'total',crc::text,'effectiveRate',crc::text,'standardRate',crc::text,'terms',jsonb_build_object('quantity',1,'unit','day'));IF p_account IS NOT NULL THEN base:=twuanis_canonical_private.founder_price(p_account,'package',p_product,'CRC',p_at,base,'PRIVATE');crc:=(base->>'total')::numeric;END IF;
 END IF;
 IF crc IS NULL OR crc<=0 OR standard_crc IS NULL OR standard_crc<crc THEN RAISE EXCEPTION 'valid canonical SINPE configuration required';END IF;
 usd:=round(crc/rate,2);standard_usd:=round(standard_crc/rate,2);
 minimum:=ceil(((usd+0.30+0.05)/(1-0.044))*100)/100;
 phase:=CASE WHEN base->>'source'='OFFER' OR base->'founderProtection' IS NOT NULL THEN 'introductory' ELSE 'standard' END;
 card:=twuanis_canonical_private.package_card_price_v1(p_product,p_duration,p_bank,phase);
 standard_card:=twuanis_canonical_private.package_card_price_v1(p_product,p_duration,p_bank,'standard');
 IF card IS NULL OR standard_card IS NULL THEN RAISE EXCEPTION 'approved fixed card price missing';END IF;
 card_available:=card>=2 AND card>usd AND card-round(card*0.044,2)-0.35>=usd;
 proposed_card:=card;
 IF NOT approved THEN
  IF p_duration='month'THEN
   legacy:=twuanis_canonical_private.resolve_package_bank_upgrade_price(p_product,'USD','month',p_bank,p_at);
   IF p_account IS NOT NULL THEN legacy:=twuanis_canonical_private.founder_composed_price(p_account,p_product,'USD',p_at,legacy,p_bank);END IF;
   card:=(legacy->>'total')::numeric;standard_card:=(legacy->>'standardTotal')::numeric;
  ELSE
   SELECT amount INTO STRICT card FROM twuanis_canonical_private.package_daily_access_prices WHERE package_id=p_product AND currency='USD'ORDER BY version DESC LIMIT 1;
   standard_card:=card;
   legacy_base:=jsonb_build_object('available',true,'quantity',1,'source','STANDARD','currency','USD','productId',p_product,'configurationId',(SELECT current_configuration_id FROM twuanis_canonical_private.intelligence_packages WHERE id=p_product),'total',card::text,'effectiveRate',card::text,'standardRate',card::text,'terms',jsonb_build_object('quantity',1,'unit','day'));
   IF p_account IS NOT NULL THEN legacy_base:=twuanis_canonical_private.founder_price(p_account,'package',p_product,'USD',p_at,legacy_base,'PRIVATE');card:=(legacy_base->>'total')::numeric;END IF;
  END IF;
  card_available:=card>=2;
 END IF;

 result:=jsonb_build_object('pricebookStatus',CASE WHEN approved THEN 'APPROVED' ELSE 'PROPOSED_ONLY'END,'proposedCardUSD',proposed_card::text,'pricebook','package-card-usd-2026-10-31-v1','phase',phase,'version','payment-method-v1','product',p_product,'duration',p_duration,'bankUpgrade',p_bank,'source',base->>'source','offerEnd',base->'offerEnd','founderProtection',base->'founderProtection','resolvedAt',p_at,'fx',jsonb_build_object('rate',rate::text,'source','BCCR','rateType','reference_sale','effectiveDate',fx_date),'sinpe',jsonb_build_object('available',true,'chargeCurrency','CRC','chargeAmount',crc::text,'displayAmounts',jsonb_build_object('USD',usd::text,'CRC',crc::text),'standardDisplayAmounts',jsonb_build_object('USD',standard_usd::text,'CRC',standard_crc::text)),'stripe',jsonb_build_object('available',card_available,'unavailableReason',CASE WHEN NOT card_available THEN 'APPROVED_PRICE_REVIEW_REQUIRED' ELSE NULL END,'chargeCurrency','USD','chargeAmount',card::text,'displayAmounts',jsonb_build_object('USD',card::text,'CRC',round(card*rate,0)::text),'standardDisplayAmounts',jsonb_build_object('USD',standard_card::text,'CRC',round(standard_card*rate,0)::text)),'model',jsonb_build_object('percentage','0.044','fixedUSD','0.30','radarUSD','0.05','minimumCardUSD',minimum::text,'rounding',CASE WHEN approved THEN 'OWNER_REVIEWED_FIXED_USD_0_25'ELSE'UNCHANGED_CANONICAL_STRIPE_QUOTE'END,'retainedUSD',(card-round(card*0.044,2)-0.35)::text));
 RETURN result;
END $$;


--
-- Name: package_projection(text); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.package_projection(p_id text) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT jsonb_build_object('id',p.id,'name_en',p.name_en,'name_es',p.name_es,'question_en',p.question_en,'question_es',p.question_es,'state',p.state,'trialEligible',p.trial_eligible,'revision',p.revision::text,'configurationId',v.id,'version',v.version::text,'termQuantity',v.term_quantity,'termUnit',v.term_unit,'capabilities',v.capabilities,'standardPrices',coalesce((SELECT jsonb_object_agg(currency,amount::text) FROM twuanis_canonical_private.intelligence_package_prices WHERE package_id=p.id),'{}'::jsonb),'acquisitionAvailable',false,'acquisitionState','fulfillment_not_activated')
 FROM twuanis_canonical_private.intelligence_packages p JOIN twuanis_canonical_private.intelligence_package_configurations v ON v.package_id=p.id AND v.id=p.current_configuration_id WHERE p.id=p_id
$$;


--
-- Name: price_integrity_currency(jsonb); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.price_integrity_currency(value jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE token text; c text; answer text;
BEGIN
 IF jsonb_typeof(value)='string' THEN token:=upper(btrim(value#>>'{}'));RETURN CASE WHEN token IN('USD','$','US$')THEN 'USD'WHEN token IN('CRC','₡','¢')THEN 'CRC'END;END IF;
 IF jsonb_typeof(value)IS DISTINCT FROM 'object' THEN RETURN NULL;END IF;
 -- A source locale/countryISO is deliberately never interpreted as currency.
 FOREACH token IN ARRAY ARRAY[value->>'code',value->>'currencyCode',value->>'symbol']LOOP
  IF token IS NULL OR token='' THEN CONTINUE;END IF;
  c:=twuanis_canonical_private.price_integrity_currency(to_jsonb(token));
  IF c IS NULL OR (answer IS NOT NULL AND answer<>c)THEN RETURN NULL;END IF;answer:=c;
 END LOOP;RETURN answer;
END $_$;


--
-- Name: price_integrity_number(text); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.price_integrity_number(value text) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE s text:=btrim(value); n numeric;
BEGIN
 IF s IS NULL OR length(s)>256 THEN RETURN NULL;END IF;
 s:=regexp_replace(s,'^(USD|CRC|US[$]|[$₡¢])[[:space:]]*','','i');
 IF s ~ '^[0-9]{1,3}(,[0-9]{3})+([.][0-9]{1,2})?$' THEN s:=replace(s,',','');END IF;
 IF s !~ '^[0-9]+([.][0-9]+)?$' THEN RETURN NULL;END IF;
 n:=s::numeric;IF n<=0 OR NOT twuanis_canonical_private.finite_numeric(n) THEN RETURN NULL;END IF;RETURN n;
END $_$;


--
-- Name: price_integrity_texts(text[], text, numeric, text); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.price_integrity_texts(texts text[], tx text, amount numeric, currency text) RETURNS text[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE body text; line text; token text[]; raw text; number_text text; suffix text; n numeric; c text; asking boolean; other_money boolean; rental boolean; reasons text[]:='{}';
BEGIN
 FOREACH body IN ARRAY texts LOOP
  IF body IS NULL THEN CONTINUE;END IF;
  IF length(body)>131072 THEN reasons:=array_append(reasons,'PRICE_TEXT_BOUND_EXCEEDED');CONTINUE;END IF;
  body:=lower(translate(regexp_replace(body,'<br[[:space:]]*/?>|\\n|\\r',E'\n','gi'),'áéíóúü','aeiouu'));
  FOREACH line IN ARRAY regexp_split_to_array(body,E'[\n\r]+') LOOP
   rental:=line ~ '\m(alquiler|alquilar|renta|rent|rental|lease)\M';
   asking:=line ~ '\m(precio|venta|price|selling|asking|inversion)\M';
   other_money:=line ~ '\m(cuota|mantenimiento|hoa|avaluo|descuento|prima|hipoteca|alquiler|renta|rent|deposito|antes|comparables)\M';
   IF asking AND line ~ '(precio|price)[[:space:]:]*(a convenir|consultar|negociable|por definir|on request|tbd|n/a|gratis|gratuito|placeholder|dummy)' THEN reasons:=array_append(reasons,'PRICE_PLACEHOLDER');END IF;
   FOR token IN SELECT regexp_matches(line,'(?:us[$]|usd[[:space:]]*[$]?|crc[[:space:]]*|[$₡¢])[[:space:]]*[0-9][0-9.,]*([[:alpha:]][[:alnum:]]*)','g')LOOP
    IF token[1] NOT IN('usd','mil','millon','millones','k')THEN reasons:=array_append(reasons,'PRICE_TEXT_MALFORMED_OR_AMBIGUOUS');END IF;
   END LOOP;
   IF tx='rent'AND rental THEN other_money:=line ~ '\m(cuota|mantenimiento|hoa|avaluo|descuento|prima|hipoteca|deposito|antes|comparables)\M';END IF;
   FOR token IN SELECT regexp_matches(line,'((?:us[$]|usd[[:space:]]*[$]?|crc[[:space:]]*|[$₡¢])[[:space:]]*[0-9][0-9.,]*(?:[ \t]+[0-9]+)*(?:[ \t]*(?:millones|millon|mil|k))?)','g')LOOP
    raw:=token[1];c:=CASE WHEN raw ~ '^(crc|₡|¢)'THEN 'CRC'ELSE 'USD'END;
    number_text:=regexp_replace(raw,'^(usd[[:space:]]*[$]?|crc|us[$]|[$₡¢])[[:space:]]*','','i');suffix:=substring(number_text FROM '(millones|millon|mil|k)$');
    IF suffix IS NOT NULL THEN number_text:=btrim(regexp_replace(number_text,'(millones|millon|mil|k)$',''));END IF;
    IF number_text ~ '^[0-9]{1,3}([.][0-9]{3}){2,}$'THEN number_text:=replace(number_text,'.','');END IF;
    IF number_text ~ '^[0-9]{1,3}( [0-9]{3})+$'THEN number_text:=replace(number_text,' ','');END IF;
    n:=CASE WHEN number_text ~ '^[0-9]+[.][0-9]{3}$'THEN NULL ELSE twuanis_canonical_private.price_integrity_number(number_text)END;
    IF suffix IN('millones','millon')THEN n:=n*1000000;ELSIF suffix IN('mil','k')THEN n:=n*1000;END IF;
    IF tx='sale' AND rental THEN reasons:=array_append(reasons,'SALE_RENTAL_PRICE_EVIDENCE');END IF;
    IF tx='rent'AND line ~ '\m(venta|sale|selling)\M'THEN reasons:=array_append(reasons,'RENT_SALE_PRICE_EVIDENCE');END IF;
    IF line ~ '-[[:space:]]*(us[$]|usd|crc|[$₡¢])'THEN reasons:=array_append(reasons,'PRICE_NEGATIVE_TEXT');END IF;
    IF n IS NULL AND (asking OR NOT other_money)THEN reasons:=array_append(reasons,'PRICE_TEXT_MALFORMED_OR_AMBIGUOUS');
    ELSIF n IS NOT NULL AND asking AND NOT other_money AND (n<>amount OR c<>currency) THEN reasons:=array_append(reasons,'PRICE_TEXT_CONTRADICTION');
    END IF;
   END LOOP;
  END LOOP;
 END LOOP;
 RETURN ARRAY(SELECT DISTINCT x FROM unnest(reasons)x ORDER BY x);
END $_$;


--
-- Name: protect_daily_membership_order(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.protect_daily_membership_order() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE other_currency text;other_quote jsonb;BEGIN
 IF NEW.target_type<>'package' OR NEW.resolved_terms->'terms'->>'unit' IS DISTINCT FROM 'day' OR NOT twuanis_canonical_private.has_introductory_membership(NEW.account_id,NEW.created_at) THEN RETURN NEW;END IF;
 other_currency:=CASE NEW.currency WHEN 'USD' THEN 'CRC' ELSE 'USD' END;
 other_quote:=NEW.resolved_terms||jsonb_build_object('total',NEW.resolved_terms->'currencyQuotes'->other_currency->>'total');
 other_quote:=twuanis_canonical_private.founder_price(NEW.account_id,'package',NEW.product_id,other_currency,NEW.created_at,other_quote,'PRIVATE');
 NEW.resolved_terms:=twuanis_canonical_private.founder_price(NEW.account_id,'package',NEW.product_id,NEW.currency,NEW.created_at,NEW.resolved_terms,'PRIVATE');
 NEW.resolved_terms:=NEW.resolved_terms||jsonb_build_object('currencyQuotes',jsonb_build_object(NEW.currency,jsonb_build_object('total',NEW.resolved_terms->>'total'),other_currency,jsonb_build_object('total',other_quote->>'total')));RETURN NEW;
END$$;


--
-- Name: publisher_allowance(uuid, uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.publisher_allowance(p_publisher uuid, p_owner uuid) RETURNS TABLE(subscription_id uuid, package_id uuid, allowance bigint, unlimited boolean, effective_start timestamp with time zone, effective_end timestamp with time zone, observed_at timestamp with time zone)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
 IF p_owner IS DISTINCT FROM twuanis_canonical_private.lock_publisher(p_publisher) THEN RAISE EXCEPTION 'publisher/customer mismatch' USING ERRCODE='22023'; END IF;
 RETURN QUERY SELECT * FROM twuanis_canonical_private.customer_publication_allowance(p_owner);
END $$;


--
-- Name: publisher_consumption(uuid, uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.publisher_consumption(p_publisher uuid, p_owner uuid) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE v_owner uuid; v_count bigint; v_bad bigint;
BEGIN
 v_owner:=twuanis_canonical_private.lock_publisher(p_publisher);
 IF p_owner IS DISTINCT FROM v_owner THEN RAISE EXCEPTION 'publisher/customer mismatch' USING ERRCODE='22023'; END IF;
 SELECT count(*),count(*) FILTER(WHERE l.owner_id IS DISTINCT FROM v_owner)
 INTO v_count,v_bad FROM public.listings l
 WHERE l.publisher_account_id=p_publisher AND l.listing_status='active';
 IF v_bad<>0 THEN RAISE EXCEPTION 'canonical listing ownership mismatch' USING ERRCODE='55000'; END IF;
 RETURN v_count;
END $$;


--
-- Name: purchased_package_interval(uuid, text, text, integer, timestamp with time zone); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.purchased_package_interval(p_account uuid, p_product text, p_unit text, p_quantity integer, p_fulfilled_at timestamp with time zone) RETURNS TABLE(starts_at timestamp with time zone, ends_at timestamp with time zone)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE coverage tstzmultirange; span tstzrange; candidate timestamptz; required_caps text[];
BEGIN
 IF p_account IS NULL OR p_product IS NULL OR p_fulfilled_at IS NULL OR NOT isfinite(p_fulfilled_at)
 OR p_quantity IS DISTINCT FROM 1 OR p_unit IS NULL OR p_unit NOT IN('day','month') THEN
 RAISE EXCEPTION 'explicit daily or monthly Package term required';END IF;
 SELECT c.capabilities INTO required_caps FROM twuanis_canonical_private.intelligence_packages p
 JOIN twuanis_canonical_private.intelligence_package_configurations c ON c.id=p.current_configuration_id WHERE p.id=p_product;
 IF NOT FOUND THEN RAISE EXCEPTION 'canonical Package required';END IF;
 PERFORM pg_advisory_xact_lock(3254,hashtext(p_account::text||':'||p_product));
 SELECT range_agg(r) INTO coverage FROM (
 SELECT twuanis_canonical_private.entitlement_interval(t.starts_at,t.ends_at,v.revoked_at) r
 FROM twuanis_canonical_private.entitlement_terms t LEFT JOIN twuanis_canonical_private.entitlement_revocations v ON v.term_id=t.id
 WHERE t.account_id=p_account AND t.product_class='PACKAGE' AND t.product_id=p_product AND t.source IN('PURCHASED','ADMIN_GRANT','RECEIPT_POLICY')
 UNION ALL
 -- Existing legacy authority grants capabilities, not modern Package identities.
 -- Only complete coverage of this exact Package configuration is eligible.
 -- Partial or merely overlapping legacy rights never defer a Package purchase.
 SELECT tstzrange(coalesce(g.period_start,g.captured_at),g.expires_at,'[)')
 FROM twuanis_canonical_private.legacy_package_access g JOIN public.user_subscriptions s ON s.id=g.subscription_id
 WHERE g.account_id=p_account AND s.user_id=p_account AND s.package_id=g.package_id
 AND s.status='active' AND s.cancelled_at IS NULL AND s.expired_at IS NULL
 AND s.current_period_start IS NOT DISTINCT FROM g.period_start AND s.current_period_end=g.expires_at
 AND cardinality(required_caps)>0 AND g.capabilities @> required_caps
 AND coalesce(g.period_start,g.captured_at)<g.expires_at
 ) x WHERE NOT isempty(r);
 candidate:=p_fulfilled_at;
 FOR span IN SELECT x FROM unnest(coverage) x ORDER BY lower(x) LOOP
  IF upper(span)<=candidate THEN CONTINUE; END IF;
  IF lower(span)<=candidate THEN candidate:=upper(span);
  ELSIF p_unit='month' OR lower(span)>=candidate+interval '24 hours' THEN EXIT;
  ELSE candidate:=upper(span);END IF;
 END LOOP;
 IF candidate IS NULL OR NOT isfinite(candidate) THEN RAISE EXCEPTION 'finite scheduling horizon required';END IF;
 starts_at:=candidate;
 ends_at:=CASE WHEN p_unit='day' THEN candidate+interval '24 hours'
 ELSE ((candidate AT TIME ZONE 'America/Costa_Rica')+interval '1 month') AT TIME ZONE 'America/Costa_Rica' END;
 RETURN NEXT;
END$$;


--
-- Name: queue_confirmed_account_notification(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.queue_confirmed_account_notification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF NEW.email_confirmed_at IS NOT NULL AND NEW.email IS NOT NULL AND
 (TG_OP='INSERT' OR OLD.email_confirmed_at IS NULL) THEN
 INSERT INTO twuanis_canonical_private.confirmed_account_notifications(account_id,email,account_created_at,email_confirmed_at,registration_language)
 VALUES(NEW.id,NEW.email,NEW.created_at,NEW.email_confirmed_at,CASE WHEN NEW.raw_user_meta_data->>'registration_language' IN('en','es') THEN NEW.raw_user_meta_data->>'registration_language' END)
 ON CONFLICT(account_id) DO NOTHING;
 END IF;RETURN NEW;END$$;


--
-- Name: queue_sinpe_notification(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.queue_sinpe_notification() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF NEW.source IN('sinpe','onvo') THEN INSERT INTO twuanis_canonical_private.sinpe_purchase_notifications(order_id,acknowledgement_id)VALUES(NEW.order_id,NEW.id)ON CONFLICT(order_id)DO NOTHING;END IF;RETURN NEW;END$$;


--
-- Name: receipt_bank_terms(uuid, text); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.receipt_bank_terms(p_account uuid, p_capability text) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT jsonb_agg(jsonb_build_object('id',t.id::text,'startsAt',t.starts_at,'endsAt',t.ends_at)ORDER BY t.id)FROM twuanis_canonical_private.entitlement_terms t JOIN twuanis_canonical_private.intelligence_package_configurations c ON c.id=t.configuration_id AND c.package_id=t.product_id JOIN twuanis_canonical_private.intelligence_package_rights r ON r.id=t.id WHERE t.account_id=p_account AND t.bank_upgrade_selected AND p_capability=ANY(c.capabilities)AND t.starts_at<=statement_timestamp()AND t.ends_at>statement_timestamp()AND r.revoked_at IS NULL AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.entitlement_revocations WHERE term_id=t.id)AND twuanis_canonical_private.receipt_term_valid(t.id);$$;


--
-- Name: receipt_term_valid(uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.receipt_term_valid(p_term uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT EXISTS(SELECT 1 FROM twuanis_canonical_private.direct_sinpe_receipts d JOIN twuanis_canonical_private.entitlement_terms t ON t.id=d.activation_term_id AND t.order_id=d.order_id AND t.account_id=d.account_id JOIN twuanis_canonical_private.offer_order_snapshots o ON o.id=d.order_id AND o.account_id=d.account_id AND o.product_id=t.product_id JOIN twuanis_canonical_private.intelligence_package_configurations c ON c.id=t.configuration_id AND c.package_id=t.product_id JOIN twuanis_canonical_private.intelligence_package_rights r ON r.id=t.id AND r.account_id=t.account_id AND r.configuration_id=t.configuration_id AND r.package_id=t.product_id AND r.starts_at=t.starts_at AND r.ends_at=t.ends_at WHERE t.id=p_term AND t.source='RECEIPT_POLICY'AND t.execution_authority='RECEIPT_POLICY'AND t.acknowledgement_id IS NULL AND t.actor_id IS NULL AND t.product_class='PACKAGE'AND t.request_id=d.id AND o.currency='CRC'AND o.resolved_terms->>'paymentExecution'='direct_sinpe'AND o.resolved_terms->>'directReceivingAccount'=d.receiving_account_id::text AND o.resolved_terms->>'configurationId'=c.id::text AND o.resolved_terms->'terms'->'capabilities'=to_jsonb(c.capabilities)AND t.bank_upgrade_selected=coalesce((o.resolved_terms->'bankUpgrade'->>'selected')::boolean,false)AND twuanis_canonical_private.direct_receipt_timing_valid(d.id,o.id) AND d.policy_version='direct-sinpe-receipt-access-2026-10-31-v1');$$;


--
-- Name: record_listing_admission_success(uuid, uuid, uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.record_listing_admission_success(p_listing uuid, p_request uuid, p_operation uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE l public.listings; e uuid;BEGIN
 SELECT * INTO STRICT l FROM public.listings WHERE id=p_listing;
 IF l.listing_status<>'active' THEN RETURN;END IF;
 SELECT cr.request_id INTO e FROM twuanis_canonical_private.csv_initial_publication ip JOIN public.canonical_operation_receipts cr ON cr.id=ip.creation_receipt WHERE ip.listing_id=l.id;
 INSERT INTO twuanis_canonical_private.listing_admission_successes(listing_id,request_id,operation_id,source_name,source_evidence_id,proposed)
 VALUES(l.id,p_request,p_operation,CASE WHEN l.owner_id IS NOT NULL THEN 'customer' ELSE coalesce(l.source_name,l.listing_origin)END,e,twuanis_canonical_private.duplicate_snapshot(to_jsonb(l))) ON CONFLICT(listing_id)DO NOTHING;
END$$;


--
-- Name: refresh_placement_terms(uuid, text); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.refresh_placement_terms(p_listing uuid, p_product text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE spans tstzmultirange;first_at timestamptz;last_at timestamptz;t twuanis_canonical_private.entitlement_terms%ROWTYPE;purchase uuid;
BEGIN
 SELECT * INTO STRICT t FROM twuanis_canonical_private.entitlement_terms WHERE listing_id=p_listing AND product_id=p_product ORDER BY committed_at DESC,id DESC LIMIT 1;
 SELECT coalesce(range_agg(twuanis_canonical_private.entitlement_interval(x.starts_at,x.ends_at,r.revoked_at)),'{}'::tstzmultirange),min(x.starts_at),max(x.ends_at)
 INTO spans,first_at,last_at FROM twuanis_canonical_private.entitlement_terms x LEFT JOIN twuanis_canonical_private.entitlement_revocations r ON r.term_id=x.id WHERE x.listing_id=p_listing AND x.product_id=p_product;
 SELECT order_id INTO purchase FROM twuanis_canonical_private.entitlement_terms WHERE listing_id=p_listing AND product_id=p_product AND source='PURCHASED' ORDER BY committed_at DESC,id DESC LIMIT 1;
 INSERT INTO twuanis_canonical_private.addon_placement_rights(product_id,listing_id,account_id,configuration_id,activated_at,expires_at,last_purchase_id,effective_intervals)
 VALUES(p_product,p_listing,t.account_id,t.configuration_id,first_at,last_at,purchase,spans)
 ON CONFLICT(product_id,listing_id) DO UPDATE SET account_id=EXCLUDED.account_id,configuration_id=EXCLUDED.configuration_id,activated_at=EXCLUDED.activated_at,expires_at=EXCLUDED.expires_at,last_purchase_id=EXCLUDED.last_purchase_id,effective_intervals=EXCLUDED.effective_intervals,revoked_at=NULL;
END $$;


