-- Name: register_account_principal(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.register_account_principal() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 INSERT INTO twuanis_canonical_private.account_principals(id) VALUES(NEW.id);
 RETURN NEW;END$$;


--
-- Name: register_future_bank_introductory_price(text, text, text); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.register_future_bank_introductory_price(p_product text, p_market text, p_commercial_class text) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE c twuanis_canonical_private.intelligence_package_configurations%ROWTYPE;v twuanis_canonical_private.package_bank_upgrade_price_versions%ROWTYPE;terms jsonb;rid uuid;money text;amount numeric;BEGIN
 IF p_market IS DISTINCT FROM 'CR' OR p_commercial_class IS DISTINCT FROM 'STANDARDIZED' THEN RAISE EXCEPTION 'only standardized Costa Rican canonical products eligible';END IF;
 SELECT x.* INTO STRICT c FROM twuanis_canonical_private.intelligence_package_configurations x JOIN twuanis_canonical_private.intelligence_packages p ON p.current_configuration_id=x.id WHERE p.id=p_product AND p.state='active';
 SELECT * INTO v FROM twuanis_canonical_private.package_bank_upgrade_price_versions WHERE configuration_id=c.id AND package_id=p_product ORDER BY effective_from,version LIMIT 1;
 IF NOT FOUND THEN RETURN NULL;END IF;
 money:=v.pricing_authority;amount:=CASE money WHEN 'CRC' THEN v.crc_amount ELSE v.usd_amount END;
 terms:=jsonb_build_object('quantity',c.term_quantity,'unit',c.term_unit,'capabilities',c.capabilities);
 INSERT INTO twuanis_canonical_private.membership_introductory_prices(policy_version,kind,product_id,market,commercial_class,currency,amount,duration,quantity_lower,quantity_upper,population,commercial_terms,original_price_version,source_evidence)
 VALUES('cr-intro-life-2000-v1','package',p_product,'CR','STANDARDIZED',money,amount,twuanis_canonical_private.membership_duration(terms),1,1,'BANK',terms,v.id::text,jsonb_build_object('authority','original canonical Bank price version','bankPriceVersionId',v.id,'bankPriceVersion',v.version,'record',to_jsonb(v))) RETURNING id INTO rid;RETURN rid;
END$$;


--
-- Name: register_future_introductory_price(text, text, text, text); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.register_future_introductory_price(p_kind text, p_product text, p_market text, p_commercial_class text) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE q jsonb;terms jsonb;rid uuid;authority text;at_time timestamptz:=statement_timestamp();BEGIN
 IF p_market IS DISTINCT FROM 'CR' OR p_commercial_class IS DISTINCT FROM 'STANDARDIZED' OR p_kind IS NULL OR p_kind NOT IN('package','addon') THEN RAISE EXCEPTION 'only standardized Costa Rican canonical products eligible';END IF;
 IF p_kind='package' THEN PERFORM id FROM twuanis_canonical_private.intelligence_packages WHERE id=p_product AND state='active' FOR SHARE;
 ELSE PERFORM id FROM twuanis_canonical_private.addon_products WHERE id=p_product AND state='active' AND term_kind='elapsed_days' AND behavior NOT IN('trei_metered','token_usage','inference_usage','variable_ai_usage') FOR SHARE;END IF;
 IF NOT FOUND THEN RAISE EXCEPTION 'existing eligible priced canonical product required';END IF;
 authority:=CASE WHEN p_product='pkg-geographic-distribution-price-range' THEN 'CRC' ELSE 'USD' END;
 q:=twuanis_canonical_private.resolve_offer_price(p_kind,p_product,authority,1,at_time);
 IF q->>'available' IS DISTINCT FROM 'true' OR q->>'source' IS DISTINCT FROM 'OFFER' OR(q->>'offerConfigurationId' IS NULL AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.addon_configurations c WHERE c.id=(q->>'configurationId')::uuid AND c.promotional_usd=(q->>'effectiveRate')::numeric AND c.promotional_until>at_time)) THEN RAISE EXCEPTION 'explicit canonical introductory Offer version required';END IF;
 terms:=q->'terms';
 INSERT INTO twuanis_canonical_private.membership_introductory_prices(policy_version,kind,product_id,market,commercial_class,currency,amount,duration,quantity_lower,quantity_upper,population,commercial_terms,original_price_version,source_evidence)
 VALUES('cr-intro-life-2000-v1',p_kind,p_product,'CR','STANDARDIZED',authority,(q->>'effectiveRate')::numeric,twuanis_canonical_private.membership_duration(terms),1,1,'PRIVATE',terms,coalesce(q->>'offerConfigurationId',q->>'configurationId'),jsonb_build_object('authority','canonical introductory publication enrollment','quote',q)) RETURNING id INTO rid;
 IF p_kind='package' THEN PERFORM twuanis_canonical_private.register_future_bank_introductory_price(p_product,p_market,p_commercial_class);END IF;
 RETURN rid;
END$$;


--
-- Name: reject_csv_evidence_change(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.reject_csv_evidence_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$ BEGIN RAISE EXCEPTION 'CSV source evidence is immutable' USING ERRCODE='55000';END $$;


--
-- Name: reject_immutable_mutation(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.reject_immutable_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
  RAISE EXCEPTION 'canonical immutable object % rejects %', TG_TABLE_NAME, TG_OP
