END
$$;


--
-- Name: resolve_offer_price(text, text, text, integer, timestamp with time zone); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.resolve_offer_price(p_kind text, p_product text, p_currency text, p_quantity integer, p_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE price_currency text:=CASE WHEN p_kind='package'AND p_product IN ('pkg-geographic-distribution-price-range','pkg-matching-market-comparison','pkg-pricing-position-relationships')THEN 'CRC'ELSE p_currency END;fx_rate numeric;usd_quote jsonb;usd_total numeric;money_key text; config uuid;term jsonb;standard numeric;effective numeric;oc uuid;oid uuid;n integer;end_time timestamptz;label_en text;label_es text;shape text;
BEGIN
 IF p_kind='addon' AND p_product='addon-2026-founding-membership' THEN
 IF p_quantity IS DISTINCT FROM 1 OR p_currency IS NULL OR p_currency NOT IN('USD','CRC') OR p_at IS NULL OR NOT isfinite(p_at) THEN RAISE EXCEPTION 'bounded membership pricing required';END IF;
 RETURN twuanis_canonical_private.new_membership_quote(p_currency,p_at);
 END IF;
 IF p_currency='CRC' THEN
  usd_quote:=twuanis_canonical_private.resolve_offer_price(p_kind,p_product,'USD',p_quantity,p_at);
  IF usd_quote IS NULL OR(usd_quote->>'available'IS DISTINCT FROM'true'AND NOT(usd_quote?'standardRate'OR usd_quote?'unitPrice'))THEN RETURN usd_quote||jsonb_build_object('currency','CRC');END IF;
  usd_total:=(usd_quote->>'total')::numeric;
  fx_rate:=(SELECT rate FROM public.fx_rates WHERE base_currency='USD'AND quote_currency='CRC'AND rate_type='reference_sale'AND source='BCCR'AND effective_date<=(p_at AT TIME ZONE 'America/Costa_Rica')::date ORDER BY effective_date DESC LIMIT 1);
  IF fx_rate IS NULL OR fx_rate<=0 THEN RAISE EXCEPTION 'BCCR reference sale rate unavailable';END IF;
  FOR money_key IN SELECT unnest(ARRAY['standardRate','effectiveRate','unitPrice','total','standardTotal'])LOOP
   IF usd_quote->>money_key IS NOT NULL THEN usd_quote:=jsonb_set(usd_quote,ARRAY[money_key],to_jsonb(round((usd_quote->>money_key)::numeric*fx_rate,0)::text));END IF;
  END LOOP;
  IF p_kind='package' AND p_product IN ('pkg-geographic-distribution-price-range','pkg-matching-market-comparison','pkg-pricing-position-relationships') THEN
   SELECT amount INTO STRICT standard FROM twuanis_canonical_private.intelligence_package_prices WHERE package_id=p_product AND currency='CRC';
   SELECT amount INTO effective FROM twuanis_canonical_private.offer_scalar_prices WHERE configuration_id=(usd_quote->>'offerConfigurationId')::uuid AND currency='CRC';effective:=coalesce(effective,standard);
   usd_quote:=usd_quote||jsonb_build_object('standardRate',standard::text,'effectiveRate',effective::text,'total',effective::text,'pricingAuthority','CRC');
  END IF;
  IF usd_quote->>'priceShape'='whole_job'THEN usd_quote:=usd_quote||jsonb_build_object('total',((usd_quote->>'effectiveRate')::numeric*p_quantity)::text);
  ELSIF p_kind='execution_credit'THEN usd_quote:=usd_quote||jsonb_build_object('total',((usd_quote->>'unitPrice')::numeric*p_quantity)::text,'standardTotal',((usd_quote->>'unitPrice')::numeric*p_quantity)::text);END IF;
  RETURN usd_quote||jsonb_build_object('currencyQuotes',jsonb_build_object('USD',jsonb_build_object('total',usd_total::text),'CRC',jsonb_build_object('total',usd_quote->>'total')),'currency','CRC','fx',jsonb_build_object('rate',fx_rate,'source','BCCR','rateType','reference_sale'));
 END IF;

 IF p_kind='addon' AND EXISTS(SELECT 1 FROM twuanis_canonical_private.addon_products p JOIN twuanis_canonical_private.addon_configurations c ON c.id=p.current_configuration_id WHERE p.id=p_product AND p.behavior='homepage_background') THEN
 IF p_currency IS DISTINCT FROM 'USD' OR p_quantity IS DISTINCT FROM 1 OR p_at IS NULL OR NOT isfinite(p_at) THEN RAISE EXCEPTION 'bounded advertising pricing required';END IF;
 RETURN(SELECT jsonb_build_object('available',p.state='active','reason',CASE WHEN p.state<>'active' THEN 'commercial_configuration_pending' END,'targetType','addon','productId',p.id,'configurationId',c.id,'configurationVersion',c.version,'currency','USD','priceShape','scalar','quantity',1,'standardRate',s.amount::text,'effectiveRate',(CASE WHEN p_at<c.promotional_until THEN c.promotional_usd ELSE s.amount END)::text,'total',(CASE WHEN p_at<c.promotional_until THEN c.promotional_usd ELSE s.amount END)::text,'source',CASE WHEN p_at<c.promotional_until THEN 'OFFER' ELSE 'STANDARD' END,'offerEnd',CASE WHEN p_at<c.promotional_until THEN c.promotional_until END,'terms',jsonb_build_object('kind','elapsed_days','quantity',c.calendar_months,'unit',CASE WHEN c.calendar_months IS NOT NULL THEN 'month' END,'durationDays',CASE WHEN c.calendar_months IS NULL THEN c.duration_days END,'behavior',p.behavior,'placementMarket',c.placement_market),'resolvedAt',p_at) FROM twuanis_canonical_private.addon_products p JOIN twuanis_canonical_private.addon_configurations c ON c.id=p.current_configuration_id JOIN twuanis_canonical_private.addon_standard_prices s ON s.configuration_id=c.id AND s.currency='USD' WHERE p.id=p_product);
 END IF;
 IF p_kind='addon' AND p_product='addon-homepage-exposure' THEN
  IF p_currency IS NULL OR p_currency<>'USD' OR p_quantity IS DISTINCT FROM 1 OR p_at IS NULL OR NOT isfinite(p_at) THEN RAISE EXCEPTION 'bounded Homepage Exposure pricing required';END IF;
  SELECT current_configuration_id INTO config FROM twuanis_canonical_private.addon_products WHERE id=p_product AND state='active';
  IF config='05000000-0000-4000-8000-000000000103'::uuid THEN
   standard:=500;effective:=CASE WHEN p_at<'2027-01-01 00:00:00 America/Costa_Rica'::timestamptz THEN 100 ELSE 500 END;
   RETURN jsonb_build_object('available',true,'targetType',p_kind,'productId',p_product,'configurationId',config,'configurationVersion',2,'currency','USD','priceShape','scalar','quantity',1,'standardRate',standard::text,'effectiveRate',effective::text,'total',effective::text,'source',CASE WHEN effective<standard THEN 'OFFER' ELSE 'STANDARD' END,'offerEnd',CASE WHEN effective<standard THEN '2027-01-01 00:00:00 America/Costa_Rica'::timestamptz ELSE NULL END,'priceVersion','HOMEPAGE-EXPOSURE-MONTHLY-R1','terms',jsonb_build_object('kind','elapsed_days','quantity',1,'unit','month','durationDays',NULL,'behavior','homepage_carousel'),'resolvedAt',p_at);
  END IF;
 END IF;
 IF p_kind='addon'AND p_product='addon-2026-founding-membership' THEN
 IF p_quantity IS DISTINCT FROM 1 OR p_currency IS NULL OR p_currency NOT IN('USD','CRC') OR p_at IS NULL OR NOT isfinite(p_at) THEN RAISE EXCEPTION 'bounded membership pricing required';END IF;
 SELECT c.id,s.amount INTO config,standard FROM twuanis_canonical_private.addon_products p JOIN twuanis_canonical_private.addon_configurations c ON c.id=p.current_configuration_id JOIN twuanis_canonical_private.addon_standard_prices s ON s.configuration_id=c.id AND s.currency=price_currency WHERE p.id=p_product AND p.state='active';
 IF config IS NULL THEN RETURN jsonb_build_object('available',false,'reason','unpriced');END IF;
 RETURN jsonb_build_object('available',p_at<'2027-01-01 00:00:00 America/Costa_Rica'::timestamptz,'reason',CASE WHEN p_at>='2027-01-01 00:00:00 America/Costa_Rica'::timestamptz THEN 'membership_acquisition_ended' ELSE NULL END,'targetType',p_kind,'productId',p_product,'configurationId',config,'currency',p_currency,'priceShape','scalar','quantity',1,'standardRate',standard::text,'effectiveRate',standard::text,'total',standard::text,'source','STANDARD','offerEnd','2026-12-31 23:59:59.999999 America/Costa_Rica'::timestamptz,'terms',jsonb_build_object('kind','lifetime','durationDays',NULL,'behavior','founding_pricing_entitlement'),'resolvedAt',p_at);
 END IF;
 IF p_kind='execution_credit' THEN
  IF p_product IS DISTINCT FROM 'execution-credit-v1'OR p_quantity IS NULL OR p_quantity NOT IN(2,5,10,20,50)OR p_currency IS NULL OR p_currency NOT IN('USD','CRC')OR p_at IS NULL OR NOT isfinite(p_at)THEN RAISE EXCEPTION 'Invalid token product/quantity/currency';END IF;
  RETURN (SELECT jsonb_build_object('available',true,'targetType',p_kind,'productId',v.product_id,'productClass','EXECUTION_CREDIT','configurationId',v.id,'priceVersionId',v.id,'priceVersion',v.version,'quantity',p_quantity,'currency',p_currency,'unitPrice',(CASE WHEN p_currency='USD'THEN v.usd_unit ELSE v.crc_unit END)::text,'total',(p_quantity*(CASE WHEN p_currency='USD'THEN v.usd_unit ELSE v.crc_unit END))::text,'standardTotal',(p_quantity*(CASE WHEN p_currency='USD'THEN v.usd_unit ELSE v.crc_unit END))::text,'source','STANDARD','terms',jsonb_build_object('quantity',p_quantity,'unit','execution_credit'),'resolvedAt',p_at)FROM twuanis_canonical_private.execution_credit_price_versions v WHERE v.product_id=p_product AND v.effective_from<=p_at AND(v.effective_until IS NULL OR p_at<v.effective_until));
 END IF;
 IF p_kind IS NULL OR p_kind NOT IN ('package','addon') OR p_currency IS NULL OR p_currency NOT IN ('USD','CRC') OR p_quantity IS NULL OR p_quantity<1 OR p_at IS NULL OR NOT isfinite(p_at) THEN RAISE EXCEPTION 'invalid resolution context'; END IF;
 IF p_kind='package' THEN
  SELECT c.id,jsonb_build_object('quantity',c.term_quantity,'unit',c.term_unit,'capabilities',c.capabilities)
  INTO config,term FROM twuanis_canonical_private.intelligence_packages p JOIN twuanis_canonical_private.intelligence_package_configurations c ON c.id=p.current_configuration_id WHERE p.id=p_product AND p.state='active';
  SELECT amount INTO standard FROM twuanis_canonical_private.intelligence_package_prices WHERE package_id=p_product AND currency=price_currency;
  shape:='scalar';
 ELSE
  SELECT c.id,jsonb_build_object('kind',p.term_kind,'durationDays',CASE WHEN c.calendar_months IS NULL THEN c.duration_days END,'quantity',c.calendar_months,'unit',CASE WHEN c.calendar_months IS NOT NULL THEN 'month' END,'placementMarket',c.placement_market,'behavior',p.behavior),CASE WHEN p.term_kind='whole_job' THEN 'whole_job' ELSE 'scalar' END
  INTO config,term,shape FROM twuanis_canonical_private.addon_products p JOIN twuanis_canonical_private.addon_configurations c ON c.id=p.current_configuration_id WHERE p.id=p_product AND p.state='active' AND p.term_kind<>'unconfigured';
  IF shape='whole_job' THEN
   SELECT unit_rate INTO standard FROM twuanis_canonical_private.addon_quantity_tiers WHERE configuration_id=config AND currency=price_currency AND p_quantity BETWEEN lower_quantity AND upper_quantity;
  ELSE
   SELECT amount INTO standard FROM twuanis_canonical_private.addon_standard_prices WHERE configuration_id=config AND currency=price_currency;
  END IF;
 END IF;
 IF config IS NULL THEN RETURN jsonb_build_object('available',false,'reason','target_unavailable'); END IF;
 IF shape='scalar' AND p_quantity<>1 THEN RAISE EXCEPTION 'scalar quantity must be one'; END IF;
 IF standard IS NULL THEN RETURN jsonb_build_object('available',false,'reason','unpriced'); END IF;
 SELECT count(*) INTO n FROM twuanis_canonical_private.offers o JOIN twuanis_canonical_private.offer_configurations c ON c.id=o.current_configuration_id
 WHERE ((p_kind='package' AND o.package_id=p_product) OR (p_kind='addon' AND o.addon_id=p_product)) AND o.state='eligible' AND p_at BETWEEN c.starts_at AND c.ends_at
 AND (EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_scalar_prices WHERE configuration_id=c.id AND currency=price_currency)
 OR EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_quantity_tiers WHERE configuration_id=c.id AND currency=price_currency AND p_quantity BETWEEN lower_quantity AND upper_quantity));
 IF n>1 THEN RAISE EXCEPTION 'ambiguous applicable offer'; END IF;
 IF n=1 THEN
  SELECT o.id,c.id,c.ends_at,c.name_en,c.name_es,coalesce(s.amount,t.unit_rate) INTO oid,oc,end_time,label_en,label_es,effective
  FROM twuanis_canonical_private.offers o JOIN twuanis_canonical_private.offer_configurations c ON c.id=o.current_configuration_id
  LEFT JOIN twuanis_canonical_private.offer_scalar_prices s ON s.configuration_id=c.id AND s.currency=price_currency
  LEFT JOIN twuanis_canonical_private.offer_quantity_tiers t ON t.configuration_id=c.id AND t.currency=price_currency AND p_quantity BETWEEN t.lower_quantity AND t.upper_quantity
  WHERE ((p_kind='package' AND o.package_id=p_product) OR (p_kind='addon' AND o.addon_id=p_product)) AND o.state='eligible' AND p_at BETWEEN c.starts_at AND c.ends_at AND coalesce(s.amount,t.unit_rate) IS NOT NULL;
 END IF;
 effective:=coalesce(effective,standard);
 IF p_kind='package' AND p_product IN ('pkg-geographic-distribution-price-range','pkg-matching-market-comparison','pkg-pricing-position-relationships') THEN
  SELECT rate INTO fx_rate FROM public.fx_rates WHERE base_currency='USD' AND quote_currency='CRC' AND rate_type='reference_sale' AND source='BCCR' AND effective_date<=(p_at AT TIME ZONE 'America/Costa_Rica')::date ORDER BY effective_date DESC LIMIT 1;
  IF fx_rate IS NULL OR fx_rate<=0 THEN RAISE EXCEPTION 'BCCR reference sale rate unavailable';END IF;
  standard:=round(standard/fx_rate,2);effective:=round(effective/fx_rate,2);
 END IF;
 RETURN jsonb_build_object('available',true,'targetType',p_kind,'productId',p_product,'configurationId',config,'currency',p_currency,
 'priceShape',shape,'quantity',p_quantity,'standardRate',standard::text,'effectiveRate',effective::text,'total',(effective*p_quantity)::text,
 'source',CASE WHEN oid IS NULL THEN 'STANDARD' ELSE 'OFFER' END,'offerId',oid,'offerConfigurationId',oc,'offerEnd',end_time,'name_en',label_en,'name_es',label_es,'terms',term,'resolvedAt',p_at)||CASE WHEN p_kind='package'AND p_product IN ('pkg-geographic-distribution-price-range','pkg-matching-market-comparison','pkg-pricing-position-relationships')THEN jsonb_build_object('pricingAuthority','CRC','fx',jsonb_build_object('rate',fx_rate,'source','BCCR','rateType','reference_sale'))ELSE '{}'::jsonb END;
END $$;


--
-- Name: resolve_package_bank_upgrade_price(text, text, text, boolean, timestamp with time zone); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.resolve_package_bank_upgrade_price(p_product text, p_currency text, p_duration text, p_bank_upgrade boolean, p_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE cfg uuid;b jsonb;v twuanis_canonical_private.package_bank_upgrade_price_versions%ROWTYPE;inc numeric:=0;latest timestamptz;n integer;
BEGIN
 IF p_product IS NULL OR p_currency IS NULL OR p_currency NOT IN('USD','CRC') OR p_duration IS DISTINCT FROM 'month' OR p_bank_upgrade IS NULL OR p_at IS NULL OR NOT isfinite(p_at) THEN RAISE EXCEPTION 'typed monthly Package pricing required' USING ERRCODE='22023';END IF;
 SELECT p.current_configuration_id INTO cfg FROM twuanis_canonical_private.intelligence_packages p JOIN twuanis_canonical_private.intelligence_package_configurations c ON c.id=p.current_configuration_id AND c.package_id=p.id WHERE p.id=p_product AND p.state='active';
 IF cfg IS NULL THEN RAISE EXCEPTION 'active canonical Package required' USING ERRCODE='22023';END IF;
 b:=twuanis_canonical_private.resolve_offer_price('package',p_product,p_currency,1,p_at);
 IF b->>'available' IS DISTINCT FROM 'true' OR (b->>'configurationId')::uuid IS DISTINCT FROM cfg THEN RAISE EXCEPTION 'canonical base pricing unavailable' USING ERRCODE='23514';END IF;
 IF p_bank_upgrade THEN
 SELECT max(effective_from) INTO latest FROM twuanis_canonical_private.package_bank_upgrade_price_versions WHERE configuration_id=cfg AND package_id=p_product AND effective_from<=p_at;
 SELECT count(*) INTO n FROM twuanis_canonical_private.package_bank_upgrade_price_versions WHERE configuration_id=cfg AND package_id=p_product AND effective_from=latest;
 IF n<>1 THEN RAISE EXCEPTION 'missing or ambiguous Bank upgrade price' USING ERRCODE='23514';END IF;
 SELECT * INTO STRICT v FROM twuanis_canonical_private.package_bank_upgrade_price_versions WHERE configuration_id=cfg AND package_id=p_product AND effective_from=latest;
 inc:=CASE WHEN v.pricing_authority='CRC' THEN CASE p_currency WHEN 'CRC'THEN v.crc_amount ELSE round(v.crc_amount/(SELECT rate FROM public.fx_rates WHERE base_currency='USD'AND quote_currency='CRC'AND rate_type='reference_sale'AND source='BCCR'AND effective_date<=(p_at AT TIME ZONE 'America/Costa_Rica')::date ORDER BY effective_date DESC LIMIT 1),2)END ELSE CASE p_currency WHEN 'USD'THEN v.usd_amount ELSE round(v.usd_amount*(SELECT rate FROM public.fx_rates WHERE base_currency='USD'AND quote_currency='CRC'AND rate_type='reference_sale'AND source='BCCR'AND effective_date<=(p_at AT TIME ZONE 'America/Costa_Rica')::date ORDER BY effective_date DESC LIMIT 1),0)END END;
 END IF;
 RETURN jsonb_build_object('base',b,'baseTotal',b->>'total','bankUpgrade',jsonb_build_object('selected',p_bank_upgrade,'priceVersionId',v.id,'priceVersion',v.version,'amount',inc::text),'total',((b->>'total')::numeric+inc)::text,'standardTotal',((b->>'standardRate')::numeric+inc)::text,'currency',p_currency,'fx',b->'fx','configurationId',cfg,'duration','month');
END $$;


--
-- Name: resolve_publisher(uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.resolve_publisher(p_owner uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE v_id uuid;
BEGIN
 IF p_owner IS NULL THEN RAISE EXCEPTION 'customer identity required' USING ERRCODE='22023'; END IF;
 PERFORM twuanis_canonical_private.lock_capacity_policy(false);
 SELECT id INTO v_id FROM public.publisher_accounts WHERE owner_user_id=p_owner FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'publisher not provisioned' USING ERRCODE='P0002'; END IF;
 RETURN v_id;
END $$;


--
-- Name: revoke_all_administrative_access(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.revoke_all_administrative_access() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  revoked_count bigint;
BEGIN
  UPDATE twuanis_canonical_private.administrative_access_grants
  SET
    revoked_at = clock_timestamp(),
    revoked_by = session_user
  WHERE revoked_at IS NULL;

  GET DIAGNOSTICS revoked_count = ROW_COUNT;

  RETURN revoked_count;
END
$$;


--
-- Name: s11_image_string(jsonb, boolean); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.s11_image_string(v jsonb, nested boolean DEFAULT false) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE f double precision; t text;
BEGIN
 CASE jsonb_typeof(v)
 WHEN 'string' THEN RETURN v#>>'{}';
 WHEN 'null' THEN RETURN CASE WHEN nested THEN '' ELSE 'null' END;
 WHEN 'boolean' THEN RETURN v::text;
 WHEN 'object' THEN RETURN '[object Object]';
 WHEN 'array' THEN RETURN coalesce((SELECT string_agg(twuanis_canonical_private.s11_image_string(value,true),',' ORDER BY n)
   FROM jsonb_array_elements(v) WITH ORDINALITY e(value,n)),'');
 WHEN 'number' THEN
  BEGIN f:=(v::text)::double precision; EXCEPTION WHEN numeric_value_out_of_range THEN
   IF abs((v::text)::numeric)<1 THEN RETURN '0'; END IF;
   RETURN CASE WHEN left(v::text,1)='-' THEN '-Infinity' ELSE 'Infinity' END; END;
  IF f=0 THEN RETURN '0'; END IF;
  t:=f::text;
  IF abs(f)>=0.000001 AND abs(f)<1e21 THEN RETURN trim_scale(t::numeric)::text; END IF;
  RETURN regexp_replace(t,'e([+-])0+','e\1');
 ELSE RAISE EXCEPTION 'unsupported stored JSON';
 END CASE;
END $$;


--
-- Name: s11_image_trim(text); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.s11_image_trim(v text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
 SELECT btrim(v,chr(9)||chr(10)||chr(11)||chr(12)||chr(13)||chr(32)||chr(160)||chr(5760)||
 chr(8192)||chr(8193)||chr(8194)||chr(8195)||chr(8196)||chr(8197)||chr(8198)||chr(8199)||
 chr(8200)||chr(8201)||chr(8202)||chr(8232)||chr(8233)||chr(8239)||chr(8287)||chr(12288)||chr(65279))
$$;


--
-- Name: s3_admission_command(uuid, bigint, text, text, uuid, jsonb, jsonb, boolean, jsonb); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.s3_admission_command(p_listing uuid, p_expected bigint, p_actor_kind text, p_actor_identity text, p_request uuid, p_domains jsonb, p_source jsonb, p_administrative_clear boolean, p_extra_content jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
 l public.listings%ROWTYPE; before_l public.listings%ROWTYPE; admission_intent jsonb; own uuid; pub uuid; receipt public.canonical_operation_receipts%ROWTYPE;
 payload jsonb; fingerprint text; op text; rid uuid:=gen_random_uuid(); result jsonb; changed boolean:=false;
 item record; v jsonb; ids bigint[]; oldids bigint[]; dim text; labels text[]; tags text[]; termrow record;
 geo bigint[]; oldgeo jsonb; newgeo jsonb; q record; f public.listing_fact_evidence%ROWTYPE; oldf jsonb;
 amount numeric; oldamount numeric; newcurrency text; moneychanged boolean:=false; eventkind text;
 ev text; nextstate text; lifechanged boolean:=false; deadline timestamptz; observed timestamptz:=clock_timestamp();
 allowance bigint; used bigint; ruleset uuid; ruleid uuid; band bigint; total integer:=0;
 sourceobs public.listing_source_observations%ROWTYPE; sourceid uuid:=gen_random_uuid(); sourcefp text; sourcetime timestamptz;
 conflict boolean:=false; txconf boolean; geoconf boolean; oldrev bigint; finalrev bigint; group_name text; field_name text; normalized_geo jsonb;
BEGIN
 BEGIN
 IF p_administrative_clear THEN
  IF p_actor_kind IS DISTINCT FROM 'trusted' OR p_source IS NOT NULL OR p_actor_identity IS DISTINCT FROM ('admin:'||twuanis_canonical_private.assert_administrative_permission('listings.manage')::text) THEN RAISE EXCEPTION 'administrative context required' USING ERRCODE='42501'; END IF;
 END IF;
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'READ COMMITTED required' USING ERRCODE='0A000'; END IF;
 IF p_listing IS NULL OR p_request IS NULL OR p_expected IS NULL OR p_expected<0
 OR p_actor_kind IS NULL OR p_actor_kind NOT IN ('owner','trusted','system','migration')
 OR p_actor_identity IS NULL OR length(p_actor_identity) NOT BETWEEN 1 AND 256 OR p_actor_identity COLLATE "C" !~ '[^[:space:]]' THEN
  RAISE EXCEPTION 'explicit command identity required' USING ERRCODE='22023';
 END IF;
 PERFORM twuanis_canonical_private.s3_keys(p_domains,ARRAY['geography','semantics','facts','measurements','money','lifecycle']);
 -- Normalize sets before fingerprinting: order and duplicates are not semantic changes.
 IF p_domains ? 'semantics' THEN
  PERFORM twuanis_canonical_private.s3_keys(p_domains->'semantics',ARRAY['property_type','utility','environment','terrain','accessibility','legal_status']);
  FOR item IN SELECT key,value FROM jsonb_each(p_domains->'semantics') LOOP
   ids:=twuanis_canonical_private.s3_term_ids(item.value); total:=total+cardinality(ids);
   p_domains:=jsonb_set(p_domains,ARRAY['semantics',item.key],coalesce((SELECT jsonb_agg(x::text ORDER BY x) FROM unnest(ids)x),'[]'::jsonb));
  END LOOP;
  IF total>64 THEN RAISE EXCEPTION 'command semantic bound' USING ERRCODE='54000'; END IF;
 END IF;
 -- Numeric scale is representation, not semantic payload identity.
 IF p_domains ? 'money' AND p_domains->'money' ? 'amount' THEN
  p_domains:=jsonb_set(p_domains,'{money,amount}',to_jsonb(trim_scale(twuanis_canonical_private.s3_decimal(p_domains->'money'->'amount'))::text));
 END IF;
 IF p_domains ? 'lifecycle' AND p_domains->'lifecycle' ? 'duration_seconds' THEN
  p_domains:=jsonb_set(p_domains,'{lifecycle,duration_seconds}',to_jsonb(trim_scale(twuanis_canonical_private.s3_decimal(p_domains->'lifecycle'->'duration_seconds'))::text));
 END IF;
 FOREACH group_name IN ARRAY ARRAY['facts','measurements'] LOOP
  IF p_domains ? group_name THEN
   FOR item IN SELECT key,value FROM jsonb_each(p_domains->group_name) LOOP
    FOREACH field_name IN ARRAY ARRAY['value','lower','upper'] LOOP
     IF item.value ? field_name AND item.value->field_name<>'null'::jsonb THEN
      p_domains:=jsonb_set(p_domains,ARRAY[group_name,item.key,field_name],to_jsonb(trim_scale(twuanis_canonical_private.s3_decimal(item.value->field_name))::text));
     END IF;
    END LOOP;
   END LOOP;
  END IF;
 END LOOP;
 IF p_domains ? 'geography' THEN
  p_domains:=jsonb_set(p_domains,'{geography}',jsonb_build_object('district',NULL)||(p_domains->'geography'));
 END IF;
 IF p_source IS NOT NULL THEN
  PERFORM twuanis_canonical_private.s3_keys(p_source,ARRAY['source_name','source_listing_id','observation_id','observed_at','transaction','geography'],ARRAY['source_name','source_listing_id','observation_id','observed_at','transaction','geography']);
  normalized_geo:=jsonb_build_object('district',NULL)||(p_source->'geography');
  p_source:=jsonb_set(p_source,'{geography}',normalized_geo);
  IF p_domains ? 'geography' AND p_domains->'geography' IS DISTINCT FROM normalized_geo THEN RAISE EXCEPTION 'source geography disagrees with mutation' USING ERRCODE='22023'; END IF;
  p_domains:=jsonb_set(p_domains,'{geography}',normalized_geo);
  sourcetime:=(p_source->>'observed_at')::timestamptz;
  IF sourcetime IS NULL OR NOT isfinite(sourcetime) THEN RAISE EXCEPTION 'source observation time required' USING ERRCODE='22023'; END IF;
  p_source:=jsonb_set(p_source,'{observed_at}',to_jsonb(to_char(sourcetime AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')));
 END IF;
 op:=CASE WHEN p_source IS NULL THEN 'domain_mutation' ELSE 'source_observation' END;
 payload:=jsonb_build_object('listing',p_listing,'expected',p_expected,'domains',p_domains,'source',p_source);
 fingerprint:=encode(sha256(convert_to(payload::text,'UTF8')),'hex');
 -- Resolve immutable ownership before locking, then recheck after listing lock.
 SELECT owner_id,publisher_account_id INTO own,pub FROM public.listings WHERE id=p_listing;
 IF NOT FOUND THEN RAISE EXCEPTION 'listing missing' USING ERRCODE='P0002'; END IF;
 IF own IS NOT NULL THEN
  IF pub IS NULL THEN RAISE EXCEPTION 'canonical customer publisher missing' USING ERRCODE='55000'; END IF;
  IF twuanis_canonical_private.lock_publisher(pub) IS DISTINCT FROM own THEN RAISE EXCEPTION 'publisher ownership mismatch' USING ERRCODE='55000'; END IF;
 ELSE
  IF pub IS NOT NULL OR p_actor_kind='owner' THEN RAISE EXCEPTION 'invalid ownerless authority' USING ERRCODE='42501'; END IF;
  PERFORM twuanis_canonical_private.lock_capacity_policy(false);
 END IF;
 IF p_actor_kind='owner' AND p_actor_identity IS DISTINCT FROM own::text THEN RAISE EXCEPTION 'owner context mismatch' USING ERRCODE='42501'; END IF;
 IF p_source IS NOT NULL THEN
  IF p_actor_kind NOT IN ('trusted','system') THEN RAISE EXCEPTION 'source authority required' USING ERRCODE='42501'; END IF;
  PERFORM twuanis_canonical_private.s3_keys(p_source,ARRAY['source_name','source_listing_id','observation_id','observed_at','transaction','geography'],ARRAY['source_name','source_listing_id','observation_id','observed_at','transaction','geography']);
  IF jsonb_typeof(p_source->'source_name') IS DISTINCT FROM 'string' OR length(p_source->>'source_name') NOT BETWEEN 1 AND 128
   OR jsonb_typeof(p_source->'source_listing_id') IS DISTINCT FROM 'string' OR length(p_source->>'source_listing_id') NOT BETWEEN 1 AND 256
   OR jsonb_typeof(p_source->'observation_id') IS DISTINCT FROM 'string' OR length(p_source->>'observation_id') NOT BETWEEN 1 AND 256
   OR p_source->>'transaction' NOT IN ('sale','rent') THEN RAISE EXCEPTION 'invalid source identity' USING ERRCODE='22023'; END IF;
  sourcetime:=(p_source->>'observed_at')::timestamptz;
  IF sourcetime IS NULL OR NOT isfinite(sourcetime) THEN RAISE EXCEPTION 'source observation time required' USING ERRCODE='22023'; END IF;
  sourcefp:=encode(sha256(convert_to(jsonb_build_object('listing',p_listing,'source',p_source,'domains',p_domains)::text,'UTF8')),'hex');
  PERFORM pg_advisory_xact_lock(3103,hashtext(jsonb_build_array(p_source->>'source_name',p_source->>'source_listing_id')::text));
 END IF;
 PERFORM pg_advisory_xact_lock(3104,hashtext(jsonb_build_array(p_actor_kind,p_actor_identity,op,p_request)::text));
 SELECT * INTO receipt FROM public.canonical_operation_receipts WHERE authority_kind=p_actor_kind AND authority_identity=p_actor_identity AND operation_type=op AND request_id=p_request;
 IF FOUND THEN
  IF receipt.payload_fingerprint<>fingerprint OR receipt.listing_id IS DISTINCT FROM p_listing THEN RAISE EXCEPTION 'idempotency conflict' USING ERRCODE='22023'; END IF;
  RETURN jsonb_build_object('outcome',receipt.outcome,'revision',receipt.result_revision::text,'receipt_id',receipt.id::text,'replayed',true);
 END IF;
 SELECT * INTO STRICT l FROM public.listings WHERE id=p_listing FOR UPDATE;
 IF l.owner_id IS DISTINCT FROM own OR l.publisher_account_id IS DISTINCT FROM pub THEN RAISE EXCEPTION 'ownership changed' USING ERRCODE='40001'; END IF;
 IF l.canonical_domain_version IS DISTINCT FROM 1 OR l.transaction_type NOT IN ('sale','rent') OR l.listing_status IS NULL THEN RAISE EXCEPTION 'canonical listing required' USING ERRCODE='55000'; END IF;
 -- A source replay is observation-idempotent even with a new operation request ID.
 IF p_source IS NOT NULL THEN
  IF l.source_name IS DISTINCT FROM p_source->>'source_name' OR l.source_listing_id IS DISTINCT FROM p_source->>'source_listing_id' THEN RAISE EXCEPTION 'source appearance mismatch' USING ERRCODE='22023'; END IF;
  SELECT * INTO sourceobs FROM public.listing_source_observations WHERE source_name=l.source_name AND source_listing_id=l.source_listing_id AND source_observation_id=p_source->>'observation_id';
  IF FOUND THEN
   IF sourceobs.payload_fingerprint<>sourcefp OR sourceobs.listing_id IS DISTINCT FROM p_listing THEN RAISE EXCEPTION 'source observation conflict' USING ERRCODE='22023'; END IF;
   RETURN jsonb_build_object('outcome',sourceobs.outcome,'revision',sourceobs.result_revision::text,'observation_id',sourceobs.id::text,'replayed',true);
  END IF;
 END IF;
 IF l.canonical_revision<>p_expected THEN RAISE EXCEPTION 'stale canonical revision' USING ERRCODE='40001'; END IF;
 before_l:=l;oldrev:=l.canonical_revision;
 -- Canonical eligibility requires established P+C and exact projection provenance.
 SELECT jsonb_object_agg(t.term_type,t.official_code) INTO oldgeo FROM public.listing_membership_origins o JOIN public.ontology_terms t ON t.id=o.ontology_term_id WHERE o.listing_id=p_listing AND o.origin_domain='geography' AND t.term_type IN ('province','canton','district');
 geo:=twuanis_canonical_private.s3_geography(oldgeo);
 SELECT p.term_name AS province,c.term_name AS canton,d.term_name AS district INTO q
 FROM public.ontology_terms p JOIN public.ontology_terms c ON c.id=geo[2]
 LEFT JOIN public.ontology_terms d ON d.id=geo[3] WHERE p.id=geo[1];
 IF (l.province,l.canton,l.district,l.province_normalized,l.canton_normalized,l.district_normalized)
 IS DISTINCT FROM (q.province,q.canton,q.district,twuanis_private.normalize_geographic_projection(q.province),twuanis_private.normalize_geographic_projection(q.canton),twuanis_private.normalize_geographic_projection(q.district)) THEN
  RAISE EXCEPTION 'canonical geography projection disagreement' USING ERRCODE='55000';
 END IF;
 IF (SELECT count(*) FROM public.listing_semantic_selections WHERE listing_id=p_listing AND dimension='property_type')<>1 THEN
  RAISE EXCEPTION 'canonical property type missing' USING ERRCODE='55000';
 END IF;
 IF (SELECT count(*) FROM public.listing_membership_origins o JOIN public.ontology_terms t ON t.id=o.ontology_term_id WHERE o.listing_id=p_listing AND o.origin_domain='geography' AND t.term_type IN ('province','canton','district'))<>cardinality(geo)
 OR EXISTS(SELECT 1 FROM public.listing_membership_origins o WHERE o.listing_id=p_listing AND NOT EXISTS(SELECT 1 FROM public.listings_ontology_terms lot WHERE lot.listing_id=p_listing AND lot.ontology_term_id=o.ontology_term_id))
 OR EXISTS(SELECT 1 FROM public.listings_ontology_terms lot WHERE lot.listing_id=p_listing AND NOT EXISTS(SELECT 1 FROM public.listing_membership_origins o WHERE o.listing_id=p_listing AND o.ontology_term_id=lot.ontology_term_id)) THEN RAISE EXCEPTION 'canonical provenance incomplete' USING ERRCODE='55000'; END IF;
 IF p_source IS NOT NULL THEN
  newgeo:=p_source->'geography'; geo:=twuanis_canonical_private.s3_geography(newgeo);
  txconf:=l.transaction_type IS DISTINCT FROM p_source->>'transaction';
  geoconf:=oldgeo->>'province' IS DISTINCT FROM newgeo->>'province' OR oldgeo->>'canton' IS DISTINCT FROM newgeo->>'canton';
  conflict:=txconf OR geoconf;
  IF conflict THEN
   INSERT INTO public.listing_source_observations(id,source_name,source_listing_id,source_observation_id,listing_id,source_observed_at,outcome,payload_fingerprint,result_revision)
   VALUES(sourceid,l.source_name,l.source_listing_id,p_source->>'observation_id',p_listing,sourcetime,'conflict',sourcefp,oldrev);
   INSERT INTO public.source_identity_conflicts(listing_id,observation_id,source_name,source_listing_id,existing_transaction_type,observed_transaction_type,existing_province_code,existing_canton_code,observed_province_code,observed_canton_code,conflict_type)
   VALUES(p_listing,sourceid,l.source_name,l.source_listing_id,l.transaction_type,p_source->>'transaction',oldgeo->>'province',oldgeo->>'canton',newgeo->>'province',newgeo->>'canton',CASE WHEN txconf AND geoconf THEN 'transaction_and_geography' WHEN txconf THEN 'transaction' ELSE 'geography' END);
   INSERT INTO public.canonical_operation_receipts(id,authority_kind,authority_identity,operation_type,request_id,payload_fingerprint,outcome,listing_id,result_revision)
   VALUES(rid,p_actor_kind,p_actor_identity,op,p_request,fingerprint,'conflict',p_listing,oldrev);
   RETURN jsonb_build_object('outcome','conflict','revision',oldrev::text,'receipt_id',rid::text,'replayed',false);
  END IF;
  -- An older observation is durable evidence, never a stale overwrite.
  IF l.last_seen IS NOT NULL AND sourcetime<l.last_seen THEN
   INSERT INTO public.listing_source_observations(id,source_name,source_listing_id,source_observation_id,listing_id,source_observed_at,outcome,payload_fingerprint,result_revision)
   VALUES(sourceid,l.source_name,l.source_listing_id,p_source->>'observation_id',p_listing,sourcetime,'stale',sourcefp,oldrev);
   INSERT INTO public.canonical_operation_receipts(id,authority_kind,authority_identity,operation_type,request_id,payload_fingerprint,outcome,listing_id,result_revision)
   VALUES(rid,p_actor_kind,p_actor_identity,op,p_request,fingerprint,'stale',p_listing,oldrev);
   RETURN jsonb_build_object('outcome','stale','revision',oldrev::text,'receipt_id',rid::text,'replayed',false);
  END IF;
  IF p_domains ? 'geography' AND p_domains->'geography' IS DISTINCT FROM newgeo THEN RAISE EXCEPTION 'source geography disagrees with mutation' USING ERRCODE='22023'; END IF;
  p_domains:=jsonb_set(p_domains,'{geography}',newgeo);
 END IF;
 IF l.listing_status IN ('archived','deleted') AND (p_domains - 'lifecycle')<>'{}'::jsonb THEN RAISE EXCEPTION 'state does not permit evidence edit' USING ERRCODE='22023'; END IF;
 IF p_domains ? 'geography' THEN
  v:=p_domains->'geography';
  -- Source identity already resolved and locked the identical supplied geography.
  IF p_source IS NULL THEN geo:=twuanis_canonical_private.s3_geography(v); END IF;
  IF (oldgeo->>'province',oldgeo->>'canton',oldgeo->>'district') IS DISTINCT FROM (v->>'province',v->>'canton',v->>'district') THEN
   PERFORM twuanis_canonical_private.s3_origins(p_listing,'geography',geo);
   SELECT term_name INTO l.province FROM public.ontology_terms WHERE id=geo[1];
   SELECT term_name INTO l.canton FROM public.ontology_terms WHERE id=geo[2];
   SELECT term_name INTO l.district FROM public.ontology_terms WHERE id=geo[3];
   l.province_normalized:=twuanis_private.normalize_geographic_projection(l.province);
   l.canton_normalized:=twuanis_private.normalize_geographic_projection(l.canton);
   l.district_normalized:=twuanis_private.normalize_geographic_projection(l.district);changed:=true;
  END IF;
 END IF;
 FOR item IN SELECT key,value FROM jsonb_each(coalesce(p_domains->'semantics','{}')) ORDER BY key LOOP
  dim:=item.key;ids:=twuanis_canonical_private.s3_term_ids(item.value);
  IF (dim='property_type' AND cardinality(ids)<>1) OR (dim='legal_status' AND cardinality(ids)>1) THEN RAISE EXCEPTION 'semantic cardinality' USING ERRCODE='23514'; END IF;
  labels:='{}';
  FOR termrow IN SELECT * FROM public.ontology_terms WHERE id=ANY(ids) ORDER BY id FOR SHARE LOOP
   IF termrow.term_type IS DISTINCT FROM dim OR termrow.level IS DISTINCT FROM 1 OR termrow.term_name IS NULL THEN RAISE EXCEPTION 'semantic term type/level' USING ERRCODE='23514'; END IF;
   labels:=array_append(labels,termrow.term_name);
  END LOOP;
  IF cardinality(labels)<>cardinality(ids) THEN RAISE EXCEPTION 'unknown semantic term' USING ERRCODE='23514'; END IF;
  IF dim='accessibility' THEN
   PERFORM term_id FROM twuanis_canonical_private.accessibility_identity WHERE term_id=ANY(ids) ORDER BY term_id FOR SHARE;
   SELECT array_agg(code) INTO tags FROM twuanis_canonical_private.accessibility_identity WHERE term_id=ANY(ids);
   IF coalesce(cardinality(tags),0)<>cardinality(ids) OR ('boat'=ANY(tags) AND cardinality(tags)>1) OR ('4x4'=ANY(tags) AND tags && ARRAY['2wd','paved']) THEN RAISE EXCEPTION 'accessibility set incompatible or unmapped' USING ERRCODE='23514'; END IF;
  END IF;
  SELECT coalesce(array_agg(ontology_term_id ORDER BY ontology_term_id),'{}') INTO oldids FROM public.listing_semantic_selections WHERE listing_id=p_listing AND dimension=dim;
  IF oldids IS DISTINCT FROM ids THEN
   DELETE FROM public.listing_semantic_selections WHERE listing_id=p_listing AND dimension=dim;
   INSERT INTO public.listing_semantic_selections(listing_id,dimension,ontology_term_id) SELECT p_listing,dim,x FROM unnest(ids)x;
   PERFORM twuanis_canonical_private.s3_origins(p_listing,dim,ids);
   CASE dim WHEN 'property_type' THEN l.property_type:=labels[1]; WHEN 'utility' THEN l.utility:=labels;
    WHEN 'terrain' THEN l.terrain:=labels; WHEN 'environment' THEN l.environment:=array_to_string(labels,'|');
    WHEN 'accessibility' THEN l.accessibility:=array_to_string(labels,'|'); WHEN 'legal_status' THEN l.legal_status:=labels[1]; END CASE;
   changed:=true;
  END IF;
 END LOOP;
 IF p_domains ? 'facts' THEN PERFORM twuanis_canonical_private.s3_keys(p_domains->'facts',ARRAY['bedrooms','bathrooms','parking','year_built','distance_to_paved_road']); END IF;
 FOR item IN SELECT key,value FROM jsonb_each(coalesce(p_domains->'facts','{}')) ORDER BY key LOOP
  dim:=item.key;v:=item.value;ids:='{}';ruleid:=NULL;ruleset:=NULL;band:=NULL;
  PERFORM twuanis_canonical_private.s3_keys(v,ARRAY['kind','value','term','lower','upper','lower_inclusive','upper_inclusive','source','reference','rule_set'],ARRAY['kind']);
  SELECT to_jsonb(e)-ARRAY['recorded_at','observed_at'] INTO oldf FROM public.listing_fact_evidence e WHERE listing_id=p_listing AND dimension=dim;
  IF v->>'kind'='clear' THEN
   IF v<>'{"kind":"clear"}'::jsonb THEN RAISE EXCEPTION 'clear has no value' USING ERRCODE='22023'; END IF;
   f:=NULL;
  ELSE
   IF v->>'kind' NOT IN ('exact','category','range') OR v->>'kind' IS NULL THEN RAISE EXCEPTION 'invalid fact kind' USING ERRCODE='22023'; END IF;
   f:=NULL;f.listing_id:=p_listing;f.dimension:=dim;f.kind:=v->>'kind';f.evidence_source:=v->>'source';f.evidence_reference:=v->>'reference';
   IF f.kind='exact' THEN
    IF v ?| ARRAY['term','lower','upper','lower_inclusive','upper_inclusive'] THEN RAISE EXCEPTION 'exact fact payload' USING ERRCODE='22023'; END IF;
    f.exact_value:=twuanis_canonical_private.s3_decimal(v->'value');
   ELSIF f.kind='category' THEN
    IF v ?| ARRAY['value','lower','upper','lower_inclusive','upper_inclusive','rule_set'] THEN RAISE EXCEPTION 'category payload' USING ERRCODE='22023'; END IF;
    ids:=twuanis_canonical_private.s3_term_ids(jsonb_build_array(v->'term'));f.category_term_id:=ids[1];
   ELSE
    IF v ?| ARRAY['value','term','rule_set'] OR NOT v ?& ARRAY['lower','upper','lower_inclusive','upper_inclusive'] OR jsonb_typeof(v->'lower_inclusive')<>'boolean' OR jsonb_typeof(v->'upper_inclusive')<>'boolean' THEN RAISE EXCEPTION 'explicit range required' USING ERRCODE='22023'; END IF;
    f.range_lower:=CASE WHEN v->'lower'='null'::jsonb THEN NULL ELSE twuanis_canonical_private.s3_decimal(v->'lower') END;
    f.range_upper:=CASE WHEN v->'upper'='null'::jsonb THEN NULL ELSE twuanis_canonical_private.s3_decimal(v->'upper') END;
    f.lower_inclusive:=(v->>'lower_inclusive')::boolean;f.upper_inclusive:=(v->>'upper_inclusive')::boolean;
   END IF;
  END IF;
  IF v ? 'rule_set' THEN
   ruleset:=(v->>'rule_set')::uuid;
   PERFORM s.id FROM public.listing_classification_rule_sets s JOIN twuanis_canonical_private.classification_seals z ON z.rule_set_id=s.id WHERE s.id=ruleset AND s.domain=dim FOR SHARE OF s;
   IF NOT FOUND THEN RAISE EXCEPTION 'sealed typed classification required' USING ERRCODE='55000'; END IF;
   SELECT r.id,r.ontology_term_id INTO STRICT ruleid,band FROM public.listing_classification_rules r WHERE r.rule_set_id=ruleset AND r.bounds @> f.exact_value;
   ids:=ARRAY[band];
  END IF;
  IF oldf IS DISTINCT FROM (CASE WHEN f.kind IS NULL THEN NULL ELSE to_jsonb(f)-ARRAY['recorded_at','observed_at'] END)
   OR (SELECT array_agg(DISTINCT classification_rule_id) FILTER(WHERE classification_rule_id IS NOT NULL) FROM public.listing_membership_origins WHERE listing_id=p_listing AND origin_domain=dim) IS DISTINCT FROM (CASE WHEN ruleid IS NULL THEN NULL ELSE ARRAY[ruleid] END) THEN
   DELETE FROM public.listing_fact_evidence WHERE listing_id=p_listing AND dimension=dim;
   IF f.kind IS NOT NULL THEN
    INSERT INTO public.listing_fact_evidence(listing_id,dimension,kind,exact_value,category_term_id,range_lower,range_upper,lower_inclusive,upper_inclusive,evidence_source,evidence_reference)
    VALUES(p_listing,dim,f.kind,f.exact_value,f.category_term_id,f.range_lower,f.range_upper,f.lower_inclusive,f.upper_inclusive,f.evidence_source,f.evidence_reference);
   END IF;
   PERFORM twuanis_canonical_private.s3_origins(p_listing,dim,ids,ruleid);
   IF f.kind='category' THEN SELECT term_name INTO dim FROM public.ontology_terms WHERE id=f.category_term_id;
   ELSIF f.kind='exact' THEN dim:=f.exact_value::text;
   ELSIF f.kind='range' THEN dim:=(CASE WHEN f.lower_inclusive THEN '[' ELSE '(' END)||coalesce(f.range_lower::text,'')||','||coalesce(f.range_upper::text,'')||(CASE WHEN f.upper_inclusive THEN ']' ELSE ')' END);
   ELSE dim:=NULL; END IF;
   CASE item.key WHEN 'bedrooms' THEN l.bedrooms:=dim; WHEN 'bathrooms' THEN l.bathrooms:=dim; WHEN 'parking' THEN l.parking:=dim; WHEN 'year_built' THEN l.year_built_range:=dim; WHEN 'distance_to_paved_road' THEN l.distance_to_paved_road_range:=dim; END CASE;
   changed:=true;
  END IF;
 END LOOP;
 IF p_domains ? 'measurements' THEN PERFORM twuanis_canonical_private.s3_keys(p_domains->'measurements',ARRAY['property_area','construction_area']); END IF;
 FOR item IN SELECT key,value FROM jsonb_each(coalesce(p_domains->'measurements','{}')) ORDER BY key LOOP
  dim:=item.key;v:=item.value;ids:='{}';ruleid:=NULL;band:=NULL;
  IF v='{"kind":"clear"}'::jsonb THEN
   IF p_actor_kind<>'owner' AND NOT p_administrative_clear THEN RAISE EXCEPTION 'measurement clear requires customer authority' USING ERRCODE='42501'; END IF;
   amount:=CASE dim WHEN 'property_area' THEN l.property_area ELSE l.construction_area END;
   IF amount IS NOT NULL OR EXISTS(SELECT 1 FROM public.listing_membership_origins WHERE listing_id=p_listing AND origin_domain=dim) THEN
    IF dim='property_area' THEN l.property_area:=NULL; ELSE l.construction_area:=NULL; END IF;
    PERFORM twuanis_canonical_private.s3_origins(p_listing,dim,'{}'::bigint[],NULL);
    changed:=true;
   END IF;
   CONTINUE;
  END IF;
  PERFORM twuanis_canonical_private.s3_keys(v,ARRAY['value','rule_set'],ARRAY['value']);
  amount:=twuanis_canonical_private.s3_decimal(v->'value');
  IF amount<=0 THEN RAISE EXCEPTION 'positive exact measurement required' USING ERRCODE='23514'; END IF;
  IF v ? 'rule_set' THEN
   ruleset:=(v->>'rule_set')::uuid;
   PERFORM s.id FROM public.listing_classification_rule_sets s JOIN twuanis_canonical_private.classification_seals z ON z.rule_set_id=s.id WHERE s.id=ruleset AND s.domain=dim FOR SHARE OF s;
   IF NOT FOUND THEN RAISE EXCEPTION 'sealed typed classification required' USING ERRCODE='55000'; END IF;
   SELECT r.id,r.ontology_term_id INTO STRICT ruleid,band FROM public.listing_classification_rules r WHERE r.rule_set_id=ruleset AND r.bounds @> amount;ids:=ARRAY[band];
  END IF;
  IF amount IS DISTINCT FROM (CASE dim WHEN 'property_area' THEN l.property_area ELSE l.construction_area END)
   OR (SELECT array_agg(DISTINCT classification_rule_id) FILTER(WHERE classification_rule_id IS NOT NULL) FROM public.listing_membership_origins WHERE listing_id=p_listing AND origin_domain=dim) IS DISTINCT FROM (CASE WHEN ruleid IS NULL THEN NULL ELSE ARRAY[ruleid] END) THEN
   IF dim='property_area' THEN l.property_area:=amount; ELSE l.construction_area:=amount; END IF;
   PERFORM twuanis_canonical_private.s3_origins(p_listing,dim,ids,ruleid);changed:=true;
  END IF;
 END LOOP;
 IF p_domains ? 'money' THEN
  v:=p_domains->'money';PERFORM twuanis_canonical_private.s3_keys(v,ARRAY['amount','currency','reason'],ARRAY['amount','currency']);
  amount:=twuanis_canonical_private.s3_decimal(v->'amount');newcurrency:=v->>'currency';
  IF amount<=0 OR newcurrency IS NULL OR newcurrency NOT IN ('CRC','USD') THEN RAISE EXCEPTION 'positive original monetary pair required' USING ERRCODE='23514'; END IF;
  oldamount:=CASE l.transaction_type WHEN 'sale' THEN l.current_price ELSE l.monthly_price END;
  IF (oldamount,l.currency) IS DISTINCT FROM (amount,newcurrency) THEN
   moneychanged:=true;changed:=true;eventkind:=CASE WHEN oldamount IS NULL THEN 'initial_observation' ELSE 'change' END;
   IF l.transaction_type='sale' THEN l.current_price:=amount;ELSE l.monthly_price:=amount;END IF;
   l.currency:=newcurrency;
  END IF;
 END IF;
 IF p_domains ? 'lifecycle' THEN
  v:=p_domains->'lifecycle';PERFORM twuanis_canonical_private.s3_keys(v,ARRAY['event','duration_seconds','reason'],ARRAY['event']);ev:=v->>'event';nextstate:=NULL;
  CASE ev
   WHEN 'publish' THEN IF l.listing_status='draft' THEN nextstate:='active';END IF;
   WHEN 'renew' THEN IF l.listing_status IN ('active','expired') THEN nextstate:='active';END IF;
   WHEN 'unpublish' THEN IF l.listing_status='active' THEN nextstate:='draft';END IF;
   WHEN 'expire' THEN IF l.listing_status='active' THEN nextstate:='expired';END IF;
   WHEN 'archive' THEN IF l.listing_status IN ('draft','active','expired') THEN nextstate:='archived';END IF;
   WHEN 'restore' THEN IF l.listing_status IN ('archived','deleted') THEN nextstate:='draft';END IF;
   WHEN 'delete' THEN IF l.listing_status IN ('draft','active','expired','archived') THEN nextstate:='deleted';END IF;
   ELSE NULL;
  END CASE;
  IF nextstate IS NULL THEN RAISE EXCEPTION 'invalid lifecycle transition' USING ERRCODE='22023'; END IF;
  observed:=clock_timestamp();
  IF nextstate='active' THEN
   amount:=twuanis_canonical_private.s3_decimal(v->'duration_seconds');
   IF amount<=0 OR amount<>trunc(amount) OR amount>315576000 THEN RAISE EXCEPTION 'bounded trusted duration required' USING ERRCODE='22023'; END IF;
   IF coalesce(CASE l.transaction_type WHEN 'sale' THEN l.current_price ELSE l.monthly_price END,0)<=0 OR l.currency NOT IN ('CRC','USD') THEN RAISE EXCEPTION 'publication requires monetary evidence' USING ERRCODE='23514'; END IF;
   IF own IS NOT NULL THEN
    SELECT a.allowance INTO allowance FROM twuanis_canonical_private.publisher_allowance(pub,own)a;
    used:=twuanis_canonical_private.publisher_consumption(pub,own);
    IF allowance IS NOT NULL AND ((l.listing_status='active' AND used>allowance) OR (l.listing_status<>'active' AND used>=allowance)) THEN RAISE EXCEPTION 'publication capacity exceeded' USING ERRCODE='23514'; END IF;
   END IF;
   IF ev='renew' AND l.publication_expires_at IS NULL THEN RAISE EXCEPTION 'renewal requires established deadline' USING ERRCODE='55000'; END IF;
   deadline:=greatest(observed,CASE WHEN ev='renew' AND l.listing_status='active' THEN l.publication_expires_at ELSE observed END)+amount*interval '1 second';
   l.publication_expires_at:=deadline;
  ELSIF v ? 'duration_seconds' THEN RAISE EXCEPTION 'duration only for publication/renewal' USING ERRCODE='22023'; END IF;
  CASE ev WHEN 'publish' THEN l.published_at:=observed; WHEN 'renew' THEN l.renewed_at:=observed;
   WHEN 'expire' THEN l.expired_at:=observed; WHEN 'archive' THEN l.archived_at:=observed; WHEN 'delete' THEN l.deleted_at:=observed; ELSE NULL; END CASE;
  l.listing_status:=nextstate;lifechanged:=true;changed:=true;
 END IF;
 IF p_source IS NOT NULL THEN
  l.first_seen:=least(l.first_seen,sourcetime);l.last_seen:=greatest(l.last_seen,sourcetime);l.last_scraped:=clock_timestamp();l.times_scraped:=coalesce(l.times_scraped,0)+1;changed:=true;
 END IF;
 IF p_extra_content IS NOT NULL THEN
  PERFORM twuanis_canonical_private.s3_keys(p_extra_content,ARRAY['title','description','whatsapp']);
  l.title:=CASE WHEN p_extra_content?'title' THEN p_extra_content->>'title' ELSE l.title END;l.description:=CASE WHEN p_extra_content?'description' THEN p_extra_content->>'description' ELSE l.description END;l.whatsapp:=CASE WHEN p_extra_content?'whatsapp' THEN p_extra_content->>'whatsapp' ELSE l.whatsapp END;
 END IF;
 IF l.listing_status='active' THEN
  admission_intent:=jsonb_build_object('listing',p_listing,'expectedRevision',p_expected::text,'kind',p_actor_kind,'actor',p_actor_identity,'domains',p_domains,'source',p_source,'clear',p_administrative_clear,'content',p_extra_content,'before',jsonb_build_object('title',before_l.title,'description',before_l.description,'whatsapp',before_l.whatsapp,'images',to_jsonb(before_l)->'images'));
  result:=twuanis_canonical_private.decide_listing_admission(to_jsonb(l)||jsonb_build_object('__intent',admission_intent),p_request,p_actor_identity,false);
  IF result->>'admission' <> 'ALLOW' THEN
   RAISE EXCEPTION USING ERRCODE='PDP01', MESSAGE='canonical duplicate admission held',DETAIL=(jsonb_build_object('proposed',twuanis_canonical_private.duplicate_snapshot(to_jsonb(l))||jsonb_build_object('__intent',admission_intent,'__command',jsonb_build_object('kind',p_actor_kind,'actor',p_actor_identity,'request',p_request,'domains',p_domains,'source',p_source,'clear',p_administrative_clear,'content',p_extra_content,'before',jsonb_build_object('title',before_l.title,'description',before_l.description,'whatsapp',before_l.whatsapp,'images',to_jsonb(before_l)->'images'))),'decision',result))::text;
  END IF;
 END IF;
 finalrev:=oldrev+CASE WHEN changed THEN 1 ELSE 0 END;
 INSERT INTO public.canonical_operation_receipts(id,authority_kind,authority_identity,operation_type,request_id,payload_fingerprint,outcome,listing_id,result_revision)
 VALUES(rid,p_actor_kind,p_actor_identity,op,p_request,fingerprint,CASE WHEN changed THEN 'succeeded' ELSE 'noop' END,p_listing,finalrev);
 IF p_source IS NOT NULL THEN
  INSERT INTO public.listing_source_observations(id,source_name,source_listing_id,source_observation_id,listing_id,source_observed_at,outcome,payload_fingerprint,result_revision)
  VALUES(sourceid,l.source_name,l.source_listing_id,p_source->>'observation_id',p_listing,sourcetime,'accepted',sourcefp,finalrev);
 END IF;
 IF moneychanged THEN
  INSERT INTO public.listing_monetary_events(listing_id,operation_id,listing_revision,transaction_type,event_kind,old_amount,old_currency,new_amount,new_currency,actor_kind,actor_identity,reason,source_observation_id,source_observed_at)
  VALUES(p_listing,rid,finalrev,l.transaction_type,eventkind,oldamount,CASE WHEN oldamount IS NULL THEN NULL ELSE before_l.currency END,CASE l.transaction_type WHEN 'sale' THEN l.current_price ELSE l.monthly_price END,l.currency,p_actor_kind,p_actor_identity,p_domains->'money'->>'reason',CASE WHEN p_source IS NOT NULL THEN sourceid END,sourcetime);
 END IF;
 IF lifechanged THEN
  INSERT INTO public.listing_lifecycle_events(listing_id,operation_id,listing_revision,event_type,previous_state,resulting_state,actor_kind,actor_identity,reason,publication_expires_at)
  VALUES(p_listing,rid,finalrev,ev,before_l.listing_status,l.listing_status,p_actor_kind,p_actor_identity,p_domains->'lifecycle'->>'reason',l.publication_expires_at);
 END IF;
 IF changed THEN
  UPDATE public.listings SET province=l.province,canton=l.canton,district=l.district,
   province_normalized=l.province_normalized,canton_normalized=l.canton_normalized,district_normalized=l.district_normalized,
   property_type=l.property_type,utility=l.utility,environment=l.environment,terrain=l.terrain,accessibility=l.accessibility,legal_status=l.legal_status,
   bedrooms=l.bedrooms,bathrooms=l.bathrooms,parking=l.parking,year_built_range=l.year_built_range,distance_to_paved_road_range=l.distance_to_paved_road_range,
   property_area=l.property_area,construction_area=l.construction_area,current_price=l.current_price,monthly_price=l.monthly_price,currency=l.currency,
   listing_status=l.listing_status,publication_expires_at=l.publication_expires_at,published_at=l.published_at,renewed_at=l.renewed_at,expired_at=l.expired_at,archived_at=l.archived_at,deleted_at=l.deleted_at,
   first_seen=l.first_seen,last_seen=l.last_seen,last_scraped=l.last_scraped,times_scraped=l.times_scraped,canonical_revision=finalrev,updated_at=clock_timestamp()
  WHERE id=p_listing;
 END IF;
 IF l.listing_status='active' AND before_l.listing_status<>'active' AND before_l.published_at IS NULL THEN PERFORM twuanis_canonical_private.record_listing_admission_success(p_listing,p_request,rid); END IF;
 RETURN jsonb_build_object('outcome',CASE WHEN changed THEN 'succeeded' ELSE 'noop' END,'revision',finalrev::text,'receipt_id',rid::text,'replayed',false);
 EXCEPTION WHEN SQLSTATE 'PDP01' THEN
  GET STACKED DIAGNOSTICS group_name=PG_EXCEPTION_DETAIL;
  result:=twuanis_canonical_private.decide_listing_admission((group_name::jsonb)->'proposed',p_request,p_actor_identity,true);
  IF result->>'admission'='ALLOW' THEN RAISE EXCEPTION 'Admission evidence changed; retry original command' USING ERRCODE='40001'; END IF;
  RETURN result||jsonb_build_object('listing_id',p_listing,'revision',p_expected::text,'outcome','held');
 END;
END $$;


--
-- Name: s3_command(uuid, bigint, text, text, uuid, jsonb, jsonb); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.s3_command(p_listing uuid, p_expected bigint, p_actor_kind text, p_actor_identity text, p_request uuid, p_domains jsonb, p_source jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE sql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
 SELECT twuanis_canonical_private.s3_command_with_administrative_clear(p_listing,p_expected,p_actor_kind,p_actor_identity,p_request,p_domains,p_source,false);
$$;


--
-- Name: s3_command_with_administrative_clear(uuid, bigint, text, text, uuid, jsonb, jsonb, boolean); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.s3_command_with_administrative_clear(p_listing uuid, p_expected bigint, p_actor_kind text, p_actor_identity text, p_request uuid, p_domains jsonb, p_source jsonb, p_administrative_clear boolean) RETURNS jsonb
    LANGUAGE sql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$ SELECT twuanis_canonical_private.s3_admission_command(p_listing,p_expected,p_actor_kind,p_actor_identity,p_request,p_domains,p_source,p_administrative_clear,NULL); $$;


--
-- Name: s3_decimal(jsonb); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.s3_decimal(v jsonb) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
BEGIN
 IF jsonb_typeof(v) IS DISTINCT FROM 'string' OR length(v#>>'{}')>256 OR (v#>>'{}') !~ '^[0-9]+([.][0-9]+)?$' THEN
  RAISE EXCEPTION 'bounded exact decimal string required' USING ERRCODE='22023';
 END IF;
 RETURN (v#>>'{}')::numeric;
END $_$;


--
-- Name: s3_geography(jsonb); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.s3_geography(v jsonb) RETURNS bigint[]
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE p public.ontology_terms%ROWTYPE; c public.ontology_terms%ROWTYPE; d public.ontology_terms%ROWTYPE; ids bigint[]; n bigint; t record;
BEGIN
 PERFORM twuanis_canonical_private.s3_keys(v,ARRAY['province','canton','district'],ARRAY['province','canton']);
 IF jsonb_typeof(v->'province') IS DISTINCT FROM 'string' OR (v->>'province') !~ '^[0-9]$'
 OR jsonb_typeof(v->'canton') IS DISTINCT FROM 'string' OR (v->>'canton') !~ '^[0-9]{3}$'
 OR (v ? 'district' AND v->'district'<>'null'::jsonb AND (jsonb_typeof(v->'district')<>'string' OR (v->>'district') !~ '^[0-9]{5}$')) THEN
  RAISE EXCEPTION 'Province and Canton required; optional District must be DTA code' USING ERRCODE='22023';
 END IF;
 SELECT * INTO STRICT p FROM public.ontology_terms WHERE official_code=v->>'province' AND term_type IN ('province','canton','district');
 SELECT * INTO STRICT c FROM public.ontology_terms WHERE official_code=v->>'canton' AND term_type IN ('province','canton','district');
 IF v->>'district' IS NOT NULL THEN SELECT * INTO STRICT d FROM public.ontology_terms WHERE official_code=v->>'district' AND term_type IN ('province','canton','district'); END IF;
 ids:=array_remove(ARRAY[p.id,c.id,d.id],NULL);
 FOR n IN SELECT x FROM unnest(ids)x ORDER BY x LOOP
  SELECT * INTO STRICT t FROM public.ontology_terms WHERE id=n FOR SHARE;
  IF n=p.id THEN p:=t; ELSIF n=c.id THEN c:=t; ELSE d:=t; END IF;
 END LOOP;
 IF p.term_type<>'province' OR p.level IS DISTINCT FROM 1 OR p.official_code IS DISTINCT FROM v->>'province'
 OR c.term_type<>'canton' OR c.level IS DISTINCT FROM 2 OR c.official_code IS DISTINCT FROM v->>'canton'
 OR p.parent_id IS DISTINCT FROM 9 OR c.parent_id IS DISTINCT FROM p.id OR left(c.official_code,1)<>p.official_code
 OR (d.id IS NOT NULL AND (d.term_type<>'district' OR d.level IS DISTINCT FROM 3 OR d.official_code IS DISTINCT FROM v->>'district' OR d.parent_id IS DISTINCT FROM c.id OR left(d.official_code,3)<>c.official_code))
 OR p.term_name IS NULL OR c.term_name IS NULL OR (d.id IS NOT NULL AND d.term_name IS NULL) THEN
  RAISE EXCEPTION 'canonical geography disagreement' USING ERRCODE='23514';
 END IF;
 RETURN ids;
END $_$;


--
-- Name: s3_keys(jsonb, text[], text[]); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.s3_keys(v jsonb, allowed text[], required text[] DEFAULT '{}'::text[]) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
 IF v IS NULL OR jsonb_typeof(v)<>'object' OR octet_length(v::text)>32768 THEN
  RAISE EXCEPTION 'bounded object required' USING ERRCODE='22023';
 END IF;
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(v) k WHERE NOT k=ANY(allowed)) OR NOT v ?& required THEN
  RAISE EXCEPTION 'unknown or missing domain field' USING ERRCODE='22023';
 END IF;
END $$;


--
-- Name: s3_origins(uuid, text, bigint[], uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.s3_origins(lid uuid, dim text, ids bigint[], rule uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE expanded bigint[]:=ids; x record; parent record; oldids bigint[]; edge_count integer:=0;
BEGIN
 expanded:=twuanis_canonical_private.canonical_origin_ids(dim,ids);
 SELECT array_agg(ontology_term_id) INTO oldids FROM public.listing_membership_origins WHERE listing_id=lid AND origin_domain=dim;
 DELETE FROM public.listing_membership_origins WHERE listing_id=lid AND origin_domain=dim;
 INSERT INTO public.listing_membership_origins(listing_id,ontology_term_id,origin_domain,classification_rule_id)
 SELECT lid,t,dim,CASE WHEN t=ANY(ids) THEN rule ELSE NULL END FROM (SELECT DISTINCT unnest(expanded)t)s;
 DELETE FROM public.listings_ontology_terms lot WHERE lot.listing_id=lid AND lot.ontology_term_id=ANY(oldids)
 AND NOT EXISTS(SELECT 1 FROM public.listing_membership_origins o WHERE o.listing_id=lid AND o.ontology_term_id=lot.ontology_term_id);
 INSERT INTO public.listings_ontology_terms(listing_id,ontology_term_id) SELECT lid,t FROM (SELECT DISTINCT unnest(expanded)t)s ON CONFLICT DO NOTHING;
END $$;


--
-- Name: s3_seal_classification(uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.s3_seal_classification(p_set uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE n integer;
BEGIN
 PERFORM id FROM public.listing_classification_rule_sets WHERE id=p_set FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'classification set missing' USING ERRCODE='P0002'; END IF;
 SELECT count(*) INTO n FROM (SELECT id FROM public.listing_classification_rules WHERE rule_set_id=p_set LIMIT 65)s;
 IF n NOT BETWEEN 1 AND 64 THEN RAISE EXCEPTION 'classification set must have 1..64 rules' USING ERRCODE='54000'; END IF;
 INSERT INTO twuanis_canonical_private.classification_seals VALUES(p_set) ON CONFLICT DO NOTHING;
END $$;


--
-- Name: s3_sealed_rule_guard(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.s3_sealed_rule_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
 PERFORM id FROM public.listing_classification_rule_sets WHERE id=NEW.rule_set_id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM twuanis_canonical_private.classification_seals WHERE rule_set_id=NEW.rule_set_id) THEN
  RAISE EXCEPTION 'classification version sealed' USING ERRCODE='55000';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: s3_term_ids(jsonb); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.s3_term_ids(v jsonb) RETURNS bigint[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE e jsonb; a bigint[]:='{}'; n bigint;
BEGIN
 IF jsonb_typeof(v) IS DISTINCT FROM 'array' OR jsonb_array_length(v)>32 THEN RAISE EXCEPTION 'bounded identity set required' USING ERRCODE='22023'; END IF;
 FOR e IN SELECT value FROM jsonb_array_elements(v) LOOP
  IF jsonb_typeof(e)<>'string' OR length(e#>>'{}')>19 OR (e#>>'{}') !~ '^[1-9][0-9]*$' THEN RAISE EXCEPTION 'decimal string term identity required' USING ERRCODE='22023'; END IF;
  n:=(e#>>'{}')::bigint; a:=array_append(a,n);
 END LOOP;
 RETURN ARRAY(SELECT DISTINCT x FROM unnest(a)x ORDER BY x);
END $_$;


--
-- Name: s4_create_core(uuid, uuid, jsonb, jsonb); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.s4_create_core(p_owner uuid, p_request uuid, p_input jsonb, p_source jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
 l public.listings%ROWTYPE; p_listing uuid:=gen_random_uuid(); pub uuid; actor text; kind text; op text; rid uuid:=gen_random_uuid(); obsid uuid:=gen_random_uuid();
 receipt public.canonical_operation_receipts%ROWTYPE; existing public.listings%ROWTYPE; previous_obs public.listing_source_observations%ROWTYPE;
 p_domains jsonb; body jsonb; content jsonb; fingerprint text; sourcefp text; sourcectx jsonb; observed timestamptz; geo bigint[];
 item record; termrow record; v jsonb; dim text; ids bigint[]; oldids bigint[]; labels text[]; tags text[];
 f public.listing_fact_evidence%ROWTYPE; oldf jsonb; ruleid uuid; ruleset uuid; band bigint; amount numeric; oldamount numeric; newcurrency text;
 changed boolean:=false; moneychanged boolean:=false; eventkind text; c text;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'READ COMMITTED required' USING ERRCODE='0A000'; END IF;
 IF octet_length(p_input::text)>65536 OR octet_length(p_source::text)>8192 THEN RAISE EXCEPTION 'creation payload bound' USING ERRCODE='54000'; END IF;
 IF p_request IS NULL THEN RAISE EXCEPTION 'request identity required' USING ERRCODE='22023'; END IF;
 PERFORM twuanis_canonical_private.s3_keys(p_input,ARRAY['transaction','geography','semantics','facts','measurements','money','content'],ARRAY['transaction','geography','semantics']);
 IF jsonb_typeof(p_input->'transaction') IS DISTINCT FROM 'string' OR p_input->>'transaction' NOT IN ('sale','rent') THEN RAISE EXCEPTION 'explicit sale/rent required' USING ERRCODE='22023'; END IF;
 p_domains:=twuanis_canonical_private.s4_domains(p_input-ARRAY['transaction','content'],CASE WHEN p_owner IS NOT NULL THEN 'owner' WHEN p_source IS NOT NULL THEN 'source' ELSE 'manual' END);
 IF NOT (p_domains->'semantics') ? 'property_type' OR cardinality(twuanis_canonical_private.s3_term_ids(p_domains->'semantics'->'property_type'))<>1 THEN RAISE EXCEPTION 'exactly one property type required' USING ERRCODE='23514'; END IF;
 content:=coalesce(p_input->'content','{}');PERFORM twuanis_canonical_private.s3_keys(content,ARRAY['title','description','whatsapp']);
 FOREACH c IN ARRAY ARRAY['title','description','whatsapp'] LOOP
  IF content ? c AND (jsonb_typeof(content->c) IS DISTINCT FROM 'string' OR length(content->>c)>CASE c WHEN 'title' THEN 512 WHEN 'description' THEN 16000 ELSE 256 END) THEN RAISE EXCEPTION 'bounded text content required' USING ERRCODE='22023'; END IF;
 END LOOP;
 IF p_owner IS NOT NULL THEN
  IF p_source IS NOT NULL THEN RAISE EXCEPTION 'customer cannot establish source authority' USING ERRCODE='42501'; END IF;
  kind:='owner';actor:=p_owner::text;op:='create_customer';pub:=twuanis_canonical_private.ensure_publisher_account(p_owner);
 ELSE
  kind:='trusted';actor:='service_role';op:='create_trusted';PERFORM twuanis_canonical_private.lock_capacity_policy(false);
 END IF;
 IF p_source IS NOT NULL THEN
  PERFORM twuanis_canonical_private.s3_keys(p_source,ARRAY['source_name','source_listing_id','observation_id','observed_at','source_type'],ARRAY['source_name','source_listing_id','observation_id','observed_at','source_type']);
  FOREACH c IN ARRAY ARRAY['source_name','source_listing_id','observation_id'] LOOP
   IF jsonb_typeof(p_source->c) IS DISTINCT FROM 'string' OR length(p_source->>c) NOT BETWEEN 1 AND (CASE WHEN c='source_name' THEN 128 ELSE 256 END) OR (p_source->>c) COLLATE "C" !~ '[^[:space:]]' THEN RAISE EXCEPTION 'opaque source identity invalid' USING ERRCODE='22023'; END IF;
  END LOOP;
  IF p_source->>'source_type' IS NULL OR p_source->>'source_type' NOT IN ('realtor','bank_remate','developer','brokerage','government','owner_direct','unknown') THEN RAISE EXCEPTION 'trusted source type required' USING ERRCODE='22023'; END IF;
  observed:=(p_source->>'observed_at')::timestamptz;
  IF observed IS NULL OR NOT isfinite(observed) THEN RAISE EXCEPTION 'observation time required' USING ERRCODE='22023'; END IF;
  p_source:=jsonb_set(p_source,'{observed_at}',to_jsonb(to_char(observed AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')));
  PERFORM pg_advisory_xact_lock(3103,hashtext(jsonb_build_array(p_source->>'source_name',p_source->>'source_listing_id')::text));
 END IF;
 body:=jsonb_build_object('transaction',p_input->'transaction','domains',p_domains,'content',content,'source',p_source);
 fingerprint:=encode(sha256(convert_to(body::text,'UTF8')),'hex');
 PERFORM pg_advisory_xact_lock(3104,hashtext(jsonb_build_array(kind,actor,op,p_request)::text));
 SELECT * INTO receipt FROM public.canonical_operation_receipts WHERE authority_kind=kind AND authority_identity=actor AND operation_type=op AND request_id=p_request;
 IF FOUND THEN
  IF receipt.payload_fingerprint<>fingerprint THEN RAISE EXCEPTION 'creation idempotency conflict' USING ERRCODE='22023'; END IF;
  RETURN jsonb_build_object('listing_id',receipt.listing_id::text,'revision',receipt.result_revision::text,'receipt_id',receipt.id::text,'replayed',true);
 END IF;
 IF p_source IS NOT NULL THEN
  SELECT * INTO existing FROM public.listings WHERE source_name=p_source->>'source_name' AND source_listing_id=p_source->>'source_listing_id';
  IF FOUND THEN
   IF existing.canonical_domain_version IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'existing source requires reconciliation' USING ERRCODE='55000'; END IF;
   SELECT * INTO previous_obs FROM public.listing_source_observations WHERE source_name=existing.source_name AND source_listing_id=existing.source_listing_id AND source_observation_id=p_source->>'observation_id';
   IF NOT FOUND THEN RAISE EXCEPTION 'existing source: use controlled source mutation' USING ERRCODE='55000'; END IF;
   SELECT r.* INTO STRICT receipt FROM public.canonical_operation_receipts r
    JOIN public.listing_lifecycle_events e ON e.operation_id=r.id AND e.listing_id=r.listing_id AND e.event_type='create'
    WHERE r.listing_id=existing.id AND r.operation_type='create_trusted' AND r.authority_kind='trusted' AND r.authority_identity=actor;
   IF receipt.payload_fingerprint<>fingerprint THEN RAISE EXCEPTION 'source creation identity/payload conflict' USING ERRCODE='22023'; END IF;
   -- Bind this new operation identity even when source identity already proves
   -- replay. Otherwise it could later be reused for a materially different create.
   INSERT INTO public.canonical_operation_receipts(id,authority_kind,authority_identity,operation_type,request_id,payload_fingerprint,outcome,listing_id,result_revision)
   VALUES(rid,kind,actor,op,p_request,fingerprint,'succeeded',existing.id,receipt.result_revision);
   RETURN jsonb_build_object('listing_id',existing.id::text,'revision',receipt.result_revision::text,'receipt_id',rid::text,'replayed',true);
  END IF;
 END IF;
 -- Explicit draft and transaction. CRC without any amount is a storage placeholder
 -- required by the existing NOT NULL column, never a monetary observation/history.
 INSERT INTO public.listings(id,owner_id,publisher_account_id,transaction_type,listing_status,currency,listing_origin,listing_source_type,
  canonical_revision,canonical_domain_version,title,description,whatsapp,source_name,source_listing_id,current_price,monthly_price)
 VALUES(p_listing,p_owner,pub,p_input->>'transaction','draft',coalesce(p_domains->'money'->>'currency','CRC'),
  CASE WHEN p_owner IS NOT NULL THEN 'customer' WHEN p_source IS NOT NULL THEN 'imported' ELSE 'system' END,
  CASE WHEN p_owner IS NOT NULL THEN 'customer' WHEN p_source IS NOT NULL THEN p_source->>'source_type' ELSE 'unknown' END,
  0,NULL,content->>'title',content->>'description',content->>'whatsapp',p_source->>'source_name',p_source->>'source_listing_id',NULL,NULL)
 RETURNING * INTO l;
 geo:=twuanis_canonical_private.s3_geography(p_domains->'geography');
 PERFORM twuanis_canonical_private.s3_origins(p_listing,'geography',geo);
 SELECT term_name INTO l.province FROM public.ontology_terms WHERE id=geo[1];
 SELECT term_name INTO l.canton FROM public.ontology_terms WHERE id=geo[2];
 SELECT term_name INTO l.district FROM public.ontology_terms WHERE id=geo[3];
 l.province_normalized:=twuanis_private.normalize_geographic_projection(l.province);
 l.canton_normalized:=twuanis_private.normalize_geographic_projection(l.canton);
 l.district_normalized:=twuanis_private.normalize_geographic_projection(l.district);
 -- Creation-specific population below mirrors the closed S3 domain validation,
 -- using its pure validators/origin helper and S1 constraints. It does not invoke
 -- s3_command on a prematurely eligible row or rewrite that closed command.
 FOR item IN SELECT key,value FROM jsonb_each(coalesce(p_domains->'semantics','{}')) ORDER BY key LOOP
  dim:=item.key;ids:=twuanis_canonical_private.s3_term_ids(item.value);
  IF (dim='property_type' AND cardinality(ids)<>1) OR (dim='legal_status' AND cardinality(ids)>1) THEN RAISE EXCEPTION 'semantic cardinality' USING ERRCODE='23514'; END IF;
  labels:='{}';
  FOR termrow IN SELECT * FROM public.ontology_terms WHERE id=ANY(ids) ORDER BY id FOR SHARE LOOP
   IF termrow.term_type IS DISTINCT FROM dim OR termrow.level IS DISTINCT FROM 1 OR termrow.term_name IS NULL THEN RAISE EXCEPTION 'semantic term type/level' USING ERRCODE='23514'; END IF;
   labels:=array_append(labels,termrow.term_name);
  END LOOP;
  IF cardinality(labels)<>cardinality(ids) THEN RAISE EXCEPTION 'unknown semantic term' USING ERRCODE='23514'; END IF;
  IF dim='accessibility' THEN
   PERFORM term_id FROM twuanis_canonical_private.accessibility_identity WHERE term_id=ANY(ids) ORDER BY term_id FOR SHARE;
   SELECT array_agg(code) INTO tags FROM twuanis_canonical_private.accessibility_identity WHERE term_id=ANY(ids);
   IF coalesce(cardinality(tags),0)<>cardinality(ids) OR ('boat'=ANY(tags) AND cardinality(tags)>1) OR ('4x4'=ANY(tags) AND tags && ARRAY['2wd','paved']) THEN RAISE EXCEPTION 'accessibility set incompatible or unmapped' USING ERRCODE='23514'; END IF;
  END IF;
  SELECT coalesce(array_agg(ontology_term_id ORDER BY ontology_term_id),'{}') INTO oldids FROM public.listing_semantic_selections WHERE listing_id=p_listing AND dimension=dim;
  IF oldids IS DISTINCT FROM ids THEN
   DELETE FROM public.listing_semantic_selections WHERE listing_id=p_listing AND dimension=dim;
   INSERT INTO public.listing_semantic_selections(listing_id,dimension,ontology_term_id) SELECT p_listing,dim,x FROM unnest(ids)x;
   PERFORM twuanis_canonical_private.s3_origins(p_listing,dim,ids);
   CASE dim WHEN 'property_type' THEN l.property_type:=labels[1]; WHEN 'utility' THEN l.utility:=labels;
    WHEN 'terrain' THEN l.terrain:=labels; WHEN 'environment' THEN l.environment:=array_to_string(labels,'|');
    WHEN 'accessibility' THEN l.accessibility:=array_to_string(labels,'|'); WHEN 'legal_status' THEN l.legal_status:=labels[1]; END CASE;
   changed:=true;
  END IF;
 END LOOP;
 IF p_domains ? 'facts' THEN PERFORM twuanis_canonical_private.s3_keys(p_domains->'facts',ARRAY['bedrooms','bathrooms','parking','year_built','distance_to_paved_road']); END IF;
 FOR item IN SELECT key,value FROM jsonb_each(coalesce(p_domains->'facts','{}')) ORDER BY key LOOP
  dim:=item.key;v:=item.value;ids:='{}';ruleid:=NULL;ruleset:=NULL;band:=NULL;
  PERFORM twuanis_canonical_private.s3_keys(v,ARRAY['kind','value','term','lower','upper','lower_inclusive','upper_inclusive','source','reference','rule_set'],ARRAY['kind']);
  SELECT to_jsonb(e)-ARRAY['recorded_at','observed_at'] INTO oldf FROM public.listing_fact_evidence e WHERE listing_id=p_listing AND dimension=dim;
  IF v->>'kind'='clear' THEN
   IF v<>'{"kind":"clear"}'::jsonb THEN RAISE EXCEPTION 'clear has no value' USING ERRCODE='22023'; END IF;
   f:=NULL;
  ELSE
   IF v->>'kind' NOT IN ('exact','category','range') OR v->>'kind' IS NULL THEN RAISE EXCEPTION 'invalid fact kind' USING ERRCODE='22023'; END IF;
   f:=NULL;f.listing_id:=p_listing;f.dimension:=dim;f.kind:=v->>'kind';f.evidence_source:=v->>'source';f.evidence_reference:=v->>'reference';
   IF f.kind='exact' THEN
    IF v ?| ARRAY['term','lower','upper','lower_inclusive','upper_inclusive'] THEN RAISE EXCEPTION 'exact fact payload' USING ERRCODE='22023'; END IF;
    f.exact_value:=twuanis_canonical_private.s3_decimal(v->'value');
   ELSIF f.kind='category' THEN
    IF v ?| ARRAY['value','lower','upper','lower_inclusive','upper_inclusive','rule_set'] THEN RAISE EXCEPTION 'category payload' USING ERRCODE='22023'; END IF;
    ids:=twuanis_canonical_private.s3_term_ids(jsonb_build_array(v->'term'));f.category_term_id:=ids[1];
   ELSE
    IF v ?| ARRAY['value','term','rule_set'] OR NOT v ?& ARRAY['lower','upper','lower_inclusive','upper_inclusive'] OR jsonb_typeof(v->'lower_inclusive')<>'boolean' OR jsonb_typeof(v->'upper_inclusive')<>'boolean' THEN RAISE EXCEPTION 'explicit range required' USING ERRCODE='22023'; END IF;
    f.range_lower:=CASE WHEN v->'lower'='null'::jsonb THEN NULL ELSE twuanis_canonical_private.s3_decimal(v->'lower') END;
    f.range_upper:=CASE WHEN v->'upper'='null'::jsonb THEN NULL ELSE twuanis_canonical_private.s3_decimal(v->'upper') END;
    f.lower_inclusive:=(v->>'lower_inclusive')::boolean;f.upper_inclusive:=(v->>'upper_inclusive')::boolean;
   END IF;
  END IF;
  IF v ? 'rule_set' THEN
   ruleset:=(v->>'rule_set')::uuid;
   PERFORM s.id FROM public.listing_classification_rule_sets s JOIN twuanis_canonical_private.classification_seals z ON z.rule_set_id=s.id WHERE s.id=ruleset AND s.domain=dim FOR SHARE OF s;
   IF NOT FOUND THEN RAISE EXCEPTION 'sealed typed classification required' USING ERRCODE='55000'; END IF;
   SELECT r.id,r.ontology_term_id INTO STRICT ruleid,band FROM public.listing_classification_rules r WHERE r.rule_set_id=ruleset AND r.bounds @> f.exact_value;
   ids:=ARRAY[band];
  END IF;
  IF oldf IS DISTINCT FROM (CASE WHEN f.kind IS NULL THEN NULL ELSE to_jsonb(f)-ARRAY['recorded_at','observed_at'] END)
   OR (SELECT array_agg(DISTINCT classification_rule_id) FILTER(WHERE classification_rule_id IS NOT NULL) FROM public.listing_membership_origins WHERE listing_id=p_listing AND origin_domain=dim) IS DISTINCT FROM (CASE WHEN ruleid IS NULL THEN NULL ELSE ARRAY[ruleid] END) THEN
   DELETE FROM public.listing_fact_evidence WHERE listing_id=p_listing AND dimension=dim;
   IF f.kind IS NOT NULL THEN
    INSERT INTO public.listing_fact_evidence(listing_id,dimension,kind,exact_value,category_term_id,range_lower,range_upper,lower_inclusive,upper_inclusive,evidence_source,evidence_reference)
    VALUES(p_listing,dim,f.kind,f.exact_value,f.category_term_id,f.range_lower,f.range_upper,f.lower_inclusive,f.upper_inclusive,f.evidence_source,f.evidence_reference);
   END IF;
   PERFORM twuanis_canonical_private.s3_origins(p_listing,dim,ids,ruleid);
   IF f.kind='category' THEN SELECT term_name INTO dim FROM public.ontology_terms WHERE id=f.category_term_id;
   ELSIF f.kind='exact' THEN dim:=f.exact_value::text;
   ELSIF f.kind='range' THEN dim:=(CASE WHEN f.lower_inclusive THEN '[' ELSE '(' END)||coalesce(f.range_lower::text,'')||','||coalesce(f.range_upper::text,'')||(CASE WHEN f.upper_inclusive THEN ']' ELSE ')' END);
   ELSE dim:=NULL; END IF;
   CASE item.key WHEN 'bedrooms' THEN l.bedrooms:=dim; WHEN 'bathrooms' THEN l.bathrooms:=dim; WHEN 'parking' THEN l.parking:=dim; WHEN 'year_built' THEN l.year_built_range:=dim; WHEN 'distance_to_paved_road' THEN l.distance_to_paved_road_range:=dim; END CASE;
   changed:=true;
  END IF;
 END LOOP;
 IF p_domains ? 'measurements' THEN PERFORM twuanis_canonical_private.s3_keys(p_domains->'measurements',ARRAY['property_area','construction_area']); END IF;
 FOR item IN SELECT key,value FROM jsonb_each(coalesce(p_domains->'measurements','{}')) ORDER BY key LOOP
  dim:=item.key;v:=item.value;ids:='{}';ruleid:=NULL;band:=NULL;
  PERFORM twuanis_canonical_private.s3_keys(v,ARRAY['value','rule_set'],ARRAY['value']);
  amount:=twuanis_canonical_private.s3_decimal(v->'value');
  IF amount<=0 THEN RAISE EXCEPTION 'positive exact measurement required' USING ERRCODE='23514'; END IF;
  IF v ? 'rule_set' THEN
   ruleset:=(v->>'rule_set')::uuid;
   PERFORM s.id FROM public.listing_classification_rule_sets s JOIN twuanis_canonical_private.classification_seals z ON z.rule_set_id=s.id WHERE s.id=ruleset AND s.domain=dim FOR SHARE OF s;
   IF NOT FOUND THEN RAISE EXCEPTION 'sealed typed classification required' USING ERRCODE='55000'; END IF;
   SELECT r.id,r.ontology_term_id INTO STRICT ruleid,band FROM public.listing_classification_rules r WHERE r.rule_set_id=ruleset AND r.bounds @> amount;ids:=ARRAY[band];
  END IF;
  IF amount IS DISTINCT FROM (CASE dim WHEN 'property_area' THEN l.property_area ELSE l.construction_area END)
   OR (SELECT array_agg(DISTINCT classification_rule_id) FILTER(WHERE classification_rule_id IS NOT NULL) FROM public.listing_membership_origins WHERE listing_id=p_listing AND origin_domain=dim) IS DISTINCT FROM (CASE WHEN ruleid IS NULL THEN NULL ELSE ARRAY[ruleid] END) THEN
   IF dim='property_area' THEN l.property_area:=amount; ELSE l.construction_area:=amount; END IF;
   PERFORM twuanis_canonical_private.s3_origins(p_listing,dim,ids,ruleid);changed:=true;
  END IF;
 END LOOP;
 IF p_domains ? 'money' THEN
  v:=p_domains->'money';PERFORM twuanis_canonical_private.s3_keys(v,ARRAY['amount','currency','reason'],ARRAY['amount','currency']);
  amount:=twuanis_canonical_private.s3_decimal(v->'amount');newcurrency:=v->>'currency';
  IF amount<=0 OR newcurrency IS NULL OR newcurrency NOT IN ('CRC','USD') THEN RAISE EXCEPTION 'positive original monetary pair required' USING ERRCODE='23514'; END IF;
  oldamount:=CASE l.transaction_type WHEN 'sale' THEN l.current_price ELSE l.monthly_price END;
  IF (oldamount,l.currency) IS DISTINCT FROM (amount,newcurrency) THEN
   moneychanged:=true;changed:=true;eventkind:=CASE WHEN oldamount IS NULL THEN 'initial_observation' ELSE 'change' END;
   IF l.transaction_type='sale' THEN l.current_price:=amount;ELSE l.monthly_price:=amount;END IF;
   l.currency:=newcurrency;
  END IF;
 END IF;
 INSERT INTO public.canonical_operation_receipts(id,authority_kind,authority_identity,operation_type,request_id,payload_fingerprint,outcome,listing_id,result_revision)
 VALUES(rid,kind,actor,op,p_request,fingerprint,'succeeded',p_listing,1);
 IF p_source IS NOT NULL THEN
  sourcectx:=(p_source-'source_type')||jsonb_build_object('transaction',l.transaction_type,'geography',p_domains->'geography');
  sourcefp:=encode(sha256(convert_to(jsonb_build_object('listing',p_listing,'source',sourcectx,'domains',p_domains)::text,'UTF8')),'hex');
  INSERT INTO public.listing_source_observations(id,source_name,source_listing_id,source_observation_id,listing_id,source_observed_at,outcome,payload_fingerprint,result_revision)
  VALUES(obsid,l.source_name,l.source_listing_id,p_source->>'observation_id',p_listing,observed,'accepted',sourcefp,1);
  l.first_seen:=observed;l.last_seen:=observed;l.last_scraped:=clock_timestamp();l.times_scraped:=1;
 END IF;
 INSERT INTO public.listing_lifecycle_events(listing_id,operation_id,listing_revision,event_type,previous_state,resulting_state,actor_kind,actor_identity)
 VALUES(p_listing,rid,1,'create',NULL,'draft',kind,actor);
 IF moneychanged THEN
  INSERT INTO public.listing_monetary_events(listing_id,operation_id,listing_revision,transaction_type,event_kind,old_amount,old_currency,new_amount,new_currency,actor_kind,actor_identity,reason,source_observation_id,source_observed_at)
  VALUES(p_listing,rid,1,l.transaction_type,'initial_observation',NULL,NULL,CASE l.transaction_type WHEN 'sale' THEN l.current_price ELSE l.monthly_price END,l.currency,kind,actor,p_domains->'money'->>'reason',CASE WHEN p_source IS NOT NULL THEN obsid END,observed);
 END IF;
 -- Eligibility and coherent projections are established in the final row write,
 -- after required semantic/fact/member/history/receipt work, all in one transaction.
 UPDATE public.listings SET province=l.province,canton=l.canton,district=l.district,
  province_normalized=l.province_normalized,canton_normalized=l.canton_normalized,district_normalized=l.district_normalized,
  property_type=l.property_type,utility=l.utility,environment=l.environment,terrain=l.terrain,accessibility=l.accessibility,legal_status=l.legal_status,
  bedrooms=l.bedrooms,bathrooms=l.bathrooms,parking=l.parking,year_built_range=l.year_built_range,distance_to_paved_road_range=l.distance_to_paved_road_range,
  property_area=l.property_area,construction_area=l.construction_area,current_price=l.current_price,monthly_price=l.monthly_price,currency=l.currency,
  first_seen=l.first_seen,last_seen=l.last_seen,last_scraped=l.last_scraped,times_scraped=coalesce(l.times_scraped,0),
  canonical_revision=1,canonical_domain_version=1,updated_at=clock_timestamp() WHERE id=p_listing;
 RETURN jsonb_build_object('listing_id',p_listing::text,'revision','1','receipt_id',rid::text,'replayed',false);
END $$;


--
-- Name: s4_domains(jsonb, text); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.s4_domains(d jsonb, evidence_kind text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE x record; g text; k text; ids bigint[]; n integer:=0;
BEGIN
 IF octet_length(d::text)>65536 THEN RAISE EXCEPTION 'domain payload bound' USING ERRCODE='54000'; END IF;
 PERFORM twuanis_canonical_private.s3_keys(d,ARRAY['geography','semantics','facts','measurements','money','lifecycle']);
 IF evidence_kind NOT IN ('owner','source','manual') OR evidence_kind IS NULL THEN RAISE EXCEPTION 'internal evidence authority required' USING ERRCODE='22023'; END IF;
 IF d ? 'semantics' THEN
  PERFORM twuanis_canonical_private.s3_keys(d->'semantics',ARRAY['property_type','utility','environment','terrain','accessibility','legal_status']);
  FOR x IN SELECT key,value FROM jsonb_each(d->'semantics') LOOP
   ids:=twuanis_canonical_private.s3_term_ids(x.value);n:=n+cardinality(ids);
   d:=jsonb_set(d,ARRAY['semantics',x.key],coalesce((SELECT jsonb_agg(v::text ORDER BY v) FROM unnest(ids)v),'[]'));
  END LOOP;
  IF n>64 THEN RAISE EXCEPTION 'semantic command bound' USING ERRCODE='54000'; END IF;
 END IF;
 IF d ? 'facts' THEN
  PERFORM twuanis_canonical_private.s3_keys(d->'facts',ARRAY['bedrooms','bathrooms','parking','year_built','distance_to_paved_road']);
  FOR x IN SELECT key,value FROM jsonb_each(d->'facts') LOOP
   PERFORM twuanis_canonical_private.s3_keys(x.value,ARRAY['kind','value','term','lower','upper','lower_inclusive','upper_inclusive','reference'],ARRAY['kind']);
   IF x.value->>'kind'<>'clear' THEN d:=jsonb_set(d,ARRAY['facts',x.key,'source'],to_jsonb(evidence_kind)); END IF;
  END LOOP;
 END IF;
 IF d ? 'measurements' THEN
  PERFORM twuanis_canonical_private.s3_keys(d->'measurements',ARRAY['property_area','construction_area']);
  FOR x IN SELECT key,value FROM jsonb_each(d->'measurements') LOOP
   IF x.value='{"kind":"clear"}'::jsonb THEN
    IF evidence_kind<>'owner' THEN RAISE EXCEPTION 'measurement clear requires customer authority' USING ERRCODE='42501'; END IF;
   ELSE
    PERFORM twuanis_canonical_private.s3_keys(x.value,ARRAY['value'],ARRAY['value']);
   END IF;
  END LOOP;
 END IF;
 FOREACH g IN ARRAY ARRAY['facts','measurements'] LOOP
  FOR x IN SELECT key,value FROM jsonb_each(coalesce(d->g,'{}')) LOOP
   FOREACH k IN ARRAY ARRAY['value','lower','upper'] LOOP
    IF x.value ? k AND x.value->k<>'null'::jsonb THEN d:=jsonb_set(d,ARRAY[g,x.key,k],to_jsonb(trim_scale(twuanis_canonical_private.s3_decimal(x.value->k))::text)); END IF;
   END LOOP;
  END LOOP;
 END LOOP;
 IF d ? 'money' THEN
  PERFORM twuanis_canonical_private.s3_keys(d->'money',ARRAY['amount','currency','reason'],ARRAY['amount','currency']);
  d:=jsonb_set(d,'{money,amount}',to_jsonb(trim_scale(twuanis_canonical_private.s3_decimal(d->'money'->'amount'))::text));
 END IF;
 IF d ? 'geography' THEN
  PERFORM twuanis_canonical_private.s3_keys(d->'geography',ARRAY['province','canton','district'],ARRAY['province','canton']);
  d:=jsonb_set(d,'{geography}',jsonb_build_object('district',NULL)||(d->'geography'));
 END IF;
 RETURN d;
END $$;


--
-- Name: s6_legacy_normalize(text, boolean); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.s6_legacy_normalize(v text, slug boolean DEFAULT false) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
 SELECT CASE WHEN slug THEN
  regexp_replace(regexp_replace(replace(regexp_replace(normalize(lower(coalesce(v,'')),NFD),U&'[\0300-\036f]','','g'),'+','plus'),'[^a-z0-9]+','-','g'),'(^-|-$)','','g')
 ELSE btrim(regexp_replace(regexp_replace(regexp_replace(normalize(lower(coalesce(v,'')),NFD),U&'[\0300-\036f]','','g'),'[^a-z0-9\s]',' ','g'),'\s+',' ','g')) END
$_$;


