--
-- Name: sinpe_account_guard(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.sinpe_account_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF TG_OP='DELETE' OR (NEW.id,NEW.currency,NEW.instructions_en,NEW.instructions_es) IS DISTINCT FROM (OLD.id,OLD.currency,OLD.instructions_en,OLD.instructions_es) THEN RAISE EXCEPTION 'receiving identity immutable'; END IF;RETURN NEW;END$$;


--
-- Name: sinpe_lock_order(uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.sinpe_lock_order(p_order uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$DECLARE o twuanis_canonical_private.offer_order_snapshots%ROWTYPE;BEGIN
 SELECT * INTO STRICT o FROM twuanis_canonical_private.offer_order_snapshots WHERE id=p_order;
 IF o.listing_id IS NOT NULL THEN PERFORM id FROM public.listings WHERE id=o.listing_id FOR UPDATE;
 ELSIF o.job_id IS NOT NULL THEN PERFORM twuanis_canonical_private.lock_capacity_policy(false);PERFORM id FROM public.publisher_accounts WHERE owner_user_id=o.account_id FOR UPDATE;PERFORM id FROM twuanis_canonical_private.addon_import_jobs WHERE id=o.job_id FOR UPDATE;END IF;
 PERFORM id FROM twuanis_canonical_private.offer_order_snapshots WHERE id=p_order FOR UPDATE;
END$$;


--
-- Name: sinpe_pending_review(uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.sinpe_pending_review(p_order uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT EXISTS(SELECT 1 FROM public.sinpe_payments p JOIN twuanis_canonical_private.offer_order_snapshots o ON o.id=p.canonical_order_id WHERE o.id=p_order AND p.created_at<=o.payment_deadline AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.sinpe_review_decisions d WHERE d.attempt_id=p.id))
$$;


--
-- Name: sinpe_projection(uuid, boolean); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.sinpe_projection(p_id uuid, p_admin boolean) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT jsonb_build_object('id',p.id,'orderId',p.canonical_order_id,'accountId',p.user_id,'submittedAt',p.created_at,'expectedAmount',o.resolved_terms->>'total','currency',o.currency,'deadline',o.payment_deadline,'lateEvidence',p.created_at>o.payment_deadline,'customerEvidence',p.submission_evidence,'receivingAccount',p.receiving_account_id,'state',coalesce(d.disposition,'REVIEW_PENDING'),'decisionAt',d.decided_at,'reason',d.reason,
 'awaitingPublication',d.disposition='APPROVED' AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.addon_fulfillments f WHERE f.purchase_id=o.id) AND EXISTS(SELECT 1 FROM public.listings l WHERE l.id=o.listing_id AND l.owner_id=o.account_id AND l.listing_status NOT IN('active','deleted')),
 'fulfillmentState',CASE WHEN d.disposition<>'APPROVED' OR d.disposition IS NULL THEN 'NOT_ELIGIBLE' ELSE coalesce((SELECT f.result->>'state' FROM twuanis_canonical_private.sinpe_fulfillment_attempts f WHERE f.order_id=o.id ORDER BY f.created_at DESC,f.id DESC LIMIT 1),'PENDING') END,
 'review',CASE WHEN p_admin THEN jsonb_build_object('actorId',d.actor_id,'bankReference',d.bank_reference,'receivedAt',d.received_at,'amount',d.amount::text,'currency',d.currency,'bankEvidence',d.bank_evidence,'receivingAccount',d.receiving_account_id) ELSE NULL END,
 'order',CASE WHEN p_admin THEN twuanis_canonical_private.order_evidence(o.id) ELSE NULL END)
 FROM public.sinpe_payments p JOIN twuanis_canonical_private.offer_order_snapshots o ON o.id=p.canonical_order_id LEFT JOIN twuanis_canonical_private.sinpe_review_decisions d ON d.attempt_id=p.id WHERE p.id=p_id
$$;


--
-- Name: sinpe_submission_guard(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.sinpe_submission_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF TG_OP='INSERT' THEN
  IF NEW.canonical_order_id IS NOT NULL AND current_user<>'postgres' THEN RAISE EXCEPTION 'trusted submission only';END IF;RETURN NEW;
 END IF;
 IF OLD.canonical_order_id IS NOT NULL OR (TG_OP='UPDATE' AND NEW.canonical_order_id IS NOT NULL) THEN RAISE EXCEPTION 'canonical submission immutable';END IF;
 IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;END$$;


--
-- Name: step2_approve_sinpe_payment(uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.step2_approve_sinpe_payment(p_payment_id uuid) RETURNS TABLE(payment_id uuid, subscription_id uuid, previous_subscription_id uuid, user_id uuid, package_id uuid, payment_status text, subscription_status text, period_start timestamp with time zone, period_end timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
#variable_conflict use_column
declare
    v_capacity_owner uuid;
    v_reviewer_id uuid;

    v_payment public.sinpe_payments%rowtype;

    v_pending_subscription
        public.user_subscriptions%rowtype;

    v_active_subscription
        public.user_subscriptions%rowtype;

    v_period_start timestamptz;
    v_period_end timestamptz;
begin
    -- ========================================================
    -- 1. VERIFY REVIEWER
    -- ========================================================

    perform public.require_payment_reviewer();

    v_reviewer_id := auth.uid();
    -- Identity-only pre-read, without a commercial row lock. Revalidate after wait.
    SELECT p.user_id INTO v_capacity_owner FROM public.sinpe_payments p WHERE p.id=p_payment_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'SINPE payment not found.'; END IF;
    PERFORM twuanis_canonical_private.ensure_publisher_account(v_capacity_owner);

    -- ========================================================
    -- 2. LOCK PAYMENT
    -- ========================================================

    select *
    into v_payment
    from public.sinpe_payments
    where id = p_payment_id
    for update;

    if not found then
        raise exception
            'SINPE payment not found.';
    end if;

    IF v_payment.user_id IS DISTINCT FROM v_capacity_owner THEN RAISE EXCEPTION 'payment owner changed' USING ERRCODE='40001'; END IF;

    if v_payment.status not in (
        'submitted',
        'under_review'
    ) then
        raise exception
            'Only submitted or under-review payments can be approved.';
    end if;

    -- ========================================================
    -- 3. LOCK PENDING SUBSCRIPTION
    -- ========================================================

    select *
    into v_pending_subscription
    from public.user_subscriptions
    where id = v_payment.subscription_id
    for update;

    if not found then
        raise exception
            'Pending subscription not found.';
    end if;

    if (
        v_pending_subscription.user_id <>
        v_payment.user_id
    ) then
        raise exception
            'Payment and subscription users do not match.';
    end if;

    if (
        v_pending_subscription.status <>
        'pending_payment'
    ) then
        raise exception
            'The target subscription is not pending payment.';
    end if;

    -- ========================================================
    -- 4. LOCK CURRENT ACTIVE SUBSCRIPTION
    -- ========================================================

    select *
    into v_active_subscription
    from public.user_subscriptions
    where user_id =
        v_pending_subscription.user_id
      and status = 'active'
      and id <>
        v_pending_subscription.id
    order by created_at desc
    limit 1
    for update;

    -- ========================================================
    -- 5. CALCULATE NEW SUBSCRIPTION PERIOD
    -- ========================================================

    v_period_start := clock_timestamp();

    v_period_end :=
        case
            when
                v_pending_subscription.billing_cycle =
                'annual'
            then
                v_period_start +
                interval '1 year'

            when
                v_pending_subscription.billing_cycle =
                'monthly'
            then
                v_period_start +
                interval '1 month'

            else
                null
        end;

    -- ========================================================
    -- 6. DEACTIVATE PREVIOUS SUBSCRIPTION
    -- ========================================================

    if v_active_subscription.id is not null then
        update public.user_subscriptions
        set
            status = 'cancelled',
            cancelled_at = v_period_start,
            current_period_end =
                least(
                    coalesce(
                        current_period_end,
                        v_period_start
                    ),
                    v_period_start
                ),
            updated_at = v_period_start
        where id =
            v_active_subscription.id;
    end if;

    -- ========================================================
    -- 7. ACTIVATE UPGRADED SUBSCRIPTION
    -- ========================================================

    update public.user_subscriptions
    set
        status = 'active',
        started_at = v_period_start,
        current_period_start =
            v_period_start,
        current_period_end =
            v_period_end,
        cancelled_at = null,
        expired_at = null,
        updated_at = v_period_start
    where id =
        v_pending_subscription.id;

    -- ========================================================
    -- 8. APPROVE SINPE PAYMENT
    -- ========================================================

    update public.sinpe_payments
    set
        status = 'approved',
        reviewed_by = v_reviewer_id,
        reviewed_at = v_period_start,
        approved_at = v_period_start,
        rejected_at = null,
        rejection_reason = null,
        updated_at = v_period_start
    where id = v_payment.id;

    -- ========================================================
    -- 9. RETURN RESULT
    -- ========================================================

    return query
    select
        v_payment.id,
        v_pending_subscription.id,
        v_active_subscription.id,
        v_pending_subscription.user_id,
        v_pending_subscription.package_id,
        'approved'::text,
        'active'::text,
        v_period_start,
        v_period_end;
end;
$$;


--
-- Name: step2_reject_sinpe_payment(uuid, text); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.step2_reject_sinpe_payment(p_payment_id uuid, p_rejection_reason text) RETURNS TABLE(payment_id uuid, subscription_id uuid, user_id uuid, package_id uuid, payment_status text, subscription_status text, rejection_reason text, rejected_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
    v_reviewer_id uuid;

    v_payment
        public.sinpe_payments%rowtype;

    v_pending_subscription
        public.user_subscriptions%rowtype;

    v_rejected_at timestamptz;
begin
    -- ========================================================
    -- 1. VERIFY REVIEWER
    -- ========================================================

    perform public.require_payment_reviewer();

    v_reviewer_id := auth.uid();

    -- ========================================================
    -- 2. VALIDATE REJECTION REASON
    -- ========================================================

    if
        p_rejection_reason is null
        or length(
            trim(
                p_rejection_reason
            )
        ) = 0
    then
        raise exception
            'A rejection reason is required.';
    end if;

    -- ========================================================
    -- 3. LOCK SINPE PAYMENT
    -- ========================================================

    select *
    into v_payment
    from public.sinpe_payments
    where id = p_payment_id
    for update;

    if not found then
        raise exception
            'SINPE payment not found.';
    end if;

    if v_payment.status not in (
        'submitted',
        'under_review'
    ) then
        raise exception
            'Only submitted or under-review payments can be rejected.';
    end if;

    -- ========================================================
    -- 4. LOCK PENDING SUBSCRIPTION
    -- ========================================================

    select *
    into v_pending_subscription
    from public.user_subscriptions
    where id = v_payment.subscription_id
    for update;

    if not found then
        raise exception
            'Pending subscription not found.';
    end if;

    if
        v_pending_subscription.user_id <>
        v_payment.user_id
    then
        raise exception
            'Payment and subscription users do not match.';
    end if;

    if
        v_pending_subscription.status <>
        'pending_payment'
    then
        raise exception
            'The target subscription is not pending payment.';
    end if;

    v_rejected_at := now();

    -- ========================================================
    -- 5. REJECT SINPE PAYMENT
    -- ========================================================

    update public.sinpe_payments
    set
        status = 'rejected',
        rejection_reason =
            trim(
                p_rejection_reason
            ),
        reviewed_by =
            v_reviewer_id,
        reviewed_at =
            v_rejected_at,
        rejected_at =
            v_rejected_at,
        approved_at =
            null,
        updated_at =
            v_rejected_at
    where id =
        v_payment.id;

    -- ========================================================
    -- 6. CANCEL PENDING SUBSCRIPTION
    -- ========================================================

    update public.user_subscriptions
    set
        status = 'cancelled',
        cancelled_at =
            v_rejected_at,
        started_at =
            null,
        current_period_start =
            null,
        current_period_end =
            null,
        expired_at =
            null,
        updated_at =
            v_rejected_at
    where id =
        v_pending_subscription.id;

    -- ========================================================
    -- 7. RETURN RESULT
    -- ========================================================

    return query
    select
        v_payment.id,
        v_pending_subscription.id,
        v_pending_subscription.user_id,
        v_pending_subscription.package_id,
        'rejected'::text,
        'cancelled'::text,
        trim(
            p_rejection_reason
        ),
        v_rejected_at;
end;
$$;


--
-- Name: stripe_paid(uuid); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.stripe_paid(p_ack uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT EXISTS(SELECT 1 FROM twuanis_canonical_private.stripe_receipts r JOIN twuanis_canonical_private.offer_paid_acknowledgements a ON a.id=r.acknowledgement_id JOIN twuanis_canonical_private.offer_order_snapshots o ON o.id=a.order_id JOIN twuanis_canonical_private.stripe_checkouts c ON c.order_id=o.id WHERE a.id=p_ack AND a.source='stripe' AND r.disposition='APPROVED' AND r.order_id=o.id AND r.amount=a.amount AND a.amount=(o.resolved_terms->>'total')::numeric AND r.currency=a.currency AND a.currency=o.currency AND r.paid_at BETWEEN o.created_at AND o.payment_deadline AND c.session_id=r.session_id AND c.account_id=r.account_id AND c.mode=r.mode AND c.payment_intent=r.payment_intent);
$$;


--
-- Name: validate_addon_configuration(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.validate_addon_configuration() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE pid text; p twuanis_canonical_private.addon_products%ROWTYPE; c twuanis_canonical_private.addon_configurations%ROWTYPE;
BEGIN
 IF TG_TABLE_NAME='addon_products' THEN pid:=NEW.id;
 ELSIF TG_TABLE_NAME='addon_configurations' THEN pid:=NEW.product_id;
 ELSE SELECT product_id INTO pid FROM twuanis_canonical_private.addon_configurations WHERE id=NEW.configuration_id; END IF;
 SELECT * INTO STRICT p FROM twuanis_canonical_private.addon_products WHERE id=pid;
 FOR c IN SELECT * FROM twuanis_canonical_private.addon_configurations WHERE product_id=pid LOOP
  IF (p.term_kind<>'elapsed_days' AND c.duration_days IS NOT NULL) OR (p.term_kind='elapsed_days' AND p.state='active' AND c.id=p.current_configuration_id AND c.duration_days IS NULL) THEN RAISE EXCEPTION 'typed add-on duration required'; END IF;
  IF p.term_kind='whole_job' THEN
   IF EXISTS(SELECT 1 FROM twuanis_canonical_private.addon_standard_prices WHERE configuration_id=c.id)
    OR (SELECT count(*) FROM twuanis_canonical_private.addon_quantity_tiers WHERE configuration_id=c.id)<>3
    OR NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.addon_quantity_tiers WHERE configuration_id=c.id AND lower_quantity=1 AND upper_quantity=25)
    OR NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.addon_quantity_tiers WHERE configuration_id=c.id AND lower_quantity=26 AND upper_quantity=100)
    OR NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.addon_quantity_tiers WHERE configuration_id=c.id AND lower_quantity=101 AND upper_quantity=500)
   THEN RAISE EXCEPTION 'approved complete whole-job schedule required'; END IF;
  ELSE
   IF EXISTS(SELECT 1 FROM twuanis_canonical_private.addon_quantity_tiers WHERE configuration_id=c.id) THEN RAISE EXCEPTION 'quantity pricing requires operation product'; END IF;
   IF p.term_kind='unconfigured' AND EXISTS(SELECT 1 FROM twuanis_canonical_private.addon_standard_prices WHERE configuration_id=c.id) THEN RAISE EXCEPTION 'future experience remains unpriced'; END IF;
   IF p.term_kind='lifetime' AND EXISTS(SELECT 1 FROM twuanis_canonical_private.addon_standard_prices WHERE configuration_id=c.id AND currency<>'USD') THEN RAISE EXCEPTION 'founding CRC unpriced'; END IF;
  END IF;
 END LOOP;
 IF p.term_kind='unconfigured' AND p.state<>'inactive' THEN RAISE EXCEPTION 'future experience remains inactive'; END IF;
 IF p.state='active' AND p.term_kind IN ('elapsed_days','lifetime') AND
  (SELECT count(*) FROM twuanis_canonical_private.addon_standard_prices WHERE configuration_id=p.current_configuration_id) <> (CASE WHEN EXISTS(SELECT 1 FROM twuanis_canonical_private.addon_configurations z WHERE z.id=p.current_configuration_id AND(z.placement_market IS NOT NULL OR z.calendar_months IS NOT NULL)) THEN 1 WHEN p.id='addon-homepage-exposure' AND p.current_configuration_id='05000000-0000-4000-8000-000000000103'::uuid THEN 1 WHEN p.term_kind='elapsed_days' THEN 2 ELSE 1 END)
 THEN RAISE EXCEPTION 'active add-on prices incomplete'; END IF;
 IF p.current_configuration_id='05000000-0000-4000-8000-000000000103'::uuid AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.addon_standard_prices WHERE configuration_id=p.current_configuration_id AND currency='USD' AND amount=500) THEN RAISE EXCEPTION 'exact USD Homepage Exposure version required';END IF;
 IF p.id='addon-homepage-background' AND p.state='active' THEN RAISE EXCEPTION 'background capacity and rotation pending';END IF;
 RETURN NULL;
END $$;


--
-- Name: validate_campaign_creative(jsonb); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.validate_campaign_creative(v jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$ DECLARE k text;u text;mid uuid; BEGIN
 IF jsonb_typeof(v) IS DISTINCT FROM 'object' OR octet_length(v::text)>12000 OR EXISTS(SELECT 1 FROM jsonb_object_keys(v)x WHERE x<>ALL(ARRAY['headline_en','headline_es','copy_en','copy_es','cta_en','cta_es','destination_en','destination_es','alt_en','alt_es','image','video'])) THEN RAISE EXCEPTION 'invalid creative';END IF;
 FOREACH k IN ARRAY ARRAY['headline_en','headline_es','copy_en','copy_es','cta_en','cta_es','destination_en','destination_es','alt_en','alt_es'] LOOP
  IF jsonb_typeof(v->k) IS DISTINCT FROM 'string' OR length(v->>k)>2000 THEN RAISE EXCEPTION 'localized creative fields required';END IF;
 END LOOP;
 FOREACH k IN ARRAY ARRAY['headline_en','headline_es','cta_en','cta_es'] LOOP IF length(btrim(v->>k)) NOT BETWEEN 1 AND 300 THEN RAISE EXCEPTION 'headline and CTA required';END IF;END LOOP;
 FOREACH k IN ARRAY ARRAY['destination_en','destination_es'] LOOP
  u:=v->>k;
  -- V1 owned destinations only. No open redirect, URL scheme, query redirect, or executable data.
  IF u <> ALL(ARRAY['/en','/es','/en/market-hub','/es/centro-de-mercado','/en/market-intelligence','/es/inteligencia-de-mercado','/en/market-intelligence/packages','/es/inteligencia-de-mercado/paquetes']) THEN RAISE EXCEPTION 'approved internal information destination required';END IF;
 END LOOP;
 FOREACH k IN ARRAY ARRAY['image','video'] LOOP
  IF v ? k AND v->k<>'null'::jsonb THEN
   mid:=(v->>k)::uuid;
   IF NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.campaign_media WHERE id=mid AND completed AND mime=CASE WHEN k='image' THEN 'image/jpeg' ELSE 'video/mp4' END) THEN RAISE EXCEPTION 'completed system media required';END IF;
   IF length(btrim(v->>'alt_en'))=0 OR length(btrim(v->>'alt_es'))=0 THEN RAISE EXCEPTION 'localized media description required';END IF;
  END IF;
 END LOOP;
END $$;


--
-- Name: validate_classification_rule(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.validate_classification_rule() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE v_domain text; v_type text; v_level integer;
BEGIN
  -- A fresh post-lock statement snapshot is required by this bounded validator.
  -- Reject other isolation levels rather than permit a stale overlap check.
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'classification insertion requires READ COMMITTED' USING ERRCODE = '0A000';
  END IF;
  -- Serialize inserts within a version without requiring a new extension.
  -- Classification publication/selection and lock integration belong to S3.
  SELECT s.domain INTO STRICT v_domain FROM public.listing_classification_rule_sets s
    WHERE s.id = NEW.rule_set_id FOR UPDATE;
  SELECT t.term_type, t.level INTO STRICT v_type, v_level FROM public.ontology_terms t
    WHERE t.id = NEW.ontology_term_id FOR SHARE;
  IF v_type IS DISTINCT FROM v_domain OR v_level IS DISTINCT FROM 1 THEN
    RAISE EXCEPTION 'classification term type/level mismatch' USING ERRCODE = '23514';
  END IF;
  IF EXISTS (SELECT 1 FROM public.listing_classification_rules r
    WHERE r.rule_set_id = NEW.rule_set_id AND r.bounds && NEW.bounds) THEN
    RAISE EXCEPTION 'classification bounds overlap within version' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: validate_new_term_reference(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.validate_new_term_reference() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE v_id bigint; v_domain text; v_type text; v_level integer;
BEGIN
  IF TG_TABLE_NAME = 'listing_semantic_selections' THEN
    v_id := NEW.ontology_term_id; v_domain := NEW.dimension;
  ELSIF TG_TABLE_NAME = 'listing_fact_evidence' THEN
    IF NEW.kind <> 'category' THEN RETURN NEW; END IF;
    v_id := NEW.category_term_id; v_domain := NEW.dimension;
  ELSE
    RAISE EXCEPTION 'unexpected validator attachment' USING ERRCODE = '55000';
  END IF;
  SELECT t.term_type, t.level INTO STRICT v_type, v_level
    FROM public.ontology_terms t WHERE t.id = v_id FOR SHARE;
  IF v_type IS DISTINCT FROM v_domain OR v_level IS DISTINCT FROM 1 THEN
    RAISE EXCEPTION 'term type/level mismatch for %', v_domain USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: validate_offer_configuration(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.validate_offer_configuration() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE cid uuid; c twuanis_canonical_private.offer_configurations%ROWTYPE;o twuanis_canonical_private.offers%ROWTYPE;
BEGIN
 IF TG_TABLE_NAME='offers' THEN cid:=NEW.current_configuration_id;
 ELSIF TG_TABLE_NAME='offer_configurations' THEN cid:=NEW.id; ELSE cid:=NEW.configuration_id; END IF;
 SELECT * INTO STRICT c FROM twuanis_canonical_private.offer_configurations WHERE id=cid;
 SELECT * INTO STRICT o FROM twuanis_canonical_private.offers WHERE id=c.offer_id;
 IF c.price_shape='whole_job' THEN
  IF o.addon_id IS DISTINCT FROM 'addon-bulk-listing-import'
   OR EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_scalar_prices WHERE configuration_id=cid)
   OR (SELECT count(*) FROM twuanis_canonical_private.offer_quantity_tiers WHERE configuration_id=cid)<>3
   OR NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_quantity_tiers WHERE configuration_id=cid AND lower_quantity=1 AND upper_quantity=25)
   OR NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_quantity_tiers WHERE configuration_id=cid AND lower_quantity=26 AND upper_quantity=100)
   OR NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_quantity_tiers WHERE configuration_id=cid AND lower_quantity=101 AND upper_quantity=500)
  THEN RAISE EXCEPTION 'complete approved whole-job offer schedule required'; END IF;
 ELSE
  IF o.addon_id='addon-bulk-listing-import'
   OR EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_quantity_tiers WHERE configuration_id=cid)
   OR NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_scalar_prices WHERE configuration_id=cid)
  THEN RAISE EXCEPTION 'scalar offer price required'; END IF;
 END IF;
 IF o.addon_id='addon-premium-listing-template' THEN RAISE EXCEPTION 'unavailable target'; END IF;
 IF o.addon_id='addon-2026-founding-membership' AND EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_scalar_prices WHERE configuration_id=cid AND currency<>'USD') THEN RAISE EXCEPTION 'founding CRC unpriced'; END IF;
 RETURN NULL;
END $$;


--
-- Name: validate_package_catalog(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.validate_package_catalog() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM twuanis_canonical_private.intelligence_packages p JOIN twuanis_canonical_private.intelligence_package_configurations v ON v.id=p.current_configuration_id WHERE p.state='active' AND (cardinality(v.capabilities)=0 OR (SELECT count(*) FROM twuanis_canonical_private.intelligence_package_prices s WHERE s.package_id=p.id)<>2)) THEN RAISE EXCEPTION 'active package incomplete'; END IF;
 RETURN NULL;
END $$;


--
-- Name: validate_package_configuration(); Type: FUNCTION; Schema: twuanis_canonical_private; Owner: -
--

CREATE FUNCTION twuanis_canonical_private.validate_package_configuration() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF NEW.capabilities IS DISTINCT FROM (SELECT coalesce(array_agg(DISTINCT c ORDER BY c),'{}'::text[]) FROM unnest(NEW.capabilities)c)
 OR EXISTS(SELECT 1 FROM unnest(NEW.capabilities)c WHERE NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.intelligence_capabilities WHERE id=c)) THEN RAISE EXCEPTION 'invalid capability set'; END IF;
 RETURN NEW;
END $$;


--
-- Name: authority(text, uuid, uuid); Type: FUNCTION; Schema: twuanis_measurement_private; Owner: -
--

CREATE FUNCTION twuanis_measurement_private.authority(p_event text, p_subject uuid, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$DECLARE r jsonb;BEGIN
 IF p_event IN('purchase','tw_payment_state') THEN
 SELECT jsonb_build_object('receipt_ref',a.id,'outcome_at',a.acknowledged_at,'product_id',o.product_id,'amount',a.amount::text,'currency',a.currency,'status','verified') INTO r
 FROM twuanis_canonical_private.offer_order_snapshots o JOIN twuanis_canonical_private.offer_paid_acknowledgements a ON a.order_id=o.id
 JOIN twuanis_canonical_private.onvo_receipts v ON v.acknowledgement_id=a.id AND v.order_id=o.id AND v.disposition='APPROVED' AND v.amount=a.amount AND v.currency=a.currency
 WHERE o.id=p_subject AND o.account_id=p_actor AND o.target_type='package' AND a.source='onvo' AND a.currency=o.currency AND a.amount=(o.resolved_terms->>'total')::numeric AND a.amount>0;
 ELSIF p_event='tw_entitlement_state' THEN
 SELECT jsonb_build_object('receipt_ref',t.id,'outcome_at',t.committed_at,'product_id',t.product_id,'status','active') INTO r
 FROM twuanis_canonical_private.entitlement_terms t JOIN twuanis_canonical_private.offer_order_snapshots o ON o.id=t.order_id
 JOIN twuanis_canonical_private.offer_paid_acknowledgements a ON a.id=t.acknowledgement_id AND a.order_id=o.id
 JOIN twuanis_canonical_private.intelligence_package_rights rights ON rights.id=t.id AND rights.account_id=t.account_id AND rights.package_id=t.product_id AND rights.configuration_id=t.configuration_id AND rights.starts_at=t.starts_at AND rights.ends_at=t.ends_at
 WHERE o.id=p_subject AND o.account_id=p_actor AND t.account_id=p_actor AND t.product_class='PACKAGE' AND t.product_id=o.product_id AND t.source='PURCHASED'
 AND t.starts_at<=clock_timestamp() AND t.ends_at>clock_timestamp() AND NOT EXISTS(SELECT 1 FROM twuanis_canonical_private.entitlement_revocations rv WHERE rv.term_id=t.id);
 ELSIF p_event='tw_report_ready' THEN
 SELECT jsonb_build_object('receipt_ref',rpt.id,'outcome_at',rpt.created_at,'status','complete','capability_id',e.orchestrator_id) INTO r
 FROM twuanis_canonical_private.execution_credit_reports rpt JOIN twuanis_canonical_private.execution_credit_executions e ON e.id=rpt.execution_id
 WHERE e.id=p_subject AND e.account_id=p_actor AND rpt.account_id=p_actor
 AND EXISTS(SELECT 1 FROM twuanis_canonical_private.execution_credit_events ev WHERE ev.execution_id=e.id AND ev.report_id=rpt.id AND ev.kind IN('EXECUTION_CONSUMED','OWNER_COMPLETED'));
 ELSIF p_event='tw_execution_result' THEN
 SELECT jsonb_build_object('receipt_ref',ev.id::text,'outcome_at',ev.occurred_at,'status',CASE WHEN ev.kind='RESERVATION_RELEASED' THEN 'failure' ELSE 'success' END,'capability_id',e.orchestrator_id) INTO r
 FROM twuanis_canonical_private.execution_credit_executions e JOIN twuanis_canonical_private.execution_credit_events ev ON ev.execution_id=e.id
 WHERE e.id=p_subject AND e.account_id=p_actor AND ((twuanis_canonical_private.execution_credit_execution_state(e.id)='COMPLETED' AND ev.kind IN('EXECUTION_CONSUMED','OWNER_COMPLETED')) OR(twuanis_canonical_private.execution_credit_execution_state(e.id)='RELEASED' AND ev.kind='RESERVATION_RELEASED'))
 ORDER BY ev.occurred_at,ev.id LIMIT 1;
 END IF;RETURN r;
END$$;


--
-- Name: journey_admit_r3(integer, integer); Type: FUNCTION; Schema: twuanis_measurement_private; Owner: -
--

CREATE FUNCTION twuanis_measurement_private.journey_admit_r3(p_starts integer, p_events integer) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE c twuanis_measurement_private.journey_policy_r3%ROWTYPE;n timestamptz:=date_trunc('minute',clock_timestamp());
BEGIN
 SELECT * INTO c FROM twuanis_measurement_private.journey_policy_r3 WHERE singleton FOR UPDATE;
 IF public.ka10_journey_policy()->>'state'<>'APPROVED' THEN RETURN 'POLICY_REQUIRED';END IF;
 IF c.minute_at IS DISTINCT FROM n THEN c.starts:=0;c.events:=0;END IF;
 IF c.starts+p_starts>100 OR c.events+p_events>2000 THEN UPDATE twuanis_measurement_private.journey_policy_r3 SET rate_rejections=rate_rejections+1 WHERE singleton;RETURN 'RATE_LIMITED';END IF;
 UPDATE twuanis_measurement_private.journey_policy_r3 SET minute_at=n,starts=c.starts+p_starts,events=c.events+p_events WHERE singleton;
 RETURN 'ADMITTED';
END $$;


--
-- Name: journey_archive_r4(); Type: FUNCTION; Schema: twuanis_measurement_private; Owner: -
--

CREATE FUNCTION twuanis_measurement_private.journey_archive_r4() RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    SET statement_timeout TO '5s'
    AS $$
DECLARE ids text[];r record;c twuanis_measurement_private.journey_policy_r3%ROWTYPE;preserved integer:=0;withheld integer:=0;
BEGIN
 SELECT * INTO c FROM twuanis_measurement_private.journey_policy_r3 WHERE singleton;
 SELECT array_agg(id) INTO ids FROM(SELECT j.id FROM twuanis_measurement_private.journeys_r3 j WHERE j.history_until<=clock_timestamp() AND j.archive_state IS NULL AND j.aggregate_ref IS NOT NULL AND NOT EXISTS(SELECT 1 FROM twuanis_measurement_private.journey_orders_r3 active_order WHERE active_order.journey=j.id AND active_order.followup_until>clock_timestamp()) AND NOT j.suppressed AND j.policy_ref IS NOT NULL AND j.account_id IS DISTINCT FROM 'd81064bc-1b4a-478f-8f6a-b263c4779bc1'::uuid AND NOT EXISTS(SELECT 1 FROM twuanis_measurement_private.journey_erasure_r3 er WHERE er.account_id=j.account_id OR EXISTS(SELECT 1 FROM twuanis_measurement_private.journey_orders_r3 o WHERE o.journey=j.id AND o.account_id=er.account_id) OR EXISTS(SELECT 1 FROM twuanis_measurement_private.journey_events_r3 ev JOIN twuanis_canonical_private.offer_order_snapshots own ON own.id::text=ev.envelope->>'order' WHERE ev.journey=j.id AND ev.authority='canonical' AND own.account_id=er.account_id)) ORDER BY j.history_until,j.id LIMIT greatest(10,c.min_contributors) FOR UPDATE) due;
 IF ids IS NULL THEN RETURN '{"state":"CHECKED","scopes":0}';END IF;
 SELECT max(minimum_contributors),CASE WHEN bool_and(anonymous_aggregate_approved) THEN 'scope-approved' END,'snapshot-'||md5(string_agg(DISTINCT aggregate_ref,'|' ORDER BY aggregate_ref)) INTO c.min_contributors,c.anonymous_aggregate_approval_ref,c.aggregate_approval_ref FROM twuanis_measurement_private.journeys_r3 WHERE id=ANY(ids);
 IF c.aggregate_approval_ref IS NULL THEN RETURN '{"state":"POLICY_REQUIRED"}';END IF;
 FOR r IN
 SELECT * FROM twuanis_measurement_private.journey_cells_r4(ids,true) LOOP
 IF r.contributors>=c.min_contributors AND r.dominance<=0.2 AND (NOT r.anonymous OR c.anonymous_aggregate_approval_ref IS NOT NULL) AND (r.paid=0 OR r.payers>=c.min_contributors AND r.revenue_dominance<=0.2) THEN
 INSERT INTO twuanis_measurement_private.journey_business_r4(bucket_day,cohort_day,projection,dimensions,event_count,scope_occurrences,scope_starts,revenue,status,policy_ref) VALUES(r.event_day,r.cohort,r.projection,r.dimensions,r.events,r.scopes,r.starts,CASE WHEN r.projection='commercial' THEN r.paid END,'APPROVED_AGGREGATE',c.aggregate_approval_ref)
 ON CONFLICT(bucket_day,cohort_day,projection,dimensions) DO UPDATE SET event_count=journey_business_r4.event_count+excluded.event_count,scope_occurrences=journey_business_r4.scope_occurrences+excluded.scope_occurrences,scope_starts=journey_business_r4.scope_starts+excluded.scope_starts,revenue=journey_business_r4.revenue+excluded.revenue,updated_at=clock_timestamp();preserved:=preserved+1;
 ELSE
 -- Do not retain a fine sparse cell, its value, category, campaign or revenue.
 INSERT INTO twuanis_measurement_private.journey_business_r4(bucket_day,cohort_day,projection,dimensions,status,policy_ref) VALUES(date_trunc('month',r.event_day)::date,date_trunc('month',r.cohort)::date,'coverage','{"reason":"privacy_withheld"}','PRIVACY_WITHHELD',c.aggregate_approval_ref) ON CONFLICT DO NOTHING;withheld:=withheld+1;
 END IF;
 END LOOP;
 UPDATE twuanis_measurement_private.journeys_r3 SET archive_state=CASE WHEN preserved>0 THEN 'PRESERVED' ELSE 'PRIVACY_WITHHELD' END WHERE id=ANY(ids);
 RETURN jsonb_build_object('state','CHECKED','scopes',cardinality(ids),'preservedCells',preserved,'privacyWithheldCells',withheld);
END $$;


--
-- Name: journey_cells_r4(text[], boolean); Type: FUNCTION; Schema: twuanis_measurement_private; Owner: -
--

CREATE FUNCTION twuanis_measurement_private.journey_cells_r4(p_ids text[], p_archival boolean) RETURNS TABLE(event_day date, cohort date, projection text, dimensions jsonb, events bigint, scopes bigint, starts bigint, paid numeric, contributors bigint, anonymous boolean, dominance numeric, revenue_dominance numeric, payers bigint)
    LANGUAGE sql
    SET search_path TO 'pg_catalog'
    AS $_$
 WITH source AS MATERIALIZED(
 SELECT e.*,j.created_at,(e.observed_at AT TIME ZONE 'UTC')::date event_day,(j.created_at AT TIME ZONE 'UTC')::date cohort,
 coalesce(CASE WHEN j.identity_until>clock_timestamp() THEN j.account_id::text END,'anonymous:'||j.id) contributor,(j.account_id IS NULL OR j.identity_until<=clock_timestamp()) anonymous,
 min(e.received_seq) OVER(PARTITION BY e.journey) first_event,
 CASE WHEN e.envelope->>'name'='purchase' AND e.authority='canonical' THEN (e.envelope->>'amount')::numeric ELSE 0 END paid,
 CASE WHEN e.envelope->>'name'='page_view' THEN 'landing' WHEN e.envelope->>'control'='navigate_intelligence' THEN 'intelligence' WHEN e.envelope->>'control' LIKE 'example_open_%' THEN 'example' WHEN e.envelope->>'control' LIKE 'capability_navigation_%' THEN 'algorithm' WHEN e.envelope->>'control' LIKE 'view_package_%' OR e.envelope->>'name'='tw_package_view' THEN 'package' WHEN e.envelope->>'name'='begin_checkout' THEN 'checkout' WHEN e.envelope->>'name'='tw_order_created' THEN 'order' WHEN e.envelope->>'name'='purchase' AND e.authority='canonical' THEN 'purchase' WHEN e.envelope->>'name'='tw_access_active' THEN 'access' WHEN e.envelope->>'control' LIKE 'navigate_%_discovery' THEN 'discovery' END stage
 FROM twuanis_measurement_private.journey_archival_r4 e JOIN twuanis_measurement_private.journeys_r3 j ON j.id=e.journey WHERE e.journey=ANY(p_ids) AND (p_archival OR(least(e.retention_until,twuanis_measurement_private.journey_evidence_deadline_r4(j,e.observed_at))>clock_timestamp() AND j.archive_state IS NULL))
 ), first_stages AS(SELECT DISTINCT ON(journey,stage) * FROM source WHERE stage IS NOT NULL ORDER BY journey,stage,observed_at,received_seq), transitions AS(SELECT *,lag(stage) OVER(PARTITION BY journey ORDER BY observed_at,received_seq) previous FROM first_stages),
 cells AS(
 SELECT event_day,cohort,journey,contributor,anonymous,paid,received_seq=first_event starts,p.projection,p.dimensions FROM source CROSS JOIN LATERAL(
 SELECT 'traffic'::text projection,jsonb_build_object('locale',coalesce(envelope->>'locale','unknown'),'population',coalesce(envelope->>'population',envelope->'evidence'->>'listing_market','UNKNOWN'),'event',envelope->>'name') dimensions
 UNION ALL SELECT 'acquisition',jsonb_build_object('campaign',coalesce(envelope->>'campaign','unattributed'),'source',coalesce(envelope->>'source','unattributed'),'medium',coalesce(envelope->>'medium','unattributed'),'landing',CASE WHEN envelope->>'landing' ~ '^/(en|es)(/(buy|comprar|rent-lease|alquilar-arrendar|bank-properties|remates|market-intelligence|inteligencia-de-mercado)(/packages|/paquetes)?)?$' THEN envelope->>'landing' WHEN received_seq=first_event THEN coalesce(envelope->>'page','unavailable') ELSE 'unavailable' END,'locale',coalesce(envelope->>'locale','unknown'))
 UNION ALL SELECT 'feature',jsonb_build_object('control',coalesce(envelope->>'control',envelope->>'name'),'locale',coalesce(envelope->>'locale','unknown'),'population',coalesce(envelope->>'population',envelope->'evidence'->>'listing_market','UNKNOWN'))
 UNION ALL SELECT 'algorithm',jsonb_build_object('control',envelope->>'control','algorithm',CASE WHEN envelope->>'subject' ~ '^(summary|composition|market-asking-price-distribution|matching|comparison|configuration|distribution|geography|size|construction-land|cohort-comparison|cross-dimensional|discovery|position|comparables|asking-area-ratio|weighted-price)$' THEN envelope->>'subject' ELSE envelope->>'control' END,'locale',coalesce(envelope->>'locale','unknown')) WHERE envelope->>'control' ~ '^(example_open|capability_navigation|view_package|locked_card_packages)_' OR envelope->>'operation'='execution'
 UNION ALL SELECT 'commercial',jsonb_build_object('product',coalesce(envelope->>'product','unavailable'),'campaign',coalesce(envelope->>'campaign','unattributed'),'currency',coalesce(envelope->>'currency','unavailable'),'event',envelope->>'name','outcome',envelope->>'outcome') WHERE envelope->>'operation' IN('checkout','order','payment_status')
 )p
 UNION ALL SELECT cohort,cohort,journey,contributor,anonymous,0,false,'flow',jsonb_build_object('stage',stage,'campaign',coalesce(envelope->>'campaign','unattributed')) FROM first_stages
 UNION ALL SELECT cohort,cohort,journey,contributor,anonymous,0,false,'transition',jsonb_build_object('from',previous,'to',stage,'campaign',coalesce(envelope->>'campaign','unattributed')) FROM transitions WHERE previous IS NOT NULL
 ), per_contributor AS(SELECT event_day,cohort,projection,dimensions,contributor,bool_or(anonymous) anonymous,count(*) events,count(DISTINCT journey) scopes,count(*) FILTER(WHERE starts) starts,sum(paid) paid FROM cells GROUP BY event_day,cohort,projection,dimensions,contributor), totals AS(
 SELECT event_day,cohort,projection,dimensions,sum(events)::bigint events,sum(scopes)::bigint scopes,sum(starts)::bigint starts,sum(paid) paid,count(*) contributors,bool_or(anonymous) anonymous,max(events)::numeric/sum(events) dominance,CASE WHEN sum(paid)>0 THEN max(paid)/sum(paid) ELSE 0 END revenue_dominance,count(*) FILTER(WHERE paid>0) payers FROM per_contributor GROUP BY event_day,cohort,projection,dimensions
 ) SELECT * FROM totals;
$_$;


--
-- Name: journey_close_clock_r4(); Type: FUNCTION; Schema: twuanis_measurement_private; Owner: -
--

CREATE FUNCTION twuanis_measurement_private.journey_close_clock_r4() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF NEW.collection_closed_at IS NULL AND(NEW.ended_at IS NOT NULL OR NEW.expires_at<=clock_timestamp() OR NEW.last_at+interval '30 minutes'<=clock_timestamp()) THEN
 NEW.collection_closed_at:=least(NEW.ended_at,NEW.expires_at,NEW.last_at+interval '30 minutes');NEW.ended_at:=coalesce(NEW.ended_at,NEW.collection_closed_at);NEW.end_reason:=coalesce(NEW.end_reason,'expiry');NEW.history_until:=NEW.collection_closed_at+make_interval(days=>NEW.history_days);
 UPDATE twuanis_measurement_private.journey_events_r3 SET retention_until=greatest(NEW.history_until,observed_at+make_interval(days=>NEW.history_days)) WHERE journey=NEW.id;
 END IF;RETURN NEW;
END $$;


--
-- Name: journeys_r3; Type: TABLE; Schema: twuanis_measurement_private; Owner: -
--

CREATE TABLE twuanis_measurement_private.journeys_r3 (
    id text NOT NULL,
    proof text NOT NULL,
    notice text DEFAULT 'journey-r4-pending'::text NOT NULL,
    account_id uuid,
    auth_session uuid,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    history_days integer,
    collection_closed_at timestamp with time zone,
    last_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    expires_at timestamp with time zone DEFAULT (clock_timestamp() + '24:00:00'::interval) NOT NULL,
    history_until timestamp with time zone DEFAULT '-infinity'::timestamp with time zone NOT NULL,
    identity_until timestamp with time zone DEFAULT '-infinity'::timestamp with time zone NOT NULL,
    commercial_until timestamp with time zone DEFAULT '-infinity'::timestamp with time zone NOT NULL,
    aggregate_ref text,
    anonymous_aggregate_approved boolean DEFAULT false NOT NULL,
    minimum_contributors integer DEFAULT 10 NOT NULL,
    archive_state text,
    policy_ref text,
    linked_at timestamp with time zone,
    end_reason text,
    ended_at timestamp with time zone,
    suppressed boolean DEFAULT false NOT NULL,
    received integer DEFAULT 0 NOT NULL,
    CONSTRAINT journeys_r3_archive_state_check CHECK ((archive_state = ANY (ARRAY['PRESERVED'::text, 'PRIVACY_WITHHELD'::text]))),
    CONSTRAINT journeys_r3_check CHECK (((account_id IS NOT NULL) OR (auth_session IS NULL))),
    CONSTRAINT journeys_r3_end_reason_check CHECK ((end_reason = ANY (ARRAY['logout'::text, 'switch'::text, 'withdrawal'::text, 'owner'::text, 'expiry'::text]))),
    CONSTRAINT journeys_r3_history_days_check CHECK ((history_days > 0)),
    CONSTRAINT journeys_r3_id_check CHECK ((id ~ '^[a-f0-9]{32}$'::text)),
    CONSTRAINT journeys_r3_minimum_contributors_check CHECK ((minimum_contributors >= 10)),
    CONSTRAINT journeys_r3_notice_check CHECK (((notice = 'journey-r4-pending'::text) OR (notice ~ '^journey-r4-[a-f0-9]{32}$'::text))),
    CONSTRAINT journeys_r3_proof_check CHECK ((proof ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT journeys_r3_received_check CHECK (((received >= 0) AND (received <= 2000)))
);


--
-- Name: journey_evidence_deadline_r4(twuanis_measurement_private.journeys_r3, timestamp with time zone); Type: FUNCTION; Schema: twuanis_measurement_private; Owner: -
--

CREATE FUNCTION twuanis_measurement_private.journey_evidence_deadline_r4(p_journey twuanis_measurement_private.journeys_r3, p_observed timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
 SELECT greatest(coalesce(p_journey.collection_closed_at,least(p_journey.ended_at,p_journey.expires_at,p_journey.last_at+interval '30 minutes')),p_observed)+make_interval(days=>p_journey.history_days)
$$;


--
-- Name: journey_paid_r3(uuid, uuid); Type: FUNCTION; Schema: twuanis_measurement_private; Owner: -
--

CREATE FUNCTION twuanis_measurement_private.journey_paid_r3(p_order uuid, p_account uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE r jsonb;
BEGIN
 r:=twuanis_measurement_private.authority('purchase',p_order,p_account);IF r IS NOT NULL THEN RETURN r;END IF;
 SELECT jsonb_build_object('receipt_ref',a.id,'outcome_at',a.acknowledged_at,'product_id',o.product_id,'amount',a.amount::text,'currency',a.currency,'status','verified') INTO r
 FROM twuanis_canonical_private.offer_order_snapshots o JOIN twuanis_canonical_private.offer_paid_acknowledgements a ON a.order_id=o.id
 JOIN twuanis_canonical_private.onvo_receipts v ON v.acknowledgement_id=a.id AND v.order_id=o.id AND v.disposition='APPROVED' AND v.amount=a.amount AND v.currency=a.currency
 WHERE o.id=p_order AND o.account_id=p_account AND a.source='onvo' AND a.currency=o.currency AND a.amount=(o.resolved_terms->>'total')::numeric AND a.amount>0;
 IF r IS NOT NULL THEN IF EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_order_snapshots WHERE id=p_order AND target_type='execution_credit') THEN BEGIN PERFORM twuanis_canonical_private.assert_execution_credit_payment(p_order,(r->>'receipt_ref')::uuid);EXCEPTION WHEN OTHERS THEN RETURN NULL;END;END IF; RETURN r;END IF;
 IF to_regprocedure('twuanis_canonical_private.stripe_paid(uuid)') IS NOT NULL THEN
 EXECUTE $query$ SELECT jsonb_build_object('receipt_ref',a.id,'outcome_at',a.acknowledged_at,'product_id',o.product_id,'amount',a.amount::text,'currency',a.currency,'status','verified') FROM twuanis_canonical_private.offer_order_snapshots o JOIN twuanis_canonical_private.offer_paid_acknowledgements a ON a.order_id=o.id WHERE o.id=$1 AND o.account_id=$2 AND a.source='stripe' AND a.amount>0 AND a.currency=o.currency AND a.amount=(o.resolved_terms->>'total')::numeric AND twuanis_canonical_private.stripe_paid(a.id) $query$ INTO r USING p_order,p_account;
 END IF;IF r IS NOT NULL THEN IF EXISTS(SELECT 1 FROM twuanis_canonical_private.offer_order_snapshots WHERE id=p_order AND target_type='execution_credit') THEN BEGIN PERFORM twuanis_canonical_private.assert_execution_credit_payment(p_order,(r->>'receipt_ref')::uuid);EXCEPTION WHEN OTHERS THEN RETURN NULL;END;END IF; END IF;RETURN r;
END $_$;


--
-- Name: journey_record_clock_r4(); Type: FUNCTION; Schema: twuanis_measurement_private; Owner: -
--

CREATE FUNCTION twuanis_measurement_private.journey_record_clock_r4() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE j twuanis_measurement_private.journeys_r3%ROWTYPE;
BEGIN
 SELECT * INTO j FROM twuanis_measurement_private.journeys_r3 WHERE id=NEW.journey;
 IF j.history_days IS NULL OR j.history_days<=0 THEN RAISE EXCEPTION 'Missing approved retention snapshot';END IF;
 -- Later actual outcome/observation gets a full personal-evidence window. No receipt-time fabrication.
 NEW.retention_until:=greatest(j.history_until,NEW.observed_at+make_interval(days=>j.history_days));RETURN NEW;
END $$;


--
-- Name: subject(text, uuid, uuid); Type: FUNCTION; Schema: twuanis_measurement_private; Owner: -
--

CREATE FUNCTION twuanis_measurement_private.subject(p_kind text, p_id uuid, p_actor uuid) RETURNS timestamp with time zone
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT created_at FROM twuanis_canonical_private.offer_order_snapshots WHERE p_kind='order' AND id=p_id AND account_id=p_actor AND target_type='package'
 UNION ALL SELECT reserved_at FROM twuanis_canonical_private.execution_credit_executions WHERE p_kind='execution' AND id=p_id AND account_id=p_actor
$$;


--
-- Name: normalize_geographic_projection(text); Type: FUNCTION; Schema: twuanis_private; Owner: -
--

CREATE FUNCTION twuanis_private.normalize_geographic_projection(p_name text) RETURNS text
    LANGUAGE sql STABLE STRICT
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  SELECT btrim(regexp_replace(regexp_replace(
    lower(public.unaccent('public.unaccent'::regdictionary, p_name)),
    '[^a-z0-9 ]', '', 'g'), '[[:space:]]+', ' ', 'g'));
$$;


--
-- Name: write_listing_canonical(uuid, text, text, text, text, text, uuid, boolean); Type: FUNCTION; Schema: twuanis_private; Owner: -
--

CREATE FUNCTION twuanis_private.write_listing_canonical(p_listing_id uuid, p_operation text, p_province_code text, p_canton_code text, p_district_code text, p_expected_status text, p_actor_id uuid, p_trusted_server boolean) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE
  v_listing public.listings%ROWTYPE;
  v_p public.ontology_terms%ROWTYPE;
  v_c public.ontology_terms%ROWTYPE;
  v_d public.ontology_terms%ROWTYPE;
  v_row public.ontology_terms%ROWTYPE;
  v_ids bigint[];
  v_id bigint;
  v_pc bigint;
  v_cc bigint;
  v_dc bigint;
  v_matches boolean;
BEGIN
  IF p_operation IS DISTINCT FROM 'set_geography' THEN
    RAISE EXCEPTION 'CG3 unsupported operation' USING ERRCODE = '22023';
  END IF;
  IF p_province_code IS NULL OR p_province_code !~ '^[0-9]$' THEN
    RAISE EXCEPTION 'CG3 malformed Province code' USING ERRCODE = '22023';
  END IF;
  IF p_canton_code IS NULL OR p_canton_code !~ '^[0-9]{3}$' THEN
    RAISE EXCEPTION 'CG3 malformed Canton code' USING ERRCODE = '22023';
  END IF;
  IF p_district_code IS NOT NULL AND p_district_code !~ '^[0-9]{5}$' THEN
    RAISE EXCEPTION 'CG3 malformed District code' USING ERRCODE = '22023';
  END IF;

  SELECT l.* INTO v_listing FROM public.listings AS l
  WHERE l.id = p_listing_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'CG3 listing not found' USING ERRCODE = 'P0002';
  END IF;
  IF p_trusted_server IS NULL OR
     (NOT p_trusted_server AND (p_actor_id IS NULL OR
       v_listing.owner_id IS DISTINCT FROM p_actor_id)) OR
     (p_trusted_server AND p_actor_id IS NOT NULL) THEN
    RAISE EXCEPTION 'CG3 unauthorized operation context' USING ERRCODE = '42501';
  END IF;
  IF p_expected_status IS NULL OR
     v_listing.listing_status IS DISTINCT FROM p_expected_status THEN
    RAISE EXCEPTION 'CG3 stale expected status' USING ERRCODE = '40001';
  END IF;
  IF v_listing.listing_status NOT IN ('draft', 'active', 'expired') THEN
    RAISE EXCEPTION 'CG3 lifecycle state does not permit geography edit'
      USING ERRCODE = '22023';
  END IF;

  -- Exact, geographically restricted lookup. CG-1 enforces uniqueness;
  -- STRICT additionally rejects absent/ambiguous identities.
  SELECT t.* INTO STRICT v_p FROM public.ontology_terms AS t
  WHERE t.official_code = p_province_code
    AND t.term_type IN ('province', 'canton', 'district');
  SELECT t.* INTO STRICT v_c FROM public.ontology_terms AS t
  WHERE t.official_code = p_canton_code
    AND t.term_type IN ('province', 'canton', 'district');
  IF p_district_code IS NOT NULL THEN
    SELECT t.* INTO STRICT v_d FROM public.ontology_terms AS t
    WHERE t.official_code = p_district_code
      AND t.term_type IN ('province', 'canton', 'district');
  END IF;
  v_ids := ARRAY[v_p.id, v_c.id];
  IF p_district_code IS NOT NULL THEN
    v_ids := array_append(v_ids, v_d.id);
  END IF;

  -- Materialize sorted scalar IDs before acquiring any dictionary row lock.
  -- Each sequential statement locks just one primary-key row. Re-read after
  -- waiting, then revalidate identity: the initial unlocked snapshot is not trust.
  FOR v_id IN SELECT u.id FROM unnest(v_ids) AS u(id) ORDER BY u.id LOOP
    SELECT t.* INTO STRICT v_row FROM public.ontology_terms AS t
    WHERE t.id = v_id FOR SHARE;
    IF v_id = v_p.id THEN v_p := v_row;
    ELSIF v_id = v_c.id THEN v_c := v_row;
    ELSE v_d := v_row;
    END IF;
  END LOOP;
  IF v_p.official_code IS DISTINCT FROM p_province_code OR
     v_p.term_type IS DISTINCT FROM 'province' OR v_p.level IS DISTINCT FROM 1 OR
     v_c.official_code IS DISTINCT FROM p_canton_code OR
     v_c.term_type IS DISTINCT FROM 'canton' OR v_c.level IS DISTINCT FROM 2 OR
     (p_district_code IS NOT NULL AND (
       v_d.official_code IS DISTINCT FROM p_district_code OR
       v_d.term_type IS DISTINCT FROM 'district' OR v_d.level IS DISTINCT FROM 3)) THEN
    RAISE EXCEPTION 'CG3 dictionary identity/type/level disagreement' USING ERRCODE = '23514';
  END IF;
  IF v_c.parent_id IS DISTINCT FROM v_p.id OR
     left(v_c.official_code, 1) IS DISTINCT FROM v_p.official_code OR
     (p_district_code IS NOT NULL AND (
       v_d.parent_id IS DISTINCT FROM v_c.id OR
       left(v_d.official_code, 3) IS DISTINCT FROM v_c.official_code OR
       left(v_d.official_code, 1) IS DISTINCT FROM v_p.official_code)) THEN
    RAISE EXCEPTION 'CG3 hierarchy conflict' USING ERRCODE = '23514';
  END IF;
  IF v_p.term_name IS NULL OR v_c.term_name IS NULL OR
     (p_district_code IS NOT NULL AND v_d.term_name IS NULL) THEN
    RAISE EXCEPTION 'CG3 missing canonical term name' USING ERRCODE = '23514';
  END IF;

  DELETE FROM public.listings_ontology_terms AS lot
  USING public.ontology_terms AS term
  WHERE lot.listing_id = p_listing_id
    AND term.id = lot.ontology_term_id
    AND term.term_type IN ('province', 'canton', 'district');

  INSERT INTO public.listings_ontology_terms (listing_id, ontology_term_id)
  SELECT p_listing_id, u.id FROM unnest(v_ids) AS u(id);

  UPDATE public.listings AS l SET
    province = v_p.term_name,
    canton = v_c.term_name,
    district = v_d.term_name,
    province_normalized = twuanis_private.normalize_geographic_projection(v_p.term_name),
    canton_normalized = twuanis_private.normalize_geographic_projection(v_c.term_name),
    district_normalized = twuanis_private.normalize_geographic_projection(v_d.term_name)
  WHERE l.id = p_listing_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'CG3 projection update failed' USING ERRCODE = '23514';
  END IF;

  SELECT count(*) FILTER (WHERE t.term_type = 'province'),
         count(*) FILTER (WHERE t.term_type = 'canton'),
         count(*) FILTER (WHERE t.term_type = 'district'),
         bool_and(CASE t.term_type
           WHEN 'province' THEN t.id = v_p.id AND t.level = 1
             AND t.official_code = p_province_code
           WHEN 'canton' THEN t.id = v_c.id AND t.level = 2
             AND t.official_code = p_canton_code AND t.parent_id = v_p.id
           WHEN 'district' THEN t.id = v_d.id AND t.level = 3
             AND t.official_code = p_district_code AND t.parent_id = v_c.id
           ELSE false END)
    INTO v_pc, v_cc, v_dc, v_matches
  FROM public.listings_ontology_terms AS lot
  JOIN public.ontology_terms AS t ON t.id = lot.ontology_term_id
  WHERE lot.listing_id = p_listing_id
    AND t.term_type IN ('province', 'canton', 'district');
  IF v_pc <> 1 OR v_cc <> 1 OR
     v_dc <> (CASE WHEN p_district_code IS NULL THEN 0 ELSE 1 END) OR
     v_matches IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'CG3 invalid final canonical memberships' USING ERRCODE = '23514';
  END IF;
  SELECT l.* INTO STRICT v_listing FROM public.listings AS l WHERE l.id = p_listing_id;
  IF v_listing.province IS DISTINCT FROM v_p.term_name OR
     v_listing.canton IS DISTINCT FROM v_c.term_name OR
     v_listing.district IS DISTINCT FROM v_d.term_name OR
     v_listing.province_normalized IS DISTINCT FROM twuanis_private.normalize_geographic_projection(v_p.term_name) OR
     v_listing.canton_normalized IS DISTINCT FROM twuanis_private.normalize_geographic_projection(v_c.term_name) OR
     v_listing.district_normalized IS DISTINCT FROM twuanis_private.normalize_geographic_projection(v_d.term_name) OR
     v_listing.listing_status IS DISTINCT FROM p_expected_status THEN
    RAISE EXCEPTION 'CG3 final projection/status disagreement' USING ERRCODE = '23514';
  END IF;
  RETURN jsonb_build_object(
    'listing_id', p_listing_id::text, 'listing_status', v_listing.listing_status,
    'province', jsonb_build_object('official_code', p_province_code, 'ontology_id', v_p.id::text),
    'canton', jsonb_build_object('official_code', p_canton_code, 'ontology_id', v_c.id::text),
    'district', CASE WHEN p_district_code IS NULL THEN NULL ELSE
      jsonb_build_object('official_code', p_district_code, 'ontology_id', v_d.id::text) END);
END;
$_$;


