    requires_manual_approval boolean DEFAULT false NOT NULL,
    display_order integer NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT add_on_products_description_en_not_blank CHECK ((length(TRIM(BOTH FROM description_en)) > 0)),
    CONSTRAINT add_on_products_description_es_not_blank CHECK ((length(TRIM(BOTH FROM description_es)) > 0)),
    CONSTRAINT add_on_products_duration_consistency CHECK ((((duration_type = 'days'::text) AND (duration_days IS NOT NULL) AND (duration_days > 0)) OR ((duration_type <> 'days'::text) AND (duration_days IS NULL)))),
    CONSTRAINT add_on_products_duration_type_check CHECK ((duration_type = ANY (ARRAY['days'::text, 'listing_lifetime'::text, 'permanent'::text, 'single_use'::text]))),
    CONSTRAINT add_on_products_maximum_quantity_positive CHECK (((maximum_quantity IS NULL) OR (maximum_quantity > 0))),
    CONSTRAINT add_on_products_name_en_not_blank CHECK ((length(TRIM(BOTH FROM name_en)) > 0)),
    CONSTRAINT add_on_products_name_es_not_blank CHECK ((length(TRIM(BOTH FROM name_es)) > 0)),
    CONSTRAINT add_on_products_price_crc_nonnegative CHECK ((price_crc >= 0)),
    CONSTRAINT add_on_products_price_usd_nonnegative CHECK ((price_usd >= 0)),
    CONSTRAINT add_on_products_product_type_check CHECK ((product_type = ANY (ARRAY['promotion'::text, 'presentation'::text, 'verification'::text, 'publishing_capacity'::text, 'membership'::text]))),
    CONSTRAINT add_on_products_slug_not_blank CHECK ((length(TRIM(BOTH FROM slug)) > 0)),
    CONSTRAINT add_on_products_target_type_check CHECK ((target_type = ANY (ARRAY['listing'::text, 'account'::text])))
);


--
-- Name: bank_transfer_payments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bank_transfer_payments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    purchase_request_id uuid NOT NULL,
    user_id uuid NOT NULL,
    amount numeric NOT NULL,
    currency text NOT NULL,
    bank_name text NOT NULL,
    account_reference text NOT NULL,
    transfer_reference text NOT NULL,
    sender_name text NOT NULL,
    sender_account_last4 text,
    payment_date timestamp with time zone NOT NULL,
    status text DEFAULT 'submitted'::text NOT NULL,
    rejection_reason text,
    internal_notes text,
    reviewed_by uuid,
    reviewed_at timestamp with time zone,
    approved_at timestamp with time zone,
    rejected_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT bank_transfer_account_reference_not_blank CHECK ((length(TRIM(BOTH FROM account_reference)) > 0)),
    CONSTRAINT bank_transfer_amount_positive CHECK ((amount > (0)::numeric)),
    CONSTRAINT bank_transfer_approved_state_valid CHECK (((status <> 'approved'::text) OR (approved_at IS NOT NULL))),
    CONSTRAINT bank_transfer_bank_name_not_blank CHECK ((length(TRIM(BOTH FROM bank_name)) > 0)),
    CONSTRAINT bank_transfer_currency_valid CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT bank_transfer_reference_not_blank CHECK ((length(TRIM(BOTH FROM transfer_reference)) > 0)),
    CONSTRAINT bank_transfer_rejected_state_valid CHECK (((status <> 'rejected'::text) OR ((rejected_at IS NOT NULL) AND (rejection_reason IS NOT NULL) AND (length(TRIM(BOTH FROM rejection_reason)) > 0)))),
    CONSTRAINT bank_transfer_review_state_valid CHECK (((status <> ALL (ARRAY['approved'::text, 'rejected'::text])) OR ((reviewed_by IS NOT NULL) AND (reviewed_at IS NOT NULL)))),
    CONSTRAINT bank_transfer_sender_account_last4_valid CHECK (((sender_account_last4 IS NULL) OR (sender_account_last4 ~ '^[0-9A-Za-z]{4}$'::text))),
    CONSTRAINT bank_transfer_sender_name_not_blank CHECK ((length(TRIM(BOTH FROM sender_name)) > 0)),
    CONSTRAINT bank_transfer_status_valid CHECK ((status = ANY (ARRAY['submitted'::text, 'under_review'::text, 'approved'::text, 'rejected'::text, 'cancelled'::text])))
);


--
-- Name: canonical_operation_receipts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.canonical_operation_receipts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    authority_kind text NOT NULL,
    authority_identity text NOT NULL,
    operation_type text NOT NULL,
    request_id uuid NOT NULL,
    payload_fingerprint text NOT NULL,
    outcome text NOT NULL,
    listing_id uuid,
    result_code text,
    completed_at timestamp with time zone DEFAULT now() NOT NULL,
    result_revision bigint,
    CONSTRAINT canonical_operation_receipts_authority_identity_check CHECK ((((length(authority_identity) >= 1) AND (length(authority_identity) <= 256)) AND ((authority_identity COLLATE "C") ~ '[^[:space:]]'::text))),
    CONSTRAINT canonical_operation_receipts_authority_kind_check CHECK ((authority_kind = ANY (ARRAY['owner'::text, 'trusted'::text, 'system'::text, 'migration'::text]))),
    CONSTRAINT canonical_operation_receipts_operation_type_check CHECK ((operation_type ~ '^[a-z][a-z0-9_]{0,63}$'::text)),
    CONSTRAINT canonical_operation_receipts_outcome_check CHECK ((outcome = ANY (ARRAY['succeeded'::text, 'noop'::text, 'stale'::text, 'conflict'::text, 'rejected'::text]))),
    CONSTRAINT canonical_operation_receipts_payload_fingerprint_check CHECK ((payload_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT canonical_operation_receipts_result_code_check CHECK (((result_code IS NULL) OR ((length(result_code) >= 1) AND (length(result_code) <= 128)))),
    CONSTRAINT canonical_operation_receipts_result_revision_check CHECK ((result_revision >= 0))
);


