--
-- Name: ontology_terms; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ontology_terms (
    id bigint NOT NULL,
    parent_id bigint,
    term_name text NOT NULL,
    term_type text NOT NULL,
    slug text NOT NULL,
    description text,
    created_at timestamp with time zone DEFAULT now(),
    level integer DEFAULT 0,
    official_code text,
    term_name_en text,
    term_name_es text,
    slug_en text,
    slug_es text,
    CONSTRAINT ontology_terms_geography_code_check CHECK (
CASE term_type
    WHEN 'province'::text THEN ((official_code IS NOT NULL) AND (official_code ~ '^[0-9]{1}$'::text))
    WHEN 'canton'::text THEN ((official_code IS NOT NULL) AND (official_code ~ '^[0-9]{3}$'::text))
    WHEN 'district'::text THEN ((official_code IS NOT NULL) AND (official_code ~ '^[0-9]{5}$'::text))
    ELSE true
END),
    CONSTRAINT ontology_terms_geography_level_check CHECK (
CASE term_type
    WHEN 'province'::text THEN ((level IS NOT NULL) AND (level = 1))
    WHEN 'canton'::text THEN ((level IS NOT NULL) AND (level = 2))
    WHEN 'district'::text THEN ((level IS NOT NULL) AND (level = 3))
    ELSE true
END)
);


--
-- Name: canton_graph_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.canton_graph_view AS
 SELECT c.id AS canton_id,
    c.term_name_en AS canton,
    p.term_name_en AS province,
    count(DISTINCT lot.listing_id) AS listing_count
   FROM (((public.ontology_terms c
     JOIN public.ontology_terms p ON ((p.id = c.parent_id)))
     JOIN public.ontology_terms d ON (((d.parent_id = c.id) AND (d.term_type = 'district'::text))))
     LEFT JOIN public.listings_ontology_terms lot ON ((lot.ontology_term_id = d.id)))
  WHERE (c.term_type = 'canton'::text)
  GROUP BY c.id, c.term_name_en, p.term_name_en
  ORDER BY (count(DISTINCT lot.listing_id)) DESC;


