--
-- Name: geography_graph_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.geography_graph_view AS
 SELECT d.id AS district_id,
    d.term_name_en AS district,
    c.term_name_en AS canton,
    p.term_name_en AS province,
    count(DISTINCT lot.listing_id) AS listing_count
   FROM (((public.ontology_terms d
     JOIN public.ontology_terms c ON ((c.id = d.parent_id)))
     JOIN public.ontology_terms p ON ((p.id = c.parent_id)))
     LEFT JOIN public.listings_ontology_terms lot ON ((lot.ontology_term_id = d.id)))
  WHERE (d.term_type = 'district'::text)
  GROUP BY d.id, d.term_name_en, c.term_name_en, p.term_name_en;


--
-- Name: geography_hierarchy_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.geography_hierarchy_view AS
 SELECT p.id AS province_id,
    p.term_name_en AS province,
    c.id AS canton_id,
    c.term_name_en AS canton,
    d.id AS district_id,
    d.term_name_en AS district,
    count(DISTINCT lot.listing_id) AS listing_count
   FROM (((public.ontology_terms p
     JOIN public.ontology_terms c ON (((c.parent_id = p.id) AND (c.term_type = 'canton'::text))))
     JOIN public.ontology_terms d ON (((d.parent_id = c.id) AND (d.term_type = 'district'::text))))
     LEFT JOIN public.listings_ontology_terms lot ON ((lot.ontology_term_id = d.id)))
  WHERE (p.term_type = 'province'::text)
  GROUP BY p.id, p.term_name_en, c.id, c.term_name_en, d.id, d.term_name_en
  ORDER BY p.term_name_en, c.term_name_en, d.term_name_en;


