--
-- Name: listing_analytics_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.listing_analytics_summary AS
 SELECT l.id AS listing_id,
    l.owner_id,
    l.listing_status,
    l.published_at,
    l.updated_at,
    (GREATEST((0)::numeric, floor((EXTRACT(epoch FROM (now() - COALESCE(l.published_at, l.created_at, now()))) / (86400)::numeric))))::integer AS days_since_published,
    (GREATEST((0)::numeric, floor((EXTRACT(epoch FROM (now() - COALESCE(l.updated_at, l.created_at, now()))) / (86400)::numeric))))::integer AS days_since_last_update,
    count(e.id) FILTER (WHERE (e.event_type = 'view'::text)) AS view_count,
    count(e.id) FILTER (WHERE (e.event_type = 'share'::text)) AS share_count,
    count(e.id) FILTER (WHERE (e.event_type = 'whatsapp_click'::text)) AS whatsapp_click_count,
    count(e.id) FILTER (WHERE (e.event_type = 'email_inquiry'::text)) AS email_inquiry_count,
    ( SELECT count(*) AS count
           FROM public.listing_favorites f
          WHERE (f.listing_id = l.id)) AS favorite_count
   FROM (public.listings l
     LEFT JOIN public.listing_events e ON ((e.listing_id = l.id)))
  GROUP BY l.id, l.owner_id, l.listing_status, l.published_at, l.updated_at, l.created_at;


