    CONSTRAINT listing_entitlements_expiration_order CHECK (((expires_at IS NULL) OR (starts_at IS NULL) OR (expires_at > starts_at))),
    CONSTRAINT listing_entitlements_purchase_relationship CHECK ((((source_type = 'purchase'::text) AND (purchase_request_id IS NOT NULL)) OR ((source_type <> 'purchase'::text) AND (purchase_request_id IS NULL)))),
    CONSTRAINT listing_entitlements_revocation_consistency CHECK ((((status = 'revoked'::text) AND (revoked_at IS NOT NULL)) OR ((status <> 'revoked'::text) AND (revoked_at IS NULL) AND (revoked_by IS NULL) AND (revocation_reason IS NULL)))),
    CONSTRAINT listing_entitlements_source_type_check CHECK ((source_type = ANY (ARRAY['package_credit'::text, 'purchase'::text, 'manual'::text, 'system'::text]))),
    CONSTRAINT listing_entitlements_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'scheduled'::text, 'active'::text, 'expired'::text, 'revoked'::text, 'cancelled'::text])))
);


