--
-- Name: listing_fact_evidence; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.listing_fact_evidence (
    listing_id uuid NOT NULL,
    dimension text NOT NULL,
    kind text NOT NULL,
    exact_value numeric,
    category_term_id bigint,
    range_lower numeric,
    range_upper numeric,
    lower_inclusive boolean,
    upper_inclusive boolean,
    evidence_source text NOT NULL,
    evidence_reference text,
    observed_at timestamp with time zone,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT listing_fact_evidence_check CHECK ((((kind = 'exact'::text) AND (exact_value IS NOT NULL) AND (category_term_id IS NULL) AND (range_lower IS NULL) AND (range_upper IS NULL) AND (lower_inclusive IS NULL) AND (upper_inclusive IS NULL)) OR ((kind = 'category'::text) AND (exact_value IS NULL) AND (category_term_id IS NOT NULL) AND (range_lower IS NULL) AND (range_upper IS NULL) AND (lower_inclusive IS NULL) AND (upper_inclusive IS NULL) AND (dimension <> 'distance_to_paved_road'::text)) OR ((kind = 'range'::text) AND (exact_value IS NULL) AND (category_term_id IS NULL) AND ((range_lower IS NOT NULL) OR (range_upper IS NOT NULL)) AND (lower_inclusive IS NOT NULL) AND (upper_inclusive IS NOT NULL) AND ((range_lower IS NOT NULL) OR (NOT lower_inclusive)) AND ((range_upper IS NOT NULL) OR (NOT upper_inclusive)) AND (NOT isempty(numrange(range_lower, range_upper, (
CASE
    WHEN lower_inclusive THEN '['::text
    ELSE '('::text
END ||
CASE
    WHEN upper_inclusive THEN ']'::text
    ELSE ')'::text
END))))))),
    CONSTRAINT listing_fact_evidence_check1 CHECK ((twuanis_canonical_private.finite_numeric(exact_value) AND twuanis_canonical_private.finite_numeric(range_lower) AND twuanis_canonical_private.finite_numeric(range_upper))),
    CONSTRAINT listing_fact_evidence_check2 CHECK ((((exact_value IS NULL) OR (exact_value >= (0)::numeric)) AND ((range_lower IS NULL) OR (range_lower >= (0)::numeric)) AND ((range_upper IS NULL) OR (range_upper >= (0)::numeric)))),
    CONSTRAINT listing_fact_evidence_check3 CHECK (((dimension <> 'bathrooms'::text) OR (kind <> 'exact'::text) OR (exact_value > (0)::numeric))),
    CONSTRAINT listing_fact_evidence_check4 CHECK (((dimension <> ALL (ARRAY['bedrooms'::text, 'parking'::text, 'year_built'::text])) OR (((exact_value IS NULL) OR (exact_value = trunc(exact_value))) AND ((range_lower IS NULL) OR (range_lower = trunc(range_lower))) AND ((range_upper IS NULL) OR (range_upper = trunc(range_upper)))))),
    CONSTRAINT listing_fact_evidence_check5 CHECK (((dimension <> 'year_built'::text) OR (((exact_value IS NULL) OR ((exact_value >= (1)::numeric) AND (exact_value <= (9999)::numeric))) AND ((range_lower IS NULL) OR ((range_lower >= (1)::numeric) AND (range_lower <= (9999)::numeric))) AND ((range_upper IS NULL) OR ((range_upper >= (1)::numeric) AND (range_upper <= (9999)::numeric)))))),
    CONSTRAINT listing_fact_evidence_dimension_check CHECK ((dimension = ANY (ARRAY['bedrooms'::text, 'bathrooms'::text, 'parking'::text, 'year_built'::text, 'distance_to_paved_road'::text]))),
    CONSTRAINT listing_fact_evidence_evidence_reference_check CHECK (((evidence_reference IS NULL) OR ((length(evidence_reference) >= 1) AND (length(evidence_reference) <= 1024)))),
    CONSTRAINT listing_fact_evidence_evidence_source_check CHECK ((evidence_source = ANY (ARRAY['owner'::text, 'source'::text, 'manual'::text, 'migration'::text]))),
    CONSTRAINT listing_fact_evidence_kind_check CHECK ((kind = ANY (ARRAY['exact'::text, 'category'::text, 'range'::text])))
);


--
-- Name: listing_graph_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.listing_graph_view AS
 SELECT l.id,
    l.title,
    l.price_millions,
    l.province_normalized,
    l.canton_normalized,
    l.district_normalized,
    max(
        CASE
            WHEN (o.term_type = 'property_type'::text) THEN o.term_name_en
            ELSE NULL::text
        END) AS property_type,
    max(
        CASE
            WHEN (o.term_type = 'bedrooms'::text) THEN o.term_name_en
            ELSE NULL::text
        END) AS bedrooms,
    max(
        CASE
            WHEN (o.term_type = 'bathrooms'::text) THEN o.term_name_en
            ELSE NULL::text
        END) AS bathrooms,
    max(
        CASE
            WHEN (o.term_type = 'parking'::text) THEN o.term_name_en
            ELSE NULL::text
        END) AS parking,
    max(
        CASE
            WHEN (o.term_type = 'year_built'::text) THEN o.term_name_en
            ELSE NULL::text
        END) AS year_built,
    max(
        CASE
            WHEN (o.term_type = 'environment'::text) THEN o.term_name_en
            ELSE NULL::text
        END) AS environment,
    max(
        CASE
            WHEN (o.term_type = 'accessibility'::text) THEN o.term_name_en
            ELSE NULL::text
        END) AS accessibility,
    max(
        CASE
            WHEN (o.term_type = 'legal_status'::text) THEN o.term_name_en
            ELSE NULL::text
        END) AS legal_status,
    string_agg(
        CASE
            WHEN (o.term_type = 'terrain'::text) THEN o.term_name_en
            ELSE NULL::text
        END, ', '::text) FILTER (WHERE (o.term_type = 'terrain'::text)) AS terrain
   FROM ((public.listings l
     LEFT JOIN public.listings_ontology_terms lot ON ((lot.listing_id = l.id)))
     LEFT JOIN public.ontology_terms o ON ((o.id = lot.ontology_term_id)))
  GROUP BY l.id, l.title, l.price_millions, l.province_normalized, l.canton_normalized, l.district_normalized;


--
-- Name: listing_lifecycle_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.listing_lifecycle_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    listing_id uuid NOT NULL,
    operation_id uuid NOT NULL,
    listing_revision bigint NOT NULL,
    event_type text NOT NULL,
    previous_state text,
    resulting_state text NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    actor_kind text NOT NULL,
    actor_identity text NOT NULL,
    reason text,
    publication_expires_at timestamp with time zone,
    CONSTRAINT listing_lifecycle_events_actor_identity_check CHECK ((((length(actor_identity) >= 1) AND (length(actor_identity) <= 256)) AND ((actor_identity COLLATE "C") ~ '[^[:space:]]'::text))),
    CONSTRAINT listing_lifecycle_events_actor_kind_check CHECK ((actor_kind = ANY (ARRAY['owner'::text, 'trusted'::text, 'system'::text, 'migration'::text]))),
    CONSTRAINT listing_lifecycle_events_check CHECK ((((event_type = 'create'::text) AND (previous_state IS NULL) AND (resulting_state = 'draft'::text)) OR ((previous_state IS NOT NULL) AND (((event_type = 'publish'::text) AND (previous_state = 'draft'::text) AND (resulting_state = 'active'::text)) OR ((event_type = 'renew'::text) AND (previous_state = ANY (ARRAY['active'::text, 'expired'::text])) AND (resulting_state = 'active'::text)) OR ((event_type = 'unpublish'::text) AND (previous_state = 'active'::text) AND (resulting_state = 'draft'::text)) OR ((event_type = 'expire'::text) AND (previous_state = 'active'::text) AND (resulting_state = 'expired'::text)) OR ((event_type = 'archive'::text) AND (previous_state = ANY (ARRAY['draft'::text, 'active'::text, 'expired'::text])) AND (resulting_state = 'archived'::text)) OR ((event_type = 'restore'::text) AND (previous_state = ANY (ARRAY['archived'::text, 'deleted'::text])) AND (resulting_state = 'draft'::text)) OR ((event_type = 'delete'::text) AND (previous_state = ANY (ARRAY['draft'::text, 'active'::text, 'expired'::text, 'archived'::text])) AND (resulting_state = 'deleted'::text)))))),
    CONSTRAINT listing_lifecycle_events_event_type_check CHECK ((event_type = ANY (ARRAY['create'::text, 'publish'::text, 'renew'::text, 'unpublish'::text, 'expire'::text, 'archive'::text, 'restore'::text, 'delete'::text]))),
    CONSTRAINT listing_lifecycle_events_listing_revision_check CHECK ((listing_revision >= 0)),
    CONSTRAINT listing_lifecycle_events_previous_state_check CHECK ((previous_state = ANY (ARRAY['draft'::text, 'active'::text, 'expired'::text, 'archived'::text, 'deleted'::text]))),
    CONSTRAINT listing_lifecycle_events_reason_check CHECK (((reason IS NULL) OR ((length(reason) >= 1) AND (length(reason) <= 1024)))),
    CONSTRAINT listing_lifecycle_events_resulting_state_check CHECK ((resulting_state = ANY (ARRAY['draft'::text, 'active'::text, 'expired'::text, 'archived'::text, 'deleted'::text])))
);


