);


--
-- Name: listing_monetary_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.listing_monetary_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    listing_id uuid NOT NULL,
    operation_id uuid NOT NULL,
    listing_revision bigint NOT NULL,
    transaction_type text NOT NULL,
    event_kind text NOT NULL,
    old_amount numeric,
    old_currency text,
    new_amount numeric,
    new_currency text,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    source_observed_at timestamp with time zone,
    source_observation_id uuid,
    actor_kind text NOT NULL,
    actor_identity text NOT NULL,
    reason text,
    CONSTRAINT listing_monetary_events_actor_identity_check CHECK ((((length(actor_identity) >= 1) AND (length(actor_identity) <= 256)) AND ((actor_identity COLLATE "C") ~ '[^[:space:]]'::text))),
    CONSTRAINT listing_monetary_events_actor_kind_check CHECK ((actor_kind = ANY (ARRAY['owner'::text, 'trusted'::text, 'system'::text, 'migration'::text]))),
    CONSTRAINT listing_monetary_events_check CHECK ((((old_amount IS NULL) AND (old_currency IS NULL)) OR ((old_amount IS NOT NULL) AND (old_currency IS NOT NULL) AND (old_amount > (0)::numeric) AND (old_currency = ANY (ARRAY['CRC'::text, 'USD'::text]))))),
    CONSTRAINT listing_monetary_events_check1 CHECK ((((new_amount IS NULL) AND (new_currency IS NULL)) OR ((new_amount IS NOT NULL) AND (new_currency IS NOT NULL) AND (new_amount > (0)::numeric) AND (new_currency = ANY (ARRAY['CRC'::text, 'USD'::text]))))),
    CONSTRAINT listing_monetary_events_check2 CHECK ((twuanis_canonical_private.finite_numeric(old_amount) AND twuanis_canonical_private.finite_numeric(new_amount))),
    CONSTRAINT listing_monetary_events_check3 CHECK ((((event_kind = ANY (ARRAY['initial_observation'::text, 'migration_baseline'::text])) AND (old_amount IS NULL) AND (new_amount IS NOT NULL)) OR ((event_kind = 'change'::text) AND (old_amount IS NOT NULL) AND (new_amount IS NOT NULL) AND ((old_amount IS DISTINCT FROM new_amount) OR (old_currency IS DISTINCT FROM new_currency))) OR ((event_kind = 'draft_removal'::text) AND (old_amount IS NOT NULL) AND (new_amount IS NULL)))),
    CONSTRAINT listing_monetary_events_event_kind_check CHECK ((event_kind = ANY (ARRAY['initial_observation'::text, 'change'::text, 'draft_removal'::text, 'migration_baseline'::text]))),
    CONSTRAINT listing_monetary_events_listing_revision_check CHECK ((listing_revision >= 0)),
    CONSTRAINT listing_monetary_events_reason_check CHECK (((reason IS NULL) OR ((length(reason) >= 1) AND (length(reason) <= 1024)))),
    CONSTRAINT listing_monetary_events_transaction_type_check CHECK ((transaction_type = ANY (ARRAY['sale'::text, 'rent'::text])))
);


