CREATE TABLE public.listing_semantic_selections (
    listing_id uuid NOT NULL,
    dimension text NOT NULL,
    ontology_term_id bigint NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT listing_semantic_selections_dimension_check CHECK ((dimension = ANY (ARRAY['property_type'::text, 'utility'::text, 'environment'::text, 'terrain'::text, 'accessibility'::text, 'legal_status'::text])))
);


--
-- Name: listing_source_observations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.listing_source_observations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    source_name text NOT NULL,
    source_listing_id text NOT NULL,
    source_observation_id text NOT NULL,
    listing_id uuid,
    source_observed_at timestamp with time zone,
    processed_at timestamp with time zone DEFAULT now() NOT NULL,
    outcome text NOT NULL,
    payload_fingerprint text NOT NULL,
    evidence_reference text,
    result_revision bigint,
    CONSTRAINT listing_source_observations_check CHECK (((outcome <> ALL (ARRAY['accepted'::text, 'stale'::text, 'conflict'::text])) OR (listing_id IS NOT NULL))),
    CONSTRAINT listing_source_observations_evidence_reference_check CHECK (((evidence_reference IS NULL) OR ((length(evidence_reference) >= 1) AND (length(evidence_reference) <= 1024)))),
    CONSTRAINT listing_source_observations_outcome_check CHECK ((outcome = ANY (ARRAY['accepted'::text, 'stale'::text, 'conflict'::text, 'rejected'::text]))),
    CONSTRAINT listing_source_observations_payload_fingerprint_check CHECK ((payload_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT listing_source_observations_result_revision_check CHECK ((result_revision >= 0)),
    CONSTRAINT listing_source_observations_source_listing_id_check CHECK ((((length(source_listing_id) >= 1) AND (length(source_listing_id) <= 256)) AND ((source_listing_id COLLATE "C") ~ '[^[:space:]]'::text))),
    CONSTRAINT listing_source_observations_source_name_check CHECK ((((length(source_name) >= 1) AND (length(source_name) <= 128)) AND ((source_name COLLATE "C") ~ '[^[:space:]]'::text))),
    CONSTRAINT listing_source_observations_source_observation_id_check CHECK ((((length(source_observation_id) >= 1) AND (length(source_observation_id) <= 256)) AND ((source_observation_id COLLATE "C") ~ '[^[:space:]]'::text)))
);


