--
-- Name: ontology_graph_cache; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.ontology_graph_cache AS
 SELECT r.source_term_id,
    r.target_term_id,
    r.relationship_type,
    source.term_name AS source_name,
    source.term_type AS source_type,
    source.slug AS source_slug,
    target.term_name AS target_name,
    target.term_type AS target_type,
    target.slug AS target_slug
   FROM ((public.ontology_relationships r
     JOIN public.ontology_terms source ON ((source.id = r.source_term_id)))
     JOIN public.ontology_terms target ON ((target.id = r.target_term_id)))
  WITH NO DATA;


