CREATE VIEW public.ontology_hierarchy AS
 SELECT child.id,
    child.parent_id,
    parent.term_name AS parent_name,
    child.term_name,
    child.term_type
   FROM (public.ontology_terms child
     LEFT JOIN public.ontology_terms parent ON ((parent.id = child.parent_id)));


