    CONSTRAINT packages_billing_interval_check CHECK ((billing_interval = ANY (ARRAY['free'::text, 'monthly'::text, 'annual'::text]))),
    CONSTRAINT packages_display_order_check CHECK ((display_order >= 1)),
    CONSTRAINT packages_free_price_consistency CHECK ((((billing_interval = 'free'::text) AND (price_usd = 0) AND (price_crc = 0)) OR (billing_interval <> 'free'::text))),
    CONSTRAINT packages_hierarchy_level_check CHECK ((hierarchy_level >= 1)),
    CONSTRAINT packages_parent_not_self CHECK (((parent_package_id IS NULL) OR (parent_package_id <> id))),
    CONSTRAINT packages_price_crc_check CHECK ((price_crc >= 0)),
    CONSTRAINT packages_price_usd_check CHECK ((price_usd >= 0))
);


--
-- Name: package_composition_validation; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.package_composition_validation AS
 WITH expected_engines AS (
         SELECT expected.package_slug,
            expected.engine_slug
           FROM ( VALUES ('market-explorer'::text,'market-explorer'::text), ('market-valuation-pricing'::text,'market-explorer'::text), ('market-valuation-pricing'::text,'valuation'::text), ('market-valuation-pricing'::text,'pricing-strategy'::text), ('market-valuation-pricing'::text,'property-matching'::text), ('market-comparison-frequency'::text,'market-explorer'::text), ('market-comparison-frequency'::text,'valuation'::text), ('market-comparison-frequency'::text,'pricing-strategy'::text), ('market-comparison-frequency'::text,'property-matching'::text), ('market-comparison-frequency'::text,'market-comparison'::text), ('market-comparison-frequency'::text,'market-frequency'::text), ('market-pricing-intelligence'::text,'market-explorer'::text), ('market-pricing-intelligence'::text,'valuation'::text), ('market-pricing-intelligence'::text,'pricing-strategy'::text), ('market-pricing-intelligence'::text,'property-matching'::text), ('market-pricing-intelligence'::text,'market-comparison'::text), ('market-pricing-intelligence'::text,'market-frequency'::text), ('market-pricing-intelligence'::text,'price-per-square-meter-intelligence'::text)) expected(package_slug, engine_slug)
        ), actual_engines AS (
         SELECT p.slug AS package_slug,
            e.slug AS engine_slug
           FROM ((public.package_engines pe
             JOIN public.packages p ON ((p.id = pe.package_id)))
             JOIN public.engines e ON ((e.id = pe.engine_id)))
        ), missing_engines AS (
         SELECT expected.package_slug,
            expected.engine_slug,
            'missing'::text AS validation_status
           FROM (expected_engines expected
             LEFT JOIN actual_engines actual ON (((actual.package_slug = expected.package_slug) AND (actual.engine_slug = expected.engine_slug))))
          WHERE (actual.engine_slug IS NULL)
        ), unexpected_engines AS (
         SELECT actual.package_slug,
            actual.engine_slug,
            'unexpected'::text AS validation_status
           FROM (actual_engines actual
             LEFT JOIN expected_engines expected ON (((expected.package_slug = actual.package_slug) AND (expected.engine_slug = actual.engine_slug))))
          WHERE (expected.engine_slug IS NULL)
        )
 SELECT missing_engines.package_slug,
    missing_engines.engine_slug,
    missing_engines.validation_status
   FROM missing_engines
UNION ALL
 SELECT unexpected_engines.package_slug,
    unexpected_engines.engine_slug,
    unexpected_engines.validation_status
   FROM unexpected_engines;


