    CONSTRAINT package_entitlements_single_value CHECK ((((boolean_value IS NOT NULL) AND (integer_value IS NULL) AND (text_value IS NULL)) OR ((boolean_value IS NULL) AND (integer_value IS NOT NULL) AND (text_value IS NULL)) OR ((boolean_value IS NULL) AND (integer_value IS NULL) AND (text_value IS NOT NULL))))
);


--
-- Name: package_entitlement_validation; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.package_entitlement_validation AS
 WITH expected_entitlements AS (
         SELECT t.package_slug,
            t.entitlement_slug
           FROM ( VALUES ('market-explorer'::text,'save-favorites'::text), ('market-explorer'::text,'save-searches'::text), ('market-explorer'::text,'email-alerts'::text), ('market-valuation-pricing'::text,'save-favorites'::text), ('market-valuation-pricing'::text,'save-searches'::text), ('market-valuation-pricing'::text,'email-alerts'::text), ('market-valuation-pricing'::text,'save-valuations'::text), ('market-valuation-pricing'::text,'save-pricing-strategies'::text), ('market-valuation-pricing'::text,'save-property-matches'::text), ('market-valuation-pricing'::text,'pdf-export'::text), ('market-comparison-frequency'::text,'save-favorites'::text), ('market-comparison-frequency'::text,'save-searches'::text), ('market-comparison-frequency'::text,'email-alerts'::text), ('market-comparison-frequency'::text,'save-valuations'::text), ('market-comparison-frequency'::text,'save-pricing-strategies'::text), ('market-comparison-frequency'::text,'save-property-matches'::text), ('market-comparison-frequency'::text,'pdf-export'::text), ('market-comparison-frequency'::text,'save-market-comparisons'::text), ('market-comparison-frequency'::text,'save-frequency-analyses'::text), ('market-comparison-frequency'::text,'csv-export'::text), ('market-pricing-intelligence'::text,'save-favorites'::text), ('market-pricing-intelligence'::text,'save-searches'::text), ('market-pricing-intelligence'::text,'email-alerts'::text), ('market-pricing-intelligence'::text,'save-valuations'::text), ('market-pricing-intelligence'::text,'save-pricing-strategies'::text), ('market-pricing-intelligence'::text,'save-property-matches'::text), ('market-pricing-intelligence'::text,'pdf-export'::text), ('market-pricing-intelligence'::text,'save-market-comparisons'::text), ('market-pricing-intelligence'::text,'save-frequency-analyses'::text), ('market-pricing-intelligence'::text,'csv-export'::text), ('market-pricing-intelligence'::text,'save-price-m2-analyses'::text), ('market-pricing-intelligence'::text,'api-access'::text), ('market-pricing-intelligence'::text,'team-access'::text)) t(package_slug, entitlement_slug)
        ), actual_entitlements AS (
         SELECT p.slug AS package_slug,
            e.slug AS entitlement_slug,
            pe.boolean_value,
            pe.integer_value,
            pe.text_value,
            e.value_type
           FROM ((public.package_entitlements pe
             JOIN public.packages p ON ((p.id = pe.package_id)))
             JOIN public.entitlements e ON ((e.id = pe.entitlement_id)))
        ), missing AS (
         SELECT expected.package_slug,
            expected.entitlement_slug,
            'missing'::text AS validation_status
           FROM (expected_entitlements expected
             LEFT JOIN actual_entitlements actual ON (((actual.package_slug = expected.package_slug) AND (actual.entitlement_slug = expected.entitlement_slug))))
          WHERE (actual.entitlement_slug IS NULL)
        ), unexpected AS (
         SELECT actual.package_slug,
            actual.entitlement_slug,
            'unexpected'::text AS validation_status
           FROM (actual_entitlements actual
             LEFT JOIN expected_entitlements expected ON (((expected.package_slug = actual.package_slug) AND (expected.entitlement_slug = actual.entitlement_slug))))
          WHERE (expected.entitlement_slug IS NULL)
        ), invalid_value AS (
         SELECT actual_entitlements.package_slug,
            actual_entitlements.entitlement_slug,
            'invalid_value'::text AS validation_status
           FROM actual_entitlements
          WHERE (((actual_entitlements.value_type = 'boolean'::text) AND (actual_entitlements.boolean_value IS NULL)) OR ((actual_entitlements.value_type = 'integer'::text) AND (actual_entitlements.integer_value IS NULL)) OR ((actual_entitlements.value_type = 'text'::text) AND (actual_entitlements.text_value IS NULL)))
        )
 SELECT missing.package_slug,
    missing.entitlement_slug,
    missing.validation_status
   FROM missing
UNION ALL
 SELECT unexpected.package_slug,
    unexpected.entitlement_slug,
    unexpected.validation_status
   FROM unexpected
UNION ALL
 SELECT invalid_value.package_slug,
    invalid_value.entitlement_slug,
    invalid_value.validation_status
   FROM invalid_value;


