--
-- Name: purchase_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.purchase_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    owner_id uuid NOT NULL,
    product_type text NOT NULL,
    package_id uuid,
    add_on_product_id uuid,
    target_type text NOT NULL,
    listing_id uuid,
    quantity integer DEFAULT 1 NOT NULL,
    unit_amount numeric(14,2) NOT NULL,
    amount numeric(14,2) NOT NULL,
    currency text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    expires_at timestamp with time zone,
    approved_at timestamp with time zone,
    approved_by uuid,
    rejected_at timestamp with time zone,
    rejected_by uuid,
    rejection_reason text,
    cancelled_at timestamp with time zone,
    cancelled_by uuid,
    cancellation_reason text,
    expired_at timestamp with time zone,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT purchase_requests_amount_nonnegative CHECK ((amount >= (0)::numeric)),
    CONSTRAINT purchase_requests_approved_state_valid CHECK ((((status = 'approved'::text) AND (approved_at IS NOT NULL)) OR ((status <> 'approved'::text) AND (approved_at IS NULL) AND (approved_by IS NULL)))),
    CONSTRAINT purchase_requests_cancelled_state_valid CHECK ((((status = 'cancelled'::text) AND (cancelled_at IS NOT NULL) AND (cancellation_reason IS NOT NULL) AND (length(TRIM(BOTH FROM cancellation_reason)) > 0)) OR ((status <> 'cancelled'::text) AND (cancelled_at IS NULL) AND (cancelled_by IS NULL) AND (cancellation_reason IS NULL)))),
    CONSTRAINT purchase_requests_currency_valid CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT purchase_requests_expiration_deadline_valid CHECK (((expires_at IS NULL) OR (expires_at > created_at))),
    CONSTRAINT purchase_requests_expired_state_valid CHECK ((((status = 'expired'::text) AND (expired_at IS NOT NULL)) OR ((status <> 'expired'::text) AND (expired_at IS NULL)))),
    CONSTRAINT purchase_requests_product_relationship CHECK ((((product_type = 'package'::text) AND (package_id IS NOT NULL) AND (add_on_product_id IS NULL)) OR ((product_type = 'add_on'::text) AND (add_on_product_id IS NOT NULL) AND (package_id IS NULL)))),
    CONSTRAINT purchase_requests_product_type_check CHECK ((product_type = ANY (ARRAY['package'::text, 'add_on'::text]))),
    CONSTRAINT purchase_requests_quantity_positive CHECK ((quantity > 0)),
    CONSTRAINT purchase_requests_rejected_state_valid CHECK ((((status = 'rejected'::text) AND (rejected_at IS NOT NULL) AND (rejection_reason IS NOT NULL) AND (length(TRIM(BOTH FROM rejection_reason)) > 0)) OR ((status <> 'rejected'::text) AND (rejected_at IS NULL) AND (rejected_by IS NULL) AND (rejection_reason IS NULL)))),
    CONSTRAINT purchase_requests_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text, 'expired'::text, 'cancelled'::text]))),
    CONSTRAINT purchase_requests_target_relationship CHECK ((((target_type = 'account'::text) AND (listing_id IS NULL)) OR ((target_type = 'listing'::text) AND (listing_id IS NOT NULL)))),
    CONSTRAINT purchase_requests_target_type_check CHECK ((target_type = ANY (ARRAY['account'::text, 'listing'::text]))),
    CONSTRAINT purchase_requests_unit_amount_nonnegative CHECK ((unit_amount >= (0)::numeric))
);


