--
-- Name: sinpe_payments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sinpe_payments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    subscription_id uuid,
    amount numeric(12,2) NOT NULL,
    currency text NOT NULL,
    sinpe_reference text NOT NULL,
    sender_name text NOT NULL,
    sender_phone text,
    payment_date timestamp with time zone,
    receipt_storage_path text,
    status text DEFAULT 'submitted'::text NOT NULL,
    rejection_reason text,
    internal_notes text,
    reviewed_by uuid,
    reviewed_at timestamp with time zone,
    approved_at timestamp with time zone,
    rejected_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    purchase_request_id uuid,
    canonical_order_id uuid,
    submission_request_id uuid,
    receiving_account_id uuid,
    submission_evidence jsonb,
    CONSTRAINT sinpe_canonical_submission_shape CHECK (((canonical_order_id IS NULL) OR ((submission_request_id IS NOT NULL) AND (receiving_account_id IS NOT NULL) AND (submission_evidence IS NOT NULL) AND (jsonb_typeof(submission_evidence) = 'object'::text) AND (octet_length((submission_evidence)::text) <= 8000) AND (created_at IS NOT NULL)))),
    CONSTRAINT sinpe_payment_date_authority CHECK ((((canonical_order_id IS NULL) AND (payment_date IS NOT NULL)) OR ((canonical_order_id IS NOT NULL) AND (payment_date IS NULL)))),
    CONSTRAINT sinpe_payments_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT sinpe_payments_approved_at_valid CHECK (((status <> 'approved'::text) OR (approved_at IS NOT NULL))),
    CONSTRAINT sinpe_payments_commercial_relationship CHECK ((((canonical_order_id IS NULL) AND ((purchase_request_id IS NOT NULL) OR (subscription_id IS NOT NULL))) OR ((canonical_order_id IS NOT NULL) AND (purchase_request_id IS NULL) AND (subscription_id IS NULL)))),
    CONSTRAINT sinpe_payments_currency_check CHECK ((currency = ANY (ARRAY['CRC'::text, 'USD'::text]))),
    CONSTRAINT sinpe_payments_reference_not_blank CHECK ((length(TRIM(BOTH FROM sinpe_reference)) > 0)),
    CONSTRAINT sinpe_payments_rejected_at_valid CHECK (((status <> 'rejected'::text) OR ((rejected_at IS NOT NULL) AND (rejection_reason IS NOT NULL) AND (length(TRIM(BOTH FROM rejection_reason)) > 0)))),
    CONSTRAINT sinpe_payments_review_status_valid CHECK (((status <> ALL (ARRAY['approved'::text, 'rejected'::text])) OR ((reviewed_by IS NOT NULL) AND (reviewed_at IS NOT NULL)))),
    CONSTRAINT sinpe_payments_sender_name_not_blank CHECK ((length(TRIM(BOTH FROM sender_name)) > 0)),
    CONSTRAINT sinpe_payments_status_check CHECK ((status = ANY (ARRAY['submitted'::text, 'under_review'::text, 'approved'::text, 'rejected'::text, 'cancelled'::text])))
);


--
-- Name: source_identity_conflicts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.source_identity_conflicts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    listing_id uuid NOT NULL,
    observation_id uuid NOT NULL,
    source_name text NOT NULL,
    source_listing_id text NOT NULL,
    existing_transaction_type text NOT NULL,
    observed_transaction_type text NOT NULL,
    existing_province_code text NOT NULL,
    existing_canton_code text NOT NULL,
    observed_province_code text NOT NULL,
    observed_canton_code text NOT NULL,
    conflict_type text NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    resolution_status text DEFAULT 'open'::text NOT NULL,
    resolution_reference text,
    resolved_at timestamp with time zone,
    CONSTRAINT source_identity_conflicts_check CHECK ((("left"(existing_canton_code, 1) = existing_province_code) AND ("left"(observed_canton_code, 1) = observed_province_code))),
    CONSTRAINT source_identity_conflicts_check1 CHECK (((conflict_type = ANY (ARRAY['transaction'::text, 'transaction_and_geography'::text])) = (existing_transaction_type <> observed_transaction_type))),
    CONSTRAINT source_identity_conflicts_check2 CHECK (((conflict_type = ANY (ARRAY['geography'::text, 'transaction_and_geography'::text])) = ((existing_province_code <> observed_province_code) OR (existing_canton_code <> observed_canton_code)))),
    CONSTRAINT source_identity_conflicts_check3 CHECK ((((resolution_status = 'open'::text) AND (resolution_reference IS NULL) AND (resolved_at IS NULL)) OR ((resolution_status = ANY (ARRAY['resolved'::text, 'dismissed'::text])) AND (resolution_reference IS NOT NULL) AND (resolved_at IS NOT NULL)))),
    CONSTRAINT source_identity_conflicts_conflict_type_check CHECK ((conflict_type = ANY (ARRAY['transaction'::text, 'geography'::text, 'transaction_and_geography'::text]))),
    CONSTRAINT source_identity_conflicts_existing_canton_code_check CHECK ((existing_canton_code ~ '^[0-9]{3}$'::text)),
    CONSTRAINT source_identity_conflicts_existing_province_code_check CHECK ((existing_province_code ~ '^[0-9]$'::text)),
    CONSTRAINT source_identity_conflicts_existing_transaction_type_check CHECK ((existing_transaction_type = ANY (ARRAY['sale'::text, 'rent'::text]))),
    CONSTRAINT source_identity_conflicts_observed_canton_code_check CHECK ((observed_canton_code ~ '^[0-9]{3}$'::text)),
    CONSTRAINT source_identity_conflicts_observed_province_code_check CHECK ((observed_province_code ~ '^[0-9]$'::text)),
    CONSTRAINT source_identity_conflicts_observed_transaction_type_check CHECK ((observed_transaction_type = ANY (ARRAY['sale'::text, 'rent'::text]))),
    CONSTRAINT source_identity_conflicts_resolution_reference_check CHECK (((resolution_reference IS NULL) OR (((length(resolution_reference) >= 1) AND (length(resolution_reference) <= 1024)) AND ((resolution_reference COLLATE "C") ~ '[^[:space:]]'::text)))),
    CONSTRAINT source_identity_conflicts_resolution_status_check CHECK ((resolution_status = ANY (ARRAY['open'::text, 'resolved'::text, 'dismissed'::text])))
);


