);


--
-- Name: addon_configurations; Type: TABLE; Schema: twuanis_canonical_private; Owner: -
--

CREATE TABLE twuanis_canonical_private.addon_configurations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    product_id text NOT NULL,
    version bigint NOT NULL,
    duration_days integer,
    behavior_version integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    placement_market text,
    calendar_months integer,
    promotional_usd numeric(14,2),
    promotional_until timestamp with time zone,
    CONSTRAINT addon_configurations_behavior_version_check CHECK ((behavior_version = 1)),
    CONSTRAINT addon_configurations_calendar_months_check CHECK ((calendar_months = 1)),
    CONSTRAINT addon_configurations_duration_days_check CHECK (((duration_days >= 1) AND (duration_days <= 3650))),
    CONSTRAINT addon_configurations_placement_market_check CHECK ((placement_market = ANY (ARRAY['sale'::text, 'rent'::text]))),
    CONSTRAINT addon_configurations_promotional_usd_check CHECK ((promotional_usd > (0)::numeric)),
    CONSTRAINT addon_configurations_version_check CHECK ((version > 0)),
    CONSTRAINT advertising_market_version_scope CHECK (
CASE
    WHEN ((product_id = 'addon-homepage-exposure'::text) AND (version >= 3)) THEN (NOT (placement_market IS DISTINCT FROM 'sale'::text))
    WHEN ((product_id = 'addon-featured-listing'::text) AND (version >= 2)) THEN (NOT (placement_market IS DISTINCT FROM 'sale'::text))
    WHEN (product_id = ANY (ARRAY['addon-homepage-exposure-rent'::text, 'addon-featured-listing-rent'::text])) THEN (NOT (placement_market IS DISTINCT FROM 'rent'::text))
    ELSE true
END)
);


