    CONSTRAINT addon_standard_prices_check CHECK (((amount > (0)::numeric) AND (amount < ('1000000000000'::bigint)::numeric) AND (scale(amount) <= 2) AND ((currency <> 'CRC'::text) OR (amount = trunc(amount))))),
    CONSTRAINT addon_standard_prices_currency_check CHECK ((currency = ANY (ARRAY['USD'::text, 'CRC'::text])))
);


