);


--
-- Name: customer_email_sources; Type: VIEW; Schema: twuanis_canonical_private; Owner: -
--

CREATE VIEW twuanis_canonical_private.customer_email_sources AS
 SELECT
        CASE
            WHEN (e.event_type = 'expire'::text) THEN ('listing-deadline:'::text || l.id)
            ELSE ('listing:'::text || (e.id)::text)
        END AS event_key,
    l.owner_id AS account_id,
    ('listing_'::text ||
        CASE e.event_type
            WHEN 'publish'::text THEN 'published'::text
            WHEN 'renew'::text THEN 'renewed'::text
            ELSE 'expired'::text
        END) AS template,
        CASE
            WHEN (e.event_type = 'expire'::text) THEN COALESCE((EXTRACT(epoch FROM e.publication_expires_at))::text, (e.id)::text)
            ELSE (e.listing_revision)::text
        END AS event_revision,
    'listing'::text AS entity_kind,
    l.id AS entity_id,
    e.recorded_at AS occurred_at,
    jsonb_build_object('listingId', l.id, 'title', l.title, 'transaction', l.transaction_type, 'endsAt',
        CASE
            WHEN (e.event_type = 'expire'::text) THEN LEAST(COALESCE(e.publication_expires_at, e.recorded_at), e.recorded_at)
            ELSE e.publication_expires_at
        END, 'deadline', e.publication_expires_at, 'reminderDays',
        CASE
            WHEN (e.event_type = 'expire'::text) THEN 0
            ELSE NULL::integer
        END, 'ownerId', l.owner_id, 'lifecycleEventId', e.id, 'operationId', e.operation_id, 'language', ( SELECT (tok.listing_data #>> '{publication_delivery,language}'::text[])
           FROM (twuanis_canonical_private.token_creation_commands cmd
             JOIN public.listing_publish_tokens tok ON ((tok.token = cmd.token)))
          WHERE ((cmd.listing_id = l.id) AND (cmd.owner_id = l.owner_id) AND (cmd.publication_request = op.request_id) AND ((tok.listing_data #>> '{publication_delivery,account_id}'::text[]) = (l.owner_id)::text))
         LIMIT 1)) AS payload
   FROM ((public.listing_lifecycle_events e
     JOIN public.canonical_operation_receipts op ON (((op.id = e.operation_id) AND (op.listing_id = e.listing_id) AND (op.outcome = 'succeeded'::text))))
     JOIN public.listings l ON ((l.id = e.listing_id)))
  WHERE ((e.event_type = ANY (ARRAY['publish'::text, 'renew'::text, 'expire'::text])) AND (l.owner_id IS NOT NULL))
UNION ALL
 SELECT ('claim:'::text || e.id) AS event_key,
    e.subject AS account_id,
        CASE e.operation
            WHEN 'claimed'::text THEN 'listing_claimed'::text
            WHEN 'approve'::text THEN 'claim_approved'::text
            WHEN 'reject'::text THEN 'claim_rejected'::text
            ELSE 'claim_revoked'::text
        END AS template,
    (e.id)::text AS event_revision,
    'claim'::text AS entity_kind,
    e.id AS entity_id,
    e.created_at AS occurred_at,
    jsonb_build_object('listingId', e.listing_id, 'title', l.title, 'transaction', l.transaction_type, 'challengeId', e.challenge_id, 'claimEventId', e.id) AS payload
   FROM (twuanis_canonical_private.listing_claim_events e
     LEFT JOIN public.listings l ON ((l.id = e.listing_id)))
  WHERE ((e.operation = ANY (ARRAY['claimed'::text, 'approve'::text, 'reject'::text, 'revoke'::text])) AND ((e.operation = 'claimed'::text) OR ((e.evidence ->> 'ok'::text) = 'true'::text)))
UNION ALL
 SELECT ('payment:'::text || a.id) AS event_key,
    o.account_id,
    'payment_acknowledged'::text AS template,
    (a.id)::text AS event_revision,
    'order'::text AS entity_kind,
    o.id AS entity_id,
    a.acknowledged_at AS occurred_at,
    jsonb_build_object('orderId', o.id, 'acknowledgementId', a.id, 'productId', o.product_id, 'nameEn', COALESCE((o.resolved_terms ->> 'nameEN'::text),
        CASE
            WHEN (o.target_type = 'package'::text) THEN ( SELECT intelligence_packages.name_en
               FROM twuanis_canonical_private.intelligence_packages
              WHERE (intelligence_packages.id = o.product_id))
            ELSE ( SELECT addon_products.name_en
               FROM twuanis_canonical_private.addon_products
              WHERE (addon_products.id = o.product_id))
        END, o.product_id), 'nameEs', COALESCE((o.resolved_terms ->> 'nameES'::text),
        CASE
            WHEN (o.target_type = 'package'::text) THEN ( SELECT COALESCE(intelligence_packages.name_es, intelligence_packages.name_en) AS "coalesce"
               FROM twuanis_canonical_private.intelligence_packages
              WHERE (intelligence_packages.id = o.product_id))
            ELSE ( SELECT COALESCE(addon_products.name_es, addon_products.name_en) AS "coalesce"
               FROM twuanis_canonical_private.addon_products
              WHERE (addon_products.id = o.product_id))
        END, o.product_id), 'quantity', (o.resolved_terms ->> 'quantity'::text), 'amount', (a.amount)::text, 'currency', a.currency, 'language', (o.resolved_terms ->> 'language'::text)) AS payload
   FROM (twuanis_canonical_private.offer_paid_acknowledgements a
     JOIN twuanis_canonical_private.offer_order_snapshots o ON ((o.id = a.order_id)))
UNION ALL
 SELECT ('term:'::text || t.id) AS event_key,
    t.account_id,
        CASE
            WHEN (t.source = 'ADMIN_GRANT'::text) THEN 'grant_activated'::text
            WHEN (t.product_class = 'PACKAGE'::text) THEN 'package_activated'::text
            ELSE 'addon_activated'::text
        END AS template,
    (t.id)::text AS event_revision,
    'term'::text AS entity_kind,
    t.id AS entity_id,
    GREATEST(t.starts_at, t.committed_at) AS occurred_at,
    (COALESCE(twuanis_canonical_private.customer_email_product(t.product_class, t.product_id, t.configuration_id), '{}'::jsonb) || jsonb_build_object('termId', t.id, 'productClass', t.product_class, 'listingId', t.listing_id, 'transaction', l.transaction_type, 'title', l.title, 'startsAt', t.starts_at, 'endsAt', t.ends_at, 'orderId', t.order_id, 'source', t.source, 'language', (o.resolved_terms ->> 'language'::text), 'bankUpgrade', t.bank_upgrade_selected)) AS payload
   FROM ((twuanis_canonical_private.entitlement_terms t
     LEFT JOIN public.listings l ON ((l.id = t.listing_id)))
     LEFT JOIN twuanis_canonical_private.offer_order_snapshots o ON ((o.id = t.order_id)))
UNION ALL
 SELECT ('revocation:'::text || r.term_id) AS event_key,
    t.account_id,
    'entitlement_revoked'::text AS template,
    (r.request_id)::text AS event_revision,
    'term'::text AS entity_kind,
    t.id AS entity_id,
    r.revoked_at AS occurred_at,
    (COALESCE(twuanis_canonical_private.customer_email_product(t.product_class, t.product_id, t.configuration_id), '{}'::jsonb) || jsonb_build_object('termId', t.id, 'productClass', t.product_class, 'listingId', t.listing_id, 'transaction', l.transaction_type, 'title', l.title, 'endsAt', r.revoked_at)) AS payload
   FROM ((twuanis_canonical_private.entitlement_revocations r
     JOIN twuanis_canonical_private.entitlement_terms t ON ((t.id = r.term_id)))
     LEFT JOIN public.listings l ON ((l.id = t.listing_id)))
UNION ALL
 SELECT ('addon:'::text || f.purchase_id) AS event_key,
    f.account_id,
    'addon_activated'::text AS template,
    (f.purchase_id)::text AS event_revision,
    'addon'::text AS entity_kind,
    f.purchase_id AS entity_id,
    f.activated_at AS occurred_at,
    (COALESCE(twuanis_canonical_private.customer_email_product('LISTING_ADDON'::text, f.product_id, f.configuration_id), '{}'::jsonb) || jsonb_build_object('orderId', f.purchase_id, 'operationId', f.target_id, 'startsAt', f.activated_at, 'operationComplete', true)) AS payload
   FROM twuanis_canonical_private.addon_fulfillments f
  WHERE (((f.result ->> 'ok'::text) = 'true'::text) AND (NOT (f.result ? 'termId'::text)))
UNION ALL
 SELECT ('listing-deadline:'::text || l.id) AS event_key,
    l.owner_id AS account_id,
        CASE d.days
            WHEN 0 THEN 'listing_expired'::text
            ELSE (('listing_reminder_'::text || d.days) || 'd'::text)
        END AS template,
    (EXTRACT(epoch FROM l.publication_expires_at))::text AS event_revision,
    'listing'::text AS entity_kind,
    l.id AS entity_id,
    (l.publication_expires_at - make_interval(secs => ((86400 * d.days))::double precision)) AS occurred_at,
    jsonb_build_object('listingId', l.id, 'title', l.title, 'transaction', l.transaction_type, 'endsAt', l.publication_expires_at, 'ownerId', l.owner_id, 'reminderDays', d.days) AS payload
   FROM (public.listings l
     CROSS JOIN ( VALUES (7), (1), (0)) d(days))
  WHERE ((l.owner_id IS NOT NULL) AND (l.listing_status = ANY (ARRAY['active'::text, 'expired'::text])) AND (l.publication_expires_at IS NOT NULL))
UNION ALL
 SELECT ('term-deadline:'::text || t.id) AS event_key,
    t.account_id,
    (
        CASE
            WHEN (t.product_class = 'PACKAGE'::text) THEN 'package'::text
            ELSE 'addon'::text
        END ||
        CASE d.days
            WHEN 0 THEN '_expired'::text
            ELSE (('_reminder_'::text || d.days) || 'd'::text)
        END) AS template,
    (EXTRACT(epoch FROM t.ends_at))::text AS event_revision,
    'term'::text AS entity_kind,
    t.id AS entity_id,
    (t.ends_at - make_interval(secs => ((86400 * d.days))::double precision)) AS occurred_at,
    (COALESCE(twuanis_canonical_private.customer_email_product(t.product_class, t.product_id, t.configuration_id), '{}'::jsonb) || jsonb_build_object('termId', t.id, 'productClass', t.product_class, 'listingId', t.listing_id, 'transaction', l.transaction_type, 'title', l.title, 'endsAt', t.ends_at, 'reminderDays', d.days)) AS payload
   FROM ((twuanis_canonical_private.entitlement_terms t
     LEFT JOIN public.listings l ON ((l.id = t.listing_id)))
     CROSS JOIN ( VALUES (7), (1), (0)) d(days))
  WHERE (t.ends_at IS NOT NULL);


