--
-- Name: direct_sinpe_receipts; Type: TABLE; Schema: twuanis_canonical_private; Owner: -
--

CREATE TABLE twuanis_canonical_private.direct_sinpe_receipts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    order_id uuid NOT NULL,
    account_id uuid NOT NULL,
    receiving_account_id uuid NOT NULL,
    policy_version text DEFAULT 'direct-sinpe-receipt-access-2026-10-31-v1'::text NOT NULL,
    object_path text NOT NULL,
    sha256 text NOT NULL,
    mime_type text NOT NULL,
    file_size bigint NOT NULL,
    submitted_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    activation_term_id uuid,
    reconciliation text DEFAULT 'UNRECONCILED'::text NOT NULL,
    reconciled_by uuid,
    reconciled_at timestamp with time zone,
    recovery_evidence jsonb,
    CONSTRAINT direct_recovery_shape CHECK (((recovery_evidence IS NULL) OR COALESCE(((jsonb_typeof(recovery_evidence) = 'object'::text) AND ((recovery_evidence ->> 'version'::text) = 'owner-direct-recovery-v1'::text) AND ((recovery_evidence ->> 'paymentTimeSource'::text) = 'OWNER_CONFIRMED'::text) AND ((recovery_evidence ->> 'receiptOrigin'::text) = 'OWNER_SUPPLIED_AFTER_INTERNAL_DELETION'::text) AND ((recovery_evidence ->> 'providerVerified'::text) = 'false'::text) AND (jsonb_typeof((recovery_evidence -> 'input'::text)) = 'object'::text)), false))),
    CONSTRAINT direct_sinpe_receipts_check CHECK ((object_path = ((((((
CASE
    WHEN (recovery_evidence IS NULL) THEN ''::text
    ELSE 'owner-recovery/'::text
END || (account_id)::text) || '/'::text) || (order_id)::text) || '/'::text) || sha256) ||
CASE mime_type
    WHEN 'application/pdf'::text THEN '.pdf'::text
    WHEN 'image/jpeg'::text THEN '.jpg'::text
    WHEN 'image/png'::text THEN '.png'::text
    ELSE '.webp'::text
END))),
    CONSTRAINT direct_sinpe_receipts_check1 CHECK (((reconciliation = 'UNRECONCILED'::text) = ((reconciled_by IS NULL) AND (reconciled_at IS NULL)))),
    CONSTRAINT direct_sinpe_receipts_file_size_check CHECK (((file_size >= 1) AND (file_size <= 5242880))),
    CONSTRAINT direct_sinpe_receipts_mime_type_check CHECK ((mime_type = ANY (ARRAY['application/pdf'::text, 'image/jpeg'::text, 'image/png'::text, 'image/webp'::text]))),
    CONSTRAINT direct_sinpe_receipts_policy_version_check CHECK ((policy_version = 'direct-sinpe-receipt-access-2026-10-31-v1'::text)),
    CONSTRAINT direct_sinpe_receipts_reconciliation_check CHECK ((reconciliation = ANY (ARRAY['UNRECONCILED'::text, 'RECONCILED'::text, 'UNMATCHED'::text]))),
    CONSTRAINT direct_sinpe_receipts_sha256_check CHECK ((sha256 ~ '^[0-9a-f]{64}$'::text))
);


