--
-- Name: execution_credit_allocations; Type: TABLE; Schema: twuanis_canonical_private; Owner: -
--

CREATE TABLE twuanis_canonical_private.execution_credit_allocations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    kind text NOT NULL,
    quantity bigint NOT NULL,
    origin text NOT NULL,
    package_id text,
    term_id uuid,
    order_id uuid,
    acknowledgement_id uuid,
    effective_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone,
    issued_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    provenance jsonb NOT NULL,
    CONSTRAINT execution_credit_allocations_check CHECK (((expires_at IS NULL) OR (expires_at > effective_at))),
    CONSTRAINT execution_credit_allocations_check1 CHECK ((isfinite(effective_at) AND ((expires_at IS NULL) OR isfinite(expires_at)))),
    CONSTRAINT execution_credit_allocations_check2 CHECK ((((kind = 'INCLUDED_PACKAGE'::text) AND (term_id IS NOT NULL) AND (package_id IS NOT NULL) AND (order_id IS NOT NULL) AND ((acknowledgement_id IS NOT NULL) OR ((acknowledgement_id IS NULL) AND twuanis_canonical_private.receipt_term_valid(term_id))) AND (expires_at IS NOT NULL)) OR ((kind = 'ADMIN_ALLOWANCE'::text) AND (term_id IS NULL) AND (package_id IS NULL) AND (order_id IS NULL) AND (acknowledgement_id IS NULL) AND (quantity = 3) AND (expires_at IS NOT NULL)) OR ((kind = 'PURCHASED'::text) AND (term_id IS NULL) AND (package_id IS NULL) AND (order_id IS NOT NULL) AND (acknowledgement_id IS NOT NULL) AND (expires_at IS NULL) AND (quantity = ANY (ARRAY[(2)::bigint, (5)::bigint, (10)::bigint, (20)::bigint, (50)::bigint]))))),
    CONSTRAINT execution_credit_allocations_kind_check CHECK ((kind = ANY (ARRAY['INCLUDED_PACKAGE'::text, 'PURCHASED'::text, 'ADMIN_ALLOWANCE'::text]))),
    CONSTRAINT execution_credit_allocations_provenance_check CHECK ((jsonb_typeof(provenance) = 'object'::text)),
    CONSTRAINT execution_credit_allocations_quantity_check CHECK (((quantity > 0) AND (quantity <= 1000000)))
);


--
-- Name: execution_credit_events; Type: TABLE; Schema: twuanis_canonical_private; Owner: -
--

CREATE TABLE twuanis_canonical_private.execution_credit_events (
    id bigint NOT NULL,
    account_id uuid NOT NULL,
    allocation_id uuid,
    execution_id uuid,
    report_id uuid,
    kind text NOT NULL,
    quantity bigint NOT NULL,
    occurred_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    actor_id uuid,
    request_id uuid NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT execution_credit_events_check CHECK ((((kind = 'ADJUSTMENT'::text) AND (quantity <> 0) AND (abs(quantity) <= 1000000)) OR ((kind = ANY (ARRAY['ALLOCATION_ISSUED'::text, 'PURCHASE_CREDITED'::text, 'ALLOCATION_EXPIRED'::text])) AND (quantity >= 0)) OR ((kind = ANY (ARRAY['EXECUTION_RESERVED'::text, 'RESERVATION_RELEASED'::text])) AND (quantity = ANY (ARRAY[(0)::bigint, (1)::bigint]))) OR ((kind = ANY (ARRAY['EXECUTION_CONSUMED'::text, 'REFUND'::text])) AND (quantity = 1)) OR ((kind = 'OWNER_COMPLETED'::text) AND (quantity = 0)))),
    CONSTRAINT execution_credit_events_check1 CHECK (((kind = ANY (ARRAY['EXECUTION_RESERVED'::text, 'RESERVATION_RELEASED'::text, 'EXECUTION_CONSUMED'::text, 'OWNER_COMPLETED'::text, 'REFUND'::text])) = (execution_id IS NOT NULL))),
    CONSTRAINT execution_credit_events_check2 CHECK (((kind <> ALL (ARRAY['EXECUTION_CONSUMED'::text, 'OWNER_COMPLETED'::text])) OR (report_id IS NOT NULL))),
    CONSTRAINT execution_credit_events_kind_check CHECK ((kind = ANY (ARRAY['ALLOCATION_ISSUED'::text, 'PURCHASE_CREDITED'::text, 'EXECUTION_RESERVED'::text, 'RESERVATION_RELEASED'::text, 'EXECUTION_CONSUMED'::text, 'ALLOCATION_EXPIRED'::text, 'ADJUSTMENT'::text, 'REFUND'::text, 'OWNER_COMPLETED'::text]))),
    CONSTRAINT execution_credit_events_metadata_check CHECK ((jsonb_typeof(metadata) = 'object'::text))
);


