    payment_method text DEFAULT 'legacy'::text NOT NULL,
    receiving_phone text,
    CONSTRAINT direct_sinpe_destination CHECK (((payment_method = ANY (ARRAY['legacy'::text, 'direct_sinpe'::text])) AND ((payment_method <> 'direct_sinpe'::text) OR ((currency = 'CRC'::text) AND (receiving_phone ~ '^\+506[0-9]{8}$'::text))))),
    CONSTRAINT sinpe_receiving_accounts_currency_check CHECK ((currency = ANY (ARRAY['USD'::text, 'CRC'::text]))),
    CONSTRAINT sinpe_receiving_accounts_instructions_en_check CHECK (((length(instructions_en) >= 1) AND (length(instructions_en) <= 2000))),
    CONSTRAINT sinpe_receiving_accounts_instructions_es_check CHECK (((length(instructions_es) >= 1) AND (length(instructions_es) <= 2000)))
);


--
-- Name: sinpe_review_decisions; Type: TABLE; Schema: twuanis_canonical_private; Owner: -
--

CREATE TABLE twuanis_canonical_private.sinpe_review_decisions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    attempt_id uuid NOT NULL,
    actor_id uuid NOT NULL,
    request_id uuid NOT NULL,
    command jsonb NOT NULL,
    disposition text NOT NULL,
    reason text NOT NULL,
    receiving_account_id uuid,
    bank_reference text,
    amount numeric,
    currency text,
    received_at timestamp with time zone,
    bank_evidence text,
    decided_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    acknowledgement_id uuid,
    CONSTRAINT sinpe_review_decisions_check CHECK ((((disposition = 'REJECTED'::text) AND (receiving_account_id IS NULL) AND (bank_reference IS NULL) AND (amount IS NULL) AND (currency IS NULL) AND (received_at IS NULL) AND (acknowledgement_id IS NULL)) OR ((disposition = ANY (ARRAY['APPROVED'::text, 'RECEIVED_UNMATCHED'::text])) AND (receiving_account_id IS NOT NULL) AND (bank_reference IS NOT NULL) AND ((length(bank_reference) >= 1) AND (length(bank_reference) <= 300)) AND (bank_reference = btrim(bank_reference)) AND (amount > (0)::numeric) AND (amount < ('1000000000000'::bigint)::numeric) AND (scale(amount) <= 2) AND (currency = ANY (ARRAY['USD'::text, 'CRC'::text])) AND (bank_evidence IS NOT NULL) AND ((length(bank_evidence) >= 1) AND (length(bank_evidence) <= 2000))))),
    CONSTRAINT sinpe_review_decisions_check1 CHECK (((disposition = 'APPROVED'::text) = (acknowledgement_id IS NOT NULL))),
    CONSTRAINT sinpe_review_decisions_disposition_check CHECK ((disposition = ANY (ARRAY['APPROVED'::text, 'RECEIVED_UNMATCHED'::text, 'REJECTED'::text])))
);


