--

CREATE TABLE twuanis_measurement_private.consent_grants (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    session_id uuid NOT NULL,
    purpose text DEFAULT 'analytics_outcomes'::text NOT NULL,
    notice_version text NOT NULL,
    environment text NOT NULL,
    epoch text NOT NULL,
    revision bigint DEFAULT 1 NOT NULL,
    granted_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    expires_at timestamp with time zone DEFAULT (clock_timestamp() + '24:00:00'::interval) NOT NULL,
    revoked_at timestamp with time zone,
    revocation_reason text,
    client_id text,
    revoke_digest text NOT NULL,
    purge_at timestamp with time zone DEFAULT ((clock_timestamp() + '7 days'::interval) - '00:10:00'::interval) NOT NULL,
    ga_session_id bigint,
    ga_session_observed_at timestamp with time zone,
    CONSTRAINT consent_grants_check CHECK (((expires_at > granted_at) AND (expires_at <= (granted_at + '24:00:00'::interval)))),
    CONSTRAINT consent_grants_check1 CHECK (((purge_at <= (granted_at + '7 days'::interval)) AND (purge_at > expires_at))),
    CONSTRAINT consent_grants_check2 CHECK (((revoked_at IS NULL) = (revocation_reason IS NULL))),
    CONSTRAINT consent_grants_client_id_check CHECK ((client_id ~ '^[0-9]{1,20}\.[0-9]{1,20}$'::text)),
    CONSTRAINT consent_grants_environment_check CHECK ((environment = 'production'::text)),
    CONSTRAINT consent_grants_epoch_check CHECK ((epoch ~ '^[a-f0-9]{32}$'::text)),
    CONSTRAINT consent_grants_ga_session_id_check CHECK ((ga_session_id > 0)),
    CONSTRAINT consent_grants_notice_version_check CHECK ((notice_version = 'ka09-v1'::text)),
    CONSTRAINT consent_grants_purpose_check CHECK ((purpose = 'analytics_outcomes'::text)),
    CONSTRAINT consent_grants_revision_check CHECK ((revision > 0)),
    CONSTRAINT consent_grants_revocation_reason_check CHECK ((revocation_reason = ANY (ARRAY['withdrawal'::text, 'logout'::text, 'account_switch'::text, 'erasure'::text]))),
    CONSTRAINT consent_grants_revoke_digest_check CHECK ((revoke_digest ~ '^[a-f0-9]{64}$'::text))
);


