--
-- Name: journey_archival_r4; Type: VIEW; Schema: twuanis_measurement_private; Owner: -
--

CREATE VIEW twuanis_measurement_private.journey_archival_r4 AS
 SELECT e.journey,
    e.id,
    e.client_seq,
    e.received_seq,
    e.retention_until,
    e.observed_at,
    e.received_at,
    e.envelope,
    e.authority,
        CASE
            WHEN (j.identity_until > clock_timestamp()) THEN j.account_id
            ELSE NULL::uuid
        END AS account_id,
        CASE
            WHEN (j.identity_until > clock_timestamp()) THEN j.linked_at
            ELSE NULL::timestamp with time zone
        END AS linked_at,
    j.ended_at,
    j.end_reason
   FROM (twuanis_measurement_private.journey_events_r3 e
     JOIN twuanis_measurement_private.journeys_r3 j ON ((j.id = e.journey)))
  WHERE ((NOT j.suppressed) AND (j.account_id IS DISTINCT FROM 'd81064bc-1b4a-478f-8f6a-b263c4779bc1'::uuid) AND ((e.retention_until > clock_timestamp()) OR (j.archive_state IS NULL)) AND (j.policy_ref IS NOT NULL) AND (NOT (EXISTS ( SELECT 1
           FROM twuanis_measurement_private.journey_erasure_r3 r
          WHERE ((r.account_id = j.account_id) OR (EXISTS ( SELECT 1
                   FROM twuanis_measurement_private.journey_orders_r3 o
                  WHERE ((o.journey = j.id) AND (o.account_id = r.account_id)))) OR (EXISTS ( SELECT 1
                   FROM twuanis_canonical_private.offer_order_snapshots own
                  WHERE (((own.id)::text = (e.envelope ->> 'order'::text)) AND (own.account_id = r.account_id) AND (e.authority = 'canonical'::text)))))))) AND (NOT (((e.envelope ->> 'control'::text) ~~ 'server_response_%'::text) AND (EXISTS ( SELECT 1
           FROM twuanis_measurement_private.journey_events_r3 acknowledged
          WHERE ((acknowledged.journey = e.journey) AND (acknowledged.id = ((e.envelope -> 'evidence'::text) ->> 'event_id'::text)) AND (acknowledged.authority = 'server_acknowledged'::text)))))));


--
-- Name: journey_business_r4; Type: TABLE; Schema: twuanis_measurement_private; Owner: -
--

CREATE TABLE twuanis_measurement_private.journey_business_r4 (
    bucket_day date NOT NULL,
    cohort_day date NOT NULL,
    projection text NOT NULL,
    dimensions jsonb NOT NULL,
    event_count bigint,
    scope_occurrences bigint,
    scope_starts bigint,
    revenue numeric,
    status text NOT NULL,
    policy_ref text NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT journey_business_r4_check CHECK (((status <> 'PRIVACY_WITHHELD'::text) OR ((event_count IS NULL) AND (scope_occurrences IS NULL) AND (scope_starts IS NULL) AND (revenue IS NULL)))),
    CONSTRAINT journey_business_r4_dimensions_check CHECK ((octet_length((dimensions)::text) <= 1024)),
    CONSTRAINT journey_business_r4_projection_check CHECK ((projection = ANY (ARRAY['traffic'::text, 'acquisition'::text, 'feature'::text, 'algorithm'::text, 'commercial'::text, 'flow'::text, 'transition'::text, 'coverage'::text]))),
    CONSTRAINT journey_business_r4_status_check CHECK ((status = ANY (ARRAY['APPROVED_AGGREGATE'::text, 'PRIVACY_WITHHELD'::text])))
);


--
-- Name: journey_events_r3_received_seq_seq; Type: SEQUENCE; Schema: twuanis_measurement_private; Owner: -
--

ALTER TABLE twuanis_measurement_private.journey_events_r3 ALTER COLUMN received_seq ADD GENERATED ALWAYS AS IDENTITY (
