);


--
-- Name: journey_policy_r3; Type: TABLE; Schema: twuanis_measurement_private; Owner: -
--

CREATE TABLE twuanis_measurement_private.journey_policy_r3 (
    singleton boolean DEFAULT true NOT NULL,
    approval_ref text,
    history_days integer,
    identity_days integer,
    commercial_days integer,
    suppression_days integer,
    aggregate_approval_ref text,
    anonymous_aggregate_approval_ref text,
    min_contributors integer DEFAULT 10 NOT NULL,
    minute_at timestamp with time zone,
    starts integer DEFAULT 0 NOT NULL,
    events integer DEFAULT 0 NOT NULL,
    rate_rejections bigint DEFAULT 0 NOT NULL,
    capacity_rejections bigint DEFAULT 0 NOT NULL,
    CONSTRAINT journey_policy_r3_aggregate_approval_ref_check CHECK (((length(aggregate_approval_ref) >= 1) AND (length(aggregate_approval_ref) <= 120))),
    CONSTRAINT journey_policy_r3_anonymous_aggregate_approval_ref_check CHECK (((length(anonymous_aggregate_approval_ref) >= 1) AND (length(anonymous_aggregate_approval_ref) <= 120))),
    CONSTRAINT journey_policy_r3_approval_ref_check CHECK (((length(approval_ref) >= 1) AND (length(approval_ref) <= 120))),
    CONSTRAINT journey_policy_r3_check CHECK (((identity_days <= history_days) AND (commercial_days <= history_days))),
    CONSTRAINT journey_policy_r3_commercial_days_check CHECK ((commercial_days > 0)),
    CONSTRAINT journey_policy_r3_history_days_check CHECK ((history_days > 0)),
    CONSTRAINT journey_policy_r3_identity_days_check CHECK ((identity_days > 0)),
    CONSTRAINT journey_policy_r3_min_contributors_check CHECK (((min_contributors >= 10) AND (min_contributors <= 100))),
    CONSTRAINT journey_policy_r3_singleton_check CHECK (singleton),
    CONSTRAINT journey_policy_r3_suppression_days_check CHECK ((suppression_days > 0))
);


--
-- Name: journey_reporting_r3; Type: VIEW; Schema: twuanis_measurement_private; Owner: -
--

CREATE VIEW twuanis_measurement_private.journey_reporting_r3 AS
 SELECT e.journey,
    e.id,
    e.client_seq,
    e.received_seq,
    e.retention_until,
    e.observed_at,
    e.received_at,
    e.envelope,
    e.authority,
        CASE
            WHEN (j.identity_until > clock_timestamp()) THEN j.account_id
            ELSE NULL::uuid
        END AS account_id,
        CASE
            WHEN (j.identity_until > clock_timestamp()) THEN j.linked_at
            ELSE NULL::timestamp with time zone
        END AS linked_at,
    j.ended_at,
    j.end_reason
   FROM (twuanis_measurement_private.journey_events_r3 e
     JOIN twuanis_measurement_private.journeys_r3 j ON ((j.id = e.journey)))
  WHERE ((NOT j.suppressed) AND (j.account_id IS DISTINCT FROM 'd81064bc-1b4a-478f-8f6a-b263c4779bc1'::uuid) AND (LEAST(e.retention_until, twuanis_measurement_private.journey_evidence_deadline_r4(j.*, e.observed_at)) > clock_timestamp()) AND (j.policy_ref IS NOT NULL) AND (NOT (EXISTS ( SELECT 1
           FROM twuanis_measurement_private.journey_erasure_r3 r
          WHERE ((r.account_id = j.account_id) OR (EXISTS ( SELECT 1
                   FROM twuanis_measurement_private.journey_orders_r3 o
                  WHERE ((o.journey = j.id) AND (o.account_id = r.account_id)))) OR (EXISTS ( SELECT 1
                   FROM twuanis_canonical_private.offer_order_snapshots own
                  WHERE (((own.id)::text = (e.envelope ->> 'order'::text)) AND (own.account_id = r.account_id) AND (e.authority = 'canonical'::text)))))))) AND (NOT (((e.envelope ->> 'control'::text) ~~ 'server_response_%'::text) AND (EXISTS ( SELECT 1
           FROM twuanis_measurement_private.journey_events_r3 acknowledged
          WHERE ((acknowledged.journey = e.journey) AND (acknowledged.id = ((e.envelope -> 'evidence'::text) ->> 'event_id'::text)) AND (acknowledged.authority = 'server_acknowledged'::text)))))));


--
-- Name: outcome_claims; Type: TABLE; Schema: twuanis_measurement_private; Owner: -
--

CREATE TABLE twuanis_measurement_private.outcome_claims (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    grant_id uuid NOT NULL,
    grant_revision bigint NOT NULL,
    event_name text NOT NULL,
    subject_kind text NOT NULL,
    subject_id uuid NOT NULL,
    environment text NOT NULL,
    destination text DEFAULT 'G-XPKD8XE7FD'::text NOT NULL,
    event_id text NOT NULL,
    origin_at timestamp with time zone NOT NULL,
    page_instance text NOT NULL,
    locale text NOT NULL,
    bound_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    purge_at timestamp with time zone NOT NULL,
    state text DEFAULT 'PENDING'::text NOT NULL,
    reason text,
    receipt_ref text,
    outcome_at timestamp with time zone,
    payload_digest text,
    reservation uuid,
    reserved_until timestamp with time zone,
    reservation_count integer DEFAULT 0 NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    attempt_at timestamp with time zone,
    finished_at timestamp with time zone,
    http_status smallint,
    provider_receipt text,
    CONSTRAINT outcome_claims_attempt_count_check CHECK (((attempt_count >= 0) AND (attempt_count <= 1))),
    CONSTRAINT outcome_claims_check CHECK (((subject_kind = 'order'::text) = (event_name = ANY (ARRAY['purchase'::text, 'tw_payment_state'::text, 'tw_entitlement_state'::text])))),
    CONSTRAINT outcome_claims_check1 CHECK (((expires_at <= (bound_at + '72:00:00'::interval)) AND (purge_at <= (bound_at + '7 days'::interval)))),
    CONSTRAINT outcome_claims_check2 CHECK (((attempt_count = 0) = (attempt_at IS NULL))),
    CONSTRAINT outcome_claims_destination_check CHECK ((destination = 'G-XPKD8XE7FD'::text)),
    CONSTRAINT outcome_claims_environment_check CHECK ((environment = 'production'::text)),
    CONSTRAINT outcome_claims_event_id_check CHECK ((event_id ~ '^e[a-f0-9]{64}$'::text)),
    CONSTRAINT outcome_claims_event_name_check CHECK ((event_name = ANY (ARRAY['purchase'::text, 'tw_payment_state'::text, 'tw_entitlement_state'::text, 'tw_execution_result'::text, 'tw_report_ready'::text]))),
    CONSTRAINT outcome_claims_http_status_check CHECK (((http_status >= 100) AND (http_status <= 599))),
    CONSTRAINT outcome_claims_locale_check CHECK ((locale = ANY (ARRAY['en'::text, 'es'::text]))),
    CONSTRAINT outcome_claims_page_instance_check CHECK ((page_instance ~ '^[a-f0-9]{32}$'::text)),
    CONSTRAINT outcome_claims_payload_digest_check CHECK ((payload_digest ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT outcome_claims_provider_receipt_check CHECK ((provider_receipt ~ '^[a-zA-Z0-9_-]{1,80}$'::text)),
    CONSTRAINT outcome_claims_reason_check CHECK ((reason = ANY (ARRAY['revoked'::text, 'expired'::text, 'authority'::text, 'missing_client'::text, 'stale'::text, 'rejected'::text, 'timeout'::text, 'interrupted'::text, 'http_accepted'::text, 'provider_receipt'::text, 'disabled'::text]))),
    CONSTRAINT outcome_claims_receipt_ref_check CHECK ((length(receipt_ref) <= 80)),
    CONSTRAINT outcome_claims_reservation_count_check CHECK (((reservation_count >= 0) AND (reservation_count <= 2))),
    CONSTRAINT outcome_claims_state_check CHECK ((state = ANY (ARRAY['PENDING'::text, 'ELIGIBLE'::text, 'CLAIMED'::text, 'ATTEMPTED'::text, 'ACKNOWLEDGED'::text, 'FAILED'::text, 'SUPPRESSED'::text, 'UNKNOWN'::text]))),
    CONSTRAINT outcome_claims_subject_kind_check CHECK ((subject_kind = ANY (ARRAY['order'::text, 'execution'::text])))
);


