--

CREATE TABLE twuanis_remates_private.financial_values (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    institution_id uuid NOT NULL,
    offering_id uuid NOT NULL,
    source_id uuid NOT NULL,
    observation_id uuid NOT NULL,
    field_path text NOT NULL,
    ordinal integer NOT NULL,
    kind text NOT NULL,
    original_label text,
    raw_amount text,
    original_currency text,
    original_unit text,
    amount numeric,
    currency text,
    status text NOT NULL,
    round_key text,
    round_path text,
    round_ordinal integer,
    actor_id uuid NOT NULL,
    receipt_id uuid NOT NULL,
    reason text NOT NULL,
    recorded_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT financial_values_amount_check CHECK ((twuanis_canonical_private.finite_numeric(amount) AND ((amount IS NULL) OR ((amount >= (0)::numeric) AND (scale(amount) <= 18) AND (amount < '1000000000000000000000000000000'::numeric))))),
    CONSTRAINT financial_values_check CHECK ((((status = 'VALID'::text) AND (amount IS NOT NULL) AND (((kind = 'DISCOUNT_PERCENT'::text) AND (currency IS NULL) AND (amount <= (100)::numeric)) OR ((kind <> 'DISCOUNT_PERCENT'::text) AND (currency IS NOT NULL)))) OR ((status <> 'VALID'::text) AND (amount IS NULL) AND (currency IS NULL)))),
    CONSTRAINT financial_values_check1 CHECK ((((kind = 'AUCTION_BASE'::text) AND (((round_key IS NOT NULL) AND (round_path IS NOT NULL) AND (round_ordinal IS NOT NULL)) OR ((status <> 'VALID'::text) AND (num_nonnulls(round_key, round_path, round_ordinal) = 0)))) OR ((kind <> 'AUCTION_BASE'::text) AND (num_nonnulls(round_key, round_path, round_ordinal) = 0)))),
    CONSTRAINT financial_values_currency_check CHECK ((currency = ANY (ARRAY['CRC'::text, 'USD'::text]))),
    CONSTRAINT financial_values_kind_check CHECK ((kind = ANY (ARRAY['SELLING_PRICE'::text, 'APPRAISAL'::text, 'REFERENCE'::text, 'AUCTION_BASE'::text, 'DISCOUNT_AMOUNT'::text, 'DISCOUNT_PERCENT'::text, 'FINANCING_AMOUNT'::text, 'INSTALLMENT'::text, 'CONDOMINIUM_FEE'::text]))),
    CONSTRAINT financial_values_reason_check CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 2000))),
    CONSTRAINT financial_values_round_key_check CHECK (((length(round_key) >= 1) AND (length(round_key) <= 200))),
    CONSTRAINT financial_values_status_check CHECK ((status = ANY (ARRAY['VALID'::text, 'MISSING'::text, 'AMBIGUOUS'::text, 'INVALID'::text])))
);


