    CONSTRAINT media_assets_reason_check CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 2000))),
    CONSTRAINT media_assets_rights_status_check CHECK ((rights_status = 'UNVERIFIED'::text))
);


