    link_revision bigint NOT NULL,
    actor_id uuid NOT NULL,
    receipt_id uuid NOT NULL,
    reason text NOT NULL,
    recorded_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT observation_links_link_revision_check CHECK ((link_revision > 0)),
    CONSTRAINT observation_links_reason_check CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 2000))),
    CONSTRAINT observation_links_recorded_at_check CHECK (isfinite(recorded_at))
);


--
-- Name: observations; Type: TABLE; Schema: twuanis_remates_private; Owner: -
--

CREATE TABLE twuanis_remates_private.observations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    source_id uuid NOT NULL,
    run_id uuid NOT NULL,
    observation_key text NOT NULL,
    record_key text NOT NULL,
    retrieved_at timestamp with time zone NOT NULL,
    published_at timestamp with time zone,
    updated_at timestamp with time zone,
    source_url text NOT NULL,
    parser_version text NOT NULL,
    parse_status text NOT NULL,
    raw_text text NOT NULL,
    content_sha256 text NOT NULL,
    actor_id uuid NOT NULL,
    receipt_id uuid NOT NULL,
    recorded_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    payload jsonb NOT NULL,
    CONSTRAINT observations_content_sha256_check CHECK ((content_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT observations_observation_key_check CHECK (((length(observation_key) >= 1) AND (length(observation_key) <= 128))),
    CONSTRAINT observations_parse_status_check CHECK ((parse_status = ANY (ARRAY['PARSED'::text, 'FAILED'::text, 'UNPARSED'::text]))),
    CONSTRAINT observations_parser_version_check CHECK (((length(parser_version) >= 1) AND (length(parser_version) <= 128))),
    CONSTRAINT observations_payload_check CHECK (((jsonb_typeof(payload) = 'object'::text) AND (octet_length((payload)::text) <= 16384))),
    CONSTRAINT observations_published_at_check CHECK (isfinite(published_at)),
    CONSTRAINT observations_raw_text_check CHECK ((octet_length(raw_text) <= 8192)),
    CONSTRAINT observations_record_key_check CHECK (((length(record_key) >= 1) AND (length(record_key) <= 256))),
    CONSTRAINT observations_recorded_at_check CHECK (isfinite(recorded_at)),
    CONSTRAINT observations_retrieved_at_check CHECK (isfinite(retrieved_at)),
    CONSTRAINT observations_source_url_check CHECK ((length(source_url) <= 2048)),
    CONSTRAINT observations_updated_at_check CHECK (isfinite(updated_at))
);


