--
-- Name: property_facts; Type: TABLE; Schema: twuanis_remates_private; Owner: -
--

CREATE TABLE twuanis_remates_private.property_facts (
    classification_id uuid NOT NULL,
    property_id uuid NOT NULL,
    dimension text NOT NULL,
    kind text NOT NULL,
    exact_value numeric,
    category_term_id bigint,
    range_lower numeric,
    range_upper numeric,
    lower_inclusive boolean,
    upper_inclusive boolean,
    evidence_id uuid NOT NULL,
    field_path text NOT NULL,
    ordinal integer NOT NULL,
    rule_set_id uuid,
    rule_id uuid,
    rule_fingerprint text,
    CONSTRAINT property_facts_check CHECK ((((kind = 'exact'::text) AND (exact_value IS NOT NULL) AND (category_term_id IS NULL) AND (num_nonnulls(range_lower, range_upper, lower_inclusive, upper_inclusive) = 0)) OR ((kind = 'category'::text) AND (category_term_id IS NOT NULL) AND (exact_value IS NULL) AND (num_nonnulls(range_lower, range_upper, lower_inclusive, upper_inclusive) = 0) AND (dimension <> 'distance_to_paved_road'::text)) OR ((kind = 'range'::text) AND (exact_value IS NULL) AND (category_term_id IS NULL) AND (num_nonnulls(range_lower, range_upper) > 0) AND (lower_inclusive IS NOT NULL) AND (upper_inclusive IS NOT NULL) AND ((range_lower IS NOT NULL) OR (NOT lower_inclusive)) AND ((range_upper IS NOT NULL) OR (NOT upper_inclusive)) AND (NOT isempty(numrange(range_lower, range_upper, (
CASE
    WHEN lower_inclusive THEN '['::text
    ELSE '('::text
END ||
CASE
    WHEN upper_inclusive THEN ']'::text
    ELSE ')'::text
END))))))),
    CONSTRAINT property_facts_check1 CHECK ((twuanis_canonical_private.finite_numeric(exact_value) AND twuanis_canonical_private.finite_numeric(range_lower) AND twuanis_canonical_private.finite_numeric(range_upper))),
    CONSTRAINT property_facts_check2 CHECK ((((exact_value IS NULL) OR (exact_value >= (0)::numeric)) AND ((range_lower IS NULL) OR (range_lower >= (0)::numeric)) AND ((range_upper IS NULL) OR (range_upper >= (0)::numeric)))),
    CONSTRAINT property_facts_check3 CHECK (((dimension <> ALL (ARRAY['bathrooms'::text, 'property_area'::text, 'construction_area'::text])) OR (kind <> 'exact'::text) OR (exact_value > (0)::numeric))),
    CONSTRAINT property_facts_check4 CHECK (((dimension <> ALL (ARRAY['bedrooms'::text, 'parking'::text, 'year_built'::text])) OR (((exact_value IS NULL) OR (exact_value = trunc(exact_value))) AND ((range_lower IS NULL) OR (range_lower = trunc(range_lower))) AND ((range_upper IS NULL) OR (range_upper = trunc(range_upper)))))),
    CONSTRAINT property_facts_check5 CHECK (((dimension <> 'year_built'::text) OR (((exact_value IS NULL) OR ((exact_value >= (1)::numeric) AND (exact_value <= (9999)::numeric))) AND ((range_lower IS NULL) OR ((range_lower >= (1)::numeric) AND (range_lower <= (9999)::numeric))) AND ((range_upper IS NULL) OR ((range_upper >= (1)::numeric) AND (range_upper <= (9999)::numeric)))))),
    CONSTRAINT property_facts_check6 CHECK ((((rule_set_id IS NULL) AND (rule_id IS NULL) AND (rule_fingerprint IS NULL)) OR ((kind = 'exact'::text) AND (rule_set_id IS NOT NULL) AND (rule_id IS NOT NULL) AND (rule_fingerprint ~ '^[0-9a-f]{64}$'::text)))),
    CONSTRAINT property_facts_dimension_check CHECK ((dimension = ANY (ARRAY['bedrooms'::text, 'bathrooms'::text, 'parking'::text, 'year_built'::text, 'distance_to_paved_road'::text, 'property_area'::text, 'construction_area'::text]))),
    CONSTRAINT property_facts_kind_check CHECK ((kind = ANY (ARRAY['exact'::text, 'category'::text, 'range'::text])))
);


