--
-- Name: saved_searches; Type: TABLE; Schema: twuanis_remates_private; Owner: -
--

CREATE TABLE twuanis_remates_private.saved_searches (
    id uuid NOT NULL,
    user_id uuid NOT NULL,
    population text DEFAULT 'REMATES'::text NOT NULL,
    name text NOT NULL,
    definition jsonb NOT NULL,
    language text NOT NULL,
    revision bigint NOT NULL,
    active boolean NOT NULL,
    alerts_enabled boolean DEFAULT false NOT NULL,
    alert_frequency text,
    last_checked_at timestamp with time zone,
    recorded_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    alert_page integer DEFAULT 0 NOT NULL,
    CONSTRAINT saved_searches_alert_frequency_check CHECK ((alert_frequency = ANY (ARRAY['daily'::text, 'weekly'::text]))),
    CONSTRAINT saved_searches_alert_page_check CHECK (((alert_page >= 0) AND (alert_page <= 9999))),
    CONSTRAINT saved_searches_check CHECK ((alerts_enabled = (alert_frequency IS NOT NULL))),
    CONSTRAINT saved_searches_definition_check CHECK (((jsonb_typeof(definition) = 'object'::text) AND (octet_length((definition)::text) <= 3000))),
    CONSTRAINT saved_searches_language_check CHECK ((language = ANY (ARRAY['en'::text, 'es'::text]))),
    CONSTRAINT saved_searches_name_check CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 128))),
    CONSTRAINT saved_searches_population_check CHECK ((population = 'REMATES'::text)),
    CONSTRAINT saved_searches_revision_check CHECK ((revision > 0))
);


--
-- Name: source_aliases; Type: TABLE; Schema: twuanis_remates_private; Owner: -
