    CONSTRAINT source_aliases_created_at_check CHECK (isfinite(created_at)),
    CONSTRAINT source_aliases_namespace_check CHECK ((namespace ~ '^[a-z0-9][a-z0-9._:-]{0,127}$'::text))
);


