    observation_id uuid NOT NULL,
    revision bigint NOT NULL,
    prior_binding_id uuid,
    decision_id uuid NOT NULL,
    starts_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT source_bindings_check CHECK (((revision = 1) = (prior_binding_id IS NULL))),
    CONSTRAINT source_bindings_record_key_check CHECK (((length(record_key) >= 1) AND (length(record_key) <= 256))),
    CONSTRAINT source_bindings_revision_check CHECK ((revision > 0)),
    CONSTRAINT source_bindings_starts_at_check CHECK (isfinite(starts_at))
);


--
-- Name: source_lifecycle_policies; Type: TABLE; Schema: twuanis_remates_private; Owner: -
--

CREATE TABLE twuanis_remates_private.source_lifecycle_policies (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    source_id uuid NOT NULL,
    source_revision bigint NOT NULL,
    revision bigint NOT NULL,
    prior_id uuid,
    fresh_seconds bigint NOT NULL,
    archive_seconds bigint NOT NULL,
    absent_runs integer NOT NULL,
    coverage_key text NOT NULL,
    unconfirmed_visibility text NOT NULL,
    suspended_visibility text NOT NULL,
    actor_id uuid NOT NULL,
    receipt_id uuid NOT NULL,
    reason text NOT NULL,
    recorded_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT source_lifecycle_policies_absent_runs_check CHECK (((absent_runs >= 1) AND (absent_runs <= 32))),
    CONSTRAINT source_lifecycle_policies_check CHECK (((archive_seconds >= fresh_seconds) AND (archive_seconds <= 315360000))),
    CONSTRAINT source_lifecycle_policies_check1 CHECK (((revision = 1) = (prior_id IS NULL))),
    CONSTRAINT source_lifecycle_policies_coverage_key_check CHECK (((length(btrim(coverage_key)) >= 1) AND (length(btrim(coverage_key)) <= 256))),
    CONSTRAINT source_lifecycle_policies_fresh_seconds_check CHECK (((fresh_seconds >= 1) AND (fresh_seconds <= 315360000))),
    CONSTRAINT source_lifecycle_policies_reason_check CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 2000))),
    CONSTRAINT source_lifecycle_policies_revision_check CHECK ((revision > 0)),
    CONSTRAINT source_lifecycle_policies_source_revision_check CHECK ((source_revision > 0)),
    CONSTRAINT source_lifecycle_policies_suspended_visibility_check CHECK ((suspended_visibility = ANY (ARRAY['HIDE'::text, 'LAST_VERIFIED'::text]))),
    CONSTRAINT source_lifecycle_policies_unconfirmed_visibility_check CHECK ((unconfirmed_visibility = ANY (ARRAY['HIDE'::text, 'LABELLED'::text])))
);


