    CONSTRAINT source_operations_revision_check CHECK ((revision > 0)),
    CONSTRAINT source_operations_state_check CHECK ((state = ANY (ARRAY['REVIEW_READY'::text, 'SUSPENDED'::text, 'STOPPED'::text])))
);


--
-- Name: source_origin_hosts; Type: TABLE; Schema: twuanis_remates_private; Owner: -
--

CREATE TABLE twuanis_remates_private.source_origin_hosts (
    host text NOT NULL,
    institution_id uuid NOT NULL,
    CONSTRAINT source_origin_hosts_host_check CHECK (((host = lower(host)) AND (host ~ '^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$'::text) AND (host ~ '[a-z]'::text) AND (length(host) <= 253)))
);


