    observation_count integer NOT NULL,
    review_evidence text NOT NULL,
    actor_id uuid NOT NULL,
    receipt_id uuid NOT NULL,
    recorded_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT source_run_verifications_observation_count_check CHECK (((observation_count >= 0) AND (observation_count <= 10000))),
    CONSTRAINT source_run_verifications_review_evidence_check CHECK (((length(btrim(review_evidence)) >= 3) AND (length(btrim(review_evidence)) <= 2000)))
);


--
-- Name: source_runs; Type: TABLE; Schema: twuanis_remates_private; Owner: -
--

CREATE TABLE twuanis_remates_private.source_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    source_id uuid NOT NULL,
    run_key text NOT NULL,
    source_revision bigint NOT NULL,
    adapter_version text NOT NULL,
    started_at timestamp with time zone NOT NULL,
    ended_at timestamp with time zone NOT NULL,
    outcome text NOT NULL,
    scope text NOT NULL,
    page_manifest jsonb NOT NULL,
    actor_id uuid NOT NULL,
    receipt_id uuid NOT NULL,
    recorded_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    payload jsonb NOT NULL,
    CONSTRAINT source_runs_check CHECK ((isfinite(ended_at) AND (ended_at >= started_at))),
    CONSTRAINT source_runs_outcome_check CHECK ((outcome = ANY (ARRAY['COMPLETE'::text, 'PARTIAL'::text, 'FAILED'::text]))),
    CONSTRAINT source_runs_page_manifest_check CHECK (((jsonb_typeof(page_manifest) = 'array'::text) AND (jsonb_array_length(page_manifest) <= 32))),
    CONSTRAINT source_runs_payload_check CHECK (((jsonb_typeof(payload) = 'object'::text) AND (octet_length((payload)::text) <= 16384))),
    CONSTRAINT source_runs_recorded_at_check CHECK (isfinite(recorded_at)),
    CONSTRAINT source_runs_run_key_check CHECK (((length(run_key) >= 1) AND (length(run_key) <= 128))),
    CONSTRAINT source_runs_scope_check CHECK (((length(btrim(scope)) >= 1) AND (length(btrim(scope)) <= 2000))),
    CONSTRAINT source_runs_source_revision_check CHECK ((source_revision > 0)),
    CONSTRAINT source_runs_started_at_check CHECK (isfinite(started_at))
);


--
-- Name: upload_receipts; Type: TABLE; Schema: twuanis_remates_private; Owner: -
--

CREATE TABLE twuanis_remates_private.upload_receipts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    institution_id uuid NOT NULL,
    source_id uuid NOT NULL,
    offering_id uuid NOT NULL,
    observation_id uuid NOT NULL,
    actor_id uuid NOT NULL,
    request_id uuid NOT NULL,
    receipt_id uuid NOT NULL,
    original_hash text NOT NULL,
    original_mime text NOT NULL,
    original_name text NOT NULL,
    original_bytes integer NOT NULL,
    object_key text NOT NULL,
    reason text NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    expires_at timestamp with time zone DEFAULT (clock_timestamp() + '00:15:00'::interval) NOT NULL,
    CONSTRAINT upload_receipts_check CHECK ((expires_at > created_at)),
    CONSTRAINT upload_receipts_check1 CHECK ((object_key = (((('institutions/'::text || (institution_id)::text) || '/'::text) || (id)::text) ||
CASE
    WHEN (original_mime = 'text/plain'::text) THEN '.txt'::text
    ELSE '.webp'::text
END))),
    CONSTRAINT upload_receipts_original_bytes_check CHECK (((original_bytes >= 1) AND (original_bytes <= 5242880))),
    CONSTRAINT upload_receipts_original_hash_check CHECK ((original_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT upload_receipts_original_mime_check CHECK ((original_mime = ANY (ARRAY['image/jpeg'::text, 'image/png'::text, 'image/webp'::text, 'text/plain'::text]))),
    CONSTRAINT upload_receipts_original_name_check CHECK (((length(original_name) >= 1) AND (length(original_name) <= 255))),
    CONSTRAINT upload_receipts_reason_check CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 2000)))
);


--
-- Name: commands; Type: TABLE; Schema: twuanis_scraper_private; Owner: -
--

CREATE TABLE twuanis_scraper_private.commands (
    id uuid NOT NULL,
    requested_by uuid NOT NULL,
    requested_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    state text NOT NULL,
    scrapers text[] NOT NULL,
    claimed_by text,
    claimed_at timestamp with time zone,
    launched_at timestamp with time zone,
    finished_at timestamp with time zone,
    summary jsonb DEFAULT '{}'::jsonb NOT NULL,
    notification_state text DEFAULT 'not_requested'::text NOT NULL,
    CONSTRAINT commands_notification_state_check CHECK ((notification_state = ANY (ARRAY['not_requested'::text, 'pending'::text, 'sent'::text, 'failed'::text]))),
    CONSTRAINT commands_state_check CHECK ((state = ANY (ARRAY['requested'::text, 'accepted'::text, 'running'::text, 'completed'::text, 'failed'::text, 'rejected'::text, 'expired'::text]))),
    CONSTRAINT commands_supported_scrapers_check CHECK ((((cardinality(scrapers) >= 1) AND (cardinality(scrapers) <= 2)) AND (scrapers <@ ARRAY['encuentra24-sale'::text, 'encuentra24-rent'::text, 'helcor-sale'::text, 'helcor-rent'::text, 'remax-central-sale'::text, 'remax-central-rent'::text, 'inmobiliaria-cdj-sale'::text, 'inmobiliaria-cdj-rent'::text, 'montero-realty-group-sale'::text, 'montero-realty-group-rent'::text, 'devop-sale'::text])))
);


--
-- Name: worker_heartbeats; Type: TABLE; Schema: twuanis_scraper_private; Owner: -
--

CREATE TABLE twuanis_scraper_private.worker_heartbeats (
    worker_id text NOT NULL,
    last_seen_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    state text NOT NULL,
    active_command_id uuid,
    details jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT worker_heartbeats_state_check CHECK ((state = ANY (ARRAY['idle'::text, 'running'::text, 'offline'::text]))),
    CONSTRAINT worker_heartbeats_worker_id_check CHECK ((worker_id = 'local-imac'::text))
);


